import {
  COMPANION_STOP_TIMEOUT_MS,
  CONSECUTIVE_FAILURES_BEFORE_RESTART,
  HEALTH_CHECK_INTERVAL_MS,
  HEALTH_CHECK_TIMEOUT_MS,
  RESTART_WINDOW_MS,
  decideCompanionRestart,
} from './companion-restart-policy.ts';
import { getOwnedCompanionActivity } from './companion-activity.ts';
import { resolveTypeScriptEntrypointCommand } from './runtime-command.ts';

function getCompanionBase(): string {
  // Use IPv4 loopback explicitly — `localhost` can resolve to ::1 while the
  // listener may be IPv4-only, causing flaky "connection refused" for Zed Agent.
  return `http://127.0.0.1:${getCompanionPort()}`;
}

// ---------- Companion babysitter ----------

let companionProc: ChildProcess | null = null;
let babysitterTimer: ReturnType<typeof setInterval> | null = null;
let stdioLoggingConfigured = false;
let companionSpawnedAt = 0;
let consecutiveHealthFailures = 0;
let recentRestartTimestamps: number[] = [];
let babysitterCheckInFlight = false;
let restartInFlight: Promise<boolean> | null = null;
let suppressExitRestart = false;
let shuttingDown = false;

function getModuleDirectory(): string {
  return dirname(fileURLToPath(import.meta.url));
}

function getWorkspaceRoot(): string {
  return resolve(
    process.env.AEON_ROOT ?? resolve(getModuleDirectory(), '../../../..')
  );
}

function getCompanionEntry(): string {
  return resolve(
    getWorkspaceRoot(),
    'open-source/zedge/companion/src/index.ts'
  );
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function configureStdioLogging(): void {
  if (stdioLoggingConfigured) {
    return;
  }

  stdioLoggingConfigured = true;
  console.log = (...args: unknown[]) => console.error('[zedge:mcp]', ...args);
  console.warn = (...args: unknown[]) =>
    process.stderr.write(`[zedge:mcp:warn] ${args.join(' ')}\n`);
  console.info = (...args: unknown[]) =>
    process.stderr.write(`[zedge:mcp:info] ${args.join(' ')}\n`);
  console.debug = (...args: unknown[]) =>
    process.stderr.write(`[zedge:mcp:debug] ${args.join(' ')}\n`);
}

/** Check if the current companion process is reachable. */
async function isCompanionAlive(): Promise<boolean> {
  try {
    const resp = await fetch(`${getCompanionBase()}/health`, {
      signal: AbortSignal.timeout(HEALTH_CHECK_TIMEOUT_MS),
    });
    return resp.ok;
  } catch {
    return false;
  }
}

/** Spawn the companion sidecar as a child process via the current runtime */
function spawnCompanion(): void {
  if (
    companionProc &&
    companionProc.exitCode === null &&
    companionProc.signalCode === null
  ) {
    console.warn(
      '[zedge:babysitter] Refusing duplicate companion spawn while owned child is still active'
    );
    return;
  }

  const runtimeCommand = resolveTypeScriptEntrypointCommand(
    getCompanionEntry()
  );
  console.log(
    `[zedge:babysitter] Spawning companion: ${runtimeCommand.display}`
  );
  const child = spawn(runtimeCommand.command, [...runtimeCommand.args], {
    stdio: ['ignore', 'inherit', 'inherit'],
    env: { ...process.env },
  });
  companionProc = child;
  companionSpawnedAt = Date.now();
  consecutiveHealthFailures = 0;

  child.on('error', (error) => {
    console.warn(
      `[zedge:babysitter] Failed to spawn companion: ${error.message}`
    );
    if (companionProc === child) {
      companionProc = null;
    }
  });

  child.on('exit', (code, signal) => {
    console.log(
      `[zedge:babysitter] Companion exited with code ${code} signal ${
        signal ?? 'none'
      }`
    );
    if (companionProc === child) {
      companionProc = null;
    }
    if (!shuttingDown && !suppressExitRestart) {
      void restartCompanion('owned child exited unexpectedly', {
        force: true,
      });
    }
  });
}

async function stopCompanion(): Promise<void> {
  const child = companionProc;
  if (!child) {
    return;
  }

  suppressExitRestart = true;
  const exitPromise = new Promise<void>((resolve) => {
    if (child.exitCode !== null || child.signalCode !== null) {
      resolve();
      return;
    }
    child.once('exit', () => resolve());
  });

  try {
    child.kill('SIGTERM');
  } catch {
    // Best-effort shutdown only.
  }

  const exitedGracefully = await Promise.race([
    exitPromise.then(() => true),
    sleep(COMPANION_STOP_TIMEOUT_MS).then(() => false),
  ]);

  if (
    !exitedGracefully &&
    child.exitCode === null &&
    child.signalCode === null
  ) {
    try {
      child.kill('SIGKILL');
    } catch {
      // Best-effort hard stop only.
    }
    await Promise.race([exitPromise, sleep(1_000)]);
  }

  if (companionProc === child) {
    companionProc = null;
  }
  suppressExitRestart = false;
}

async function restartCompanion(
  reason: string,
  options: { force?: boolean } = {}
): Promise<boolean> {
  if (restartInFlight) {
    return restartInFlight;
  }

  restartInFlight = (async () => {
    const busyActivity = getOwnedCompanionActivity(companionProc?.pid);
    const decision = decideCompanionRestart({
      now: Date.now(),
      activityBusyUntil: busyActivity?.busyUntil ?? null,
      companionSpawnedAt,
      consecutiveFailures: consecutiveHealthFailures,
      restartTimestamps: recentRestartTimestamps,
      force: options.force,
    });
    recentRestartTimestamps = decision.restartTimestamps;

    if (!decision.shouldRestart) {
      if (decision.reason === 'busy' && busyActivity) {
        console.debug(
          `[zedge:babysitter] Companion busy with ${
            busyActivity.kind
          }; skipping restart until ${new Date(
            busyActivity.busyUntil
          ).toISOString()}`
        );
      } else if (decision.reason === 'startup_grace') {
        console.debug(
          '[zedge:babysitter] Skipping restart during companion startup grace window'
        );
      } else if (decision.reason === 'rate_limited') {
        console.warn(
          `[zedge:babysitter] Restart suppressed after ${
            recentRestartTimestamps.length
          } restarts in the last ${Math.round(RESTART_WINDOW_MS / 1000)}s`
        );
      }
      return false;
    }

    console.log(`[zedge:babysitter] Restarting companion: ${reason}`);
    await stopCompanion();
    spawnCompanion();

    const alive = await waitForCompanion();
    if (!alive) {
      console.warn(
        '[zedge:babysitter] Companion did not become healthy after restart'
      );
      return false;
    }

    consecutiveHealthFailures = 0;
    console.log('[zedge:babysitter] Companion healthy after restart');
    return true;
  })().finally(() => {
    restartInFlight = null;
  });

  return restartInFlight;
}

/** Start the babysitter loop: check health, restart if dead */
function startBabysitter(): void {
  if (babysitterTimer) return;

  babysitterTimer = setInterval(async () => {
    if (babysitterCheckInFlight || restartInFlight) {
      return;
    }

    babysitterCheckInFlight = true;
    try {
      const alive = await isCompanionAlive();
      if (alive) {
        consecutiveHealthFailures = 0;
        return;
      }

      consecutiveHealthFailures += 1;

      const busyActivity = getOwnedCompanionActivity(companionProc?.pid);
      if (busyActivity) {
        console.debug(
          `[zedge:babysitter] Health check failed during ${busyActivity.kind} (${consecutiveHealthFailures}/${CONSECUTIVE_FAILURES_BEFORE_RESTART})`
        );
      }

      console.warn(
        `[zedge:babysitter] Companion health check failed (${consecutiveHealthFailures}/${CONSECUTIVE_FAILURES_BEFORE_RESTART})`
      );
      await restartCompanion(
        `health check failed ${consecutiveHealthFailures} consecutive times`
      );
    } finally {
      babysitterCheckInFlight = false;
    }
  }, HEALTH_CHECK_INTERVAL_MS);

  // Clean up on exit
  process.on('exit', () => {
    shuttingDown = true;
    if (babysitterTimer) clearInterval(babysitterTimer);
    if (companionProc && !companionProc.killed) {
      try {
        companionProc.kill('SIGTERM');
      } catch {
        /* Process may already be terminated */
      }
    }
  });
}

// ---------- MCP JSON-RPC types ----------

export interface JsonRpcRequest {
  jsonrpc: '2.0';
  id?: string | number;
  method: string;
  params?: Record<string, unknown>;
}

export interface JsonRpcResponse {
  jsonrpc: '2.0';
  id: string | number | null;
  result?: unknown;
  error?: { code: number; message: string; data?: unknown };
}

interface McpPromptArgument {
  name: string;
  description: string;
  required?: boolean;
}

interface McpPromptDefinition {
  name: string;
  description: string;
  arguments?: McpPromptArgument[];
  instructions: string;
  toolName?: string;
  payload?: (args: string | null) => Record<string, unknown>;
}

// ---------- Companion health check ----------

async function waitForCompanion(maxAttempts = 240): Promise<boolean> {
  for (let i = 0; i < maxAttempts; i++) {
    try {
      const resp = await fetch(`${getCompanionBase()}/probe/ready`, {
        signal: AbortSignal.timeout(HEALTH_CHECK_TIMEOUT_MS),
      });
      if (resp.ok) return true;
    } catch {
      // not ready yet
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  return false;
}

async function recoverCompanionAfterFetchFailure(reason: string): Promise<void> {
  await restartCompanion(reason, { force: true });
  const ok = await waitForCompanion();
  if (!ok) {
    throw new Error(
      `Companion still unreachable at ${getCompanionBase()} after recovery attempt`
    );
  }
}

/**
 * Fetch the companion HTTP API; on connection failure, force-restart the owned
 * sidecar (or spawn it) and retry once. Does not retry on HTTP 4xx/5xx.
 */
async function fetchCompanion(
  path: string,
  init: RequestInit = {},
  timeoutMs = 10_000
): Promise<Response> {
  const url = `${getCompanionBase()}${path}`;
  const doFetch = (): Promise<Response> =>
    fetch(url, {
      ...init,
      signal: init.signal ?? AbortSignal.timeout(timeoutMs),
    });

  try {
    return await doFetch();
  } catch (err) {
    if (err instanceof Error && err.name === 'AbortError') {
      throw err;
    }
    console.warn(
      `[zedge:mcp] Companion fetch failed, attempting recovery: ${
        err instanceof Error ? err.message : String(err)
      }`
    );
    await recoverCompanionAfterFetchFailure('companion unreachable');
    return await doFetch();
  }
}

// ---------- MCP message handlers ----------

const slashArgsPrompt: McpPromptArgument[] = [
  {
    name: 'args',
    description:
      'The raw argument text after the slash command, matching the extension command surface',
  },
];

function parsePromptArgs(args: string | null): string[] {
  return tokenizeArgs(args);
}

function buildSwarmPromptPayload(args: string | null): Record<string, unknown> {
  if (!args) {
    return { action: 'roles' };
  }

  return {
    action: 'start',
    task: args,
  };
}

function normalizeGnotAction(
  value: string | null
): 'files' | 'lint' | 'format' | 'doctor' | 'next' | 'status' {
  switch (value) {
    case 'lint':
    case 'format':
    case 'doctor':
    case 'next':
    case 'status':
      return value;
    case 'next-action':
    case 'next_action':
      return 'next';
    case 'release-status':
    case 'release_status':
      return 'status';
    default:
      return 'files';
  }
}

function buildGnotCommandPayload(
  argsText: string | null,
  overrides: Record<string, unknown> = {}
): Record<string, unknown> {
  const parts = tokenizeArgs(argsText);
  const action = normalizeGnotAction(
    optionalString(overrides.action) ?? optionalString(parts[0])
  );
  const payload: Record<string, unknown> = { action };

  if (action === 'lint' || action === 'format') {
    const filePath =
      optionalString(overrides.filePath) ?? optionalString(parts[1]);
    const sourceText = optionalString(overrides.sourceText);
    const write = overrides.write === true;

    if (filePath) {
      payload.filePath = filePath;
    }
    if (sourceText) {
      payload.sourceText = sourceText;
    }
    if (write) {
      payload.write = true;
    }
    return payload;
  }

  if (action === 'doctor' || action === 'next' || action === 'status') {
    const app = optionalString(overrides.app) ?? optionalString(parts[1]);
    const environment =
      optionalString(overrides.environment) ?? optionalString(parts[2]);
    if (app) {
      payload.app = app;
    }
    if (environment) {
      payload.environment = environment;
    }
    return payload;
  }

  return payload;
}

