export async function handlePromptsList(): Promise<Record<string, unknown>> {
  return {
    prompts: ZEDGE_PROMPTS.map((prompt) => ({
      name: extensionPromptName(prompt.name),
      description: prompt.description,
      arguments: prompt.arguments ?? [],
    })),
  };
}

export async function handlePromptGet(
  params: Record<string, unknown>
): Promise<Record<string, unknown>> {
  const name = optionalString(params.name);
  if (!name) {
    throw new Error('Prompt name is required');
  }

  const prompt = ZEDGE_PROMPTS.find(
    (candidate) => candidate.name === canonicalZedgeCommandName(name)
  );
  if (!prompt) {
    throw new Error(`Unknown prompt: ${name}`);
  }

  const providedArguments = asRecord(params.arguments);
  const argsText = optionalString(providedArguments.args);

  return {
    description: prompt.description,
    messages: [
      {
        role: 'user',
        content: {
          type: 'text',
          text: renderPromptText(prompt, argsText),
        },
      },
    ],
  };
}

export async function handleToolCall(
  params: Record<string, unknown>
): Promise<Record<string, unknown>> {
  const name = String(params.name ?? '');
  const args = asRecord(params.arguments);

  try {
    if (name.startsWith('zedge_babelfish_')) {
      const text = await callBabelfishMcpTool(getCompanionBase(), name, args);
      return {
        content: [{ type: 'text', text }],
      };
    }

    switch (name) {
      case 'zedge_command':
        return executeZedgeCommandTool(args);

      case 'zedge_infer': {
        const messages: Array<{ role: string; content: string }> = [];
        if (args.system) {
          messages.push({ role: 'system', content: String(args.system) });
        }
        messages.push({ role: 'user', content: String(args.prompt ?? '') });

        const resp = await fetchCompanion(
          '/v1/chat/completions',
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              model: args.model ?? 'tinyllama-1.1b',
              messages,
              stream: false,
            }),
          },
          120_000
        );
        const data = (await resp.json()) as {
          choices?: Array<{ message?: { content?: string } }>;
        };
        const content =
          data.choices?.[0]?.message?.content ?? JSON.stringify(data);
        return {
          content: [{ type: 'text', text: content }],
        };
      }

      case 'zedge_models': {
        const resp = await fetchCompanion('/v1/models', {}, 10_000);
        const data = await resp.json();
        return {
          content: [{ type: 'text', text: JSON.stringify(data, null, 2) }],
        };
      }

      case 'zedge_status': {
        const resp = await fetchCompanion('/health', {}, 10_000);
        const data = await resp.json();
        return {
          content: [{ type: 'text', text: JSON.stringify(data, null, 2) }],
        };
      }

      case 'zedge_gnot': {
        const payload = buildGnotCommandPayload(null, args);
        const action = String(payload.action ?? 'files');
        if ((action === 'lint' || action === 'format') && !payload.filePath) {
          return {
            content: [
              {
                type: 'text',
                text: `filePath is required for ${action}`,
              },
            ],
            isError: true,
          };
        }
        if (
          (action === 'doctor' || action === 'next' || action === 'status') &&
          !payload.app
        ) {
          return {
            content: [
              {
                type: 'text',
                text: `app is required for ${action}`,
              },
            ],
            isError: true,
          };
        }
        return createToolResult(await callGnotCommand(payload));
      }

      case 'zedge_apply_code': {
        const filePath =
          optionalString(args.file_path) ?? optionalString(args.filePath);
        const search = optionalString(args.search);
        const replace =
          typeof args.replace === 'string'
            ? args.replace
            : String(args.replace ?? '');
        if (!filePath || !search) {
          return {
            content: [
              { type: 'text', text: 'file_path and search are required' },
            ],
            isError: true,
          };
        }

        return createToolResult(
          await postCompanionJson(
            '/edit/range/preview',
            { file_path: filePath, search, replace },
            10_000
          )
        );
      }

      case 'zedge_preview_range_replace': {
        const filePath =
          optionalString(args.file_path) ?? optionalString(args.filePath);
        const range = args.range;
        const replacementText =
          typeof args.replacement_text === 'string'
            ? args.replacement_text
            : typeof args.replacementText === 'string'
            ? args.replacementText
            : typeof args.replace === 'string'
            ? args.replace
            : '';
        if (!filePath || !range) {
          return {
            content: [
              {
                type: 'text',
                text: 'file_path and range are required',
              },
            ],
            isError: true,
          };
        }

        return createToolResult(
          await postCompanionJson(
            '/edit/range/preview',
            {
              file_path: filePath,
              range,
              replacement_text: replacementText,
            },
            10_000
          )
        );
      }

      case 'zedge_apply_edit_preview': {
        const previewId =
          optionalString(args.preview_id) ?? optionalString(args.previewId);
        if (!previewId) {
          return {
            content: [
              {
                type: 'text',
                text: 'preview_id is required',
              },
            ],
            isError: true,
          };
        }

        return createToolResult(
          await postCompanionJson(
            '/edit/range/apply',
            { previewId },
            10_000
          )
        );
      }

      case 'zedge_tts_speak':
      case 'zedge_tts_preview': {
        const input = optionalString(args.input) ?? optionalString(args.text);
        if (!input) {
          return {
            content: [
              {
                type: 'text',
                text: 'input is required',
              },
            ],
            isError: true,
          };
        }

        const body: Record<string, unknown> = { input };
        const voice = optionalString(args.voice);
        if (voice) body.voice = voice;
        const path = name === 'zedge_tts_speak' ? '/tts/speak' : '/tts/preview';
        return createToolResult(await postCompanionJson(path, body, 120_000));
      }

      case 'zedge_tts_voices':
        return createToolResult(
          await fetchCompanionText('/tts/voices', {}, 10_000)
        );

      case 'zedge_search_codebase': {
        const query = String(args.query ?? '');
        const topK = typeof args.top_k === 'number' ? args.top_k : 5;
        const resp = await fetch(`${getCompanionBase()}/code-index/search`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query, topK }),
          signal: AbortSignal.timeout(30_000),
        });
        const data = await resp.json();
        return {
          content: [{ type: 'text', text: JSON.stringify(data, null, 2) }],
        };
      }

      case 'zedge_related_context': {
        const file = String(args.file_path ?? '');
        const fullFilePath = resolve(getWorkspaceRoot(), file);
        const resp = await fetch(
          `${getCompanionBase()}/code-index/related?file=${encodeURIComponent(
            fullFilePath
          )}`,
          { signal: AbortSignal.timeout(10_000) }
        );
        const data = await resp.json();
        return {
          content: [{ type: 'text', text: JSON.stringify(data, null, 2) }],
        };
      }

      case 'zedge_workspace': {
        const [treeResp, changesResp] = await Promise.all([
          fetch(`${getCompanionBase()}/vfs/tree`, {
            signal: AbortSignal.timeout(10_000),
          }).catch(() => null),
          fetch(`${getCompanionBase()}/vfs/changes`, {
            signal: AbortSignal.timeout(10_000),
          }).catch(() => null),
        ]);
        const tree = treeResp ? await treeResp.text() : '(unavailable)';
        const changes = changesResp
          ? await changesResp.text()
          : '(unavailable)';
        return {
          content: [
            {
              type: 'text',
              text: `## File Tree\n${tree}\n\n## Git Changes\n${changes}`,
            },
          ],
        };
      }

      case 'zedge_void_map': {
        const action = String(args.action ?? 'status');
        const base = getCompanionBase();
        let voidResp: Response;
        switch (action) {
          case 'status':
            voidResp = await fetch(`${base}/void-map/status`, {
              signal: AbortSignal.timeout(10_000),
            });
            break;
          case 'query': {
            const params = new URLSearchParams();
            if (args.file_path) params.set('file', String(args.file_path));
            if (args.category) params.set('category', String(args.category));
            voidResp = await fetch(`${base}/void-map/query?${params}`, {
              signal: AbortSignal.timeout(10_000),
            });
            break;
          }
          case 'steering': {
            const sp = new URLSearchParams();
            if (args.file_path) sp.set('file', String(args.file_path));
            voidResp = await fetch(`${base}/void-map/steering?${sp}`, {
              signal: AbortSignal.timeout(10_000),
            });
            break;
          }
          case 'export': {
            const { exportRecords } = await import('./void-map-export.ts');
            const records = exportRecords({
              filePath: args.file_path ? String(args.file_path) : undefined,
              category: args.category ? String(args.category) : undefined,
            });
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(
                    { records, count: records.length },
                    null,
                    2
                  ),
                },
              ],
            };
          }
          case 'compact':
            voidResp = await fetch(`${base}/void-map/compact`, {
              method: 'POST',
              signal: AbortSignal.timeout(10_000),
            });
            break;
          default:
            return {
              content: [
                { type: 'text', text: `Unknown void map action: ${action}` },
              ],
              isError: true,
            };
        }
        return {
          content: [
            {
              type: 'text',
              text: JSON.stringify(await voidResp.json(), null, 2),
            },
          ],
        };
      }

      case 'zedge_engram': {
        const action = String(args.action ?? 'status');
        const { getEngramStore } = await import('./engram-store.ts');
        const store = getEngramStore();
        switch (action) {
          case 'status':
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(store.getStatus(), null, 2),
                },
              ],
            };
          case 'recall': {
            const query = String(args.query ?? '');
            if (!query)
              return {
                content: [
                  { type: 'text', text: 'query is required for recall' },
                ],
                isError: true,
              };
            const results = await store.recall(query, 5);
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(
                    results.map((r) => ({
                      score: r.score,
                      type: r.engram.type,
                      content: r.engram.content,
                      createdAt: r.engram.createdAt,
                    })),
                    null,
                    2
                  ),
                },
              ],
            };
          }
          case 'remember': {
            const content = String(args.query ?? '');
            const type = String(args.type ?? 'code-pattern') as
              | 'conversation-summary'
              | 'code-pattern'
              | 'user-preference'
              | 'file-relationship';
            if (!content)
              return {
                content: [
                  {
                    type: 'text',
                    text: 'query (content) is required for remember',
                  },
                ],
                isError: true,
              };
            const engram = await store.remember({ type, content });
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(
                    { remembered: true, id: engram.id, type: engram.type },
                    null,
                    2
                  ),
                },
              ],
            };
          }
          case 'forget': {
            const id = String(args.id ?? '');
            if (!id)
              return {
                content: [{ type: 'text', text: 'id is required for forget' }],
                isError: true,
              };
            const removed = store.forget(id);
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify({ forgotten: removed, id }, null, 2),
                },
              ],
            };
          }
          default:
            return {
              content: [
                { type: 'text', text: `Unknown engram action: ${action}` },
              ],
              isError: true,
            };
        }
      }

      case 'zedge_emotion': {
        const filePath = String(args.file_path ?? '');
        if (!filePath)
          return {
            content: [{ type: 'text', text: 'file_path is required' }],
            isError: true,
          };
        const { readFileSync } = await import('fs');
        const { resolve } = await import('path');
        const { analyzeCodeEmotion, routeByEmotion } = await import(
          './emotion-router.ts'
        );
        try {
          const fullPath = resolve(
            process.env.AEON_ROOT || process.cwd(),
            filePath
          );
          const content = readFileSync(fullPath, 'utf-8');
          const profile = analyzeCodeEmotion(content);
          const route = routeByEmotion(profile);
          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify({ profile, route }, null, 2),
              },
            ],
          };
        } catch (err) {
          return {
            content: [
              {
                type: 'text',
                text: `Failed to analyze: ${
                  err instanceof Error ? err.message : String(err)
                }`,
              },
            ],
            isError: true,
          };
        }
      }

      case 'zedge_gg_agent': {
        const action = String(args.action ?? 'list');
        const base = getCompanionBase();
        switch (action) {
          case 'list': {
            const resp = await fetch(`${base}/forge/projects`, {
              signal: AbortSignal.timeout(10_000),
            });
            const data = (await resp.json()) as {
              projects?: Array<{ name: string; kind: string }>;
            };
            const agents = (data.projects ?? []).filter(
              (p: { kind: string }) => p.kind === 'agent'
            );
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(
                    { agents, count: agents.length },
                    null,
                    2
                  ),
                },
              ],
            };
          }
          case 'trigger': {
            const agentName = String(args.agent_name ?? '');
            if (!agentName)
              return {
                content: [{ type: 'text', text: 'agent_name is required' }],
                isError: true,
              };
            const resp = await fetch(`${base}/forge/deploy`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                project: agentName,
                trigger: 'manual',
                payload: args.payload,
              }),
              signal: AbortSignal.timeout(120_000),
            });
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(await resp.json(), null, 2),
                },
              ],
            };
          }
          case 'status': {
            const resp = await fetch(`${base}/forge/status`, {
              signal: AbortSignal.timeout(10_000),
            });
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(await resp.json(), null, 2),
                },
              ],
            };
          }
          case 'health': {
            const agentName = String(args.agent_name ?? '');
            if (!agentName)
              return {
                content: [{ type: 'text', text: 'agent_name is required' }],
                isError: true,
              };
            const resp = await fetch(
              `${base}/forge/status?project=${encodeURIComponent(agentName)}`,
              { signal: AbortSignal.timeout(10_000) }
            );
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(await resp.json(), null, 2),
                },
              ],
            };
          }
          default:
            return {
              content: [
                { type: 'text', text: `Unknown agent action: ${action}` },
              ],
              isError: true,
            };
        }
      }

      case 'zedge_swarm': {
        const action = String(args.action ?? 'roles');
        const base = getCompanionBase();
        if (action === 'start') {
          const task = String(args.task ?? '');
          if (!task) {
            return {
              content: [{ type: 'text', text: 'task is required for start' }],
              isError: true,
            };
          }

          const roles = Array.isArray(args.roles)
            ? args.roles.filter(
                (value): value is string => typeof value === 'string'
              )
            : ['reviewer', 'refactorer', 'tester'];
          const targetFiles = Array.isArray(args.target_files)
            ? args.target_files.filter(
                (value): value is string => typeof value === 'string'
              )
            : undefined;

          const resp = await fetch(`${base}/agent/swarm/start`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              task,
              roles,
              target_files: targetFiles,
            }),
            signal: AbortSignal.timeout(120_000),
          });
          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(await resp.json(), null, 2),
              },
            ],
            isError: !resp.ok,
          };
        }

        const resp = await fetch(`${base}/agent/swarm/roles`, {
          signal: AbortSignal.timeout(10_000),
        });
        return {
          content: [
            { type: 'text', text: JSON.stringify(await resp.json(), null, 2) },
          ],
          isError: !resp.ok,
        };
      }

      case 'zedge_cloud_agent': {
        const action = String(args.action ?? 'sessions');
        const base = getCompanionBase();
        switch (action) {
          case 'start': {
            const agentName = String(args.agent_name ?? '');
            const task = String(args.task ?? '');
            if (!agentName || !task) {
              return {
                content: [
                  {
                    type: 'text',
                    text: 'agent_name and task are required for start',
                  },
                ],
                isError: true,
              };
            }
            const targetFiles = Array.isArray(args.target_files)
              ? args.target_files.filter(
                  (v): v is string => typeof v === 'string'
                )
              : undefined;
            const resp = await fetch(`${base}/cloud-agent/start`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                agent_name: agentName,
                task,
                target_files: targetFiles,
              }),
              signal: AbortSignal.timeout(120_000),
            });
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(await resp.json(), null, 2),
                },
              ],
            };
          }
          case 'sessions': {
            const resp = await fetch(`${base}/cloud-agent/sessions`, {
              signal: AbortSignal.timeout(10_000),
            });
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(await resp.json(), null, 2),
                },
              ],
            };
          }
          case 'status': {
            const sessionId = String(args.session_id ?? '');
            if (!sessionId)
              return {
                content: [{ type: 'text', text: 'session_id required' }],
                isError: true,
              };
            const resp = await fetch(
              `${base}/cloud-agent/session/${sessionId}`,
              { signal: AbortSignal.timeout(10_000) }
            );
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(await resp.json(), null, 2),
                },
              ],
            };
          }
          case 'cancel': {
            const sid = String(args.session_id ?? '');
            if (!sid)
              return {
                content: [{ type: 'text', text: 'session_id required' }],
                isError: true,
              };
            const resp = await fetch(`${base}/cloud-agent/cancel/${sid}`, {
              method: 'POST',
              signal: AbortSignal.timeout(10_000),
            });
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify(await resp.json(), null, 2),
                },
              ],
            };
          }
          default:
            return {
              content: [
                { type: 'text', text: `Unknown cloud agent action: ${action}` },
              ],
              isError: true,
            };
        }
      }

      case 'zedge_topology_run': {
        const filePath = String(args.file_path ?? '');
        if (!filePath)
          return {
            content: [{ type: 'text', text: 'file_path is required' }],
            isError: true,
          };
        const resp = await fetch(`${getCompanionBase()}/gnosis/run`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            file_path: filePath,
            input: args.input,
            strategy: args.strategy,
          }),
          signal: AbortSignal.timeout(60_000),
        });
        const result = (await resp.json()) as Record<string, unknown>;
        const metrics = (result.metrics as Record<string, unknown>) ?? {};
        return {
          content: [
            {
              type: 'text',
              text: `## Topology: ${filePath} [${
                result.success ? 'OK' : 'FAILED'
              }]\n\nbeta1: ${metrics.beta1 ?? '?'} | nodes: ${
                metrics.nodeCount ?? '?'
              } | edges: ${metrics.edgeCount ?? '?'}\n\n${
                result.logs ?? ''
              }\n\n${result.error ? `Error: ${result.error}` : ''}`,
            },
          ],
        };
      }

      case 'zedge_multi_file_edit': {
        const instruction = String(args.instruction ?? '');
        if (!instruction) {
          return {
            content: [{ type: 'text', text: 'instruction is required' }],
            isError: true,
          };
        }
        const resp = await fetch(`${getCompanionBase()}/agent/multi-file`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            instruction,
            target_files: args.target_files,
            model: args.model,
          }),
          signal: AbortSignal.timeout(120_000),
        });
        const data = await resp.json();
        return {
          content: [{ type: 'text', text: JSON.stringify(data, null, 2) }],
        };
      }

      case 'zedge_daydream': {
        const action = String(args.action ?? 'candidates');
        const resp = await (async () => {
          switch (action) {
            case 'status':
              return fetch(`${getCompanionBase()}/cera/daydream/status`, {
                signal: AbortSignal.timeout(10_000),
              });
            case 'candidates':
              return fetch(`${getCompanionBase()}/cera/daydream/candidates`, {
                signal: AbortSignal.timeout(10_000),
              });
            case 'dream':
              return fetch(`${getCompanionBase()}/cera/daydream/dream`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ file_path: args.file_path }),
                signal: AbortSignal.timeout(120_000),
              });
            case 'accept':
              return fetch(`${getCompanionBase()}/cera/daydream/accept`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id: args.id, apply: true }),
                signal: AbortSignal.timeout(120_000),
              });
            case 'reject':
              return fetch(`${getCompanionBase()}/cera/daydream/reject`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id: args.id }),
                signal: AbortSignal.timeout(10_000),
              });
            default:
              return new Response(
                JSON.stringify({ error: `Unknown action: ${action}` }),
                { status: 400 }
              );
          }
        })();
        const data = await resp.json();
        return {
          content: [{ type: 'text', text: JSON.stringify(data, null, 2) }],
        };
      }

      default:
        return {
          content: [{ type: 'text', text: `Unknown tool: ${name}` }],
          isError: true,
        };
    }
  } catch (err) {
    return {
      content: [
        {
          type: 'text',
          text: `Error calling ${name}: ${
            err instanceof Error ? err.message : String(err)
          }`,
        },
      ],
      isError: true,
    };
  }
}

