// ---------- MCP message dispatch ----------

export async function dispatch(
  msg: JsonRpcRequest
): Promise<JsonRpcResponse | null> {
  const { id, method, params } = msg;

  // Notifications (no id) — just acknowledge
  if (id === undefined) {
    // notifications/initialized, etc. — no response needed
    return null;
  }

  try {
    let result: unknown;

    switch (method) {
      case 'initialize':
        result = handleInitialize(params ?? {});
        break;
      case 'tools/list':
        result = await handleToolsList();
        break;
      case 'prompts/list':
        result = await handlePromptsList();
        break;
      case 'prompts/get':
        result = await handlePromptGet(params ?? {});
        break;
      case 'tools/call':
        result = await handleToolCall(params ?? {});
        break;
      case 'resources/list':
        result = await handleResourcesList();
        break;
      case 'resources/read': {
        const uri = (params as Record<string, unknown>)?.uri as string;
        if (uri === 'zedge://observatory') {
          const { getObservatorySnapshot } = await import('./observatory.ts');
          result = {
            contents: [
              {
                uri,
                mimeType: 'application/json',
                text: JSON.stringify(await getObservatorySnapshot(), null, 2),
              },
            ],
          };
        } else if (uri === 'zedge://void-sync') {
          const { federatedVoidSync } = await import(
            './federated-void-sync.ts'
          );
          result = {
            contents: [
              {
                uri,
                mimeType: 'application/json',
                text: JSON.stringify(federatedVoidSync.getStatus(), null, 2),
              },
            ],
          };
        } else if (uri === 'zedge://breeding') {
          const { agentBreeding } = await import('./agent-breeding.ts');
          result = {
            contents: [
              {
                uri,
                mimeType: 'application/json',
                text: JSON.stringify(agentBreeding.getStatus(), null, 2),
              },
            ],
          };
        } else {
          result = { contents: [] };
        }
        break;
      }
      case 'ping':
        result = {};
        break;
      default:
        return {
          jsonrpc: '2.0',
          id,
          error: { code: -32601, message: `Method not found: ${method}` },
        };
    }

    return { jsonrpc: '2.0', id, result };
  } catch (err) {
    return {
      jsonrpc: '2.0',
      id,
      error: {
        code: -32603,
        message: err instanceof Error ? err.message : String(err),
      },
    };
  }
}

// ---------- Stdio transport ----------

function send(response: JsonRpcResponse): void {
  const json = JSON.stringify(response);
  const header = `Content-Length: ${Buffer.byteLength(json)}\r\n\r\n`;
  process.stdout.write(header + json);
}

export async function main(): Promise<void> {
  configureStdioLogging();
  console.log('Starting MCP stdio bridge...');
  await runMcpBridge();
  return;
}

async function runMcpBridge(): Promise<void> {
  const companionStartup = (async () => {
    const alreadyRunning = await isCompanionAlive();
    if (!alreadyRunning) {
      console.log('Companion not running, spawning it...');
      spawnCompanion();
    }

    const alive = await waitForCompanion();
    if (!alive) {
      console.warn(
        'Companion sidecar not reachable at ' +
          getCompanionBase() +
          ' after spawn. Tools will fail until it starts.'
      );
    } else {
      console.log('Companion sidecar is ready');
    }

    startBabysitter();
  })();

  // Read stdin line-by-line (MCP uses Content-Length headers)
  let buffer = '';
  let stdinClosed = false;
  let pendingMessages = 0;

  await new Promise<void>((resolve) => {
    function exitIfIdle(): void {
      if (!stdinClosed || pendingMessages > 0) {
        return;
      }

      if (babysitterTimer) {
        clearInterval(babysitterTimer);
        babysitterTimer = null;
      }
      shuttingDown = true;
      console.log('stdin closed, exiting');
      resolve();
    }

    process.stdin.setEncoding('utf-8');
    // Pipe-backed launches need stdin resumed explicitly or Node can exit before
    // the first MCP request arrives.
    process.stdin.resume();
    process.stdin.on('data', async (chunk: string) => {
      buffer += chunk;

      // Parse Content-Length framed messages
      while (true) {
        const headerEnd = buffer.indexOf('\r\n\r\n');
        if (headerEnd === -1) break;

        const headerBlock = buffer.slice(0, headerEnd);
        const match = headerBlock.match(/Content-Length:\s*(\d+)/i);
        if (!match) {
          // Skip malformed header
          buffer = buffer.slice(headerEnd + 4);
          continue;
        }

        const contentLength = parseInt(match[1], 10);
        const bodyStart = headerEnd + 4;

        if (buffer.length < bodyStart + contentLength) {
          // Incomplete body — wait for more data
          break;
        }

        const body = buffer.slice(bodyStart, bodyStart + contentLength);
        buffer = buffer.slice(bodyStart + contentLength);

        try {
          const msg = JSON.parse(body) as JsonRpcRequest;
          pendingMessages += 1;
          try {
            await companionStartup;
            const response = await dispatch(msg);
            if (response) {
              send(response);
            }
          } finally {
            pendingMessages -= 1;
            exitIfIdle();
          }
        } catch (err) {
          console.warn('Failed to parse MCP message:', err);
          // Send parse error if we had an id somehow
          send({
            jsonrpc: '2.0',
            id: null,
            error: { code: -32700, message: 'Parse error' },
          });
        }
      }
    });

    process.stdin.on('end', () => {
      stdinClosed = true;
      exitIfIdle();
    });
  });
}

function isExecutedDirectly(importMetaUrl: string): boolean {
  if (process.env.GNODE_RUNTIME === '1') {
    return false;
  }

  const entryPath = process.argv[1];
  if (!entryPath) {
    return false;
  }

  return resolve(fileURLToPath(importMetaUrl)) === resolve(entryPath);
}

if (isExecutedDirectly(import.meta.url)) {
  main().catch((err) => {
    console.error('Fatal error:', err);
    process.exit(1);
  });
}
