import {
  existsSync,
  mkdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { homedir } from 'node:os';
import { dirname, resolve } from 'node:path';
import { hostname } from 'node:os';
import { JSONBackingStore, VaultBackingStore } from './platform-proxy.js';

// Dynamic import avoids pulling the `@a0n/bitwise` WASM module into the
// top-level import graph, which breaks `gnode test` resolution of
// `bitwise_bg.wasm` when loaded through the test runtime's synthesized module
// tree. Callers below await `loadBitwise()` at use time.
async function loadBitwise(): Promise<typeof import('@a0n/bitwise')> {
  return import('@a0n/bitwise');
}

