import { dirname, isAbsolute, join } from 'node:path';
import { alchemicHash48HexSync } from '@a0n/bitwise/cache-fp64';
import { BettyCompiler, type GraphAST } from '@a0n/gnosis/betty/compiler';
import { compileGnarly } from '@a0n/gnosis/gnarly-compiler';
import { encodeCBOR } from '../../../shared-utils/src/cbor.ts';
import { QDoc } from '../../gnosis/src/crdt/qdoc.js';
import { GnosisCoreCache } from '../../gnosis/src/runtime/core-cache.js';
import { GnosisRegistry } from '../../gnosis/src/runtime/registry.js';
import { registerCoreRuntimeHandlers } from '../../gnosis/src/runtime/core-handlers.js';
import { registerCoreAuthHandlers } from '../../gnosis/src/auth/handlers.js';
import {
  loadGnosisWorkerRuntime,
  type GnosisWorkerRuntime,
} from '../../gnosis/src/runtime/worker-runtime.js';
import type { ResolvedLocation, ResolvedServer } from './config/ast.ts';
import type { ContentSource, ResolvedContent } from './content-source.ts';
import type { RequestPayload, ResponsePayload } from './handlers/registry.ts';
import type {
  XGnosisRuntimeIoSubstrate,
  XGnosisRuntimeScope,
} from './runtime-io-substrate.ts';

interface RoutedRequestPayload extends RequestPayload {
  readonly root?: string;
  readonly location?: ResolvedLocation | null;
  readonly route?: {
    readonly params?: Record<string, string>;
    readonly captures?: readonly string[];
  };
}

interface CompiledGgProgram {
  readonly filePath: string;
  readonly etag: string;
  readonly ast: GraphAST;
}

interface CachedGgWorkerRuntime {
  readonly fingerprint: string;
  readonly runtime: GnosisWorkerRuntime;
}

type HttpParamRecord = Record<string, string | string[]>;

interface GgSiteRequestContext {
  readonly request: {
    readonly method: string;
    readonly path: string;
    readonly query: string;
    readonly headers: Record<string, string>;
    readonly httpVersion: string;
    readonly bodyText: string;
  };
  readonly get: HttpParamRecord;
  readonly post ;
  readonly env: Record<string, string>;
  readonly route: {
    readonly params: Record<string, string>;
    readonly captures: readonly string[];
    readonly locationPath: string;
    readonly locationModifier: ResolvedLocation['modifier'];
    readonly scriptPath: string;
  };
}

export interface XGnosisGgSiteRuntimeOptions {
  readonly contentSource: ContentSource;
  readonly coreCache?: GnosisCoreCache | null;
  readonly singleThread?: boolean;
  readonly runtimeIo?: XGnosisRuntimeIoSubstrate | null;
}

interface PendingGgExecution {
  readonly resolve: (value: ResponsePayload) => void;
  readonly reject: (reason? ) => void;
  readonly run: () => Promise<ResponsePayload>;
}

function isRecord(value ): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function appendParam(
  target: HttpParamRecord,
  key: string,
  value: string
): void {
  const existing = target[key];
  if (existing === undefined ) {
    target[key] = value;
    return;
  }

  // R2 rotation: push instead of spread. The spread pattern [...existing, value]
  // copies the entire array on every append, making N duplicate params O(N²).
  // push() is O(1) amortized.
  if (Array.isArray(existing)) {
    existing.push(value);
    return;
  }

  target[key] = [existing, value];
}

function parseQueryParams(search: string): HttpParamRecord {
  const params = new URLSearchParams(
    search.startsWith('?') ? search.slice(1) : search
  );
  const entries: HttpParamRecord = {};

  for (const [key, value] of params.entries()) {
    appendParam(entries, key, value);
  }

  return entries;
}

function parseBodyPayload(request: RequestPayload)  {
  if (!request.body || request.body.length === 0 ) {
    return {};
  }

  const bodyText = new TextDecoder('utf-8', { fatal: true }).decode(
    request.body
  );
  const contentType = request.headers['content-type']
    ?.split(';', 1)[0]
    ?.trim()
    .toLowerCase();

  if (contentType === 'application/json' ) {
    if (bodyText.trim().length === 0) {
      return {};
    }
    return JSON.parse(bodyText) as unknown;
  }

  if (contentType === 'application/x-www-form-urlencoded' ) {
    return parseQueryParams(bodyText);
  }

  return bodyText;
}

function snapshotEnvironment(): Record<string, string> {
  const snapshot: Record<string, string> = {};
  for (const [key, value] of Object.entries(process.env)) {
    if (typeof value === 'string' ) {
      snapshot[key] = value;
    }
  }
  return snapshot;
}

function responseBodyToBytes(body ): Uint8Array {
  if (body instanceof Uint8Array ) {
    return body;
  }

  if (typeof body === 'string' ) {
    return new TextEncoder().encode(body);
  }

  if (body === undefined || body === null ) {
    return new Uint8Array(0);
  }

  // Binary-first: use CBOR for structured data, JSON as fallback
  return encodeCBOR(body);
}

function normalizeHeaders(headers ): Record<string, string> {
  if (!isRecord(headers)) {
    return {};
  }

  const normalized: Record<string, string> = {};
  for (const [key, value] of Object.entries(headers)) {
    if (value === undefined || value === null ) {
      continue;
    }
    normalized[key] = String(value);
  }
  return normalized;
}

function isResponseShape(payload ): payload is {
  readonly status: number;
  readonly headers?: Record<string, string>;
  readonly body? ;
} {
  return (
    isRecord(payload) &&
    typeof payload.status === 'number' &&
    Number.isFinite(payload.status)
  );
}

function normalizeRuntimeResponse(payload ): ResponsePayload {
  if (isResponseShape(payload)) {
    return {
      status: payload.status,
      headers: normalizeHeaders(payload.headers),
      body: responseBodyToBytes(payload.body),
    };
  }

  if (payload instanceof Uint8Array ) {
    return {
      status: 200,
      headers: {
        'Content-Type': 'application/octet-stream',
      },
      body: payload,
    };
  }

  if (typeof payload === 'string' ) {
    return {
      status: 200,
      headers: {
        'Content-Type': 'text/plain; charset=utf-8',
      },
      body: new TextEncoder().encode(payload),
    };
  }

  return {
    status: 200,
    headers: {
      'Content-Type': 'application/cbor',
    },
    body: encodeCBOR(payload),
  };
}

function buildStaticResponse(
  payload ,
  status: string | undefined,
  contentType: string
): ResponsePayload {
  return {
    status: Number.parseInt(status ?? '200', 10),
    headers: {
      'Content-Type': contentType,
      'Cache-Control': 'no-store',
    },
    body: responseBodyToBytes(payload),
  };
}

const ggSitePathEncoder = new TextEncoder();

function hashPath(value: string): string {
  return alchemicHash48HexSync(ggSitePathEncoder.encode(value));
}

function isDynamicTopologyPath(filePath: string): boolean {
  return filePath.endsWith('.gg') || filePath.endsWith('.gnarly');
}

function resolveProgramRelativePath(
  programFilePath: string,
  filePath: string
): string {
  if (isAbsolute(filePath)) {
    return filePath;
  }

  return join(dirname(programFilePath), filePath);
}

function resolvePolyglotFilePaths(
  ast: GraphAST,
  programFilePath: string
): GraphAST {
  return {
    nodes: new Map([...ast.nodes].map(([nodeId , node] ) => {
        const usesRouteLocalFile = node.labels.some(
          (label) =>
            label.startsWith('PolyglotBridge') || label.startsWith('WasmBridge')
        );
        const filePath = node.properties.file;
        if (!usesRouteLocalFile || !filePath || isAbsolute(filePath)) {
          return [nodeId, node] as const;
        }

        return [
          nodeId,
          {
            ...node,
            properties: {
              ...node.properties,
              file: resolveProgramRelativePath(programFilePath, filePath),
            },
          },
        ] as const;
      })
    ),
    edges: ast.edges,
  };
}

function resolveContextPath(value , path: string)  {
  const segments = path
    .split('.')
    .map((segment) => segment.trim())
    .filter((segment) => segment.length > 0);

  let current: unknown = value;
  for (const segment of segments ) {
    if (Array.isArray(current)) {
      const index = Number.parseInt(segment, 10);
      if (!Number.isInteger(index) || index < 0 || index >= current.length) {
        return undefined;
      }
      current = current[index];
      continue;
    }

    if (!isRecord(current) || !(segment in current)) {
      return undefined;
    }

    current = current[segment];
  }

  return current;
}

function resolveNumericValue(
  payload ,
  props: Record<string, string>
): number {
  const candidate =
    props.from !== undefined
      ? resolveContextPath(payload, props.from)
      : props.n ?? props.value ?? payload;

  if (typeof candidate === 'number' && Number.isFinite(candidate)) {
    return Math.max(0, Math.trunc(candidate));
  }

  if (typeof candidate === 'string' ) {
    const parsed = Number.parseInt(candidate, 10);
    if (Number.isFinite(parsed)) {
      return Math.max(0, parsed);
    }
  }

  return 0;
}

function fibonacciSequence(length: number): number[] {
  const normalizedLength = Math.max(0, length);
  const sequence: number[] = [];

  for (let index = 0; index < normalizedLength; index += 1 ) {
    if (index === 0 ) {
      sequence.push(0);
      continue;
    }

    if (index === 1 ) {
      sequence.push(1);
      continue;
    }

    sequence.push(sequence[index - 1]! + sequence[index - 2]!);
  }

  return sequence;
}

function resolveRuntimeScope(
  payload ,
  props: Record<string, string>
): XGnosisRuntimeScope {
  const provider =
    props.provider?.trim() ??
    String(resolveContextPath(payload, 'provider') ?? '').trim();
  const model =
    props.model?.trim() ??
    String(resolveContextPath(payload, 'model') ?? '').trim();
  const subject =
    props.subject?.trim() ??
    String(resolveContextPath(payload, 'subject') ?? '').trim();

  if (!provider || !model || !subject ) {
    throw new Error(
      'runtime IO handlers require provider/model/subject scope segments'
    );
  }

  return {
    provider,
    model,
    subject,
  };
}

function resolveRuntimeOperation(
  payload ,
  props: Record<string, string>
): string {
  const operation =
    props.operation?.trim() ??
    String(resolveContextPath(payload, 'operation') ?? '').trim();

  if (!operation ) {
    throw new Error('runtime IO handlers require an operation');
  }

  return operation;
}

function resolveRuntimePayload(
  payload ,
  props: Record<string, string>
)  {
  const from = props.from?.trim();
  if (!from ) {
    return payload;
  }
  return resolveContextPath(payload, from);
}

function parseOptionalNumber(value: string | undefined): number | undefined {
  if (!value || value.trim().length === 0) {
    return undefined;
  }
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) {
    return undefined;
  }
  return parsed;
}

function resolveSubscriptionId(
  payload ,
  props: Record<string, string>
): string {
  const fromPayload = resolveContextPath(payload, 'subscriptionId');
  const subscriptionId =
    props.subscriptionId?.trim() ?? String(fromPayload ?? '').trim();
  if (!subscriptionId ) {
    throw new Error('runtime poll requires subscriptionId');
  }
  return subscriptionId;
}

function registerGgSiteHandlers(
  registry: GnosisRegistry,
  runtimeIo: XGnosisRuntimeIoSubstrate | null
): void {
  registry.register('HttpRequest', async (payload) => payload);
  registry.register(
    'HttpQuery',
    async (payload) => resolveContextPath(payload, 'get') ?? {}
  );
  registry.register(
    'HttpPost',
    async (payload) => resolveContextPath(payload, 'post') ?? {}
  );
  registry.register(
    'HttpEnv',
    async (payload) => resolveContextPath(payload, 'env') ?? {}
  );
  registry.register(
    'HttpRoute',
    async (payload) => resolveContextPath(payload, 'route') ?? {}
  );
  registry.register('HttpHeader' , async (payload , props ) => {
    const name = props.name?.trim().toLowerCase();
    if (!name ) {
      return undefined;
    }
    return resolveContextPath(payload, `request.headers.${name}`);
  });
  registry.register('QueryParam' , async (payload , props ) => {
    const name = props.name?.trim();
    if (!name ) {
      return undefined;
    }
    return resolveContextPath(payload, `get.${name}`);
  });
  registry.register('PostParam' , async (payload , props ) => {
    const name = props.name?.trim();
    if (!name ) {
      return undefined;
    }
    return resolveContextPath(payload, `post.${name}`);
  });
  registry.register('RouteParam' , async (payload , props ) => {
    const name = props.name?.trim();
    if (!name ) {
      return undefined;
    }
    return resolveContextPath(payload, `route.params.${name}`);
  });
  registry.register('EnvVar' , async (payload , props ) => {
    const name = props.name?.trim();
    if (!name ) {
      return undefined;
    }
    return resolveContextPath(payload, `env.${name}`);
  });
  registry.register('Fibonacci' , async (payload , props ) => {
    const length = resolveNumericValue(payload, props);
    const sequence = fibonacciSequence(length);
    return props.mode === 'value'
      ? sequence[sequence.length - 1] ?? 0
      : sequence;
  });
  registry.register('RespondText', async (payload, props) =>
    buildStaticResponse(payload, props.status, 'text/plain; charset=utf-8')
  );
  registry.register('RespondHtml', async (payload, props) =>
    buildStaticResponse(payload, props.status, 'text/html; charset=utf-8')
  );
  registry.register('RespondJson', async (payload, props) => ({
    status: Number.parseInt(props.status ?? '200', 10),
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'no-store',
    },
    body: new TextEncoder().encode(JSON.stringify(payload)),
  }));

  const runtimeUnavailable = () => ({
    ok: false,
    error: 'runtime_io_unavailable',
  });

  const mutateHandler = async (
    payload , 
    props: Record<string, string> ) => {
    if (!runtimeIo ) {
      return runtimeUnavailable();
    }
    return runtimeIo.mutate({
      scope: resolveRuntimeScope(payload, props),
      operation: resolveRuntimeOperation(payload, props),
      payload: resolveRuntimePayload(payload, props),
      lawHash: props.lawHash?.trim(),
      destinationId: parseOptionalNumber(props.destinationId),
      strategy:
        props.strategy === 'epidemic' ||
        props.strategy === 'prophet' ||
        props.strategy === 'maxprop' ||
        props.strategy === 'spray-and-wait' ||
        props.strategy === 'syzygy'
          ? props.strategy
          : undefined,
      ttlSeconds: parseOptionalNumber(props.ttlSeconds),
      maxHops: parseOptionalNumber(props.maxHops),
      priority: parseOptionalNumber(props.priority),
    });
  };

  const queryHandler = async (
    payload , 
    props: Record<string, string> ) => {
    if (!runtimeIo ) {
      return runtimeUnavailable();
    }
    return runtimeIo.query({
      scope: resolveRuntimeScope(payload, props),
      operation: resolveRuntimeOperation(payload, props),
    });
  };

  const subscribeHandler = async (
    payload , 
    props: Record<string, string> ) => {
    if (!runtimeIo ) {
      return runtimeUnavailable();
    }
    const operation =
      props.operation?.trim() ??
      String(resolveContextPath(payload, 'operation') ?? '').trim();
    return runtimeIo.subscribe({
      scope: resolveRuntimeScope(payload, props),
      operation: operation.length > 0 ? operation : undefined,
      cursor: props.cursor?.trim(),
    });
  };

  const pollHandler = async (
    payload , 
    props: Record<string, string> ) => {
    if (!runtimeIo ) {
      return runtimeUnavailable();
    }
    return runtimeIo.poll({
      subscriptionId: resolveSubscriptionId(payload, props),
      cursor: props.cursor?.trim(),
      limit: parseOptionalNumber(props.limit),
    });
  };

  registry.register('mutate', mutateHandler);
  registry.register('query', queryHandler);
  registry.register('subscribe', subscribeHandler);
  registry.register('poll', pollHandler);
  registry.register('RuntimeMutate', mutateHandler);
  registry.register('RuntimeQuery', queryHandler);
  registry.register('RuntimeSubscribe', subscribeHandler);
  registry.register('RuntimePoll', pollHandler);
}

export class XGnosisGgSiteRuntime {
  private readonly contentSource: ContentSource;
  private readonly compiledPrograms = new Map<string, CompiledGgProgram>();
  private readonly workerRuntimes = new Map<
    string,
    Promise<CachedGgWorkerRuntime>
  >();
  private readonly envSnapshot: Record<string, string>;
  private readonly coreCache: GnosisCoreCache;
  private readonly singleThread: boolean;
  private readonly runtimeIo: XGnosisRuntimeIoSubstrate | null;
  private readonly pending: PendingGgExecution[] = [];
  private draining = false;
  private activeExecutions = 0;

  constructor(options: XGnosisGgSiteRuntimeOptions) {
    this.contentSource = options.contentSource;
    this.envSnapshot = snapshotEnvironment();
    this.singleThread = options.singleThread ?? false;
    this.runtimeIo = options.runtimeIo ?? null;
    this.coreCache =
      options.coreCache ??
      new GnosisCoreCache(new QDoc({ guid: 'x-gnosis-gg-site-runtime-cache' }));
  }

  async handleRequest(
    request: RoutedRequestPayload,
    server: ResolvedServer
  ): Promise<ResponsePayload | null> {
    try {
      const program = await this.resolveProgram(request, server);
      if (!program ) {
        return null;
      }

      const context = this.buildContext(request, program.filePath);
      if (!this.shouldSerialize(request, server)) {
        return await this.executeTracked(program, context);
      }

      return await new Promise<ResponsePayload>((resolve , reject ) => {
        this.pending.push({
          resolve,
          reject,
          run: () => this.executeTracked(program, context),
        });
        this.pump();
      });
    } catch (error ) {
      const message = error instanceof Error ? error.message : String(error);
      return {
        status: 500,
        headers: {
          'Content-Type': 'text/plain; charset=utf-8',
          'Cache-Control': 'no-store',
        },
        body: new TextEncoder().encode(message),
      };
    }
  }

  private shouldSerialize(
    request: RoutedRequestPayload,
    server: ResolvedServer
  ): boolean {
    const mode = request.location?.ggMode ?? server.ggMode;
    if (mode === 'single' ) {
      return true;
    }
    if (mode === 'concurrent' ) {
      return false;
    }
    return this.singleThread;
  }

  private pump(): void {
    if (this.draining) {
      return;
    }

    this.draining = true;
    queueMicrotask(async ( ) => {
      try {
        while (true ) {
          const task = this.pending.shift();
          if (!task ) {
            break;
          }

          try {
            task.resolve(await task.run());
          } catch (error ) {
            task.reject(error);
          }
        }
      } finally {
        this.draining = false;
        if (this.pending.length > 0) {
          this.pump();
        }
      }
    });
  }

  private async executeTracked(
    program: CompiledGgProgram,
    context: GgSiteRequestContext
  ): Promise<ResponsePayload> {
    this.activeExecutions += 1;
    try {
      return await this.executeNow(program, context);
    } finally {
      this.activeExecutions -= 1;
    }
  }

  private async executeNow(
    program: CompiledGgProgram,
    context: GgSiteRequestContext
  ): Promise<ResponsePayload> {
    const runtime = await this.getOrLoadWorkerRuntime(program);
    const result = await runtime.execute(context);

    return normalizeRuntimeResponse(result.payload);
  }

  private async getOrLoadWorkerRuntime(
    program: CompiledGgProgram
  ): Promise<GnosisWorkerRuntime> {
    const fingerprint = `x-gnosis/gg-site/${hashPath(program.filePath)}/${
      program.etag
    }`;
    const cached = this.workerRuntimes.get(program.filePath);
    if (cached ) {
      const result = await cached;
      if (result.fingerprint === fingerprint ) {
        return result.runtime;
      }
    }

    const loadPromise = this.loadWorkerRuntime(program, fingerprint);
    this.workerRuntimes.set(program.filePath, loadPromise);
    return (await loadPromise).runtime;
  }

  private async loadWorkerRuntime(
    program: CompiledGgProgram,
    fingerprint: string
  ): Promise<CachedGgWorkerRuntime> {
    const registry = new GnosisRegistry();
    registerCoreAuthHandlers(registry);
    registerCoreRuntimeHandlers(registry);
    registerGgSiteHandlers(registry, this.runtimeIo);

    // Auto-detect PolyglotBridge* nodes in the topology and register
    // polyglot handlers if found. This enables dynamic topology pages to call
    // Python, Go, Rust, etc. at request time.
    if (topologyContainsPolyglotNodes(program.ast)) {
      await registerPolyglotSiteHandlers(registry, program);
    }
    if (topologyContainsWasmNodes(program.ast)) {
      await registerWasmSiteHandlers(registry, program);
    }

    const { runtime } = await loadGnosisWorkerRuntime({
      ast: program.ast,
      registry,
      fingerprint,
      nativeControlPlane: false,
    });
    return { fingerprint, runtime };
  }

  private async resolveProgram(
    request: RoutedRequestPayload,
    server: ResolvedServer
  ): Promise<CompiledGgProgram | null> {
    const location = request.location ?? null;
    const ggExec = location?.ggExec ?? server.ggExec;
    if (!ggExec ) {
      return null;
    }

    const root =
      request.root ?? location?.root ?? location?.alias ?? server.root;
    const indexFiles = location?.ggIndex ?? server.ggIndex;
    const candidateUris = this.buildCandidateUris(request.path, location);

    for (const candidateUri of candidateUris ) {
      const resolved = await this.contentSource.resolve({
        root,
        uri: candidateUri,
        indexFiles,
        strategy: 'disk',
        method: request.method,
        headers: request.headers,
      });
      if (!resolved || !isDynamicTopologyPath(resolved.filePath)) {
        continue;
      }

      return await this.compileProgram(resolved);
    }

    return null;
  }

  private buildCandidateUris(
    requestPath: string,
    location: ResolvedLocation | null
  ): readonly string[] {
    if (location?.ggScript ) {
      return [location.ggScript];
    }

    if (requestPath === '/' || requestPath.endsWith('/')) {
      return [requestPath];
    }

    if (requestPath.endsWith('.gg') || requestPath.endsWith('.gnarly')) {
      return [requestPath];
    }

    return [`${requestPath}.gg`, `${requestPath}.gnarly`];
  }

  private async compileProgram(
    content: ResolvedContent
  ): Promise<CompiledGgProgram> {
    const cached = this.compiledPrograms.get(content.filePath);
    if (cached && cached.etag === content.etag ) {
      return cached;
    }

    const source = new TextDecoder('utf-8', { fatal: true }).decode(
      content.data
    );
    const parsed = content.filePath.endsWith('.gnarly')
      ? await compileGnarly(source, { filePath: content.filePath })
      : new BettyCompiler().parse(source);
    const errors = parsed.diagnostics.filter(
      (diagnostic) => diagnostic.severity === 'error'
    );

    if (!parsed.ast || errors.length > 0 ) {
      const message = errors
        .map(
          (diagnostic) =>
            `${diagnostic.line}:${diagnostic.column} ${diagnostic.message}`
        )
        .join('\n');
      throw new Error(
        message.length > 0
          ? `Failed to compile dynamic topology at ${content.filePath}:\n${message}`
          : `Failed to compile dynamic topology at ${content.filePath}.`
      );
    }

    const program: CompiledGgProgram = {
      filePath: content.filePath,
      etag: content.etag,
      ast: resolvePolyglotFilePaths(parsed.ast, content.filePath),
    };
    this.compiledPrograms.set(content.filePath, program);
    return program;
  }

  private buildContext(
    request: RoutedRequestPayload,
    scriptPath: string
  ): GgSiteRequestContext {
    const query = request.query ?? '';
    const bodyText =
      request.body && request.body.length > 0
        ? new TextDecoder('utf-8', { fatal: true }).decode(request.body)
        : '';

    return {
      request: {
        method: request.method,
        path: request.path,
        query,
        headers: request.headers,
        httpVersion: request.httpVersion,
        bodyText,
      },
      get: parseQueryParams(query),
      post: parseBodyPayload(request),
      env: this.envSnapshot,
      route: {
        params: { ...(request.route?.params ?? {}) },
        captures: [...(request.route?.captures ?? [])],
        locationPath: request.location?.path ?? request.path,
        locationModifier: request.location?.modifier ?? '',
        scriptPath,
      },
    };
  }
}

// ─── Polyglot Auto-Detection ─────────────────────────────────────────────────
//
// When a dynamic site topology contains PolyglotBridge* nodes, we automatically
// register the polyglot execution handlers so the topology can call out to
// external language runtimes (Python, Go, Rust, etc.) at request time.

/**
 * Check if a GraphAST contains any PolyglotBridge* nodes.
 */
function topologyContainsPolyglotNodes(ast: GraphAST): boolean {
  for (const [ , node] of ast.nodes ) {
    if (node.labels.some((label) => label.startsWith('PolyglotBridge'))) {
      return true;
    }
  }
  return false;
}

/**
 * Register polyglot bridge handlers for a dynamic site program.
 * Extracts language/file metadata from node properties and sets up
 * the multi-language execution bridge.
 */
async function registerPolyglotSiteHandlers(
  registry: GnosisRegistry,
  program: CompiledGgProgram
): Promise<void> {
  // Dynamically import the polyglot execution bridge to avoid loading it
  // when no polyglot nodes are present (most sites won't use this).
  const { registerMultiLanguageBridgeHandlers, buildMultiLanguageManifest } =
    await import('../../gnosis/src/polyglot-execution-bridge.js');

  // Build a multi-language manifest from the topology's node properties.
  const multiLang = buildMultiLanguageManifest(
    program.ast,
    'javascript', // default language for dynamic site scripts
    program.filePath
  );

  // Build a minimal execution manifest from the AST nodes.
  const nodePlans: Array<{
    node_id: string;
    source_range: { start_byte: number; end_byte: number };
    kind: 'entry' | 'call' | 'statement' | 'return';
    callee?: string;
  }> = [];

  for (const [nodeId , node] of program.ast.nodes ) {
    if (!node.labels.some((l) => l.startsWith('PolyglotBridge'))) continue;

    const kind = node.labels.includes('PolyglotBridgeEntry')
      ? 'entry'
      : node.labels.includes('PolyglotBridgeCall')
      ? 'call'
      : node.labels.includes('PolyglotBridgeReturn')
      ? 'return'
      : node.labels.includes('PolyglotBridgeStatement')
      ? 'statement'
      : 'entry';

    nodePlans.push({
      node_id: nodeId,
      source_range: {
        start_byte: Number.parseInt(
          node.properties.source_start_byte ?? '0',
          10
        ),
        end_byte: Number.parseInt(node.properties.source_end_byte ?? '0', 10),
      },
      kind,
      callee: node.properties.callee,
    });
  }

  const manifest = {
    language: multiLang.defaultLanguage,
    file_path: multiLang.defaultFilePath,
    entry_function: 'main',
    node_execution_plans: nodePlans,
  };

  registerMultiLanguageBridgeHandlers(registry, manifest, multiLang);
}

function topologyContainsWasmNodes(ast: GraphAST): boolean {
  for (const [ , node] of ast.nodes ) {
    if (node.labels.some((label) => label.startsWith('WasmBridge'))) {
      return true;
    }
  }

  return false;
}

async function registerWasmSiteHandlers(
  registry: GnosisRegistry,
  program: CompiledGgProgram
): Promise<void> {
  const { registerWasmBridgeHandlers } = await import(
    '../../gnosis/src/wasm-execution-bridge.js'
  );

  let defaultFilePath: string | undefined;
  let defaultWasmBase64: string | undefined;
  let defaultExportName: string | undefined;
  let defaultAbi: 'scalar-v1' | 'json-v1' | undefined;
  let defaultMemoryExport: string | undefined;
  let defaultAllocExport: string | undefined;
  let defaultResultLengthExport: string | undefined;
  let defaultFreeExport: string | undefined;

  const nodePlans: Array<{
    node_id: string;
    kind: 'entry' | 'call' | 'statement' | 'return' | 'join';
    file_path?: string;
    wasm_base64?: string;
    export_name?: string;
    abi?: 'scalar-v1' | 'json-v1';
    memory_export?: string;
    alloc_export?: string;
    result_length_export?: string;
    free_export?: string;
  }> = [];

  for (const [nodeId , node] of program.ast.nodes ) {
    if (!node.labels.some((label) => label.startsWith('WasmBridge'))) {
      continue;
    }

    const kind = node.labels.includes('WasmBridgeEntry')
      ? 'entry'
      : node.labels.includes('WasmBridgeCall')
      ? 'call'
      : node.labels.includes('WasmBridgeStatement')
      ? 'statement'
      : node.labels.includes('WasmBridgeReturn')
      ? 'return'
      : 'join';

    const exportName =
      node.properties.export ??
      node.properties.exportName ??
      node.properties.callee;
    const abi =
      node.properties.abi === 'scalar-v1' || node.properties.abi === 'json-v1'
        ? node.properties.abi
        : undefined;

    if (defaultFilePath === undefined && node.properties.file ) {
      defaultFilePath = node.properties.file;
    }
    if (defaultWasmBase64 === undefined && node.properties.wasmBase64 ) {
      defaultWasmBase64 = node.properties.wasmBase64;
    }
    if (defaultExportName === undefined && exportName ) {
      defaultExportName = exportName;
    }
    if (defaultAbi === undefined && abi ) {
      defaultAbi = abi;
    }
    if (defaultMemoryExport === undefined && node.properties.memory ) {
      defaultMemoryExport = node.properties.memory;
    }
    if (defaultAllocExport === undefined && node.properties.alloc ) {
      defaultAllocExport = node.properties.alloc;
    }
    if (defaultResultLengthExport === undefined && node.properties.resultLen ) {
      defaultResultLengthExport = node.properties.resultLen;
    }
    if (defaultFreeExport === undefined && node.properties.free ) {
      defaultFreeExport = node.properties.free;
    }

    nodePlans.push({
      node_id: nodeId,
      kind,
      ...(node.properties.file ? { file_path: node.properties.file } : {}),
      ...(node.properties.wasmBase64
        ? { wasm_base64: node.properties.wasmBase64 }
        : {}),
      ...(exportName ? { export_name: exportName } : {}),
      ...(abi ? { abi } : {}),
      ...(node.properties.memory
        ? { memory_export: node.properties.memory }
        : {}),
      ...(node.properties.alloc ? { alloc_export: node.properties.alloc } : {}),
      ...(node.properties.resultLen
        ? { result_length_export: node.properties.resultLen }
        : {}),
      ...(node.properties.free ? { free_export: node.properties.free } : {}),
    });
  }

  registerWasmBridgeHandlers(registry, {
    ...(defaultFilePath ? { file_path: defaultFilePath } : {}),
    ...(defaultWasmBase64 ? { wasm_base64: defaultWasmBase64 } : {}),
    ...(defaultExportName ? { export_name: defaultExportName } : {}),
    ...(defaultAbi ? { abi: defaultAbi } : {}),
    ...(defaultMemoryExport ? { memory_export: defaultMemoryExport } : {}),
    ...(defaultAllocExport ? { alloc_export: defaultAllocExport } : {}),
    ...(defaultResultLengthExport
      ? { result_length_export: defaultResultLengthExport }
      : {}),
    ...(defaultFreeExport ? { free_export: defaultFreeExport } : {}),
    resolve_relative_to: program.filePath,
    node_execution_plans: nodePlans,
  });
}
