import { existsSync, readFileSync, statSync } from 'node:fs';
import { dirname, extname, resolve } from 'node:path';
import { createHoneyPit } from '@a0n/gnosis/mesh-policy';
import type {
  XRangerBindingRecord,
  XRangerLinkedServiceMesh,
  XRangerMeshHoneyPitConfig,
  XRangerMeshOverlaySpec,
  XRangerMeshPolicyConfig,
  XRangerMeshPortSpec,
  XRangerResolvedConfig,
} from './types.ts';

interface WranglerTomlDocument {
  root: Record<string, unknown>;
  tables: Record<string, Record<string, unknown>>;
  arrayTables: Record<string, Array<Record<string, unknown>>>;
}

export interface XRangerConfigResolveOptions {
  readonly script?: string;
  readonly config?: string;
  readonly env?: string;
  readonly cwd?: string;
}

function stripTomlComment(line: string): string {
  let inSingle = false;
  let inDouble = false;
  for (let index = 0; index < line.length; index += 1) {
    const character = line[index];
    if (character === '\\' && inDouble && index + 1 < line.length) {
      index += 1;
      continue;
    }
    if (character === "'" && !inDouble) {
      inSingle = !inSingle;
      continue;
    }
    if (character === '"' && !inSingle) {
      inDouble = !inDouble;
      continue;
    }
    if (character === '#' && !inSingle && !inDouble) {
      return line.slice(0, index);
    }
  }
  return line;
}

function splitDelimited(raw: string): string[] {
  const values: string[] = [];
  let current = '';
  let inSingle = false;
  let inDouble = false;
  let braceDepth = 0;
  let bracketDepth = 0;

  for (let index = 0; index < raw.length; index += 1) {
    const character = raw[index];
    if (character === '\\' && inDouble && index + 1 < raw.length) {
      current += character + raw[index + 1];
      index += 1;
      continue;
    }
    if (character === "'" && !inDouble) {
      inSingle = !inSingle;
      current += character;
      continue;
    }
    if (character === '"' && !inSingle) {
      inDouble = !inDouble;
      current += character;
      continue;
    }
    if (!inSingle && !inDouble) {
      if (character === '{') braceDepth += 1;
      else if (character === '}') braceDepth -= 1;
      else if (character === '[') bracketDepth += 1;
      else if (character === ']') bracketDepth -= 1;
    }
    if (
      character === ',' &&
      !inSingle &&
      !inDouble &&
      braceDepth === 0 &&
      bracketDepth === 0
    ) {
      values.push(current.trim());
      current = '';
      continue;
    }
    current += character;
  }

  if (current.trim()) {
    values.push(current.trim());
  }
  return values;
}

function unescapeTomlString(value: string): string {
  let result = '';
  for (let index = 0; index < value.length; index += 1) {
    if (value[index] === '\\' && index + 1 < value.length) {
      const next = value[index + 1];
      switch (next) {
        case '"':
          result += '"';
          index += 1;
          break;
        case '\\':
          result += '\\';
          index += 1;
          break;
        case 'n':
          result += '\n';
          index += 1;
          break;
        case 'r':
          result += '\r';
          index += 1;
          break;
        case 't':
          result += '\t';
          index += 1;
          break;
        default:
          result += `\\${next}`;
          index += 1;
          break;
      }
    } else {
      result += value[index];
    }
  }
  return result;
}

function parseTomlScalar(raw: string): unknown {
  const value = raw.trim();
  if (value === '') {
    return '';
  }
  if (value.startsWith('"') && value.endsWith('"')) {
    return unescapeTomlString(value.slice(1, -1));
  }
  if (value.startsWith("'") && value.endsWith("'")) {
    return value.slice(1, -1);
  }
  if (value === 'true' || value === 'false') {
    return value === 'true';
  }
  if (/^-?\d+(\.\d+)?$/.test(value)) {
    return Number(value);
  }
  if (value.startsWith('[') && value.endsWith(']')) {
    const inner = value.slice(1, -1).trim();
    return inner === ''
      ? []
      : splitDelimited(inner).map((entry) => parseTomlScalar(entry));
  }
  if (value.startsWith('{') && value.endsWith('}')) {
    const result: Record<string, unknown> = {};
    for (const pair of splitDelimited(value.slice(1, -1))) {
      const eqIndex = pair.indexOf('=');
      if (eqIndex < 0) {
        continue;
      }
      const key = pair.slice(0, eqIndex).trim();
      result[key] = parseTomlScalar(pair.slice(eqIndex + 1).trim());
    }
    return result;
  }
  return value;
}

function parseWranglerToml(text: string): WranglerTomlDocument {
  const document: WranglerTomlDocument = {
    root: {},
    tables: {},
    arrayTables: {},
  };

  let currentSection: string | null = null;
  let currentArrayEntry: Record<string, unknown> | null = null;
  let arrayMode = false;

  for (const lineRaw of text.split(/\r?\n/)) {
    const line = stripTomlComment(lineRaw).trim();
    if (line === '') {
      continue;
    }

    if (line.startsWith('[[') && line.endsWith(']]')) {
      currentSection = line.slice(2, -2).trim();
      arrayMode = true;
      currentArrayEntry = {};
      if (!document.arrayTables[currentSection]) {
        document.arrayTables[currentSection] = [];
      }
      document.arrayTables[currentSection].push(currentArrayEntry);
      continue;
    }

    if (line.startsWith('[') && line.endsWith(']')) {
      currentSection = line.slice(1, -1).trim();
      arrayMode = false;
      currentArrayEntry = null;
      if (!document.tables[currentSection]) {
        document.tables[currentSection] = {};
      }
      continue;
    }

    const eqIndex = line.indexOf('=');
    if (eqIndex < 0) {
      continue;
    }

    const key = line.slice(0, eqIndex).trim();
    const value = parseTomlScalar(line.slice(eqIndex + 1).trim());
    if (arrayMode && currentArrayEntry) {
      currentArrayEntry[key] = value;
    } else if (currentSection) {
      document.tables[currentSection]![key] = value;
    } else {
      document.root[key] = value;
    }
  }

  return document;
}

function stripJsonComments(text: string): string {
  let result = '';
  let inString = false;
  let stringDelimiter = '"';
  let inLineComment = false;
  let inBlockComment = false;

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    const next = text[index + 1];

    if (inLineComment) {
      if (character === '\n') {
        inLineComment = false;
        result += character;
      }
      continue;
    }

    if (inBlockComment) {
      if (character === '*' && next === '/') {
        inBlockComment = false;
        index += 1;
      }
      continue;
    }

    if (inString) {
      result += character;
      if (character === '\\') {
        result += next ?? '';
        index += 1;
        continue;
      }
      if (character === stringDelimiter) {
        inString = false;
      }
      continue;
    }

    if (character === '"' || character === "'") {
      inString = true;
      stringDelimiter = character;
      result += character;
      continue;
    }

    if (character === '/' && next === '/') {
      inLineComment = true;
      index += 1;
      continue;
    }

    if (character === '/' && next === '*') {
      inBlockComment = true;
      index += 1;
      continue;
    }

    result += character;
  }

  return result;
}

function stripTrailingCommas(text: string): string {
  return text.replace(/,\s*([}\]])/g, '$1');
}

function parseJsonc(text: string): Record<string, unknown> {
  return JSON.parse(stripTrailingCommas(stripJsonComments(text))) as Record<
    string,
    unknown
  >;
}

function findConfigUpwards(cwd: string): string | null {
  let current = resolve(cwd);
  while (true) {
    for (const candidate of [
      'aeon.toml',
      'xranger.toml',
      'wrangler.toml',
      'wrangler.json',
      'wrangler.jsonc',
    ]) {
      const fullPath = resolve(current, candidate);
      if (existsSync(fullPath)) {
        return fullPath;
      }
    }
    const parent = dirname(current);
    if (parent === current) {
      return null;
    }
    current = parent;
  }
}

function ensureObject(value: unknown): Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function stringRecord(value: unknown): Record<string, string> {
  const result: Record<string, string> = {};
  const objectValue = ensureObject(value);
  for (const [key, entry] of Object.entries(objectValue)) {
    if (typeof entry === 'string') {
      result[key] = entry;
    } else if (typeof entry === 'number' || typeof entry === 'boolean') {
      result[key] = String(entry);
    }
  }
  return result;
}

function arrayEntries(value: unknown): Array<Record<string, unknown>> {
  return Array.isArray(value)
    ? value.filter(
        (entry): entry is Record<string, unknown> =>
          typeof entry === 'object' && entry !== null
      )
    : [];
}

/**
 * Parse a `mesh = { ... }` inline table or `[services.NAME.mesh]` nested
 * table from a service binding config into an
 * {@link XRangerLinkedServiceMesh} record.
 *
 * Accepts both TOML snake_case (`source_port_idx`, `dest_port_idx`,
 * `inherit_overlays`) and JSON camelCase (`sourcePortIdx`, `destPortIdx`,
 * `inheritOverlays`) keys. `inheritOverlays` defaults to `true` when
 * absent — the default link honors source overlays per
 * `linkHonorsSourceOverlay`.
 *
 * Throws a descriptive `Error` at config-parse time for:
 *   - non-integer `source_port_idx` / `dest_port_idx`
 *   - negative `source_port_idx` / `dest_port_idx`
 *   - non-boolean `inherit_overlays` when present
 *
 * Callers guard the call with `mesh !== undefined`; this function never
 * returns `undefined` once invoked.
 */
function normalizeLinkedServiceMesh(
  mesh: Record<string, unknown>,
  configPath: string,
  bindingName: string
): XRangerLinkedServiceMesh {
  const readIntegerIndex = (
    ...keys: readonly string[]
  ): { value: number; present: boolean } => {
    for (const key of keys) {
      if (key in mesh) {
        const raw = mesh[key];
        if (typeof raw !== 'number' || !Number.isFinite(raw)) {
          throw new Error(
            `x-ranger service binding mesh error in ${configPath}: services.${bindingName}.mesh.${key} must be a number (got ${JSON.stringify(
              raw
            )}).`
          );
        }
        if (!Number.isInteger(raw)) {
          throw new Error(
            `x-ranger service binding mesh error in ${configPath}: services.${bindingName}.mesh.${key} must be an integer (got ${raw}).`
          );
        }
        if (raw < 0) {
          throw new Error(
            `x-ranger service binding mesh error in ${configPath}: services.${bindingName}.mesh.${key} must be non-negative (got ${raw}).`
          );
        }
        return { value: raw, present: true };
      }
    }
    return { value: 0, present: false };
  };

  const source = readIntegerIndex('source_port_idx', 'sourcePortIdx');
  if (!source.present) {
    throw new Error(
      `x-ranger service binding mesh error in ${configPath}: services.${bindingName}.mesh.source_port_idx is required.`
    );
  }
  const dest = readIntegerIndex('dest_port_idx', 'destPortIdx');
  if (!dest.present) {
    throw new Error(
      `x-ranger service binding mesh error in ${configPath}: services.${bindingName}.mesh.dest_port_idx is required.`
    );
  }

  let inheritOverlays = true;
  for (const key of ['inherit_overlays', 'inheritOverlays']) {
    if (key in mesh) {
      const raw = mesh[key];
      if (typeof raw !== 'boolean') {
        throw new Error(
          `x-ranger service binding mesh error in ${configPath}: services.${bindingName}.mesh.${key} must be a boolean (got ${JSON.stringify(
            raw
          )}).`
        );
      }
      inheritOverlays = raw;
      break;
    }
  }

  return {
    sourcePortIdx: source.value,
    destPortIdx: dest.value,
    inheritOverlays,
  };
}

/**
 * Extract the mesh-metadata record for a single `[[services]]` entry.
 *
 * Two config surfaces are supported:
 *   1. Inline TOML / JSON: `mesh = { source_port_idx = 0, ... }` lives
 *      directly on the service entry and is pre-parsed into a
 *      `Record<string, unknown>` by `parseTomlScalar` or `JSON.parse`.
 *   2. Nested TOML table: `[services.<BINDING>.mesh]` — looked up on the
 *      caller-supplied `nestedMeshLookup` map.
 *
 * Returns `undefined` when no mesh metadata is present. The caller
 * (`normalizeServiceBindings`) decides whether the resulting binding is
 * mesh-aware.
 */
function extractServiceMeshMetadata(
  entry: Record<string, unknown>,
  bindingName: string,
  nestedMeshLookup: ReadonlyMap<string, Record<string, unknown>> | undefined,
  configPath: string
): XRangerLinkedServiceMesh | undefined {
  const inline = entry.mesh;
  if (typeof inline === 'object' && inline !== null && !Array.isArray(inline)) {
    return normalizeLinkedServiceMesh(
      inline as Record<string, unknown>,
      configPath,
      bindingName
    );
  }
  const nested = nestedMeshLookup?.get(bindingName);
  if (nested) {
    return normalizeLinkedServiceMesh(nested, configPath, bindingName);
  }
  return undefined;
}

/**
 * Like {@link normalizeBindings} but specialized for `type: 'service'`
 * entries, with optional linked-mesh metadata discovery.
 *
 * `nestedMeshLookup` maps a binding name (e.g. `'AUTH_SERVICE'`) to the
 * corresponding `[services.<BINDING>.mesh]` TOML sub-table. Pass
 * `undefined` when parsing JSON (where mesh metadata is always inline
 * on the entry).
 *
 * Legacy service bindings (no `mesh` key, no nested table) are emitted
 * unchanged — the `mesh` field is simply omitted.
 */
function normalizeServiceBindings(
  entries: readonly Record<string, unknown>[],
  nestedMeshLookup: ReadonlyMap<string, Record<string, unknown>> | undefined,
  configPath: string
): XRangerBindingRecord[] {
  const normalized: XRangerBindingRecord[] = [];
  for (const entry of entries) {
    const binding = typeof entry.binding === 'string' ? entry.binding : null;
    if (!binding) {
      continue;
    }
    const mesh = extractServiceMeshMetadata(
      entry,
      binding,
      nestedMeshLookup,
      configPath
    );
    normalized.push({
      type: 'service',
      binding,
      service: typeof entry.service === 'string' ? entry.service : undefined,
      entrypoint:
        typeof entry.entrypoint === 'string' ? entry.entrypoint : undefined,
      ...(mesh ? { mesh } : {}),
    });
  }
  return normalized;
}

/**
 * Scan a TOML document's `tables` map for `[services.<NAME>.mesh]`
 * nested tables scoped under the given prefix (`"services"` for the
 * root, `"env.<name>.services"` for env-scoped entries). Returns a
 * binding-name → table map the service normalizer consumes.
 */
function collectServiceMeshTables(
  tables: Record<string, Record<string, unknown>>,
  prefix: string
): ReadonlyMap<string, Record<string, unknown>> {
  const out = new Map<string, Record<string, unknown>>();
  const head = `${prefix}.`;
  const tail = '.mesh';
  for (const key of Object.keys(tables)) {
    if (!key.startsWith(head) || !key.endsWith(tail)) continue;
    const middle = key.slice(head.length, key.length - tail.length);
    // Only accept a single path segment between the prefix and `.mesh`.
    if (middle === '' || middle.includes('.')) continue;
    const record = tables[key];
    if (record !== undefined) {
      out.set(middle, record);
    }
  }
  return out;
}

function normalizeBindings(
  entries: readonly Record<string, unknown>[],
  type: XRangerBindingRecord['type']
): XRangerBindingRecord[] {
  const normalized: XRangerBindingRecord[] = [];

  for (const entry of entries) {
    const binding = typeof entry.binding === 'string' ? entry.binding : null;
    if (!binding) {
      continue;
    }

    if (type === 'service') {
      normalized.push({
        type,
        binding,
        service: typeof entry.service === 'string' ? entry.service : undefined,
        entrypoint:
          typeof entry.entrypoint === 'string' ? entry.entrypoint : undefined,
      });
      continue;
    }

    if (type === 'durable-object') {
      normalized.push({
        type,
        binding,
        className:
          typeof entry.class_name === 'string' ? entry.class_name : undefined,
        scriptName:
          typeof entry.script_name === 'string' ? entry.script_name : undefined,
      });
      continue;
    }

    if (type === 'mtls-certificate') {
      normalized.push({
        type,
        binding,
        certificateId:
          typeof entry.certificate_id === 'string'
            ? entry.certificate_id
            : undefined,
      });
      continue;
    }

    if (type === 'kv') {
      normalized.push({
        type,
        binding,
        id: typeof entry.id === 'string' ? entry.id : undefined,
      });
      continue;
    }

    if (type === 'r2') {
      normalized.push({
        type,
        binding,
        bucketName:
          typeof entry.bucket_name === 'string' ? entry.bucket_name : undefined,
      });
      continue;
    }

    normalized.push({
      type,
      binding,
      id: typeof entry.database_id === 'string' ? entry.database_id : undefined,
      databaseName:
        typeof entry.database_name === 'string'
          ? entry.database_name
          : undefined,
      previewDatabaseId:
        typeof entry.preview_database_id === 'string'
          ? entry.preview_database_id
          : undefined,
      migrationsDir:
        typeof entry.migrations_dir === 'string'
          ? entry.migrations_dir
          : undefined,
      migrationsTable:
        typeof entry.migrations_table === 'string'
          ? entry.migrations_table
          : undefined,
    });
  }

  return normalized;
}

function mergeBindings(
  ...groups: readonly (readonly XRangerBindingRecord[])[]
): XRangerBindingRecord[] {
  const deduped = new Map<string, XRangerBindingRecord>();
  for (const group of groups) {
    for (const entry of group) {
      deduped.set(`${entry.type}:${entry.binding}`, entry);
    }
  }
  return [...deduped.values()];
}

function normalizeMeshPort(
  entry: Record<string, unknown>,
  configPath: string,
  index: number
): XRangerMeshPortSpec {
  const path = entry.path;
  if (typeof path !== 'string' || path === '') {
    throw new Error(
      `x-ranger mesh config error in ${configPath}: mesh.ports[${index}] must have a non-empty string "path".`
    );
  }
  const methodsRaw = entry.methods;
  let methods: readonly string[] | undefined;
  if (Array.isArray(methodsRaw)) {
    const collected: string[] = [];
    for (const method of methodsRaw) {
      if (typeof method === 'string' && method !== '') {
        collected.push(method);
      }
    }
    methods = collected;
  }
  const spec: XRangerMeshPortSpec =
    methods === undefined ? { path } : { path, methods };
  return spec;
}

function normalizeMeshOverlay(
  entry: Record<string, unknown>,
  configPath: string,
  index: number
): XRangerMeshOverlaySpec {
  const pathPrefix = entry.path_prefix ?? entry.pathPrefix;
  if (typeof pathPrefix !== 'string' || pathPrefix === '') {
    throw new Error(
      `x-ranger mesh config error in ${configPath}: mesh.overlays[${index}] must have a non-empty string "path_prefix".`
    );
  }
  const reason = entry.reason;
  // `honeypit: true` on an overlay opts it into the global honey-pit
  // pool routing. Accepts only boolean; non-boolean values are
  // ignored silently for forward-compat with richer future shapes.
  const rawHoneypit = entry.honeypit;
  const honeypit = typeof rawHoneypit === 'boolean' ? rawHoneypit : undefined;
  const base: { pathPrefix: string; reason?: string } =
    typeof reason === 'string' && reason !== ''
      ? { pathPrefix, reason }
      : { pathPrefix };
  const spec: XRangerMeshOverlaySpec =
    honeypit === true ? { ...base, honeypit: true } : base;
  return spec;
}

/**
 * Parse a `[mesh.honeypit]` TOML table (or `mesh.honeypit` JSON object)
 * into a validated {@link XRangerMeshHoneyPitConfig}.
 *
 * Accepted keys:
 *   - `capacity` (number) — max trapped inhabitants. Must be a positive
 *     integer.
 *   - `drain_slots` (TOML) / `drainSlots` (JSON) — server drain worker
 *     count. Must be a positive integer. `drain_slots` is also
 *     accepted in JSON as a dual-convention fallback.
 *
 * Delegates validation to `createHoneyPit` from the gnosis SSOT and
 * rethrows its `RangeError` with a config-context message so operators
 * see the offending file path.
 */
function normalizeMeshHoneyPit(
  entry: Record<string, unknown>,
  configPath: string
): XRangerMeshHoneyPitConfig {
  const capacityRaw = entry.capacity;
  if (typeof capacityRaw !== 'number' || !Number.isFinite(capacityRaw)) {
    throw new Error(
      `x-ranger mesh config error in ${configPath}: mesh.honeypit.capacity must be a number (got ${JSON.stringify(
        capacityRaw
      )}).`
    );
  }
  const drainSlotsRaw =
    entry.drain_slots !== undefined ? entry.drain_slots : entry.drainSlots;
  if (typeof drainSlotsRaw !== 'number' || !Number.isFinite(drainSlotsRaw)) {
    throw new Error(
      `x-ranger mesh config error in ${configPath}: mesh.honeypit.drain_slots must be a number (got ${JSON.stringify(
        drainSlotsRaw
      )}).`
    );
  }
  // Storage discriminator: accepts 'memory' (default) or 'do'. Absent
  // means memory for backward compatibility.
  const storageRaw = entry.storage;
  let storage: 'memory' | 'do' | undefined;
  if (storageRaw !== undefined) {
    if (storageRaw !== 'memory' && storageRaw !== 'do') {
      throw new Error(
        `x-ranger mesh config error in ${configPath}: mesh.honeypit.storage must be "memory" or "do" (got ${JSON.stringify(
          storageRaw
        )}).`
      );
    }
    storage = storageRaw;
  }
  // DO binding name: accepts TOML snake_case and JSON camelCase.
  const doBindingNameRaw =
    entry.do_binding_name !== undefined
      ? entry.do_binding_name
      : entry.doBindingName;
  let doBindingName: string | undefined;
  if (doBindingNameRaw !== undefined) {
    if (typeof doBindingNameRaw !== 'string' || doBindingNameRaw === '') {
      throw new Error(
        `x-ranger mesh config error in ${configPath}: mesh.honeypit.do_binding_name must be a non-empty string (got ${JSON.stringify(
          doBindingNameRaw
        )}).`
      );
    }
    doBindingName = doBindingNameRaw;
  }
  // Storage/binding invariant: `storage="do"` requires `doBindingName`.
  // Resolve-time rejection surfaces the error with the exact config
  // path; the mesh wrapper's constructor also throws as a defense in
  // depth.
  if (storage === 'do' && doBindingName === undefined) {
    throw new Error(
      `x-ranger mesh config error in ${configPath}: mesh.honeypit.storage="do" requires mesh.honeypit.do_binding_name.`
    );
  }
  try {
    const pit = createHoneyPit(capacityRaw, drainSlotsRaw, 0);
    return {
      capacity: pit.capacity,
      drainSlots: pit.drainSlots,
      ...(storage !== undefined ? { storage } : {}),
      ...(doBindingName !== undefined ? { doBindingName } : {}),
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(
      `x-ranger mesh config error in ${configPath}: invalid [mesh.honeypit]: ${message}`
    );
  }
}

/**
 * Extract a `mesh.honeypit` sub-table from a mesh slice's inputs.
 *
 * For TOML, the config parser already lifted `[mesh.honeypit]` into
 * `document.tables['mesh.honeypit']`, so callers pass that directly
 * (or the env-scoped `env.<name>.mesh.honeypit`). For JSON, the
 * `mesh.honeypit` nested object is pulled out of the mesh table first.
 */
function readMeshHoneyPit(
  table: Record<string, unknown> | undefined,
  configPath: string
): XRangerMeshHoneyPitConfig | undefined {
  if (table === undefined) return undefined;
  return normalizeMeshHoneyPit(table, configPath);
}

/**
 * Extract a boolean scalar, accepting both TOML snake_case and JSON
 * camelCase keys. Returns undefined when neither key is present or the
 * value is not a boolean.
 */
function readBooleanFlag(
  table: Record<string, unknown>,
  ...keys: readonly string[]
): boolean | undefined {
  for (const key of keys) {
    const raw = table[key];
    if (typeof raw === 'boolean') {
      return raw;
    }
  }
  return undefined;
}

/**
 * Build a mesh-policy slice from a single mesh table + port array + overlay
 * array. Used for both the root and the env-scoped slice before merging.
 * Returns `undefined` when every source is absent (no mesh slice at all).
 */
interface MeshPolicySlice {
  readonly present: boolean;
  readonly hasPortsSection: boolean;
  readonly hasOverlaysSection: boolean;
  readonly meshTable: Record<string, unknown>;
  readonly ports: readonly XRangerMeshPortSpec[];
  readonly overlays: readonly XRangerMeshOverlaySpec[] | undefined;
  readonly requireAuth: boolean | undefined;
  readonly requireAuthHeaderPresent: boolean | undefined;
  readonly version: number | undefined;
  readonly mode: 'audit' | 'enforce' | 'shadow' | undefined;
  /** Parsed global `[mesh.honeypit]` config, if present. */
  readonly honeypit: XRangerMeshHoneyPitConfig | undefined;
}

/**
 * Per-invocation warning tracker for cross-convention key usage. One
 * `DeprecationWarner` is instantiated per mesh-policy parse (per config
 * load), so each load emits at most one warning per convention category
 * instead of spamming one per offending key.
 */
interface DeprecationWarner {
  readonly noteTomlCamelCase: () => void;
  readonly noteJsonSnakeCase: () => void;
}

function createDeprecationWarner(configPath: string): DeprecationWarner {
  let warnedTomlCamel = false;
  let warnedJsonSnake = false;
  return {
    noteTomlCamelCase: () => {
      if (warnedTomlCamel) return;
      warnedTomlCamel = true;
      console.warn(
        `[x-ranger] WARNING: camelCase keys detected in TOML mesh policy section. TOML convention is snake_case (path_prefix, require_auth). Silent accept for backward compatibility; future versions will reject this. Config: ${configPath}`
      );
    },
    noteJsonSnakeCase: () => {
      if (warnedJsonSnake) return;
      warnedJsonSnake = true;
      console.warn(
        `[x-ranger] WARNING: snake_case keys detected in JSON mesh policy section. JSON convention is camelCase (pathPrefix, requireAuth). Silent accept for backward compatibility; future versions will reject this. Config: ${configPath}`
      );
    },
  };
}

const SUPPORTED_MESH_POLICY_VERSION = 1;
const VALID_MESH_MODES: readonly ('audit' | 'enforce' | 'shadow')[] = [
  'audit',
  'enforce',
  'shadow',
];

function parseMeshVersion(
  table: Record<string, unknown>,
  configPath: string
): number | undefined {
  const raw = table.version;
  if (raw === undefined) {
    return undefined;
  }
  if (typeof raw !== 'number' || !Number.isFinite(raw)) {
    throw new Error(
      `x-ranger mesh config error in ${configPath}: mesh.version must be a number.`
    );
  }
  if (raw !== SUPPORTED_MESH_POLICY_VERSION) {
    throw new Error(
      `Mesh policy version ${raw} is not supported (expected ${SUPPORTED_MESH_POLICY_VERSION}). Config: ${configPath}. Upgrade x-ranger or downgrade the config.`
    );
  }
  return raw;
}

function parseMeshMode(
  table: Record<string, unknown>,
  configPath: string
): 'audit' | 'enforce' | 'shadow' | undefined {
  const raw = table.mode;
  if (raw === undefined) {
    return undefined;
  }
  if (
    typeof raw !== 'string' ||
    !VALID_MESH_MODES.includes(raw as 'audit' | 'enforce' | 'shadow')
  ) {
    throw new Error(
      `x-ranger mesh config error in ${configPath}: mesh.mode must be one of 'audit', 'enforce', 'shadow' (got ${JSON.stringify(
        raw
      )}).`
    );
  }
  return raw as 'audit' | 'enforce' | 'shadow';
}

function buildMeshSlice(
  meshTable: Record<string, unknown> | undefined,
  portsTable: Array<Record<string, unknown>> | undefined,
  overlaysTable: Array<Record<string, unknown>> | undefined,
  configPath: string,
  warner?: DeprecationWarner,
  honeyPitTable?: Record<string, unknown> | undefined
): MeshPolicySlice {
  const hasPortsSection = portsTable !== undefined;
  const hasOverlaysSection = overlaysTable !== undefined;
  const hasMeshTable = meshTable !== undefined;
  const hasHoneyPitTable = honeyPitTable !== undefined;

  const table = meshTable ?? {};
  const portEntries = portsTable ?? [];
  const overlayEntries = overlaysTable ?? [];

  // TOML convention is snake_case. Flag camelCase appearances so
  // operators know they're relying on dual-accept.
  if (warner) {
    if (
      'requireAuth' in table ||
      'requireAuthHeaderPresent' in table ||
      'requireAuthHeaderPresence' in table
    ) {
      warner.noteTomlCamelCase();
    }
    for (const entry of portEntries) {
      if ('pathPrefix' in entry) {
        warner.noteTomlCamelCase();
        break;
      }
    }
    for (const entry of overlayEntries) {
      if ('pathPrefix' in entry) {
        warner.noteTomlCamelCase();
        break;
      }
    }
  }

  const ports = portEntries.map((entry, index) =>
    normalizeMeshPort(entry, configPath, index)
  );

  const overlays =
    overlayEntries.length > 0
      ? overlayEntries.map((entry, index) =>
          normalizeMeshOverlay(entry, configPath, index)
        )
      : undefined;

  const requireAuth = readBooleanFlag(table, 'require_auth', 'requireAuth');
  const requireAuthHeaderPresent = readBooleanFlag(
    table,
    'require_auth_header_presence',
    'require_auth_header_present',
    'requireAuthHeaderPresent',
    'requireAuthHeaderPresence'
  );

  const version = parseMeshVersion(table, configPath);
  const mode = parseMeshMode(table, configPath);
  const honeypit = readMeshHoneyPit(honeyPitTable, configPath);

  return {
    present:
      hasMeshTable || hasPortsSection || hasOverlaysSection || hasHoneyPitTable,
    hasPortsSection,
    hasOverlaysSection,
    meshTable: table,
    ports,
    overlays,
    requireAuth,
    requireAuthHeaderPresent,
    version,
    mode,
    honeypit,
  };
}

/**
 * Merge a root mesh slice with an (optional) env-scoped mesh slice.
 *
 * Merge semantics (field-by-field inheritance, not root-wipe):
 *
 *   - If the env slice is absent or has no mesh-shaped content, return the
 *     root slice verbatim.
 *   - Otherwise, start with root values and overlay env values per field:
 *     - `ports` is replaced iff the env declares a `[[env.<name>.mesh.ports]]`
 *       array (even when empty); otherwise it inherits root's ports.
 *     - `overlays` is replaced iff the env declares a
 *       `[[env.<name>.mesh.overlays]]` array; otherwise inherits root's.
 *     - `requireAuth` and `requireAuthHeaderPresent` inherit when the env's
 *       `[env.<name>.mesh]` table does not define them.
 *
 * Opt-in full-replace escape hatch: if the env's `[env.<name>.mesh]` table
 * sets `override = true`, the env slice is used as-is and root is ignored
 * entirely (including empty arrays when the env declared them). This
 * preserves the pre-fix root-wipe behavior for users who actually want it.
 *
 * Prior to this fix, any env-scoped mesh section silently discarded the
 * entire root policy — adding `[env.prod.mesh] require_auth = true` wiped
 * staging's port list, turning the worker into a 404-every-path black hole.
 * That was the CSO P0. The new default is field-by-field merge; the old
 * behavior is opt-in via `override = true`.
 */
function mergeMeshSlices(
  root: MeshPolicySlice | undefined,
  env: MeshPolicySlice | undefined
): XRangerMeshPolicyConfig | undefined {
  const rootPresent = root !== undefined && root.present;
  const envPresent = env !== undefined && env.present;

  if (!rootPresent && !envPresent) {
    return undefined;
  }

  // Opt-in full-replace: env wins entirely, root is ignored.
  if (envPresent && env !== undefined) {
    const overrideFlag = readBooleanFlag(env.meshTable, 'override');
    if (overrideFlag === true) {
      return materializeMeshPolicy(env);
    }
  }

  // No env slice: root verbatim.
  if (!envPresent) {
    return materializeMeshPolicy(root as MeshPolicySlice);
  }

  // No root slice: env verbatim (nothing to merge into).
  if (!rootPresent) {
    return materializeMeshPolicy(env as MeshPolicySlice);
  }

  const rootSlice = root as MeshPolicySlice;
  const envSlice = env as MeshPolicySlice;

  // Ports: replace iff env declared the array section; else inherit.
  const mergedPorts = envSlice.hasPortsSection
    ? envSlice.ports
    : rootSlice.ports;

  // Overlays: replace iff env declared the array section; else inherit.
  // An env that declares an empty overlays array (no [[...]] entries is
  // equivalent to "not declared" in TOML) inherits root's overlays.
  const mergedOverlays = envSlice.hasOverlaysSection
    ? envSlice.overlays
    : rootSlice.overlays;

  // Boolean flags: env wins when defined, else inherit root.
  const mergedRequireAuth =
    envSlice.requireAuth !== undefined
      ? envSlice.requireAuth
      : rootSlice.requireAuth;
  const mergedRequireAuthHeaderPresent =
    envSlice.requireAuthHeaderPresent !== undefined
      ? envSlice.requireAuthHeaderPresent
      : rootSlice.requireAuthHeaderPresent;

  // Version & mode: env wins when defined, else inherit root.
  const mergedVersion =
    envSlice.version !== undefined ? envSlice.version : rootSlice.version;
  const mergedMode =
    envSlice.mode !== undefined ? envSlice.mode : rootSlice.mode;

  // Honey-pit: env wins when defined, else inherit root. Env can
  // redeclare a narrower or wider pool; root's pool is the default.
  const mergedHoneyPit =
    envSlice.honeypit !== undefined ? envSlice.honeypit : rootSlice.honeypit;

  return assembleMeshPolicy(
    mergedPorts,
    mergedOverlays,
    mergedRequireAuth,
    mergedRequireAuthHeaderPresent,
    mergedVersion,
    mergedMode,
    mergedHoneyPit
  );
}

function materializeMeshPolicy(
  slice: MeshPolicySlice
): XRangerMeshPolicyConfig {
  return assembleMeshPolicy(
    slice.ports,
    slice.overlays,
    slice.requireAuth,
    slice.requireAuthHeaderPresent,
    slice.version,
    slice.mode,
    slice.honeypit
  );
}

function assembleMeshPolicy(
  ports: readonly XRangerMeshPortSpec[],
  overlays: readonly XRangerMeshOverlaySpec[] | undefined,
  requireAuth: boolean | undefined,
  requireAuthHeaderPresent: boolean | undefined,
  version: number | undefined,
  mode: 'audit' | 'enforce' | 'shadow' | undefined,
  honeypit?: XRangerMeshHoneyPitConfig | undefined
): XRangerMeshPolicyConfig {
  // Write the canonical field whenever either TOML/JSON key was set,
  // and also write the compat `requireAuth` field so legacy readers keep
  // working. The runtime wrapper reads `requireAuthHeaderPresent ?? requireAuth`.
  const canonical =
    requireAuthHeaderPresent !== undefined
      ? requireAuthHeaderPresent
      : requireAuth;
  const compat =
    requireAuth !== undefined ? requireAuth : requireAuthHeaderPresent;

  // Version normalizes to 1 when absent. parseMeshVersion already rejects
  // any value other than 1, so the normalized output is always 1.
  const resolvedVersion = version ?? SUPPORTED_MESH_POLICY_VERSION;

  // Mode normalizes to 'enforce' when absent.
  const resolvedMode: 'audit' | 'enforce' | 'shadow' = mode ?? 'enforce';

  return {
    version: resolvedVersion,
    ports,
    ...(compat !== undefined ? { requireAuth: compat } : {}),
    ...(canonical !== undefined ? { requireAuthHeaderPresent: canonical } : {}),
    ...(overlays !== undefined ? { overlays } : {}),
    ...(honeypit !== undefined ? { honeypit } : {}),
    mode: resolvedMode,
  };
}

function buildMeshPolicyFromToml(
  document: WranglerTomlDocument,
  environment: string | undefined,
  configPath: string
): XRangerMeshPolicyConfig | undefined {
  const warner = createDeprecationWarner(configPath);

  const rootSlice = buildMeshSlice(
    document.tables.mesh,
    document.arrayTables['mesh.ports'],
    document.arrayTables['mesh.overlays'],
    configPath,
    warner,
    document.tables['mesh.honeypit']
  );

  const envPrefix = environment ? `env.${environment}` : null;
  const envSlice = envPrefix
    ? buildMeshSlice(
        document.tables[`${envPrefix}.mesh`],
        document.arrayTables[`${envPrefix}.mesh.ports`],
        document.arrayTables[`${envPrefix}.mesh.overlays`],
        configPath,
        warner,
        document.tables[`${envPrefix}.mesh.honeypit`]
      )
    : undefined;

  return mergeMeshSlices(
    rootSlice.present ? rootSlice : undefined,
    envSlice && envSlice.present ? envSlice : undefined
  );
}

function meshObjectOrUndefined(
  raw: unknown
): Record<string, unknown> | undefined {
  return typeof raw === 'object' && raw !== null && !Array.isArray(raw)
    ? (raw as Record<string, unknown>)
    : undefined;
}

function buildJsonMeshSlice(
  mesh: Record<string, unknown> | undefined,
  configPath: string,
  warner?: DeprecationWarner
): MeshPolicySlice | undefined {
  if (mesh === undefined) {
    return undefined;
  }
  const portEntries = arrayEntries(mesh.ports);
  const overlayEntries = arrayEntries(mesh.overlays);
  const hasPortsSection = Array.isArray(mesh.ports);
  const hasOverlaysSection = Array.isArray(mesh.overlays);

  // JSON convention is camelCase. Flag snake_case appearances so
  // operators know they're relying on dual-accept.
  if (warner) {
    if (
      'require_auth' in mesh ||
      'require_auth_header_presence' in mesh ||
      'require_auth_header_present' in mesh
    ) {
      warner.noteJsonSnakeCase();
    }
    for (const entry of portEntries) {
      if ('path_prefix' in entry) {
        warner.noteJsonSnakeCase();
        break;
      }
    }
    for (const entry of overlayEntries) {
      if ('path_prefix' in entry) {
        warner.noteJsonSnakeCase();
        break;
      }
    }
  }

  const ports = portEntries.map((entry, index) =>
    normalizeMeshPort(entry, configPath, index)
  );
  const overlays =
    overlayEntries.length > 0
      ? overlayEntries.map((entry, index) =>
          normalizeMeshOverlay(entry, configPath, index)
        )
      : undefined;

  const requireAuth = readBooleanFlag(mesh, 'require_auth', 'requireAuth');
  const requireAuthHeaderPresent = readBooleanFlag(
    mesh,
    'require_auth_header_presence',
    'require_auth_header_present',
    'requireAuthHeaderPresent',
    'requireAuthHeaderPresence'
  );

  const version = parseMeshVersion(mesh, configPath);
  const mode = parseMeshMode(mesh, configPath);

  const honeyPitTable = meshObjectOrUndefined(mesh.honeypit);
  const honeypit = readMeshHoneyPit(honeyPitTable, configPath);

  return {
    present: true,
    hasPortsSection,
    hasOverlaysSection,
    meshTable: mesh,
    ports,
    overlays,
    requireAuth,
    requireAuthHeaderPresent,
    version,
    mode,
    honeypit,
  };
}

function buildMeshPolicyFromJson(
  document: Record<string, unknown>,
  envSection: Record<string, unknown>,
  configPath: string
): XRangerMeshPolicyConfig | undefined {
  const warner = createDeprecationWarner(configPath);
  const rootMesh = meshObjectOrUndefined(document.mesh);
  const envMesh = meshObjectOrUndefined(envSection.mesh);

  const rootSlice = buildJsonMeshSlice(rootMesh, configPath, warner);
  const envSlice = buildJsonMeshSlice(envMesh, configPath, warner);

  return mergeMeshSlices(rootSlice, envSlice);
}

function parseTomlConfig(
  configPath: string,
  environment: string | undefined
): XRangerResolvedConfig {
  const raw = readFileSync(configPath, 'utf8');
  const document = parseWranglerToml(raw);
  const envPrefix = environment ? `env.${environment}` : null;
  const root = document.root;
  const vars = {
    ...stringRecord(document.tables.vars),
    ...(envPrefix ? stringRecord(document.tables[`${envPrefix}.vars`]) : {}),
  };

  const bindings = mergeBindings(
    normalizeBindings(document.arrayTables.kv_namespaces ?? [], 'kv'),
    envPrefix
      ? normalizeBindings(
          document.arrayTables[`${envPrefix}.kv_namespaces`] ?? [],
          'kv'
        )
      : [],
    normalizeBindings(document.arrayTables.r2_buckets ?? [], 'r2'),
    envPrefix
      ? normalizeBindings(
          document.arrayTables[`${envPrefix}.r2_buckets`] ?? [],
          'r2'
        )
      : [],
    normalizeBindings(document.arrayTables.d1_databases ?? [], 'd1'),
    envPrefix
      ? normalizeBindings(
          document.arrayTables[`${envPrefix}.d1_databases`] ?? [],
          'd1'
        )
      : [],
    normalizeBindings(
      document.arrayTables.mtls_certificates ?? [],
      'mtls-certificate'
    ),
    envPrefix
      ? normalizeBindings(
          document.arrayTables[`${envPrefix}.mtls_certificates`] ?? [],
          'mtls-certificate'
        )
      : [],
    normalizeServiceBindings(
      document.arrayTables.services ?? [],
      collectServiceMeshTables(document.tables, 'services'),
      resolve(configPath)
    ),
    envPrefix
      ? normalizeServiceBindings(
          document.arrayTables[`${envPrefix}.services`] ?? [],
          collectServiceMeshTables(document.tables, `${envPrefix}.services`),
          resolve(configPath)
        )
      : [],
    normalizeBindings(
      document.arrayTables['durable_objects.bindings'] ?? [],
      'durable-object'
    ),
    envPrefix
      ? normalizeBindings(
          document.arrayTables[`${envPrefix}.durable_objects.bindings`] ?? [],
          'durable-object'
        )
      : []
  );

  const main =
    typeof root.main === 'string'
      ? root.main
      : typeof root.script === 'string'
      ? root.script
      : 'src/index.ts';

  const meshPolicy = buildMeshPolicyFromToml(
    document,
    environment,
    resolve(configPath)
  );

  return {
    configPath: resolve(configPath),
    projectRoot: dirname(resolve(configPath)),
    name:
      typeof root.name === 'string'
        ? root.name
        : environment
        ? `x-ranger-${environment}`
        : 'x-ranger-worker',
    main,
    compatibilityDate:
      typeof root.compatibility_date === 'string'
        ? root.compatibility_date
        : undefined,
    vars,
    bindings,
    ...(meshPolicy ? { meshPolicy } : {}),
  };
}

function parseJsonConfig(
  configPath: string,
  environment: string | undefined
): XRangerResolvedConfig {
  const raw = readFileSync(configPath, 'utf8');
  const document = parseJsonc(raw);
  const envSection = ensureObject(
    environment ? ensureObject(document.env)[environment] : undefined
  );

  const bindings = mergeBindings(
    normalizeBindings(arrayEntries(document.kv_namespaces), 'kv'),
    normalizeBindings(arrayEntries(envSection.kv_namespaces), 'kv'),
    normalizeBindings(arrayEntries(document.r2_buckets), 'r2'),
    normalizeBindings(arrayEntries(envSection.r2_buckets), 'r2'),
    normalizeBindings(arrayEntries(document.d1_databases), 'd1'),
    normalizeBindings(arrayEntries(envSection.d1_databases), 'd1'),
    normalizeBindings(
      arrayEntries(document.mtls_certificates),
      'mtls-certificate'
    ),
    normalizeBindings(
      arrayEntries(envSection.mtls_certificates),
      'mtls-certificate'
    ),
    normalizeServiceBindings(
      arrayEntries(document.services),
      undefined,
      resolve(configPath)
    ),
    normalizeServiceBindings(
      arrayEntries(envSection.services),
      undefined,
      resolve(configPath)
    ),
    normalizeBindings(
      arrayEntries(ensureObject(document.durable_objects).bindings),
      'durable-object'
    ),
    normalizeBindings(
      arrayEntries(ensureObject(envSection.durable_objects).bindings),
      'durable-object'
    )
  );

  const main =
    typeof document.main === 'string'
      ? document.main
      : typeof document.script === 'string'
      ? document.script
      : 'src/index.ts';

  const meshPolicy = buildMeshPolicyFromJson(
    document,
    envSection,
    resolve(configPath)
  );

  return {
    configPath: resolve(configPath),
    projectRoot: dirname(resolve(configPath)),
    name:
      typeof document.name === 'string'
        ? document.name
        : environment
        ? `x-ranger-${environment}`
        : 'x-ranger-worker',
    main,
    compatibilityDate:
      typeof document.compatibility_date === 'string'
        ? document.compatibility_date
        : undefined,
    vars: {
      ...stringRecord(document.vars),
      ...stringRecord(envSection.vars),
    },
    bindings,
    ...(meshPolicy ? { meshPolicy } : {}),
  };
}

export function resolveXRangerConfig(
  options: XRangerConfigResolveOptions = {}
): XRangerResolvedConfig {
  const cwd = resolve(options.cwd ?? process.cwd());
  const configPath = options.config
    ? resolve(cwd, options.config)
    : findConfigUpwards(cwd);

  if (!configPath) {
    throw new Error(
      'x-ranger could not locate a aeon.toml, xranger.toml, wrangler.toml, wrangler.json, or wrangler.jsonc file.'
    );
  }

  const extension = extname(configPath);
  const parsed =
    extension === '.toml'
      ? parseTomlConfig(configPath, options.env)
      : parseJsonConfig(configPath, options.env);

  let scriptPath = options.script
    ? resolve(parsed.projectRoot, options.script)
    : resolve(parsed.projectRoot, parsed.main);

  // If scriptPath is a directory and contains manifest.json, it's a gnot built bundle.
  if (existsSync(scriptPath) && statSync(scriptPath).isDirectory()) {
    const manifestPath = resolve(scriptPath, 'manifest.json');
    if (existsSync(manifestPath)) {
      // In a real implementation, we would merge the manifest.json into the config.
      // For now, we assume the bundle is ready for execution.
    }
  }

  return {
    ...parsed,
    main: scriptPath,
  };
}

export function defaultXRangerRegistryDir(
  config: XRangerResolvedConfig
): string {
  return resolve(config.projectRoot, '.x-ranger', 'sessions');
}
