import { FlowFrame, FIN, FOLD, FORK, VENT } from './types';

export const BODY_POLITICK_FRAME_SCHEMA = 'aeon.body-politick.signal.v1';
export const BODY_POLITICK_FLOW_STREAM_ID = 0xb0d1;

export interface BodyPolitickFrame {
  readonly schema: typeof BODY_POLITICK_FRAME_SCHEMA;
  readonly signalId: string;
  readonly eventId: string;
  readonly outcomeId: string;
  readonly sourceClass: string;
  readonly sourceId: string;
  readonly phyleId?: string;
  readonly estimate: number;
  readonly confidence: number;
  readonly sampleSize: number;
  readonly participantCount: number;
  readonly releasedFields: number;
  readonly privacyBudget: number;
  readonly privacyPolicy: string;
  readonly privateMemberFlowExposed: false;
  readonly claimsAuthority: false;
  readonly falsificationStatus: string;
  readonly theoremLineage: readonly string[];
  readonly conjectures: readonly string[];
  readonly observedAt: string;
  readonly metadata: Record<string, unknown>;
}

export interface BodyPolitickFlowFrameOptions {
  readonly streamId?: number;
  readonly sequence?: number;
  readonly flags?: number;
  readonly terminalBatch?: boolean;
}

const encoder = new TextEncoder();
const decoder = new TextDecoder();

function stableSequence(input: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function hasLineageOrConjecture(frame: BodyPolitickFrame): boolean {
  return frame.theoremLineage.length > 0 || frame.conjectures.length > 0;
}

function defaultFlags(frame: BodyPolitickFrame, terminalBatch: boolean): number {
  const invalidBoundary =
    frame.claimsAuthority !== false ||
    frame.privateMemberFlowExposed !== false ||
    !hasLineageOrConjecture(frame);
  const base = invalidBoundary ? VENT : FORK | FOLD;
  return terminalBatch ? base | FIN : base;
}

export function encodeBodyPolitickFlowFrame(
  frame: BodyPolitickFrame,
  options: BodyPolitickFlowFrameOptions = {}
): FlowFrame {
  const payload = encoder.encode(JSON.stringify(frame));
  return {
    streamId: options.streamId ?? BODY_POLITICK_FLOW_STREAM_ID,
    sequence:
      options.sequence ??
      stableSequence(`${frame.eventId}:${frame.outcomeId}:${frame.signalId}`),
    flags:
      options.flags ?? defaultFlags(frame, options.terminalBatch === true),
    payload,
  };
}

function assertBodyPolitickFrame(value: unknown): asserts value is BodyPolitickFrame {
  if (!value || typeof value !== 'object') {
    throw new Error('Body-politick FlowFrame payload must be a JSON object.');
  }
  const frame = value as Partial<BodyPolitickFrame>;
  if (frame.schema !== BODY_POLITICK_FRAME_SCHEMA) {
    throw new Error('Body-politick FlowFrame payload has an unsupported schema.');
  }
  if (typeof frame.eventId !== 'string' || frame.eventId.length === 0) {
    throw new Error('Body-politick FlowFrame payload is missing eventId.');
  }
  if (typeof frame.outcomeId !== 'string' || frame.outcomeId.length === 0) {
    throw new Error('Body-politick FlowFrame payload is missing outcomeId.');
  }
  if (frame.claimsAuthority !== false) {
    throw new Error('Body-politick FlowFrame payload must not claim authority.');
  }
  if (frame.privateMemberFlowExposed !== false) {
    throw new Error('Body-politick FlowFrame payload must not expose member flow.');
  }
  if (!Array.isArray(frame.theoremLineage) || !Array.isArray(frame.conjectures)) {
    throw new Error('Body-politick FlowFrame payload must include lineage arrays.');
  }
  if (!hasLineageOrConjecture(frame as BodyPolitickFrame)) {
    throw new Error('Body-politick FlowFrame payload must include theorem lineage or conjecture markers.');
  }
}

export function decodeBodyPolitickFlowFrame(flowFrame: FlowFrame): BodyPolitickFrame {
  const parsed = JSON.parse(decoder.decode(flowFrame.payload)) as unknown;
  assertBodyPolitickFrame(parsed);
  return parsed;
}
