/**
 * Node filesystem-backed content source.
 *
 * This remains the default x-gnosis origin for local and Bun-hosted paths.
 * Edge/worker deployments can layer a D1 VFS in front of it or omit it.
 */

import { existsSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import {
  type ContentRequest,
  type ContentSource,
  type ResolvedContent,
  buildWeakEtag,
  inferContentTypeFromPath,
  normalizeContentPath,
} from './content-source.ts';

export class NodeFilesystemContentSource implements ContentSource {
  readonly name = 'filesystem';

  resolve(request: ContentRequest): ResolvedContent | null {
    const filePath = resolveFilesystemPath(
      request.root,
      request.uri,
      request.indexFiles
    );
    if (!filePath ) {
      return null;
    }

    const data = readFileSync(filePath);
    const stat = statSync(filePath);
    const lastModified = stat.mtimeMs;
    const contentType = inferContentTypeFromPath(filePath);
    const body = new Uint8Array(data);

    return {
      data: body,
      contentType,
      etag: buildWeakEtag(stat.size, lastModified),
      lastModified,
      size: stat.size,
      filePath,
    };
  }
}

function resolveFilesystemPath(
  root: string,
  uri: string,
  indexFiles: readonly string[]
): string | null {
  const cleanUri = normalizeContentPath(uri);
  const fullPath = join(root, cleanUri);

  if (existsSync(fullPath)) {
    try {
      const stat = statSync(fullPath);
      if (stat.isFile()) {
        return fullPath;
      }

      if (stat.isDirectory()) {
        for (const indexFile of indexFiles ) {
          const indexPath = join(fullPath, indexFile);
          if (existsSync(indexPath) && statSync(indexPath).isFile()) {
            return indexPath;
          }
        }
      }
    } catch {
      return null;
    }
  }

  return null;
}
