/**
 * @a0n/auth - XPath-like Node Selection
 *
 * Select nodes in data trees using XPath-inspired expressions.
 * Supports leaf/branch targeting, predicates, and recursive descent.
 *
 * @example
 * ```typescript
 * import { select, compile, NodeType } from '@a0n/auth';
 *
 * const data = {
 *   users: {
 *     alice: { email: 'alice@example.com', role: 'admin', settings: { theme: 'dark' } },
 *     bob: { email: 'bob@example.com', role: 'user', settings: { theme: 'light' } },
 *   },
 *   config: { public: true },
 * };
 *
 * // Select all email fields anywhere in the tree
 * select('//email', data);
 * // => [{ path: '/users/alice/email', value: 'alice@example.com', type: 'leaf' }, ...]
 *
 * // Select admin users
 * select('/users/*[role="admin"]', data);
 * // => [{ path: '/users/alice', value: {...}, type: 'branch' }]
 *
 * // Select all leaf nodes under settings
 * select('//settings/leaf()', data);
 * // => [{ path: '/users/alice/settings/theme', value: 'dark', type: 'leaf' }, ...]
 *
 * // Select all branches (objects)
 * select('//branch()', data);
 * // => all object nodes
 * ```
 */

// =============================================================================
// TYPES
// =============================================================================

/**
 * Node types in the tree
 */
export type NodeType = 'leaf' | 'branch' | 'array' | 'root';

/**
 * A selected node from the tree
 */
export interface SelectedNode {
  /** Full path to the node */
  path: string;
  /** The node's value */
  value: unknown;
  /** Type of node */
  type: NodeType;
  /** Parent path */
  parent: string;
  /** Node name (last path segment) */
  name: string;
  /** Depth in the tree (0 = root) */
  depth: number;
}

/**
 * Compiled selector for reuse
 */
export interface CompiledSelector {
  /** Original expression */
  expression: string;
  /** Parsed steps */
  steps: SelectorStep[];
  /** Execute against data */
  select: (data: unknown) => SelectedNode[];
  /** Check if a path matches */
  matches: (path: string, data: unknown) => boolean;
}

/**
 * A single step in the selector
 */
export interface SelectorStep {
  /** Axis type */
  axis: 'child' | 'descendant' | 'self' | 'parent' | 'ancestor';
  /** Node test */
  nodeTest: NodeTest;
  /** Predicates to filter */
  predicates: Predicate[];
}

/**
 * Node test types
 */
export type NodeTest =
  | { type: 'name'; name: string }
  | { type: 'wildcard' }
  | { type: 'doubleWildcard' }
  | { type: 'function'; fn: 'leaf' | 'branch' | 'array' | 'text' | 'node' };

/**
 * Predicate for filtering nodes
 */
export type Predicate =
  | { type: 'index'; index: number }
  | { type: 'comparison'; left: string; op: string; right: string }
  | { type: 'exists'; path: string }
  | { type: 'function'; fn: string; args: string[] };

// =============================================================================
// PARSING
// =============================================================================

/**
 * Parse an XPath-like expression into steps
 */
export function parseSelector(expression: string): SelectorStep[] {
  const steps: SelectorStep[] = [];
  let remaining = expression.trim();

  // Handle leading /
  if (remaining.startsWith('//')) {
    remaining = remaining.slice(2);
    steps.push(createDescendantStep(remaining));
    remaining = consumeStep(remaining);
  } else if (remaining.startsWith('/')) {
    remaining = remaining.slice(1);
  }

  while (remaining.length > 0) {
    // Check for descendant axis
    if (remaining.startsWith('//')) {
      remaining = remaining.slice(2);
      if (remaining.length > 0) {
        steps.push(createDescendantStep(remaining));
        remaining = consumeStep(remaining);
      }
      continue;
    }

    // Check for child axis
    if (remaining.startsWith('/')) {
      remaining = remaining.slice(1);
      continue;
    }

    // Parse the step
    const step = parseStep(remaining);
    steps.push(step);
    remaining = consumeStep(remaining);
  }

  return steps;
}

function createDescendantStep(remaining: string): SelectorStep {
  const step = parseStep(remaining);
  step.axis = 'descendant';
  return step;
}

function parseStep(input: string): SelectorStep {
  let remaining = input;
  let axis: SelectorStep['axis'] = 'child';
  let nodeTest: NodeTest;
  const predicates: Predicate[] = [];

  // Check for axis prefix
  if (remaining.startsWith('..')) {
    axis = 'parent';
    remaining = remaining.slice(2);
  } else if (remaining.startsWith('.')) {
    axis = 'self';
    remaining = remaining.slice(1);
  }

  // Parse node test
  const nameMatch = remaining.match(/^([a-zA-Z_$][a-zA-Z0-9_$]*|\*\*|\*)/);
  if (nameMatch) {
    const name = nameMatch[1];
    if (name === '**') {
      nodeTest = { type: 'doubleWildcard' };
    } else if (name === '*') {
      nodeTest = { type: 'wildcard' };
    } else {
      nodeTest = { type: 'name', name };
    }
    remaining = remaining.slice(name.length);
  } else {
    nodeTest = { type: 'wildcard' };
  }

  // Check for function call
  const funcMatch = remaining.match(/^\(\s*\)/);
  if (funcMatch && nodeTest.type === 'name') {
    const fnName = (nodeTest as { type: 'name'; name: string }).name;
    const supportedFunctions = [
      'leaf',
      'branch',
      'array',
      'text',
      'node',
    ] as const;
    if (
      supportedFunctions.includes(fnName as (typeof supportedFunctions)[number])
    ) {
      nodeTest = {
        type: 'function',
        fn: fnName as (typeof supportedFunctions)[number],
      };
      remaining = remaining.slice(funcMatch[0].length);
    }
  }

  // Parse predicates
  while (remaining.startsWith('[')) {
    const endBracket = findMatchingBracket(remaining);
    if (endBracket === -1) break;

    const predicateStr = remaining.slice(1, endBracket);
    const predicate = parsePredicate(predicateStr);
    if (predicate) {
      predicates.push(predicate);
    }
    remaining = remaining.slice(endBracket + 1);
  }

  return { axis, nodeTest, predicates };
}

function parsePredicate(input: string): Predicate | null {
  const trimmed = input.trim();

  // Index predicate: [0], [1], [-1]
  if (/^-?\d+$/.test(trimmed)) {
    return { type: 'index', index: parseInt(trimmed, 10) };
  }

  // Comparison predicate: [role="admin"], [count>5]
  const compMatch = trimmed.match(
    /^([a-zA-Z_$][a-zA-Z0-9_$]*)\s*(=|!=|>|<|>=|<=)\s*(.+)$/
  );
  if (compMatch) {
    return {
      type: 'comparison',
      left: compMatch[1],
      op: compMatch[2],
      right: compMatch[3].trim(),
    };
  }

  // Exists predicate: [email]
  if (/^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(trimmed)) {
    return { type: 'exists', path: trimmed };
  }

  // Function predicate: [contains(name, "test")]
  const fnMatch = trimmed.match(/^([a-zA-Z]+)\((.+)\)$/);
  if (fnMatch) {
    const args = fnMatch[2].split(',').map((a) => a.trim());
    return { type: 'function', fn: fnMatch[1], args };
  }

  return null;
}

function findMatchingBracket(input: string): number {
  if (!input.startsWith('[')) return -1;

  let depth = 0;
  for (let i = 0; i < input.length; i++) {
    if (input[i] === '[') depth++;
    else if (input[i] === ']') {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

function consumeStep(input: string): string {
  // Consume until next / or end
  let i = 0;
  let inBracket = 0;

  while (i < input.length) {
    if (input[i] === '[') inBracket++;
    else if (input[i] === ']') inBracket--;
    else if (input[i] === '/' && inBracket === 0) break;
    i++;
  }

  return input.slice(i);
}

// =============================================================================
// COMPILATION
// =============================================================================

/**
 * Compile a selector expression for reuse
 */
export function compile(expression: string): CompiledSelector {
  const steps = parseSelector(expression);

  return {
    expression,
    steps,
    select: (data: unknown) => executeSelector(steps, data),
    matches: (path: string, data: unknown) => {
      const selected = executeSelector(steps, data);
      return selected.some((node) => node.path === path);
    },
  };
}

// =============================================================================
// EXECUTION
// =============================================================================

/**
 * Select nodes from data using an expression
 */
export function select(expression: string, data: unknown): SelectedNode[] {
  const steps = parseSelector(expression);
  return executeSelector(steps, data);
}

/**
 * Execute compiled selector steps
 */
function executeSelector(steps: SelectorStep[], data: unknown): SelectedNode[] {
  // Start with root node
  let currentNodes: SelectedNode[] = [
    {
      path: '',
      value: data,
      type: getNodeType(data),
      parent: '',
      name: '',
      depth: 0,
    },
  ];

  for (const step of steps) {
    currentNodes = executeStep(step, currentNodes, data);
  }

  return currentNodes;
}

/**
 * Execute a single step
 */
function executeStep(
  step: SelectorStep,
  nodes: SelectedNode[],
  rootData: unknown
): SelectedNode[] {
  let result: SelectedNode[] = [];

  for (const node of nodes) {
    let candidates: SelectedNode[];

    switch (step.axis) {
      case 'child':
        candidates = getChildren(node);
        break;
      case 'descendant':
        candidates = getDescendants(node);
        break;
      case 'self':
        candidates = [node];
        break;
      case 'parent':
        candidates = getParent(node, rootData);
        break;
      case 'ancestor':
        candidates = getAncestors(node, rootData);
        break;
      default:
        candidates = [];
    }

    // Apply node test
    candidates = candidates.filter((c) => matchesNodeTest(c, step.nodeTest));

    // Apply predicates
    for (const predicate of step.predicates) {
      candidates = applyPredicate(candidates, predicate);
    }

    result = result.concat(candidates);
  }

  return result;
}

function getParent(node: SelectedNode, rootData: unknown): SelectedNode[] {
  if (!node.path) return [];
  const parentPath = node.parent;
  const parentValue = resolvePath(rootData, parentPath);
  if (parentValue === undefined) {
    return [];
  }
  const grandParentPath = getParentPath(parentPath);
  return [
    {
      path: parentPath,
      value: parentValue,
      type: getNodeType(parentValue),
      parent: grandParentPath ?? '',
      name: getNodeName(parentPath),
      depth: Math.max(0, node.depth - 1),
    },
  ];
}

function getAncestors(node: SelectedNode, rootData: unknown): SelectedNode[] {
  const ancestors: SelectedNode[] = [];
  let currentPath: string | null = node.parent;
  while (currentPath !== null) {
    const value = resolvePath(rootData, currentPath);
    if (value === undefined) {
      break;
    }
    const parentPath = getParentPath(currentPath);
    ancestors.push({
      path: currentPath,
      value,
      type: getNodeType(value),
      parent: parentPath ?? '',
      name: getNodeName(currentPath),
      depth: currentPath ? currentPath.split('/').filter(Boolean).length : 0,
    });
    currentPath = parentPath;
  }
  return ancestors;
}

function getParentPath(path: string): string | null {
  if (path === '') return null;
  if (path.endsWith(']')) {
    const bracketIndex = path.lastIndexOf('[');
    if (bracketIndex > -1) {
      const withoutIndex = path.slice(0, bracketIndex);
      return withoutIndex || '';
    }
  }
  const slashIndex = path.lastIndexOf('/');
  if (slashIndex <= 0) return '';
  return path.slice(0, slashIndex);
}

function getNodeName(path: string): string {
  if (!path) return '';
  const slashIndex = path.lastIndexOf('/');
  return slashIndex >= 0 ? path.slice(slashIndex + 1) : path;
}

function resolvePath(rootData: unknown, path: string): unknown {
  if (path === '') return rootData;
  let current: unknown = rootData;
  const rawSegments = path.split('/').filter(Boolean);
  for (const rawSegment of rawSegments) {
    const tokens = rawSegment.match(/([^\[\]]+)|\[(\d+)\]/g);
    if (!tokens) {
      return undefined;
    }
    for (const token of tokens) {
      if (token.startsWith('[') && token.endsWith(']')) {
        const index = Number(token.slice(1, -1));
        if (!Array.isArray(current) || Number.isNaN(index)) {
          return undefined;
        }
        current = current[index];
      } else {
        if (typeof current !== 'object' || current === null) {
          return undefined;
        }
        const obj = current as Record<string, unknown>;
        current = obj[token];
      }
    }
  }
  return current;
}

/**
 * Get child nodes
 */
function getChildren(node: SelectedNode): SelectedNode[] {
  const children: SelectedNode[] = [];
  const value = node.value;

  if (value === null || value === undefined) {
    return children;
  }

  if (Array.isArray(value)) {
    value.forEach((item, index) => {
      children.push({
        path: `${node.path}[${index}]`,
        value: item,
        type: getNodeType(item),
        parent: node.path,
        name: `[${index}]`,
        depth: node.depth + 1,
      });
    });
  } else if (typeof value === 'object') {
    for (const [key, val] of Object.entries(value)) {
      children.push({
        path: node.path ? `${node.path}/${key}` : `/${key}`,
        value: val,
        type: getNodeType(val),
        parent: node.path,
        name: key,
        depth: node.depth + 1,
      });
    }
  }

  return children;
}

/**
 * Get all descendant nodes (recursive)
 */
function getDescendants(
  node: SelectedNode,
  maxDepth: number = 100
): SelectedNode[] {
  const descendants: SelectedNode[] = [];
  if (maxDepth <= 0) return descendants;
  const children = getChildren(node);

  for (const child of children) {
    descendants.push(child);
    descendants.push(...getDescendants(child, maxDepth - 1));
  }

  return descendants;
}

/**
 * Determine node type
 */
function getNodeType(value: unknown): NodeType {
  if (value === null || value === undefined) {
    return 'leaf';
  }
  if (Array.isArray(value)) {
    return 'array';
  }
  if (typeof value === 'object') {
    return 'branch';
  }
  return 'leaf';
}

/**
 * Check if node matches a node test
 */
function matchesNodeTest(node: SelectedNode, test: NodeTest): boolean {
  switch (test.type) {
    case 'name':
      return node.name === test.name;

    case 'wildcard':
      return true;

    case 'doubleWildcard':
      return true;

    case 'function':
      switch (test.fn) {
        case 'leaf':
          return node.type === 'leaf';
        case 'branch':
          return node.type === 'branch';
        case 'array':
          return node.type === 'array';
        case 'text':
          return typeof node.value === 'string';
        case 'node':
          return true;
        default:
          return false;
      }

    default:
      return false;
  }
}

/**
 * Apply a predicate to filter nodes
 */
function applyPredicate(
  nodes: SelectedNode[],
  predicate: Predicate
): SelectedNode[] {
  switch (predicate.type) {
    case 'index': {
      const index =
        predicate.index < 0 ? nodes.length + predicate.index : predicate.index;
      return index >= 0 && index < nodes.length ? [nodes[index]] : [];
    }

    case 'comparison':
      return nodes.filter((node) => evaluateComparison(node, predicate));

    case 'exists':
      return nodes.filter((node) => hasProperty(node.value, predicate.path));

    case 'function':
      return nodes.filter((node) => evaluatePredicateFunction(node, predicate));

    default:
      return nodes;
  }
}

/**
 * Evaluate a comparison predicate
 */
function evaluateComparison(
  node: SelectedNode,
  pred: { left: string; op: string; right: string }
): boolean {
  const leftValue = getProperty(node.value, pred.left);
  let rightValue: unknown = pred.right;

  // Parse right value
  if (rightValue === 'true') rightValue = true;
  else if (rightValue === 'false') rightValue = false;
  else if (rightValue === 'null') rightValue = null;
  else if (/^-?\d+(\.\d+)?$/.test(rightValue as string)) {
    rightValue = parseFloat(rightValue as string);
  } else if (
    ((rightValue as string).startsWith('"') &&
      (rightValue as string).endsWith('"')) ||
    ((rightValue as string).startsWith("'") &&
      (rightValue as string).endsWith("'"))
  ) {
    rightValue = (rightValue as string).slice(1, -1);
  }

  switch (pred.op) {
    case '=':
    case '==':
      return leftValue === rightValue;
    case '!=':
      return leftValue !== rightValue;
    case '>':
      return (leftValue as number) > (rightValue as number);
    case '<':
      return (leftValue as number) < (rightValue as number);
    case '>=':
      return (leftValue as number) >= (rightValue as number);
    case '<=':
      return (leftValue as number) <= (rightValue as number);
    default:
      return false;
  }
}

/**
 * Evaluate a predicate function
 */
function evaluatePredicateFunction(
  node: SelectedNode,
  pred: { fn: string; args: string[] }
): boolean {
  switch (pred.fn) {
    case 'contains': {
      const [prop, search] = pred.args;
      const value = getProperty(node.value, prop);
      const searchStr = search.replace(/^["']|["']$/g, '');
      if (typeof value === 'string') {
        return value.includes(searchStr);
      }
      if (Array.isArray(value)) {
        return value.includes(searchStr);
      }
      return false;
    }

    case 'startsWith': {
      const [prop, prefix] = pred.args;
      const value = getProperty(node.value, prop);
      const prefixStr = prefix.replace(/^["']|["']$/g, '');
      return typeof value === 'string' && value.startsWith(prefixStr);
    }

    case 'endsWith': {
      const [prop, suffix] = pred.args;
      const value = getProperty(node.value, prop);
      const suffixStr = suffix.replace(/^["']|["']$/g, '');
      return typeof value === 'string' && value.endsWith(suffixStr);
    }

    case 'matches': {
      const [prop, pattern] = pred.args;
      const value = getProperty(node.value, prop);
      const patternStr = pattern.replace(/^["']|["']$/g, '');
      return typeof value === 'string' && new RegExp(patternStr).test(value);
    }

    case 'not': {
      // Negate another predicate - simplified
      return false;
    }

    default:
      return false;
  }
}

/**
 * Get a property from a value
 */
function getProperty(value: unknown, path: string): unknown {
  if (value === null || value === undefined) {
    return undefined;
  }

  const parts = path.split('.');
  let current: unknown = value;

  for (const part of parts) {
    if (current === null || current === undefined) {
      return undefined;
    }
    current = (current as Record<string, unknown>)[part];
  }

  return current;
}

/**
 * Check if a property exists
 */
function hasProperty(value: unknown, path: string): boolean {
  return getProperty(value, path) !== undefined;
}

// =============================================================================
// UTILITY FUNCTIONS
// =============================================================================

/**
 * Get all leaf nodes in a tree
 */
export function getLeaves(data: unknown): SelectedNode[] {
  return select('//leaf()', data);
}

/**
 * Get all branch nodes in a tree
 */
export function getBranches(data: unknown): SelectedNode[] {
  return select('//branch()', data);
}

/**
 * Get all nodes at a specific depth
 */
export function getNodesAtDepth(data: unknown, depth: number): SelectedNode[] {
  const all = select('//node()', data);
  return all.filter((n) => n.depth === depth);
}

/**
 * Get the value at a specific path
 */
export function getValue(data: unknown, path: string): unknown {
  const results = select(path, data);
  return results.length > 0 ? results[0].value : undefined;
}

/**
 * Check if a path exists in the data
 */
export function pathExists(data: unknown, path: string): boolean {
  return select(path, data).length > 0;
}

/**
 * Get all paths in the tree
 */
export function getAllPaths(data: unknown): string[] {
  return select('//node()', data).map((n) => n.path);
}

/**
 * Filter nodes by a custom predicate function
 */
export function filterNodes(
  data: unknown,
  expression: string,
  predicate: (node: SelectedNode) => boolean
): SelectedNode[] {
  return select(expression, data).filter(predicate);
}

// =============================================================================
// CAPABILITY INTEGRATION
// =============================================================================

/**
 * Check if a capability grants access to specific nodes
 */
export function capabilityGrantsAccess(
  capabilityResource: string,
  targetPath: string,
  data: unknown
): boolean {
  // If capability is a simple path pattern, convert to xpath
  const selector = pathToSelector(capabilityResource);
  const compiled = compile(selector);

  // Check if the target path is selected
  const selected = compiled.select(data);
  return selected.some((node) => {
    // Exact match
    if (node.path === targetPath) return true;
    // Ancestor match (capability on parent grants access to children)
    if (targetPath.startsWith(node.path + '/')) return true;
    return false;
  });
}

/**
 * Convert a simple path pattern to an xpath selector
 */
export function pathToSelector(pattern: string): string {
  // Handle common patterns
  let selector = pattern;

  // Remove scheme:namespace: prefix
  const prefixMatch = pattern.match(/^[a-z]+:[a-z]+:(.*)/i);
  if (prefixMatch) {
    selector = prefixMatch[1];
  }

  // Convert ** to descendant axis
  selector = selector.replace(/\/\*\*/g, '//node()');
  selector = selector.replace(/\*\*/g, '//node()');

  // Ensure leading /
  if (!selector.startsWith('/') && !selector.startsWith('//')) {
    selector = '/' + selector;
  }

  return selector;
}

/**
 * Get all nodes a capability grants access to
 */
export function getGrantedNodes(
  capabilityResource: string,
  data: unknown
): SelectedNode[] {
  const selector = pathToSelector(capabilityResource);
  const selected = select(selector, data);

  // Include all descendants of selected nodes
  const result: SelectedNode[] = [];
  const seenPaths = new Set<string>();

  for (const node of selected) {
    if (!seenPaths.has(node.path)) {
      result.push(node);
      seenPaths.add(node.path);
    }

    // Add descendants
    const descendants = getDescendants(node);
    for (const desc of descendants) {
      if (!seenPaths.has(desc.path)) {
        result.push(desc);
        seenPaths.add(desc.path);
      }
    }
  }

  return result;
}
