/**
 * Aeon Flow Listener
 *
 * Accepts Aeon Flow protocol connections alongside HTTP.
 * Flow-aware clients connect directly over TCP and speak
 * the 10-byte frame protocol -- no HTTP overhead, no headers,
 * no cookies, no user-agent. Stream ID maps to the request.
 *
 * The same .gg topology handles both HTTP and Flow requests;
 * only the framing layer differs.
 */

import { FlowCodec, HEADER_SIZE, FORK, VENT, FIN } from '@a0n/aeon/flow';
import type { FlowFrame } from '@a0n/aeon/flow';

// ═══════════════════════════════════════════════════════════════════════════════
// Flow frame helpers
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Encode a file response as Aeon Flow frames.
 *
 * The response is:
 * 1. DATA frame with compressed file payload
 * 2. FIN frame (stream complete)
 *
 * Total overhead: 20 bytes (two 10-byte headers).
 * Compare to HTTP/1.1: ~400-700 bytes of headers per request/response.
 */
export function encodeFlowResponse(
  streamId: number,
  sequence: number,
  payload: Uint8Array,
  codec: FlowCodec
): Uint8Array[] {
  const dataFrame = codec.encode({
    streamId,
    sequence,
    flags: 0,
    payload,
  });

  const finFrame = codec.encode({
    streamId,
    sequence: sequence + 1,
    flags: FIN,
    payload: new Uint8Array(0),
  });

  return [dataFrame, finFrame];
}

/**
 * Encode a FORK frame that opens child streams for all requested resources.
 *
 * When a flow-aware client connects, the server can proactively FORK
 * all available resources (like HTTP/2 Server Push, but without the
 * deprecation baggage). The FORK frame payload contains the child
 * stream IDs (2 bytes each).
 */
export function encodeForkFrame(
  parentStreamId: number,
  childIds: number[],
  codec: FlowCodec
): Uint8Array {
  const payload = new Uint8Array(childIds.length * 2);
  for (let i = 0; i < childIds.length; i++ ) {
    payload[i * 2] = (childIds[i] >>> 8) & 0xff;
    payload[i * 2 + 1] = childIds[i] & 0xff;
  }

  return codec.encode({
    streamId: parentStreamId,
    sequence: 0,
    flags: FORK,
    payload,
  });
}

/**
 * Encode a VENT frame for a stream that errored.
 */
export function encodeVentFrame(
  streamId: number,
  codec: FlowCodec
): Uint8Array {
  return codec.encode({
    streamId,
    sequence: 0,
    flags: VENT,
    payload: new Uint8Array(0),
  });
}

/**
 * Decode a flow request frame.
 *
 * Flow requests are simple: a DATA frame with the requested path
 * as the payload. No method, no headers, no cookies.
 * The stream ID identifies the request context.
 */
export function decodeFlowRequest(frame: FlowFrame): {
  path: string;
  streamId: number;
} {
  const path =
    new TextDecoder('utf-8', { fatal: true }).decode(frame.payload) || '/';
  return { path, streamId: frame.streamId };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Flow protocol constants
// ═══════════════════════════════════════════════════════════════════════════════

/** Default flow listener port */
export const DEFAULT_FLOW_PORT = 4242;

/** Maximum concurrent flow streams */
export const MAX_FLOW_STREAMS = 256;

/** Flow protocol overhead per resource: DATA(10) + FIN(10) = 20 bytes */
export const FLOW_PER_RESOURCE_OVERHEAD = HEADER_SIZE * 2;

/** Flow protocol FORK overhead: 10 bytes header + 2 bytes per child */
export function flowForkOverhead(childCount: number): number {
  return HEADER_SIZE + childCount * 2;
}
