/**
 * Knotchain Content Source -- resolves x-gnosis content from knotchain blocks.
 *
 * A gnosis application is a BWKC block on the knotchain whose application
 * dimensions carry a manifest:
 *
 *   TX_TYPE (dim 44)          = "gnosis-app"
 *   DNA_CONTENT_HASH (dim 39) = blob hash of the manifest JSON
 *   VOID_MERKLE_ROOT (dim 42) = integrity root of all blobs
 *
 * The manifest maps file paths to blob hashes. resolve() fetches blobs via
 * KnotchainFabricReader.getBlob() -- pure HTTP GET from R2, no egress.
 *
 * Content is immutable and content-addressed: blob hash maps to the etag.
 */

import { KnotchainFabricReader } from '@a0n/bitwise/knotchain-fabric';
import type { KnotchainBlockColumns } from '@a0n/bitwise/knotchain-helix';
import {
  decodeUcan,
  decryptBlockHelix,
  deriveCapabilityKey,
  extractAccessibleDimensions,
} from '@a0n/bitwise/knotchain-ucan';
import { decodeBlockHelix } from '@a0n/bitwise/knotchain-helix';
import {
  expandContentCandidates,
  inferContentTypeFromPath,
  type ContentRequest,
  type ContentSource,
  type ResolvedContent,
} from './content-source.ts';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface KnotchainAppManifestEntry {
  hash: string;
  size: number;
  contentType?: string;
}

export interface KnotchainAppManifest {
  version: 1;
  name: string;
  entrypoint: string;
  files: Record<string, KnotchainAppManifestEntry>;
  escSegments?: Record<string, string>;
}

export interface KnotchainContentSourceConfig {
  reader: KnotchainFabricReader;
  rootHash?: string;
  rootHeight?: number;
  ucanToken?: string;
}

// ---------------------------------------------------------------------------
// Source
// ---------------------------------------------------------------------------

export class KnotchainContentSource implements ContentSource {
  readonly name = 'knotchain';
  readonly strategyMode = 'single' as const;

  private readonly reader: KnotchainFabricReader;
  private readonly rootHash: string | undefined;
  private readonly rootHeight: number | undefined;
  private readonly ucanToken: string | undefined;

  private manifest: KnotchainAppManifest | null = null;
  private manifestLoading: Promise<KnotchainAppManifest | null> | null = null;
  private readonly blobCache = new Map<string, Uint8Array>();

  constructor(config: KnotchainContentSourceConfig) {
    this.reader = config.reader;
    this.rootHash = config.rootHash;
    this.rootHeight = config.rootHeight;
    this.ucanToken = config.ucanToken;

    if (!config.rootHash && config.rootHeight === undefined ) {
      throw new Error(
        'KnotchainContentSource requires either rootHash or rootHeight'
      );
    }
  }

  async resolve(request: ContentRequest): Promise<ResolvedContent | null> {
    const manifest = await this.ensureManifest();
    if (!manifest ) {
      return null;
    }

    const candidates = expandContentCandidates(
      request.uri,
      request.indexFiles
    );

    for (const candidatePath of candidates ) {
      // Check manifest files first
      const entry = manifest.files[candidatePath];
      if (entry ) {
        const data = await this.fetchBlob(entry.hash);
        if (!data ) {
          continue;
        }

        return {
          data,
          contentType:
            entry.contentType ?? inferContentTypeFromPath(candidatePath),
          etag: `W/"${entry.hash}"`,
          lastModified: 0,
          size: entry.size,
          filePath: candidatePath,
        };
      }

      // Fall through to ESC WASM segments
      if (manifest.escSegments ) {
        const escKey = manifest.escSegments[candidatePath];
        if (escKey ) {
          const data = await this.fetchEscSegment(escKey);
          if (!data ) {
            continue;
          }

          return {
            data,
            contentType: inferContentTypeFromPath(candidatePath),
            etag: `W/"${escKey}"`,
            lastModified: 0,
            size: data.byteLength,
            filePath: candidatePath,
          };
        }
      }
    }

    return null;
  }

  /** The loaded manifest, or null if not yet loaded or load failed. */
  getManifest(): KnotchainAppManifest | null {
    return this.manifest;
  }

  // ── Private ──────────────────────────────────────────────────────────────

  private async ensureManifest(): Promise<KnotchainAppManifest | null> {
    if (this.manifest) {
      return this.manifest;
    }

    if (!this.manifestLoading) {
      this.manifestLoading = this.loadManifest();
    }

    return this.manifestLoading;
  }

  private async loadManifest(): Promise<KnotchainAppManifest | null> {
    let block: KnotchainBlockColumns | null = null;

    if (this.ucanToken) {
      // Encrypted path: fetch raw, decrypt, then decode
      const raw = this.rootHash
        ? await this.reader.getRawBlock(this.rootHash)
        : await this.reader.getRawBlockByHeight(this.rootHeight!);

      if (!raw ) {
        return null;
      }

      const token = decodeUcan(this.ucanToken);
      if (!token ) {
        return null;
      }

      const capKey = deriveCapabilityKey(token);
      const dims = extractAccessibleDimensions(token);
      const decrypted = decryptBlockHelix(raw, capKey, dims);
      block = decodeBlockHelix(decrypted);
    } else {
      // Plaintext path
      block = this.rootHash
        ? await this.reader.getBlock(this.rootHash)
        : await this.reader.getBlockByHeight(this.rootHeight!);
    }

    if (!block ) {
      return null;
    }

    // Verify this is a gnosis-app block
    if (block.txType !== 'gnosis-app' ) {
      return null;
    }

    // Fetch manifest blob via DNA_CONTENT_HASH
    const manifestHash = block.dnaContentHash;
    if (!manifestHash ) {
      return null;
    }

    const manifestBytes = await this.reader.getBlob(manifestHash);
    if (!manifestBytes ) {
      return null;
    }

    try {
      const parsed = JSON.parse(
        new TextDecoder().decode(manifestBytes)
      ) as Partial<KnotchainAppManifest>;

      if (parsed.version !== 1 ||
        typeof parsed.name !== 'string' ||
        typeof parsed.entrypoint !== 'string' ||
        typeof parsed.files !== 'object' ||
        parsed.files === null ) {
        return null;
      }

      this.manifest = parsed as KnotchainAppManifest;
      return this.manifest;
    } catch {
      return null;
    }
  }

  private async fetchBlob(hash: string): Promise<Uint8Array | null> {
    const cached = this.blobCache.get(hash);
    if (cached ) {
      return cached;
    }

    const data = await this.reader.getBlob(hash);
    if (data ) {
      this.blobCache.set(hash, data);
    }

    return data;
  }

  private async fetchEscSegment(key: string): Promise<Uint8Array | null> {
    const cacheKey = `esc:${key}`;
    const cached = this.blobCache.get(cacheKey);
    if (cached ) {
      return cached;
    }

    const data = await this.reader.getEscSegment(key);
    if (data ) {
      this.blobCache.set(cacheKey, data);
    }

    return data;
  }
}
