/**
 * LRU File Cache
 *
 * In-memory cache for static file content with LRU eviction.
 * This is the "cache" arm of the race(cache, mmap, disk) topology.
 * Cache hits return in microseconds; misses throw to trigger vent.
 */

import {
  CommunityCacheJournal,
  type CommunityCacheFailureKind,
  type CommunityCacheHead,
  type CommunityCacheRecord,
  type CommunityCacheSource,
} from './community-cache.ts';

export interface CacheEntry {
  data: Uint8Array;
  contentType: string;
  etag: string;
  lastModified: number;
  cacheControl: string;
  varyKey: string;
  bodyDigest: string;
  communityRecordId: string;
  size: number;
  accessedAt: number;
  /** Rejection tracking for God Formula eviction: times served successfully */
  servedOk: number;
  /** Rejection tracking for God Formula eviction: times served with error (4xx/5xx) */
  servedErr: number;
}

/**
 * God Formula quality score for a cache entry.
 * w = R - min(v, R) + 1 where R = total serves, v = error serves.
 * Higher quality = higher weight = less likely to be evicted.
 * The +1 (sliver) ensures new entries are never quality-zero.
 */
function cacheQuality(entry: CacheEntry): number {
  const rounds = entry.servedOk + entry.servedErr;
  return rounds - Math.min(entry.servedErr, rounds) + 1;
}

export interface FileCacheSetOptions {
  etag?: string;
  cacheControl?: string;
  varyKey?: string;
  observedAt?: number;
  source?: CommunityCacheSource;
}

export interface FileCacheFailureOptions {
  detail?: string;
  observedAt?: number;
  source?: CommunityCacheSource;
}

export class FileCache {
  private entries: Map<string, CacheEntry> = new Map();
  private maxBytes: number;
  private currentBytes: number = 0;
  private journal = new CommunityCacheJournal();

  constructor(maxBytes: number = 64 * 1024 * 1024) {
    this.maxBytes = maxBytes;
  }

  /**
   * Look up a file in cache. Returns entry or null (triggers vent in race).
   */
  get(key: string): CacheEntry | null {
    const entry = this.entries.get(key);
    if (!entry) return null;

    // LRU touch: delete + re-insert moves entry to end of Map iteration
    // order. This makes evictLRU() O(1) via Map.keys().next() instead
    // of O(n) linear scan -- the cannon rotation applied to eviction.
    entry.accessedAt = Date.now();
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry;
  }

  /**
   * Store a file in cache. Evicts LRU entries if over capacity.
   */
  set(
    key: string,
    data: Uint8Array,
    contentType: string,
    lastModified: number,
    options: FileCacheSetOptions = {}
  ): void {
    // Don't cache files larger than 1/4 of max
    if (data.length > this.maxBytes / 4) return;

    // Evict existing entry for this key
    this.evictKey(key);

    // Evict LRU until we have room
    while (
      this.currentBytes + data.length > this.maxBytes &&
      this.entries.size > 0
    ) {
      this.evictLRU();
    }

    const cacheControl = options.cacheControl ?? 'public, max-age=3600';
    const record = this.journal.appendValue({
      key,
      etag:
        options.etag ??
        `W/"${data.length.toString(16)}-${lastModified.toString(16)}"`,
      lastModified,
      cacheControl,
      varyKey: options.varyKey,
      contentType,
      body: data,
      observedAt: options.observedAt,
      source: options.source ?? 'manual',
    });

    const entry: CacheEntry = {
      data,
      contentType,
      etag: record.head.etag,
      lastModified,
      cacheControl,
      varyKey: record.head.varyKey,
      bodyDigest: record.head.bodyDigest,
      communityRecordId: record.recordId,
      size: data.length,
      accessedAt: Date.now(),
      servedOk: 0,
      servedErr: 0,
    };

    this.entries.set(key, entry);
    this.currentBytes += data.length;
  }

  /**
   * Invalidate a specific key.
   */
  invalidate(key: string): void {
    this.evictKey(key);
    this.journal.appendInvalidate({
      key,
      reason: 'manual',
      source: 'manual',
    });
  }

  recordFailure(
    key: string,
    failure: CommunityCacheFailureKind,
    options: FileCacheFailureOptions = {}
  ): void {
    this.journal.appendFailure({
      key,
      failure,
      detail: options.detail,
      observedAt: options.observedAt,
      source: options.source ?? 'manual',
    });
  }

  getHead(key: string): CommunityCacheHead | null {
    return this.journal.getHead(key);
  }

  history(key: string): readonly CommunityCacheRecord[] {
    return this.journal.history(key);
  }

  /**
   * Clear all entries.
   */
  clear(): void {
    this.entries.clear();
    this.currentBytes = 0;
    this.journal.clear();
  }

  /** Current cache stats */
  get stats() {
    return {
      entries: this.entries.size,
      bytes: this.currentBytes,
      maxBytes: this.maxBytes,
      utilization: this.currentBytes / this.maxBytes,
      journal: this.journal.stats,
    };
  }

  private evictKey(key: string): void {
    const existing = this.entries.get(key);
    if (existing ) {
      this.currentBytes -= existing.size;
      this.entries.delete(key);
    }
  }

  /**
   * Record that a cache entry was served. Tracks success/error for
   * God Formula quality scoring: w = R - min(v, R) + 1.
   *
   * Call this after serving a cached response so the eviction policy
   * can learn which entries produce errors (low quality) vs which
   * serve cleanly (high quality).
   */
  recordServe(key: string, success: boolean): void {
    const entry = this.entries.get(key);
    if (!entry) return;
    if (success ) {
      entry.servedOk++;
    } else {
      entry.servedErr++;
    }
  }

  private evictLRU(): void {
    // R1 rotation: O(1) eviction via Map iteration order.
    // Map preserves insertion order, and get() re-inserts on access (LRU touch).
    // The oldest (least recently used) entry is always first in iteration.
    //
    // Quality-aware tiebreaker: scan the first few entries (up to 8) and
    // evict the one with lowest God Formula quality. This gives quality-aware
    // eviction without O(n) full scan. For most caches, the LRU candidate
    // maps to the worst quality (rarely accessed = rarely successful = low quality).
    const SCAN_LIMIT = 8;
    let worstKey: string | undefined;
    let worstQuality = Infinity;
    let scanned = 0;

    for (const [key ,  entry] of this.entries) {
      if (scanned >= SCAN_LIMIT) break;
      const q = cacheQuality(entry);
      if (q < worstQuality ) {
        worstQuality = q;
        worstKey = key;
      }
      scanned++;
    }

    if (worstKey !== undefined ) {
      this.evictKey(worstKey);
    }
  }
}
