import { p256 } from '@noble/curves/nist.js';

export interface UcanCapability {
  can: string;
  with: string;
  constraints?: Record<string, unknown>;
}

export interface UcanHeader {
  alg: 'ES256';
  typ: 'UCAN';
  ucv: '0.10.0';
  kid?: string;
}

export interface UcanPayload {
  iss: string;
  aud: string;
  exp: number;
  iat: number;
  att: UcanCapability[];
  nbf?: number;
  nonce?: string;
  jti?: string;
  prf?: string[];
  fct?: Record<string, unknown>;
}

export interface IssuedUcanToken {
  token: string;
  header: UcanHeader;
  payload: UcanPayload;
}

export interface VerifyUcanResult {
  valid: boolean;
  header?: UcanHeader;
  payload?: UcanPayload;
  error?: string;
}

export interface VerifyUcanOptions {
  token: string;
  issuerPublicKeyJwk: JsonWebKey;
  expectedIssuerDid?: string;
  expectedAudience?: string;
  requiredCapabilities?: UcanCapability[];
  revokedTokenHashes?: ReadonlyArray<string> | ReadonlySet<string>;
  revokedIssuerDids?: ReadonlyArray<string> | ReadonlySet<string>;
  revokedDevices?: ReadonlyArray<DeviceRevocationRecord>;
  nowMs?: number;
  clockSkewSeconds?: number;
}

export interface DeviceIdentity {
  provider: string;
  providerId: string;
}

export interface DeviceRevocationRecord extends DeviceIdentity {
  revocationId: string;
  revokedAtMs: number;
  revokedByDid?: string;
  reason?: string;
  tokenHash?: string;
}

export interface CreateDeviceRevocationOptions extends DeviceIdentity {
  revokedAtMs?: number;
  revokedByDid?: string;
  reason?: string;
  tokenHash?: string;
}

export interface DeterministicIssuer {
  did: string;
  kid: string;
  privateKeyJwk: JsonWebKey;
  publicKeyJwk: JsonWebKey;
}

export interface IssueUcanOptions {
  issuerDid: string;
  audience: string;
  privateKeyJwk: JsonWebKey;
  capabilities: UcanCapability[];
  expirationSeconds: number;
  notBeforeSeconds?: number;
  facts?: Record<string, unknown>;
  proofs?: string[];
  nonce?: string;
  nowMs?: number;
  kid?: string;
}

export interface ZkCommitment {
  algorithm: 'SHA-256';
  context: string;
  salt: string;
  commitment: string;
}

export interface CreateZkCommitmentOptions {
  subject: string;
  pepper: string;
  context?: string;
  salt?: string;
}

const DEFAULT_UCAN_VERSION = '0.10.0' as const;
const DEFAULT_CLOCK_SKEW_SECONDS = 30;
const P256_ORDER =
  0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551n;

function bytesToBase64Url(bytes: Uint8Array): string {
  let binary = '';
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }

  return btoa(binary)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function base64UrlToBytes(value: string): Uint8Array | null {
  const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
  const remainder = normalized.length % 4;
  const padded =
    normalized + (remainder === 0 ? '' : '='.repeat(4 - remainder));

  try {
    const binary = atob(padded);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) {
      bytes[index] = binary.charCodeAt(index);
    }
    return bytes;
  } catch {
    return null;
  }
}

function toArrayBuffer(view: Uint8Array): ArrayBuffer {
  if (
    view.buffer instanceof ArrayBuffer &&
    view.byteOffset === 0 &&
    view.byteLength === view.buffer.byteLength
  ) {
    return view.buffer;
  }

  return view.slice().buffer;
}

function encodeJsonToBase64Url(value: unknown): string {
  return bytesToBase64Url(new TextEncoder().encode(JSON.stringify(value)));
}

function decodeJsonFromBase64Url<T>(value: string): T | null {
  const decoded = base64UrlToBytes(value);
  if (!decoded) {
    return null;
  }

  try {
    return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(decoded)) as T;
  } catch {
    return null;
  }
}

function randomHex(bytes = 16): string {
  return Array.from(crypto.getRandomValues(new Uint8Array(bytes)))
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('');
}

function bytesToBigInt(bytes: Uint8Array): bigint {
  let value = 0n;
  for (const byte of bytes) {
    value = (value << 8n) | BigInt(byte);
  }
  return value;
}

function bigIntToFixedBytes(value: bigint, length: number): Uint8Array {
  const output = new Uint8Array(length);
  let remaining = value;

  for (let index = length - 1; index >= 0; index -= 1) {
    output[index] = Number(remaining & 0xffn);
    remaining >>= 8n;
  }

  return output;
}

function canonicalizeJsonObject(value: Record<string, unknown>): string {
  const sortedEntries = Object.entries(value).sort(([left], [right]) =>
    left.localeCompare(right)
  );

  const normalized: Record<string, unknown> = {};
  for (const [key, entryValue] of sortedEntries) {
    normalized[key] = entryValue;
  }

  return JSON.stringify(normalized);
}

async function sha256Bytes(value: string): Promise<Uint8Array> {
  const digest = await crypto.subtle.digest(
    'SHA-256',
    new TextEncoder().encode(value)
  );
  return new Uint8Array(digest);
}

async function computeKeyId(publicKeyJwk: JsonWebKey): Promise<string> {
  const canonical = canonicalizeJsonObject(
    publicKeyJwk as Record<string, unknown>
  );
  const digest = await sha256Bytes(canonical);
  return bytesToBase64Url(digest.slice(0, 16));
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function normalizeProvider(provider: string): string {
  const normalized = provider.trim().toLowerCase();
  if (!normalized) {
    throw new Error('Provider is required for device identity');
  }
  return normalized;
}

function normalizeProviderId(providerId: string): string {
  const normalized = providerId.trim();
  if (!normalized) {
    throw new Error('Provider ID is required for device identity');
  }
  return normalized;
}

function hasStringValue(
  collection: ReadonlyArray<string> | ReadonlySet<string> | undefined,
  value: string
): boolean {
  if (!collection) {
    return false;
  }

  for (const entry of collection) {
    if (entry === value) {
      return true;
    }
  }

  return false;
}

function extractDeviceIdentityFromFacts(
  facts: Record<string, unknown> | undefined
): DeviceIdentity | null {
  if (!facts) {
    return null;
  }

  const directProvider = facts.provider;
  const directProviderId = facts.providerId;
  if (
    typeof directProvider === 'string' &&
    typeof directProviderId === 'string'
  ) {
    return {
      provider: directProvider,
      providerId: directProviderId,
    };
  }

  const altProvider = facts.deviceProvider;
  const altProviderId = facts.deviceId;
  if (typeof altProvider === 'string' && typeof altProviderId === 'string') {
    return {
      provider: altProvider,
      providerId: altProviderId,
    };
  }

  const nestedDevice = facts.device;
  if (isRecord(nestedDevice)) {
    const nestedProvider = nestedDevice.provider;
    const nestedProviderId =
      typeof nestedDevice.providerId === 'string'
        ? nestedDevice.providerId
        : nestedDevice.id;

    if (
      typeof nestedProvider === 'string' &&
      typeof nestedProviderId === 'string'
    ) {
      return {
        provider: nestedProvider,
        providerId: nestedProviderId,
      };
    }
  }

  return null;
}

export function createDeviceRevocationId(
  provider: string,
  providerId: string
): string {
  return `${normalizeProvider(provider)}:${normalizeProviderId(providerId)}`;
}

export function createDeviceRevocationRecord(
  options: CreateDeviceRevocationOptions
): DeviceRevocationRecord {
  return {
    provider: normalizeProvider(options.provider),
    providerId: normalizeProviderId(options.providerId),
    revocationId: createDeviceRevocationId(
      options.provider,
      options.providerId
    ),
    revokedAtMs: Math.trunc(options.revokedAtMs ?? Date.now()),
    ...(options.revokedByDid ? { revokedByDid: options.revokedByDid } : {}),
    ...(options.reason ? { reason: options.reason } : {}),
    ...(options.tokenHash ? { tokenHash: options.tokenHash } : {}),
  };
}

export function revokeDevice(
  existing: ReadonlyArray<DeviceRevocationRecord>,
  options: CreateDeviceRevocationOptions
): {
  updated: boolean;
  record: DeviceRevocationRecord;
  revocations: DeviceRevocationRecord[];
} {
  const record = createDeviceRevocationRecord(options);
  const existingIndex = existing.findIndex(
    (entry) => entry.revocationId === record.revocationId
  );

  if (existingIndex === -1) {
    return {
      updated: true,
      record,
      revocations: [...existing, record],
    };
  }

  const current = existing[existingIndex];
  const alreadySame =
    current.provider === record.provider &&
    current.providerId === record.providerId &&
    current.revokedByDid === record.revokedByDid &&
    current.reason === record.reason &&
    current.tokenHash === record.tokenHash;

  if (alreadySame) {
    return {
      updated: false,
      record: current,
      revocations: [...existing],
    };
  }

  const merged: DeviceRevocationRecord = {
    ...current,
    ...record,
    revokedAtMs: Math.max(current.revokedAtMs, record.revokedAtMs),
  };

  const revocations = [...existing];
  revocations[existingIndex] = merged;

  return {
    updated: true,
    record: merged,
    revocations,
  };
}

export function isDeviceRevoked(
  revocations: ReadonlyArray<DeviceRevocationRecord>,
  provider: string,
  providerId: string
): boolean {
  const revocationId = createDeviceRevocationId(provider, providerId);
  return revocations.some((entry) => entry.revocationId === revocationId);
}

export async function createTokenRevocationHash(
  token: string
): Promise<string> {
  const digest = await sha256Bytes(token);
  return bytesToBase64Url(digest);
}

function isUcanHeader(value: unknown): value is UcanHeader {
  if (!isRecord(value)) {
    return false;
  }

  return (
    value.alg === 'ES256' &&
    value.typ === 'UCAN' &&
    value.ucv === DEFAULT_UCAN_VERSION
  );
}

function isUcanPayload(value: unknown): value is UcanPayload {
  if (!isRecord(value)) {
    return false;
  }

  return (
    typeof value.iss === 'string' &&
    typeof value.aud === 'string' &&
    typeof value.exp === 'number' &&
    typeof value.iat === 'number' &&
    Array.isArray(value.att)
  );
}

function actionMatches(granted: string, required: string): boolean {
  if (granted === '*' || granted === required) {
    return true;
  }

  if (granted.endsWith('/*')) {
    return required.startsWith(granted.slice(0, -1));
  }

  return false;
}

function resourceMatches(granted: string, required: string): boolean {
  if (granted === '*' || granted === required) {
    return true;
  }

  if (granted.endsWith('*')) {
    return required.startsWith(granted.slice(0, -1));
  }

  return false;
}

function isPlainObjectRecord(value: unknown): value is Record<string, unknown> {
  if (!isRecord(value)) {
    return false;
  }

  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function constraintValueMatches(granted: unknown, required: unknown): boolean {
  if (Array.isArray(required)) {
    if (!Array.isArray(granted) || granted.length < required.length) {
      return false;
    }

    return required.every((requiredItem, index) =>
      constraintValueMatches(granted[index], requiredItem)
    );
  }

  if (isPlainObjectRecord(required)) {
    if (!isPlainObjectRecord(granted)) {
      return false;
    }

    return Object.entries(required).every(([key, requiredValue]) =>
      constraintValueMatches(granted[key], requiredValue)
    );
  }

  return Object.is(granted, required);
}

function constraintsMatch(
  granted: Record<string, unknown> | undefined,
  required: Record<string, unknown> | undefined
): boolean {
  if (!required) {
    return true;
  }
  if (!granted) {
    return false;
  }

  return Object.entries(required).every(([key, requiredValue]) =>
    constraintValueMatches(granted[key], requiredValue)
  );
}

function capabilitySatisfies(
  granted: UcanCapability,
  required: UcanCapability
): boolean {
  return (
    actionMatches(granted.can, required.can) &&
    resourceMatches(granted.with, required.with) &&
    constraintsMatch(granted.constraints, required.constraints)
  );
}

function capabilitiesCover(
  granted: UcanCapability[],
  required: UcanCapability[]
): boolean {
  return required.every((requiredCapability) =>
    granted.some((grantedCapability) =>
      capabilitySatisfies(grantedCapability, requiredCapability)
    )
  );
}

export function createTodoGlobalSpaceResource(): string {
  return 'todo:space:global';
}

export function createTodoGlobalSpaceCapabilities(
  permission: 'read' | 'write' | 'read_write' = 'read_write'
): UcanCapability[] {
  const resource = createTodoGlobalSpaceResource();

  if (permission === 'read') {
    return [
      {
        can: 'todo/space/read',
        with: resource,
      },
    ];
  }

  if (permission === 'write') {
    return [
      {
        can: 'todo/space/write',
        with: resource,
      },
    ];
  }

  return [
    {
      can: 'todo/space/read',
      with: resource,
    },
    {
      can: 'todo/space/write',
      with: resource,
    },
  ];
}

export function createTodoPersonalSpaceCapabilities(
  ownerId: string
): UcanCapability[] {
  return [
    {
      can: 'todo/space/read',
      with: `todo:space:personal:${ownerId}`,
    },
    {
      can: 'todo/space/write',
      with: `todo:space:personal:${ownerId}`,
    },
  ];
}

export function createTodoPersonalSpaceResource(ownerId: string): string {
  return `todo:space:personal:${ownerId}`;
}

export async function deriveDeterministicP256IssuerFromSecret(
  secret: string,
  options?: {
    context?: string;
    issuerDid?: string;
  }
): Promise<DeterministicIssuer> {
  const trimmedSecret = secret.trim();
  if (!trimmedSecret) {
    throw new Error('Secret is required to derive a deterministic issuer key');
  }

  const context = options?.context?.trim() || 'affectively-auth/ucan';
  const seed = await sha256Bytes(`${context}:${trimmedSecret}`);

  const scalar = (bytesToBigInt(seed) % (P256_ORDER - 1n)) + 1n;
  const privateKeyBytes = bigIntToFixedBytes(scalar, 32);
  const publicKeyBytes = p256.getPublicKey(privateKeyBytes, false);

  const x = publicKeyBytes.slice(1, 33);
  const y = publicKeyBytes.slice(33, 65);

  const publicKeyJwk: JsonWebKey = {
    kty: 'EC',
    crv: 'P-256',
    x: bytesToBase64Url(x),
    y: bytesToBase64Url(y),
    ext: true,
    key_ops: ['verify'],
  };

  const privateKeyJwk: JsonWebKey = {
    ...publicKeyJwk,
    d: bytesToBase64Url(privateKeyBytes),
    key_ops: ['sign'],
  };

  const kid = await computeKeyId(publicKeyJwk);
  const did = options?.issuerDid?.trim() || `did:key:z${kid}`;

  return {
    did,
    kid,
    privateKeyJwk,
    publicKeyJwk,
  };
}

export async function issueUcanToken(
  options: IssueUcanOptions
): Promise<IssuedUcanToken> {
  const nowSeconds = Math.floor((options.nowMs ?? Date.now()) / 1000);
  const expiration = Math.max(1, Math.trunc(options.expirationSeconds));

  const payload: UcanPayload = {
    iss: options.issuerDid,
    aud: options.audience,
    exp: nowSeconds + expiration,
    iat: nowSeconds,
    att: options.capabilities,
    nonce: options.nonce ?? randomHex(16),
    jti: randomHex(16),
    ...(typeof options.notBeforeSeconds === 'number'
      ? { nbf: nowSeconds + Math.trunc(options.notBeforeSeconds) }
      : {}),
    ...(options.proofs && options.proofs.length > 0
      ? { prf: options.proofs }
      : {}),
    ...(options.facts ? { fct: options.facts } : {}),
  };

  const header: UcanHeader = {
    alg: 'ES256',
    typ: 'UCAN',
    ucv: DEFAULT_UCAN_VERSION,
    ...(options.kid ? { kid: options.kid } : {}),
  };

  const encodedHeader = encodeJsonToBase64Url(header);
  const encodedPayload = encodeJsonToBase64Url(payload);
  const signingInput = `${encodedHeader}.${encodedPayload}`;

  const key = await crypto.subtle.importKey(
    'jwk',
    options.privateKeyJwk,
    {
      name: 'ECDSA',
      namedCurve: 'P-256',
    },
    false,
    ['sign']
  );

  const signature = await crypto.subtle.sign(
    {
      name: 'ECDSA',
      hash: 'SHA-256',
    },
    key,
    new TextEncoder().encode(signingInput)
  );

  const token = `${signingInput}.${bytesToBase64Url(
    new Uint8Array(signature)
  )}`;

  return {
    token,
    header,
    payload,
  };
}

export async function verifyUcanToken(
  options: VerifyUcanOptions
): Promise<VerifyUcanResult> {
  const parts = options.token.split('.');
  if (parts.length !== 3) {
    return {
      valid: false,
      error: 'invalid_format',
    };
  }

  const [encodedHeader, encodedPayload, encodedSignature] = parts;
  const header = decodeJsonFromBase64Url<UcanHeader>(encodedHeader);
  const payload = decodeJsonFromBase64Url<UcanPayload>(encodedPayload);
  const signature = base64UrlToBytes(encodedSignature);

  if (!header || !isUcanHeader(header)) {
    return {
      valid: false,
      error: 'invalid_header',
    };
  }

  if (!payload || !isUcanPayload(payload)) {
    return {
      valid: false,
      error: 'invalid_payload',
    };
  }

  if (!signature) {
    return {
      valid: false,
      error: 'invalid_signature_encoding',
    };
  }

  if (options.revokedTokenHashes) {
    const tokenHash = await createTokenRevocationHash(options.token);
    if (hasStringValue(options.revokedTokenHashes, tokenHash)) {
      return {
        valid: false,
        error: 'revoked_token',
        header,
        payload,
      };
    }
  }

  if (
    options.revokedIssuerDids &&
    hasStringValue(options.revokedIssuerDids, payload.iss)
  ) {
    return {
      valid: false,
      error: 'revoked_issuer',
      header,
      payload,
    };
  }

  if (options.revokedDevices && options.revokedDevices.length > 0) {
    const deviceIdentity = extractDeviceIdentityFromFacts(payload.fct);
    if (
      deviceIdentity &&
      isDeviceRevoked(
        options.revokedDevices,
        deviceIdentity.provider,
        deviceIdentity.providerId
      )
    ) {
      return {
        valid: false,
        error: 'revoked_device',
        header,
        payload,
      };
    }
  }

  const nowSeconds = Math.floor((options.nowMs ?? Date.now()) / 1000);
  const clockSkew = Math.max(
    0,
    Math.trunc(options.clockSkewSeconds ?? DEFAULT_CLOCK_SKEW_SECONDS)
  );

  if (payload.exp <= nowSeconds - clockSkew) {
    return {
      valid: false,
      error: 'expired',
      header,
      payload,
    };
  }

  if (typeof payload.nbf === 'number' && payload.nbf > nowSeconds + clockSkew) {
    return {
      valid: false,
      error: 'not_before',
      header,
      payload,
    };
  }

  if (options.expectedIssuerDid && payload.iss !== options.expectedIssuerDid) {
    return {
      valid: false,
      error: 'issuer_mismatch',
      header,
      payload,
    };
  }

  if (options.expectedAudience && payload.aud !== options.expectedAudience) {
    return {
      valid: false,
      error: 'audience_mismatch',
      header,
      payload,
    };
  }

  const key = await crypto.subtle.importKey(
    'jwk',
    options.issuerPublicKeyJwk,
    {
      name: 'ECDSA',
      namedCurve: 'P-256',
    },
    false,
    ['verify']
  );

  const isSignatureValid = await crypto.subtle.verify(
    {
      name: 'ECDSA',
      hash: 'SHA-256',
    },
    key,
    toArrayBuffer(signature),
    toArrayBuffer(
      new TextEncoder().encode(`${encodedHeader}.${encodedPayload}`)
    )
  );

  if (!isSignatureValid) {
    return {
      valid: false,
      error: 'invalid_signature',
      header,
      payload,
    };
  }

  if (
    options.requiredCapabilities &&
    options.requiredCapabilities.length > 0 &&
    !capabilitiesCover(payload.att, options.requiredCapabilities)
  ) {
    return {
      valid: false,
      error: 'capability_mismatch',
      header,
      payload,
    };
  }

  return {
    valid: true,
    header,
    payload,
  };
}

export async function createZkCommitment(
  options: CreateZkCommitmentOptions
): Promise<ZkCommitment> {
  const context = options.context?.trim() || 'affectively/zk-commitment';
  const salt =
    options.salt?.trim() ||
    bytesToBase64Url(crypto.getRandomValues(new Uint8Array(16)));
  const commitmentBytes = await sha256Bytes(
    `${context}:${options.subject}:${salt}:${options.pepper}`
  );

  return {
    algorithm: 'SHA-256',
    context,
    salt,
    commitment: bytesToBase64Url(commitmentBytes),
  };
}

export async function verifyZkCommitment(
  commitment: ZkCommitment,
  options: {
    subject: string;
    pepper: string;
  }
): Promise<boolean> {
  const recomputed = await createZkCommitment({
    subject: options.subject,
    pepper: options.pepper,
    context: commitment.context,
    salt: commitment.salt,
  });

  return recomputed.commitment === commitment.commitment;
}
