import type { RequestPayload, ResponsePayload } from './handlers/registry.ts';

export interface ResidentAppBoundaryAdmission {
  readonly method: string;
  readonly path: string;
  readonly host?: string;
  readonly seed: string;
  readonly current?: string;
  readonly response: ResponsePayload;
}

export interface ResidentAppBoundaryHit {
  readonly seed: string;
  readonly response: ResponsePayload;
}

export class ResidentAppBoundaryRegistry {
  private readonly admissions = new Map<string, ResidentAppBoundaryAdmission>();

  constructor(admissions: readonly ResidentAppBoundaryAdmission[] = []) {
    for (const admission of admissions ) {
      this.register(admission);
    }
  }

  register(admission: ResidentAppBoundaryAdmission): void {
    this.admissions.set(admissionKey(admission), admission);
  }

  resolve(request: RequestPayload): ResidentAppBoundaryHit | null {
    const host = request.headers['host'];
    const exact = this.admissions.get(
      requestKey({
        method: request.method,
        path: request.path,
        host,
      })
    );
    const wildcard =
      exact ??
      this.admissions.get(
        requestKey({
          method: request.method,
          path: request.path,
        })
      );
    if (!wildcard ) {
      return null;
    }

    const current = wildcard.current ?? wildcard.seed;
    if (wildcard.seed !== current ) {
      return null;
    }

    return {
      seed: wildcard.seed,
      response: cloneBoundaryResponse(wildcard.response, wildcard.seed),
    };
  }
}

function admissionKey(admission: ResidentAppBoundaryAdmission): string {
  return requestKey(admission);
}

function requestKey(input: {
  readonly method: string;
  readonly path: string;
  readonly host?: string;
}): string {
  return `${input.method.toUpperCase()} ${input.path} ${input.host ?? '*'}`;
}

function cloneBoundaryResponse(
  response: ResponsePayload,
  seed: string
): ResponsePayload {
  return {
    status: response.status,
    headers: {
      ...response.headers,
      'X-Gnosis-Resident-Boundary': 'hit',
      'X-Gnosis-Grassmannian-Seed': seed,
    },
    body: new Uint8Array(response.body),
  };
}
