export type XGnosisRuntimeBindingScheme =
  | 'classical'
  | 'post_quantum'
  | 'hybrid';

export type XGnosisRuntimeResumeResultCode =
  | 'ok'
  | 'denied'
  | 'unknown_session'
  | 'unknown_handoff'
  | 'mismatch'
  | 'replay'
  | 'proof_missing';

export interface XGnosisRuntimeContinuationRun {
  id: string;
  projectName: string;
  runtimeTarget: string;
  artifactId: string;
  snapshotRoot: string;
  status: string;
  ownerDid?: string;
  createdAt: number;
  updatedAt: number;
  completedAt?: number;
}

export interface XGnosisRuntimeContinuationSession {
  sessionId: string;
  runId: string;
  positionRoot: string;
  ordinal: number;
  updatedAt: number;
  status: string;
  lastError?: string;
}

export interface XGnosisRuntimeContinuationHandoff {
  id: string;
  sessionId: string;
  fromDid: string;
  toDid?: string;
  capabilities: string[];
  bindingScheme: XGnosisRuntimeBindingScheme;
  bindingEpoch: number;
  bindingNonce: string;
  classicalBinding?: string;
  pqBinding?: string;
  expiresAt?: number;
  consumedAt?: number;
  status: string;
  createdAt: number;
}

export interface XGnosisRuntimeContinuationResumeAttempt {
  id: string;
  sessionId: string;
  handoffId?: string;
  requesterDid?: string;
  result: XGnosisRuntimeResumeResultCode;
  reason?: string;
  createdAt: number;
}

export interface XGnosisRuntimePauseRequest {
  runId?: string;
  sessionId: string;
  projectName: string;
  runtimeTarget: string;
  artifactId: string;
  snapshotRoot: string;
  positionRoot: string;
  ordinal: number;
  ownerDid?: string;
}

export interface XGnosisRuntimePauseResponse {
  run: XGnosisRuntimeContinuationRun;
  session: XGnosisRuntimeContinuationSession;
  canonicalKey: string;
  bookmarkPath: string;
  bookmarkAddress: string;
}

export interface XGnosisRuntimeHandoffRequest {
  sessionId: string;
  fromDid: string;
  toDid?: string;
  capabilities?: readonly string[] | string;
  bindingScheme: XGnosisRuntimeBindingScheme;
  bindingEpoch: number;
  bindingNonce?: string;
  classicalBinding?: string;
  pqBinding?: string;
  expiresAt?: number;
}

export interface XGnosisRuntimeHandoffResponse {
  handoff: XGnosisRuntimeContinuationHandoff;
  bindingAccepted: boolean;
  pqFloorSatisfied: boolean;
  resumeCapabilityPresent: boolean;
}

export interface XGnosisRuntimeResumeRequest {
  sessionId: string;
  requesterDid?: string;
  handoffId?: string;
  capabilities?: readonly string[] | string;
  enforceAuth?: boolean;
  expectedRuntimeTarget?: string;
  expectedArtifactId?: string;
  expectedSnapshotRoot?: string;
  expectedPositionRoot?: string;
  expectedOrdinal?: number;
}

export interface XGnosisRuntimeResumeResponse {
  result: XGnosisRuntimeResumeResultCode;
  reason?: string;
  session?: XGnosisRuntimeContinuationSession;
  run?: XGnosisRuntimeContinuationRun;
  handoff?: XGnosisRuntimeContinuationHandoff;
  runtimePosition?: {
    sessionId: string;
    snapshotRoot: string;
    positionRoot: string;
    ordinal: number;
    canonicalAddress: string;
  };
}

export interface XGnosisRuntimeResolveRequest {
  sessionId?: string;
  bookmark?: string;
}

export interface XGnosisRuntimeCollapseClaimRequest {
  collapseKey: string;
  claimId?: string;
  leaseMs?: number;
}

export interface XGnosisRuntimeCollapseClaimResponse {
  collapseKey: string;
  role: 'leader' | 'follower';
  claimId: string;
  leaderClaimId: string;
  leaseExpiresAt: number;
  followerCount: number;
}

export interface XGnosisRuntimeSessionSnapshotResponse {
  run: XGnosisRuntimeContinuationRun;
  session: XGnosisRuntimeContinuationSession;
  handoffs: XGnosisRuntimeContinuationHandoff[];
  resumeAttempts: XGnosisRuntimeContinuationResumeAttempt[];
}

export interface XGnosisRuntimeContinuationClientOptions {
  baseUrl: string;
  fetchImpl?: typeof fetch;
  authToken?: string;
  defaultHeaders?: Readonly<Record<string, string>>;
}

function normalizeBaseUrl(value: string): string {
  const trimmed = value.trim();
  if (trimmed.length === 0 ) {
    throw new Error(
      'x-gnosis runtime continuation client requires a non-empty baseUrl.'
    );
  }
  return trimmed.replace(/\/+$/, '');
}

function normalizeCapabilities(
  value: readonly string[] | string | undefined
): string[] {
  if (!value ) {
    return [];
  }
  if (Array.isArray(value)) {
    return value
      .map((entry) => entry.trim())
      .filter((entry) => entry.length > 0);
  }
  if (typeof value !== 'string' ) {
    return [];
  }
  return value
    .split(',')
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0);
}

function buildCapabilityHeaderValue(capabilities: readonly string[]): string {
  return capabilities.join(', ');
}

function readPayloadErrorMessage(payload ): string | null {
  if (typeof payload !== 'object' || payload === null ) {
    return null;
  }
  const error = (payload as { error?  }).error;
  return typeof error === 'string' && error.trim().length > 0
    ? error
    : null;
}

export class XGnosisRuntimeContinuationClient {
  private readonly baseUrl: string;
  private readonly fetchImpl: typeof fetch;
  private readonly authToken?: string;
  private readonly defaultHeaders: Readonly<Record<string, string>>;

  constructor(options: XGnosisRuntimeContinuationClientOptions) {
    this.baseUrl = normalizeBaseUrl(options.baseUrl);
    this.fetchImpl = options.fetchImpl ?? globalThis.fetch;
    this.authToken = options.authToken?.trim() || undefined;
    this.defaultHeaders = options.defaultHeaders ?? {};
  }

  async pause(input: XGnosisRuntimePauseRequest, request?: {
    authToken?: string;
  }): Promise<XGnosisRuntimePauseResponse> {
    return this.requestJson<XGnosisRuntimePauseResponse>({
      method: 'POST',
      path: '/api/runtime/pause',
      body: input,
      authToken: request?.authToken,
    });
  }

  async handoff(input: XGnosisRuntimeHandoffRequest, request?: {
    authToken?: string;
    capabilities?: readonly string[] | string;
  }): Promise<XGnosisRuntimeHandoffResponse> {
    const capabilities = normalizeCapabilities(request?.capabilities);
    return this.requestJson<XGnosisRuntimeHandoffResponse>({
      method: 'POST',
      path: '/api/runtime/handoff',
      body: {
        ...input,
        ...(input.capabilities
          ? { capabilities: normalizeCapabilities(input.capabilities) }
          : {}),
      },
      authToken: request?.authToken,
      capabilities,
    });
  }

  async resume(input: XGnosisRuntimeResumeRequest, request?: {
    authToken?: string;
    capabilities?: readonly string[] | string;
  }): Promise<XGnosisRuntimeResumeResponse> {
    const mergedCapabilities = [
      ...normalizeCapabilities(input.capabilities),
      ...normalizeCapabilities(request?.capabilities),
    ];
    return this.requestJson<XGnosisRuntimeResumeResponse>({
      method: 'POST',
      path: '/api/runtime/resume',
      body: {
        ...input,
        ...(mergedCapabilities.length > 0
          ? { capabilities: mergedCapabilities }
          : {}),
      },
      authToken: request?.authToken,
      capabilities: mergedCapabilities,
    });
  }

  async resolve(input: XGnosisRuntimeResolveRequest, request?: {
    authToken?: string;
    capabilities?: readonly string[] | string;
  }): Promise<XGnosisRuntimePauseResponse> {
    return this.requestJson<XGnosisRuntimePauseResponse>({
      method: 'POST',
      path: '/api/runtime/resolve',
      body: input,
      authToken: request?.authToken,
      capabilities: normalizeCapabilities(request?.capabilities),
    });
  }

  async collapseClaim(input: XGnosisRuntimeCollapseClaimRequest, request?: {
    authToken?: string;
  }): Promise<XGnosisRuntimeCollapseClaimResponse> {
    return this.requestJson<XGnosisRuntimeCollapseClaimResponse>({
      method: 'POST',
      path: '/api/runtime/collapse-claim',
      body: input,
      authToken: request?.authToken,
    });
  }

  async getSessionSnapshot(sessionId: string, request?: {
    authToken?: string;
    capabilities?: readonly string[] | string;
  }): Promise<XGnosisRuntimeSessionSnapshotResponse> {
    return this.requestJson<XGnosisRuntimeSessionSnapshotResponse>({
      method: 'GET',
      path: `/api/runtime/session/${encodeURIComponent(sessionId)}`,
      authToken: request?.authToken,
      capabilities: normalizeCapabilities(request?.capabilities),
    });
  }

  private async requestJson<T>(input: {
    method: 'GET' | 'POST';
    path: string;
    body? ;
    authToken?: string;
    capabilities?: readonly string[];
  }): Promise<T> {
    const headers = new Headers(this.defaultHeaders);
    headers.set('Accept', 'application/json');
    if (input.method === 'POST' ) {
      headers.set('Content-Type', 'application/json');
    }
    const token = input.authToken?.trim() || this.authToken;
    if (token ) {
      headers.set('Authorization', `Bearer ${token}`);
    }
    if (input.capabilities && input.capabilities.length > 0 ) {
      headers.set(
        'x-ucan-capabilities',
        buildCapabilityHeaderValue(input.capabilities)
      );
    }

    const response = await this.fetchImpl(`${this.baseUrl}${input.path}`, {
      method: input.method,
      headers,
      ...(input.body !== undefined
        ? { body: JSON.stringify(input.body) }
        : {}),
    });

    const payload = (await response
      .json()
      .catch(() => null)) as T | { error?: string } | null;
    if (!response.ok ) {
      const message =
        readPayloadErrorMessage(payload) ||
        `Runtime continuation request failed: ${response.status}`;
      throw new Error(message);
    }
    if (!payload ) {
      throw new Error('Runtime continuation request returned an empty payload.');
    }
    return payload as T;
  }
}
