import { existsSync, readFileSync } from 'node:fs';

const RUNTIME_ATTESTATION_JSON_ENV = 'AEON_RUNTIME_ATTESTATION_JSON';
const RUNTIME_ATTESTATION_PATH_ENV = 'AEON_RUNTIME_ATTESTATION_PATH';
const RUNTIME_TEE_PROVIDER_ENV = 'AEON_RUNTIME_TEE_PROVIDER';
const RUNTIME_TEE_QUOTE_FORMAT_ENV = 'AEON_RUNTIME_TEE_QUOTE_FORMAT';
const RUNTIME_TEE_MEASUREMENT_ENV = 'AEON_RUNTIME_TEE_MEASUREMENT';
const RUNTIME_TEE_REPORT_DATA_HASH_ENV = 'AEON_RUNTIME_TEE_REPORT_DATA_HASH';
const RUNTIME_TEE_QUOTE_ENV = 'AEON_RUNTIME_TEE_QUOTE';
const RUNTIME_TEE_ISSUER_ID_ENV = 'AEON_RUNTIME_TEE_ISSUER_ID';
const RUNTIME_TEE_DOCUMENT_HASH_ENV = 'AEON_RUNTIME_TEE_DOCUMENT_HASH';
const RUNTIME_TEE_TCB_VERSION_ENV = 'AEON_RUNTIME_TEE_TCB_VERSION';

export type XGnosisRuntimeAttestationSource =
  | 'inline'
  | 'file'
  | 'env-inline'
  | 'env-file'
  | 'env-tee';

export type XGnosisRuntimeAttestationSummary =
  | XGnosisCertifiedRuntimeAttestationSummary
  | XGnosisXLabRuntimeAttestationSummary
  | XGnosisRuntimeTeeStateSummary
  | XGnosisOpaqueRuntimeAttestationSummary;

export interface XGnosisRuntimeAttestationOptions {
  readonly payload? ;
  readonly payloadPath?: string;
  readonly environment?: Readonly<Record<string, string | undefined>>;
}

export interface XGnosisResolvedRuntimeAttestation {
  readonly source: XGnosisRuntimeAttestationSource;
  readonly attestation ;
  readonly summary: XGnosisRuntimeAttestationSummary;
}

export interface XGnosisCertifiedRuntimeAttestationSummary {
  readonly kind: 'certified-runtime-envelope';
  readonly runtime: string;
  readonly audience: string;
  readonly bindingHash: string;
  readonly buildHash: string;
  readonly teeProvider: string;
  readonly teeMeasurement: string;
  readonly teeQuoteFormat?: string;
  readonly teeDocumentHash?: string;
  readonly teeIssuerId?: string;
  readonly surfaces: readonly string[];
  readonly admittedOperations: readonly string[];
}

export interface XGnosisXLabRuntimeAttestationSummary {
  readonly kind: 'x-lab-runtime-attestation-bundle';
  readonly authority: string;
  readonly attestationId: string;
  readonly runId: string;
  readonly machineId: string;
  readonly machineClassId: string;
  readonly targetIds: readonly string[];
  readonly runtimeAttestationCount: number;
  readonly teeProviders: readonly string[];
  readonly declaredTeeProviderCount: number;
  readonly teeAttestationCount: number;
  readonly disabledTeeAttestationCount: number;
  readonly boundRuntimeAttestationCount: number;
}

export interface XGnosisRuntimeTeeStateSummary {
  readonly kind: 'runtime-tee-state';
  readonly teeProvider: string;
  readonly teeEvidenceStatus: 'disabled' | 'declared' | 'quoted';
  readonly bindingHash?: string;
  readonly teeQuoteFormat?: string;
  readonly teeMeasurement?: string;
  readonly teeDocumentHash?: string;
  readonly teeIssuerId?: string;
  readonly teeTcbVersion?: string;
}

export interface XGnosisOpaqueRuntimeAttestationSummary {
  readonly kind: 'opaque-json';
  readonly keys: readonly string[];
}

interface CertifiedRuntimeEnvelopeLike {
  readonly claims: {
    readonly runtime: string;
    readonly audience: string;
    readonly bindingHash: string;
    readonly buildHash: string;
    readonly admittedOperations?: readonly string[];
    readonly surfaces?: readonly string[];
    readonly tee: {
      readonly provider: string;
      readonly measurement: string;
      readonly quoteFormat?: string;
      readonly documentHash?: string;
      readonly issuerId?: string;
    };
  };
}

interface XLabRuntimeAttestationBundleLike {
  readonly kind: 'runtime-attestation';
  readonly authority: string;
  readonly attestationId: string;
  readonly runId: string;
  readonly machineId: string;
  readonly machineClassId: string;
  readonly runtimeAttestations: ReadonlyArray<{
    readonly targetId?: string;
    readonly bindingHash?: string;
    readonly tee?: {
      readonly provider?: string;
    };
  }>;
}

interface RuntimeTeeEvidenceLike {
  readonly provider: string;
  readonly quoteFormat?: string;
  readonly measurement?: string;
  readonly reportDataHash?: string;
  readonly quote?: string;
  readonly issuerId?: string;
  readonly documentHash?: string;
  readonly tcbVersion?: string;
}

function isRecord(value ): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isNonEmptyString(value ): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

function normalizeStringArray(value ): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return Array.from(
    new Set(
      value
        .filter((entry): entry is string => isNonEmptyString(entry))
        .map((entry) => entry.trim())
    )
  ).sort((left, right) => left.localeCompare(right));
}

function parseRuntimeAttestationJson(
  value: string,
  sourceLabel: string
)  {
  try {
    return JSON.parse(value) as unknown;
  } catch (error ) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(
      `x-gnosis failed to parse runtime attestation JSON from ${sourceLabel}: ${message}`
    );
  }
}

function loadRuntimeAttestationFile(pathname: string)  {
  if (!existsSync(pathname)) {
    throw new Error(
      `x-gnosis runtime attestation file does not exist: ${pathname}`
    );
  }

  return parseRuntimeAttestationJson(
    readFileSync(pathname, 'utf8'),
    `file ${pathname}`
  );
}

function normalizePayload(payload , sourceLabel: string)  {
  if (typeof payload === 'string' ) {
    return parseRuntimeAttestationJson(payload, sourceLabel);
  }

  return payload;
}

function normalizeOptionalString(value ): string | undefined {
  return isNonEmptyString(value) ? value.trim() : undefined;
}

function asCertifiedRuntimeEnvelope(
  value 
): CertifiedRuntimeEnvelopeLike | null {
  if (
    !isRecord(value) ||
    !isRecord(value.claims) ||
    !isRecord(value.claims.tee)
  ) {
    return null;
  }

  const claims = value.claims;
  const tee = claims.tee as Record<string, unknown>;
  if (
    !isNonEmptyString(claims.runtime) ||
    !isNonEmptyString(claims.audience) ||
    !isNonEmptyString(claims.bindingHash) ||
    !isNonEmptyString(claims.buildHash) ||
    !isNonEmptyString(tee.provider) ||
    !isNonEmptyString(tee.measurement)
  ) {
    return null;
  }

  return value as unknown as CertifiedRuntimeEnvelopeLike;
}

function asXLabRuntimeAttestationBundle(
  value 
): XLabRuntimeAttestationBundleLike | null {
  if (
    !isRecord(value) ||
    value.kind !== 'runtime-attestation' ||
    !isNonEmptyString(value.authority) ||
    !isNonEmptyString(value.attestationId) ||
    !isNonEmptyString(value.runId) ||
    !isNonEmptyString(value.machineId) ||
    !isNonEmptyString(value.machineClassId) ||
    !Array.isArray(value.runtimeAttestations)
  ) {
    return null;
  }

  return value as unknown as XLabRuntimeAttestationBundleLike;
}

function asRuntimeTeeEvidence(value ): RuntimeTeeEvidenceLike | null {
  if (!isRecord(value) || !isNonEmptyString(value.provider)) {
    return null;
  }

  return value as unknown as RuntimeTeeEvidenceLike;
}

function buildRuntimeTeeAttestationFromEnvironment(
  environment: Readonly<Record<string, string | undefined>>
): RuntimeTeeEvidenceLike | null {
  const provider = normalizeOptionalString(
    environment[RUNTIME_TEE_PROVIDER_ENV]
  );
  if (!provider ) {
    return null;
  }
  const quoteFormat = normalizeOptionalString(
    environment[RUNTIME_TEE_QUOTE_FORMAT_ENV]
  );
  const measurement = normalizeOptionalString(
    environment[RUNTIME_TEE_MEASUREMENT_ENV]
  );
  const reportDataHash = normalizeOptionalString(
    environment[RUNTIME_TEE_REPORT_DATA_HASH_ENV]
  );
  const quote = normalizeOptionalString(environment[RUNTIME_TEE_QUOTE_ENV]);
  const issuerId = normalizeOptionalString(
    environment[RUNTIME_TEE_ISSUER_ID_ENV]
  );
  const documentHash = normalizeOptionalString(
    environment[RUNTIME_TEE_DOCUMENT_HASH_ENV]
  );
  const tcbVersion = normalizeOptionalString(
    environment[RUNTIME_TEE_TCB_VERSION_ENV]
  );

  return {
    provider,
    ...(quoteFormat ? { quoteFormat } : {}),
    ...(measurement ? { measurement } : {}),
    ...(reportDataHash ? { reportDataHash } : {}),
    ...(quote ? { quote } : {}),
    ...(issuerId ? { issuerId } : {}),
    ...(documentHash ? { documentHash } : {}),
    ...(tcbVersion ? { tcbVersion } : {}),
  };
}

export function summarizeRuntimeAttestation(
  attestation 
): XGnosisRuntimeAttestationSummary {
  const certifiedRuntime = asCertifiedRuntimeEnvelope(attestation);
  if (certifiedRuntime ) {
    return {
      kind: 'certified-runtime-envelope',
      runtime: certifiedRuntime.claims.runtime,
      audience: certifiedRuntime.claims.audience,
      bindingHash: certifiedRuntime.claims.bindingHash,
      buildHash: certifiedRuntime.claims.buildHash,
      teeProvider: certifiedRuntime.claims.tee.provider,
      teeMeasurement: certifiedRuntime.claims.tee.measurement,
      ...(isNonEmptyString(certifiedRuntime.claims.tee.quoteFormat)
        ? { teeQuoteFormat: certifiedRuntime.claims.tee.quoteFormat.trim() }
        : {}),
      ...(isNonEmptyString(certifiedRuntime.claims.tee.documentHash)
        ? { teeDocumentHash: certifiedRuntime.claims.tee.documentHash.trim() }
        : {}),
      ...(isNonEmptyString(certifiedRuntime.claims.tee.issuerId)
        ? { teeIssuerId: certifiedRuntime.claims.tee.issuerId.trim() }
        : {}),
      surfaces: normalizeStringArray(certifiedRuntime.claims.surfaces),
      admittedOperations: normalizeStringArray(
        certifiedRuntime.claims.admittedOperations
      ),
    };
  }

  const xLabBundle = asXLabRuntimeAttestationBundle(attestation);
  if (xLabBundle ) {
    const teeProviders = Array.from(
      new Set(
        xLabBundle.runtimeAttestations
          .map((runtimeAttestation) =>
            isRecord(runtimeAttestation.tee) &&
            isNonEmptyString(runtimeAttestation.tee.provider)
              ? runtimeAttestation.tee.provider.trim()
              : null
          )
          .filter((provider): provider is string => provider !== null)
      )
    ).sort((left, right) => left.localeCompare(right));

    const declaredTeeProviderCount = xLabBundle.runtimeAttestations.filter(
      (runtimeAttestation) =>
        isRecord(runtimeAttestation.tee) &&
        isNonEmptyString(runtimeAttestation.tee.provider)
    ).length;
    const disabledTeeAttestationCount = xLabBundle.runtimeAttestations.filter(
      (runtimeAttestation) =>
        isRecord(runtimeAttestation.tee) &&
        isNonEmptyString(runtimeAttestation.tee.provider) &&
        runtimeAttestation.tee.provider.trim() === 'none'
    ).length;

    return {
      kind: 'x-lab-runtime-attestation-bundle',
      authority: xLabBundle.authority,
      attestationId: xLabBundle.attestationId,
      runId: xLabBundle.runId,
      machineId: xLabBundle.machineId,
      machineClassId: xLabBundle.machineClassId,
      targetIds: Array.from(
        new Set(
          xLabBundle.runtimeAttestations
            .map((runtimeAttestation) =>
              isNonEmptyString(runtimeAttestation.targetId)
                ? runtimeAttestation.targetId.trim()
                : null
            )
            .filter((targetId): targetId is string => targetId !== null)
        )
      ).sort((left, right) => left.localeCompare(right)),
      runtimeAttestationCount: xLabBundle.runtimeAttestations.length,
      teeProviders,
      declaredTeeProviderCount,
      teeAttestationCount: xLabBundle.runtimeAttestations.filter(
        (runtimeAttestation) =>
          isRecord(runtimeAttestation.tee) &&
          isNonEmptyString(runtimeAttestation.tee.provider) &&
          runtimeAttestation.tee.provider.trim() !== 'none'
      ).length,
      disabledTeeAttestationCount,
      boundRuntimeAttestationCount: xLabBundle.runtimeAttestations.filter(
        (runtimeAttestation) => isNonEmptyString(runtimeAttestation.bindingHash)
      ).length,
    };
  }

  const runtimeTee = asRuntimeTeeEvidence(attestation);
  if (runtimeTee ) {
    const teeProvider = runtimeTee.provider.trim();
    return {
      kind: 'runtime-tee-state',
      teeProvider,
      teeEvidenceStatus:
        teeProvider === 'none'
          ? 'disabled'
          : isNonEmptyString(runtimeTee.quote)
          ? 'quoted'
          : 'declared',
      ...(isNonEmptyString(runtimeTee.reportDataHash)
        ? { bindingHash: runtimeTee.reportDataHash.trim() }
        : {}),
      ...(isNonEmptyString(runtimeTee.quoteFormat)
        ? { teeQuoteFormat: runtimeTee.quoteFormat.trim() }
        : {}),
      ...(isNonEmptyString(runtimeTee.measurement)
        ? { teeMeasurement: runtimeTee.measurement.trim() }
        : {}),
      ...(isNonEmptyString(runtimeTee.documentHash)
        ? { teeDocumentHash: runtimeTee.documentHash.trim() }
        : {}),
      ...(isNonEmptyString(runtimeTee.issuerId)
        ? { teeIssuerId: runtimeTee.issuerId.trim() }
        : {}),
      ...(isNonEmptyString(runtimeTee.tcbVersion)
        ? { teeTcbVersion: runtimeTee.tcbVersion.trim() }
        : {}),
    };
  }

  return {
    kind: 'opaque-json',
    keys: isRecord(attestation)
      ? Object.keys(attestation).sort((left, right) =>
          left.localeCompare(right)
        )
      : [],
  };
}

export function extractRuntimeBindingHash(attestation ): string | null {
  const certifiedRuntime = asCertifiedRuntimeEnvelope(attestation);
  if (certifiedRuntime ) {
    return certifiedRuntime.claims.bindingHash;
  }

  const xLabBundle = asXLabRuntimeAttestationBundle(attestation);
  if (!xLabBundle ) {
    const runtimeTee = asRuntimeTeeEvidence(attestation);
    return isNonEmptyString(runtimeTee?.reportDataHash)
      ? runtimeTee.reportDataHash.trim()
      : null;
  }

  const bindingHashes = Array.from(
    new Set(
      xLabBundle.runtimeAttestations
        .map((runtimeAttestation) =>
          isNonEmptyString(runtimeAttestation.bindingHash)
            ? runtimeAttestation.bindingHash.trim()
            : null
        )
        .filter((bindingHash): bindingHash is string => bindingHash !== null)
    )
  );

  return bindingHashes.length === 1 ? bindingHashes[0] ?? null : null;
}

export function resolveXGnosisRuntimeAttestation(
  options?: XGnosisRuntimeAttestationOptions | null
): XGnosisResolvedRuntimeAttestation | null {
  const environment = options?.environment ?? process.env;

  if (options && 'payload' in options ) {
    const attestation = normalizePayload(options.payload, 'inline payload');
    return {
      source: 'inline',
      attestation,
      summary: summarizeRuntimeAttestation(attestation),
    };
  }

  if (isNonEmptyString(options?.payloadPath)) {
    const attestation = loadRuntimeAttestationFile(options.payloadPath);
    return {
      source: 'file',
      attestation,
      summary: summarizeRuntimeAttestation(attestation),
    };
  }

  if (isNonEmptyString(environment[RUNTIME_ATTESTATION_JSON_ENV])) {
    const attestation = parseRuntimeAttestationJson(
      environment[RUNTIME_ATTESTATION_JSON_ENV],
      `env ${RUNTIME_ATTESTATION_JSON_ENV}`
    );
    return {
      source: 'env-inline',
      attestation,
      summary: summarizeRuntimeAttestation(attestation),
    };
  }

  if (isNonEmptyString(environment[RUNTIME_ATTESTATION_PATH_ENV])) {
    const attestation = loadRuntimeAttestationFile(
      environment[RUNTIME_ATTESTATION_PATH_ENV]
    );
    return {
      source: 'env-file',
      attestation,
      summary: summarizeRuntimeAttestation(attestation),
    };
  }

  const runtimeTeeAttestation =
    buildRuntimeTeeAttestationFromEnvironment(environment);
  if (runtimeTeeAttestation ) {
    return {
      source: 'env-tee',
      attestation: runtimeTeeAttestation,
      summary: summarizeRuntimeAttestation(runtimeTeeAttestation),
    };
  }

  return null;
}
