export const FANO_TRANSPORT_MAGIC = new Uint8Array([0x46, 0x41, 0x4e, 0x4f]);
export const FANO_TRANSPORT_PAYLOAD_LEN = 11;
export const FANO_TRANSPORT_RESIDUAL_VALIDATED = 0b0000_0001;
export const FANO_TRANSPORT_FINGERPRINT_VERIFIED = 0b0000_0010;
export const AEON_GR_2_12_AMBIENT_DIM = 12;
export const AEON_FANO_VISIBLE_PHASES = 7;
export const MONSTER_MOONSHINE_DIM = 196_884;
export const FANO_ROUTE_KIND = 'gnosis-uring-fano-route/v1';

export type FanoRouteDecision =
  | {
      kind: typeof FANO_ROUTE_KIND;
      decision: 'xor';
      monsterColumns: [number, number];
      aeonPhases: [number, number];
      aeonGate: [number, number];
      fanoStates: [number, number];
      completion: number;
    }
  | {
      kind: typeof FANO_ROUTE_KIND;
      decision: 'same-aeon-phase';
      phase: number;
    }
  | {
      kind: typeof FANO_ROUTE_KIND;
      decision: 'outside-fano-subatlas';
      aeonGate: [number, number];
    }
  | {
      kind: typeof FANO_ROUTE_KIND;
      decision: 'validation-required';
      aeonGate: [number, number];
    }
  | {
      kind: typeof FANO_ROUTE_KIND;
      decision: 'malformed';
    };

export interface EncodeFanoTransportPayloadOptions {
  residualValidated?: boolean;
  fingerprintVerified?: boolean;
}

export function encodeFanoTransportPayload(
  lhsColumn: number,
  rhsColumn: number,
  options: EncodeFanoTransportPayloadOptions = {}
): Uint8Array | null {
  if (!isMonsterColumn(lhsColumn) || !isMonsterColumn(rhsColumn)) {
    return null;
  }

  const payload = new Uint8Array(FANO_TRANSPORT_PAYLOAD_LEN);
  payload.set(FANO_TRANSPORT_MAGIC, 0);
  writeU24(payload, 4, lhsColumn);
  writeU24(payload, 7, rhsColumn);
  payload[10] =
    (options.residualValidated === false
      ? 0
      : FANO_TRANSPORT_RESIDUAL_VALIDATED) |
    (options.fingerprintVerified === false
      ? 0
      : FANO_TRANSPORT_FINGERPRINT_VERIFIED);
  return payload;
}

export function isFanoTransportPayload(payload: Uint8Array): boolean {
  return (
    payload.length === FANO_TRANSPORT_PAYLOAD_LEN &&
    payload[0] === FANO_TRANSPORT_MAGIC[0] &&
    payload[1] === FANO_TRANSPORT_MAGIC[1] &&
    payload[2] === FANO_TRANSPORT_MAGIC[2] &&
    payload[3] === FANO_TRANSPORT_MAGIC[3]
  );
}

export function routeFanoTransportPayload(
  payload: Uint8Array
): FanoRouteDecision {
  if (!isFanoTransportPayload(payload)) {
    return { kind: FANO_ROUTE_KIND, decision: 'malformed' };
  }

  return routeFanoTransportColumns(
    readU24(payload, 4),
    readU24(payload, 7),
    (payload[10] & FANO_TRANSPORT_RESIDUAL_VALIDATED) !== 0,
    (payload[10] & FANO_TRANSPORT_FINGERPRINT_VERIFIED) !== 0
  );
}

export function packFanoRouteDecision(decision: FanoRouteDecision): number {
  switch (decision.decision) {
    case 'xor':
      return packFanoXorPayloadRoute(
        FANO_XOR_ROUTE_ADMITTED,
        decision.completion,
        decision.aeonGate[0],
        decision.aeonGate[1]
      );
    case 'same-aeon-phase':
      return packFanoXorPayloadRoute(
        FANO_XOR_ROUTE_SAME_PHASE,
        decision.phase,
        0,
        0
      );
    case 'outside-fano-subatlas':
      return packFanoXorPayloadRoute(
        FANO_XOR_ROUTE_OUTSIDE_SUBATLAS,
        0,
        decision.aeonGate[0],
        decision.aeonGate[1]
      );
    case 'validation-required':
      return packFanoXorPayloadRoute(
        FANO_XOR_ROUTE_SHADOW_REQUIRED,
        0,
        decision.aeonGate[0],
        decision.aeonGate[1]
      );
    case 'malformed':
      return 0xffff;
  }
}

export function fanoRouteDecisionHint(decision: FanoRouteDecision): number {
  switch (decision.decision) {
    case 'xor':
      return decision.monsterColumns[0] <= decision.monsterColumns[1]
        ? FANO_XOR_ROUTE_HINT_POSITIVE
        : FANO_XOR_ROUTE_HINT_NEGATIVE;
    case 'same-aeon-phase':
      return FANO_XOR_ROUTE_HINT_ZERO_ROOT;
    default:
      return FANO_XOR_ROUTE_HINT_NONE;
  }
}

export function packFanoRouteDecisionWithHint(
  decision: FanoRouteDecision,
  hint = fanoRouteDecisionHint(decision)
): number {
  switch (decision.decision) {
    case 'xor':
      return packFanoXorPayloadRouteWithHint(
        hint,
        FANO_XOR_ROUTE_ADMITTED,
        decision.completion,
        decision.aeonGate[0],
        decision.aeonGate[1]
      );
    case 'same-aeon-phase':
      return packFanoXorPayloadRouteWithHint(
        hint,
        FANO_XOR_ROUTE_SAME_PHASE,
        decision.phase,
        0,
        0
      );
    case 'outside-fano-subatlas':
      return packFanoXorPayloadRouteWithHint(
        hint,
        FANO_XOR_ROUTE_OUTSIDE_SUBATLAS,
        0,
        decision.aeonGate[0],
        decision.aeonGate[1]
      );
    case 'validation-required':
      return packFanoXorPayloadRouteWithHint(
        hint,
        FANO_XOR_ROUTE_SHADOW_REQUIRED,
        0,
        decision.aeonGate[0],
        decision.aeonGate[1]
      );
    case 'malformed':
      return 0xffff;
  }
}

export function encodeFanoPackedRouteResponse(
  decision: FanoRouteDecision
): Uint8Array {
  const admittedCount = decision.decision === 'xor' ? 1 : 0;
  return fanoXorFlowPayload(admittedCount, packFanoRouteDecision(decision));
}

export function encodeFanoHintedPackedRouteResponse(
  decision: FanoRouteDecision,
  hint = fanoRouteDecisionHint(decision)
): Uint8Array {
  const admittedCount = decision.decision === 'xor' ? 1 : 0;
  return fanoXorFlowPayload(
    admittedCount,
    packFanoRouteDecisionWithHint(decision, hint)
  );
}

export function routeFanoTransportColumns(
  lhsColumn: number,
  rhsColumn: number,
  residualValidated = true,
  fingerprintVerified = true
): FanoRouteDecision {
  if (!isMonsterColumn(lhsColumn) || !isMonsterColumn(rhsColumn)) {
    return { kind: FANO_ROUTE_KIND, decision: 'malformed' };
  }

  const lhsPhase = monsterColumnPhase(lhsColumn);
  const rhsPhase = monsterColumnPhase(rhsColumn);
  if (lhsPhase === rhsPhase) {
    return {
      kind: FANO_ROUTE_KIND,
      decision: 'same-aeon-phase',
      phase: lhsPhase,
    };
  }

  const aeonGate =
    lhsPhase < rhsPhase
      ? ([lhsPhase, rhsPhase] as [number, number])
      : ([rhsPhase, lhsPhase] as [number, number]);
  const lhsState = aeonPhaseToFanoState(lhsPhase);
  const rhsState = aeonPhaseToFanoState(rhsPhase);
  if (lhsState === null || rhsState === null) {
    return {
      kind: FANO_ROUTE_KIND,
      decision: 'outside-fano-subatlas',
      aeonGate,
    };
  }

  if (!residualValidated || !fingerprintVerified) {
    return {
      kind: FANO_ROUTE_KIND,
      decision: 'validation-required',
      aeonGate,
    };
  }

  return {
    kind: FANO_ROUTE_KIND,
    decision: 'xor',
    monsterColumns: [lhsColumn, rhsColumn],
    aeonPhases: [lhsPhase, rhsPhase],
    aeonGate,
    fanoStates: [lhsState, rhsState],
    completion: tritonCollide(lhsState, rhsState),
  };
}

export function tritonCollide(lhs: number, rhs: number): number {
  return (lhs ^ rhs) & 0b111;
}

export function monsterColumnPhase(column: number): number {
  return column % AEON_GR_2_12_AMBIENT_DIM;
}

export function aeonPhaseToFanoState(phase: number): number | null {
  return phase >= 0 && phase < AEON_FANO_VISIBLE_PHASES ? phase + 1 : null;
}

function isMonsterColumn(column: number): boolean {
  return (
    Number.isInteger(column) &&
    column >= 0 &&
    column < MONSTER_MOONSHINE_DIM
  );
}

function writeU24(payload: Uint8Array, offset: number, value: number): void {
  payload[offset] = (value >>> 16) & 0xff;
  payload[offset + 1] = (value >>> 8) & 0xff;
  payload[offset + 2] = value & 0xff;
}

function readU24(payload: Uint8Array, offset: number): number {
  return (
    (payload[offset] << 16) | (payload[offset + 1] << 8) | payload[offset + 2]
  );
}
