import type { DistributedTopology, TopologyEdge, TopologyNode } from '@a0n/cognitive-bridge';

export interface SpanRecord {
  readonly traceId: string;
  readonly spanId: string;
  readonly parentSpanId?: string;
  readonly name: string;
  readonly startTime: number;
  readonly endTime: number;
  readonly status: { code: number; message?: string };
  readonly attributes: Record<string, string | number | boolean>;
}

/**
 * Betti-Stress Analyzer
 *
 * Maps real-time telemetry (spans) against the distributed topology
 * to calculate predictive stress scores.
 */
export function analyzeTopologyStress(
  topology: DistributedTopology,
  spans: SpanRecord[]
): DistributedTopology {
  const nodeStress = new Map<
    string,
    { total: number; errors: number; totalDuration: number }
  >();

  // Map spans to nodes
  for (const span of spans) {
    const projectName = span.attributes['a0.project.name'] as string;
    if (!projectName) continue;

    const nodeId = `worker:${projectName}`;
    const stats = nodeStress.get(nodeId) || {
      total: 0,
      errors: 0,
      totalDuration: 0,
    };

    stats.total++;
    if (span.status.code === 2) stats.errors++; // 2 = Error
    stats.totalDuration += span.endTime - span.startTime;

    nodeStress.set(nodeId, stats);
  }

  // Enrich nodes with stress scores
  const enrichedNodes = topology.nodes.map((node: TopologyNode) => {
    const stats = nodeStress.get(node.id);
    if (!stats || stats.total === 0) return node;

    // Heuristic: Stress = (Error Rate * 0.7) + (Latent Pressure * 0.3)
    const errorRate = stats.errors / stats.total;
    const avgDuration = stats.totalDuration / stats.total;

    // Normalize duration: > 500ms starts contributing significantly to stress
    const latentPressure = Math.min(1, avgDuration / 1000);

    const stressScore = Math.min(1, errorRate * 0.7 + latentPressure * 0.3);

    return {
      ...node,
      stressScore,
    };
  });

  // Simple propagation for edges: stress is the max of its endpoints
  const enrichedEdges = topology.edges.map((edge: TopologyEdge) => {
    const sourceNode = enrichedNodes.find((n: TopologyNode) => n.id === edge.source);
    const targetNode = enrichedNodes.find((n: TopologyNode) => n.id === edge.target);

    const stressScore = Math.max(
      sourceNode?.stressScore || 0,
      targetNode?.stressScore || 0
    );

    return {
      ...edge,
      stressScore,
    };
  });

  return {
    ...topology,
    nodes: enrichedNodes,
    edges: enrichedEdges,
  };
}
