import { mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { homedir } from 'node:os';
import { createRequire } from 'node:module';
import type { ReleaseGraphSnapshot } from './types.js';

const DEFAULT_RELEASE_STORE_PATH = join(
  homedir(),
  '.gnot-repl',
  'releases.sqlite3'
);

interface SqliteStatement {
  run(...values: unknown[]): unknown;
  all(...values: unknown[]): unknown[];
}

interface SqliteDatabase {
  exec(sql: string): void;
  prepare(sql: string): SqliteStatement;
  close(): void;
}

type DatabaseSyncCtor = new (path: string) => SqliteDatabase;

function resolveDatabaseSync(): DatabaseSyncCtor {
  const require = createRequire(import.meta.url);
  const moduleShape = require('node:sqlite') as {
    DatabaseSync?: DatabaseSyncCtor;
  };
  if (!moduleShape.DatabaseSync) {
    throw new Error('node:sqlite DatabaseSync is unavailable');
  }
  return moduleShape.DatabaseSync;
}

export interface ReleaseStore {
  loadAll(): ReleaseGraphSnapshot[];
  saveGraph(graph: ReleaseGraphSnapshot): void;
  close(): void;
}

export class SqliteReleaseStore implements ReleaseStore {
  private readonly db: SqliteDatabase;

  constructor(path: string = DEFAULT_RELEASE_STORE_PATH) {
    const DatabaseSync = resolveDatabaseSync();
    mkdirSync(dirname(path), { recursive: true });
    this.db = new DatabaseSync(path);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS release_graphs (
        graph_key TEXT PRIMARY KEY,
        app TEXT NOT NULL,
        environment TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        updated_at INTEGER NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_release_graphs_env_app
      ON release_graphs (environment, app);
    `);
  }

  loadAll(): ReleaseGraphSnapshot[] {
    const statement = this.db.prepare(
      'SELECT payload_json FROM release_graphs ORDER BY environment, app'
    );
    const rows = statement.all() as Array<{ payload_json: string }>;
    const graphs: ReleaseGraphSnapshot[] = [];
    for (const row of rows) {
      try {
        const parsed = JSON.parse(row.payload_json) as ReleaseGraphSnapshot;
        graphs.push(parsed);
      } catch {
        // Skip corrupted rows to keep startup resilient.
      }
    }
    return graphs;
  }

  saveGraph(graph: ReleaseGraphSnapshot): void {
    const key = `${graph.environment}:${graph.app}`;
    const statement = this.db.prepare(
      `INSERT INTO release_graphs (graph_key, app, environment, payload_json, updated_at)
       VALUES (?, ?, ?, ?, ?)
       ON CONFLICT(graph_key) DO UPDATE SET
         payload_json = excluded.payload_json,
         updated_at = excluded.updated_at`
    );
    statement.run(
      key,
      graph.app,
      graph.environment,
      JSON.stringify(graph),
      Date.now()
    );
  }

  close(): void {
    this.db.close();
  }
}

export class InMemoryReleaseStore implements ReleaseStore {
  private readonly graphs = new Map<string, ReleaseGraphSnapshot>();

  loadAll(): ReleaseGraphSnapshot[] {
    return Array.from(this.graphs.values()).map((graph) =>
      JSON.parse(JSON.stringify(graph))
    ) as ReleaseGraphSnapshot[];
  }

  saveGraph(graph: ReleaseGraphSnapshot): void {
    this.graphs.set(
      `${graph.environment}:${graph.app}`,
      JSON.parse(JSON.stringify(graph)) as ReleaseGraphSnapshot
    );
  }

  close(): void {}
}
