import { FlowFrame, FIN, FOLD, FORK, VENT } from './types';

export const MONITOR_FRAME_SCHEMA = 'gnosis.monitor.v1';
// Stream id: 0x6d6f = ASCII "mo" (monitor). Distinct from Skymesh 0x5353 ("SS")
// and BodyPolitick 0xb0d1.
export const MONITOR_FLOW_STREAM_ID = 0x6d6f;

export type MonitorSceneKind = 'raster' | 'vector' | 'embed' | 'skymesh';

export interface MonitorFlowFrame {
  readonly schemaVersion: string;
  readonly scene: string;
  readonly kind: MonitorSceneKind;
  readonly title?: string;
  readonly width: number;
  readonly height: number;
  readonly channels?: 1 | 4;
  readonly raster?: string;
  readonly palette?: string;
  readonly vector?: unknown;
  readonly embed?: { readonly url: string; readonly params?: Record<string, unknown> };
  readonly attributes?: Record<string, string>;
  readonly metadata?: Record<string, unknown>;
  readonly ts: number;
  readonly [key: string]: unknown;
}

export interface MonitorFlowFrameOptions {
  readonly streamId?: number;
  readonly sequence?: number;
  readonly flags?: number;
  readonly terminalBatch?: boolean;
}

const encoder = new TextEncoder();
const decoder = new TextDecoder();

const MONITOR_SCENE_KINDS: readonly MonitorSceneKind[] = ['raster', 'vector', 'embed', 'skymesh'];

function stableSequence(input: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function sequenceKey(frame: MonitorFlowFrame): string {
  return `${frame.scene}:${frame.ts}`;
}

function isMalformed(frame: MonitorFlowFrame): boolean {
  if (
    !frame ||
    typeof frame !== 'object' ||
    frame.schemaVersion !== MONITOR_FRAME_SCHEMA ||
    typeof frame.scene !== 'string' ||
    !MONITOR_SCENE_KINDS.includes(frame.kind)
  ) {
    return true;
  }
  if (frame.kind === 'raster') {
    return (
      typeof frame.width !== 'number' ||
      typeof frame.height !== 'number' ||
      typeof frame.raster !== 'string'
    );
  }
  return false;
}

function defaultFlags(frame: MonitorFlowFrame, terminalBatch: boolean): number {
  const base = isMalformed(frame) ? VENT : FORK | FOLD;
  return terminalBatch ? base | FIN : base;
}

export function encodeMonitorFlowFrame(
  frame: MonitorFlowFrame,
  options: MonitorFlowFrameOptions = {}
): FlowFrame {
  const payload = encoder.encode(JSON.stringify(frame));
  return {
    streamId: options.streamId ?? MONITOR_FLOW_STREAM_ID,
    sequence: options.sequence ?? stableSequence(sequenceKey(frame)),
    flags: options.flags ?? defaultFlags(frame, options.terminalBatch === true),
    payload,
  };
}

function assertMonitorFrame(value: unknown): asserts value is MonitorFlowFrame {
  if (!value || typeof value !== 'object') {
    throw new Error('Monitor FlowFrame payload must be a JSON object.');
  }
  const frame = value as Partial<MonitorFlowFrame>;
  if (frame.schemaVersion !== MONITOR_FRAME_SCHEMA) {
    throw new Error('Monitor FlowFrame payload has an unsupported schemaVersion.');
  }
  if (typeof frame.scene !== 'string') {
    throw new Error('Monitor FlowFrame payload must include a scene string.');
  }
  if (!MONITOR_SCENE_KINDS.includes(frame.kind as MonitorSceneKind)) {
    throw new Error('Monitor FlowFrame payload has an unsupported kind.');
  }
  if (frame.kind === 'raster') {
    if (typeof frame.width !== 'number' || typeof frame.height !== 'number') {
      throw new Error('Monitor FlowFrame raster payload must include numeric width and height.');
    }
    if (typeof frame.raster !== 'string') {
      throw new Error('Monitor FlowFrame raster payload must include a raster string.');
    }
  }
}

export function decodeMonitorFlowFrame(flowFrame: FlowFrame): MonitorFlowFrame {
  const parsed = JSON.parse(decoder.decode(flowFrame.payload)) as unknown;
  assertMonitorFrame(parsed);
  return parsed;
}
