import { compileFiniteDistribution, probabilityRatio } from './probability-compiler.js';

export type ProbabilityRouteDecision = 'reuse' | 'speculate' | 'cover' | 'explore';

export interface RouteMassInput {
  readonly route: string;
  readonly count: number;
}

export interface ProbabilityRoutePolicy {
  readonly minObservations?: number;
  readonly minConcentrationBps?: number;
  readonly residualBudget?: number;
  readonly maxRoutes?: number;
}

export interface ProbabilityRouteWitness {
  readonly route: string;
  readonly count: number;
  readonly totalMass: number;
  readonly residualMass: number;
  readonly concentrationBps: number;
  readonly probability: {
    readonly numerator: number;
    readonly denominator: number;
  };
  readonly decision: ProbabilityRouteDecision;
  readonly reason: string;
}

export interface ProbabilityRouteSelection {
  readonly totalMass: number;
  readonly witnesses: readonly ProbabilityRouteWitness[];
  readonly selected: readonly ProbabilityRouteWitness[];
}

const DEFAULT_MIN_OBSERVATIONS = 3;
const DEFAULT_MIN_CONCENTRATION_BPS = 5_000;
const DEFAULT_MAX_ROUTES = 5;

function assertRoute(route: string): void {
  if (route.trim().length === 0) {
    throw new Error('route must be a non-empty string');
  }
}

function assertNat(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error(`${label} must be a safe natural number`);
  }
}

function normalizeRouteMasses(masses: readonly RouteMassInput[]): RouteMassInput[] {
  return masses.map((mass, index) => {
    assertRoute(mass.route);
    assertNat(mass.count, `masses[${index}].count`);
    return { route: mass.route, count: mass.count };
  });
}

function routeDecision(
  route: string,
  count: number,
  totalMass: number,
  policy: Required<ProbabilityRoutePolicy>
): Pick<ProbabilityRouteWitness, 'decision' | 'reason'> {
  const residualMass = totalMass - count;
  const concentrationBps = Math.floor((count * 10_000) / totalMass);

  if (totalMass < policy.minObservations) {
    return {
      decision: 'explore',
      reason: `${route} has insufficient observed mass for reuse.`,
    };
  }

  if (residualMass > policy.residualBudget) {
    return {
      decision: 'cover',
      reason: `${route} leaves residual route mass above the configured cover budget.`,
    };
  }

  if (concentrationBps >= policy.minConcentrationBps) {
    return {
      decision: 'reuse',
      reason: `${route} concentrates enough observed mass for exact reuse.`,
    };
  }

  return {
    decision: 'speculate',
    reason: `${route} is covered but not concentrated enough for exact reuse.`,
  };
}

export function selectProbabilityRoutes(
  masses: readonly RouteMassInput[],
  options: ProbabilityRoutePolicy = {}
): ProbabilityRouteSelection {
  const normalized = normalizeRouteMasses(masses).filter((mass) => mass.count > 0);
  const distribution = compileFiniteDistribution(
    normalized.map((mass) => mass.count)
  );
  const policy: Required<ProbabilityRoutePolicy> = {
    minObservations: options.minObservations ?? DEFAULT_MIN_OBSERVATIONS,
    minConcentrationBps: options.minConcentrationBps ?? DEFAULT_MIN_CONCENTRATION_BPS,
    residualBudget: options.residualBudget ?? distribution.totalMass,
    maxRoutes: options.maxRoutes ?? DEFAULT_MAX_ROUTES,
  };

  assertNat(policy.minObservations, 'minObservations');
  assertNat(policy.minConcentrationBps, 'minConcentrationBps');
  assertNat(policy.residualBudget, 'residualBudget');
  assertNat(policy.maxRoutes, 'maxRoutes');
  if (policy.minConcentrationBps > 10_000) {
    throw new Error('minConcentrationBps cannot exceed 10000');
  }
  if (policy.maxRoutes === 0) {
    throw new Error('maxRoutes must be positive');
  }

  const witnesses = normalized
    .map((mass): ProbabilityRouteWitness => {
      const decision = routeDecision(
        mass.route,
        mass.count,
        distribution.totalMass,
        policy
      );
      return {
        route: mass.route,
        count: mass.count,
        totalMass: distribution.totalMass,
        residualMass: distribution.totalMass - mass.count,
        concentrationBps: Math.floor((mass.count * 10_000) / distribution.totalMass),
        probability: probabilityRatio(mass.count, distribution.totalMass),
        decision: decision.decision,
        reason: decision.reason,
      };
    })
    .sort(
      (left, right) =>
        right.count - left.count ||
        right.concentrationBps - left.concentrationBps ||
        left.route.localeCompare(right.route)
    );

  const selected = witnesses
    .filter((witness) => witness.decision === 'reuse' || witness.decision === 'speculate')
    .slice(0, policy.maxRoutes);

  return {
    totalMass: distribution.totalMass,
    witnesses,
    selected,
  };
}

