import { existsSync, readdirSync, statSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export interface XRangerBinaryCommand {
  readonly command: string;
  readonly args: readonly string[];
  readonly display: string;
}

function packageRoot(): string {
  return resolve(dirname(fileURLToPath(import.meta.url)), '..');
}

function rustSourceRoot(): string {
  return resolve(packageRoot(), 'gnosis-ranger');
}

function treeModifiedAfter(path: string, cutoffMs: number): boolean {
  const stats = statSync(path);
  if (stats.mtimeMs > cutoffMs) {
    return true;
  }
  if (!stats.isDirectory()) {
    return false;
  }
  return readdirSync(path).some((entry) =>
    treeModifiedAfter(resolve(path, entry), cutoffMs)
  );
}

function isUsableBinary(path: string): boolean {
  if (!existsSync(path)) {
    return false;
  }
  const binaryMtime = statSync(path).mtimeMs;
  return (
    !treeModifiedAfter(resolve(rustSourceRoot(), 'src'), binaryMtime) &&
    !treeModifiedAfter(resolve(rustSourceRoot(), 'Cargo.toml'), binaryMtime)
  );
}

export function resolveXRangerBinaryCommand(
  args: readonly string[],
  env: NodeJS.ProcessEnv = process.env
): XRangerBinaryCommand {
  const override = env.XRANGER_BIN;
  const candidates = [
    ...(override ? [override] : []),
    resolve(rustSourceRoot(), 'target', 'release', 'gnosis-ranger'),
    resolve(rustSourceRoot(), 'target', 'debug', 'gnosis-ranger'),
  ];
  const binary = candidates.find((candidate) => isUsableBinary(candidate));

  if (binary) {
    return {
      command: binary,
      args,
      display: `${binary} ${args.join(' ')}`.trim(),
    };
  }

  const manifestPath = resolve(rustSourceRoot(), 'Cargo.toml');
  const cargoArgs = [
    'run',
    '--manifest-path',
    manifestPath,
    '--bin',
    'gnosis-ranger',
    '--release',
    '--',
    ...args,
  ];
  return {
    command: 'cargo',
    args: cargoArgs,
    display: `cargo ${cargoArgs.join(' ')}`,
  };
}
