/**
 * ForgoCD Project Discovery
 *
 * Scans a monorepo workspace for deployable projects by looking for
 * aeon.toml or wrangler.toml config files in apps/workers directories.
 * Returns topologically sorted projects based on service binding deps.
 */

import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { join, basename, relative } from 'node:path';
import type {
  ForgoProject,
  ForgoProjectConfig,
  ForgoAgentConfig,
  ForgoGnosisConfig,
  ForgoGnosisSurface,
} from './types.ts';
import { parseWranglerConfig } from './wrangler-compat.ts';
import { createLogger } from './logger.ts';

const log = createLogger('forgo-discovery');

// ---------------------------------------------------------------------------
// Minimal aeon.toml parser for deploy config
// ---------------------------------------------------------------------------

function parseAeonDeployConfig(tomlText: string): {
  config: ForgoProjectConfig;
  serviceDeps: string[];
} {
  const lines = tomlText.split(/\r?\n/);
  const values: Record<string, string> = {};
  let currentSection = '';

  for (const raw of lines) {
    const line = raw.replace(/#.*$/, '').trim();
    if (!line) continue;

    if (line.startsWith('[') && line.endsWith(']') && !line.startsWith('[[')) {
      currentSection = line.slice(1, -1).trim();
      continue;
    }

    const eqIdx = line.indexOf('=');
    if (eqIdx < 0) continue;

    const key = line.slice(0, eqIdx).trim();
    let val = line.slice(eqIdx + 1).trim();
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }

    const fullKey = currentSection ? `${currentSection}.${key}` : key;
    values[fullKey] = val;
  }

  function parseInlineArray(raw: string | undefined): string[] {
    if (!raw) {
      return [];
    }

    const trimmed = raw.trim();
    if (!trimmed.startsWith('[') || !trimmed.endsWith(']')) {
      return [];
    }

    return trimmed
      .slice(1, -1)
      .split(',')
      .map((value) => value.trim().replace(/^["']|["']$/g, ''))
      .filter(Boolean);
  }

  const name = values['project.name'] || 'unknown';
  const runtime = (values['project.runtime'] ||
    'bun') as ForgoProjectConfig['runtime'];
  const kind = (values['project.kind'] ||
    'worker') as ForgoProjectConfig['kind'];
  const entryPoint = values['project.entryPoint'] || 'src/index.ts';
  const portStr = values['project.port'];
  const buildCommand = values['project.buildCommand'];
  const gnosisSurfaces = parseInlineArray(values['gnosis.surfaces']) as
    | ForgoGnosisSurface[]
    | undefined;
  const gnosisRuntimeTarget =
    values['gnosis.runtimeTarget'] ?? values['gnosis.runtime_target'];
  const gnosisHost = values['gnosis.host'];
  const gnosisBridgeWorkersRaw =
    values['gnosis.bridgeWorkers'] ?? values['gnosis.bridge_workers'];
  const gnosisBridgeWorkers = gnosisBridgeWorkersRaw
    ? Number(gnosisBridgeWorkersRaw)
    : undefined;
  const gnosisConfig: ForgoGnosisConfig | undefined =
    gnosisHost ||
    gnosisRuntimeTarget ||
    (gnosisSurfaces?.length ?? 0) > 0 ||
    gnosisBridgeWorkers !== undefined
      ? {
          host: gnosisHost as ForgoGnosisConfig['host'],
          runtimeTarget:
            gnosisRuntimeTarget as ForgoGnosisConfig['runtimeTarget'],
          surfaces: gnosisSurfaces?.length ? gnosisSurfaces : undefined,
          bridgeWorkers:
            gnosisBridgeWorkers !== undefined &&
            Number.isFinite(gnosisBridgeWorkers)
              ? Math.max(1, Math.floor(gnosisBridgeWorkers))
              : undefined,
        }
      : undefined;

  // Parse [substrate] section
  const substrate: Record<string, unknown> = {};
  const substratePrefix = 'substrate.';
  for (const [key, val] of Object.entries(values)) {
    if (key.startsWith(substratePrefix)) {
      const field = key.slice(substratePrefix.length);
      // Parse booleans
      if (val === 'true') substrate[field] = true;
      else if (val === 'false') substrate[field] = false;
      // Parse numbers
      else if (/^\d+$/.test(val)) substrate[field] = Number(val);
      // Parse arrays (simple comma-separated)
      else if (val.startsWith('[') && val.endsWith(']')) {
        substrate[field] = val
          .slice(1, -1)
          .split(',')
          .map((s) => s.trim().replace(/^["']|["']$/g, ''))
          .filter(Boolean);
      } else {
        // Parse memory strings like "2GB" or "512MB"
        const memMatch = val.match(/^(\d+)\s*(GB|MB)$/i);
        if (memMatch) {
          const num = Number(memMatch[1]);
          const unit = memMatch[2]!.toUpperCase();
          substrate[field] = unit === 'GB' ? num * 1024 : num;
        } else {
          substrate[field] = val;
        }
      }
    }
  }

  // Map TOML snake_case keys to camelCase TypeScript fields
  const substrateConfig =
    Object.keys(substrate).length > 0
      ? {
          webgpu: substrate['webgpu'] as boolean | undefined,
          webgl: substrate['webgl'] as boolean | undefined,
          wasm: substrate['wasm'] as boolean | undefined,
          simd: substrate['simd'] as boolean | undefined,
          sharedArrayBuffer:
            (substrate['shared_array_buffer'] as boolean | undefined) ??
            (substrate['sharedArrayBuffer'] as boolean | undefined),
          minMemoryMb:
            (substrate['min_memory'] as number | undefined) ??
            (substrate['minMemoryMb'] as number | undefined),
          minNpuMemoryMb:
            (substrate['min_npu_memory'] as number | undefined) ??
            (substrate['minNpuMemoryMb'] as number | undefined),
          minStorageMb:
            (substrate['min_storage'] as number | undefined) ??
            (substrate['minStorageMb'] as number | undefined),
          customCapabilities: substrate['custom_capabilities'] as
            | string[]
            | undefined,
        }
      : undefined;

  // Parse [agent] section (only for kind: 'agent')
  let agentConfig: ForgoAgentConfig | undefined;
  if (kind === 'agent') {
    const topology = values['agent.topology'] || '';
    const schedule = values['agent.schedule'];
    const maxConcurrency = values['agent.maxConcurrency']
      ? Number(values['agent.maxConcurrency'])
      : 1;
    const entropyGate = values['agent.entropyGate']
      ? Number(values['agent.entropyGate'])
      : undefined;

    // Parse trigger array
    const triggerStr = values['agent.trigger'] || '';
    const triggers = triggerStr
      .replace(/[[\]"']/g, '')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean) as ForgoAgentConfig['triggers'];

    // Parse tool arrays
    const mcpToolsStr = values['agent.tools.mcp'] || '';
    const mcpTools = mcpToolsStr
      .replace(/[[\]"']/g, '')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean);
    const builtinToolsStr = values['agent.tools.builtin'] || '';
    const builtinTools = builtinToolsStr
      .replace(/[[\]"']/g, '')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean);

    // Parse model config
    const modelId = values['agent.model.modelId'];
    const model = modelId
      ? {
          modelId,
          provider: values['agent.model.provider'],
          temperature: values['agent.model.temperature']
            ? Number(values['agent.model.temperature'])
            : undefined,
          maxTokens: values['agent.model.maxTokens']
            ? Number(values['agent.model.maxTokens'])
            : undefined,
        }
      : undefined;

    // Parse guardrail arrays
    const inputGuardrails = values['agent.guardrails.input']
      ? values['agent.guardrails.input']
          .replace(/[[\]"']/g, '')
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean)
      : undefined;
    const outputGuardrails = values['agent.guardrails.output']
      ? values['agent.guardrails.output']
          .replace(/[[\]"']/g, '')
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean)
      : undefined;

    agentConfig = {
      topology,
      schedule,
      triggers: triggers.length > 0 ? triggers : ['manual'],
      maxConcurrency,
      entropyGate,
      mcpTools: mcpTools.length > 0 ? mcpTools : undefined,
      builtinTools: builtinTools.length > 0 ? builtinTools : undefined,
      model,
      guardrails:
        inputGuardrails || outputGuardrails
          ? { input: inputGuardrails, output: outputGuardrails }
          : undefined,
    };
  }

  return {
    config: {
      name,
      runtime,
      kind,
      entryPoint,
      port: portStr ? Number(portStr) : undefined,
      env: {},
      bindings: [],
      buildCommand: buildCommand || undefined,
      substrate: substrateConfig,
      gnosis: gnosisConfig,
      agent: agentConfig,
    },
    serviceDeps: [],
  };
}

// ---------------------------------------------------------------------------
// Filesystem scanning
// ---------------------------------------------------------------------------

interface DiscoveryOptions {
  /** Directory patterns to search (relative to root). Default: ['apps', 'workers'] */
  appDirs?: string[];
  /** Only include projects whose name matches these strings */
  filter?: string[];
}

function isDirectory(path: string): boolean {
  try {
    return statSync(path).isDirectory();
  } catch {
    return false;
  }
}

function findProjectDirs(root: string, appDirs: string[]): string[] {
  const dirs: string[] = [];

  for (const appDir of appDirs) {
    const fullDir = join(root, appDir);
    if (!isDirectory(fullDir)) continue;

    try {
      const entries = readdirSync(fullDir);
      for (const entry of entries) {
        const entryPath = join(fullDir, entry);
        if (isDirectory(entryPath)) {
          dirs.push(entryPath);
        }
      }
    } catch {
      // Skip unreadable directories
    }
  }

  // Also check root itself for a config
  if (
    existsSync(join(root, 'aeon.toml')) ||
    existsSync(join(root, 'wrangler.toml'))
  ) {
    dirs.unshift(root);
  }

  return dirs;
}

function loadProjectFromDir(dir: string, root: string): ForgoProject | null {
  const aeonTomlPath = join(dir, 'aeon.toml');
  const wranglerTomlPath = join(dir, 'wrangler.toml');

  const hasAeonToml = existsSync(aeonTomlPath);
  const hasWranglerToml = existsSync(wranglerTomlPath);

  if (!hasAeonToml && !hasWranglerToml) return null;

  let config: ForgoProjectConfig;
  let serviceDeps: string[] = [];
  let configSource: ForgoProject['configSource'];

  if (hasWranglerToml) {
    const tomlText = readFileSync(wranglerTomlPath, 'utf8');
    const parsed = parseWranglerConfig(tomlText);
    config = parsed.config;
    serviceDeps = parsed.serviceDeps;
    configSource = hasAeonToml ? 'both' : 'wrangler.toml';

    // If aeon.toml also exists, let it override certain fields
    if (hasAeonToml) {
      const aeonText = readFileSync(aeonTomlPath, 'utf8');
      const aeonParsed = parseAeonDeployConfig(aeonText);
      config = { ...config, ...aeonParsed.config, bindings: config.bindings };
    }
  } else {
    const aeonText = readFileSync(aeonTomlPath, 'utf8');
    const parsed = parseAeonDeployConfig(aeonText);
    config = parsed.config;
    serviceDeps = parsed.serviceDeps;
    configSource = 'aeon.toml';
  }

  // Fallback name to directory basename
  if (config.name === 'unknown') {
    config.name = basename(dir);
  }

  const relDir = relative(root, dir) || '.';

  // Filter out self-dependencies to prevent circular dependency errors for self-referential bindings
  const cleanDeps = serviceDeps.filter((dep) => dep !== config.name);

  return {
    name: config.name,
    dir: relDir,
    configSource,
    config,
    dependsOn: cleanDeps,
  };
}

// ---------------------------------------------------------------------------
// VFS-based scanning (for post-push GitOps mode)
// ---------------------------------------------------------------------------

export interface VfsEntry {
  type: 'file';
  hash: string;
  mode: number;
}

/**
 * Discover projects from a CRDT VFS map.
 * Used by the GitOps hook after a push to scan the VFS for config files.
 */
export function discoverProjectsFromVfs(
  vfsEntries: Map<string, VfsEntry>,
  getBlobContent: (hash: string) => Uint8Array | null
): ForgoProject[] {
  const projects: ForgoProject[] = [];
  const configPaths: Array<{
    path: string;
    type: 'aeon.toml' | 'wrangler.toml';
  }> = [];

  // Scan VFS for config files
  for (const [path] of vfsEntries) {
    if (path.endsWith('/aeon.toml') || path === '/aeon.toml') {
      configPaths.push({ path, type: 'aeon.toml' });
    }
    if (path.endsWith('/wrangler.toml') || path === '/wrangler.toml') {
      configPaths.push({ path, type: 'wrangler.toml' });
    }
  }

  // Group by parent directory
  const byDir = new Map<string, { aeon?: string; wrangler?: string }>();
  for (const { path, type } of configPaths) {
    const dir = path.replace(/\/[^/]+$/, '') || '/';
    const existing = byDir.get(dir) || {};
    const entry = vfsEntries.get(path);
    if (!entry) continue;

    const content = getBlobContent(entry.hash);
    if (!content) continue;

    const text = new TextDecoder().decode(content);
    if (type === 'aeon.toml') existing.aeon = text;
    else existing.wrangler = text;
    byDir.set(dir, existing);
  }

  // Parse each directory's configs
  for (const [dir, configs] of byDir) {
    let config: ForgoProjectConfig;
    let serviceDeps: string[] = [];
    let configSource: ForgoProject['configSource'];

    if (configs.wrangler) {
      const parsed = parseWranglerConfig(configs.wrangler);
      config = parsed.config;
      serviceDeps = parsed.serviceDeps;
      configSource = configs.aeon ? 'both' : 'wrangler.toml';

      if (configs.aeon) {
        const aeonParsed = parseAeonDeployConfig(configs.aeon);
        config = { ...config, ...aeonParsed.config, bindings: config.bindings };
      }
    } else if (configs.aeon) {
      const parsed = parseAeonDeployConfig(configs.aeon);
      config = parsed.config;
      serviceDeps = parsed.serviceDeps;
      configSource = 'aeon.toml';
    } else {
      continue;
    }

    if (config.name === 'unknown') {
      config.name = dir.split('/').pop() || 'unknown';
    }

    const cleanDeps = serviceDeps.filter((dep) => dep !== config.name);

    projects.push({
      name: config.name,
      dir,
      configSource,
      config,
      dependsOn: cleanDeps,
    });
  }

  return projects;
}

// ---------------------------------------------------------------------------
// Topological sort
// ---------------------------------------------------------------------------

export interface ResolveDeployOrderOpts {
  /** Called when a circular dependency is detected */
  onCycle?: (cycle: string[]) => void;
}

/**
 * Sort projects by their service binding dependencies (topological order).
 * Projects with no dependencies come first.
 */
export function resolveDeployOrder(
  projects: ForgoProject[],
  opts?: ResolveDeployOrderOpts
): ForgoProject[] {
  const nameToProject = new Map<string, ForgoProject>();
  for (const p of projects) nameToProject.set(p.name, p);

  const visited = new Set<string>();
  const sorted: ForgoProject[] = [];

  function visit(name: string, stack: Set<string>, path: string[]): void {
    if (visited.has(name)) return;
    if (stack.has(name)) {
      // Circular dependency — build cycle path and warn
      const cycleStart = path.indexOf(name);
      const cyclePath = [...path.slice(cycleStart), name];
      log.warn('Circular dependency detected', {
        cycle: cyclePath.join(' → '),
      });
      opts?.onCycle?.(cyclePath);
      return;
    }

    stack.add(name);
    path.push(name);
    const project = nameToProject.get(name);
    if (project) {
      for (const dep of project.dependsOn) {
        visit(dep, stack, path);
      }
      visited.add(name);
      sorted.push(project);
    }
    path.pop();
    stack.delete(name);
  }

  for (const p of projects) {
    visit(p.name, new Set(), []);
  }

  return sorted;
}

/**
 * Validate that all dependsOn entries reference real projects.
 * Returns missing dependencies for logging/alerting.
 */
export function validateDependencies(projects: ForgoProject[]): {
  valid: boolean;
  missing: Array<{ project: string; missingDep: string }>;
} {
  const projectNames = new Set(projects.map((p) => p.name));
  const missing: Array<{ project: string; missingDep: string }> = [];

  for (const project of projects) {
    for (const dep of project.dependsOn) {
      if (!projectNames.has(dep)) {
        missing.push({ project: project.name, missingDep: dep });
        log.warn('Missing dependency', {
          project: project.name,
          missingDep: dep,
        });
      }
    }
  }

  return { valid: missing.length === 0, missing };
}

// ---------------------------------------------------------------------------
// Main discovery function
// ---------------------------------------------------------------------------

/**
 * Discover all deployable projects in a monorepo.
 *
 * Walks the specified app directories (default: apps/, workers/) for
 * aeon.toml or wrangler.toml config files, parses them, and returns
 * projects sorted in dependency order.
 */
export async function discoverProjects(
  root: string,
  opts?: DiscoveryOptions
): Promise<ForgoProject[]> {
  const appDirs = opts?.appDirs || [
    'apps',
    'workers',
    'open-source',
    'packages',
    'packages/agent-games',
  ];
  const dirs = findProjectDirs(root, appDirs);
  const projects: ForgoProject[] = [];

  for (const dir of dirs) {
    const project = loadProjectFromDir(dir, root);
    if (!project) continue;

    // Apply filter if provided
    if (opts?.filter && opts.filter.length > 0) {
      if (
        !opts.filter.some(
          (f) => project.name.includes(f) || project.dir.includes(f)
        )
      ) {
        continue;
      }
    }

    projects.push(project);
  }

  validateDependencies(projects);
  return resolveDeployOrder(projects);
}
