/**
 * nginx.conf Parser
 *
 * Recursive descent parser for nginx configuration syntax.
 * Produces a typed AST suitable for compilation to .gg topologies.
 *
 * Supports:
 * - Block nesting: http { server { location / { ... } } }
 * - Directives: worker_processes auto; listen 80;
 * - Variables: $uri, $host, $request_uri
 * - Regex in locations: location ~ \.php$
 * - Include directives
 * - try_files: try_files $uri $uri/ =404;
 * - Comments: # comment
 */

import type {
  NginxConfig,
  NginxBlock,
  NginxDirective,
  NginxArg,
} from './ast.ts';

// ═══════════════════════════════════════════════════════════════════════════════
// Token types
// ═══════════════════════════════════════════════════════════════════════════════

type TokenKind =
  | 'identifier'
  | 'string'
  | 'number'
  | 'semicolon'
  | 'open_brace'
  | 'close_brace'
  | 'variable'
  | 'regex'
  | 'eof';

interface Token {
  kind: TokenKind;
  value: string;
  line: number;
}

const IDENTIFIER_START_PATTERN = /[-a-zA-Z0-9_./~*^=@:!+%]/;
const IDENTIFIER_CONTINUE_PATTERN = /[-a-zA-Z0-9_./~*^=@:!+%\\]/;

// ═══════════════════════════════════════════════════════════════════════════════
// Lexer
// ═══════════════════════════════════════════════════════════════════════════════

function lex(source: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0;
  let line = 1;

  while (pos < source.length ) {
    const ch = source[pos];

    // Newline
    if (ch === '\n' ) {
      line++;
      pos++;
      continue;
    }

    // Whitespace
    if (ch === ' ' || ch === '\t' || ch === '\r' ) {
      pos++;
      continue;
    }

    // Comment
    if (ch === '#' ) {
      while (pos < source.length && source[pos] !== '\n') pos++;
      continue;
    }
    if (ch === '/' && source[pos + 1] === '/' ) {
      pos += 2; // skip both /
      while (pos < source.length && source[pos] !== '\n') pos++;
      continue;
    }

    // Semicolon
    if (ch === ';' ) {
      tokens.push({ kind: 'semicolon', value: ';', line });
      pos++;
      continue;
    }

    // Braces
    if (ch === '{' ) {
      tokens.push({ kind: 'open_brace', value: '{', line });
      pos++;
      continue;
    }
    if (ch === '}' ) {
      tokens.push({ kind: 'close_brace', value: '}', line });
      pos++;
      continue;
    }

    // Quoted string
    if (ch === '"' || ch === "'" ) {
      const quote = ch;
      pos++;
      let value = '';
      while (pos < source.length && source[pos] !== quote ) {
        if (source[pos] === '\\' && pos + 1 < source.length ) {
          pos++;
          value += source[pos];
        } else {
          if (source[pos] === '\n') line++;
          value += source[pos];
        }
        pos++;
      }
      pos++; // closing quote
      tokens.push({ kind: 'string', value, line });
      continue;
    }

    // Variable ($name)
    if (ch === '$') {
      pos++;
      let name = '';
      while (pos < source.length && /[a-zA-Z0-9_]/.test(source[pos])) {
        name += source[pos];
        pos++;
      }
      tokens.push({ kind: 'variable', value: '$' + name, line });
      continue;
    }

    // Identifier or number (anything that's not special)
    if (IDENTIFIER_START_PATTERN.test(ch)) {
      let value = '';
      while (
        pos < source.length &&
        IDENTIFIER_CONTINUE_PATTERN.test(source[pos]) &&
        source[pos] !== ';' &&
        source[pos] !== '{' &&
        source[pos] !== '}'
      ) {
        value += source[pos];
        pos++;
      }

      // Determine token kind
      if (/^\d+$/.test(value)) {
        tokens.push({ kind: 'number', value, line });
      } else {
        tokens.push({ kind: 'identifier', value, line });
      }
      continue;
    }

    // Unknown character, skip
    pos++;
  }

  tokens.push({ kind: 'eof', value: '', line });
  return tokens;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Parser
// ═══════════════════════════════════════════════════════════════════════════════

const BLOCK_TYPES = new Set([
  'http',
  'server',
  'location',
  'upstream',
  'events',
  'if',
  'types',
  'stream',
  'mail',
  'map',
  'geo',
  'limit_except',
]);

class Parser {
  private tokens: Token[];
  private pos: number;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.pos = 0;
  }

  private peek(): Token {
    return this.tokens[this.pos] ?? { kind: 'eof', value: '', line: 0 };
  }

  private advance(): Token {
    const t = this.tokens[this.pos];
    this.pos++;
    return t;
  }

  private expect(kind: TokenKind): Token {
    const t = this.advance();
    if (t.kind !== kind ) {
      throw new Error(
        `nginx.conf parse error at line ${t.line}: expected ${kind}, got ${t.kind} ('${t.value}')`
      );
    }
    return t;
  }

  parse(): NginxConfig {
    const config: NginxConfig = { directives: [], blocks: [] };

    while (this.peek().kind !== 'eof') {
      this.parseStatement(config.directives, config.blocks);
    }

    return config;
  }

  private parseStatement(
    directives: NginxDirective[],
    blocks: NginxBlock[]
  ): void {
    const t = this.peek();

    if (t.kind === 'close_brace') return;
    if (t.kind === 'eof') return;

    // Read the first token (directive name or block type)
    const nameToken = this.advance();
    const name = nameToken.value;
    const line = nameToken.line;

    // Read arguments until we hit { or ;
    const args: NginxArg[] = [];
    while (
      this.peek().kind !== 'semicolon' &&
      this.peek().kind !== 'open_brace' &&
      this.peek().kind !== 'eof'
    ) {
      const argToken = this.advance();
      if (argToken.kind === 'variable' ) {
        args.push({ kind: 'variable', name: argToken.value.slice(1) });
      } else if (
        argToken.value.startsWith('~') ||
        argToken.value.includes('\\')
      ) {
        args.push({ kind: 'regex', pattern: argToken.value });
      } else {
        args.push({ kind: 'literal', value: argToken.value });
      }
    }

    if (this.peek().kind === 'open_brace') {
      // Block
      this.advance(); // consume {

      const blockType = BLOCK_TYPES.has(name)
        ? (name as NginxBlock['type'])
        : ('http' as NginxBlock['type']); // fallback for unknown blocks

      const block: NginxBlock = {
        type: blockType,
        args,
        directives: [],
        blocks: [],
        line,
      };

      while (this.peek().kind !== 'close_brace' && this.peek().kind !== 'eof') {
        this.parseStatement(block.directives, block.blocks);
      }

      this.expect('close_brace');
      blocks.push(block);
    } else {
      // Directive
      this.expect('semicolon');
      directives.push({ name, args, line });
    }
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Public API
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Parse an nginx.conf string into a typed AST.
 */
export function parseNginxConfig(source: string): NginxConfig {
  const tokens = lex(source);
  const parser = new Parser(tokens);
  return parser.parse();
}

/**
 * Get a literal arg value, or undefined.
 */
export function getDirectiveValue(
  directives: NginxDirective[],
  name: string
): string | undefined {
  const d = directives.find((d) => d.name === name);
  if (!d || d.args.length === 0) return undefined;
  const arg = d.args[0];
  if (arg.kind === 'literal' ) {
    return arg.value;
  }
  if (arg.kind === 'regex' ) {
    return arg.pattern;
  }
  return undefined;
}

/**
 * Get all literal values for a directive (e.g., gzip_types).
 */
export function getDirectiveValues(
  directives: NginxDirective[],
  name: string
): string[] {
  const d = directives.find((d) => d.name === name);
  if (!d) return [];
  return d.args
    .filter(
      (a): a is { kind: 'literal'; value: string } => a.kind === 'literal'
    )
    .map((a) => a.value);
}
