/**
 * @a0n/auth - Rules Engine
 *
 * Firebase-style security rules for declarative access control.
 * Define rules using a simple JSON structure and evaluate them at runtime.
 *
 * @example
 * ```typescript
 * import { SecurityRules, evaluateRules } from '@a0n/auth';
 *
 * const rules: SecurityRules = {
 *   rules: {
 *     // Public sandbox - anyone can read/write
 *     sandbox: {
 *       '.read': true,
 *       '.write': true,
 *     },
 *     // Users can only access their own data
 *     users: {
 *       '$userId': {
 *         '.read': 'auth.did === $userId || resource.public === true',
 *         '.write': 'auth.did === $userId',
 *         // Profile is readable by anyone
 *         profile: {
 *           public: {
 *             '.read': true,
 *           },
 *         },
 *       },
 *     },
 *     // Admin-only area
 *     admin: {
 *       '.read': 'auth.capabilities.includes("admin/read")',
 *       '.write': 'auth.capabilities.includes("admin/write")',
 *     },
 *   },
 * };
 *
 * const context = {
 *   auth: { did: 'did:key:abc123', capabilities: ['user/read'] },
 *   resource: { public: false },
 * };
 *
 * const allowed = evaluateRules(rules, '/users/did:key:abc123/settings', 'read', context);
 * // => true (user accessing their own data)
 * ```
 */

// =============================================================================
// TYPES
// =============================================================================

/**
 * Security rules structure (Firebase-style)
 */
export interface SecurityRules {
  /** Version of the rules schema */
  version?: string;
  /** Root rules object */
  rules: RuleNode;
}

/**
 * A node in the rules tree
 */
export interface RuleNode {
  /** Read permission rule (boolean or expression) */
  '.read'?: boolean | string;
  /** Write permission rule (boolean or expression) */
  '.write'?: boolean | string;
  /** Delete permission rule (boolean or expression) */
  '.delete'?: boolean | string;
  /** Admin permission rule (boolean or expression) */
  '.admin'?: boolean | string;
  /** Validation rule for data writes */
  '.validate'?: string;
  /** Index definition for queries */
  '.indexOn'?: string[];
  /** Child rules (path segments or $variables) */
  [key: string]: RuleNode | boolean | string | string[] | undefined;
}

/**
 * Context for rule evaluation
 */
export interface RuleContext {
  /** Authentication information */
  auth?: {
    /** User's DID */
    did?: string;
    /** Granted capabilities */
    capabilities?: string[];
    /** UCAN token claims */
    claims?: Record<string, unknown>;
  };
  /** The resource being accessed */
  resource?: Record<string, unknown>;
  /** New data (for writes) */
  newData?: Record<string, unknown>;
  /** Request metadata */
  request?: {
    time?: number;
    method?: string;
    path?: string;
  };
  /** Custom variables */
  [key: string]: unknown;
}

/**
 * Result of rule evaluation
 */
export interface RuleEvaluationResult {
  /** Whether access is allowed */
  allowed: boolean;
  /** The rule that matched (if any) */
  matchedRule?: string;
  /** Path to the matching rule */
  rulePath?: string;
  /** Captured path variables */
  captures?: Record<string, string>;
  /** Reason for denial (if not allowed) */
  reason?: string;
}

// =============================================================================
// PARSING
// =============================================================================

/**
 * Parse a rules file from JSON
 */
export function parseRules(json: string | object): SecurityRules {
  const data = typeof json === 'string' ? JSON.parse(json) : json;

  if (!data.rules || typeof data.rules !== 'object') {
    throw new Error('Invalid rules: missing "rules" object');
  }

  return {
    version: data.version || '1.0',
    rules: data.rules,
  };
}

/**
 * Validate rules structure
 */
export function validateRules(rules: SecurityRules): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  function validateNode(node: RuleNode, path: string): void {
    for (const [key, value] of Object.entries(node)) {
      // Skip special keys
      if (key.startsWith('.')) {
        if (
          key === '.read' ||
          key === '.write' ||
          key === '.delete' ||
          key === '.admin'
        ) {
          if (typeof value !== 'boolean' && typeof value !== 'string') {
            errors.push(`${path}/${key}: must be boolean or string expression`);
          }
        } else if (key === '.validate') {
          if (typeof value !== 'string') {
            errors.push(`${path}/${key}: must be a string expression`);
          }
        } else if (key === '.indexOn') {
          if (!Array.isArray(value)) {
            errors.push(`${path}/${key}: must be an array of strings`);
          }
        }
        continue;
      }

      // Validate child nodes
      if (typeof value === 'object' && value !== null) {
        validateNode(value as RuleNode, `${path}/${key}`);
      }
    }
  }

  validateNode(rules.rules, '');

  return { valid: errors.length === 0, errors };
}

// =============================================================================
// EVALUATION
// =============================================================================

/**
 * Evaluate rules for a given path and operation
 *
 * @param rules - The security rules
 * @param path - The resource path (e.g., '/users/123/profile')
 * @param operation - The operation ('read', 'write', 'delete', 'admin')
 * @param context - The evaluation context
 * @returns Evaluation result
 */
export function evaluateRules(
  rules: SecurityRules,
  path: string,
  operation: 'read' | 'write' | 'delete' | 'admin',
  context: RuleContext = {}
): RuleEvaluationResult {
  // Normalize path
  const segments = path.split('/').filter((s) => s.length > 0);
  const captures: Record<string, string> = {};

  // Walk down the rules tree
  let currentNode: RuleNode = rules.rules;
  let rulePath = '';
  let lastMatchedRule: { rule: boolean | string; path: string } | null = null;

  // Check root-level rules first
  const rootRule = currentNode[`.${operation}`];
  if (rootRule !== undefined) {
    lastMatchedRule = { rule: rootRule, path: '/' };
  }

  for (let i = 0; i < segments.length; i++) {
    const segment = segments[i];
    rulePath += '/' + segment;

    // Look for exact match first
    let nextNode: RuleNode | undefined = currentNode[segment] as
      | RuleNode
      | undefined;

    // If no exact match, look for wildcard ($variable)
    if (!nextNode) {
      for (const key of Object.keys(currentNode)) {
        if (key.startsWith('$')) {
          nextNode = currentNode[key] as RuleNode;
          captures[key] = segment;
          break;
        }
      }
    }

    // No matching rule node
    if (!nextNode || typeof nextNode !== 'object') {
      break;
    }

    currentNode = nextNode;

    // Check for operation rule at this level
    const rule = currentNode[`.${operation}`];
    if (rule !== undefined) {
      lastMatchedRule = { rule, path: rulePath };
    }
  }

  // No rule found - default deny
  if (!lastMatchedRule) {
    return {
      allowed: false,
      captures,
      reason: `No rule found for ${operation} at ${path}`,
    };
  }

  // Evaluate the rule
  const { rule, path: matchedPath } = lastMatchedRule;

  // Boolean rule
  if (typeof rule === 'boolean') {
    return {
      allowed: rule,
      matchedRule: String(rule),
      rulePath: matchedPath,
      captures,
      reason: rule ? undefined : `Access denied by rule at ${matchedPath}`,
    };
  }

  // Expression rule - evaluate it
  try {
    const result = evaluateExpression(rule, context, captures);
    return {
      allowed: result,
      matchedRule: rule,
      rulePath: matchedPath,
      captures,
      reason: result ? undefined : `Expression "${rule}" evaluated to false`,
    };
  } catch (error) {
    return {
      allowed: false,
      matchedRule: rule,
      rulePath: matchedPath,
      captures,
      reason: `Error evaluating rule: ${
        error instanceof Error ? error.message : String(error)
      }`,
    };
  }
}

/**
 * Evaluate a rule expression
 */
function evaluateExpression(
  expression: string,
  context: RuleContext,
  captures: Record<string, string>
): boolean {
  // Build evaluation context
  const evalContext: Record<string, unknown> = {
    auth: context.auth || null,
    resource: context.resource || null,
    newData: context.newData || null,
    request: context.request || {
      time: Date.now(),
    },
    ...captures,
  };

  // Simple expression evaluator (no eval for security)
  return safeEvaluate(expression, evalContext);
}

/**
 * Safe expression evaluator (no eval)
 *
 * Supports:
 * - Property access (auth.did, resource.public)
 * - Comparisons (===, !==, ==, !=, >, <, >=, <=)
 * - Boolean operators (&&, ||, !)
 * - Method calls (.includes(), .startsWith(), .endsWith())
 * - Null checks (auth !== null)
 * - Literals (true, false, null, strings, numbers)
 */
function safeEvaluate(
  expression: string,
  context: Record<string, unknown>
): boolean {
  // Tokenize
  const trimmed = expression.trim();

  // Handle boolean literals
  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;

  // Handle NOT operator
  if (trimmed.startsWith('!') && !trimmed.startsWith('!=')) {
    return !safeEvaluate(trimmed.slice(1), context);
  }

  // Handle AND (&&)
  const andParts = splitByOperator(trimmed, '&&');
  if (andParts.length > 1) {
    return andParts.every((part) => safeEvaluate(part, context));
  }

  // Handle OR (||)
  const orParts = splitByOperator(trimmed, '||');
  if (orParts.length > 1) {
    return orParts.some((part) => safeEvaluate(part, context));
  }

  // Handle comparisons
  const comparisonMatch = trimmed.match(
    /^(.+?)\s*(===|!==|==|!=|>=|<=|>|<)\s*(.+)$/
  );
  if (comparisonMatch) {
    const [, left, operator, right] = comparisonMatch;
    const leftValue = resolveValue(left.trim(), context);
    const rightValue = resolveValue(right.trim(), context);

    switch (operator) {
      case '===':
        return leftValue === rightValue;
      case '!==':
        return leftValue !== rightValue;
      case '==':
        return leftValue == rightValue;
      case '!=':
        return leftValue != rightValue;
      case '>':
        return (leftValue as number) > (rightValue as number);
      case '<':
        return (leftValue as number) < (rightValue as number);
      case '>=':
        return (leftValue as number) >= (rightValue as number);
      case '<=':
        return (leftValue as number) <= (rightValue as number);
    }
  }

  // Handle method calls (.includes(), .startsWith(), etc.)
  const methodMatch = trimmed.match(
    /^(.+)\.(includes|startsWith|endsWith)\((.+)\)$/
  );
  if (methodMatch) {
    const [, target, method, arg] = methodMatch;
    const targetValue = resolveValue(target.trim(), context);
    const argValue = resolveValue(arg.trim(), context);

    if (Array.isArray(targetValue)) {
      if (method === 'includes') {
        return targetValue.includes(argValue);
      }
    } else if (typeof targetValue === 'string') {
      if (method === 'includes')
        return targetValue.includes(argValue as string);
      if (method === 'startsWith')
        return targetValue.startsWith(argValue as string);
      if (method === 'endsWith')
        return targetValue.endsWith(argValue as string);
    }

    return false;
  }

  // Handle parentheses
  if (trimmed.startsWith('(') && trimmed.endsWith(')')) {
    return safeEvaluate(trimmed.slice(1, -1), context);
  }

  // Default: resolve as boolean value
  const value = resolveValue(trimmed, context);
  return Boolean(value);
}

/**
 * Split expression by operator, respecting parentheses
 */
function splitByOperator(expression: string, operator: string): string[] {
  const parts: string[] = [];
  let current = '';
  let depth = 0;
  let i = 0;

  while (i < expression.length) {
    const char = expression[i];

    if (char === '(') depth++;
    else if (char === ')') depth--;

    if (depth === 0 && expression.slice(i, i + operator.length) === operator) {
      parts.push(current.trim());
      current = '';
      i += operator.length;
      continue;
    }

    current += char;
    i++;
  }

  if (current.trim()) {
    parts.push(current.trim());
  }

  return parts;
}

/**
 * Resolve a value from the context
 */
function resolveValue(
  expression: string,
  context: Record<string, unknown>
): unknown {
  const trimmed = expression.trim();

  // String literal
  if (
    (trimmed.startsWith("'") && trimmed.endsWith("'")) ||
    (trimmed.startsWith('"') && trimmed.endsWith('"'))
  ) {
    return trimmed.slice(1, -1);
  }

  // Number literal
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
    return parseFloat(trimmed);
  }

  // Boolean/null literals
  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;
  if (trimmed === 'null') return null;
  if (trimmed === 'undefined') return undefined;

  // Variable starting with $ (captured path segment)
  if (trimmed.startsWith('$')) {
    return context[trimmed];
  }

  // Property path (auth.did, resource.public, etc.)
  const parts = trimmed.split('.');
  let value: unknown = context;

  for (const part of parts) {
    if (value === null || value === undefined) {
      return undefined;
    }
    value = (value as Record<string, unknown>)[part];
  }

  return value;
}

// =============================================================================
// RULE BUILDERS
// =============================================================================

/**
 * Helper to create rules programmatically
 */
export class RulesBuilder {
  private rules: RuleNode = {};

  /**
   * Set read rule
   */
  read(rule: boolean | string): this {
    this.rules['.read'] = rule;
    return this;
  }

  /**
   * Set write rule
   */
  write(rule: boolean | string): this {
    this.rules['.write'] = rule;
    return this;
  }

  /**
   * Set delete rule
   */
  delete(rule: boolean | string): this {
    this.rules['.delete'] = rule;
    return this;
  }

  /**
   * Set admin rule
   */
  admin(rule: boolean | string): this {
    this.rules['.admin'] = rule;
    return this;
  }

  /**
   * Set validation rule
   */
  validate(rule: string): this {
    this.rules['.validate'] = rule;
    return this;
  }

  /**
   * Add a child path
   */
  child(path: string, builder: RulesBuilder): this {
    this.rules[path] = builder.build().rules;
    return this;
  }

  /**
   * Add a variable path ($userId, etc.)
   */
  variable(name: string, builder: RulesBuilder): this {
    this.rules[`$${name}`] = builder.build().rules;
    return this;
  }

  /**
   * Build the rules object
   */
  build(): SecurityRules {
    return {
      version: '1.0',
      rules: this.rules,
    };
  }
}

/**
 * Create a new rules builder
 */
export function rules(): RulesBuilder {
  return new RulesBuilder();
}

// =============================================================================
// COMMON RULES PATTERNS
// =============================================================================

/**
 * Create rules for a public sandbox area
 */
export function sandboxRules(): RuleNode {
  return {
    '.read': true,
    '.write': true,
    '.delete': true,
  };
}

/**
 * Create rules for user-owned data
 */
export function userOwnedRules(userIdVariable: string = '$userId'): RuleNode {
  return {
    '.read': `auth.did === ${userIdVariable}`,
    '.write': `auth.did === ${userIdVariable}`,
    '.delete': `auth.did === ${userIdVariable}`,
  };
}

/**
 * Create rules for authenticated users only
 */
export function authenticatedRules(): RuleNode {
  return {
    '.read': 'auth !== null && auth.did !== null',
    '.write': 'auth !== null && auth.did !== null',
  };
}

/**
 * Create rules for admin-only access
 */
export function adminOnlyRules(capability: string = 'admin'): RuleNode {
  return {
    '.read': `auth.capabilities.includes("${capability}/read")`,
    '.write': `auth.capabilities.includes("${capability}/write")`,
    '.admin': `auth.capabilities.includes("${capability}/admin")`,
  };
}

/**
 * Create read-only rules
 */
export function readOnlyRules(readRule: boolean | string = true): RuleNode {
  return {
    '.read': readRule,
    '.write': false,
    '.delete': false,
  };
}

// =============================================================================
// UTILITY
// =============================================================================

/**
 * Merge multiple rules objects
 */
export function mergeRules(...rulesList: SecurityRules[]): SecurityRules {
  const merged: RuleNode = {};

  for (const rules of rulesList) {
    deepMerge(merged, rules.rules);
  }

  return {
    version: '1.0',
    rules: merged,
  };
}

function deepMerge(target: RuleNode, source: RuleNode): void {
  for (const [key, value] of Object.entries(source)) {
    if (
      typeof value === 'object' &&
      value !== null &&
      !Array.isArray(value) &&
      !key.startsWith('.')
    ) {
      if (!target[key] || typeof target[key] !== 'object') {
        target[key] = {};
      }
      deepMerge(target[key] as RuleNode, value as RuleNode);
    } else {
      target[key] = value;
    }
  }
}

/**
 * Generate rules documentation
 */
export function generateRulesDoc(rules: SecurityRules): string {
  const lines: string[] = ['# Security Rules', ''];

  function documentNode(node: RuleNode, path: string, indent: number): void {
    const prefix = '  '.repeat(indent);

    for (const [key, value] of Object.entries(node)) {
      if (key.startsWith('.')) {
        lines.push(`${prefix}- **${key}**: \`${value}\``);
      } else if (typeof value === 'object' && value !== null) {
        lines.push(`${prefix}## ${path}${key}/`);
        documentNode(value as RuleNode, `${path}${key}/`, indent + 1);
      }
    }
  }

  documentNode(rules.rules, '/', 0);

  return lines.join('\n');
}
