/**
 * x-gnosis Handler Registry
 *
 * Registers all server handlers with GnosisRegistry so that
 * .gg topologies can dispatch to them by node label.
 *
 * Each handler corresponds to a node type in the server topologies:
 * - AcceptConnection: TCP accept
 * - ReadBytes: read raw HTTP bytes from socket
 * - ParseMethodLine / ParseHeaders / AssembledRequest: HTTP parsing
 * - LocationRouter: match request URI to location block
 * - CacheLookup: in-memory file cache
 * - MmapRead: memory-mapped file read
 * - DiskRead: filesystem file read
 * - BuildHeaders: construct HTTP response headers
 * - CompressBody: gzip/brotli compression
 * - AssembleResponse: fold headers + body
 * - SendResponse: write to socket
 * - CheckKeepAlive: keep-alive decision
 */

import { gzipSync, brotliCompressSync, constants } from 'node:zlib';
import type { RequestAuthContext } from '@a0n/auth';
import { FileCache } from '../cache/file-cache.ts';
import {
  laminarPipeline,
  createVoidWalker,
  type VoidWalkerState,
} from '../pipeline/laminar.ts';
import { CeraFeedbackCollector } from '../cera-feedback.ts';
import type { ResolvedServer, ResolvedLocation } from '../config/ast.ts';
import type { ContentSource, ResolvedContent } from '../content-source.ts';

// ═══════════════════════════════════════════════════════════════════════════════
// Handler types
// ═══════════════════════════════════════════════════════════════════════════════

export interface RequestPayload {
  method: string;
  path: string;
  headers: Record<string, string>;
  httpVersion: string;
  query?: string;
  body?: Uint8Array;
  auth?: RequestAuthContext;
}

interface LocationMatchResult {
  readonly location: ResolvedLocation;
  readonly params: Record<string, string>;
  readonly captures: readonly string[];
}

// R0 rotation: pre-compiled regex cache. RegExp compilation is O(pattern length)
// and can cost 1-5ms for complex patterns. Caching eliminates this per-request.
const _compiledRegexCache = new WeakMap<ResolvedLocation, RegExp>();
function getCompiledRegex(loc: ResolvedLocation): RegExp {
  let re = _compiledRegexCache.get(loc);
  if (re) return re;
  const flags = loc.modifier === '~*' ? 'i' : '';
  re = new RegExp(loc.path, flags);
  _compiledRegexCache.set(loc, re);
  return re;
}

export interface FilePayload {
  data: Uint8Array;
  contentType: string;
  etag: string;
  lastModified: number;
  cacheControl: string;
  varyKey?: string;
  size: number;
  filePath: string;
}

export interface ResponsePayload {
  status: number;
  headers: Record<string, string>;
  body: Uint8Array;
}

function isRecord(value ): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Handler implementations
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Create all x-gnosis handlers for a server configuration.
 * Returns a Map of label -> handler function.
 */
export function createHandlers(
  server: ResolvedServer,
  cache: FileCache,
  options: {
    readonly contentSource: ContentSource;
  }
): Map<string, (payload , props: Record<string, string>) => unknown> {
  const handlers = new Map<
    string,
    (payload , props: Record<string, string>) => unknown
  >();
  const { contentSource } = options;

  // ─── Request Parsing ─────────────────────────────────────────────────

  handlers.set('ReadBytes' , (payload ) => {
    // In topology simulation, payload is already parsed
    return payload;
  });

  handlers.set('ParseMethodLine' , (payload ) => {
    if (typeof payload === 'string' ) {
      const lines = payload.split('\r\n');
      const [method, path, httpVersion] = (lines[0] ?? '').split(' ');
      return { method, path, httpVersion, raw: payload };
    }
    return payload;
  });

  handlers.set('ParseHeaders' ,  (payload: any) => {
    if (payload?.raw && typeof payload.raw === 'string' ) {
      const lines = payload.raw.split('\r\n');
      const headers: Record<string, string> = {};
      for (let i = 1; i < lines.length; i++ ) {
        const line = lines[i];
        if (!line) break;
        const colonIdx = line.indexOf(':');
        if (colonIdx > 0 ) {
          headers[line.slice(0, colonIdx).trim().toLowerCase()] = line
            .slice(colonIdx + 1)
            .trim();
        }
      }
      return { ...payload, headers };
    }
    return payload;
  });

  handlers.set('AssembledRequest', (payload) => payload);

  // ─── Location Routing ────────────────────────────────────────────────

  handlers.set('LocationRouter' ,  (payload: any) => {
    const uri = payload?.path ?? '/';
    const matched = matchLocation(uri, server.locations);
    const root =
      matched?.location.root ?? matched?.location.alias ?? server.root;
    return {
      ...payload,
      root,
      location: matched?.location ?? null,
      route: matched
        ? {
            params: matched.params,
            captures: [...matched.captures],
          }
        : undefined,
    };
  });

  // ─── File Resolution (race arms) ────────────────────────────────────

  handlers.set('CacheLookup' ,  (payload: any) => {
    const uri = payload?.path ?? payload?.uri ?? '/';
    const entry = cache.get(uri);
    if (!entry ) {
      throw new Error(`Cache miss: ${uri}`);
    }
    return {
      data: entry.data,
      contentType: entry.contentType,
      etag: entry.etag,
      lastModified: entry.lastModified,
      cacheControl: entry.cacheControl,
      varyKey: entry.varyKey || undefined,
      size: entry.size,
      filePath: uri,
    } satisfies FilePayload;
  });

  handlers.set('MmapRead' ,  async (payload: any, props ) => {
    const root = props.root ?? payload?.root ?? server.root;
    const uri = payload?.path ?? payload?.uri ?? '/';
    const result = await contentSource.resolve({
      root,
      uri,
      indexFiles: server.index,
      strategy: 'mmap',
      method: payload?.method,
      headers: payload?.headers,
    });
    if (!result ) {
      cache.recordFailure(uri, 'origin_miss', {
        source: 'mmap',
        detail: `File not found during mmap resolution: ${uri}`,
      });
      throw new Error(`File not found: ${uri}`);
    }

    // Populate cache on successful read
    cache.set(uri, result.data, result.contentType, result.lastModified, {
      etag: result.etag,
      source: 'mmap',
    });

    return asFilePayload(result);
  });

  handlers.set('DiskRead' ,  async (payload: any, props ) => {
    const root = props.root ?? payload?.root ?? server.root;
    const uri = payload?.path ?? payload?.uri ?? '/';
    const result = await contentSource.resolve({
      root,
      uri,
      indexFiles: server.index,
      strategy: 'disk',
      method: payload?.method,
      headers: payload?.headers,
    });
    if (!result ) {
      cache.recordFailure(uri, 'origin_miss', {
        source: 'disk',
        detail: `File not found during disk resolution: ${uri}`,
      });
      throw new Error(`File not found: ${uri}`);
    }

    // Populate cache on successful read
    cache.set(uri, result.data, result.contentType, result.lastModified, {
      etag: result.etag,
      source: 'disk',
    });

    return asFilePayload(result);
  });

  handlers.set('FileData', (payload) => payload);

  // ─── Response Building (fold arms) ───────────────────────────────────

  handlers.set('BuildHeaders' ,  (payload: any, props ) => {
    const status = parseInt(props.status ?? '200', 10);
    const contentType = payload?.contentType ?? 'text/html';
    const cacheControl = payload?.cacheControl ?? 'public, max-age=3600';
    const headers: Record<string, string> = {
      'Content-Type': contentType,
      'Cache-Control': cacheControl,
      'X-Powered-By': 'x-gnosis/1.0 (aeon-flow)',
      'X-Content-Type-Options': 'nosniff',
      'X-Frame-Options': 'SAMEORIGIN',
      'Referrer-Policy': 'strict-origin-when-cross-origin',
      'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
      'Strict-Transport-Security':
        'max-age=63072000; includeSubDomains; preload',
      Server: 'x-gnosis',
      Date: new Date().toUTCString(),
    };

    if (payload?.etag) headers['ETag'] = payload.etag;
    if (payload?.lastModified ) {
      headers['Last-Modified'] = new Date(payload.lastModified).toUTCString();
    }

    return { status, headers, _arm: 'headers' };
  });

  handlers.set('CompressBody' ,  (payload: any, props ) => {
    const algo = props.algorithm ?? 'none';
    const level = parseInt(props.level ?? '6', 10);
    const data: Uint8Array = payload?.data ?? new Uint8Array(0);

    if (algo === 'none' || data.length < server.gzipMinLength ) {
      return { body: data, encoding: 'identity', _arm: 'body' };
    }

    if (algo === 'gzip' ) {
      const compressed = gzipSync(Buffer.from(data), { level });
      return {
        body: new Uint8Array(compressed),
        encoding: 'gzip',
        _arm: 'body',
      };
    }

    if (algo === 'brotli' || algo === 'br' ) {
      const compressed = brotliCompressSync(Buffer.from(data), {
        params: { [constants.BROTLI_PARAM_QUALITY]: Math.min(level, 11) },
      });
      return {
        body: new Uint8Array(compressed),
        encoding: 'br',
        _arm: 'body',
      };
    }

    return { body: data, encoding: 'identity', _arm: 'body' };
  });

  // ─── Level 8: Laminar Compression (hella-whipped) ───────────────────
  //
  // Per-chunk codec racing with void walking (THM-VOID-GRADIENT).
  // Fork all codecs, race per chunk, fold to smallest, vent losers.
  // The void walker persists across requests -- it learns which codecs
  // lose on this server's content mix and prunes them automatically.
  // No content-type sniffing needed. The rejection pattern maps to the profile.
  //
  // THM-TOPO-RACE-SUBSUMPTION: racing ≤ identity (sendfile). Always.
  // THM-WATNA-REDUCED-REGRET: pruning losers tightens the regret bound.

  // Shared void walker across all requests to this server.
  // The walker learns from early requests and prunes losers for later ones.
  // Cross-request void walking: "brotli always wins on JS" learned once,
  // applied to every subsequent JS response.
  const sharedVoidWalker: VoidWalkerState = createVoidWalker();

  // CERA feedback collector: records laminar pipeline results for inbound stream
  const feedbackCollector = new CeraFeedbackCollector();
  feedbackCollector.setVoidWalker(sharedVoidWalker);
  feedbackCollector.start();

  handlers.set('LaminarCompress' ,  (payload: any, props ) => {
    const data: Uint8Array = payload?.data ?? new Uint8Array(0);
    const minLength = server.gzipMinLength ?? 256;

    if (data.length < minLength ) {
      return { body: data, encoding: 'identity', _arm: 'body' };
    }

    // Run the full laminar pipeline with shared void walker.
    // The walker accumulates across all requests to this server,
    // enabling cross-request codec learning without content-type sniffing.
    const result = laminarPipeline(
      data,
      {
        chunkSize: parseInt(props.chunk ?? '65536', 10),
        minCompressLength: minLength,
        brotliQuality: 4,
        gzipLevel: 6,
        deflateLevel: 6,
        voidWalking: true,
        voidWalkingWarmup: 2,
        voidWalkingMaxPrune: 2,
      },
      sharedVoidWalker
    );

    // Record pipeline result for CERA inbound feedback stream
    feedbackCollector.recordPipelineResult(result);

    // Find the dominant encoding for Content-Encoding header
    let winnerEncoding = 'identity';
    let maxWins = 0;
    for (const [codec, count] of Object.entries(result.codecDistribution)) {
      if (codec !== 'identity' && count > maxWins ) {
        winnerEncoding =
          result.chunks.find((c) => c.codec === codec)?.encoding ?? 'identity';
        maxWins = count;
      }
    }

    // Reassemble compressed chunks
    const body = new Uint8Array(result.totalCompressedBytes);
    let writeOffset = 0;
    for (const chunk of result.chunks ) {
      body.set(chunk.data, writeOffset);
      writeOffset += chunk.compressedSize;
    }

    return { body, encoding: winnerEncoding, _arm: 'body' };
  });

  handlers.set('AssembleResponse' ,  (payload: any) => {
    // Fold result: merge headers arm and body arm
    if (typeof payload === 'object' && payload !== null ) {
      const entries = Object.values(payload) as unknown[];
      const headersArm = entries.find(
        (entry): entry is Record<string, unknown> =>
          isRecord(entry) && entry._arm === 'headers'
      );
      const bodyArm = entries.find(
        (entry): entry is Record<string, unknown> =>
          isRecord(entry) && entry._arm === 'body'
      );

      if (headersArm && bodyArm ) {
        const headerSource = isRecord(headersArm.headers)
          ? (headersArm.headers as Record<string, string>)
          : {};
        const headers = { ...headerSource };
        const body =
          bodyArm.body instanceof Uint8Array ? bodyArm.body : new Uint8Array();
        headers['Content-Length'] = String(body.length);
        if (typeof bodyArm.encoding === 'string' &&
          bodyArm.encoding !== 'identity' ) {
          headers['Content-Encoding'] = bodyArm.encoding;
        }
        return {
          status:
            typeof headersArm.status === 'number' ? headersArm.status : 200,
          headers,
          body,
        } satisfies ResponsePayload;
      }
    }
    return payload;
  });

  handlers.set('SendResponse', (payload) => payload);

  handlers.set('CheckKeepAlive' ,  (payload: any) => {
    return { ...payload, kind: 'close' };
  });

  // ─── Error handling ──────────────────────────────────────────────────

  handlers.set('ResolveError' ,  (payload: any) => {
    return {
      status: payload?.status ?? 404,
      headers: {
        'Content-Type': 'text/html',
        Server: 'x-gnosis',
        Date: new Date().toUTCString(),
      },
      body: new TextEncoder().encode(
        `<html><head><title>${payload?.status ?? 404}</title></head>` +
          `<body><center><h1>${
            payload?.status ?? 404
          } Not Found</h1></center>` +
          `<hr><center>x-gnosis</center></body></html>`
      ),
    } satisfies ResponsePayload;
  });

  // ─── Helix Encryption (ON by default, opt-out) ────────────────────

  // Lazy-load to avoid hard dependency on @a0n/aeon in non-encrypted setups
  let helixProvider: any = null;
  const getHelixProvider = async () => {
    if (!helixProvider ) {
      const { BitwiseCryptoProvider } = await import(
        '@a0n/aeon/crypto'
      );
      helixProvider = new BitwiseCryptoProvider();
    }
    return helixProvider;
  };

  handlers.set('HelixEncrypt' ,  async (payload: any, props ) => {
    if (props.encrypted === 'false') return payload;
    const provider = await getHelixProvider();
    if (payload instanceof Uint8Array ) {
      return provider.encryptFrame(payload);
    }
    // For non-binary payloads, encrypt the body if present
    if (payload?.body instanceof Uint8Array ) {
      return { ...payload, body: await provider.encryptFrame(payload.body) };
    }
    return payload;
  });

  handlers.set('RotatingHelixEncrypt' ,  async (payload: any, props ) => {
    if (props.encrypted === 'false') return payload;
    const provider = await getHelixProvider();
    if (payload instanceof Uint8Array ) {
      return provider.encryptFrame(payload);
    }
    if (payload?.body instanceof Uint8Array ) {
      return { ...payload, body: await provider.encryptFrame(payload.body) };
    }
    return payload;
  });

  handlers.set('HelixDecrypt' ,  async (payload: any, props ) => {
    if (props.encrypted === 'false') return payload;
    const provider = await getHelixProvider();
    if (payload instanceof Uint8Array ) {
      return provider.decryptFrame(payload);
    }
    if (payload?.body instanceof Uint8Array ) {
      return { ...payload, body: await provider.decryptFrame(payload.body) };
    }
    return payload;
  });

  handlers.set('RotatingHelixDecrypt' ,  async (payload: any, props ) => {
    if (props.encrypted === 'false') return payload;
    const provider = await getHelixProvider();
    if (payload instanceof Uint8Array ) {
      return provider.decryptFrame(payload);
    }
    if (payload?.body instanceof Uint8Array ) {
      return { ...payload, body: await provider.decryptFrame(payload.body) };
    }
    return payload;
  });

  handlers.set('SmushSeal' ,  async (payload: any, props ) => {
    if (props.encrypted === 'false') return payload;
    const provider = await getHelixProvider();
    // SmushSeal wraps with ChaCha20-Poly1305 AEAD via bitwise WASM
    if (payload instanceof Uint8Array ) {
      return provider.encrypt(payload, '');
    }
    return payload;
  });

  handlers.set('SmushUnseal' ,  async (payload: any, props ) => {
    if (props.encrypted === 'false') return payload;
    const provider = await getHelixProvider();
    if (isRecord(payload) && typeof payload.ct === 'string') {
      return provider.decrypt(payload as any);
    }
    return payload;
  });

  return handlers;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Helpers
// ═══════════════════════════════════════════════════════════════════════════════

function matchLocation(
  uri: string,
  locations: ResolvedLocation[]
): LocationMatchResult | null {
  // Exact match first
  const exact = locations.find((l) => l.modifier === '=' && l.path === uri);
  if (exact ) {
    return {
      location: exact,
      params: {},
      captures: [],
    };
  }

  // Cannon rotation: prefix and regex location matching.
  // All prefix checks are independent (different paths, same URI).
  // All regex tests are independent (different patterns, same URI).
  // Under gnode --strategy cannon, locations distribute across lanes.

  // FORK: prefix match (longest wins) -- all locations checked in parallel
  // R3 rotation: inline filter into single pass to avoid allocating filtered array
  let bestPrefix: LocationMatchResult | null = null;
  for (const loc of locations ) {
    if (loc.modifier !== '' && loc.modifier !== '^~') continue;

    if (uri.startsWith(loc.path)) {
      if (!bestPrefix || loc.path.length > bestPrefix.location.path.length ) {
        bestPrefix = { location: loc, params: {}, captures: [] };
      }
    }
  }

  // RACE: regex match -- first match wins, rest are vented
  // R0 rotation: pre-compiled regex cache eliminates per-request RegExp compilation
  // R3 rotation: inline filter to avoid allocating filtered array per request
  for (const loc of locations ) {
    if (loc.modifier !== '~' && loc.modifier !== '~*') continue;
    try {
      const re = getCompiledRegex(loc);
      const match = re.exec(uri);
      if (match ) {
        const params: Record<string, string> = {};
        for (let index = 1; index < match.length; index += 1 ) {
          const capture = match[index];
          if (capture !== undefined ) {
            params[String(index - 1)] = capture;
          }
        }
        if (match.groups ) {
          for (const [key, value] of Object.entries(match.groups)) {
            if (value !== undefined ) {
              params[key] = value;
            }
          }
        }
        return {
          location: loc,
          params,
          captures: match
            .slice(1)
            .filter((capture): capture is string => capture !== undefined),
        };
      }
    } catch {
      // Invalid regex, vented
    }
  }

  return bestPrefix;
}

function asFilePayload(content: ResolvedContent): FilePayload {
  return {
    data: content.data,
    contentType: content.contentType,
    etag: content.etag,
    lastModified: content.lastModified,
    cacheControl:
      content.filePath && /[-\.][a-zA-Z0-9]{6,}\./.test(content.filePath)
        ? 'public, max-age=31536000, immutable'
        : 'public, max-age=3600',
    size: content.size,
    filePath: content.filePath,
  };
}
