/**
 * Mesh Atomized Encryption (mesh-AE) — distributed encryption shroud
 *
 * Splits plaintext across `atomizationFactor` shards; each shard is encrypted with
 * an independent AES-256-GCM key derived from the master key (HKDF-SHA256).
 * Intended for distributed settings where epistemic gap / hidden forks justify
 * multiple independent ciphertext atoms (see `MESH_SHROUD.md`).
 *
 * - **mesh-ae-v2** (current): AES-256-GCM + per-shard HKDF; use for all new data.
 * - **mesh-ae-v1** (legacy): XOR stream + 16-bit checksum; decrypt-only for migration.
 */

import {
  createCipheriv,
  createDecipheriv,
  createHash,
  hkdfSync,
  randomBytes,
} from 'node:crypto';

export interface AtomizationInputs {
  observableDeficit: number;
  reconciledDeficit: number;
  hiddenForks?: number;
  maxAtoms?: number;
}

/** Legacy envelope — decrypt only for existing ciphertext. */
export interface MeshAtomizedEnvelopeV1 {
  version: 'mesh-ae-v1';
  atomizationFactor: number;
  nonce: string;
  shardCount: number;
  shardChecksums: number[];
  shards: string[];
}

/** AEAD-backed envelope — default for `meshAtomizedEncrypt`. */
export interface MeshAtomizedEnvelopeV2 {
  version: 'mesh-ae-v2';
  atomizationFactor: number;
  nonce: string;
  shardCount: number;
  /** Base64(iv12 ∥ ciphertext ∥ tag16) per shard, AES-256-GCM. */
  shards: string[];
}

export type MeshAtomizedEnvelope = MeshAtomizedEnvelopeV1 | MeshAtomizedEnvelopeV2;

const DEFAULT_MAX_ATOMS = 256;

const AES_IV_BYTES = 12;
const AES_TAG_BYTES = 16;
const AES_KEY_BYTES = 32;
const HKDF_SALT_BYTES = 16;

function assertFiniteNonNegative(value: number, field: string): void {
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`[mesh-atomized] ${field} must be a non-negative finite number`);
  }
}

function assertMasterKey(key: Uint8Array): void {
  if (key.length === 0) {
    throw new Error('[mesh-atomized] key must not be empty');
  }
  if (key.length < 16) {
    throw new Error(
      '[mesh-atomized] master key must be at least 16 bytes (prefer 32 random bytes for AES-256-HKDF security)'
    );
  }
}

function fnv1a32(data: Uint8Array): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < data.length; i += 1) {
    hash ^= data[i];
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function xorshift32(seed: number): () => number {
  let x = seed | 0;
  if (x === 0) x = 0x9e3779b9;
  return () => {
    x ^= x << 13;
    x ^= x >>> 17;
    x ^= x << 5;
    return x >>> 0;
  };
}

function deriveShardKeystreamV1(
  key: Uint8Array,
  shardIndex: number,
  nonce: string,
  length: number
): Uint8Array {
  const nonceBytes = new TextEncoder().encode(nonce);
  const composite = new Uint8Array(key.length + nonceBytes.length + 4);
  composite.set(key, 0);
  composite.set(nonceBytes, key.length);
  composite[key.length + nonceBytes.length] = shardIndex & 0xff;
  composite[key.length + nonceBytes.length + 1] = (shardIndex >>> 8) & 0xff;
  composite[key.length + nonceBytes.length + 2] = (shardIndex >>> 16) & 0xff;
  composite[key.length + nonceBytes.length + 3] = (shardIndex >>> 24) & 0xff;

  const rand = xorshift32(fnv1a32(composite));
  const out = new Uint8Array(length);
  for (let i = 0; i < length; i += 1) {
    out[i] = rand() & 0xff;
  }
  return out;
}

function deriveShardKeyV2(masterKey: Uint8Array, shardIndex: number, envelopeNonce: string): Uint8Array {
  const salt = createHash('sha256').update(envelopeNonce, 'utf8').digest().subarray(0, HKDF_SALT_BYTES);
  const info = new TextEncoder().encode(`mesh-ae-v2/shard/${shardIndex}`);
  return new Uint8Array(hkdfSync('sha256', masterKey, salt, info, AES_KEY_BYTES));
}

function encryptShardAesGcm(plaintext: Uint8Array, key: Uint8Array): Uint8Array {
  const iv = randomBytes(AES_IV_BYTES);
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  const enc = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return new Uint8Array(Buffer.concat([iv, enc, tag]));
}

function decryptShardAesGcm(blob: Uint8Array, key: Uint8Array): Uint8Array {
  if (blob.length < AES_IV_BYTES + AES_TAG_BYTES) {
    throw new Error('[mesh-atomized] v2 shard blob too short');
  }
  const iv = blob.subarray(0, AES_IV_BYTES);
  const tag = blob.subarray(blob.length - AES_TAG_BYTES);
  const enc = blob.subarray(AES_IV_BYTES, blob.length - AES_TAG_BYTES);
  const decipher = createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(tag);
  return new Uint8Array(Buffer.concat([decipher.update(enc), decipher.final()]));
}

function checksum16(bytes: Uint8Array): number {
  let sum = 0;
  for (let i = 0; i < bytes.length; i += 1) {
    sum = (sum + bytes[i]) & 0xffff;
  }
  return sum;
}

function xorBytes(a: Uint8Array, b: Uint8Array): Uint8Array {
  const out = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i += 1) {
    out[i] = a[i] ^ b[i];
  }
  return out;
}

function toBase64(data: Uint8Array): string {
  return Buffer.from(data).toString('base64');
}

function fromBase64(data: string): Uint8Array {
  return new Uint8Array(Buffer.from(data, 'base64'));
}

function chunkRoundRobin(data: Uint8Array, shards: number): Uint8Array[] {
  const buckets: number[][] = Array.from({ length: shards }, () => []);
  for (let i = 0; i < data.length; i += 1) {
    buckets[i % shards].push(data[i]);
  }
  return buckets.map((bucket) => Uint8Array.from(bucket));
}

function mergeRoundRobin(chunks: Uint8Array[]): Uint8Array {
  const totalLength = chunks.reduce((sum, c) => sum + c.length, 0);
  const out = new Uint8Array(totalLength);
  const offsets = new Array(chunks.length).fill(0);

  for (let i = 0; i < totalLength; i += 1) {
    const shard = i % chunks.length;
    out[i] = chunks[shard][offsets[shard]];
    offsets[shard] += 1;
  }

  return out;
}

export function resolveAtomizationFactor(inputs: AtomizationInputs): number {
  const { observableDeficit, reconciledDeficit, hiddenForks, maxAtoms = DEFAULT_MAX_ATOMS } = inputs;
  assertFiniteNonNegative(observableDeficit, 'observableDeficit');
  assertFiniteNonNegative(reconciledDeficit, 'reconciledDeficit');
  assertFiniteNonNegative(maxAtoms, 'maxAtoms');

  const unknowabilityGap = Math.max(0, Math.floor(observableDeficit - reconciledDeficit));
  const hiddenCap = hiddenForks == null ? Number.POSITIVE_INFINITY : Math.max(0, Math.floor(hiddenForks));

  return Math.max(1, Math.min(unknowabilityGap, hiddenCap, Math.floor(maxAtoms)));
}

/**
 * Encrypt with **mesh-ae-v2** (AES-256-GCM per shard, HKDF-derived keys).
 */
export function meshAtomizedEncrypt(
  plaintext: Uint8Array,
  key: Uint8Array,
  atomizationFactor: number,
  nonce: string = `mesh-ae-${Date.now().toString(36)}`
): MeshAtomizedEnvelopeV2 {
  assertFiniteNonNegative(atomizationFactor, 'atomizationFactor');
  assertMasterKey(key);

  const shardCount = Math.max(1, Math.floor(atomizationFactor));
  const plainShards = chunkRoundRobin(plaintext, shardCount);
  const cipherShards: string[] = [];

  for (let i = 0; i < plainShards.length; i += 1) {
    const shardKey = deriveShardKeyV2(key, i, nonce);
    const blob = encryptShardAesGcm(plainShards[i], shardKey);
    cipherShards.push(toBase64(blob));
  }

  return {
    version: 'mesh-ae-v2',
    atomizationFactor: shardCount,
    nonce,
    shardCount,
    shards: cipherShards,
  };
}

function decryptV1(envelope: MeshAtomizedEnvelopeV1, key: Uint8Array): Uint8Array {
  if (envelope.shards.length !== envelope.shardCount || envelope.shardChecksums.length !== envelope.shardCount) {
    throw new Error('[mesh-atomized] v1 shard metadata mismatch');
  }
  const plainShards: Uint8Array[] = [];
  for (let i = 0; i < envelope.shardCount; i += 1) {
    const cipher = fromBase64(envelope.shards[i]);
    const stream = deriveShardKeystreamV1(key, i, envelope.nonce, cipher.length);
    const plain = xorBytes(cipher, stream);
    const checksum = checksum16(plain);
    if (checksum !== envelope.shardChecksums[i]) {
      throw new Error(`[mesh-atomized] v1 shard checksum mismatch at index ${i}`);
    }
    plainShards.push(plain);
  }
  return mergeRoundRobin(plainShards);
}

function decryptV2(envelope: MeshAtomizedEnvelopeV2, key: Uint8Array): Uint8Array {
  if (envelope.shards.length !== envelope.shardCount) {
    throw new Error('[mesh-atomized] v2 shard count mismatch');
  }
  assertMasterKey(key);
  const plainShards: Uint8Array[] = [];
  for (let i = 0; i < envelope.shardCount; i += 1) {
    const blob = fromBase64(envelope.shards[i]);
    const shardKey = deriveShardKeyV2(key, i, envelope.nonce);
    const plain = decryptShardAesGcm(blob, shardKey);
    plainShards.push(plain);
  }
  return mergeRoundRobin(plainShards);
}

export function meshAtomizedDecrypt(envelope: MeshAtomizedEnvelope, key: Uint8Array): Uint8Array {
  if (envelope.version === 'mesh-ae-v1') {
    return decryptV1(envelope, key);
  }
  if (envelope.version === 'mesh-ae-v2') {
    return decryptV2(envelope, key);
  }
  throw new Error(`[mesh-atomized] unsupported envelope version: ${String((envelope as MeshAtomizedEnvelope).version)}`);
}
