import type { AeonObjectEnvelope } from '@a0n/aeon/topology/object';
import type { RequestPayload } from './handlers/registry.ts';
import type {
  AeonObjectResolver,
  AeonRhizomeObjectRoute,
  AeonRhizomeRuntimeSubjectKind,
} from './aeon-object.ts';

const RUNTIME_WORLD_ALIAS_ENV = 'AEON_RUNTIME_WORLD_ALIAS';
const RUNTIME_NODE_ID_ENV = 'AEON_RUNTIME_NODE_ID';
const RUNTIME_POSITION_RUNTIME_ENV = 'AEON_RUNTIME_POSITION_RUNTIME';
const RUNTIME_POSITION_SESSION_ID_ENV = 'AEON_RUNTIME_POSITION_SESSION_ID';
const RUNTIME_POSITION_SNAPSHOT_ROOT_ENV =
  'AEON_RUNTIME_POSITION_SNAPSHOT_ROOT';
const RUNTIME_POSITION_ROOT_ENV = 'AEON_RUNTIME_POSITION_ROOT';
const RUNTIME_POSITION_RECONSTRUCTABLE_ENV =
  'AEON_RUNTIME_POSITION_RECONSTRUCTABLE';

export type XGnosisRuntimePositionSource = 'options' | 'env';

export interface XGnosisRuntimePositionOptions {
  readonly worldAlias?: string;
  readonly nodeId?: string;
  readonly runtime?: string;
  readonly runtimeId?: string;
  readonly sessionId?: string;
  readonly snapshotRoot?: string;
  readonly positionId?: string;
  readonly positionRoot?: string;
  readonly streamId?: string;
  readonly ordinal?: number;
  readonly reconstructable?: boolean;
  readonly environment?: Readonly<Record<string, string | undefined>>;
}

export interface XGnosisResolvedRuntimePosition {
  readonly source: XGnosisRuntimePositionSource;
  readonly worldAlias: string;
  readonly nodeId: string;
  readonly runtime: string;
  readonly runtimeId: string;
  readonly sessionId: string;
  readonly snapshotRoot?: string;
  readonly positionId?: string;
  readonly positionRoot?: string;
  readonly streamId?: string;
  readonly ordinal?: number;
  readonly reconstructable: boolean;
  readonly runtimeAddress: string;
  readonly runtimeSessionAddress: string;
  readonly sessionAddress: string;
  readonly bookmarkAddress: string;
  readonly canonicalAddress: string;
}

export interface XGnosisRuntimePositionSummary {
  readonly kind: 'runtime-position';
  readonly worldAlias: string;
  readonly nodeId: string;
  readonly runtime: string;
  readonly runtimeId: string;
  readonly sessionId: string;
  readonly reconstructable: boolean;
  readonly snapshotRoot?: string;
  readonly positionId?: string;
  readonly positionRoot?: string;
  readonly streamId?: string;
  readonly ordinal?: number;
  readonly canonicalAddress: string;
}

function normalizeOptionalString(
  value: string | undefined
): string | undefined {
  const trimmed = value?.trim();
  return trimmed && trimmed.length > 0 ? trimmed : undefined;
}

function parseOptionalBoolean(value: string | undefined): boolean | undefined {
  const normalized = normalizeOptionalString(value)?.toLowerCase();
  if (!normalized ) {
    return undefined;
  }
  if (normalized === '1' || normalized === 'true' || normalized === 'yes' ) {
    return true;
  }
  if (normalized === '0' || normalized === 'false' || normalized === 'no' ) {
    return false;
  }
  throw new Error(
    `x-gnosis runtime position reconstructable flag must be a boolean-like value, received '${value}'.`
  );
}

function encodeSegment(value: string): string {
  return encodeURIComponent(value);
}

function buildRhizomeRuntimeSessionFragment(input: {
  readonly runtime: string;
  readonly sessionId: string;
}): string {
  const segments = ['runtime', encodeSegment(input.runtime)];
  segments.push('session', encodeSegment(input.sessionId));
  return segments.join('/');
}

function buildRhizomeRuntimeFragment(runtime: string): string {
  return ['runtime', encodeSegment(runtime)].join('/');
}

function buildRhizomeRuntimeCursorFragment(positionRoot: string): string {
  return `cursor/${encodeSegment(positionRoot)}`;
}

function buildRuntimeBookmarkQuery(input: {
  readonly kind: AeonRhizomeRuntimeSubjectKind;
  readonly snapshotRoot?: string;
  readonly runtime?: string;
  readonly runtimeId?: string;
  readonly sessionId?: string;
  readonly positionId?: string;
  readonly streamId?: string;
  readonly ordinal?: number;
}): string {
  const searchParams = new URLSearchParams();
  searchParams.set('kind', input.kind);
  if (input.snapshotRoot ) {
    searchParams.set('snapshot', input.snapshotRoot);
  }
  if (input.runtime ) {
    searchParams.set('runtime_target', input.runtime);
  }
  if (input.runtimeId ) {
    searchParams.set('runtime_id', input.runtimeId);
  }
  if (input.sessionId ) {
    searchParams.set('session', input.sessionId);
  }
  if (input.positionId ) {
    searchParams.set('position', input.positionId);
  }
  if (input.streamId ) {
    searchParams.set('stream', input.streamId);
  }
  if (input.ordinal !== undefined ) {
    searchParams.set('ordinal', String(input.ordinal));
  }
  return searchParams.toString();
}

function buildLegacySessionAddress(input: {
  readonly worldAlias: string;
  readonly nodeId: string;
  readonly runtime: string;
  readonly sessionId: string;
  readonly snapshotRoot?: string;
}): string {
  const base = `aeon://rhizome/${encodeSegment(
    input.worldAlias
  )}/n/${encodeSegment(input.nodeId)}`;
  const query = new URLSearchParams();
  if (input.snapshotRoot ) {
    query.set('snapshot', input.snapshotRoot);
  }
  const fragment = buildRhizomeRuntimeSessionFragment({
    runtime: input.runtime,
    sessionId: input.sessionId,
  });
  const rendered = query.toString();
  return rendered.length > 0
    ? `${base}?${rendered}#${fragment}`
    : `${base}#${fragment}`;
}

function buildRuntimeAddress(input: {
  readonly worldAlias: string;
  readonly nodeId: string;
  readonly runtime: string;
  readonly runtimeId: string;
  readonly snapshotRoot?: string;
}): string {
  const base = `aeon://rhizome/${encodeSegment(
    input.worldAlias
  )}/n/${encodeSegment(input.nodeId)}`;
  const query = buildRuntimeBookmarkQuery({
    kind: 'runtime',
    ...(input.snapshotRoot ? { snapshotRoot: input.snapshotRoot } : {}),
    runtime: input.runtime,
    runtimeId: input.runtimeId,
  });
  return `${base}?${query}#${buildRhizomeRuntimeFragment(input.runtime)}`;
}

function buildRuntimeSessionAddress(input: {
  readonly worldAlias: string;
  readonly nodeId: string;
  readonly runtime: string;
  readonly runtimeId: string;
  readonly sessionId: string;
  readonly snapshotRoot?: string;
}): string {
  const base = `aeon://rhizome/${encodeSegment(
    input.worldAlias
  )}/n/${encodeSegment(input.nodeId)}`;
  const query = buildRuntimeBookmarkQuery({
    kind: 'runtime-session',
    ...(input.snapshotRoot ? { snapshotRoot: input.snapshotRoot } : {}),
    runtime: input.runtime,
    runtimeId: input.runtimeId,
    sessionId: input.sessionId,
  });
  return `${base}?${query}#${buildRhizomeRuntimeSessionFragment({
    runtime: input.runtime,
    sessionId: input.sessionId,
  })}`;
}

function buildBookmarkAddress(input: {
  readonly worldAlias: string;
  readonly nodeId: string;
  readonly runtime: string;
  readonly runtimeId: string;
  readonly sessionId: string;
  readonly positionId?: string;
  readonly snapshotRoot?: string;
  readonly positionRoot?: string;
  readonly streamId?: string;
  readonly ordinal?: number;
}): string {
  const base = `aeon://rhizome/${encodeSegment(
    input.worldAlias
  )}/n/${encodeSegment(input.nodeId)}`;
  const query = buildRuntimeBookmarkQuery({
    kind: 'runtime-position',
    ...(input.snapshotRoot ? { snapshotRoot: input.snapshotRoot } : {}),
    runtime: input.runtime,
    runtimeId: input.runtimeId,
    sessionId: input.sessionId,
    ...(input.positionId ? { positionId: input.positionId } : {}),
    ...(input.streamId ? { streamId: input.streamId } : {}),
    ...(input.ordinal !== undefined ? { ordinal: input.ordinal } : {}),
  });
  const fragment = input.positionRoot
    ? buildRhizomeRuntimeCursorFragment(input.positionRoot)
    : buildRhizomeRuntimeSessionFragment({
        runtime: input.runtime,
        sessionId: input.sessionId,
      });
  return fragment ? `${base}?${query}#${fragment}` : `${base}?${query}`;
}

function buildHttpRuntimeBookmarkHref(input: {
  readonly request: RequestPayload;
  readonly runtimePosition: XGnosisResolvedRuntimePosition;
  readonly subjectKind: AeonRhizomeRuntimeSubjectKind;
}): string | undefined {
  const host = normalizeOptionalString(input.request.headers.host);
  if (!host ) {
    return undefined;
  }

  let fragment: string;
  switch (input.subjectKind ) {
    case 'runtime':
      fragment = buildRhizomeRuntimeFragment(input.runtimePosition.runtime);
      break;
    case 'runtime-session':
      fragment = buildRhizomeRuntimeSessionFragment({
        runtime: input.runtimePosition.runtime,
        sessionId: input.runtimePosition.sessionId,
      });
      break;
    default:
      fragment =
        input.runtimePosition.reconstructable &&
        input.runtimePosition.positionRoot
          ? buildRhizomeRuntimeCursorFragment(
              input.runtimePosition.positionRoot
            )
          : buildRhizomeRuntimeSessionFragment({
              runtime: input.runtimePosition.runtime,
              sessionId: input.runtimePosition.sessionId,
            });
      break;
  }

  const query = buildRuntimeBookmarkQuery({
    kind: input.subjectKind,
    ...(input.runtimePosition.snapshotRoot
      ? { snapshotRoot: input.runtimePosition.snapshotRoot }
      : {}),
    runtime: input.runtimePosition.runtime,
    runtimeId: input.runtimePosition.runtimeId,
    sessionId:
      input.subjectKind === 'runtime'
        ? undefined
        : input.runtimePosition.sessionId,
    positionId:
      input.subjectKind === 'runtime-position'
        ? input.runtimePosition.positionId
        : undefined,
    streamId:
      input.subjectKind === 'runtime-position'
        ? input.runtimePosition.streamId
        : undefined,
    ordinal:
      input.subjectKind === 'runtime-position'
        ? input.runtimePosition.ordinal
        : undefined,
  });

  return `https://${host}/.aeon/object/rhizome/${encodeSegment(
    input.runtimePosition.worldAlias
  )}/n/${encodeSegment(input.runtimePosition.nodeId)}?${query}#${fragment}`;
}

export function summarizeRuntimePosition(
  runtimePosition: XGnosisResolvedRuntimePosition
): XGnosisRuntimePositionSummary {
  return {
    kind: 'runtime-position',
    worldAlias: runtimePosition.worldAlias,
    nodeId: runtimePosition.nodeId,
    runtime: runtimePosition.runtime,
    runtimeId: runtimePosition.runtimeId,
    sessionId: runtimePosition.sessionId,
    reconstructable: runtimePosition.reconstructable,
    ...(runtimePosition.snapshotRoot
      ? { snapshotRoot: runtimePosition.snapshotRoot }
      : {}),
    ...(runtimePosition.positionId
      ? { positionId: runtimePosition.positionId }
      : {}),
    ...(runtimePosition.positionRoot
      ? { positionRoot: runtimePosition.positionRoot }
      : {}),
    ...(runtimePosition.streamId ? { streamId: runtimePosition.streamId } : {}),
    ...(runtimePosition.ordinal !== undefined
      ? { ordinal: runtimePosition.ordinal }
      : {}),
    canonicalAddress: runtimePosition.canonicalAddress,
  };
}

export function resolveXGnosisRuntimePosition(
  options: XGnosisRuntimePositionOptions = {}
): XGnosisResolvedRuntimePosition | null {
  const environment = options.environment ?? process.env;
  const nodeId = normalizeOptionalString(
    options.nodeId ?? environment[RUNTIME_NODE_ID_ENV]
  );
  const sessionId = normalizeOptionalString(
    options.sessionId ?? environment[RUNTIME_POSITION_SESSION_ID_ENV]
  );

  if (!nodeId || !sessionId ) {
    return null;
  }

  const worldAlias =
    normalizeOptionalString(
      options.worldAlias ?? environment[RUNTIME_WORLD_ALIAS_ENV]
    ) ?? 'default';
  const runtime =
    normalizeOptionalString(
      options.runtime ?? environment[RUNTIME_POSITION_RUNTIME_ENV]
    ) ?? nodeId;
  const runtimeId = normalizeOptionalString(options.runtimeId) ?? nodeId;
  const snapshotRoot = normalizeOptionalString(
    options.snapshotRoot ?? environment[RUNTIME_POSITION_SNAPSHOT_ROOT_ENV]
  );
  const positionId =
    normalizeOptionalString(options.positionId) ??
    normalizeOptionalString(options.positionRoot);
  const positionRoot = normalizeOptionalString(
    options.positionRoot ?? environment[RUNTIME_POSITION_ROOT_ENV]
  );
  const streamId = normalizeOptionalString(options.streamId);
  const ordinal =
    options.ordinal !== undefined && Number.isFinite(options.ordinal)
      ? options.ordinal
      : undefined;
  const reconstructable =
    options.reconstructable ??
    parseOptionalBoolean(environment[RUNTIME_POSITION_RECONSTRUCTABLE_ENV]) ??
    Boolean(snapshotRoot && positionRoot);
  const runtimeAddress = buildRuntimeAddress({
    worldAlias,
    nodeId,
    runtime,
    runtimeId,
    ...(snapshotRoot ? { snapshotRoot } : {}),
  });
  const runtimeSessionAddress = buildRuntimeSessionAddress({
    worldAlias,
    nodeId,
    runtime,
    runtimeId,
    sessionId,
    ...(snapshotRoot ? { snapshotRoot } : {}),
  });
  const sessionAddress = buildLegacySessionAddress({
    worldAlias,
    nodeId,
    runtime,
    sessionId,
    ...(snapshotRoot ? { snapshotRoot } : {}),
  });
  const bookmarkAddress = buildBookmarkAddress({
    worldAlias,
    nodeId,
    runtime,
    runtimeId,
    sessionId,
    ...(positionId ? { positionId } : {}),
    ...(snapshotRoot ? { snapshotRoot } : {}),
    ...(positionRoot ? { positionRoot } : {}),
    ...(streamId ? { streamId } : {}),
    ...(ordinal !== undefined ? { ordinal } : {}),
  });

  return {
    source:
      options.nodeId !== undefined ||
      options.sessionId !== undefined ||
      options.runtime !== undefined ||
      options.snapshotRoot !== undefined ||
      options.positionRoot !== undefined
        ? 'options'
        : 'env',
    worldAlias,
    nodeId,
    runtime,
    runtimeId,
    sessionId,
    ...(positionId ? { positionId } : {}),
    ...(snapshotRoot ? { snapshotRoot } : {}),
    ...(positionRoot ? { positionRoot } : {}),
    ...(streamId ? { streamId } : {}),
    ...(ordinal !== undefined ? { ordinal } : {}),
    reconstructable,
    runtimeAddress,
    runtimeSessionAddress,
    sessionAddress,
    bookmarkAddress,
    canonicalAddress:
      reconstructable && snapshotRoot && positionRoot
        ? bookmarkAddress
        : sessionAddress,
  };
}

function isRuntimeBookmarkSubjectKind(
  value: AeonRhizomeObjectRoute['subjectKind']
): value is AeonRhizomeRuntimeSubjectKind {
  return (
    value === 'runtime' ||
    value === 'runtime-session' ||
    value === 'runtime-position'
  );
}

function routeMatchesRuntimeBookmark(
  route: AeonRhizomeObjectRoute,
  runtimePosition: XGnosisResolvedRuntimePosition
): boolean {
  if (
    route.kind !== 'rhizome' ||
    !isRuntimeBookmarkSubjectKind(route.subjectKind)
  ) {
    return false;
  }
  if (route.worldAlias !== runtimePosition.worldAlias ) {
    return false;
  }
  if (route.nodeId !== runtimePosition.nodeId ) {
    return false;
  }

  const requested = route.runtimeBookmark;
  if (!requested ) {
    return true;
  }
  if (requested.runtime !== undefined &&
    requested.runtime !== runtimePosition.runtime ) {
    return false;
  }
  if (requested.runtimeTarget !== undefined &&
    requested.runtimeTarget !== runtimePosition.runtime ) {
    return false;
  }
  if (requested.runtimeId !== undefined &&
    requested.runtimeId !== runtimePosition.runtimeId ) {
    return false;
  }
  if (requested.sessionId !== undefined &&
    requested.sessionId !== runtimePosition.sessionId ) {
    return false;
  }
  if (requested.snapshotRoot !== undefined &&
    requested.snapshotRoot !== runtimePosition.snapshotRoot ) {
    return false;
  }
  if (
    requested.positionId !== undefined &&
    requested.positionId !==
      (runtimePosition.positionId ?? runtimePosition.positionRoot)
  ) {
    return false;
  }
  if (requested.positionRoot !== undefined &&
    requested.positionRoot !== runtimePosition.positionRoot ) {
    return false;
  }
  if (requested.streamId !== undefined &&
    requested.streamId !== runtimePosition.streamId ) {
    return false;
  }
  if (requested.ordinal !== undefined &&
    requested.ordinal !== runtimePosition.ordinal ) {
    return false;
  }

  return true;
}

function dedupeStrings(values: readonly (string | undefined)[]): string[] {
  return [
    ...new Set(values.filter((value): value is string => Boolean(value))),
  ];
}

function describeRuntimeBookmark(input: {
  readonly request: RequestPayload;
  readonly runtimePosition: XGnosisResolvedRuntimePosition;
  readonly subjectKind: AeonRhizomeRuntimeSubjectKind;
}): {
  readonly objectKind: AeonRhizomeRuntimeSubjectKind;
  readonly canonicalAddress: string;
  readonly source: string;
  readonly title: string;
  readonly mimeType: string;
  readonly storageScope: string;
  readonly httpsView?: string;
  readonly lineage: string[];
  readonly graphCid?: string;
} {
  const source =
    input.runtimePosition.source === 'env'
      ? `${input.subjectKind}-env`
      : input.subjectKind;

  switch (input.subjectKind ) {
    case 'runtime':
      return {
        objectKind: 'runtime',
        canonicalAddress: input.runtimePosition.runtimeAddress,
        source,
        title: `${input.runtimePosition.nodeId} runtime`,
        mimeType: 'application/vnd.aeon.runtime+json',
        storageScope: 'world,node,runtime',
        httpsView: buildHttpRuntimeBookmarkHref({
          request: input.request,
          runtimePosition: input.runtimePosition,
          subjectKind: 'runtime',
        }),
        lineage: dedupeStrings([
          input.runtimePosition.runtimeSessionAddress,
          input.runtimePosition.sessionAddress,
          input.runtimePosition.snapshotRoot,
        ]),
      };
    case 'runtime-session':
      return {
        objectKind: 'runtime-session',
        canonicalAddress: input.runtimePosition.runtimeSessionAddress,
        source,
        title: `${input.runtimePosition.nodeId} runtime session`,
        mimeType: 'application/vnd.aeon.runtime-session+json',
        storageScope: 'world,node,runtime-session',
        httpsView: buildHttpRuntimeBookmarkHref({
          request: input.request,
          runtimePosition: input.runtimePosition,
          subjectKind: 'runtime-session',
        }),
        lineage: dedupeStrings([
          input.runtimePosition.runtimeAddress,
          input.runtimePosition.sessionAddress,
          input.runtimePosition.snapshotRoot,
        ]),
      };
    default:
      return {
        objectKind: 'runtime-position',
        canonicalAddress: input.runtimePosition.canonicalAddress,
        source,
        title: `${input.runtimePosition.nodeId} runtime position`,
        mimeType: 'application/vnd.aeon.runtime-position+json',
        storageScope: 'world,node,runtime-position',
        httpsView: buildHttpRuntimeBookmarkHref({
          request: input.request,
          runtimePosition: input.runtimePosition,
          subjectKind: 'runtime-position',
        }),
        lineage: dedupeStrings([
          input.runtimePosition.runtimeSessionAddress,
          input.runtimePosition.sessionAddress,
          input.runtimePosition.snapshotRoot,
        ]),
        ...(input.runtimePosition.positionRoot
          ? { graphCid: input.runtimePosition.positionRoot }
          : {}),
      };
  }
}

export function createRuntimePositionEnvelope(input: {
  readonly request: RequestPayload;
  readonly runtimePosition: XGnosisResolvedRuntimePosition;
  readonly subjectKind?: AeonRhizomeRuntimeSubjectKind;
}): AeonObjectEnvelope<Record<string, unknown>> {
  const resolvedAt = Date.now();
  const subjectKind = input.subjectKind ?? 'runtime-position';
  const bookmarkGuarantee = input.runtimePosition.reconstructable
    ? 'exact'
    : 'hint';
  const bookmark = describeRuntimeBookmark({
    request: input.request,
    runtimePosition: input.runtimePosition,
    subjectKind,
  });

  return {
    version: 'aeon-object/v1',
    source: bookmark.source,
    resolvedAt,
    selectedProjection: 'document',
    identity: {
      objectKind: bookmark.objectKind,
      canonicalAddress: bookmark.canonicalAddress,
      worldAlias: input.runtimePosition.worldAlias,
      nodeId: input.runtimePosition.nodeId,
      ...(bookmark.graphCid ? { graphCid: bookmark.graphCid } : {}),
      lineage: bookmark.lineage,
    },
    authority: {
      contract: 'ucan+effects',
      requiredCapabilities: ['rhizome/read'],
    },
    witness: {
      source: bookmark.source,
      status:
        bookmarkGuarantee === 'exact' ? 'reconstructable' : 'ephemeral-hint',
      generatedAt: resolvedAt,
      ...(input.runtimePosition.snapshotRoot
        ? { snapshotRoot: input.runtimePosition.snapshotRoot }
        : {}),
      cacheTtlMs: 15_000,
      sourceBadge:
        bookmarkGuarantee === 'exact' ? 'runtime bookmark' : 'runtime hint',
      proofAvailable: Boolean(input.runtimePosition.snapshotRoot),
    },
    storage: {
      scope: bookmark.storageScope,
      worldAlias: input.runtimePosition.worldAlias,
      ...(input.runtimePosition.snapshotRoot
        ? { snapshotRoot: input.runtimePosition.snapshotRoot }
        : {}),
    },
    replication: {
      ladder: ['local', 'host', 'http'],
      selected: 'host',
      httpFallback: true,
    },
    views: {
      aeon: bookmark.canonicalAddress,
      ...(bookmark.httpsView ? { https: bookmark.httpsView } : {}),
    },
    projections: {
      document: {
        href: bookmark.canonicalAddress,
        mimeType: bookmark.mimeType,
        title: bookmark.title,
        content: {
          subjectKind,
          worldAlias: input.runtimePosition.worldAlias,
          nodeId: input.runtimePosition.nodeId,
          runtime: input.runtimePosition.runtime,
          runtimeId: input.runtimePosition.runtimeId,
          sessionId: input.runtimePosition.sessionId,
          bookmarkGuarantee,
          reconstructable: input.runtimePosition.reconstructable,
          runtimeAddress: input.runtimePosition.runtimeAddress,
          runtimeSessionAddress: input.runtimePosition.runtimeSessionAddress,
          sessionAddress: input.runtimePosition.sessionAddress,
          bookmarkAddress: input.runtimePosition.bookmarkAddress,
          canonicalAddress: bookmark.canonicalAddress,
          ...(input.runtimePosition.snapshotRoot
            ? { snapshotRoot: input.runtimePosition.snapshotRoot }
            : {}),
          ...(input.runtimePosition.positionId
            ? { positionId: input.runtimePosition.positionId }
            : {}),
          ...(input.runtimePosition.positionRoot
            ? { positionRoot: input.runtimePosition.positionRoot }
            : {}),
          ...(input.runtimePosition.streamId
            ? { streamId: input.runtimePosition.streamId }
            : {}),
          ...(input.runtimePosition.ordinal !== undefined
            ? { ordinal: input.runtimePosition.ordinal }
            : {}),
        },
      },
    },
  };
}

export function createRuntimePositionObjectResolver(
  runtimePosition: XGnosisResolvedRuntimePosition
): AeonObjectResolver {
  return ({ route, request }) =>
    routeMatchesRuntimeBookmark(route, runtimePosition)
      ? createRuntimePositionEnvelope({
          request,
          runtimePosition,
          subjectKind: route.subjectKind,
        })
      : null;
}
