/**
 * @a0n/auth - Identity Management
 *
 * DID generation and key management using Web Crypto API
 */

import type { DID, Identity, KeyPair, SigningAlgorithm } from './ucanTypes.js';

/**
 * Algorithm configurations for key generation
 */
const ALGORITHM_CONFIG: Record<
  SigningAlgorithm,
  { name: string; namedCurve?: string; hash?: string }
> = {
  ES256: { name: 'ECDSA', namedCurve: 'P-256' },
  ES384: { name: 'ECDSA', namedCurve: 'P-384' },
  ES512: { name: 'ECDSA', namedCurve: 'P-521' },
  Ed25519: { name: 'Ed25519' },
};

/**
 * Base64url encode bytes
 */
function base64UrlEncode(bytes: Uint8Array): string {
  const binary = String.fromCharCode(...bytes);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}

/**
 * Base64url decode string
 */
function base64UrlDecode(str: string): Uint8Array {
  let base64 = str.replace(/-/g, '+').replace(/_/g, '/');
  while (base64.length % 4) base64 += '=';
  const binary = atob(base64);
  return Uint8Array.from(binary, (c) => c.charCodeAt(0));
}

/**
 * Compute key fingerprint from public key
 */
export async function computeFingerprint(
  publicKey: JsonWebKey
): Promise<string> {
  // Canonical JSON representation
  const canonical = JSON.stringify(publicKey, Object.keys(publicKey).sort());
  const bytes = new TextEncoder().encode(canonical);

  // SHA-256 hash
  const hashBuffer = await crypto.subtle.digest('SHA-256', bytes);
  const hashBytes = new Uint8Array(hashBuffer);

  // Take first 16 bytes and encode as base64url
  return base64UrlEncode(hashBytes.slice(0, 16));
}

/**
 * Derive DID from public key using did:key method
 *
 * @param publicKey - JWK public key
 * @returns DID string
 *
 * @example
 * ```typescript
 * const did = await deriveDID(publicKey);
 * // 'did:key:z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK'
 * ```
 */
export async function deriveDID(publicKey: JsonWebKey): Promise<DID> {
  const fingerprint = await computeFingerprint(publicKey);
  // Use 'z' prefix for base58btc multibase encoding simulation
  return `did:key:z${fingerprint}` as DID;
}

/**
 * Generate a new cryptographic key pair
 *
 * @param algorithm - Signing algorithm to use (default: ES256)
 * @returns Key pair with public and private keys
 */
export async function generateKeyPair(
  algorithm: SigningAlgorithm = 'ES256'
): Promise<KeyPair> {
  const config = ALGORITHM_CONFIG[algorithm];

  let keyPair: CryptoKeyPair;

  if (algorithm === 'Ed25519') {
    // Ed25519 support
    keyPair = (await crypto.subtle.generateKey({ name: 'Ed25519' }, true, [
      'sign',
      'verify',
    ])) as CryptoKeyPair;
  } else {
    // ECDSA variants
    keyPair = (await crypto.subtle.generateKey(
      { name: config.name, namedCurve: config.namedCurve! },
      true,
      ['sign', 'verify']
    )) as CryptoKeyPair;
  }

  const publicKey = (await crypto.subtle.exportKey(
    'jwk',
    keyPair.publicKey
  )) as JsonWebKey;
  const privateKey = (await crypto.subtle.exportKey(
    'jwk',
    keyPair.privateKey
  )) as JsonWebKey;
  const fingerprint = await computeFingerprint(publicKey);

  return {
    algorithm,
    publicKey,
    privateKey,
    fingerprint,
  };
}

/**
 * Generate a new identity with DID and key pairs
 *
 * @param options - Identity generation options
 * @returns New identity with DID and keys
 *
 * @example
 * ```typescript
 * const identity = await generateIdentity({ displayName: 'My Node' });
 * console.log(identity.did); // 'did:key:z...'
 * ```
 */
export async function generateIdentity(options?: {
  algorithm?: SigningAlgorithm;
  displayName?: string;
  includeEncryptionKey?: boolean;
}): Promise<Identity> {
  const {
    algorithm = 'ES256',
    displayName,
    includeEncryptionKey = false,
  } = options || {};

  // Generate signing key pair
  const signingKey = await generateKeyPair(algorithm);

  // Derive DID from public key
  const did = await deriveDID(signingKey.publicKey);

  // Optionally generate encryption key pair (always P-256 for ECDH compatibility)
  let encryptionKey: KeyPair | undefined;
  if (includeEncryptionKey) {
    const ecdhKeyPair = (await crypto.subtle.generateKey(
      { name: 'ECDH', namedCurve: 'P-256' },
      true,
      ['deriveBits']
    )) as CryptoKeyPair;

    const publicKey = (await crypto.subtle.exportKey(
      'jwk',
      ecdhKeyPair.publicKey
    )) as JsonWebKey;
    const privateKey = (await crypto.subtle.exportKey(
      'jwk',
      ecdhKeyPair.privateKey
    )) as JsonWebKey;
    const fingerprint = await computeFingerprint(publicKey);

    encryptionKey = {
      algorithm: 'ES256', // ECDH uses same curve as ES256
      publicKey,
      privateKey,
      fingerprint,
    };
  }

  return {
    did,
    signingKey,
    encryptionKey,
    createdAt: Date.now(),
    displayName,
  };
}

/**
 * Import an existing identity from key material
 *
 * @param signingPrivateKey - JWK private key for signing
 * @param options - Import options
 * @returns Imported identity
 */
export async function importIdentity(
  signingPrivateKey: JsonWebKey,
  options?: {
    algorithm?: SigningAlgorithm;
    displayName?: string;
    encryptionPrivateKey?: JsonWebKey;
  }
): Promise<Identity> {
  const {
    algorithm = 'ES256',
    displayName,
    encryptionPrivateKey,
  } = options || {};

  // Extract public key from private key
  const publicKey = { ...signingPrivateKey };
  delete publicKey.d; // Remove private component

  const fingerprint = await computeFingerprint(publicKey);
  const did = await deriveDID(publicKey);

  const signingKey: KeyPair = {
    algorithm,
    publicKey,
    privateKey: signingPrivateKey,
    fingerprint,
  };

  let encryptionKey: KeyPair | undefined;
  if (encryptionPrivateKey) {
    const encPubKey = { ...encryptionPrivateKey };
    delete encPubKey.d;
    const encFingerprint = await computeFingerprint(encPubKey);

    encryptionKey = {
      algorithm: 'ES256',
      publicKey: encPubKey,
      privateKey: encryptionPrivateKey,
      fingerprint: encFingerprint,
    };
  }

  return {
    did,
    signingKey,
    encryptionKey,
    createdAt: Date.now(),
    displayName,
  };
}

/**
 * Export an identity for storage (includes private keys)
 *
 * @param identity - Identity to export
 * @returns Serializable identity object
 */
export function exportIdentity(identity: Identity): {
  did: DID;
  signingKey: KeyPair;
  encryptionKey?: KeyPair;
  createdAt: number;
  displayName?: string;
} {
  return {
    did: identity.did,
    signingKey: identity.signingKey,
    encryptionKey: identity.encryptionKey,
    createdAt: identity.createdAt,
    displayName: identity.displayName,
  };
}

/**
 * Export only the public portion of an identity (safe to share)
 *
 * @param identity - Identity to export
 * @returns Public identity data
 */
export function exportPublicIdentity(identity: Identity): {
  did: DID;
  publicSigningKey: JsonWebKey;
  publicEncryptionKey?: JsonWebKey;
  displayName?: string;
} {
  return {
    did: identity.did,
    publicSigningKey: identity.signingKey.publicKey,
    publicEncryptionKey: identity.encryptionKey?.publicKey,
    displayName: identity.displayName,
  };
}

/**
 * Verify that a DID matches a public key
 *
 * @param did - DID to verify
 * @param publicKey - Public key to check
 * @returns True if DID derives from the public key
 */
export async function verifyDIDOwnership(
  did: DID,
  publicKey: JsonWebKey
): Promise<boolean> {
  const derivedDID = await deriveDID(publicKey);
  return derivedDID === did;
}

/**
 * Sign data with an identity's private key
 *
 * @param identity - Identity with private key
 * @param data - Data to sign
 * @returns Signature bytes
 */
export async function sign(
  identity: Identity,
  data: Uint8Array
): Promise<Uint8Array> {
  if (!identity.signingKey.privateKey) {
    throw new Error('Identity does not have a private key');
  }

  const algorithm = identity.signingKey.algorithm;
  const config = ALGORITHM_CONFIG[algorithm];
  const dataBytes = new Uint8Array(data);

  let cryptoKey: CryptoKey;

  if (algorithm === 'Ed25519') {
    cryptoKey = await crypto.subtle.importKey(
      'jwk',
      identity.signingKey.privateKey,
      { name: 'Ed25519' },
      false,
      ['sign']
    );
  } else {
    cryptoKey = await crypto.subtle.importKey(
      'jwk',
      identity.signingKey.privateKey,
      { name: config.name, namedCurve: config.namedCurve! },
      false,
      ['sign']
    );
  }

  let signatureBuffer: ArrayBuffer;

  if (algorithm === 'Ed25519') {
    signatureBuffer = await crypto.subtle.sign('Ed25519', cryptoKey, dataBytes);
  } else {
    // Use SHA-256 for ES256, SHA-384 for ES384, SHA-512 for ES512
    const hash =
      algorithm === 'ES256'
        ? 'SHA-256'
        : algorithm === 'ES384'
        ? 'SHA-384'
        : 'SHA-512';

    signatureBuffer = await crypto.subtle.sign(
      { name: 'ECDSA', hash },
      cryptoKey,
      dataBytes
    );
  }

  return new Uint8Array(signatureBuffer);
}

/**
 * Verify a signature against data and a public key
 *
 * @param publicKey - JWK public key
 * @param signature - Signature bytes
 * @param data - Original data
 * @param algorithm - Signing algorithm used
 * @returns True if signature is valid
 */
export async function verify(
  publicKey: JsonWebKey,
  signature: Uint8Array,
  data: Uint8Array,
  algorithm: SigningAlgorithm = 'ES256'
): Promise<boolean> {
  const config = ALGORITHM_CONFIG[algorithm];
  const dataBytes = new Uint8Array(data);
  const signatureBytes = new Uint8Array(signature);

  let cryptoKey: CryptoKey;

  try {
    if (algorithm === 'Ed25519') {
      cryptoKey = await crypto.subtle.importKey(
        'jwk',
        publicKey,
        { name: 'Ed25519' },
        false,
        ['verify']
      );
    } else {
      cryptoKey = await crypto.subtle.importKey(
        'jwk',
        publicKey,
        { name: config.name, namedCurve: config.namedCurve! },
        false,
        ['verify']
      );
    }

    if (algorithm === 'Ed25519') {
      return await crypto.subtle.verify(
        'Ed25519',
        cryptoKey,
        signatureBytes,
        dataBytes
      );
    } else {
      const hash =
        algorithm === 'ES256'
          ? 'SHA-256'
          : algorithm === 'ES384'
          ? 'SHA-384'
          : 'SHA-512';

      return await crypto.subtle.verify(
        { name: 'ECDSA', hash },
        cryptoKey,
        signatureBytes,
        dataBytes
      );
    }
  } catch {
    return false;
  }
}

/**
 * Generate a random nonce for replay protection
 */
export function generateNonce(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  return base64UrlEncode(bytes);
}

/**
 * Generate a unique token ID
 */
export function generateTokenId(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  return base64UrlEncode(bytes);
}

export { base64UrlEncode, base64UrlDecode };
