import { mkdtemp, rm, writeFile, access } from 'node:fs/promises';
import { constants as fsConstants } from 'node:fs';
import { spawn, type ChildProcessWithoutNullStreams } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  type GnotCommandRequest,
  type GnotCommandResult,
  type GnotCommandRunner,
} from './types.js';

const DEFAULT_TIMEOUT_MS = 5_000;

interface SpawnResult {
  exitCode: number;
  stdout: string;
  stderr: string;
  durationMs: number;
  timedOut: boolean;
}

function normalizeNewline(input: string): string {
  return input.endsWith('\n') ? input : `${input}\n`;
}

async function exists(path: string): Promise<boolean> {
  try {
    await access(path, fsConstants.F_OK);
    return true;
  } catch {
    return false;
  }
}

async function resolveGnotCommand(
  repoRoot: string
): Promise<{ command: string; argsPrefix: string[] }> {
  const envBinary = process.env.GNOT_BIN;
  if (envBinary && envBinary.trim().length > 0) {
    return {
      command: envBinary,
      argsPrefix: [],
    };
  }

  const debugBinary = join(repoRoot, 'open-source/gnot/target/debug/gnot');
  if (await exists(debugBinary)) {
    return {
      command: debugBinary,
      argsPrefix: [],
    };
  }

  const cargoManifest = join(repoRoot, 'open-source/gnot/Cargo.toml');
  return {
    command: 'cargo',
    argsPrefix: [
      'run',
      '--quiet',
      '--manifest-path',
      cargoManifest,
      '--bin',
      'gnot',
      '--',
    ],
  };
}

async function spawnAndCapture(
  command: string,
  args: string[],
  cwd: string,
  timeoutMs: number,
  signal: AbortSignal
): Promise<SpawnResult> {
  const startedAt = Date.now();
  const child = spawn(command, args, {
    cwd,
    stdio: ['ignore', 'pipe', 'pipe'],
  });

  let stdout = '';
  let stderr = '';
  let timedOut = false;

  child.stdout.on('data', (chunk: Buffer) => {
    stdout += chunk.toString('utf8');
  });
  child.stderr.on('data', (chunk: Buffer) => {
    stderr += chunk.toString('utf8');
  });

  const killChild = (): void => {
    if (!child.killed) {
      child.kill('SIGKILL');
    }
  };

  let timeoutHandle: NodeJS.Timeout | undefined;
  if (timeoutMs > 0) {
    timeoutHandle = setTimeout(() => {
      timedOut = true;
      killChild();
    }, timeoutMs);
  }

  const abortHandler = (): void => {
    killChild();
  };
  signal.addEventListener('abort', abortHandler, { once: true });

  const exitCode = await new Promise<number>((resolve) => {
    child.on('exit', (code: number | null) => {
      resolve(code ?? 1);
    });
    child.on('error', (error: Error) => {
      stderr += `${error.message}\n`;
      resolve(1);
    });
  });

  if (timeoutHandle) {
    clearTimeout(timeoutHandle);
  }
  signal.removeEventListener('abort', abortHandler);

  return {
    exitCode,
    stdout,
    stderr,
    durationMs: Date.now() - startedAt,
    timedOut,
  };
}

export function createCargoBackedGnotRunner(): GnotCommandRunner {
  return async (request: GnotCommandRequest): Promise<GnotCommandResult> => {
    const timeoutMs =
      request.timeoutMs > 0 ? request.timeoutMs : DEFAULT_TIMEOUT_MS;
    const scratchDir = await mkdtemp(join(tmpdir(), 'gnot-repl-core-'));
    const sourcePath = join(scratchDir, 'snippet.gnot');
    await writeFile(sourcePath, normalizeNewline(request.source), 'utf8');

    const commandTarget = await resolveGnotCommand(request.repoRoot);
    const args = [
      ...commandTarget.argsPrefix,
      request.command,
      sourcePath,
      ...(request.args ?? []),
    ];
    const fullCommand = [commandTarget.command, ...args].join(' ');

    try {
      const result = await spawnAndCapture(
        commandTarget.command,
        args,
        request.repoRoot,
        timeoutMs,
        request.signal
      );
      return {
        ...result,
        command: fullCommand,
      };
    } finally {
      await rm(scratchDir, { recursive: true, force: true });
    }
  };
}

export async function runWithAbortableCommand(
  commandRunner: GnotCommandRunner,
  request: GnotCommandRequest,
  onSpawn?: (process: ChildProcessWithoutNullStreams | null) => void
): Promise<GnotCommandResult> {
  // Command runner implementations in this package are process-based and do not
  // currently expose child handles. Keep the callback for future adapters.
  if (onSpawn) {
    onSpawn(null);
  }
  return await commandRunner(request);
}
