/**
 * @a0n/auth - UCAN Crypto Utilities
 *
 * Shared cryptographic primitives for UCAN signing and verification
 * using ECDSA with the P-256 curve (ES256).
 */

function toArrayBuffer(view: Uint8Array): ArrayBuffer {
  if (
    view.buffer instanceof ArrayBuffer &&
    view.byteOffset === 0 &&
    view.byteLength === view.buffer.byteLength
  ) {
    return view.buffer;
  }

  return view.slice().buffer;
}

/**
 * Sign a digest using an ECDSA P-256 private key
 */
export async function signDigest(
  digest: string,
  privateKeyJWK: JsonWebKey
): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(digest);

  const key = await crypto.subtle.importKey(
    'jwk',
    privateKeyJWK,
    { name: 'ECDSA', namedCurve: 'P-256' },
    false,
    ['sign']
  );

  const signature = await crypto.subtle.sign(
    { name: 'ECDSA', hash: 'SHA-256' },
    key,
    data
  );

  return bufferToHex(new Uint8Array(signature));
}

/**
 * Verify an ECDSA P-256 signature against a digest
 */
export async function verifySignature(
  digest: string,
  signatureHex: string,
  publicKeyJWK: JsonWebKey
): Promise<boolean> {
  try {
    const encoder = new TextEncoder();
    const data = encoder.encode(digest);
    const signature = hexToBuffer(signatureHex);

    const key = await crypto.subtle.importKey(
      'jwk',
      publicKeyJWK,
      { name: 'ECDSA', namedCurve: 'P-256' },
      false,
      ['verify']
    );

    return await crypto.subtle.verify(
      { name: 'ECDSA', hash: 'SHA-256' },
      key,
      toArrayBuffer(signature),
      toArrayBuffer(data)
    );
  } catch (error) {
    console.error('[ucanCrypto] Verification failed:', error);
    return false;
  }
}

/**
 * Compute a SHA-256 digest of a string
 */
export async function computeDigest(text: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(text);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  return bufferToHex(new Uint8Array(hashBuffer));
}

/**
 * Helper: Convert Uint8Array to Hex string
 */
export function bufferToHex(buffer: Uint8Array): string {
  return Array.from(buffer)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Helper: Convert Hex string to Uint8Array
 */
export function hexToBuffer(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.slice(i, i + 2), 16);
  }
  return bytes;
}
