import {
  createHash,
  createPrivateKey,
  createPublicKey,
  sign as nodeSign,
  verify as nodeVerify,
} from 'node:crypto';
import type {
  FederationIssuerPublicKeyMap,
  FederationSignatureEnvelope,
  FederationValidationResult,
} from './types.js';

interface JsonObject {
  readonly [key: string]: JsonValue;
}

type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonObject
  | readonly JsonValue[];

function normalizeNumber(value: number): number {
  if (!Number.isFinite(value)) {
    return 0;
  }
  if (Object.is(value, -0)) {
    return 0;
  }
  return value;
}

function normalizeUnknown(
  value: unknown,
  seen: WeakSet<object>
): JsonValue {
  if (
    value === null ||
    typeof value === 'string' ||
    typeof value === 'boolean'
  ) {
    return value;
  }

  if (typeof value === 'number') {
    return normalizeNumber(value);
  }

  if (typeof value === 'bigint') {
    return value.toString(10);
  }

  if (value instanceof Date) {
    return value.toISOString();
  }

  if (value instanceof Uint8Array) {
    return Buffer.from(value).toString('base64');
  }

  if (Array.isArray(value)) {
    return value.map((entry) => normalizeUnknown(entry, seen));
  }

  if (typeof value === 'object') {
    if (seen.has(value)) {
      throw new Error('Cannot canonicalize circular values for federation hash');
    }
    seen.add(value);

    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([, entryValue]) => entryValue !== undefined)
      .sort(([left], [right]) => left.localeCompare(right));

    const normalized: Record<string, JsonValue> = {};
    for (const [key, entryValue] of entries) {
      normalized[key] = normalizeUnknown(entryValue, seen);
    }

    seen.delete(value);
    return normalized;
  }

  return String(value);
}

export function stableCanonicalStringify(value: unknown): string {
  const normalized = normalizeUnknown(value, new WeakSet<object>());
  return JSON.stringify(normalized);
}

export function sha256Hex(value: unknown): string {
  const input =
    typeof value === 'string' ? value : stableCanonicalStringify(value);
  return createHash('sha256').update(input).digest('hex');
}

export function signDigestEd25519(
  digestHex: string,
  privateKeyPem: string
): string {
  const privateKey = createPrivateKey(privateKeyPem);
  const signature = nodeSign(null, Buffer.from(digestHex, 'hex'), privateKey);
  return signature.toString('base64');
}

export function verifyDigestEd25519(
  digestHex: string,
  signatureBase64: string,
  publicKeyPem: string
): boolean {
  const publicKey = createPublicKey(publicKeyPem);
  return nodeVerify(
    null,
    Buffer.from(digestHex, 'hex'),
    publicKey,
    Buffer.from(signatureBase64, 'base64')
  );
}

export interface SignatureEnvelopeInput {
  readonly payload: unknown;
  readonly issuer: string;
  readonly keyId: string;
  readonly privateKeyPem: string;
  readonly signedAt?: string;
}

export function createSignatureEnvelope(
  input: SignatureEnvelopeInput
): FederationSignatureEnvelope {
  const digest = sha256Hex(input.payload);
  const signedAt = input.signedAt ?? new Date().toISOString();
  return {
    algorithm: 'ed25519',
    issuer: input.issuer,
    keyId: input.keyId,
    signedAt,
    digest,
    signature: signDigestEd25519(digest, input.privateKeyPem),
  };
}

function resolveIssuerPublicKey(
  issuer: string,
  issuerPublicKeys: FederationIssuerPublicKeyMap | undefined
): string | null {
  if (!issuerPublicKeys) {
    return null;
  }
  const key = issuerPublicKeys[issuer];
  return typeof key === 'string' && key.trim().length > 0 ? key : null;
}

export function verifySignatureEnvelope(
  payload: unknown,
  signature: FederationSignatureEnvelope,
  issuerPublicKeys?: FederationIssuerPublicKeyMap
): FederationValidationResult {
  const digest = sha256Hex(payload);
  if (digest !== signature.digest) {
    return {
      ok: false,
      reason: 'signature digest does not match payload digest',
    };
  }

  const publicKey = resolveIssuerPublicKey(signature.issuer, issuerPublicKeys);
  if (!publicKey) {
    return {
      ok: false,
      reason: `unknown issuer: ${signature.issuer}`,
    };
  }

  const verified = verifyDigestEd25519(
    signature.digest,
    signature.signature,
    publicKey
  );

  return verified
    ? { ok: true }
    : {
        ok: false,
        reason: 'signature verification failed',
      };
}
