import {
  verifyUcanToken,
  type UcanCapability,
  type UcanPayload,
} from './ucanAuth.js';

export interface RequestProcessIdentity {
  cid: string;
  instance: string;
  owner: string;
  generation: number;
}

export type RequestAuthSource = 'none' | 'propagated' | 'ucan' | 'did_bearer';

export interface RequestAuthContext {
  actorDid?: string;
  audience?: string;
  tier?: string;
  attributes?: Record<string, unknown>;
  justice?: JusticeAuthContext;
  featureFlags: string[];
  capabilities: UcanCapability[];
  requestPid?: RequestProcessIdentity;
  supervisorPid?: RequestProcessIdentity;
  verified: boolean;
  source: RequestAuthSource;
}

export interface JusticeAuthHold {
  holdId: string;
  effect: 'deny_capability' | 'pid_quarantine' | 'forge_hold';
  target: string;
  capability?: string;
  reason?: string;
  active?: boolean;
}

export interface JusticeAuthContext {
  roles: string[];
  scopes: string[];
  holds: JusticeAuthHold[];
}

export interface ResolveRequestAuthOptions {
  headers: Record<string, string | undefined>;
  method: string;
  path: string;
  expectedAudience?: string;
  requiredCapabilities?: UcanCapability[];
  allowInsecureDidBearer?: boolean;
  trustPropagatedHeaders?: boolean;
  resolveIssuerPublicKey?: ResolveIssuerPublicKey;
}

export interface ResolveIssuerPublicKeyParams {
  issuerDid: string;
  kid?: string;
}

export type ResolveIssuerPublicKey = (
  params: ResolveIssuerPublicKeyParams
) => Promise<JsonWebKey | null>;

export const REQUEST_AUTH_HEADERS = {
  verified: 'x-aeon-auth-verified',
  source: 'x-aeon-auth-source',
  actor: 'x-aeon-actor',
  audience: 'x-aeon-audience',
  tier: 'x-aeon-tier',
  flags: 'x-aeon-flags',
  attributes: 'x-aeon-auth-attributes',
  requestPid: 'x-aeon-request-pid',
  supervisorPid: 'x-aeon-supervisor-pid',
  capabilities: 'x-ucan-capabilities',
} as const;

export const JUSTICE_CAPABILITY_FAMILIES = {
  caseRead: 'justice.case.read',
  caseWrite: 'justice.case.write',
  caseAdjudicate: 'justice.case.adjudicate',
  appealWrite: 'justice.appeal.write',
  enforcementRead: 'justice.enforcement.read',
  enforcementApply: 'justice.enforcement.apply',
  enforcementOverride: 'justice.enforcement.override',
} as const;

const EMPTY_AUTH_CONTEXT: RequestAuthContext = {
  featureFlags: [],
  capabilities: [],
  verified: false,
  source: 'none',
};

function getHeader(
  headers: Record<string, string | undefined>,
  headerName: string
): string | undefined {
  const target = headerName.toLowerCase();
  for (const [name, value] of Object.entries(headers)) {
    if (name.toLowerCase() === target) {
      return value;
    }
  }
  return undefined;
}

function decodeBase64UrlJson<T>(value: string): T | undefined {
  const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
  const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4);

  try {
    return JSON.parse(atob(padded)) as T;
  } catch {
    return undefined;
  }
}

function randomHex(bytes: number): string {
  const values = crypto.getRandomValues(new Uint8Array(bytes));
  return Array.from(values, (value) =>
    value.toString(16).padStart(2, '0')
  ).join('');
}

function createRootRequestPid(owner: string): RequestProcessIdentity {
  return {
    cid: `request:${randomHex(4)}`,
    instance: randomHex(4),
    owner,
    generation: 0,
  };
}

function normalizeFeatureFlags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value
      .map((entry) => (typeof entry === 'string' ? entry.trim() : ''))
      .filter(Boolean);
  }

  if (typeof value === 'string') {
    return value
      .split(',')
      .map((entry) => entry.trim())
      .filter(Boolean);
  }

  return [];
}

function normalizeStringList(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((entry) => (typeof entry === 'string' ? entry.trim() : ''))
    .filter(Boolean);
}

function parseJsonHeader(
  value: string | undefined
): Record<string, unknown> | undefined {
  if (!value) {
    return undefined;
  }

  try {
    const parsed = JSON.parse(value);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>;
    }
  } catch {
    return undefined;
  }

  return undefined;
}

export function parsePropagatedUcanCapabilities(
  value: string | undefined
): UcanCapability[] {
  if (!value) {
    return [];
  }

  try {
    const parsed = JSON.parse(value);
    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed
      .map((entry) => {
        if (
          !entry ||
          typeof entry !== 'object' ||
          Array.isArray(entry) ||
          typeof entry['can'] !== 'string' ||
          typeof entry['with'] !== 'string'
        ) {
          return null;
        }

        const constraints = entry['constraints'];
        return {
          can: entry['can'],
          with: entry['with'],
          ...(constraints &&
          typeof constraints === 'object' &&
          !Array.isArray(constraints)
            ? { constraints: constraints as Record<string, unknown> }
            : {}),
        } satisfies UcanCapability;
      })
      .filter((entry): entry is UcanCapability => entry !== null);
  } catch {
    return [];
  }
}

export function serializePropagatedUcanCapabilities(
  capabilities: readonly UcanCapability[]
): string | undefined {
  if (capabilities.length === 0) {
    return undefined;
  }

  try {
    return JSON.stringify(capabilities);
  } catch {
    return undefined;
  }
}

function normalizeJusticeHold(value: unknown): JusticeAuthHold | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }

  const record = value as Record<string, unknown>;
  const holdId =
    typeof record['holdId'] === 'string' ? record['holdId'].trim() : '';
  const effect = record['effect'];
  const target =
    typeof record['target'] === 'string' ? record['target'].trim() : '';

  if (
    !holdId ||
    !target ||
    (effect !== 'deny_capability' &&
      effect !== 'pid_quarantine' &&
      effect !== 'forge_hold')
  ) {
    return null;
  }

  return {
    holdId,
    effect,
    target,
    ...(typeof record['capability'] === 'string'
      ? { capability: record['capability'] }
      : {}),
    ...(typeof record['reason'] === 'string'
      ? { reason: record['reason'] }
      : {}),
    ...(typeof record['active'] === 'boolean'
      ? { active: record['active'] }
      : {}),
  };
}

function normalizeJusticeContext(
  value: unknown
): JusticeAuthContext | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return undefined;
  }

  const record = value as Record<string, unknown>;
  const holds = Array.isArray(record['holds'])
    ? record['holds']
        .map((entry) => normalizeJusticeHold(entry))
        .filter((entry): entry is JusticeAuthHold => entry !== null)
    : [];

  return {
    roles: normalizeStringList(record['roles']),
    scopes: normalizeStringList(record['scopes']),
    holds,
  };
}

function factsToAttributes(
  facts: Record<string, unknown> | undefined
): Record<string, unknown> | undefined {
  if (!facts) {
    return undefined;
  }

  const attributes = Object.fromEntries(
    Object.entries(facts).filter(
      ([key]) =>
        key !== 'tier' &&
        key !== 'flags' &&
        key !== 'featureFlags' &&
        key !== 'requestPid' &&
        key !== 'supervisorPid'
    )
  );

  return Object.keys(attributes).length > 0 ? attributes : undefined;
}

function parseRequestPid(
  encoded: string | undefined,
  owner: string | undefined
): RequestProcessIdentity | undefined {
  if (!encoded) {
    return undefined;
  }

  const [cid, instance, generationValue] = encoded.split('|');
  if (!cid || !instance || !generationValue) {
    return undefined;
  }

  const generation = Number.parseInt(generationValue, 10);
  if (!Number.isFinite(generation)) {
    return undefined;
  }

  return {
    cid,
    instance,
    owner: owner ?? 'did:anonymous:request',
    generation,
  };
}

function parsePropagatedAuth(
  headers: Record<string, string | undefined>
): RequestAuthContext {
  const actorDid = getHeader(headers, REQUEST_AUTH_HEADERS.actor);
  const requestPid = parseRequestPid(
    getHeader(headers, REQUEST_AUTH_HEADERS.requestPid),
    actorDid
  );
  const supervisorPid = parseRequestPid(
    getHeader(headers, REQUEST_AUTH_HEADERS.supervisorPid),
    actorDid
  );
  const sourceHeader = getHeader(headers, REQUEST_AUTH_HEADERS.source);
  const source =
    sourceHeader === 'ucan' || sourceHeader === 'did_bearer'
      ? sourceHeader
      : 'propagated';

  const attributes = parseJsonHeader(
    getHeader(headers, REQUEST_AUTH_HEADERS.attributes)
  );

  return {
    actorDid,
    audience: getHeader(headers, REQUEST_AUTH_HEADERS.audience),
    tier: getHeader(headers, REQUEST_AUTH_HEADERS.tier),
    ...(attributes ? { attributes } : {}),
    ...(normalizeJusticeContext(attributes?.['justice'])
      ? { justice: normalizeJusticeContext(attributes?.['justice']) }
      : {}),
    featureFlags: normalizeFeatureFlags(
      getHeader(headers, REQUEST_AUTH_HEADERS.flags)
    ),
    capabilities: parsePropagatedUcanCapabilities(
      getHeader(headers, REQUEST_AUTH_HEADERS.capabilities)
    ),
    ...(requestPid ? { requestPid } : {}),
    ...(supervisorPid ? { supervisorPid } : {}),
    verified: true,
    source,
  };
}

function parseBearerToken(
  headers: Record<string, string | undefined>
): string | undefined {
  const authorization = getHeader(headers, 'authorization');
  if (!authorization) {
    return undefined;
  }

  const match = authorization.match(/^Bearer\s+(.+)$/i);
  return match?.[1]?.trim();
}

function payloadFacts(
  payload: UcanPayload | undefined
): Record<string, unknown> | undefined {
  if (!payload?.fct || Array.isArray(payload.fct)) {
    return undefined;
  }
  return payload.fct;
}

function buildVerifiedAuthContext(
  payload: UcanPayload,
  requestPid: RequestProcessIdentity
): RequestAuthContext {
  const facts = payloadFacts(payload);
  const tier = typeof facts?.tier === 'string' ? facts.tier : undefined;
  const attributes = factsToAttributes(facts);
  const featureFlags = normalizeFeatureFlags(
    facts?.featureFlags ?? facts?.flags
  );
  const justice = normalizeJusticeContext(facts?.justice);

  return {
    actorDid: payload.iss,
    audience: payload.aud,
    ...(tier ? { tier } : {}),
    ...(attributes ? { attributes } : {}),
    ...(justice ? { justice } : {}),
    featureFlags,
    capabilities: payload.att,
    requestPid,
    supervisorPid: requestPid,
    verified: true,
    source: 'ucan',
  };
}

export function encodeRequestPidHeader(
  requestPid: RequestProcessIdentity
): string {
  return `${requestPid.cid}|${requestPid.instance}|${requestPid.generation}`;
}

export function decodeRequestPidHeader(
  encoded: string,
  owner: string
): RequestProcessIdentity | undefined {
  return parseRequestPid(encoded, owner);
}

export function createPropagationHeaders(
  auth: RequestAuthContext
): Record<string, string> {
  const requestPid =
    auth.requestPid ??
    createRootRequestPid(auth.actorDid ?? 'did:anonymous:request');
  const supervisorPid = auth.supervisorPid ?? requestPid;
  const flags = auth.featureFlags.join(',');
  const verifiedValue = auth.verified ? '1' : '0';

  const headers: Record<string, string> = {
    [REQUEST_AUTH_HEADERS.verified]: verifiedValue,
    [REQUEST_AUTH_HEADERS.source]: auth.source,
    [REQUEST_AUTH_HEADERS.requestPid]: encodeRequestPidHeader(requestPid),
    [REQUEST_AUTH_HEADERS.supervisorPid]: encodeRequestPidHeader(supervisorPid),
  };

  if (auth.actorDid) {
    headers[REQUEST_AUTH_HEADERS.actor] = auth.actorDid;
  }

  if (auth.audience) {
    headers[REQUEST_AUTH_HEADERS.audience] = auth.audience;
  }

  if (auth.tier) {
    headers[REQUEST_AUTH_HEADERS.tier] = auth.tier;
  }

  if (flags) {
    headers[REQUEST_AUTH_HEADERS.flags] = flags;
  }

  if (auth.attributes) {
    try {
      headers[REQUEST_AUTH_HEADERS.attributes] = JSON.stringify(
        auth.attributes
      );
    } catch {
      // Ignore non-serializable attributes.
    }
  }

  const capabilities = serializePropagatedUcanCapabilities(auth.capabilities);
  if (capabilities) {
    headers[REQUEST_AUTH_HEADERS.capabilities] = capabilities;
  }

  return headers;
}

export function createChildRequestAuth(
  auth: RequestAuthContext
): RequestAuthContext {
  const supervisorPid = auth.supervisorPid ?? auth.requestPid;
  const parentPid =
    auth.requestPid ??
    createRootRequestPid(auth.actorDid ?? 'did:anonymous:request');
  const requestPid: RequestProcessIdentity = {
    cid: `request:${randomHex(4)}`,
    instance: randomHex(4),
    owner: parentPid.owner,
    generation: parentPid.generation + 1,
  };

  return {
    ...auth,
    requestPid,
    supervisorPid: supervisorPid ?? parentPid,
  };
}

function capabilityMatches(
  capability: UcanCapability,
  requestedCapability: string
): boolean {
  if (capability.can === '*' || capability.can === requestedCapability) {
    return true;
  }

  if (
    capability.can.endsWith('.*') &&
    requestedCapability.startsWith(capability.can.slice(0, -1))
  ) {
    return true;
  }

  return false;
}

export function hasJusticeOverrideCapability(
  auth: RequestAuthContext | null | undefined
): boolean {
  const capabilities = Array.isArray(auth?.capabilities)
    ? auth.capabilities
    : [];
  return capabilities.some((capability) =>
    capabilityMatches(
      capability,
      JUSTICE_CAPABILITY_FAMILIES.enforcementOverride
    )
  );
}

export function getDeniedJusticeCapabilities(
  auth: RequestAuthContext | null | undefined
): string[] {
  const holds = auth?.justice?.holds ?? [];
  return holds
    .filter(
      (hold) => hold.effect === 'deny_capability' && hold.active !== false
    )
    .map((hold) => hold.capability)
    .filter(
      (capability): capability is string => typeof capability === 'string'
    );
}

export function isJusticeCapabilityAllowed(
  auth: RequestAuthContext | null | undefined,
  requestedCapability: string
): boolean {
  if (hasJusticeOverrideCapability(auth)) {
    return true;
  }

  return !getDeniedJusticeCapabilities(auth).includes(requestedCapability);
}

export async function resolveRequestAuth(
  options: ResolveRequestAuthOptions
): Promise<RequestAuthContext> {
  if (
    options.trustPropagatedHeaders &&
    getHeader(options.headers, REQUEST_AUTH_HEADERS.verified) === '1'
  ) {
    return parsePropagatedAuth(options.headers);
  }

  const bearer = parseBearerToken(options.headers);
  if (!bearer) {
    return EMPTY_AUTH_CONTEXT;
  }

  if (options.allowInsecureDidBearer && bearer.startsWith('did:')) {
    const requestPid = createRootRequestPid(bearer);
    return {
      actorDid: bearer,
      featureFlags: [],
      capabilities: [],
      requestPid,
      supervisorPid: requestPid,
      verified: false,
      source: 'did_bearer',
    };
  }

  const parts = bearer.split('.');
  if (parts.length !== 3) {
    return EMPTY_AUTH_CONTEXT;
  }

  const header = decodeBase64UrlJson<{ kid?: string }>(parts[0]);
  const payload = decodeBase64UrlJson<UcanPayload>(parts[1]);

  if (!payload?.iss || !options.resolveIssuerPublicKey) {
    return EMPTY_AUTH_CONTEXT;
  }

  const issuerPublicKeyJwk = await options.resolveIssuerPublicKey({
    issuerDid: payload.iss,
    ...(header?.kid ? { kid: header.kid } : {}),
  });
  if (!issuerPublicKeyJwk) {
    return EMPTY_AUTH_CONTEXT;
  }

  const verified = await verifyUcanToken({
    token: bearer,
    issuerPublicKeyJwk,
    ...(options.expectedAudience
      ? { expectedAudience: options.expectedAudience }
      : {}),
    ...(options.requiredCapabilities && options.requiredCapabilities.length > 0
      ? { requiredCapabilities: options.requiredCapabilities }
      : {}),
  });

  if (!verified.valid || !verified.payload) {
    return EMPTY_AUTH_CONTEXT;
  }

  return buildVerifiedAuthContext(
    verified.payload,
    createRootRequestPid(verified.payload.iss)
  );
}
