import {
  computeProjectionCacheKey,
  matchesRequestGuard,
  normalizeRequestSignature,
  requestSignatureKey,
  stableContentHash,
  type FragmentNode,
  type ProjectionArtifact,
  type ProjectionProofLevel,
  type ProjectionResult,
  type RequestSignature,
} from '@a0n/aeon/topology/projection';

// ── Buleyean weight for treeshaking ──────────────────────────────────
// Inline to avoid cross-package import. Matches void.ts exactly:
// w = R - min(v, R) + 1. Always >= 1 (the sliver).
function buleyeanFragmentWeight(rounds: number, rejections: number): number {
  return rounds - Math.min(rejections, rounds) + 1;
}

/**
 * Extract Buleyean weight from a fragment's metadata.
 * Returns undefined if no rejection data is present.
 */
function fragmentWeight(node: FragmentNode): number | undefined {
  if (!node.metadata) return undefined;
  const v = parseInt(
    node.metadata.rejections ?? node.metadata.void_count ?? '',
    10
  );
  const r = parseInt(
    node.metadata.rounds ?? node.metadata.total_rounds ?? '',
    10
  );
  if (isNaN(v) || isNaN(r) || r <= 0) return undefined;
  return buleyeanFragmentWeight(r, v);
}

export interface ProjectionContext {
  artifact: ProjectionArtifact;
  signature: RequestSignature;
}

export interface ProjectedHtml {
  html: string;
  css: string;
  js: Array<{ id: string; content: string; effect: string }>;
  assets: Array<{ path: string; contentType: string; body: string }>;
  proofLevel: ProjectionProofLevel;
  selectedIds: string[];
}

const ROUTE_HTML_SUFFIX = '.html';

export function normalizeRoute(path: string): string {
  if (!path || path === '/') return '/';
  if (path.endsWith(ROUTE_HTML_SUFFIX)) {
    const trimmed = path.slice(0, -ROUTE_HTML_SUFFIX.length);
    return trimmed.length === 0 ? '/' : trimmed;
  }
  return path;
}

function buildNodeIndex(nodes: FragmentNode[]): Map<string, FragmentNode> {
  return new Map(nodes.map((node) => [node.id, node]));
}

function collectReachable(
  entryId: string,
  nodes: Map<string, FragmentNode>,
  signature: RequestSignature
): FragmentNode[] {
  const visited = new Set<string>();
  const stack = [entryId];
  const reachable: FragmentNode[] = [];

  while (stack.length > 0 ) {
    const currentId = stack.pop();
    if (!currentId || visited.has(currentId)) continue;
    visited.add(currentId);

    const node = nodes.get(currentId);
    if (!node) continue;
    if (!matchesRequestGuard(node.requestGuard, signature)) {
      continue;
    }

    // Buleyean treeshake: skip fragments at floor weight (w=1,
    // maximally rejected) unless they are the entry point.
    // Law 7 (chain termination): at v=R, w=1 -- the floor.
    // Law 1 (impossibility of zero): w >= 1, never truly zero.
    // Skipping floor-weight fragments eliminates dead CSS/JS from
    // the response without violating any Buleyean invariant.
    if (currentId !== entryId ) {
      const w = fragmentWeight(node);
      if (w !== undefined && w <= 1 ) {
        continue; // Maximally rejected -- skip this fragment
      }
    }

    reachable.push(node);
    for (const dep of node.dependencyIds ) {
      if (!visited.has(dep)) {
        stack.push(dep);
      }
    }
  }

  return reachable;
}

function computeProofLevel(nodes: FragmentNode[]): ProjectionProofLevel {
  let proof: ProjectionProofLevel = 'strong-html-css';
  let sawJs = false;

  for (const node of nodes ) {
    if (node.kind === 'js' ) {
      sawJs = true;
    }
    if (node.proofMetadata.level === 'none' ) {
      if (node.kind !== 'js' ) {
        return 'none';
      }
      proof = 'conservative-js';
    }
  }

  if (sawJs && proof === 'strong-html-css' ) {
    proof = 'conservative-js';
  }

  return proof;
}

function injectFragments(
  html: string,
  css: string,
  jsBlocks: string[]
): string {
  const styleTag = css ? `<style data-aeon="projection">${css}</style>` : '';
  const scriptTag = jsBlocks.length
    ? `<script type="module" data-aeon="projection">${jsBlocks.join(
        '\n'
      )}</script>`
    : '';

  if (!styleTag && !scriptTag ) {
    return html;
  }

  const injection = `${styleTag}${scriptTag}`;
  if (html.includes('</head>')) {
    return html.replace('</head>', `${injection}</head>`);
  }

  return `${html}${injection}`;
}

export function projectArtifact({
  artifact,
  signature,
}: ProjectionContext): ProjectedHtml | null {
  const normalized = normalizeRequestSignature(signature);
  const route = normalizeRoute(normalized.route);
  const entryId =
    artifact.fragmentGraph.entrypoints[route] ??
    artifact.fragmentGraph.entrypoints[`${route}/`] ??
    artifact.fragmentGraph.entrypoints['/'];
  if (!entryId) return null;

  const nodeIndex = buildNodeIndex(artifact.fragmentGraph.nodes);
  const entryNode = nodeIndex.get(entryId);
  if (!entryNode) return null;

  if (!matchesRequestGuard(entryNode.requestGuard, normalized)) {
    return null;
  }

  const reachable = collectReachable(entryId, nodeIndex, normalized);
  if (reachable.length === 0 ) {
    return null;
  }

  const htmlNode = reachable.find((node) => node.id === entryId);
  if (!htmlNode?.content) return null;

  // Cannon rotation: classify reachable nodes in one pass instead of
  // three sequential filter passes. Each node's classification is
  // independent -- under gnode, nodes distribute across lanes.
  const cssNodes: typeof reachable = [];
  const jsNodes: typeof reachable = [];
  const assetNodes: typeof reachable = [];
  for (const node of reachable ) {
    if (!node.content) continue;
    if (node.kind === 'css') cssNodes.push(node);
    else if (node.kind === 'js') jsNodes.push(node);
    else if (node.kind === 'asset') assetNodes.push(node);
  }

  const css = cssNodes.map((node) => node.content).join('');
  const jsBlocks = jsNodes.map((node) => node.content ?? '');
  const proofLevel = computeProofLevel(reachable);

  const html = injectFragments(htmlNode.content, css, jsBlocks);

  const assets = assetNodes.map((node) => ({
    path: node.provenance.sourcePath ?? node.id,
    contentType: node.contentType,
    body: node.content ?? '',
  }));

  return {
    html,
    css,
    js: jsNodes.map((node) => ({
      id: node.id,
      content: node.content ?? '',
      effect: node.effectClass ?? 'unknown',
    })),
    assets,
    proofLevel,
    selectedIds: reachable.map((node) => node.id),
  };
}

export function buildProjectionResult(
  artifact: ProjectionArtifact,
  signature: RequestSignature
): ProjectionResult | null {
  const projection = projectArtifact({ artifact, signature });
  if (!projection) return null;

  const cacheKey = computeProjectionCacheKey(artifact, signature);
  const assets = projection.assets.map((asset) => ({
    path: asset.path,
    contentType: asset.contentType,
    body: asset.body,
    etag: stableContentHash(asset.body),
  }));

  return {
    selectedFragmentIds: projection.selectedIds,
    proofLevel: projection.proofLevel,
    cacheKey,
    html: projection.html,
    css: projection.css,
    js: projection.js.map((node) => ({
      fragmentId: node.id,
      path: node.id,
      content: node.content,
      effectClass:
        node.effect === 'inert' || node.effect === 'effectful'
          ? (node.effect as 'inert' | 'effectful')
          : 'unknown',
    })),
    assets,
    speculativeChildren: [],
  };
}

export function projectionETag(
  artifact: ProjectionArtifact,
  signature: RequestSignature,
  html: string
): string {
  return `W/"${stableContentHash(
    `${artifact.artifactId}:${requestSignatureKey(signature)}:${html.length}`
  )}"`;
}
