/**
 * Custodial Signer Contracts
 *
 * World-facing contract definitions for action-scoped custodial
 * transaction signing. Implementations can use KMS/HSM, MPC, or
 * other hardened signing backends as long as they satisfy this shape.
 */

export type HexString = `0x${string}`;

export type CustodialSignerPayloadMap = Record<string, unknown>;

export type CustodialSignerExecuteRequestFor<
  TPayloads extends CustodialSignerPayloadMap,
  TAction extends keyof TPayloads & string = keyof TPayloads & string
> = {
  action: TAction;
  payload: TPayloads[TAction];
  chainId?: number;
  waitForReceipt?: boolean;
  requestId?: string;
};

export type CustodialSignerReceiptStatus = 'pending' | 'success' | 'reverted';

export type CustodialSignerErrorCode =
  | 'invalid_request'
  | 'signer_unavailable'
  | 'signer_denied'
  | 'tx_failed'
  | 'tx_reverted'
  | 'unauthorized'
  | 'forbidden'
  | 'unknown_action'
  | 'upstream_error';

export interface CustodialSignerExecuteResponse<
  TAction extends string = string
> {
  success: boolean;
  action: TAction;
  chainId: number;
  txHash?: HexString;
  receiptStatus?: CustodialSignerReceiptStatus;
  signerAddress?: HexString;
  keyVersion?: string;
  errorCode?: CustodialSignerErrorCode;
  errorMessage?: string;
  revertReason?: string;
}

export interface CustodialSignerMetadata<TAction extends string = string> {
  action: TAction;
  chainId: number;
  signerAddress: HexString;
  keyVersion: string;
  keyName: string;
}

export interface CustodialSignerHealthResponse {
  ok: boolean;
  service: 'custodial-signer';
  timestamp: string;
}

export interface CustodialSignerBalanceResponse<
  TAction extends string = string
> {
  action: TAction;
  chainId: number;
  signerAddress: HexString;
  balanceWei: string;
  balanceFormatted: string;
}

export interface CustodialSignerClientContractFor<
  TPayloads extends CustodialSignerPayloadMap
> {
  execute<TAction extends keyof TPayloads & string>(
    request: CustodialSignerExecuteRequestFor<TPayloads, TAction>
  ): Promise<CustodialSignerExecuteResponse<TAction>>;

  getSigner<TAction extends keyof TPayloads & string>(
    action: TAction
  ): Promise<CustodialSignerMetadata<TAction>>;

  getBalance<TAction extends keyof TPayloads & string>(
    action: TAction
  ): Promise<CustodialSignerBalanceResponse<TAction>>;

  health(): Promise<CustodialSignerHealthResponse>;
}

/**
 * Affectively default action namespace.
 *
 * These actions are namespaced and reusable across deployments while
 * keeping contract/function inputs fixed per action on the signer side.
 */
export const CUSTODIAL_SIGNER_ACTIONS = [
  'halos.recordExhaust',
  'halos.signDisclosure',
  'halos.consent.agree',
  'halos.consent.ack',
  'halos.consent.snooze',
  'edgework.relayer.registerGatewayViaSignature',
  'edgework.oracle.updateProviderCosts',
  'edgework.oracle.setProviderWeights',
  'edgework.oracle.batchUpdateModelCosts',
  'mcp.memento.publishMemento',
  'mcp.memento.eraseMemento',
  'mcp.memento.createMemento',
  'mcp.memento.batchCreateMementos',
  'mcp.memento.tombstoneMemento',
  'mcp.badge.mintBadgeBatch',
  'mcp.badge.burnBadge',
] as const;

export type CustodialSignerAction = (typeof CUSTODIAL_SIGNER_ACTIONS)[number];

export type ConsentTarget = 'agreement_to_mediate' | 'confidentiality';
export type ConsentSnoozeDuration = 'none' | '24h' | '1w' | '1m' | 'always';
export type ConsentRole = 'initiator' | 'respondent';
export type NumericInput = string | number | bigint;

export interface CustodialSignerActionPayloads {
  'halos.recordExhaust': {
    exhaustType: HexString;
    dataHash: HexString;
    metadata: HexString;
  };
  'halos.signDisclosure': {
    signoffId: string;
    userId: string;
    disclosureHash: HexString;
    disclosureType: string;
    disclosureVersion: string;
  };
  'halos.consent.agree': {
    caseId: string;
    role: ConsentRole;
    caseTitle: string;
    initiatorName: string;
    respondentName: string;
    mediatorName: string;
    caseCategory: string;
  };
  'halos.consent.ack': {
    caseId: string;
    role: ConsentRole;
    caseTitle: string;
    partyName: string;
    mediatorName: string;
  };
  'halos.consent.snooze': {
    target: ConsentTarget;
    duration: ConsentSnoozeDuration;
  };
  'edgework.relayer.registerGatewayViaSignature': {
    gateway: string;
    ucanRoot: HexString;
    metadata: string;
    signature: HexString;
  };
  'edgework.oracle.updateProviderCosts': {
    openAI: NumericInput;
    anthropic: NumericInput;
    openSource: NumericInput;
    edgework: NumericInput;
  };
  'edgework.oracle.setProviderWeights': {
    openAI: NumericInput;
    anthropic: NumericInput;
    google: NumericInput;
    openSource: NumericInput;
    other: NumericInput;
  };
  'edgework.oracle.batchUpdateModelCosts': {
    modelIds: HexString[];
    providers: string[];
    inputCosts: NumericInput[];
    outputCosts: NumericInput[];
  };
  'mcp.memento.publishMemento': {
    mementoHash: HexString;
    latitude: NumericInput;
    longitude: NumericInput;
    creatorAddress: string;
    visibility: NumericInput;
  };
  'mcp.memento.eraseMemento': {
    mementoHash: HexString;
    newCreator: string;
  };
  'mcp.memento.createMemento': {
    contentHash: HexString;
    latitude: NumericInput;
    longitude: NumericInput;
    visibility: NumericInput;
    ipfsCid: string;
  };
  'mcp.memento.batchCreateMementos': {
    mementos: Array<{
      contentHash: HexString;
      latitude: NumericInput;
      longitude: NumericInput;
      visibility: NumericInput;
      ipfsCid: string;
    }>;
  };
  'mcp.memento.tombstoneMemento': {
    tokenId: NumericInput;
    replacementContentHash: HexString;
  };
  'mcp.badge.mintBadgeBatch': {
    recipients: string[];
    badgeIds: string[];
    names: string[];
    descriptions: string[];
    categories: NumericInput[];
    earnedAts: NumericInput[];
    icons: string[];
    currentProgresses: NumericInput[];
    targetProgresses: NumericInput[];
    contentHashes: HexString[];
  };
  'mcp.badge.burnBadge': {
    tokenId: NumericInput;
  };
  // Index signature to satisfy Record<string, unknown> constraint
  [key: string]: unknown;
}

export type CustodialSignerExecuteRequest =
  CustodialSignerExecuteRequestFor<CustodialSignerActionPayloads>;

export type CustodialSignerClientContract =
  CustodialSignerClientContractFor<CustodialSignerActionPayloads>;

export const CUSTODIAL_SIGNER_RETRYABLE_CODES: ReadonlySet<CustodialSignerErrorCode> =
  new Set<CustodialSignerErrorCode>(['signer_unavailable', 'upstream_error']);
