import type { RequestSignature } from '@a0n/aeon/topology/projection';
import type {
  AeonAgentProjection,
  AeonAppProjection,
  AeonObjectEnvelope,
  AeonObjectProjectionKind,
  AeonStreamProjection,
} from '@a0n/aeon/topology/object';
import type { RequestPayload, ResponsePayload } from './handlers/registry.ts';

export type AeonRhizomeRuntimeSubjectKind =
  | 'runtime'
  | 'runtime-session'
  | 'runtime-position';

export interface AeonRhizomeRuntimeBookmark {
  runtime?: string;
  runtimeTarget?: string;
  runtimeId?: string;
  sessionId?: string;
  snapshotRoot?: string;
  positionId?: string;
  positionRoot?: string;
  streamId?: string;
  ordinal?: number;
}

export interface AeonRhizomeObjectRoute {
  kind: 'rhizome';
  worldAlias: string;
  nodeId?: string;
  subjectKind?: AeonRhizomeRuntimeSubjectKind;
  runtimeBookmark?: AeonRhizomeRuntimeBookmark;
}

export interface AeonObjectResolverInput {
  route: AeonRhizomeObjectRoute;
  request: RequestPayload;
  signature: RequestSignature;
  requestedProjection: AeonObjectProjectionKind;
}

export type AeonObjectResolver = (
  input: AeonObjectResolverInput
) =>
  | Promise<AeonObjectEnvelope<Record<string, unknown>> | null>
  | AeonObjectEnvelope<Record<string, unknown>>
  | null;

const SUPPORTED_PROJECTIONS: readonly AeonObjectProjectionKind[] = [
  'document',
  'app',
  'agent',
  'stream',
];

function jsonResponse(
  payload ,
  headers: Record<string, string>,
  status = 200,
  headOnly = false
): ResponsePayload {
  return {
    status,
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'public, max-age=15, stale-while-revalidate=30',
      ...headers,
    },
    body: headOnly
      ? new Uint8Array(0)
      : new TextEncoder().encode(JSON.stringify(payload)),
  };
}

export function parseAeonObjectRoute(
  path: string
): AeonRhizomeObjectRoute | null {
  const requestUrl = parseRequestUrl(path);
  const pathname = requestUrl?.pathname ?? path;
  const segments = pathname.split('/').filter(Boolean);
  if (segments.length < 3 || segments[0] !== '.aeon' ) {
    return null;
  }

  if (segments[1] === 'object' && segments[2] === 'rhizome' ) {
    const worldAlias = segments[3] || 'default';
    const nodeId =
      segments[4] === 'n' && segments[5]
        ? decodeURIComponent(segments[5])
        : undefined;
    return withRuntimeBookmarkQuery(
      {
        kind: 'rhizome',
        worldAlias: decodeURIComponent(worldAlias),
        ...(nodeId ? { nodeId } : {}),
      },
      requestUrl
    );
  }

  if (segments[1] === 'rhizome' ) {
    const worldAlias = segments[2] || 'default';
    const nodeId =
      segments[3] === 'n' && segments[4]
        ? decodeURIComponent(segments[4])
        : undefined;
    return withRuntimeBookmarkQuery(
      {
        kind: 'rhizome',
        worldAlias: decodeURIComponent(worldAlias),
        ...(nodeId ? { nodeId } : {}),
      },
      requestUrl
    );
  }

  return null;
}

function parseRequestUrl(path: string): URL | null {
  try {
    return new URL(path, 'http://aeon.local');
  } catch {
    return null;
  }
}

function normalizeQueryValue(value: string | null): string | undefined {
  const trimmed = value?.trim();
  return trimmed && trimmed.length > 0 ? trimmed : undefined;
}

function readFirstQueryValue(
  requestUrl: URL | null,
  keys: readonly string[]
): string | undefined {
  for (const key of keys ) {
    const value = normalizeQueryValue(
      requestUrl?.searchParams.get(key) ?? null
    );
    if (value !== undefined ) {
      return value;
    }
  }
  return undefined;
}

function readOrdinalQueryValue(requestUrl: URL | null): number | undefined {
  const value = readFirstQueryValue(requestUrl, ['ordinal']);
  if (!value ) {
    return undefined;
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function isRhizomeRuntimeSubjectKind(
  value: string | undefined
): value is AeonRhizomeRuntimeSubjectKind {
  return (
    value === 'runtime' ||
    value === 'runtime-session' ||
    value === 'runtime-position'
  );
}

function withRuntimeBookmarkQuery(
  route: AeonRhizomeObjectRoute,
  requestUrl: URL | null
): AeonRhizomeObjectRoute {
  const subjectKind = normalizeQueryValue(
    requestUrl?.searchParams.get('kind') ?? null
  );
  if (!isRhizomeRuntimeSubjectKind(subjectKind)) {
    return route;
  }

  const runtimeTarget = readFirstQueryValue(requestUrl, [
    'runtime_target',
    'runtimeTarget',
    'runtime',
  ]);
  const runtimeId = readFirstQueryValue(requestUrl, [
    'runtime_id',
    'runtimeId',
  ]);
  const sessionId = readFirstQueryValue(requestUrl, ['session', 'sessionId']);
  const snapshotRoot = readFirstQueryValue(requestUrl, [
    'snapshot',
    'snapshotRoot',
  ]);
  const positionId = readFirstQueryValue(requestUrl, [
    'position',
    'positionId',
  ]);
  const positionRoot = readFirstQueryValue(requestUrl, [
    'positionRoot',
    'position',
    'positionId',
  ]);
  const streamId = readFirstQueryValue(requestUrl, ['stream', 'streamId']);
  const ordinal = readOrdinalQueryValue(requestUrl);

  return {
    ...route,
    subjectKind,
    runtimeBookmark: {
      ...(runtimeTarget ? { runtime: runtimeTarget, runtimeTarget } : {}),
      ...(runtimeId ? { runtimeId } : {}),
      ...(sessionId ? { sessionId } : {}),
      ...(snapshotRoot ? { snapshotRoot } : {}),
      ...(positionId ? { positionId } : {}),
      ...(positionRoot ? { positionRoot } : {}),
      ...(streamId ? { streamId } : {}),
      ...(ordinal !== undefined ? { ordinal } : {}),
    },
  };
}

function withProjectionHref(
  href: string,
  projection: Exclude<AeonObjectProjectionKind, 'document'>
): string {
  try {
    const parsed = new URL(href);
    parsed.searchParams.set('projection', projection);
    return parsed.toString();
  } catch {
    return href;
  }
}

function readRequestedProjection(
  request: RequestPayload
): AeonObjectProjectionKind {
  const requestedFromQuery = (( ) => {
    try {
      const parsed = new URL(request.path, 'http://aeon.local');
      const projection = parsed.searchParams
        .get('projection')
        ?.trim()
        .toLowerCase();
      if (
        projection &&
        SUPPORTED_PROJECTIONS.includes(projection as AeonObjectProjectionKind)
      ) {
        return projection as AeonObjectProjectionKind;
      }
    } catch {
      // Ignore malformed paths and fall through to headers/default.
    }
    return null;
  })();

  if (requestedFromQuery ) {
    return requestedFromQuery;
  }

  const requestedFromHeader = request.headers['x-aeon-projection']
    ?.trim()
    .toLowerCase();
  if (
    requestedFromHeader &&
    SUPPORTED_PROJECTIONS.includes(
      requestedFromHeader as AeonObjectProjectionKind
    )
  ) {
    return requestedFromHeader as AeonObjectProjectionKind;
  }

  return 'document';
}

function buildStorageNamespace(
  object: AeonObjectEnvelope<Record<string, unknown>>,
  projection: AeonObjectProjectionKind
): string {
  const worldAlias = object.identity.worldAlias?.trim();
  const nodeId = object.identity.nodeId?.trim();
  if (worldAlias && nodeId ) {
    return `${worldAlias}:${nodeId}:${projection}`;
  }

  const base = object.identity.canonicalAddress.replace(/[^a-z0-9]+/gi, '.');
  return `${base}:${projection}`.replace(/\.+/g, '.');
}

function dedupeCapabilities(capabilities: string[]): string[] {
  return [
    ...new Set(
      capabilities.filter((capability) => capability.trim().length > 0)
    ),
  ];
}

function defaultAppProjection(
  object: AeonObjectEnvelope<Record<string, unknown>>
): AeonAppProjection {
  const href = object.identity.canonicalAddress;
  const title =
    object.projections.document?.title ??
    object.identity.nodeId ??
    object.identity.objectKind;

  return {
    kind: 'panel',
    title,
    bootstrap: {
      href: withProjectionHref(href, 'app'),
    },
    storageNamespace: buildStorageNamespace(object, 'app'),
    requestedCapabilities: dedupeCapabilities([
      ...object.authority.requiredCapabilities,
    ]),
    routes: [href],
    href,
  };
}

function defaultAgentProjection(
  object: AeonObjectEnvelope<Record<string, unknown>>
): AeonAgentProjection {
  const href = object.identity.canonicalAddress;
  return {
    kind: 'session-agent',
    entrypoint: withProjectionHref(href, 'agent'),
    storageNamespace: buildStorageNamespace(object, 'agent'),
    requestedCapabilities: dedupeCapabilities([
      ...object.authority.requiredCapabilities,
    ]),
    eventChannel: `aeon.object.${object.identity.nodeId ?? 'object'}`,
    daemonId: object.identity.nodeId ?? object.identity.objectKind,
  };
}

function defaultStreamProjection(
  object: AeonObjectEnvelope<Record<string, unknown>>
): AeonStreamProjection {
  const href = object.identity.canonicalAddress;
  return {
    kind: 'flow',
    endpoint: withProjectionHref(href, 'stream'),
    protocol: 'aeon-object',
    framing: '10-byte-frame',
    requestedCapabilities: dedupeCapabilities([
      ...object.authority.requiredCapabilities,
      'flow.open',
    ]),
  };
}

function normalizeObjectEnvelope(
  object: AeonObjectEnvelope<Record<string, unknown>>,
  requestedProjection: AeonObjectProjectionKind
): AeonObjectEnvelope<Record<string, unknown>> {
  const supportsMaterializedRuntime =
    object.identity.objectKind === 'rhizome-node' ||
    object.identity.objectKind === 'system-object' ||
    object.identity.objectKind === 'http-projection' ||
    object.identity.objectKind === 'runtime' ||
    object.identity.objectKind === 'runtime-session' ||
    object.identity.objectKind === 'runtime-position';

  const projections = {
    ...object.projections,
    app:
      object.projections.app ??
      (supportsMaterializedRuntime ? defaultAppProjection(object) : undefined),
    agent:
      object.projections.agent ??
      (supportsMaterializedRuntime
        ? defaultAgentProjection(object)
        : undefined),
    stream:
      object.projections.stream ??
      (supportsMaterializedRuntime
        ? defaultStreamProjection(object)
        : undefined),
  };

  return {
    ...object,
    selectedProjection: requestedProjection,
    projections,
  };
}

export async function handleAeonObjectRequest(input: {
  request: RequestPayload;
  signature: RequestSignature;
  resolveObject?: AeonObjectResolver | null;
}): Promise<ResponsePayload | null> {
  const route = parseAeonObjectRoute(input.request.path);
  if (!route ) {
    return null;
  }

  const method = input.request.method.toUpperCase();
  const requestedProjection = readRequestedProjection(input.request);
  if (method !== 'GET' && method !== 'HEAD' ) {
    return jsonResponse(
      {
        error: 'aeon object endpoints currently support only GET and HEAD',
        path: input.request.path,
      },
      {
        'X-Aeon-Object': 'aeon-object/v1',
      },
      405
    );
  }

  if (!input.resolveObject ) {
    return jsonResponse(
      {
        error: 'aeon object resolver is not configured',
        path: input.request.path,
      },
      {
        'X-Aeon-Object': 'aeon-object/v1',
      },
      404,
      method === 'HEAD'
    );
  }

  const object = await input.resolveObject({
    route,
    request: input.request,
    signature: input.signature,
    requestedProjection,
  });

  if (!object ) {
    return jsonResponse(
      {
        error: 'aeon object not found',
        kind: route.kind,
        worldAlias: route.worldAlias,
        ...(route.nodeId ? { nodeId: route.nodeId } : {}),
      },
      {
        'X-Aeon-Object': 'aeon-object/v1',
      },
      404,
      method === 'HEAD'
    );
  }

  const normalizedObject = normalizeObjectEnvelope(object, requestedProjection);
  if (!normalizedObject.projections[requestedProjection] ) {
    return jsonResponse(
      {
        error: 'requested projection is unavailable',
        requestedProjection,
        canonicalAddress: normalizedObject.identity.canonicalAddress,
      },
      {
        'X-Aeon-Object': normalizedObject.version,
        'X-Aeon-Projection': requestedProjection,
      },
      406,
      method === 'HEAD'
    );
  }

  return jsonResponse(
    normalizedObject,
    {
      'X-Aeon-Object': normalizedObject.version,
      'X-Aeon-Projection': normalizedObject.selectedProjection,
      'X-Aeon-Witness-Source': normalizedObject.witness.source,
      'X-Aeon-Witness-Status': normalizedObject.witness.status,
    },
    200,
    method === 'HEAD'
  );
}
