export interface FiniteDistributionWitness {
  readonly weights: readonly number[];
  readonly totalMass: number;
  readonly positiveTotal: true;
}

export interface ProbabilityRatioWitness {
  readonly numerator: number;
  readonly denominator: number;
}

export interface FiniteChannelWitness {
  readonly input: FiniteDistributionWitness;
  readonly output: FiniteDistributionWitness;
  readonly lostMass: number;
  readonly balanced: true;
}

export interface FiniteProcessWitness {
  readonly input: FiniteDistributionWitness;
  readonly output: FiniteDistributionWitness;
  readonly massLoss: number;
  readonly residual: number;
  readonly balanced: true;
  readonly lossCovered: true;
}

export interface FiniteProcessChainWitness {
  readonly input: FiniteDistributionWitness;
  readonly output: FiniteDistributionWitness;
  readonly processes: readonly FiniteProcessWitness[];
  readonly massLoss: number;
  readonly residual: number;
  readonly balanced: true;
  readonly lossCovered: true;
}

export interface FiniteKernelRowWitness {
  readonly inputMass: number;
  readonly outputWeights: readonly number[];
  readonly outputMass: number;
  readonly lostMass: number;
  readonly balanced: true;
}

export interface FiniteKernelWitness {
  readonly input: FiniteDistributionWitness;
  readonly output: FiniteDistributionWitness;
  readonly rows: readonly FiniteKernelRowWitness[];
  readonly lostMass: number;
  readonly balanced: true;
}

export interface FiniteMarkovWitnessRuntime {
  readonly kernels: readonly FiniteKernelWitness[];
  readonly shadowResidual: number;
  readonly totalShadow: number;
}

export interface FiniteCoverWitness {
  readonly footprint: number;
  readonly shadow: number;
  readonly horizon: FiniteHorizonWitness;
  readonly footprintBounded: true;
  readonly shadowBounded: true;
}

export interface FiniteHorizonWitness {
  readonly depth: number;
  readonly residualBudget: number;
}

export interface MattressAccountingWitness {
  readonly inputMass: number;
  readonly visibleMass: number;
  readonly shadowMass: number;
  readonly accountedMass: number;
  readonly conservedOrShadowed: true;
}

export interface FiniteProbabilityCompilerOptions {
  readonly allowZeroWeights?: boolean;
}

function assertNat(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error(`${label} must be a safe natural number`);
  }
}

function sumNat(values: readonly number[], label: string): number {
  let total = 0;
  for (let index = 0; index < values.length; index++) {
    const value = values[index] ?? 0;
    assertNat(value, `${label}[${index}]`);
    total += value;
    assertNat(total, `${label}.sum`);
  }
  return total;
}

export function compileFiniteDistribution(
  weights: readonly number[],
  options: FiniteProbabilityCompilerOptions = {}
): FiniteDistributionWitness {
  const totalMass = sumNat(weights, 'weights');
  if (totalMass === 0 && options.allowZeroWeights !== true) {
    throw new Error('finite distribution requires positive total mass');
  }
  if (totalMass === 0) {
    throw new Error('zero-mass distributions cannot witness Lean FiniteDistribution');
  }
  return {
    weights: [...weights],
    totalMass,
    positiveTotal: true,
  };
}

export function probabilityRatio(
  numerator: number,
  denominator: number
): ProbabilityRatioWitness {
  assertNat(numerator, 'numerator');
  assertNat(denominator, 'denominator');
  if (denominator === 0) {
    throw new Error('probability ratio denominator must be positive');
  }
  return { numerator, denominator };
}

export function eventMass(
  distribution: FiniteDistributionWitness,
  mask: readonly boolean[]
): number {
  let mass = 0;
  for (let index = 0; index < distribution.weights.length; index++) {
    if (mask[index] === true) {
      mass += distribution.weights[index] ?? 0;
      assertNat(mass, 'eventMass');
    }
  }
  return mass;
}

export function eventProbability(
  distribution: FiniteDistributionWitness,
  mask: readonly boolean[]
): ProbabilityRatioWitness {
  return probabilityRatio(eventMass(distribution, mask), distribution.totalMass);
}

export function compileFiniteChannel(
  input: FiniteDistributionWitness,
  output: FiniteDistributionWitness
): FiniteChannelWitness {
  if (output.totalMass > input.totalMass) {
    throw new Error('finite channel output mass cannot exceed input mass');
  }
  return {
    input,
    output,
    lostMass: input.totalMass - output.totalMass,
    balanced: true,
  };
}

export function compileFiniteProcess(
  input: FiniteDistributionWitness,
  output: FiniteDistributionWitness,
  residual: number = input.totalMass - output.totalMass
): FiniteProcessWitness {
  const channel = compileFiniteChannel(input, output);
  assertNat(residual, 'residual');
  if (residual < channel.lostMass) {
    throw new Error('finite process residual must cover channel mass loss');
  }
  return {
    input,
    output,
    massLoss: channel.lostMass,
    residual,
    balanced: true,
    lossCovered: true,
  };
}

export function mattressAccounting(
  process: FiniteProcessWitness
): MattressAccountingWitness {
  const accountedMass = process.output.totalMass + process.residual;
  if (accountedMass < process.input.totalMass) {
    throw new Error('process violates mattress accounting');
  }
  return {
    inputMass: process.input.totalMass,
    visibleMass: process.output.totalMass,
    shadowMass: process.residual,
    accountedMass,
    conservedOrShadowed: true,
  };
}

export function composeProcesses(
  first: FiniteProcessWitness,
  second: FiniteProcessWitness
): FiniteProcessWitness {
  if (first.output.totalMass !== second.input.totalMass) {
    throw new Error('process composition requires first output mass to match second input mass');
  }
  return {
    input: first.input,
    output: second.output,
    massLoss: first.massLoss + second.massLoss,
    residual: first.residual + second.residual,
    balanced: true,
    lossCovered: true,
  };
}

export function compileProcessChain(
  processes: readonly FiniteProcessWitness[]
): FiniteProcessChainWitness {
  if (processes.length === 0) {
    throw new Error('process chain requires at least one process');
  }
  const input = processes[0]?.input;
  let output = processes[0]?.output;
  if (input === undefined || output === undefined) {
    throw new Error('process chain requires at least one process');
  }
  let massLoss = 0;
  let residual = 0;
  for (let index = 0; index < processes.length; index++) {
    const process = processes[index];
    if (process === undefined) {
      throw new Error(`missing process at index ${index}`);
    }
    if (index > 0 && output.totalMass !== process.input.totalMass) {
      throw new Error(`process chain mass mismatch at index ${index}`);
    }
    output = process.output;
    massLoss += process.massLoss;
    residual += process.residual;
    assertNat(massLoss, 'processChain.massLoss');
    assertNat(residual, 'processChain.residual');
  }
  if (massLoss > input.totalMass) {
    throw new Error('process chain mass loss exceeds input mass');
  }
  return {
    input,
    output,
    processes: [...processes],
    massLoss,
    residual,
    balanced: true,
    lossCovered: true,
  };
}

export function compileKernelRow(
  inputMass: number,
  outputWeights: readonly number[]
): FiniteKernelRowWitness {
  assertNat(inputMass, 'inputMass');
  const outputMass = sumNat(outputWeights, 'outputWeights');
  if (outputMass > inputMass) {
    throw new Error('kernel row output mass cannot exceed input mass');
  }
  return {
    inputMass,
    outputWeights: [...outputWeights],
    outputMass,
    lostMass: inputMass - outputMass,
    balanced: true,
  };
}

export function compileFiniteKernel(
  rows: readonly FiniteKernelRowWitness[]
): FiniteKernelWitness {
  if (rows.length === 0) {
    throw new Error('finite kernel requires at least one row');
  }
  const inputWeights = rows.map((row) => row.inputMass);
  const outputWeights = rows.map((row) => row.outputMass);
  const input = compileFiniteDistribution(inputWeights);
  const output = compileFiniteDistribution(outputWeights);
  const lostMass = rows.reduce((sum, row) => sum + row.lostMass, 0);
  assertNat(lostMass, 'kernel.lostMass');
  return {
    input,
    output,
    rows: [...rows],
    lostMass,
    balanced: true,
  };
}

export function kernelToProcess(
  kernel: FiniteKernelWitness,
  residual: number = kernel.lostMass
): FiniteProcessWitness {
  return compileFiniteProcess(kernel.input, kernel.output, residual);
}

export function compileMarkovWitness(
  kernels: readonly FiniteKernelWitness[],
  shadowResidual: number = 0
): FiniteMarkovWitnessRuntime {
  assertNat(shadowResidual, 'shadowResidual');
  const kernelLoss = kernels.reduce((sum, kernel) => sum + kernel.lostMass, 0);
  assertNat(kernelLoss, 'markov.kernelLoss');
  return {
    kernels: [...kernels],
    shadowResidual,
    totalShadow: kernelLoss + shadowResidual,
  };
}

export function compileFiniteCover(
  footprint: number,
  shadow: number,
  horizon: FiniteHorizonWitness
): FiniteCoverWitness {
  assertNat(footprint, 'footprint');
  assertNat(shadow, 'shadow');
  assertNat(horizon.depth, 'horizon.depth');
  assertNat(horizon.residualBudget, 'horizon.residualBudget');
  if (footprint > horizon.depth) {
    throw new Error('finite cover footprint exceeds horizon depth');
  }
  if (shadow > horizon.residualBudget) {
    throw new Error('finite cover shadow exceeds residual budget');
  }
  return {
    footprint,
    shadow,
    horizon,
    footprintBounded: true,
    shadowBounded: true,
  };
}

export function processChainToCover(
  chain: FiniteProcessChainWitness,
  horizon: FiniteHorizonWitness
): FiniteCoverWitness {
  return compileFiniteCover(chain.output.totalMass, chain.residual, horizon);
}

export function markovWitnessToCover(
  witness: FiniteMarkovWitnessRuntime,
  footprint: number,
  horizon: FiniteHorizonWitness
): FiniteCoverWitness {
  return compileFiniteCover(footprint, witness.totalShadow, horizon);
}
