import { sha256Hex } from './crypto.js';
import type {
  AdmissiblePathProof,
  FederationChainId,
  FederationEpoch,
  RouteEnvelope,
  RouteHop,
} from './types.js';

export interface PathProofInput {
  readonly fromChainId: FederationChainId;
  readonly toChainId: FederationChainId;
  readonly epoch: FederationEpoch;
  readonly hops: readonly RouteHop[];
}

function computeSeed(input: PathProofInput): string {
  return sha256Hex({
    fromChainId: input.fromChainId,
    toChainId: input.toChainId,
    epoch: input.epoch,
    hopCount: input.hops.length,
  });
}

export function buildPathProof(input: PathProofInput): AdmissiblePathProof {
  const seed = computeSeed(input);
  const hopDigests: string[] = [];

  let rollingDigest = seed;
  for (const hop of input.hops) {
    rollingDigest = sha256Hex({
      rollingDigest,
      hopIndex: hop.index,
      hopChainId: hop.chainId,
      hopEndpoint: hop.endpoint,
      witnessDigest: hop.witnessDigest,
    });
    hopDigests.push(rollingDigest);
  }

  return {
    scheme: 'sha256-hop-chain/v1',
    seed,
    hopDigests,
    terminalDigest: rollingDigest,
  };
}

export function verifyPathProof(input: PathProofInput, proof: AdmissiblePathProof): boolean {
  if (proof.scheme !== 'sha256-hop-chain/v1') {
    return false;
  }

  const rebuilt = buildPathProof(input);

  if (rebuilt.seed !== proof.seed) {
    return false;
  }

  if (rebuilt.hopDigests.length !== proof.hopDigests.length) {
    return false;
  }

  for (let index = 0; index < rebuilt.hopDigests.length; index += 1) {
    if (rebuilt.hopDigests[index] !== proof.hopDigests[index]) {
      return false;
    }
  }

  return rebuilt.terminalDigest === proof.terminalDigest;
}

export function isBoundedTwoHopRoute(hops: readonly RouteHop[]): boolean {
  return hops.length <= 2;
}

export function computeRouteDigest(
  route: Omit<RouteEnvelope, 'digest' | 'signature'>
): string {
  return sha256Hex({
    epoch: route.epoch,
    fromChainId: route.fromChainId,
    toChainId: route.toChainId,
    destinationChainId: route.destination.chainId,
    destinationIndex: route.destination.index,
    witnessDigest: route.witness.digest,
    hopDigest: route.pathProof.terminalDigest,
    expiresAt: route.expiresAt,
  });
}
