/**
 * @a0n/auth - Token Creation & Verification
 *
 * UCAN token creation, parsing, and verification
 */

import type {
  DID,
  Identity,
  Capability,
  UCANPayload,
  UCANToken,
  CreateUCANOptions,
  VerifyUCANOptions,
  VerificationResult,
  SigningAlgorithm,
} from './ucanTypes.ts';
import {
  sign,
  verify,
  generateNonce,
  generateTokenId,
  base64UrlEncode,
  base64UrlDecode,
} from './identity.js';

/**
 * UCAN version
 */
const UCAN_VERSION = '0.10.0';

/**
 * Default expiration (1 hour in seconds)
 */
const DEFAULT_EXPIRATION_SECONDS = 60 * 60;

/**
 * Algorithm to JWT alg mapping
 */
const ALG_MAP: Record<SigningAlgorithm, string> = {
  ES256: 'ES256',
  ES384: 'ES384',
  ES512: 'ES512',
  Ed25519: 'EdDSA',
};

/**
 * JWT alg to algorithm mapping
 */
const REVERSE_ALG_MAP: Record<string, SigningAlgorithm> = {
  ES256: 'ES256',
  ES384: 'ES384',
  ES512: 'ES512',
  EdDSA: 'Ed25519',
};

/**
 * Create a UCAN token
 *
 * @param issuer - Identity of the token issuer (must have private key)
 * @param audience - DID of the intended recipient
 * @param capabilities - Array of capabilities to grant
 * @param options - Additional options
 * @returns Encoded UCAN token string
 *
 * @example
 * ```typescript
 * const token = await createUCAN(identity, audienceDID, [
 *   { can: 'file/read', with: 'storage://bucket/*' },
 *   { can: 'file/write', with: 'storage://bucket/uploads/*' },
 * ], { expirationSeconds: 3600 });
 * ```
 */
export async function createUCAN(
  issuer: Identity,
  audience: DID,
  capabilities: Capability[],
  options?: CreateUCANOptions
): Promise<string> {
  if (!issuer.signingKey.privateKey) {
    throw new Error('Issuer must have a private key to create UCAN');
  }

  const {
    expirationSeconds = DEFAULT_EXPIRATION_SECONDS,
    notBeforeSeconds,
    proofs = [],
    facts,
    nonce = generateNonce(),
  } = options || {};

  const now = Math.floor(Date.now() / 1000);

  // Build payload
  const payload: UCANPayload = {
    iss: issuer.did,
    aud: audience,
    exp: now + expirationSeconds,
    iat: now,
    att: capabilities,
    nonce,
    jti: generateTokenId(),
  };

  if (notBeforeSeconds !== undefined) {
    payload.nbf = now + notBeforeSeconds;
  }

  if (proofs.length > 0) {
    payload.prf = proofs;
  }

  if (facts) {
    payload.fct = facts;
  }

  // Build header
  const algorithm = issuer.signingKey.algorithm;
  const header = {
    alg: ALG_MAP[algorithm],
    typ: 'JWT',
    ucv: UCAN_VERSION,
  };

  // Encode header and payload
  const encodedHeader = base64UrlEncode(
    new TextEncoder().encode(JSON.stringify(header))
  );
  const encodedPayload = base64UrlEncode(
    new TextEncoder().encode(JSON.stringify(payload))
  );

  // Sign
  const signingInput = `${encodedHeader}.${encodedPayload}`;
  const signature = await sign(issuer, new TextEncoder().encode(signingInput));
  const encodedSignature = base64UrlEncode(signature);

  return `${signingInput}.${encodedSignature}`;
}

/**
 * Parse a UCAN token without verification
 *
 * @param token - Encoded UCAN token string
 * @returns Parsed UCAN token
 */
export function parseUCAN(token: string): UCANToken {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('Invalid UCAN format: expected 3 parts');
  }

  const [encodedHeader, encodedPayload, encodedSignature] = parts;

  try {
    const header = JSON.parse(
      new TextDecoder('utf-8', { fatal: true }).decode(
        base64UrlDecode(encodedHeader)
      )
    );
    const payload = JSON.parse(
      new TextDecoder('utf-8', { fatal: true }).decode(
        base64UrlDecode(encodedPayload)
      )
    ) as UCANPayload;
    const signature = base64UrlDecode(encodedSignature);

    return {
      payload,
      raw: token,
      signature,
      algorithm: header.alg,
    };
  } catch (error) {
    throw new Error(
      `Failed to parse UCAN: ${
        error instanceof Error ? error.message : 'Unknown error'
      }`
    );
  }
}

/**
 * Verify a UCAN token
 *
 * @param token - Encoded UCAN token string
 * @param issuerPublicKey - Public key of the issuer for signature verification
 * @param options - Verification options
 * @returns Verification result
 *
 * @example
 * ```typescript
 * const result = await verifyUCAN(token, issuerPublicKey, {
 *   audience: myDID,
 *   requiredCapabilities: [{ can: 'file/read', with: '*' }],
 * });
 *
 * if (result.valid) {
 *   console.log('Token is valid!');
 * }
 * ```
 */
export async function verifyUCAN(
  token: string,
  issuerPublicKey: JsonWebKey,
  options?: VerifyUCANOptions
): Promise<VerificationResult> {
  const {
    audience,
    requiredCapabilities,
    now = Math.floor(Date.now() / 1000),
  } = options || {};

  let parsed: UCANToken;

  try {
    parsed = parseUCAN(token);
  } catch (error) {
    return {
      valid: false,
      error: `Parse error: ${
        error instanceof Error ? error.message : 'Unknown'
      }`,
    };
  }

  const { payload, signature, algorithm } = parsed;

  // Check expiration
  if (payload.exp < now) {
    return {
      valid: false,
      error: 'Token has expired',
      expired: true,
      payload,
    };
  }

  // Check not-before
  if (payload.nbf && payload.nbf > now) {
    return {
      valid: false,
      error: 'Token is not yet valid',
      payload,
    };
  }

  // Check audience if specified
  if (audience && payload.aud !== audience) {
    return {
      valid: false,
      error: `Audience mismatch: expected ${audience}, got ${payload.aud}`,
      payload,
    };
  }

  // Verify signature
  const parts = token.split('.');
  const signingInput = `${parts[0]}.${parts[1]}`;
  const signingInputBytes = new TextEncoder().encode(signingInput);

  const sigAlgorithm = REVERSE_ALG_MAP[algorithm];
  if (!sigAlgorithm) {
    return {
      valid: false,
      error: `Unsupported algorithm: ${algorithm}`,
      payload,
    };
  }

  const signatureValid = await verify(
    issuerPublicKey,
    signature,
    signingInputBytes,
    sigAlgorithm
  );

  if (!signatureValid) {
    return {
      valid: false,
      error: 'Invalid signature',
      payload,
    };
  }

  // Check required capabilities
  if (requiredCapabilities && requiredCapabilities.length > 0) {
    for (const required of requiredCapabilities) {
      const hasCapability = checkCapability(payload.att, required);
      if (!hasCapability) {
        return {
          valid: false,
          error: `Missing required capability: ${required.can} on ${required.with}`,
          payload,
        };
      }
    }
  }

  // Calculate expiration info
  const expiresIn = payload.exp - now;
  const shouldRotate = expiresIn < 3 * 24 * 60 * 60; // Less than 3 days

  return {
    valid: true,
    payload,
    expiresIn,
    shouldRotate,
  };
}

/**
 * Check if a capability satisfies a requirement
 *
 * @param granted - Array of granted capabilities
 * @param required - Required capability
 * @returns True if requirement is satisfied
 */
export function checkCapability(
  granted: Capability[],
  required: Capability
): boolean {
  for (const cap of granted) {
    if (capabilityMatches(cap, required)) {
      return true;
    }
  }
  return false;
}

/**
 * Check if a capability matches a requirement
 * Supports wildcards in both 'can' and 'with' fields
 */
function capabilityMatches(granted: Capability, required: Capability): boolean {
  // Check 'can' field
  if (!actionMatches(granted.can, required.can)) {
    return false;
  }

  // Check 'with' field
  if (!resourceMatches(granted.with, required.with)) {
    return false;
  }

  return true;
}

/**
 * Check if a granted action matches a required action
 * Supports wildcards: 'file/*' matches 'file/read', '*' matches anything
 */
function actionMatches(granted: string, required: string): boolean {
  if (granted === '*' || granted === required) {
    return true;
  }

  // Check wildcard suffix
  if (granted.endsWith('/*')) {
    const prefix = granted.slice(0, -1); // Remove '*' but keep '/'
    return required.startsWith(prefix);
  }

  return false;
}

/**
 * Check if a granted resource matches a required resource
 * Supports wildcards: 'storage://bucket/*' matches 'storage://bucket/file.txt'
 */
function resourceMatches(granted: string, required: string): boolean {
  if (granted === '*' || granted === required) {
    return true;
  }

  // Check wildcard suffix
  if (granted.endsWith('*')) {
    const prefix = granted.slice(0, -1);
    return required.startsWith(prefix);
  }

  return false;
}

/**
 * Extract capabilities from a UCAN token
 *
 * @param token - Encoded UCAN token
 * @returns Array of capabilities
 */
export function getCapabilities(token: string): Capability[] {
  const parsed = parseUCAN(token);
  return parsed.payload.att;
}

/**
 * Get the issuer DID from a UCAN token
 *
 * @param token - Encoded UCAN token
 * @returns Issuer DID
 */
export function getIssuer(token: string): DID {
  const parsed = parseUCAN(token);
  return parsed.payload.iss;
}

/**
 * Get the audience DID from a UCAN token
 *
 * @param token - Encoded UCAN token
 * @returns Audience DID
 */
export function getAudience(token: string): DID {
  const parsed = parseUCAN(token);
  return parsed.payload.aud;
}

/**
 * Check if a UCAN token is expired
 *
 * @param token - Encoded UCAN token
 * @param now - Current time (defaults to now)
 * @returns True if expired
 */
export function isExpired(token: string, now?: number): boolean {
  const currentTime = now ?? Math.floor(Date.now() / 1000);
  const parsed = parseUCAN(token);
  return parsed.payload.exp < currentTime;
}

/**
 * Get time until expiration in seconds
 *
 * @param token - Encoded UCAN token
 * @param now - Current time (defaults to now)
 * @returns Seconds until expiration (negative if expired)
 */
export function getExpirationTime(token: string, now?: number): number {
  const currentTime = now ?? Math.floor(Date.now() / 1000);
  const parsed = parseUCAN(token);
  return parsed.payload.exp - currentTime;
}
