function applyRange(
  source: string,
  startLine?: number,
  endLine?: number
): string {
  if (startLine === undefined || endLine === undefined) {
    return source;
  }
  const lines = source.split(/\r?\n/);
  const safeStart = Math.max(1, startLine);
  const safeEnd = Math.max(safeStart, endLine);
  return lines.slice(safeStart - 1, safeEnd).join('\n');
}

function normalizeMode(mode: EvalMode | undefined): EvalMode {
  return mode === 'live' ? 'live' : 'dry';
}

function normalizeSafetyMode(mode: SafetyMode | undefined): SafetyMode {
  return mode === 'off' ? 'off' : 'on';
}

function normalizeDeployEnvironment(
  environment: DeployEnvironment | string | undefined
): DeployEnvironment {
  if (
    typeof environment === 'string' &&
    (DEPLOY_ENVIRONMENTS as readonly string[]).includes(environment)
  ) {
    return environment as DeployEnvironment;
  }
  return 'development';
}

function normalizeSelectorPath(value: string): string {
  return value.replace(/^\.?\//, '').replace(/\/+$/, '');
}

function projectMatchesSelector(
  project: AeonDeployProject,
  selector: string
): boolean {
  const normalizedSelector = normalizeSelectorPath(selector);
  if (!normalizedSelector) {
    return false;
  }

  const normalizedProjectDir = normalizeSelectorPath(project.dir);
  return (
    project.name === selector ||
    normalizedProjectDir === normalizedSelector ||
    normalizedProjectDir.endsWith(`/${normalizedSelector}`) ||
    normalizedSelector.endsWith(normalizedProjectDir)
  );
}

function planSummary(plan: AeonRemotePublishPlan): DeployPlanSummary {
  const appContract = normalizeAppDeployContract(plan.appContract);
  const stackContract = normalizeStackContract(plan.stackContract ?? null);
  return {
    substrate: plan.substrate ?? DEFAULT_SUBSTRATE,
    source: plan.source,
    target: plan.target,
    argv: [...plan.argv],
    smokeTarget: plan.smokeTarget,
    smokeGateRequired: plan.smokeGateRequired,
    appContract,
    stackContract,
  };
}

function normalizeStringList(values: unknown): string[] {
  if (!Array.isArray(values)) {
    return [];
  }
  const seen = new Set<string>();
  const out: string[] = [];
  for (const value of values) {
    if (typeof value !== 'string') {
      continue;
    }
    const trimmed = value.trim();
    if (trimmed.length === 0 || seen.has(trimmed)) {
      continue;
    }
    seen.add(trimmed);
    out.push(trimmed);
  }
  return out;
}

function normalizeDeployEnvSchema(input: unknown): DeployEnvSchema {
  const base =
    typeof input === 'object' && input !== null
      ? (input as Partial<DeployEnvSchema>)
      : {};
  return {
    required: normalizeStringList(base.required),
    optional: normalizeStringList(base.optional),
  };
}

function normalizeDeployHealthChecks(input: unknown): DeployHealthChecks {
  const base =
    typeof input === 'object' && input !== null
      ? (input as Partial<DeployHealthChecks>)
      : {};
  return {
    smokeTarget:
      typeof base.smokeTarget === 'string' && base.smokeTarget.trim().length > 0
        ? base.smokeTarget.trim()
        : null,
  };
}

function normalizeAppDeployContract(
  input?: Partial<AppDeployContract>
): AppDeployContract {
  const app =
    typeof input?.app === 'string' && input.app.trim().length > 0
      ? input.app.trim()
      : DEFAULT_DEPLOY_CONTRACT.app;
  const runtime =
    typeof input?.runtime === 'string' && input.runtime.trim().length > 0
      ? input.runtime.trim()
      : DEFAULT_DEPLOY_CONTRACT.runtime;
  const routes = normalizeStringList(
    input?.routes ?? DEFAULT_DEPLOY_CONTRACT.routes
  );
  const jobs = normalizeStringList(input?.jobs ?? DEFAULT_DEPLOY_CONTRACT.jobs);
  const dataBindings = normalizeStringList(
    input?.dataBindings ?? DEFAULT_DEPLOY_CONTRACT.dataBindings
  );
  const capabilities = normalizeStringList(
    input?.capabilities ?? DEFAULT_DEPLOY_CONTRACT.capabilities
  );
  return {
    app,
    runtime,
    routes,
    jobs,
    dataBindings,
    envSchema: normalizeDeployEnvSchema(input?.envSchema),
    healthChecks: normalizeDeployHealthChecks(input?.healthChecks),
    capabilities:
      capabilities.length > 0
        ? capabilities
        : [...DEFAULT_DEPLOY_CONTRACT.capabilities],
  };
}

function normalizeStackDependencyContract(
  input: unknown
): StackDependencyContract[] {
  if (!Array.isArray(input)) {
    return [];
  }
  const dependencies: StackDependencyContract[] = [];
  for (const entry of input) {
    if (!entry || typeof entry !== 'object') {
      continue;
    }
    const app =
      typeof (entry as { app?: unknown }).app === 'string'
        ? (entry as { app: string }).app.trim()
        : '';
    if (app.length === 0) {
      continue;
    }
    dependencies.push({
      app,
      dependsOn: normalizeStringList(
        (entry as { dependsOn?: unknown }).dependsOn ?? []
      ),
    });
  }
  return dependencies;
}

function normalizeStackContract(
  input: Partial<StackContract> | null | undefined
): StackContract | null {
  if (!input || typeof input !== 'object') {
    return null;
  }
  const name =
    typeof input.name === 'string' && input.name.trim().length > 0
      ? input.name.trim()
      : '';
  const apps = normalizeStringList(input.apps ?? []);
  if (name.length === 0 || apps.length === 0) {
    return null;
  }
  const dependencies = normalizeStackDependencyContract(input.dependencies);
  const appSet = new Set(apps);
  const filteredDependencies = dependencies
    .filter((dependency) => appSet.has(dependency.app))
    .map((dependency) => ({
      app: dependency.app,
      dependsOn: dependency.dependsOn.filter((target) => appSet.has(target)),
    }));
  const promotionOrder = normalizeStringList(input.promotionOrder ?? apps);
  const normalizedPromotion =
    promotionOrder.length === apps.length &&
    promotionOrder.every((app) => appSet.has(app))
      ? promotionOrder
      : apps;
  return {
    name,
    apps,
    dependencies: filteredDependencies,
    promotionOrder: normalizedPromotion,
    healthGates: normalizeStringList(input.healthGates ?? []),
  };
}

function inferContractFromPlan(plan: AeonRemotePublishPlan): AppDeployContract {
  const runtime =
    plan.project.config.kind === 'worker'
      ? 'edge'
      : plan.project.config.kind === 'app'
      ? 'app'
      : DEFAULT_DEPLOY_CONTRACT.runtime;
  return normalizeAppDeployContract({
    app: DEFAULT_DEPLOY_CONTRACT.app,
    runtime,
    healthChecks: {
      smokeTarget: plan.smokeTarget,
    },
  });
}

function resolveAppDeployContract(
  plan: AeonRemotePublishPlan
): AppDeployContract {
  return normalizeAppDeployContract({
    ...inferContractFromPlan(plan),
    ...(plan.appContract ?? {}),
  });
}

function resolveSmokeTarget(
  plan: AeonRemotePublishPlan,
  appContract: AppDeployContract
): string | null {
  if (plan.smokeTarget && plan.smokeTarget.trim().length > 0) {
    return plan.smokeTarget.trim();
  }
  if (
    typeof appContract.healthChecks.smokeTarget === 'string' &&
    appContract.healthChecks.smokeTarget.trim().length > 0
  ) {
    return appContract.healthChecks.smokeTarget.trim();
  }
  return null;
}

