function collectCandidateGnotFiles(projectRoot: string): string[] {
  const queue: Array<{ path: string; depth: number }> = [
    { path: projectRoot, depth: 0 },
  ];
  const candidates: string[] = [];
  while (queue.length > 0 && candidates.length < 64) {
    const current = queue.shift();
    if (!current) {
      break;
    }
    if (current.depth > 3) {
      continue;
    }
    let entries: string[];
    try {
      entries = readdirSync(current.path);
    } catch {
      continue;
    }
    for (const entry of entries) {
      const fullPath = join(current.path, entry);
      let stats: ReturnType<typeof statSync>;
      try {
        stats = statSync(fullPath);
      } catch {
        continue;
      }
      if (stats.isDirectory()) {
        if (
          entry === 'node_modules' ||
          entry === '.git' ||
          entry.startsWith('.a0')
        ) {
          continue;
        }
        queue.push({ path: fullPath, depth: current.depth + 1 });
        continue;
      }
      if (stats.isFile() && entry.endsWith('.gnot')) {
        candidates.push(fullPath);
      }
    }
  }

  return candidates.sort((left, right) => {
    const leftBase = left.split('/').pop() ?? left;
    const rightBase = right.split('/').pop() ?? right;
    const leftScore =
      leftBase === 'main.gnot' ? 0 : leftBase === 'app.gnot' ? 1 : 2;
    const rightScore =
      rightBase === 'main.gnot' ? 0 : rightBase === 'app.gnot' ? 1 : 2;
    if (leftScore !== rightScore) {
      return leftScore - rightScore;
    }
    return left.localeCompare(right);
  });
}

function stackContractFromManifestJson(raw: unknown): StackContract | null {
  if (!raw || typeof raw !== 'object') {
    return null;
  }
  const stack = (raw as { stack?: unknown }).stack;
  if (!stack || typeof stack !== 'object') {
    return null;
  }
  return normalizeStackContract({
    name: (stack as { name?: unknown }).name as string | undefined,
    apps: (stack as { apps?: unknown }).apps as string[] | undefined,
    dependencies: (stack as { dependencies?: unknown }).dependencies as
      | Array<{ app: string; dependsOn: string[] }>
      | undefined,
    promotionOrder: (stack as { promotionOrder?: unknown }).promotionOrder as
      | string[]
      | undefined,
    healthGates: (stack as { healthGates?: unknown }).healthGates as
      | string[]
      | undefined,
  });
}

