function normalizeEnvInputs(
  input: Record<string, string> | undefined
): Record<string, string> {
  if (!input) {
    return {};
  }
  const entries = Object.entries(input)
    .filter(
      ([key, value]) => key.trim().length > 0 && typeof value === 'string'
    )
    .map(([key, value]) => [key.trim(), value] as const)
    .sort(([left], [right]) => left.localeCompare(right));
  return Object.fromEntries(entries);
}

function appToHostSlug(value: string): string {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

function resolveReleaseUrls(
  app: string,
  environment: DeployEnvironment
): { url: string; previewUrl: string | null } {
  const slug = appToHostSlug(app) || 'app';
  if (environment === 'production') {
    return {
      url: `https://${slug}.gnot.app`,
      previewUrl: null,
    };
  }
  return {
    url: `https://${slug}--${environment}.preview.gnot.app`,
    previewUrl: `https://${slug}--${environment}.preview.gnot.app`,
  };
}

function stableStringify(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableStringify(item)).join(',')}]`;
  }
  if (value && typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>).sort(
      ([left], [right]) => left.localeCompare(right)
    );
    return `{${entries
      .map(
        ([key, entryValue]) =>
          `${JSON.stringify(key)}:${stableStringify(entryValue)}`
      )
      .join(',')}}`;
  }
  return JSON.stringify(value);
}

function computeShipFingerprint(input: {
  app: string;
  environment: DeployEnvironment;
  plan: DeployPlanSummary;
  env: Record<string, string>;
}): string {
  return stableStringify(input);
}

function currentHealthFromRelease(
  release: ReleaseRecord | undefined
): ReleaseHealthSnapshot['status'] | 'unknown' {
  if (!release || release.health.length === 0) {
    return 'unknown';
  }
  return release.health[release.health.length - 1]?.status ?? 'unknown';
}

function parseDelimitedValues(raw: string | undefined): string[] {
  if (!raw) {
    return [];
  }
  return raw
    .split(/[,\s]+/)
    .map((value) => value.trim())
    .filter((value) => value.length > 0);
}

function decodeBase64UrlString(input: string): string | null {
  try {
    const normalized = input.replace(/-/g, '+').replace(/_/g, '/');
    const padded = normalized.padEnd(
      normalized.length + ((4 - (normalized.length % 4)) % 4),
      '='
    );
    return Buffer.from(padded, 'base64').toString('utf8');
  } catch {
    return null;
  }
}

function parseUcanPayloadFromToken(token: string): {
  att: Array<{ can: string; with: string }>;
  prf: string[];
  iss?: string;
  aud?: string;
} | null {
  const parts = token.split('.');
  if (parts.length !== 3) {
    return null;
  }
  const payloadRaw = decodeBase64UrlString(parts[1] ?? '');
  if (!payloadRaw) {
    return null;
  }
  let payload: unknown;
  try {
    payload = JSON.parse(payloadRaw);
  } catch {
    return null;
  }
  if (!payload || typeof payload !== 'object') {
    return null;
  }
  const attInput = (payload as { att?: unknown }).att;
  const prfInput = (payload as { prf?: unknown }).prf;
  const att = Array.isArray(attInput)
    ? attInput
        .map((entry) => {
          if (!entry || typeof entry !== 'object') {
            return null;
          }
          const can =
            typeof (entry as { can?: unknown }).can === 'string'
              ? (entry as { can: string }).can
              : null;
          const withValue =
            typeof (entry as { with?: unknown }).with === 'string'
              ? (entry as { with: string }).with
              : null;
          if (!can || !withValue) {
            return null;
          }
          return { can, with: withValue };
        })
        .filter((entry): entry is { can: string; with: string } =>
          Boolean(entry)
        )
    : [];
  const prf = Array.isArray(prfInput)
    ? prfInput.filter((entry): entry is string => typeof entry === 'string')
    : [];
  const iss =
    typeof (payload as { iss?: unknown }).iss === 'string'
      ? (payload as { iss: string }).iss
      : undefined;
  const aud =
    typeof (payload as { aud?: unknown }).aud === 'string'
      ? (payload as { aud: string }).aud
      : undefined;
  return { att, prf, iss, aud };
}

type DelegationVerifier = (
  token: string,
  resolvePublicKey: (did: string) => Promise<JsonWebKey | null>
) => Promise<{
  valid: boolean;
  chain: Array<{
    payload: {
      iss?: string;
      aud?: string;
      att?: Array<{ can?: string; with?: string }>;
    };
  }>;
}>;

let delegationVerifierPromise: Promise<DelegationVerifier | null> | null = null;

async function loadDelegationVerifier(
  repoRoot: string
): Promise<DelegationVerifier | null> {
  if (delegationVerifierPromise) {
    return await delegationVerifierPromise;
  }
  delegationVerifierPromise = (async () => {
    try {
      const module = (await import(
        pathToFileURL(join(repoRoot, 'open-source/auth/src/delegation.js')).href
      )) as unknown as { verifyDelegationChain?: DelegationVerifier };
      if (typeof module.verifyDelegationChain !== 'function') {
        return null;
      }
      return module.verifyDelegationChain;
    } catch {
      return null;
    }
  })();
  return await delegationVerifierPromise;
}

function parseUcanTokensFromClaims(claims: Record<string, string>): string[] {
  const tokens = new Set<string>();
  const directToken = claims['ucan.token']?.trim();
  if (directToken) {
    tokens.add(directToken);
  }

  const authHeader =
    claims.authorization?.trim() ?? claims.Authorization?.trim();
  if (authHeader?.toLowerCase().startsWith('bearer ')) {
    const token = authHeader.slice('bearer '.length).trim();
    if (token.length > 0) {
      tokens.add(token);
    }
  }

  const serializedTokens = claims['ucan.tokens']?.trim();
  if (serializedTokens) {
    if (serializedTokens.startsWith('[')) {
      try {
        const parsed = JSON.parse(serializedTokens) as unknown;
        if (Array.isArray(parsed)) {
          for (const item of parsed) {
            if (typeof item === 'string' && item.trim().length > 0) {
              tokens.add(item.trim());
            }
          }
        }
      } catch {
        for (const token of parseDelimitedValues(serializedTokens)) {
          tokens.add(token);
        }
      }
    } else {
      for (const token of parseDelimitedValues(serializedTokens)) {
        tokens.add(token);
      }
    }
  }

  return Array.from(tokens.values());
}

function dedupeCapabilities(
  values: Array<{ can: string; with: string }>
): Array<{ can: string; with: string }> {
  const seen = new Set<string>();
  const out: Array<{ can: string; with: string }> = [];
  for (const value of values) {
    const can = value.can.trim();
    const withValue = value.with.trim();
    if (can.length === 0 || withValue.length === 0) {
      continue;
    }
    const key = `${can}@@${withValue}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    out.push({ can, with: withValue });
  }
  return out;
}

function defaultAuthorityFromClaims(
  claims: Record<string, string>
): SessionAuthority {
  const direct = parseDelimitedValues(claims['ucan.capabilities']);
  const fallback = parseDelimitedValues(claims.capabilities);
  const parsed = direct.length > 0 ? direct : fallback;
  const normalized = Array.from(new Set(parsed));
  const ucanTokens = parseUcanTokensFromClaims(claims);
  const parsedUcanCapabilities: Array<{ can: string; with: string }> = [];
  const parsedDelegationChain = new Set<string>(
    parseDelimitedValues(claims['ucan.delegation_chain'])
  );

  for (const token of ucanTokens) {
    const parsedToken = parseUcanPayloadFromToken(token);
    if (!parsedToken) {
      continue;
    }
    for (const capability of parsedToken.att) {
      parsedUcanCapabilities.push({
        can: capability.can,
        with: capability.with,
      });
    }
    for (const proof of parsedToken.prf) {
      if (proof.trim().length > 0) {
        parsedDelegationChain.add(proof.trim());
      }
    }
    if (parsedToken.iss) {
      parsedDelegationChain.add(`iss:${parsedToken.iss}`);
    }
    if (parsedToken.aud) {
      parsedDelegationChain.add(`aud:${parsedToken.aud}`);
    }
  }

  return {
    authMaterialPresent:
      normalized.length > 0 ||
      ucanTokens.length > 0 ||
      parsedDelegationChain.size > 0,
    capabilities: normalized,
    ucanCapabilities: dedupeCapabilities(parsedUcanCapabilities),
    delegationChain: Array.from(parsedDelegationChain.values()),
  };
}

async function resolveAuthorityFromClaims(
  claims: Record<string, string>,
  authHooks: AuthHooks | undefined,
  repoRoot: string
): Promise<SessionAuthority> {
  const fallback = defaultAuthorityFromClaims(claims);
  const ucanTokens = parseUcanTokensFromClaims(claims);
  if (ucanTokens.length === 0 || !authHooks?.resolveUcanIssuerPublicKey) {
    return fallback;
  }
  const verifier = await loadDelegationVerifier(repoRoot);
  if (!verifier) {
    return fallback;
  }

  const verifiedCapabilities: Array<{ can: string; with: string }> = [];
  const delegationChain = new Set<string>(fallback.delegationChain);
  let sawVerifiedToken = false;
  for (const token of ucanTokens) {
    try {
      const verified = await verifier(
        token,
        authHooks.resolveUcanIssuerPublicKey
      );
      if (!verified.valid) {
        continue;
      }
      sawVerifiedToken = true;
      for (const node of verified.chain) {
        for (const capability of node.payload.att ?? []) {
          if (
            typeof capability.can !== 'string' ||
            typeof capability.with !== 'string'
          ) {
            continue;
          }
          verifiedCapabilities.push({
            can: capability.can,
            with: capability.with,
          });
        }
        if (typeof node.payload.iss === 'string') {
          delegationChain.add(`iss:${node.payload.iss}`);
        }
        if (typeof node.payload.aud === 'string') {
          delegationChain.add(`aud:${node.payload.aud}`);
        }
      }
    } catch {
      // Ignore verification errors and continue with other tokens.
    }
  }

  if (!sawVerifiedToken) {
    return {
      ...fallback,
      authMaterialPresent: true,
      capabilities: fallback.capabilities,
      ucanCapabilities: [],
      delegationChain: Array.from(delegationChain.values()),
    };
  }

  return {
    authMaterialPresent: true,
    capabilities: fallback.capabilities,
    ucanCapabilities: dedupeCapabilities(verifiedCapabilities),
    delegationChain: Array.from(delegationChain.values()),
  };
}

function capabilityTokenMatches(granted: string, required: string): boolean {
  if (granted === '*' || granted === required) {
    return true;
  }
  const separator = required.includes(':')
    ? ':'
    : required.includes('/')
    ? '/'
    : '.';
  const requiredPrefix = required.split(separator)[0];
  if (granted === `${requiredPrefix}${separator}*`) {
    return true;
  }
  return false;
}

function capabilityResourceMatches(granted: string, required: string): boolean {
  if (granted === '*' || granted === required) {
    return true;
  }
  if (granted.endsWith('/*')) {
    const prefix = granted.slice(0, -1);
    return required.startsWith(prefix);
  }
  return false;
}

function capabilityAllows(
  authority: SessionAuthority,
  requiredLegacy: string,
  requiredUcan: { can: string; with: string }
): boolean {
  if (
    authority.capabilities.length === 0 &&
    authority.ucanCapabilities.length === 0 &&
    !authority.authMaterialPresent
  ) {
    // local/unauthenticated mode remains permissive for solo workflows.
    return true;
  }
  for (const token of authority.capabilities) {
    if (capabilityTokenMatches(token, requiredLegacy)) {
      return true;
    }
  }
  for (const capability of authority.ucanCapabilities) {
    if (!capabilityTokenMatches(capability.can, requiredUcan.can)) {
      continue;
    }
    if (capabilityResourceMatches(capability.with, requiredUcan.with)) {
      return true;
    }
  }
  return false;
}

function parseDelegationChain(
  requestChain: string[] | undefined,
  authority: SessionAuthority
): string[] {
  if (requestChain && requestChain.length > 0) {
    return requestChain.map((entry) => entry.trim()).filter(Boolean);
  }
  return [...authority.delegationChain];
}

function toReleaseGraphSnapshot(
  graph: ReleaseGraphState
): ReleaseGraphSnapshot {
  return {
    app: graph.app,
    environment: graph.environment,
    currentReleaseId: graph.currentReleaseId,
    releases: graph.releases,
    logs: Object.fromEntries(graph.logs.entries()),
    events: graph.events,
  };
}

function fromReleaseGraphSnapshot(
  snapshot: ReleaseGraphSnapshot
): ReleaseGraphState {
  return {
    app: snapshot.app,
    environment: snapshot.environment,
    currentReleaseId: snapshot.currentReleaseId,
    releases: snapshot.releases,
    logs: new Map(Object.entries(snapshot.logs)),
    events: snapshot.events ?? [],
  };
}

function mergeReleaseGraphs(
  local: ReleaseGraphState,
  incoming: ReleaseGraphState
): ReleaseGraphState {
  const releaseMap = new Map<string, ReleaseRecord>();
  for (const release of local.releases) {
    releaseMap.set(release.releaseId, release);
  }
  for (const release of incoming.releases) {
    if (!releaseMap.has(release.releaseId)) {
      releaseMap.set(release.releaseId, release);
    }
  }
  const releases = Array.from(releaseMap.values()).sort(
    (left, right) => left.createdAt - right.createdAt
  );

  const logs = new Map<string, string[]>();
  const releaseIds = new Set<string>([
    ...Array.from(local.logs.keys()),
    ...Array.from(incoming.logs.keys()),
  ]);
  for (const releaseId of releaseIds) {
    const merged = new Set<string>([
      ...(local.logs.get(releaseId) ?? []),
      ...(incoming.logs.get(releaseId) ?? []),
    ]);
    logs.set(releaseId, Array.from(merged));
  }

  const eventMap = new Map<string, ReleaseEvent>();
  for (const event of local.events) {
    eventMap.set(event.eventId, event);
  }
  for (const event of incoming.events) {
    if (!eventMap.has(event.eventId)) {
      eventMap.set(event.eventId, event);
    }
  }
  const events = Array.from(eventMap.values()).sort(
    (left, right) => left.at - right.at
  );

  // Pointer conflicts are resolved by explicit local actions; keep local pointer.
  return {
    app: local.app,
    environment: local.environment,
    currentReleaseId: local.currentReleaseId ?? incoming.currentReleaseId,
    releases,
    logs,
    events,
  };
}

function normalizeDependencies(
  apps: string[],
  dependencies: Record<string, string[]> | undefined
): Record<string, string[]> {
  const appSet = new Set(apps);
  const normalized: Record<string, string[]> = {};
  for (const app of apps) {
    const deps = dependencies?.[app] ?? [];
    normalized[app] = deps.filter((dep) => appSet.has(dep) && dep !== app);
  }
  return normalized;
}

function topoOrder(
  apps: string[],
  dependencies: Record<string, string[]>
): string[] | null {
  const indegree = new Map<string, number>();
  const adjacency = new Map<string, string[]>();
  for (const app of apps) {
    indegree.set(app, 0);
    adjacency.set(app, []);
  }
  for (const app of apps) {
    for (const dep of dependencies[app] ?? []) {
      adjacency.get(dep)?.push(app);
      indegree.set(app, (indegree.get(app) ?? 0) + 1);
    }
  }
  const queue = apps.filter((app) => (indegree.get(app) ?? 0) === 0);
  const order: string[] = [];
  while (queue.length > 0) {
    const current = queue.shift();
    if (!current) {
      break;
    }
    order.push(current);
    for (const next of adjacency.get(current) ?? []) {
      const nextDegree = (indegree.get(next) ?? 0) - 1;
      indegree.set(next, nextDegree);
      if (nextDegree === 0) {
        queue.push(next);
      }
    }
  }
  return order.length === apps.length ? order : null;
}

function formatCommandFailure(stdout: string, stderr: string): string {
  const raw = [stdout.trim(), stderr.trim()].filter(Boolean).join('\n');
  return raw.length > 0 ? raw : 'unknown command failure';
}

function parseLintIssues(raw: string): LintIssue[] {
  const issues: LintIssue[] = [];
  const lines = raw.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed.includes(':')) {
      continue;
    }
    const match = /^(\d+):(\d+):\s+(.+)$/.exec(trimmed);
    if (!match) {
      continue;
    }
    issues.push({
      line: Number(match[1]),
      column: Number(match[2]),
      message: match[3],
    });
  }
  return issues;
}

function findTokenAt(source: string, line: number, column: number): string {
  const lines = source.split(/\r?\n/);
  const row = lines[line - 1] ?? '';
  if (row.length === 0) {
    return '';
  }
  const cursor = Math.max(0, Math.min(row.length - 1, column - 1));
  const isWord = (char: string): boolean => /[a-zA-Z0-9_~.]/.test(char);
  let start = cursor;
  let end = cursor;
  while (start > 0 && isWord(row[start - 1])) {
    start -= 1;
  }
  while (end < row.length - 1 && isWord(row[end + 1])) {
    end += 1;
  }
  const token = row.slice(start, end + 1).trim();
  return token;
}

function completionPrefix(
  source: string,
  line: number,
  column: number
): string {
  const lines = source.split(/\r?\n/);
  const row = lines[line - 1] ?? '';
  const cursor = Math.max(0, Math.min(row.length, column - 1));
  const left = row.slice(0, cursor);
  const match = /([a-zA-Z0-9_~.]*)$/.exec(left);
  return match?.[1] ?? '';
}

function fuzzyMatch(candidate: string, query: string): boolean {
  if (query.length === 0) {
    return true;
  }
  const lowerCandidate = candidate.toLowerCase();
  const lowerQuery = query.toLowerCase();
  if (lowerCandidate.includes(lowerQuery)) {
    return true;
  }
  let index = 0;
  for (const char of lowerCandidate) {
    if (char === lowerQuery[index]) {
      index += 1;
      if (index === lowerQuery.length) {
        return true;
      }
    }
  }
  return false;
}

function parseAst(source: string): AstResult {
  const lines = source.split(/\r?\n/);
  const ast = lines
    .map((line, index) => ({ lineNumber: index + 1, line }))
    .filter(({ line }) => {
      const trimmed = line.trim();
      return trimmed.length > 0 && !trimmed.startsWith('#');
    })
    .map(({ lineNumber, line }) => {
      const raw = line.trim();
      const assignMatch =
        /^([^<=>]+)\s*(<-|=)\s*([^,]+),\s*([a-zA-Z_][a-zA-Z0-9_]*)/.exec(raw);
      const qualifiers = QUALIFIERS.filter((qualifier) =>
        new RegExp(`\\b${qualifier}\\b`).test(raw)
      );
      return {
        line: lineNumber,
        raw,
        target: assignMatch ? assignMatch[1].trim() : undefined,
        subject: assignMatch ? assignMatch[3].trim() : undefined,
        verb: assignMatch ? assignMatch[4].trim() : undefined,
        qualifiers: [...qualifiers],
      };
    });
  return { ast };
}

function inferRepoRoot(start: string): string {
  let cursor = resolve(start);
  const root = resolve('/');
  while (true) {
    const probe = join(cursor, 'open-source/gnot/Cargo.toml');
    if (existsSync(probe)) {
      return cursor;
    }
    if (cursor === root) {
      return resolve(start);
    }
    cursor = dirname(cursor);
  }
}

function previewSource(source: string): string {
  return source
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .slice(0, 2)
    .join(' ');
}

async function createAeonForgeDeployAdapter(
  repoRoot: string
): Promise<DeployAdapter> {
  type AeonDiscoveryModule = {
    discoverProjects: (
      workspaceRoot: string,
      opts?: { filter?: string[] }
    ) => Promise<AeonDeployProject[]>;
  };

  type AeonRemotePublishModule = {
    resolveRemotePublishPlan: (
      workspaceRoot: string,
      project: AeonDeployProject,
      environment: DeployEnvironment
    ) => AeonRemotePublishPlan | null;
    publishProjectRemotely: (
      plan: AeonRemotePublishPlan
    ) => Promise<AeonRemotePublishResult>;
  };

  const discoveryModule = (await import(
    pathToFileURL(
      join(repoRoot, 'open-source/aeon-forge/src/deploy/discovery.js')
    ).href
  )) as unknown as AeonDiscoveryModule;
  const remotePublishModule = (await import(
    pathToFileURL(
      join(repoRoot, 'open-source/aeon-forge/src/deploy/remote-publish.js')
    ).href
  )) as unknown as AeonRemotePublishModule;

  if (
    typeof discoveryModule.discoverProjects !== 'function' ||
    typeof remotePublishModule.resolveRemotePublishPlan !== 'function' ||
    typeof remotePublishModule.publishProjectRemotely !== 'function'
  ) {
    throw new Error('aeon-forge deploy adapter is unavailable');
  }

  return {
    discover: async (workspaceRoot, filter) =>
      await discoveryModule.discoverProjects(workspaceRoot, {
        ...(filter && filter.length > 0 ? { filter } : {}),
      }),
    resolvePlan: async (workspaceRoot, project, environment) =>
      remotePublishModule.resolveRemotePublishPlan(
        workspaceRoot,
        project,
        environment
      ),
    publish: async (plan) =>
      await remotePublishModule.publishProjectRemotely(plan),
  };
}

function encodeJobResult(
  summary: string,
  artifacts: JobArtifact[],
  warnings: string[] = []
): JobResult {
  return { summary, artifacts, warnings };
}

export class GnotReplCore {
  private readonly repoRoot: string;
  private readonly commandRunner: GnotCommandRunner;
  private readonly historyStore: HistoryStore;
  private readonly releaseStore: ReleaseStore;
  private readonly now: () => number;
  private readonly idFactory: () => string;
  private readonly eventEmitter = new EventEmitter();
  private readonly sessions = new Map<string, SessionState>();
  private readonly plugins: ReplPlugin[] = [];
  private readonly authHooks?: AuthHooks;
  private readonly defaultTimeoutMs: number;
  private readonly defaultEvalMode: EvalMode;
  private readonly defaultSafetyMode: SafetyMode;
  private readonly liveExecutor: GnotReplCoreOptions['liveExecutor'];
  private readonly deployWorkspaceRoot: string;
  private readonly injectedDeployAdapter?: DeployAdapter;
  private deployAdapterPromise: Promise<DeployAdapter> | null = null;
  private readonly substrateAdapters = new Map<
    DeploySubstrate,
    DeployAdapter
  >();
  private readonly releaseGraphs = new Map<string, ReleaseGraphState>();
  private readonly activeShipLocks = new Set<string>();
  private readonly releaseSync?: GnotReplCoreOptions['releaseSync'];
  private remoteSyncBootstrapped = false;
  private remoteSyncPromise: Promise<void> | null = null;
  private releaseCounter = 0;

  constructor(
    private readonly options: GnotReplCoreOptions = {},
    dependencies: CoreDependencies = {}
  ) {
    const root = options.repoRoot ?? inferRepoRoot(process.cwd());
    this.repoRoot = root;
    this.commandRunner =
      dependencies.commandRunner ?? createCargoBackedGnotRunner();
    if (dependencies.historyStore) {
      this.historyStore = dependencies.historyStore;
    } else {
      try {
        this.historyStore = new SqliteHistoryStore(options.historyPath);
      } catch {
        // Bun and other runtimes may not expose node:sqlite yet.
        this.historyStore = new InMemoryHistoryStore();
      }
    }
    if (dependencies.releaseStore) {
      this.releaseStore = dependencies.releaseStore;
    } else {
      try {
        this.releaseStore = new SqliteReleaseStore(options.releaseStorePath);
      } catch {
        this.releaseStore = new InMemoryReleaseStore();
      }
    }
    this.now = dependencies.now ?? (() => Date.now());
    this.idFactory = dependencies.idFactory ?? (() => randomUUID());
    this.authHooks = options.authHooks;
    this.defaultTimeoutMs =
      options.defaultTimeoutMs && options.defaultTimeoutMs > 0
        ? options.defaultTimeoutMs
        : DEFAULT_TIMEOUT_MS;
    this.defaultEvalMode = normalizeMode(options.defaultEvalMode);
    this.defaultSafetyMode = normalizeSafetyMode(options.defaultSafetyMode);
    this.liveExecutor = options.liveExecutor;
    this.deployWorkspaceRoot = resolve(
      options.deployWorkspaceRoot ?? this.repoRoot
    );
    this.injectedDeployAdapter = dependencies.deployAdapter;
    this.releaseSync = options.releaseSync;
    if (this.injectedDeployAdapter) {
      this.substrateAdapters.set(DEFAULT_SUBSTRATE, this.injectedDeployAdapter);
    }
    const persisted = this.releaseStore.loadAll();
    for (const snapshot of persisted) {
      const graph = fromReleaseGraphSnapshot(snapshot);
      this.releaseGraphs.set(
        releaseGraphKey(graph.app, graph.environment),
        graph
      );
    }
  }

  registerPlugin(plugin: ReplPlugin): void {
    this.plugins.push(plugin);
  }

  registerSubstrateAdapter(
    substrate: DeploySubstrate,
    adapter: DeployAdapter
  ): void {
    this.substrateAdapters.set(substrate, adapter);
  }

  useApp(request: UseAppRequest): UseAppResult {
    const session = this.requireSession(request.sessionId);
    const app = request.app.trim();
    if (app.length === 0) {
      throw new Error('app is required');
    }
    session.activeApp = app;
    session.activeEnvironment = normalizeDeployEnvironment(request.environment);
    session.shellMode = 'deploy';
    session.updatedAt = this.now();
    return {
      app: session.activeApp,
      environment: session.activeEnvironment,
      shellMode: session.shellMode,
    };
  }

  deploymentContext(
    request: DeploymentContextRequest
  ): DeploymentContextResult {
    const session = this.requireSession(request.sessionId);
    return {
      app: session.activeApp,
      environment: session.activeEnvironment,
      shellMode: session.shellMode,
    };
  }

  setShellMode(request: ShellModeRequest): ShellModeResult {
    const session = this.requireSession(request.sessionId);
    session.shellMode = request.mode;
    session.updatedAt = this.now();
    return { mode: session.shellMode };
  }

  async createSession(config: SessionConfig = {}): Promise<string> {
    await this.bootstrapRemoteSync();
    const sessionId = this.idFactory();
    const now = this.now();
    const claims = this.authHooks?.resolveSessionClaims
      ? await this.authHooks.resolveSessionClaims(sessionId)
      : {};
    const authority = await resolveAuthorityFromClaims(
      claims,
      this.authHooks,
      this.repoRoot
    );
    const snapshot: SessionState = {
      sessionId,
      profile: config.profile ?? DEFAULT_PROFILE,
      evalMode: normalizeMode(config.evalMode ?? this.defaultEvalMode),
      safetyMode: normalizeSafetyMode(
        config.safetyMode ?? this.defaultSafetyMode
      ),
      createdAt: now,
      updatedAt: now,
      allowLive: config.allowLive ?? false,
      defaultTimeoutMs:
        config.defaultTimeoutMs && config.defaultTimeoutMs > 0
          ? config.defaultTimeoutMs
          : this.defaultTimeoutMs,
      cwd: config.cwd ?? this.repoRoot,
      jobs: new Map<string, JobState>(),
      tags: config.tags ? [...config.tags] : [],
      claims,
      authority,
      activeApp: null,
      activeEnvironment: 'development',
      shellMode: 'deploy',
    };
    this.sessions.set(sessionId, snapshot);
    for (const plugin of this.plugins) {
      await plugin.onSessionCreate?.(snapshot);
    }
    return sessionId;
  }

  getSession(sessionId: string): SessionSnapshot {
    const session = this.requireSession(sessionId);
    return {
      sessionId: session.sessionId,
      profile: session.profile,
      evalMode: session.evalMode,
      safetyMode: session.safetyMode,
      createdAt: session.createdAt,
      updatedAt: session.updatedAt,
      lastJobId: session.lastJobId,
      lastValue: session.lastValue,
    };
  }

  closeSession(sessionId: string): void {
    const session = this.sessions.get(sessionId);
    if (!session) {
      return;
    }
    for (const job of session.jobs.values()) {
      job.controller.abort();
    }
    this.sessions.delete(sessionId);
  }

  async eval(request: EvalRequest): Promise<EvalHandle> {
    const session = this.requireSession(request.sessionId);
    const jobId = this.idFactory();
    const job: JobState = {
      id: jobId,
      request,
      status: 'queued',
      controller: new AbortController(),
    };
    session.jobs.set(jobId, job);
    session.lastJobId = jobId;
    session.updatedAt = this.now();

    this.historyStore.append(
      request.sessionId,
      'input',
      request.source,
      this.now()
    );

    this.emitEvent({
      type: 'job_queued',
      eventId: this.idFactory(),
      sessionId: request.sessionId,
      jobId,
      at: this.now(),
      status: 'queued',
      sourcePreview: previewSource(request.source),
    });

    void this.runJob(session, job);
    return { jobId };
  }

  cancel(request: CancelRequest): boolean {
    const session = this.sessions.get(request.sessionId);
    if (!session) {
      return false;
    }
    const job = session.jobs.get(request.jobId);
    if (!job) {
      return false;
    }
    job.controller.abort();
    return true;
  }

  subscribe(request: SubscribeRequest): AsyncIterable<GnotReplEvent> {
    this.requireSession(request.sessionId);
    const stream = new AsyncEventStream<GnotReplEvent>();
    const listener = (event: GnotReplEvent): void => {
      if (event.sessionId !== request.sessionId) {
        return;
      }
      if (request.jobId && event.jobId !== request.jobId) {
        return;
      }
      stream.push(event);
    };
    this.eventEmitter.on('event', listener);
    stream.onClose(() => {
      this.eventEmitter.removeListener('event', listener);
    });
    return stream;
  }

  async format(request: FormatRequest): Promise<FormatResult> {
    const session = this.requireSession(request.sessionId);
    const controller = new AbortController();
    const result = await runWithAbortableCommand(this.commandRunner, {
      command: 'format',
      source: request.source,
      timeoutMs: request.timeoutMs ?? this.defaultTimeoutMs,
      repoRoot: this.repoRoot,
      signal: controller.signal,
    });
    if (result.exitCode !== 0 || result.timedOut) {
      throw new Error(formatCommandFailure(result.stdout, result.stderr));
    }
    session.updatedAt = this.now();
    return {
      formatted: result.stdout,
    };
  }

  async lint(request: LintRequest): Promise<LintResult> {
    const session = this.requireSession(request.sessionId);
    const controller = new AbortController();
    const result = await runWithAbortableCommand(this.commandRunner, {
      command: 'lint',
      source: request.source,
      timeoutMs: request.timeoutMs ?? this.defaultTimeoutMs,
      repoRoot: this.repoRoot,
      signal: controller.signal,
      args: ['--mode', session.profile],
    });
    session.updatedAt = this.now();
    const raw = [result.stdout, result.stderr].filter(Boolean).join('\n');
    const issues = parseLintIssues(raw);
    return {
      ok: result.exitCode === 0 && issues.length === 0,
      issues,
      raw,
    };
  }

  complete(request: CompleteRequest): CompleteResult {
    this.requireSession(request.sessionId);
    const prefix = completionPrefix(
      request.source,
      request.line,
      request.column
    );
    const bindings = Array.from(
      new Set(
        request.source
          .split(/\r?\n/)
          .map((line) => line.trim())
          .map((line) => /^([a-zA-Z_][a-zA-Z0-9_]*)\s*(<-|=)/.exec(line)?.[1])
          .filter((value): value is string => Boolean(value))
      )
    ).map<CompletionItem>((binding) => ({
      label: binding,
      kind: 'binding',
      detail: 'Binding in current buffer',
    }));
    const allCandidates = [...COMPLETION_SEED, ...bindings];
    const items = allCandidates.filter((candidate) =>
      fuzzyMatch(candidate.label, prefix)
    );
    return {
      prefix,
      items: items.slice(0, 20),
    };
  }

  hover(request: HoverRequest): HoverResult {
    this.requireSession(request.sessionId);
    const token = findTokenAt(request.source, request.line, request.column);
    const description =
      HOVER_DOCS[token] ?? `No hover card yet for \`${token || '(empty)'}\`.`;
    return {
      token,
      description,
    };
  }

  signature(request: SignatureRequest): SignatureResult {
    this.requireSession(request.sessionId);
    const token = findTokenAt(request.source, request.line, request.column);
    const fallback: SignatureResult = {
      signature: '(subject, verb qualifier...)',
      description: 'Canonical gnot clause shape.',
    };
    return SIGNATURE_DOCS[token] ?? fallback;
  }

  historySearch(request: HistorySearchRequest): HistorySearchResult {
    return {
      entries: this.historyStore.search(request),
    };
  }

  exportHistory(request: ExportRequest): ExportResult {
    this.requireSession(request.sessionId);
    const limit = request.limit && request.limit > 0 ? request.limit : 200;
    return {
      format: request.format,
      content: this.historyStore.export(
        request.sessionId,
        request.format,
        limit
      ),
    };
  }

  ast(request: AstRequest): AstResult {
    this.requireSession(request.sessionId);
    return parseAst(request.source);
  }

  async bytecode(request: BytecodeRequest): Promise<BytecodeResult> {
    this.requireSession(request.sessionId);
    const controller = new AbortController();
    const result = await runWithAbortableCommand(this.commandRunner, {
      command: 'emit-ir-bytes',
      source: request.source,
      timeoutMs: request.timeoutMs ?? this.defaultTimeoutMs,
      repoRoot: this.repoRoot,
      signal: controller.signal,
    });
    if (result.exitCode !== 0 || result.timedOut) {
      throw new Error(formatCommandFailure(result.stdout, result.stderr));
    }
    return {
      irHex: result.stdout.trim(),
    };
  }

  async profile(request: ProfileRequest): Promise<ProfileResult> {
    this.requireSession(request.sessionId);
    const controller = new AbortController();
    const iterations =
      request.iterations && request.iterations > 0 ? request.iterations : 1_000;
    const result = await runWithAbortableCommand(this.commandRunner, {
      command: 'bench',
      source: request.source,
      timeoutMs: request.timeoutMs ?? this.defaultTimeoutMs,
      repoRoot: this.repoRoot,
      signal: controller.signal,
      args: ['--iterations', String(iterations)],
    });
    if (result.exitCode !== 0 || result.timedOut) {
      throw new Error(formatCommandFailure(result.stdout, result.stderr));
    }
    return {
      iterations,
      raw: result.stdout.trim(),
    };
  }

  async ship(request: ShipRequest): Promise<ShipResult> {
    const session = this.requireSession(request.sessionId);
    const environment = normalizeDeployEnvironment(request.environment);
    const workspaceRoot = resolve(
      request.workspaceRoot ?? this.deployWorkspaceRoot
    );
    const selector = request.app.trim();
    if (selector.length === 0) {
      throw new Error('app selector is required');
    }
    const substrate = request.substrate ?? DEFAULT_SUBSTRATE;
    const lockKey = `${environment}:${selector}:${substrate}`;
    if (this.activeShipLocks.has(lockKey)) {
      return {
        status: 'failed',
        environment,
        workspaceRoot,
        app: selector,
        failureClass: 'policy',
        error: 'A ship operation is already running for this app/environment.',
      };
    }
    this.activeShipLocks.add(lockKey);

    try {
      const adapter = await this.getDeployAdapter(substrate);
      const projects = await adapter.discover(workspaceRoot, [selector]);
      const project =
        projects.find((candidate) =>
          projectMatchesSelector(candidate, selector)
        ) ?? projects.find((candidate) => candidate.name === selector);
      if (!project) {
        return {
          status: 'unavailable',
          environment,
          workspaceRoot,
          app: selector,
          error: `No deployable app matched '${selector}'`,
        };
      }

      if (
        !capabilityAllows(session.authority, `ship:${project.name}`, {
          can: 'gnot/ship',
          with: `app://${project.name}`,
        })
      ) {
        return {
          status: 'failed',
          environment,
          workspaceRoot,
          app: project.name,
          failureClass: 'policy',
          error: `missing delegated capability ship:${project.name}`,
        };
      }

      const plan = await this.resolvePlanWithContractEnrichment(
        adapter,
        workspaceRoot,
        project,
        environment
      );
      if (!plan) {
        return {
          status: 'unavailable',
          environment,
          workspaceRoot,
          app: project.name,
          error: `No ship plan is available for ${project.name} (${environment})`,
        };
      }

      if (!plan.appContract) {
        return {
          status: 'failed',
          environment,
          workspaceRoot,
          app: project.name,
          failureClass: 'preflight',
          error:
            'deploy contract is required for ship-capable apps (missing manifest deploy metadata)',
        };
      }

      const appContract = resolveAppDeployContract(plan);
      const smokeTarget = resolveSmokeTarget(plan, appContract);
      const normalizedPlan: AeonRemotePublishPlan = {
        ...plan,
        substrate,
        smokeTarget,
        appContract,
      };
      const planInfo = planSummary(normalizedPlan);
      const env = normalizeEnvInputs(request.env);
      const missingEnv = appContract.envSchema.required.filter(
        (name) => !(name in env) || env[name] === ''
      );
      if (missingEnv.length > 0) {
        return {
          status: 'failed',
          environment,
          workspaceRoot,
          app: project.name,
          failureClass: 'preflight',
          error: `Missing required env vars: ${missingEnv.join(', ')}`,
        };
      }

      if (
        !capabilityAllows(session.authority, `substrate:${substrate}`, {
          can: 'gnot/substrate',
          with: `substrate://${substrate}`,
        })
      ) {
        return {
          status: 'failed',
          environment,
          workspaceRoot,
          app: project.name,
          failureClass: 'policy',
          error: `missing delegated capability substrate:${substrate}`,
        };
      }
      for (const cap of appContract.capabilities) {
        if (
          !capabilityAllows(session.authority, `substrate:${cap}`, {
            can: 'gnot/substrate',
            with: `substrate://${cap}`,
          })
        ) {
          return {
            status: 'failed',
            environment,
            workspaceRoot,
            app: project.name,
            failureClass: 'policy',
            error: `missing delegated capability substrate:${cap}`,
          };
        }
      }

      if (environment === 'production' && !smokeTarget) {
        return {
          status: 'failed',
          environment,
          workspaceRoot,
          app: project.name,
          failureClass: 'preflight',
          error:
            'Production ship requires a smoke target. Set deploy.health.smoke in the app contract.',
        };
      }

      const graph = this.getOrCreateReleaseGraph(project.name, environment);
      const fingerprint = computeShipFingerprint({
        app: project.name,
        environment,
        plan: planInfo,
        env,
      });

      const current = graph.currentReleaseId
        ? graph.releases.find(
            (release) => release.releaseId === graph.currentReleaseId
          )
        : undefined;
      if (
        current &&
        current.fingerprint === fingerprint &&
        current.status === 'promoted'
      ) {
        return {
          status: 'unchanged',
          environment,
          workspaceRoot,
          app: project.name,
          release: current,
          currentReleaseId: current.releaseId,
        };
      }

      const releaseId = this.nextReleaseId();
      const createdAt = this.now();
      const urls = resolveReleaseUrls(project.name, environment);
      const release: ReleaseRecord = {
        releaseId,
        app: project.name,
        environment,
        createdAt,
        fingerprint,
        url: urls.url,
        previewUrl: urls.previewUrl,
        plan: planInfo,
        provenance: {
          trigger: request.trigger ?? 'repl',
          substrate,
          source: normalizedPlan.source,
          target: normalizedPlan.target,
          argv: [...normalizedPlan.argv],
          delegationChain: parseDelegationChain(
            request.delegationChain,
            session.authority
          ),
        },
        smokeGateStatus: 'not-required',
        status: 'failed',
        health: [],
      };
      graph.releases.push(release);
      graph.logs.set(releaseId, []);
      this.appendReleaseEvent(graph, {
        eventId: this.idFactory(),
        app: project.name,
        environment,
        releaseId,
        kind: 'ship_started',
        message: `ship started on substrate=${substrate}`,
        at: createdAt,
      });
      this.pushReleaseLog(
        graph,
        releaseId,
        `ship started app=${project.name} env=${environment}`
      );
      this.pushReleaseHealth(release, {
        stage: 'plan',
        status: 'healthy',
        message: `plan resolved (${planInfo.source} -> ${planInfo.target})`,
        at: createdAt,
      });
      this.pushReleaseHealth(release, {
        stage: 'policy',
        status: 'healthy',
        message: 'preflight and policy gates passed',
        at: this.now(),
      });
      this.appendReleaseEvent(graph, {
        eventId: this.idFactory(),
        app: project.name,
        environment,
        releaseId,
        kind: 'policy_passed',
        message: 'policy and preflight gates passed',
        at: this.now(),
      });
      this.persistReleaseGraph(graph);

      const publishResult = await adapter.publish(normalizedPlan);
      release.smokeGateStatus = publishResult.smokeGateStatus;
      if (publishResult.status !== 'published') {
        release.status = 'failed';
        release.failureClass =
          publishResult.smokeGateStatus === 'failed' ? 'smoke' : 'publish';
        release.failureCause =
          publishResult.error ?? 'publish failed with no additional details';
        this.pushReleaseLog(
          graph,
          releaseId,
          `publish failed: ${release.failureCause}`
        );
        this.pushReleaseHealth(release, {
          stage: 'publish',
          status: 'failed',
          message: release.failureCause,
          at: this.now(),
        });
        this.appendReleaseEvent(graph, {
          eventId: this.idFactory(),
          app: project.name,
          environment,
          releaseId,
          kind: 'publish_failed',
          message: release.failureCause,
          at: this.now(),
        });
        const rollbackTo = this.autoRollbackOnSmokeFailure(graph, release);
        this.persistReleaseGraph(graph);
        void this.pushRemoteSync();
        return {
          status: 'failed',
          environment,
          workspaceRoot,
          app: project.name,
          release,
          currentReleaseId: graph.currentReleaseId ?? undefined,
          ...(rollbackTo ? { rollbackToReleaseId: rollbackTo } : {}),
          failureClass: release.failureClass,
          error: release.failureCause,
        };
      }

      this.pushReleaseLog(graph, releaseId, 'publish completed');
      this.pushReleaseHealth(release, {
        stage: 'publish',
        status: 'healthy',
        message: `publish completed (${publishResult.source} -> ${publishResult.target})`,
        at: this.now(),
      });
      this.appendReleaseEvent(graph, {
        eventId: this.idFactory(),
        app: project.name,
        environment,
        releaseId,
        kind: 'publish_succeeded',
        message: 'publish completed',
        at: this.now(),
      });

      const smokeFailed =
        publishResult.smokeGateStatus === 'failed' ||
        (environment === 'production' &&
          Boolean(smokeTarget) &&
          publishResult.smokeGateStatus !== 'passed');
      if (smokeFailed) {
        release.status = 'failed';
        release.failureClass = 'smoke';
        release.failureCause =
          publishResult.error ??
          `Smoke check failed for target ${smokeTarget ?? 'unknown'}`;
        this.pushReleaseLog(
          graph,
          releaseId,
          `smoke check failed: ${release.failureCause}`
        );
        this.pushReleaseHealth(release, {
          stage: 'smoke',
          status: 'failed',
          message: release.failureCause,
          at: this.now(),
        });
        this.appendReleaseEvent(graph, {
          eventId: this.idFactory(),
          app: project.name,
          environment,
          releaseId,
          kind: 'smoke_failed',
          message: release.failureCause,
          at: this.now(),
        });
        const rollbackTo = this.autoRollbackOnSmokeFailure(graph, release);
        this.persistReleaseGraph(graph);
        void this.pushRemoteSync();
        return {
          status: 'failed',
          environment,
          workspaceRoot,
          app: project.name,
          release,
          currentReleaseId: graph.currentReleaseId ?? undefined,
          ...(rollbackTo ? { rollbackToReleaseId: rollbackTo } : {}),
          failureClass: release.failureClass,
          error: release.failureCause,
        };
      }

      this.pushReleaseHealth(release, {
        stage: 'smoke',
        status:
          publishResult.smokeGateStatus === 'passed' ? 'healthy' : 'degraded',
        message:
          publishResult.smokeGateStatus === 'passed'
            ? `smoke passed (${smokeTarget ?? 'default'})`
            : 'smoke not required',
        at: this.now(),
      });
      this.appendReleaseEvent(graph, {
        eventId: this.idFactory(),
        app: project.name,
        environment,
        releaseId,
        kind: 'smoke_passed',
        message:
          publishResult.smokeGateStatus === 'passed'
            ? `smoke passed (${smokeTarget ?? 'default'})`
            : 'smoke not required',
        at: this.now(),
      });

      graph.currentReleaseId = releaseId;
      release.status = 'promoted';
      this.pushReleaseHealth(release, {
        stage: 'promote',
        status: 'healthy',
        message: `promoted to ${release.url}`,
        at: this.now(),
      });
      this.appendReleaseEvent(graph, {
        eventId: this.idFactory(),
        app: project.name,
        environment,
        releaseId,
        kind: 'promoted',
        message: `promoted to ${release.url}`,
        at: this.now(),
      });
      this.pushReleaseLog(graph, releaseId, `promoted url=${release.url}`);
      if (release.previewUrl) {
        this.pushReleaseLog(
          graph,
          releaseId,
          `preview url=${release.previewUrl}`
        );
      }
      this.persistReleaseGraph(graph);
      void this.pushRemoteSync();
      session.activeApp = project.name;
      session.activeEnvironment = environment;

      return {
        status: 'released',
        environment,
        workspaceRoot,
        app: project.name,
        release,
        currentReleaseId: releaseId,
      };
    } finally {
      this.activeShipLocks.delete(lockKey);
    }
  }

  async shipStack(request: StackShipRequest): Promise<StackShipResult> {
    const session = this.requireSession(request.sessionId);
    const stackName = request.stack.trim();
    if (stackName.length === 0) {
      throw new Error('stack is required');
    }
    const environment = normalizeDeployEnvironment(
      request.environment ?? session.activeEnvironment
    );
    const workspaceRoot = resolve(
      request.workspaceRoot ?? this.deployWorkspaceRoot
    );
    const substrate = request.substrate ?? DEFAULT_SUBSTRATE;
    let apps = normalizeStringList(request.apps);
    const dependencyInput: Record<string, string[]> = {
      ...(request.dependencies ?? {}),
    };
    let promotionInput = normalizeStringList(request.promotionOrder ?? []);
    let healthGates = normalizeStringList(request.healthGates ?? []);

    if (apps.length === 0) {
      const adapter = await this.getDeployAdapter(substrate);
      const scannedProjects = new Set<string>();
      const resolveFromProjects = async (
        projects: AeonDeployProject[]
      ): Promise<boolean> => {
        for (const project of projects) {
          const projectKey = `${project.name}:${project.dir}`;
          if (scannedProjects.has(projectKey)) {
            continue;
          }
          scannedProjects.add(projectKey);
          const plan = await this.resolvePlanWithContractEnrichment(
            adapter,
            workspaceRoot,
            project,
            environment
          );
          if (!plan?.stackContract) {
            continue;
          }
          const contract = normalizeStackContract(plan.stackContract);
          if (!contract) {
            continue;
          }
          if (contract.name !== stackName && project.name !== stackName) {
            continue;
          }
          apps = [...contract.apps];
          for (const dependency of contract.dependencies) {
            dependencyInput[dependency.app] = [...dependency.dependsOn];
          }
          if (promotionInput.length === 0) {
            promotionInput = [...contract.promotionOrder];
          }
          if (healthGates.length === 0) {
            healthGates = [...contract.healthGates];
          }
          return true;
        }
        return false;
      };

      const narrowedProjects = await adapter.discover(workspaceRoot, [
        stackName,
      ]);
      const foundFromNarrowed = await resolveFromProjects(narrowedProjects);
      if (!foundFromNarrowed) {
        const fallbackProjects = await adapter.discover(workspaceRoot);
        await resolveFromProjects(fallbackProjects);
      }
    }

    if (apps.length === 0) {
      return {
        status: 'failed',
        stack: stackName,
        environment,
        appResults: [],
        error:
          'stack apps are required. Pass apps explicitly or declare a stack contract in a gnot app manifest.',
      };
    }

    const dependencies = normalizeDependencies(apps, dependencyInput);
    const topo = topoOrder(apps, dependencies);
    if (!topo) {
      return {
        status: 'failed',
        stack: stackName,
        environment,
        appResults: [],
        error: 'stack dependencies contain a cycle',
      };
    }
    const promotionOrder = promotionInput.length > 0 ? promotionInput : topo;
    const orderedApps =
      promotionOrder.length === apps.length &&
      promotionOrder.every((app) => apps.includes(app))
        ? promotionOrder
        : topo;
    const strategy = request.strategy ?? 'transactional';

    const appResults: ShipResult[] = [];
    for (const app of orderedApps) {
      const result = await this.ship({
        sessionId: request.sessionId,
        app,
        environment,
        workspaceRoot,
        env: request.env,
        trigger: request.trigger,
        substrate,
        delegationChain: request.delegationChain,
      });
      appResults.push(result);
      if (result.status === 'failed' || result.status === 'unavailable') {
        if (strategy === 'transactional') {
          const successful = appResults.filter(
            (item) => item.status === 'released' || item.status === 'unchanged'
          );
          for (const shipped of successful.reverse()) {
            void this.releaseRollback({
              sessionId: request.sessionId,
              app: shipped.app,
              environment,
              releaseId: 'previous',
            });
          }
        }
        return {
          status: 'failed',
          stack: stackName,
          environment,
          appResults,
          error: result.error ?? `stack ship failed on app ${app}`,
        };
      }
    }

    const effectiveStackContract: StackContract = {
      name: stackName,
      apps: [...apps],
      dependencies: Object.entries(dependencies).map(([app, dependsOn]) => ({
        app,
        dependsOn: [...dependsOn],
      })),
      promotionOrder: [...orderedApps],
      healthGates: [...healthGates],
    };

    const stackGraph = this.getOrCreateReleaseGraph(
      `stack/${stackName}`,
      environment
    );
    const releaseId = this.nextReleaseId();
    const now = this.now();
    const childReleaseIds = appResults
      .map((item) => item.release?.releaseId)
      .filter((value): value is string => Boolean(value));
    const stackRelease: ReleaseRecord = {
      releaseId,
      app: `stack/${stackName}`,
      environment,
      createdAt: now,
      fingerprint: computeShipFingerprint({
        app: `stack/${stackName}`,
        environment,
        plan: {
          substrate,
          source: 'project.json',
          target: stackName,
          argv: ['stack', ...orderedApps],
          smokeTarget: null,
          smokeGateRequired: false,
          stackContract: effectiveStackContract,
        },
        env: normalizeEnvInputs(request.env),
      }),
      url: '',
      previewUrl: null,
      plan: {
        substrate,
        source: 'project.json',
        target: stackName,
        argv: ['stack', ...orderedApps],
        smokeTarget: null,
        smokeGateRequired: false,
        stackContract: effectiveStackContract,
      },
      provenance: {
        trigger: request.trigger ?? 'repl',
        substrate,
        source: 'project.json',
        target: stackName,
        argv: ['stack', ...orderedApps],
        delegationChain: parseDelegationChain(
          request.delegationChain,
          session.authority
        ),
      },
      smokeGateStatus: 'not-required',
      status: 'promoted',
      childReleaseIds,
      health: [
        {
          stage: 'promote',
          status: 'healthy',
          message: `stack promoted with ${orderedApps.length} app releases`,
          at: now,
        },
      ],
    };
    stackGraph.releases.push(stackRelease);
    stackGraph.currentReleaseId = releaseId;
    this.appendReleaseEvent(stackGraph, {
      eventId: this.idFactory(),
      app: stackGraph.app,
      environment,
      releaseId,
      kind: 'promoted',
      message: `stack release promoted (${orderedApps.join(', ')})`,
      at: now,
    });
    this.persistReleaseGraph(stackGraph);
    void this.pushRemoteSync();

    const promoteTargets = Array.from(
      new Set(
        (request.promoteEnvironments ?? [])
          .map((entry) => normalizeDeployEnvironment(entry))
          .filter((target) => target !== environment)
      )
    );
    const promotions: ReleasePromoteResult[] = [];
    if (promoteTargets.length > 0) {
      for (const targetEnvironment of promoteTargets) {
        for (const appResult of appResults) {
          const promoted = this.releasePromote({
            sessionId: request.sessionId,
            app: appResult.app,
            fromEnvironment: environment,
            toEnvironment: targetEnvironment,
            releaseId: appResult.release?.releaseId ?? 'current',
            delegationChain: request.delegationChain,
          });
          promotions.push(promoted);
        }
      }
      const failedPromotions = promotions.filter(
        (promotion) => promotion.status === 'failed'
      );
      if (failedPromotions.length > 0) {
        if (strategy === 'transactional') {
          const succeeded = promotions.filter(
            (promotion) => promotion.status === 'promoted'
          );
          for (const promotion of succeeded.reverse()) {
            void this.releaseRollback({
              sessionId: request.sessionId,
              app: promotion.app,
              environment: promotion.toEnvironment,
              releaseId: 'previous',
            });
          }
        }
        return {
          status: 'failed',
          stack: stackName,
          environment,
          release: stackRelease,
          appResults,
          promotions,
          error:
            failedPromotions[0]?.error ??
            'one or more environment promotions failed',
        };
      }
    }

    return {
      status: 'released',
      stack: stackName,
      environment,
      release: stackRelease,
      appResults,
      ...(promotions.length > 0 ? { promotions } : {}),
    };
  }

  async doctor(request: DoctorRequest): Promise<DoctorResult> {
    const session = this.requireSession(request.sessionId);
    const app = (request.app ?? session.activeApp ?? '').trim();
    const environment = normalizeDeployEnvironment(
      request.environment ?? session.activeEnvironment
    );
    const checks: DoctorCheck[] = [];
    if (app.length === 0) {
      checks.push({
        key: 'context',
        status: 'block',
        message: 'No app context selected. Use :use <app> [env].',
      });
      return {
        app: '',
        environment,
        ready: false,
        checks,
      };
    }

    checks.push({
      key: 'context',
      status: 'ok',
      message: `context ${app} (${environment})`,
    });

    const workspaceRoot = resolve(
      request.workspaceRoot ?? this.deployWorkspaceRoot
    );
    let adapter: DeployAdapter;
    try {
      adapter = await this.getDeployAdapter(request.substrate);
    } catch (error) {
      checks.push({
        key: 'plan',
        status: 'block',
        message: error instanceof Error ? error.message : String(error),
      });
      return { app, environment, ready: false, checks };
    }
    const projects = await adapter.discover(workspaceRoot, [app]);
    const project =
      projects.find((candidate) => projectMatchesSelector(candidate, app)) ??
      projects.find((candidate) => candidate.name === app);
    if (!project) {
      checks.push({
        key: 'plan',
        status: 'block',
        message: `No deployable app matched '${app}'.`,
      });
      return { app, environment, ready: false, checks };
    }

    const plan = await this.resolvePlanWithContractEnrichment(
      adapter,
      workspaceRoot,
      project,
      environment
    );
    if (!plan) {
      checks.push({
        key: 'plan',
        status: 'block',
        message: `No deployment plan for ${project.name} (${environment}).`,
      });
      return { app, environment, ready: false, checks };
    }
    checks.push({
      key: 'plan',
      status: 'ok',
      message: `${plan.source} -> ${plan.target}`,
    });

    const contract = plan.appContract ? resolveAppDeployContract(plan) : null;
    if (!contract) {
      checks.push({
        key: 'policy',
        status: 'block',
        message: 'deploy contract is required for ship-capable apps',
      });
      return { app, environment, ready: false, checks };
    }

    if (
      session.authority.authMaterialPresent &&
      session.authority.capabilities.length === 0 &&
      session.authority.ucanCapabilities.length === 0
    ) {
      checks.push({
        key: 'policy',
        status: 'block',
        message:
          'authorization material was provided, but no delegated capabilities were verified',
      });
      return { app, environment, ready: false, checks };
    }

    if (
      !capabilityAllows(session.authority, `ship:${project.name}`, {
        can: 'gnot/ship',
        with: `app://${project.name}`,
      })
    ) {
      checks.push({
        key: 'policy',
        status: 'block',
        message: `missing delegated capability ship:${project.name}`,
      });
    } else {
      checks.push({
        key: 'policy',
        status: 'ok',
        message: 'delegated ship capability check passed',
      });
    }

    const env = normalizeEnvInputs(request.env);
    const missingEnv = contract.envSchema.required.filter(
      (name) => !(name in env) || env[name] === ''
    );
    if (missingEnv.length > 0) {
      checks.push({
        key: 'env',
        status: 'block',
        message: `missing required env vars: ${missingEnv.join(', ')}`,
      });
    } else {
      checks.push({
        key: 'env',
        status: 'ok',
        message: 'required env vars satisfied',
      });
    }

    const smokeTarget = resolveSmokeTarget(plan, contract);
    if (environment === 'production' && !smokeTarget) {
      checks.push({
        key: 'smoke',
        status: 'block',
        message: 'production requires deploy.health.smoke target',
      });
    } else {
      checks.push({
        key: 'smoke',
        status: smokeTarget ? 'ok' : 'warn',
        message: smokeTarget
          ? `smoke target: ${smokeTarget}`
          : 'no smoke target configured (non-production)',
      });
    }

    try {
      const { discoverTopology } = await import('@a0n/x-ranger');
      const { createHash } = await import('node:crypto');
      const topology = await discoverTopology(workspaceRoot, environment);
      const proofPath = join(workspaceRoot, 'topology-proof.json');
      
      if (!existsSync(proofPath)) {
        checks.push({
          key: 'topology',
          status: 'block',
          message: 'missing topology-proof.json. Run `x-ranger mesh sign`',
        });
      } else {
        const token = JSON.parse(readFileSync(proofPath, 'utf8'));
        const canonicalString = JSON.stringify(topology, Object.keys(topology).sort());
        const currentHash = createHash('sha256').update(canonicalString).digest('hex');
        
        if (currentHash !== token.topologyHash) {
          checks.push({
            key: 'topology',
            status: 'block',
            message: 'topological divergence detected. Run `x-ranger mesh sign` to re-audit and sign.',
          });
        } else {
          checks.push({
            key: 'topology',
            status: 'ok',
            message: 'cryptographic topological soundness verified',
          });
        }
      }
    } catch (e) {
      checks.push({
        key: 'topology',
        status: 'warn',
        message: `failed to verify topological soundness: ${e instanceof Error ? e.message : String(e)}`,
      });
    }

    const status = this.releaseStatus({
      sessionId: request.sessionId,
      app: project.name,
      environment,
    });
    checks.push({
      key: 'release',
      status: status.currentReleaseId ? 'ok' : 'warn',
      message: status.currentReleaseId
        ? `current release ${status.currentReleaseId} (${status.currentHealth})`
        : 'no promoted release yet',
    });

    return {
      app: project.name,
      environment,
      ready: checks.every((check) => check.status !== 'block'),
      checks,
    };
  }

  async nextAction(request: NextActionRequest): Promise<NextActionResult> {
    const session = this.requireSession(request.sessionId);
    const app = (request.app ?? session.activeApp ?? '').trim();
    const environment = normalizeDeployEnvironment(
      request.environment ?? session.activeEnvironment
    );
    if (app.length === 0) {
      return {
        action: 'use_app',
        summary: 'Select an app first with :use <app> [env].',
      };
    }

    const diagnosis = await this.doctor({
      sessionId: request.sessionId,
      app,
      environment,
      workspaceRoot: request.workspaceRoot,
      env: request.env,
      substrate: request.substrate,
    });
    const firstBlock = diagnosis.checks.find(
      (check) => check.status === 'block'
    );
    if (firstBlock) {
      if (firstBlock.key === 'env') {
        return {
          action: 'fix_env',
          summary: firstBlock.message,
          app,
          environment,
        };
      }
      if (firstBlock.key === 'smoke') {
        return {
          action: 'set_smoke',
          summary: firstBlock.message,
          app,
          environment,
        };
      }
      return {
        action: 'fix_policy',
        summary: firstBlock.message,
        app,
        environment,
      };
    }

    const status = this.releaseStatus({
      sessionId: request.sessionId,
      app,
      environment,
    });
    if (!status.currentReleaseId) {
      return {
        action: 'ship',
        summary: 'No promoted release exists; run :ship.',
        app,
        environment,
      };
    }
    if (status.currentHealth !== 'healthy') {
      return {
        action: 'inspect_logs',
        summary: `Current release health is ${status.currentHealth}; inspect logs.`,
        app,
        environment,
      };
    }
    return {
      action: 'ship',
      summary: 'Environment is healthy; ship when you have a new candidate.',
      app,
      environment,
    };
  }

  releaseStatus(request: ReleaseStatusRequest): ReleaseStatusResult {
    this.requireSession(request.sessionId);
    const environment = normalizeDeployEnvironment(request.environment);
    const graph = this.findReleaseGraph(request.app, environment);
    if (!graph) {
      return {
        app: request.app,
        environment,
        currentReleaseId: null,
        currentHealth: 'unknown',
        releases: [],
        events: [],
      };
    }

    const current = graph.currentReleaseId
      ? graph.releases.find(
          (release) => release.releaseId === graph.currentReleaseId
        )
      : undefined;

    return {
      app: graph.app,
      environment,
      currentReleaseId: graph.currentReleaseId,
      currentHealth: currentHealthFromRelease(current),
      releases: [...graph.releases],
      events: [...graph.events],
    };
  }

  releaseLogs(request: ReleaseLogsRequest): ReleaseLogsResult {
    this.requireSession(request.sessionId);
    const environment = normalizeDeployEnvironment(request.environment);
    const graph = this.findReleaseGraph(request.app, environment);
    if (!graph) {
      return {
        app: request.app,
        environment,
        releaseId: null,
        lines: [],
      };
    }

    const releaseId = request.releaseId ?? graph.currentReleaseId;
    if (!releaseId) {
      return {
        app: graph.app,
        environment,
        releaseId: null,
        lines: [],
      };
    }
    return {
      app: graph.app,
      environment,
      releaseId,
      lines: [...(graph.logs.get(releaseId) ?? [])],
    };
  }

  releaseReplay(request: ReleaseReplayRequest): ReleaseReplayResult {
    this.requireSession(request.sessionId);
    const environment = normalizeDeployEnvironment(request.environment);
    const graph = this.findReleaseGraph(request.app, environment);
    if (!graph) {
      return {
        app: request.app,
        environment,
        currentReleaseId: null,
        events: [],
      };
    }
    const events = [...graph.events].sort((left, right) => left.at - right.at);
    let pointer: string | null = null;
    for (const event of events) {
      if (event.kind === 'promoted' && event.releaseId) {
        pointer = event.releaseId;
      }
      if (event.kind === 'rollback_completed' && event.releaseId) {
        pointer = event.releaseId;
      }
    }
    return {
      app: graph.app,
      environment,
      currentReleaseId: pointer ?? graph.currentReleaseId,
      events,
    };
  }

  releasePromote(request: ReleasePromoteRequest): ReleasePromoteResult {
    const session = this.requireSession(request.sessionId);
    const fromEnvironment = normalizeDeployEnvironment(
      request.fromEnvironment ?? session.activeEnvironment
    );
    const toEnvironment = normalizeDeployEnvironment(request.toEnvironment);
    if (fromEnvironment === toEnvironment) {
      return {
        status: 'failed',
        app: request.app,
        fromEnvironment,
        toEnvironment,
        fromReleaseId: null,
        error: 'source and target environments must differ',
      };
    }

    const sourceGraph = this.findReleaseGraph(request.app, fromEnvironment);
    if (!sourceGraph) {
      return {
        status: 'failed',
        app: request.app,
        fromEnvironment,
        toEnvironment,
        fromReleaseId: null,
        error: `No release graph exists for ${request.app} in ${fromEnvironment}`,
      };
    }

    if (
      !capabilityAllows(session.authority, `promote:${sourceGraph.app}`, {
        can: 'gnot/promote',
        with: `app://${sourceGraph.app}`,
      })
    ) {
      return {
        status: 'failed',
        app: sourceGraph.app,
        fromEnvironment,
        toEnvironment,
        fromReleaseId: sourceGraph.currentReleaseId,
        error: `missing delegated capability promote:${sourceGraph.app}`,
      };
    }

    const sourceRelease =
      request.releaseId && request.releaseId !== 'current'
        ? sourceGraph.releases.find(
            (release) => release.releaseId === request.releaseId
          )
        : sourceGraph.currentReleaseId
        ? sourceGraph.releases.find(
            (release) => release.releaseId === sourceGraph.currentReleaseId
          )
        : undefined;
    if (!sourceRelease) {
      return {
        status: 'failed',
        app: sourceGraph.app,
        fromEnvironment,
        toEnvironment,
        fromReleaseId: sourceGraph.currentReleaseId,
        error:
          request.releaseId && request.releaseId !== 'current'
            ? `release ${request.releaseId} was not found`
            : 'no promoted source release exists',
      };
    }

    if (sourceRelease.status !== 'promoted') {
      return {
        status: 'failed',
        app: sourceGraph.app,
        fromEnvironment,
        toEnvironment,
        fromReleaseId: sourceRelease.releaseId,
        error: `source release ${sourceRelease.releaseId} is not promoted`,
      };
    }

    if (currentHealthFromRelease(sourceRelease) !== 'healthy') {
      return {
        status: 'failed',
        app: sourceGraph.app,
        fromEnvironment,
        toEnvironment,
        fromReleaseId: sourceRelease.releaseId,
        error: `source release ${sourceRelease.releaseId} is not healthy`,
      };
    }

    const targetGraph = this.getOrCreateReleaseGraph(
      sourceGraph.app,
      toEnvironment
    );
    const targetCurrent = targetGraph.currentReleaseId
      ? targetGraph.releases.find(
          (release) => release.releaseId === targetGraph.currentReleaseId
        )
      : undefined;
    if (
      targetCurrent &&
      targetCurrent.fingerprint === sourceRelease.fingerprint &&
      targetCurrent.status === 'promoted'
    ) {
      return {
        status: 'promoted',
        app: sourceGraph.app,
        fromEnvironment,
        toEnvironment,
        fromReleaseId: sourceRelease.releaseId,
        toReleaseId: targetCurrent.releaseId,
      };
    }

    const now = this.now();
    const promotedReleaseId = this.nextReleaseId();
    const promotedRelease: ReleaseRecord = {
      ...sourceRelease,
      releaseId: promotedReleaseId,
      environment: toEnvironment,
      createdAt: now,
      health: [
        ...sourceRelease.health,
        {
          stage: 'promote',
          status: 'healthy',
          message: `promoted from ${fromEnvironment}:${sourceRelease.releaseId}`,
          at: now,
        },
      ],
      provenance: {
        ...sourceRelease.provenance,
        delegationChain: parseDelegationChain(
          request.delegationChain,
          session.authority
        ),
      },
    };
    targetGraph.releases.push(promotedRelease);
    targetGraph.currentReleaseId = promotedReleaseId;
    this.appendReleaseEvent(targetGraph, {
      eventId: this.idFactory(),
      app: targetGraph.app,
      environment: toEnvironment,
      releaseId: promotedReleaseId,
      kind: 'promoted',
      message: `promoted from ${fromEnvironment}:${sourceRelease.releaseId}`,
      at: now,
    });
    this.pushReleaseLog(
      targetGraph,
      promotedReleaseId,
      `promoted from ${fromEnvironment}:${sourceRelease.releaseId}`
    );
    this.persistReleaseGraph(targetGraph);
    void this.pushRemoteSync();

    return {
      status: 'promoted',
      app: sourceGraph.app,
      fromEnvironment,
      toEnvironment,
      fromReleaseId: sourceRelease.releaseId,
      toReleaseId: promotedReleaseId,
    };
  }

  releaseRollback(request: ReleaseRollbackRequest): ReleaseRollbackResult {
    const session = this.requireSession(request.sessionId);
    const environment = normalizeDeployEnvironment(request.environment);
    const graph = this.findReleaseGraph(request.app, environment);
    if (!graph) {
      return {
        status: 'failed',
        app: request.app,
        environment,
        fromReleaseId: null,
        error: `No release graph exists for ${request.app}`,
      };
    }
    if (
      !capabilityAllows(session.authority, `rollback:${graph.app}`, {
        can: 'gnot/rollback',
        with: `app://${graph.app}`,
      })
    ) {
      return {
        status: 'failed',
        app: graph.app,
        environment,
        fromReleaseId: graph.currentReleaseId,
        error: `missing delegated capability rollback:${graph.app}`,
      };
    }

    const fromReleaseId = graph.currentReleaseId;
    if (!fromReleaseId) {
      return {
        status: 'failed',
        app: graph.app,
        environment,
        fromReleaseId: null,
        error: 'No current release is available to roll back from',
      };
    }

    const targetRelease =
      request.releaseId && request.releaseId !== 'previous'
        ? graph.releases.find(
            (release) => release.releaseId === request.releaseId
          )
        : this.previousHealthyRelease(graph, fromReleaseId);
    if (!targetRelease) {
      return {
        status: 'failed',
        app: graph.app,
        environment,
        fromReleaseId,
        error:
          request.releaseId && request.releaseId !== 'previous'
            ? `Release ${request.releaseId} was not found`
            : 'No previous healthy release exists',
      };
    }

    const now = this.now();
    this.pushReleaseHealth(targetRelease, {
      stage: 'rollback',
      status: 'healthy',
      message: `promoted by rollback from ${fromReleaseId}`,
      at: now,
    });
    graph.currentReleaseId = targetRelease.releaseId;
    this.appendReleaseEvent(graph, {
      eventId: this.idFactory(),
      app: graph.app,
      environment,
      releaseId: targetRelease.releaseId,
      kind: 'rollback_completed',
      message: `rollback pointer moved from ${fromReleaseId} to ${targetRelease.releaseId}`,
      at: now,
    });
    this.pushReleaseLog(
      graph,
      targetRelease.releaseId,
      `rollback promoted from ${fromReleaseId}`
    );
    this.persistReleaseGraph(graph);
    void this.pushRemoteSync();

    return {
      status: 'rolled_back',
      app: graph.app,
      environment,
      fromReleaseId,
      toReleaseId: targetRelease.releaseId,
    };
  }

  close(): void {
    for (const session of this.sessions.values()) {
      for (const job of session.jobs.values()) {
        job.controller.abort();
      }
    }
    this.sessions.clear();
    this.releaseGraphs.clear();
    this.historyStore.close();
    this.releaseStore.close();
  }

  private nextReleaseId(): string {
    this.releaseCounter += 1;
    return `rel_${this.now()}_${String(this.releaseCounter).padStart(4, '0')}`;
  }

  private getOrCreateReleaseGraph(
    app: string,
    environment: DeployEnvironment
  ): ReleaseGraphState {
    const key = releaseGraphKey(app, environment);
    const existing = this.releaseGraphs.get(key);
    if (existing) {
      return existing;
    }
    const created: ReleaseGraphState = {
      app,
      environment,
      releases: [],
      currentReleaseId: null,
      logs: new Map<string, string[]>(),
      events: [],
    };
    this.releaseGraphs.set(key, created);
    this.persistReleaseGraph(created);
    return created;
  }

  private findReleaseGraph(
    selector: string,
    environment: DeployEnvironment
  ): ReleaseGraphState | null {
    const direct = this.releaseGraphs.get(
      releaseGraphKey(selector, environment)
    );
    if (direct) {
      return direct;
    }

    const normalizedSelector = normalizeSelectorPath(selector);
    if (!normalizedSelector) {
      return null;
    }
    for (const graph of this.releaseGraphs.values()) {
      if (graph.environment !== environment) {
        continue;
      }
      const normalizedApp = normalizeSelectorPath(graph.app);
      if (
        normalizedApp === normalizedSelector ||
        normalizedApp.endsWith(`/${normalizedSelector}`) ||
        normalizedSelector.endsWith(normalizedApp)
      ) {
        return graph;
      }
    }
    return null;
  }

  private pushReleaseLog(
    graph: ReleaseGraphState,
    releaseId: string,
    line: string
  ): void {
    const entries = graph.logs.get(releaseId) ?? [];
    entries.push(`[${new Date(this.now()).toISOString()}] ${line}`);
    graph.logs.set(releaseId, entries.slice(-200));
  }

  private appendReleaseEvent(
    graph: ReleaseGraphState,
    event: ReleaseEvent
  ): void {
    graph.events.push(event);
  }

  private pushReleaseHealth(
    release: ReleaseRecord,
    snapshot: ReleaseHealthSnapshot
  ): void {
    release.health.push(snapshot);
  }

  private previousHealthyRelease(
    graph: ReleaseGraphState,
    excludeReleaseId: string
  ): ReleaseRecord | undefined {
    for (let idx = graph.releases.length - 1; idx >= 0; idx -= 1) {
      const candidate = graph.releases[idx];
      if (candidate.releaseId === excludeReleaseId) {
        continue;
      }
      if (candidate.status === 'failed') {
        continue;
      }
      return candidate;
    }
    return undefined;
  }

  private autoRollbackOnSmokeFailure(
    graph: ReleaseGraphState,
    failedRelease: ReleaseRecord
  ): string | null {
    if (failedRelease.failureClass !== 'smoke') {
      return null;
    }
    const fallback = this.previousHealthyRelease(
      graph,
      failedRelease.releaseId
    );
    if (!fallback) {
      this.pushReleaseHealth(failedRelease, {
        stage: 'rollback',
        status: 'failed',
        message: 'automatic rollback unavailable: no previous healthy release',
        at: this.now(),
      });
      return null;
    }

    failedRelease.rollbackToReleaseId = fallback.releaseId;
    this.pushReleaseHealth(failedRelease, {
      stage: 'rollback',
      status: 'healthy',
      message: `automatic rollback to ${fallback.releaseId}`,
      at: this.now(),
    });
    this.appendReleaseEvent(graph, {
      eventId: this.idFactory(),
      app: graph.app,
      environment: graph.environment,
      releaseId: failedRelease.releaseId,
      kind: 'rollback_triggered',
      message: `automatic rollback to ${fallback.releaseId}`,
      at: this.now(),
    });
    graph.currentReleaseId = fallback.releaseId;
    this.pushReleaseLog(
      graph,
      failedRelease.releaseId,
      `automatic rollback to ${fallback.releaseId}`
    );
    this.pushReleaseLog(
      graph,
      fallback.releaseId,
      `restored as current after smoke failure in ${failedRelease.releaseId}`
    );
    return fallback.releaseId;
  }

  private persistReleaseGraph(graph: ReleaseGraphState): void {
    this.releaseStore.saveGraph(toReleaseGraphSnapshot(graph));
  }

  private async bootstrapRemoteSync(): Promise<void> {
    if (!this.releaseSync || this.remoteSyncBootstrapped) {
      return;
    }
    if (this.remoteSyncPromise) {
      await this.remoteSyncPromise;
      return;
    }
    this.remoteSyncPromise = (async () => {
      const payload = await this.releaseSync?.pull();
      if (!payload || payload.version !== 1) {
        this.remoteSyncBootstrapped = true;
        return;
      }
      for (const snapshot of payload.graphs) {
        const key = releaseGraphKey(snapshot.app, snapshot.environment);
        const incoming = fromReleaseGraphSnapshot(snapshot);
        const current = this.releaseGraphs.get(key);
        const merged = current
          ? mergeReleaseGraphs(current, incoming)
          : incoming;
        this.releaseGraphs.set(key, merged);
        this.persistReleaseGraph(merged);
      }
      this.remoteSyncBootstrapped = true;
    })()
      .catch(() => {
        // Remote sync is optional and must never block local operation.
      })
      .finally(() => {
        this.remoteSyncPromise = null;
      });
    await this.remoteSyncPromise;
  }

  private async pushRemoteSync(): Promise<void> {
    if (!this.releaseSync) {
      return;
    }
    const payload: ReleaseSyncPayload = {
      version: 1,
      generatedAt: this.now(),
      graphs: Array.from(this.releaseGraphs.values()).map((graph) =>
        toReleaseGraphSnapshot(graph)
      ),
    };
    try {
      await this.releaseSync.push(payload);
    } catch {
      // Optional best-effort sync.
    }
  }

  private async getDeployAdapter(
    substrate: DeploySubstrate = DEFAULT_SUBSTRATE
  ): Promise<DeployAdapter> {
    const registered = this.substrateAdapters.get(substrate);
    if (registered) {
      return registered;
    }
    if (substrate !== DEFAULT_SUBSTRATE) {
      throw new Error(
        `no deploy adapter is registered for substrate '${substrate}'`
      );
    }
    if (!this.deployAdapterPromise) {
      this.deployAdapterPromise = createAeonForgeDeployAdapter(
        this.repoRoot
      ).catch((error) => {
        this.deployAdapterPromise = null;
        const message = error instanceof Error ? error.message : String(error);
        throw new Error(
          `failed to initialize aeon-forge deploy adapter: ${message}`
        );
      });
    }
    const adapter = await this.deployAdapterPromise;
    this.substrateAdapters.set(DEFAULT_SUBSTRATE, adapter);
    return adapter;
  }

  private async resolvePlanWithContractEnrichment(
    adapter: DeployAdapter,
    workspaceRoot: string,
    project: AeonDeployProject,
    environment: DeployEnvironment
  ): Promise<AeonRemotePublishPlan | null> {
    const plan = await adapter.resolvePlan(workspaceRoot, project, environment);
    if (!plan) {
      return null;
    }
    const projectRoot = resolve(workspaceRoot, project.dir);
    const candidates = collectCandidateGnotFiles(projectRoot);
    if (candidates.length === 0) {
      return plan;
    }

    for (const filePath of candidates) {
      let source: string;
      try {
        source = readFileSync(filePath, 'utf8');
      } catch {
        continue;
      }
      const controller = new AbortController();
      const result = await runWithAbortableCommand(this.commandRunner, {
        command: 'emit-app-manifest',
        source,
        timeoutMs: 5_000,
        repoRoot: this.repoRoot,
        signal: controller.signal,
      });
      if (result.exitCode !== 0 || result.timedOut) {
        continue;
      }
      let manifest: unknown;
      try {
        manifest = JSON.parse(result.stdout);
      } catch {
        continue;
      }
      const deployContract = appDeployContractFromManifestJson(manifest);
      const stackContract = stackContractFromManifestJson(manifest);
      if (!deployContract && !stackContract) {
        continue;
      }
      return {
        ...plan,
        appContract: {
          ...(deployContract ?? {}),
          ...(plan.appContract ?? {}),
        },
        ...(stackContract ? { stackContract } : {}),
      };
    }

    return plan;
  }

  private requireSession(sessionId: string): SessionState {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`unknown session: ${sessionId}`);
    }
    return session;
  }

  private async runJob(session: SessionState, job: JobState): Promise<void> {
    const startedAt = this.now();
    job.startedAt = startedAt;
    job.status = 'running';

    this.emitEvent({
      type: 'job_started',
      eventId: this.idFactory(),
      sessionId: session.sessionId,
      jobId: job.id,
      at: startedAt,
      status: 'running',
    });

    try {
      const mode = normalizeMode(job.request.mode ?? session.evalMode);
      const safetyMode = normalizeSafetyMode(
        job.request.safetyMode ?? session.safetyMode
      );
      const timeoutMs =
        job.request.timeoutMs && job.request.timeoutMs > 0
          ? job.request.timeoutMs
          : session.defaultTimeoutMs ?? this.defaultTimeoutMs;
      const source = applyRange(
        job.request.source,
        job.request.range?.startLine,
        job.request.range?.endLine
      );

      const warnings: string[] = [];
      if (mode === 'live') {
        this.enforceLiveSafetyPolicy(source, safetyMode);
      }

      this.emitEvent({
        type: 'job_output',
        eventId: this.idFactory(),
        sessionId: session.sessionId,
        jobId: job.id,
        at: this.now(),
        status: 'running',
        message: `mode=${mode} safety=${safetyMode} timeout=${timeoutMs}ms`,
      });

      const result =
        mode === 'live'
          ? await this.runLiveJob(session, source, timeoutMs, warnings)
          : await this.runDryJob(session, source, timeoutMs, warnings, job);

      if (job.controller.signal.aborted) {
        throw new Error('job canceled');
      }

      job.status = 'completed';
      job.finishedAt = this.now();
      session.updatedAt = job.finishedAt;
      session.lastValue = result;
      this.historyStore.append(
        session.sessionId,
        'output',
        result.summary,
        job.finishedAt
      );

      this.emitEvent({
        type: 'job_completed',
        eventId: this.idFactory(),
        sessionId: session.sessionId,
        jobId: job.id,
        at: job.finishedAt,
        status: 'completed',
        result,
        durationMs: job.finishedAt - startedAt,
      });
    } catch (error) {
      const finishedAt = this.now();
      job.finishedAt = finishedAt;
      session.updatedAt = finishedAt;
      if (job.controller.signal.aborted) {
        job.status = 'canceled';
        this.emitEvent({
          type: 'job_canceled',
          eventId: this.idFactory(),
          sessionId: session.sessionId,
          jobId: job.id,
          at: finishedAt,
          status: 'canceled',
          durationMs: finishedAt - startedAt,
        });
      } else {
        const message = error instanceof Error ? error.message : String(error);
        job.status = 'failed';
        this.historyStore.append(
          session.sessionId,
          'error',
          message,
          finishedAt
        );
        this.emitEvent({
          type: 'job_failed',
          eventId: this.idFactory(),
          sessionId: session.sessionId,
          jobId: job.id,
          at: finishedAt,
          status: 'failed',
          durationMs: finishedAt - startedAt,
          error: {
            message,
          },
        });
      }
    } finally {
      session.jobs.delete(job.id);
    }
  }

  private enforceLiveSafetyPolicy(
    source: string,
    safetyMode: SafetyMode
  ): void {
    if (safetyMode === 'off') {
      return;
    }
    const lower = source.toLowerCase();
    const matched = LIVE_SAFETY_BLOCKLIST.filter((token) =>
      lower.includes(token)
    );
    if (matched.length > 0) {
      throw new Error(
        `safety mode blocked live execution (tokens: ${matched.join(', ')})`
      );
    }
  }

  private async runDryJob(
    session: SessionState,
    source: string,
    timeoutMs: number,
    warnings: string[],
    job: JobState
  ): Promise<JobResult> {
    const check = await runWithAbortableCommand(this.commandRunner, {
      command: 'check',
      source,
      timeoutMs,
      repoRoot: this.repoRoot,
      signal: job.controller.signal,
    });
    if (check.exitCode !== 0 || check.timedOut) {
      throw new Error(formatCommandFailure(check.stdout, check.stderr));
    }

    this.emitEvent({
      type: 'job_output',
      eventId: this.idFactory(),
      sessionId: session.sessionId,
      jobId: job.id,
      at: this.now(),
      status: 'running',
      message: 'syntax + compile check passed',
    });

    const bytecode = await runWithAbortableCommand(this.commandRunner, {
      command: 'emit-ir-bytes',
      source,
      timeoutMs,
      repoRoot: this.repoRoot,
      signal: job.controller.signal,
    });
    if (bytecode.exitCode !== 0 || bytecode.timedOut) {
      throw new Error(formatCommandFailure(bytecode.stdout, bytecode.stderr));
    }

    let manifestJson = '';
    const manifest = await runWithAbortableCommand(this.commandRunner, {
      command: 'emit-app-manifest',
      source,
      timeoutMs,
      repoRoot: this.repoRoot,
      signal: job.controller.signal,
      args: ['--pretty'],
    });
    if (manifest.exitCode === 0 && !manifest.timedOut) {
      manifestJson = manifest.stdout.trim();
    } else {
      warnings.push('manifest not emitted for this source');
    }

    return encodeJobResult(
      `dry evaluation complete (${bytecode.stdout.trim().length / 2} bytes IR)`,
      [
        {
          name: 'ir_hex',
          value: bytecode.stdout.trim(),
        },
        {
          name: 'manifest',
          value: manifestJson,
        },
      ],
      warnings
    );
  }

  private async runLiveJob(
    session: SessionState,
    source: string,
    timeoutMs: number,
    warnings: string[]
  ): Promise<JobResult> {
    if (!session.allowLive) {
      throw new Error(
        'live mode is disabled for this session; set allowLive=true at session create'
      );
    }
    if (!this.liveExecutor) {
      throw new Error('live executor is not configured');
    }
    const result = await this.liveExecutor.execute({
      sessionId: session.sessionId,
      source,
      timeoutMs,
    });
    return encodeJobResult(result.summary, result.artifacts ?? [], [
      ...warnings,
      ...(result.warnings ?? []),
    ]);
  }

  private emitEvent(event: GnotReplEvent): void {
    this.eventEmitter.emit('event', event);
    for (const plugin of this.plugins) {
      void plugin.onEvent?.(event);
    }
  }
}
