import { readFileSync, writeFileSync } from 'node:fs';
import type { RemediationProposal } from '@a0n/cognitive-bridge';

/**
 * Autonomic TOML Surgeon
 *
 * Surgically updates aeon.toml or wrangler.toml to apply topological remediations
 * while preserving developer comments and formatting.
 */
export async function applyRemediationPatch(
  filePath: string,
  proposal: RemediationProposal
): Promise<void> {
  let content = readFileSync(filePath, 'utf8');
  let lines = content.split('\n');

  for (const change of proposal.proposedChanges) {
    if (change.type === 'remove') {
      lines = removeOverlayBlock(lines, change.overlayPathPrefix);
    } else if (change.type === 'narrow') {
      lines = narrowOverlayPrefix(
        lines,
        change.overlayPathPrefix,
        change.suggestion
      );
    } else if (change.type === 'exclude') {
      lines = addExclusionToOverlay(
        lines,
        change.overlayPathPrefix,
        change.suggestion
      );
    }
  }

  writeFileSync(filePath, lines.join('\n'), 'utf8');
}

function removeOverlayBlock(lines: string[], prefix: string): string[] {
  const result: string[] = [];
  let inTargetBlock = false;
  let blockStart = -1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    if (line.startsWith('[[mesh.overlays]]')) {
      inTargetBlock = false;
      blockStart = i;
    }

    // Identify if this is our target overlay
    if (
      blockStart !== -1 &&
      (line.includes(`path_prefix = "${prefix}"`) ||
        line.includes(`pathPrefix = "${prefix}"`))
    ) {
      inTargetBlock = true;
    }

    // If we've reached the end of the block or next header
    const isNextHeader =
      line.startsWith('[') && !line.startsWith('[[mesh.overlays]]');
    if (inTargetBlock && (isNextHeader || i === lines.length - 1)) {
      // Skip the block lines (backtrack to blockStart)
      // This is a simplified version; real surgeon would handle comments above block
      return lines.slice(0, blockStart).concat(lines.slice(i));
    }

    if (!inTargetBlock) {
      result.push(lines[i]);
    }
  }

  return result;
}

function narrowOverlayPrefix(
  lines: string[],
  oldPrefix: string,
  newPrefix: string
): string[] {
  return lines.map((line) => {
    const trimmed = line.trim();
    if (
      trimmed.startsWith('path_prefix =') ||
      trimmed.startsWith('pathPrefix =')
    ) {
      if (trimmed.includes(`"${oldPrefix}"`)) {
        return line.replace(`"${oldPrefix}"`, `"${newPrefix}"`);
      }
    }
    return line;
  });
}

function addExclusionToOverlay(
  lines: string[],
  prefix: string,
  _exclusion: string
): string[] {
  // For now, we'll just log that this isn't implemented;
  // complex exclusions require multi-line block injection.
  console.warn(`Surgical exclusion not yet implemented for ${prefix}`);
  return lines;
}
