/**
 * @a0n/auth - Type Definitions
 *
 * Core types for UCAN (User Controlled Authorization Networks)
 */

/**
 * Decentralized Identifier (DID)
 * Format: did:method:identifier
 *
 * @example
 * ```typescript
 * const did: DID = 'did:key:z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK';
 * ```
 */
export type DID = `did:${string}:${string}`;

/**
 * Supported signing algorithms
 */
export type SigningAlgorithm = 'ES256' | 'Ed25519' | 'ES384' | 'ES512';

/**
 * Key pair for signing and verification
 */
export interface KeyPair {
  /** Algorithm identifier */
  algorithm: SigningAlgorithm;
  /** Public key in JWK format */
  publicKey: JsonWebKey;
  /** Private key in JWK format (only present for owned keys) */
  privateKey?: JsonWebKey;
  /** Key fingerprint for quick comparison */
  fingerprint: string;
}

/**
 * Identity representing a user or node
 */
export interface Identity {
  /** Decentralized Identifier */
  did: DID;
  /** Signing key pair */
  signingKey: KeyPair;
  /** Optional encryption key pair (different from signing) */
  encryptionKey?: KeyPair;
  /** Creation timestamp */
  createdAt: number;
  /** Optional display name */
  displayName?: string;
}

/**
 * UCAN Capability structure
 *
 * @example
 * ```typescript
 * const cap: Capability = {
 *   can: 'file/write',
 *   with: 'storage://bucket/folder/*',
 * };
 * ```
 */
export interface Capability {
  /** The action that can be performed (e.g., 'file/read', 'sync/write') */
  can: string;
  /** The resource the capability applies to (URI or pattern) */
  with: string;
  /** Optional constraints on the capability */
  constraints?: Record<string, unknown>;
}

/**
 * UCAN Token payload (decoded JWT payload)
 */
export interface UCANPayload {
  /** Issuer DID - who created this token */
  iss: DID;
  /** Audience DID - who this token is for */
  aud: DID;
  /** Expiration timestamp (Unix seconds) */
  exp: number;
  /** Not before timestamp (Unix seconds) */
  nbf?: number;
  /** Issued at timestamp (Unix seconds) */
  iat?: number;
  /** Nonce for replay protection */
  nonce?: string;
  /** Unique token identifier */
  jti?: string;
  /** Attestations (capabilities) - UCAN spec uses 'att' */
  att: Capability[];
  /** Proof chain (encoded parent UCANs) */
  prf?: string[];
  /** Facts - additional claims */
  fct?: Record<string, unknown>;
}

/**
 * Complete UCAN Token (parsed)
 */
export interface UCANToken {
  /** The complete payload */
  payload: UCANPayload;
  /** The raw encoded token string */
  raw: string;
  /** Signature bytes (decoded) */
  signature: Uint8Array;
  /** Header algorithm */
  algorithm: string;
}

/**
 * Result of UCAN verification
 */
export interface VerificationResult {
  /** Whether the token is valid */
  valid: boolean;
  /** The verified payload (if valid) */
  payload?: UCANPayload;
  /** Error message (if invalid) */
  error?: string;
  /** Whether token is expired */
  expired?: boolean;
  /** Whether token should be rotated soon */
  shouldRotate?: boolean;
  /** Seconds until expiration */
  expiresIn?: number;
}

/**
 * Options for creating a UCAN token
 */
export interface CreateUCANOptions {
  /** Expiration time in seconds from now (default: 1 hour) */
  expirationSeconds?: number;
  /** Not before time in seconds from now */
  notBeforeSeconds?: number;
  /** Parent UCAN tokens for delegation chain */
  proofs?: string[];
  /** Additional facts/claims to include */
  facts?: Record<string, unknown>;
  /** Custom nonce (auto-generated if not provided) */
  nonce?: string;
}

/**
 * Options for verifying a UCAN token
 */
export interface VerifyUCANOptions {
  /** Expected audience DID */
  audience?: DID;
  /** Required capabilities */
  requiredCapabilities?: Capability[];
  /** Check proof chain (default: true) */
  checkProofs?: boolean;
  /** Current time override for testing */
  now?: number;
}

/**
 * Delegation options for creating child UCANs
 */
export interface DelegationOptions extends CreateUCANOptions {
  /** Attenuate capabilities (reduce scope) */
  attenuate?: boolean;
}

/**
 * Key storage interface for persistence
 */
export interface KeyStorage {
  /** Store a key pair */
  store(id: string, keyPair: KeyPair): Promise<void>;
  /** Retrieve a key pair */
  retrieve(id: string): Promise<KeyPair | null>;
  /** Remove a key pair */
  remove(id: string): Promise<void>;
  /** List all stored key IDs */
  list(): Promise<string[]>;
}

/**
 * Identity storage interface
 */
export interface IdentityStorage {
  /** Store an identity */
  store(identity: Identity): Promise<void>;
  /** Retrieve an identity by DID */
  retrieve(did: DID): Promise<Identity | null>;
  /** Remove an identity */
  remove(did: DID): Promise<void>;
  /** List all stored DIDs */
  list(): Promise<DID[]>;
}

/**
 * Result of capability check
 */
export interface CapabilityCheckResult {
  /** Whether the capability is granted */
  granted: boolean;
  /** Reason for denial (if not granted) */
  reason?: string;
  /** The matching capability (if granted) */
  matchedCapability?: Capability;
}

/**
 * Delegation chain verification result
 */
export interface DelegationChainResult {
  /** Whether the chain is valid */
  valid: boolean;
  /** All tokens in the chain (from root to leaf) */
  chain: UCANToken[];
  /** Error message (if invalid) */
  error?: string;
  /** The root issuer DID */
  rootIssuer?: DID;
}
