/**
 * Minimal CBOR encoder/decoder (RFC 8949)
 *
 * Handles: uint, negint, bytes, string, array, map, null, bool, float64.
 * No dependencies. ~20-30% smaller than JSON for typical structured data.
 *
 * Used across the entire Aeon ecosystem for binary wire format.
 */

export function encodeCBOR(value: unknown): Uint8Array {
  const parts: number[] = [];

  function writeUint(major: number, n: number): void {
    if (!Number.isInteger(n) || n < 0 || n > Number.MAX_SAFE_INTEGER) {
      throw new Error(`CBOR integer out of range: ${n}`);
    }

    const mt = major << 5;
    if (n < 24) { parts.push(mt | n); }
    else if (n < 0x100) { parts.push(mt | 24, n); }
    else if (n < 0x10000) { parts.push(mt | 25, (n >> 8) & 0xff, n & 0xff); }
    else if (n < 0x1_0000_0000) {
      parts.push(mt | 26, (n >> 24) & 0xff, (n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff);
    } else {
      const high = Math.floor(n / 0x1_0000_0000);
      const low = n % 0x1_0000_0000;
      parts.push(
        mt | 27,
        (high >>> 24) & 0xff,
        (high >>> 16) & 0xff,
        (high >>> 8) & 0xff,
        high & 0xff,
        (low >>> 24) & 0xff,
        (low >>> 16) & 0xff,
        (low >>> 8) & 0xff,
        low & 0xff
      );
    }
  }

  function enc(v: unknown): void {
    if (v === null || v === undefined) { parts.push(0xf6); return; }
    if (v === true) { parts.push(0xf5); return; }
    if (v === false) { parts.push(0xf4); return; }
    if (typeof v === 'number') {
      if (Number.isInteger(v) && v >= 0) { writeUint(0, v); }
      else if (Number.isInteger(v) && v < 0) { writeUint(1, -1 - v); }
      else {
        parts.push(0xfb);
        const buf = new ArrayBuffer(8);
        new DataView(buf).setFloat64(0, v, false);
        const bytes = new Uint8Array(buf);
        for (let i = 0; i < 8; i++) parts.push(bytes[i]!);
      }
      return;
    }
    if (typeof v === 'string') {
      const bytes = new TextEncoder().encode(v);
      writeUint(3, bytes.length);
      for (let i = 0; i < bytes.length; i++) parts.push(bytes[i]!);
      return;
    }
    if (v instanceof Uint8Array) {
      writeUint(2, v.length);
      for (let i = 0; i < v.length; i++) parts.push(v[i]!);
      return;
    }
    if (ArrayBuffer.isView(v)) {
      const u8 = new Uint8Array(v.buffer, v.byteOffset, v.byteLength);
      writeUint(2, u8.length);
      for (let i = 0; i < u8.length; i++) parts.push(u8[i]!);
      return;
    }
    if (Array.isArray(v)) {
      writeUint(4, v.length);
      for (const item of v) enc(item);
      return;
    }
    if (typeof v === 'object') {
      const keys = Object.keys(v as object);
      writeUint(5, keys.length);
      for (const key of keys) {
        enc(key);
        enc((v as Record<string, unknown>)[key]);
      }
      return;
    }
    enc(String(v));
  }

  enc(value);
  return new Uint8Array(parts);
}

export function decodeCBOR<T = unknown>(data: Uint8Array): T {
  let offset = 0;

  function readUint(addl: number): number {
    if (addl < 24) return addl;
    if (addl === 24) return data[offset++]!;
    if (addl === 25) { const v = (data[offset]! << 8) | data[offset + 1]!; offset += 2; return v; }
    if (addl === 26) { const v = (data[offset]! << 24) | (data[offset + 1]! << 16) | (data[offset + 2]! << 8) | data[offset + 3]!; offset += 4; return v >>> 0; }
    if (addl === 27) {
      const high =
        data[offset]! * 0x1_000000 +
        (data[offset + 1]! << 16) +
        (data[offset + 2]! << 8) +
        data[offset + 3]!;
      const low =
        data[offset + 4]! * 0x1_000000 +
        (data[offset + 5]! << 16) +
        (data[offset + 6]! << 8) +
        data[offset + 7]!;
      offset += 8;
      const value = high * 0x1_0000_0000 + low;
      if (value > Number.MAX_SAFE_INTEGER) {
        throw new Error(`CBOR integer out of range: ${value}`);
      }
      return value;
    }
    return 0;
  }

  function decode(): unknown {
    const byte = data[offset++]!;
    const major = byte >> 5;
    const addl = byte & 0x1f;

    switch (major) {
      case 0: return readUint(addl);
      case 1: return -1 - readUint(addl);
      case 2: { const len = readUint(addl); const bytes = data.slice(offset, offset + len); offset += len; return bytes; }
      case 3: { const len = readUint(addl); const str = new TextDecoder().decode(data.slice(offset, offset + len)); offset += len; return str; }
      case 4: { const len = readUint(addl); const arr: unknown[] = []; for (let i = 0; i < len; i++) arr.push(decode()); return arr; }
      case 5: { const len = readUint(addl); const obj: Record<string, unknown> = {}; for (let i = 0; i < len; i++) { const key = String(decode()); obj[key] = decode(); } return obj; }
      case 7: {
        if (addl === 20) return false;
        if (addl === 21) return true;
        if (addl === 22) return null;
        if (addl === 27) { const view = new DataView(data.buffer, data.byteOffset + offset, 8); offset += 8; return view.getFloat64(0, false); }
        return null;
      }
      default: return null;
    }
  }

  // Auto-detect: CBOR or JSON fallback
  if (data.length > 0 && data[0] !== 0x7B && data[0] !== 0x5B) {
    return decode() as T;
  }
  return JSON.parse(new TextDecoder().decode(data)) as T;
}

/**
 * Helper for WebSocket receivers: detect binary (CBOR) vs text (JSON).
 */
export function decodeWireMessage<T = unknown>(data: string | ArrayBuffer | Uint8Array): T {
  if (typeof data === 'string') {
    return JSON.parse(data) as T;
  }
  const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);
  return decodeCBOR<T>(bytes);
}

/**
 * Helper for WebSocket senders: encode as binary CBOR.
 */
export function encodeWireMessage(data: unknown): Uint8Array {
  return encodeCBOR(data);
}
