import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { resolveXRangerConfig } from './config.js';
import { auditPolicy } from './runtime/mesh-audit.js';
import type {
  DistributedTopology,
  TopologyNode,
  TopologyEdge,
} from '@a0n/cognitive-bridge';

/**
 * Discovers the local-first distributed topology of the current project.
 * Maps workers, bindings, and mesh policies to a graph structure.
 */
export async function discoverTopology(
  projectRoot: string,
  env?: string
): Promise<DistributedTopology> {
  const config = resolveXRangerConfig({ cwd: projectRoot, env });
  const nodes: TopologyNode[] = [];
  const edges: TopologyEdge[] = [];

  // 1. Root Worker Node
  const rootId = `worker:${config.name}`;
  const auditReport = config.meshPolicy
    ? auditPolicy(config.meshPolicy)
    : { findings: [] };
  const workerErrors = auditReport.findings
    .filter((f) => f.severity === 'error')
    .map((f) => `${f.code}: ${f.message}`);

  nodes.push({
    id: rootId,
    kind: 'worker',
    label: config.name,
    sigma: config.bindings.length / 10, // heuristic
    liveness: 'alive',
    errors: workerErrors,
  });

  // 2. Bindings
  for (const binding of config.bindings) {
    const bindingId = `${binding.type}:${binding.binding}`;
    nodes.push({
      id: bindingId,
      kind: binding.type as any,
      label: binding.binding,
      sigma: 0.1,
      liveness: 'alive',
      errors: [],
    });

    edges.push({
      source: rootId,
      target: bindingId,
      kind: 'binding',
    });
  }

  // 3. Mesh Topology (Ports and Overlays as virtual nodes/edges)
  if (config.meshPolicy) {
    for (const port of config.meshPolicy.ports ?? []) {
      const portId = `port:${port.path}`;
      nodes.push({
        id: portId,
        kind: 'service',
        label: port.path,
        sigma: 0.05,
        liveness: 'alive',
        errors: [],
      });
      edges.push({
        source: rootId,
        target: portId,
        kind: 'mesh-port',
      });
    }

    for (const overlay of config.meshPolicy.overlays ?? []) {
      const overlayId = `overlay:${overlay.pathPrefix}`;
      nodes.push({
        id: overlayId,
        kind: 'service',
        label: `ICE: ${overlay.pathPrefix}`,
        sigma: 0.2,
        liveness: 'dead', // Overlays "silence" parts of the strand
        errors: [],
      });
      edges.push({
        source: rootId,
        target: overlayId,
        kind: 'mesh-overlay',
      });
    }
  }

  return {
    nodes,
    edges,
    timestamp: Date.now(),
  };
}
