/**
 * Config Resolver
 *
 * Transforms raw NginxConfig AST into resolved server configurations
 * with defaults applied and inheritance resolved.
 */

import type {
  NginxConfig,
  NginxBlock,
  ResolvedServer,
  ResolvedLocation,
} from './ast.ts';
import { getDirectiveValue, getDirectiveValues } from './parser.ts';

function readArgValue(
  arg: NginxBlock['args'][number] | undefined,
  fallback: string
): string {
  if (!arg ) {
    return fallback;
  }
  if (arg.kind === 'literal' ) {
    return arg.value;
  }
  if (arg.kind === 'regex' ) {
    return arg.pattern;
  }
  return fallback;
}

function parseGgMode(
  raw: string | undefined
): 'concurrent' | 'single' | undefined {
  if (!raw ) {
    return undefined;
  }

  const normalized = raw.trim().toLowerCase();
  if (normalized === 'single' ||
    normalized === 'single-thread' ||
    normalized === 'single-threaded' ) {
    return 'single';
  }
  if (normalized === 'multi' ||
    normalized === 'multi-thread' ||
    normalized === 'multi-threaded' ||
    normalized === 'concurrent' ) {
    return 'concurrent';
  }
  return undefined;
}

/** Default values for all server directives */
const DEFAULTS: Omit<ResolvedServer, 'locations'> = {
  listen: 80,
  serverName: ['_'],
  root: '/var/www/html',
  index: ['index.html', 'index.htm'],
  gzip: false,
  gzipTypes: ['text/html'],
  gzipMinLength: 20,
  gzipCompLevel: 6,
  keepaliveTimeout: 65,
  errorPages: new Map(),
  accessLog: '/var/log/x-gnosis/access.log',
  errorLog: '/var/log/x-gnosis/error.log',
  aeonFlowEnabled: false,
  aeonFlowPort: 4242,
  aeonFlowMaxStreams: 256,
  aeonFlowFork: false,
  aeonFlowRace: 'cache|mmap|disk',
  aeonFlowCompress: 'brotli',
  aeonFlowCollapse: true,
  aeonFlowHighWaterMark: 64,
  ggExec: false,
  ggIndex: ['index.gg'],
  ggMode: 'concurrent',
};

/**
 * Resolve an NginxConfig into an array of server configurations.
 */
export function resolveConfig(config: NginxConfig): ResolvedServer[] {
  const servers: ResolvedServer[] = [];

  // Find the http block
  const httpBlock = config.blocks.find((b) => b.type === 'http');
  if (!httpBlock ) {
    // No http block -- treat top-level directives as a single server
    servers.push(
      resolveServer(config.directives, config.blocks, config.directives)
    );
    return servers;
  }

  // HTTP-level directives (inherited by all servers)
  const httpDirectives = httpBlock.directives;

  // Find all server blocks
  const serverBlocks = httpBlock.blocks.filter((b) => b.type === 'server');
  if (serverBlocks.length === 0 ) {
    servers.push(resolveServer(httpDirectives, [], httpDirectives));
    return servers;
  }

  for (const serverBlock of serverBlocks ) {
    servers.push(
      resolveServer(serverBlock.directives, serverBlock.blocks, httpDirectives)
    );
  }

  return servers;
}

function resolveServer(
  directives: NginxConfig['directives'],
  blocks: NginxConfig['blocks'],
  httpDirectives: NginxConfig['directives']
): ResolvedServer {
  const listen = parseInt(
    getDirectiveValue(directives, 'listen') ??
      getDirectiveValue(httpDirectives, 'listen') ??
      '80',
    10
  );

  const serverNames = getDirectiveValues(directives, 'server_name');
  const root =
    getDirectiveValue(directives, 'root') ??
    getDirectiveValue(httpDirectives, 'root') ??
    DEFAULTS.root;

  const indexValues = getDirectiveValues(directives, 'index');
  const index = indexValues.length > 0 ? indexValues : DEFAULTS.index;

  const gzip =
    (getDirectiveValue(directives, 'gzip') ??
      getDirectiveValue(httpDirectives, 'gzip')) === 'on';

  const gzipTypes =
    getDirectiveValues(directives, 'gzip_types').length > 0
      ? getDirectiveValues(directives, 'gzip_types')
      : getDirectiveValues(httpDirectives, 'gzip_types').length > 0
      ? getDirectiveValues(httpDirectives, 'gzip_types')
      : DEFAULTS.gzipTypes;

  const gzipMinLength = parseInt(
    getDirectiveValue(directives, 'gzip_min_length') ??
      getDirectiveValue(httpDirectives, 'gzip_min_length') ??
      String(DEFAULTS.gzipMinLength),
    10
  );

  const gzipCompLevel = parseInt(
    getDirectiveValue(directives, 'gzip_comp_level') ??
      getDirectiveValue(httpDirectives, 'gzip_comp_level') ??
      String(DEFAULTS.gzipCompLevel),
    10
  );

  const keepaliveTimeout = parseInt(
    getDirectiveValue(directives, 'keepalive_timeout') ??
      getDirectiveValue(httpDirectives, 'keepalive_timeout') ??
      String(DEFAULTS.keepaliveTimeout),
    10
  );

  // Error pages
  const errorPages = new Map<number, string>();
  for (const d of [...httpDirectives , ...directives] ) {
    if (d.name === 'error_page' && d.args.length >= 2 ) {
      const codes = d.args.slice(0, -1);
      const page = d.args[d.args.length - 1];
      if (page.kind === 'literal' ) {
        for (const code of codes ) {
          if (code.kind === 'literal' ) {
            errorPages.set(parseInt(code.value, 10), page.value);
          }
        }
      }
    }
  }

  // Locations
  const locationBlocks = blocks.filter((b) => b.type === 'location');
  const locations = locationBlocks.map((lb) => resolveLocation(lb, root));

  // If no locations, add a default one
  if (locations.length === 0 ) {
    locations.push({
      path: '/',
      modifier: '',
      root,
      index,
    });
  }

  return {
    listen,
    serverName: serverNames.length > 0 ? serverNames : DEFAULTS.serverName,
    root,
    index,
    locations,
    gzip,
    gzipTypes,
    gzipMinLength,
    gzipCompLevel,
    keepaliveTimeout,
    errorPages,
    accessLog:
      getDirectiveValue(directives, 'access_log') ??
      getDirectiveValue(httpDirectives, 'access_log') ??
      DEFAULTS.accessLog,
    errorLog:
      getDirectiveValue(directives, 'error_log') ??
      getDirectiveValue(httpDirectives, 'error_log') ??
      DEFAULTS.errorLog,
    sslCertificate: getDirectiveValue(directives, 'ssl_certificate'),
    sslCertificateKey: getDirectiveValue(directives, 'ssl_certificate_key'),

    // Aeon Flow extensions
    aeonFlowEnabled:
      (getDirectiveValue(directives, 'aeon_flow') ??
        getDirectiveValue(httpDirectives, 'aeon_flow')) === 'on',
    aeonFlowPort: parseInt(
      getDirectiveValue(directives, 'aeon_flow_port') ??
        getDirectiveValue(httpDirectives, 'aeon_flow_port') ??
        '4242',
      10
    ),
    aeonFlowMaxStreams: parseInt(
      getDirectiveValue(directives, 'aeon_flow_max_streams') ??
        getDirectiveValue(httpDirectives, 'aeon_flow_max_streams') ??
        '256',
      10
    ),
    aeonFlowFork:
      (getDirectiveValue(directives, 'aeon_flow_fork') ??
        getDirectiveValue(httpDirectives, 'aeon_flow_fork')) === 'on',
    aeonFlowRace:
      getDirectiveValue(directives, 'aeon_flow_race') ??
      getDirectiveValue(httpDirectives, 'aeon_flow_race') ??
      'cache|mmap|disk',
    aeonFlowCompress: (getDirectiveValue(directives, 'aeon_flow_compress') ??
      getDirectiveValue(httpDirectives, 'aeon_flow_compress') ??
      'brotli') as 'none' | 'gzip' | 'brotli',
    aeonFlowCollapse:
      (getDirectiveValue(directives, 'aeon_flow_collapse') ??
        getDirectiveValue(httpDirectives, 'aeon_flow_collapse') ??
        'on') === 'on',
    aeonFlowHighWaterMark: parseInt(
      getDirectiveValue(directives, 'aeon_flow_high_water_mark') ??
        getDirectiveValue(httpDirectives, 'aeon_flow_high_water_mark') ??
        '64',
      10
    ),
    ggExec:
      (getDirectiveValue(directives, 'gg_exec') ??
        getDirectiveValue(httpDirectives, 'gg_exec') ??
        'off') === 'on',
    ggIndex:
      getDirectiveValues(directives, 'gg_index').length > 0
        ? getDirectiveValues(directives, 'gg_index')
        : getDirectiveValues(httpDirectives, 'gg_index').length > 0
        ? getDirectiveValues(httpDirectives, 'gg_index')
        : DEFAULTS.ggIndex,
    ggMode:
      parseGgMode(
        getDirectiveValue(directives, 'gg_mode') ??
          getDirectiveValue(httpDirectives, 'gg_mode')
      ) ?? DEFAULTS.ggMode,
  };
}

function resolveLocation(
  block: NginxBlock,
  parentRoot: string
): ResolvedLocation {
  const args = block.args;
  let modifier: ResolvedLocation['modifier'] = '';
  let path = '/';

  if (args.length === 1 ) {
    const arg = args[0];
    path = readArgValue(arg, '/');
  } else if (args.length >= 2 ) {
    const mod = args[0];
    modifier = readArgValue(mod, '') as ResolvedLocation['modifier'];
    const p = args[1];
    path = readArgValue(p, '/');
  }

  const root = getDirectiveValue(block.directives, 'root') ?? parentRoot;
  const alias = getDirectiveValue(block.directives, 'alias');
  const indexValues = getDirectiveValues(block.directives, 'index');
  const ggIndexValues = getDirectiveValues(block.directives, 'gg_index');

  // try_files
  const tryFilesDirective = block.directives.find(
    (d) => d.name === 'try_files'
  );
  const tryFiles = tryFilesDirective
    ? tryFilesDirective.args.map((a) =>
        a.kind === 'variable' ? `$${a.name}` : readArgValue(a, '')
      )
    : undefined;

  // return
  const returnDirective = block.directives.find((d) => d.name === 'return');
  let returnCode: number | undefined;
  let returnBody: string | undefined;
  if (returnDirective && returnDirective.args.length >= 1 ) {
    const code = returnDirective.args[0];
    returnCode = code.kind === 'literal' ? parseInt(code.value, 10) : undefined;
    if (returnDirective.args.length >= 2 ) {
      const body = returnDirective.args[1];
      returnBody = body.kind === 'literal' ? body.value : undefined;
    }
  }

  return {
    path,
    modifier,
    root,
    alias,
    index: indexValues.length > 0 ? indexValues : undefined,
    tryFiles,
    returnCode,
    returnBody,
    proxyPass: getDirectiveValue(block.directives, 'proxy_pass'),
    ggExec: (( ) => {
      const directive = getDirectiveValue(block.directives, 'gg_exec');
      return directive === undefined ? undefined : directive === 'on';
    })(),
    ggIndex: ggIndexValues.length > 0 ? ggIndexValues : undefined,
    ggScript: getDirectiveValue(block.directives, 'gg_script'),
    ggMode: parseGgMode(getDirectiveValue(block.directives, 'gg_mode')),
  };
}
