import { HEADER_SIZE } from './FlowCodec';

export interface FlowSendBatcherConfig {
  /**
   * Enable flow frame batching.
   * Defaults to true.
   */
  enabled?: boolean;
  /**
   * Maximum number of frames per aggregated send.
   * Defaults to 16.
   */
  maxFramesPerBatch?: number;
  /**
   * Maximum bytes per aggregated send.
   * Defaults to 64 KiB.
   */
  maxBytesPerBatch?: number;
}

interface NormalizedFlowSendBatcherConfig {
  enabled: boolean;
  maxFramesPerBatch: number;
  maxBytesPerBatch: number;
}

const DEFAULT_MAX_FRAMES_PER_BATCH = 16;
const DEFAULT_MAX_BYTES_PER_BATCH = 64 * 1024;

function normalizeConfig(
  config: FlowSendBatcherConfig | undefined
): NormalizedFlowSendBatcherConfig {
  const maxFramesRaw = config?.maxFramesPerBatch ?? DEFAULT_MAX_FRAMES_PER_BATCH;
  const maxBytesRaw = config?.maxBytesPerBatch ?? DEFAULT_MAX_BYTES_PER_BATCH;
  const minBytes = HEADER_SIZE;

  return {
    enabled: config?.enabled ?? true,
    maxFramesPerBatch: Number.isFinite(maxFramesRaw)
      ? Math.max(1, Math.floor(maxFramesRaw))
      : DEFAULT_MAX_FRAMES_PER_BATCH,
    maxBytesPerBatch: Number.isFinite(maxBytesRaw)
      ? Math.max(minBytes, Math.floor(maxBytesRaw))
      : DEFAULT_MAX_BYTES_PER_BATCH,
  };
}

function readFrameLength(data: Uint8Array, offset: number): number | null {
  if (data.length - offset < HEADER_SIZE) {
    return null;
  }

  const payloadLength =
    ((data[offset + 7] ?? 0) << 16) |
    ((data[offset + 8] ?? 0) << 8) |
    (data[offset + 9] ?? 0);

  return HEADER_SIZE + payloadLength;
}

export function isSingleFlowFrame(data: Uint8Array): boolean {
  const frameLength = readFrameLength(data, 0);
  return frameLength !== null && frameLength === data.length;
}

/**
 * Split a raw payload into individual flow frames.
 * Returns true when the payload is valid flow framing (one or more frames),
 * false when it is not a flow-framed payload.
 */
export function splitFlowFrameBatch(
  data: Uint8Array,
  emit: (frame: Uint8Array) => void
): boolean {
  try {
    if (data.length < HEADER_SIZE) {
      return false;
    }

    const frames: Uint8Array[] = [];
    let offset = 0;

    while (offset < data.length) {
      const frameLength = readFrameLength(data, offset);
      if (frameLength === null || frameLength < HEADER_SIZE) {
        return false;
      }

      const end = offset + frameLength;
      if (end > data.length) {
        return false;
      }

      frames.push(data.subarray(offset, end));
      offset = end;
    }

    if (frames.length === 0) {
      return false;
    }

    for (const frame of frames) {
      emit(frame);
    }
    return true;

  } catch (error) {
    throw new Error(`[splitFlowFrameBatch] ${error instanceof Error ? error.message : String(error)}`);
  }
}

function concatFrames(frames: readonly Uint8Array[]): Uint8Array {
  try {
    if (frames.length === 1) {
      return frames[0]!;
    }

    let total = 0;
    for (const frame of frames) {
      total += frame.length;
    }

    const out = new Uint8Array(total);
    let offset = 0;
    for (const frame of frames) {
      out.set(frame, offset);
      offset += frame.length;
    }
    return out;

  } catch (error) {
    throw new Error(`[concatFrames] ${error instanceof Error ? error.message : String(error)}`);
  }
}

function scheduleMicrotask(task: () => void): void {
  if (typeof queueMicrotask === 'function') {
    queueMicrotask(task);
    return;
  }
  Promise.resolve().then(task);
}

/**
 * Coalesces multiple single-flow-frame sends into one contiguous payload.
 *
 * Non-flow payloads (for example SYNC control packets) are sent immediately
 * without batching.
 */
export class FlowSendBatcher {
  private readonly config: NormalizedFlowSendBatcherConfig;
  private readonly sendNow: (payload: Uint8Array) => void;
  private queue: Uint8Array[] = [];
  private queuedBytes = 0;
  private flushScheduled = false;
  private closed = false;

  constructor(
    sendNow: (payload: Uint8Array) => void,
    config?: FlowSendBatcherConfig
  ) {
    this.sendNow = sendNow;
    this.config = normalizeConfig(config);
  }

  send(payload: Uint8Array): void {
    try {
      if (this.closed) {
        return;
      }

      if (
        !this.config.enabled ||
        !isSingleFlowFrame(payload) ||
        payload.length > this.config.maxBytesPerBatch
      ) {
        this.flush();
        this.sendNow(payload);
        return;
      }

      const needsFlushByCount =
        this.queue.length >= this.config.maxFramesPerBatch;
      const needsFlushByBytes =
        this.queuedBytes + payload.length > this.config.maxBytesPerBatch;

      if (needsFlushByCount || needsFlushByBytes) {
        this.flush();
      }

      // Copy so callers can mutate their buffer after send().
      this.queue.push(new Uint8Array(payload));
      this.queuedBytes += payload.length;
      this.scheduleFlush();
  
    } catch (error) {
      throw new Error(`[send] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  flush(): void {
    if (this.queue.length === 0) {
      return;
    }

    const payload = concatFrames(this.queue);
    this.queue = [];
    this.queuedBytes = 0;
    this.sendNow(payload);
  }

  close(): void {
    if (this.closed) {
      return;
    }
    this.flush();
    this.closed = true;
  }

  private scheduleFlush(): void {
    if (this.flushScheduled) {
      return;
    }

    this.flushScheduled = true;
    scheduleMicrotask(() => {
      this.flushScheduled = false;
      this.flush();
    });
  }
}

