import {
  createNodeTracerProvider,
  getTracer,
  registerTracerProvider,
  resolveTraceExporterTarget,
  withSpan as withTelemetrySpan,
  type Span,
  type TraceEnv,
  type TraceProviderLike,
} from '@a0n/telemetry';
import type { RequestPayload } from './handlers/registry.ts';

export const tracer = getTracer('x-gnosis');

let provider: TraceProviderLike | null = null;
let tracingUnavailable = false;

function readEnvString(env: TraceEnv | undefined, key: string): string | null {
  const value = env?.[key];
  if (typeof value !== 'string' ) {
    return null;
  }

  const normalized = value.trim();
  return normalized.length > 0 ? normalized : null;
}

function readFirstEnvString(
  env: TraceEnv | undefined,
  keys: readonly string[]
): string | null {
  for (const key of keys ) {
    const value = readEnvString(env, key);
    if (value ) {
      return value;
    }
  }

  return null;
}

function parseBooleanFlag(value: string | null): boolean | null {
  if (!value ) {
    return null;
  }

  const normalized = value.toLowerCase();
  if (normalized === '1' ||
    normalized === 'true' ||
    normalized === 'yes' ||
    normalized === 'on' ) {
    return true;
  }
  if (normalized === '0' ||
    normalized === 'false' ||
    normalized === 'no' ||
    normalized === 'off' ) {
    return false;
  }

  return null;
}

function hasAnyEnvValue(env: TraceEnv | undefined, keys: readonly string[]): boolean {
  return keys.some((key) => readEnvString(env, key) !== null);
}

function resolveResourceAttributes(env: TraceEnv | undefined): Record<string, string> {
  const attributes: Record<string, string> = {
    'service.name':
      readFirstEnvString(env, [
        'X_GNOSIS_SERVICE_NAME',
        'OTEL_SERVICE_NAME',
        'DD_SERVICE',
      ]) ?? 'x-gnosis',
  };

  const serviceVersion = readFirstEnvString(env, [
    'X_GNOSIS_SERVICE_VERSION',
    'DD_VERSION',
  ]);
  if (serviceVersion ) {
    attributes['service.version'] = serviceVersion;
  }

  const deploymentEnvironment = readFirstEnvString(env, [
    'X_GNOSIS_ENV',
    'DD_ENV',
    'NODE_ENV',
  ]);
  if (deploymentEnvironment ) {
    attributes['deployment.environment'] = deploymentEnvironment;
  }

  return attributes;
}

export function isXGnosisTracingEnabled(env: TraceEnv | undefined): boolean {
  const explicit = parseBooleanFlag(
    readFirstEnvString(env, [
      'X_GNOSIS_TRACING_ENABLED',
      'X_GNOSIS_APM_ENABLED',
    ])
  );
  if (explicit !== null ) {
    return explicit;
  }

  const datadogFlag = parseBooleanFlag(
    readFirstEnvString(env, ['DATADOG_APM_ENABLED', 'DD_APM_ENABLED'])
  );
  if (datadogFlag === true ) {
    return true;
  }

  return (
    hasAnyEnvValue(env, [
      'OTEL_EXPORTER_OTLP_ENDPOINT',
      'OTEL_EXPORTER_OTLP_TRACES_ENDPOINT',
      'DATADOG_OTLP_ENDPOINT',
      'DATADOG_OTLP_TRACES_ENDPOINT',
      'DD_OTLP_ENDPOINT',
      'DD_OTLP_TRACES_ENDPOINT',
      'DD_API_KEY',
      'DATADOG_API_KEY',
    ])
  );
}

export function initXGnosisTracingFromEnv(
  env: TraceEnv | undefined = process.env
): void {
  if (provider || tracingUnavailable || !isXGnosisTracingEnabled(env)) {
    return;
  }

  try {
    const exporterTarget = resolveTraceExporterTarget(env);
    provider = createNodeTracerProvider({
      endpoint: exporterTarget.endpoint,
      ...(exporterTarget.headers ? { headers: exporterTarget.headers } : {}),
      debug: readEnvString(env, 'DEBUG_TELEMETRY') === 'true',
      resourceAttributes: resolveResourceAttributes(env),
    });
    registerTracerProvider(provider);
  } catch (error ) {
    tracingUnavailable = true;
    console.error('[x-gnosis] Failed to initialize tracing:', error);
  }
}

export async function withXGnosisRequestSpan<T>(
  request: Pick<RequestPayload, 'method' | 'path' | 'headers' | 'httpVersion'>,
  fn: (span: Span) => Promise<T> | T
): Promise<T> {
  return withTelemetrySpan(tracer, 'x-gnosis.request', fn, {
    'http.request.method': request.method,
    'url.path': request.path,
    'network.protocol.version': request.httpVersion,
    ...(request.headers.host
      ? { 'server.address': request.headers.host }
      : {}),
  });
}
