/**
 * @a0n/zk-encryption - ECIES-P256 Implementation
 *
 * Elliptic Curve Integrated Encryption Scheme using P-256/AES-256-GCM
 */

import type {
  EncryptedPayload,
  HybridEncryptedPayload,
  EncryptionOptions,
  DecryptionResult,
  ECKeyPair,
} from './zkTypes.js';
import {
  generateKeyPair,
  importPublicKey,
  importPrivateKey,
  deriveSharedSecret,
  deriveAESKey,
  generateNonce,
} from './keys.js';
import { base64UrlEncode, base64UrlDecode } from './utils.js';

/**
 * Encrypt data using ECIES-P256
 *
 * Uses ephemeral key pair for forward secrecy:
 * 1. Generate ephemeral ECDH key pair
 * 2. Derive shared secret with recipient's public key
 * 3. Derive AES key using HKDF
 * 4. Encrypt with AES-256-GCM
 *
 * @param plaintext - Data to encrypt
 * @param recipientPublicKey - Recipient's public key (JWK)
 * @param options - Encryption options
 * @returns Encrypted payload with ephemeral public key
 *
 * @example
 * ```typescript
 * const encrypted = await eciesEncrypt(
 *   new TextEncoder().encode('Hello'),
 *   recipientPublicKey,
 *   { category: 'message' },
 * );
 * ```
 */
export async function eciesEncrypt(
  plaintext: Uint8Array,
  recipientPublicKey: JsonWebKey,
  options?: EncryptionOptions
): Promise<EncryptedPayload> {
  const { category = 'default', aad } = options || {};

  // Generate ephemeral key pair for forward secrecy
  const ephemeralKeyPair = await generateKeyPair();

  // Import keys
  const ephemeralPrivate = await importPrivateKey(ephemeralKeyPair.privateKey);
  const recipientPublic = await importPublicKey(recipientPublicKey);

  // Derive shared secret via ECDH
  const sharedSecret = await deriveSharedSecret(
    ephemeralPrivate,
    recipientPublic
  );

  // Derive AES key using HKDF
  const aesKey = await deriveAESKey(sharedSecret, category);

  // Generate IV
  const iv = generateNonce(12);

  // Build encryption parameters
  const params: {
    name: string;
    iv: BufferSource;
    tagLength: number;
    additionalData?: BufferSource;
  } = {
    name: 'AES-GCM',
    iv: iv as unknown as BufferSource,
    tagLength: 128,
  };

  if (aad) {
    params.additionalData = aad as unknown as BufferSource;
  }

  // Encrypt
  const ciphertext = await crypto.subtle.encrypt(
    params as AlgorithmIdentifier,
    aesKey,
    plaintext as unknown as BufferSource
  );
  const ctArray = new Uint8Array(ciphertext);

  // Extract ciphertext and auth tag
  const ct = ctArray.slice(0, -16);
  const tag = ctArray.slice(-16);

  // Generate nonce for replay protection
  const nonce = options?.nonce || generateNonceString();

  return {
    alg: 'ECIES-P256',
    epk: ephemeralKeyPair.publicKey, // Include ephemeral public key
    ct: base64UrlEncode(ct),
    iv: base64UrlEncode(iv),
    tag: base64UrlEncode(tag),
    category,
    nonce,
    encryptedAt: Date.now(),
  };
}

/**
 * Decrypt ECIES-P256 encrypted data
 *
 * @param encrypted - Encrypted payload
 * @param recipientPrivateKey - Recipient's private key (JWK)
 * @param aad - Additional authenticated data (must match encryption)
 * @returns Decryption result
 *
 * @example
 * ```typescript
 * const result = await eciesDecrypt(encrypted, myPrivateKey);
 * console.log(new TextDecoder('utf-8', { fatal: true }).decode(result.plaintext));
 * ```
 */
export async function eciesDecrypt(
  encrypted: EncryptedPayload,
  recipientPrivateKey: JsonWebKey,
  aad?: Uint8Array
): Promise<DecryptionResult> {
  if (!encrypted.epk) {
    throw new Error('Missing ephemeral public key (epk) in encrypted payload');
  }

  const category = encrypted.category || 'default';

  // Import keys
  const recipientPrivate = await importPrivateKey(recipientPrivateKey);
  const ephemeralPublic = await importPublicKey(encrypted.epk);

  // Derive shared secret via ECDH
  const sharedSecret = await deriveSharedSecret(
    recipientPrivate,
    ephemeralPublic
  );

  // Derive AES key using HKDF (same parameters as encryption)
  const aesKey = await deriveAESKey(sharedSecret, category);

  // Decode components
  const ct = base64UrlDecode(encrypted.ct);
  const iv = base64UrlDecode(encrypted.iv);
  const tag = base64UrlDecode(encrypted.tag);

  // Reconstruct ciphertext with tag appended
  const ciphertext = new Uint8Array(ct.length + tag.length);
  ciphertext.set(ct, 0);
  ciphertext.set(tag, ct.length);

  // Build decryption parameters
  const params: {
    name: string;
    iv: BufferSource;
    tagLength: number;
    additionalData?: BufferSource;
  } = {
    name: 'AES-GCM',
    iv: iv as unknown as BufferSource,
    tagLength: 128,
  };

  if (aad) {
    params.additionalData = aad as unknown as BufferSource;
  }

  // Decrypt
  const plaintext = await crypto.subtle.decrypt(
    params as AlgorithmIdentifier,
    aesKey,
    ciphertext as unknown as BufferSource
  );

  return {
    plaintext: new Uint8Array(plaintext),
    category: encrypted.category,
    encryptedAt: encrypted.encryptedAt,
  };
}

/**
 * Encrypt a string using ECIES-P256
 *
 * @param text - String to encrypt
 * @param recipientPublicKey - Recipient's public key
 * @param options - Encryption options
 * @returns Encrypted payload
 */
export async function eciesEncryptString(
  text: string,
  recipientPublicKey: JsonWebKey,
  options?: EncryptionOptions
): Promise<EncryptedPayload> {
  const plaintext = new TextEncoder().encode(text);
  return eciesEncrypt(plaintext, recipientPublicKey, options);
}

/**
 * Decrypt to a string using ECIES-P256
 *
 * @param encrypted - Encrypted payload
 * @param recipientPrivateKey - Recipient's private key
 * @param aad - Additional authenticated data
 * @returns Decrypted string
 */
export async function eciesDecryptString(
  payload: EncryptedPayload,
  recipientPrivateKey: JsonWebKey,
  _aad?: Uint8Array
): Promise<string> {
  const result = await eciesDecrypt(payload, recipientPrivateKey, _aad);
  return new TextDecoder('utf-8', { fatal: true }).decode(result.plaintext);
}

/**
 * Hybrid encryption - Both sender and recipient can decrypt
 *
 * Encrypts data so that:
 * 1. Recipient can decrypt with their private key
 * 2. Sender can decrypt with their private key (useful for sent items)
 *
 * @param plaintext - Data to encrypt
 * @param senderKeyPair - Sender's key pair
 * @param recipientPublicKey - Recipient's public key
 * @param options - Encryption options
 * @returns Hybrid encrypted payload
 */
export async function eciesHybridEncrypt(
  plaintext: Uint8Array,
  senderKeyPair: ECKeyPair,
  recipientPublicKey: JsonWebKey,
  options?: EncryptionOptions
): Promise<HybridEncryptedPayload> {
  const { category = 'default' } = options || {};

  // Encrypt for recipient
  const recipientEncrypted = await eciesEncrypt(
    plaintext,
    recipientPublicKey,
    options
  );

  // Also encrypt for sender (so they can decrypt their sent messages)
  const senderEncrypted = await eciesEncrypt(
    plaintext,
    senderKeyPair.publicKey,
    {
      ...options,
      category: `${category}-sender`,
    }
  );

  return {
    ...recipientEncrypted,
    senderEpk: senderEncrypted.epk!,
    senderCt: senderEncrypted.ct,
    senderIv: senderEncrypted.iv,
    senderTag: senderEncrypted.tag,
  };
}

/**
 * Decrypt hybrid encrypted data (as recipient)
 *
 * @param encrypted - Hybrid encrypted payload
 * @param recipientPrivateKey - Recipient's private key
 * @param aad - Additional authenticated data
 * @returns Decryption result
 */
export async function eciesHybridDecryptAsRecipient(
  encrypted: HybridEncryptedPayload,
  recipientPrivateKey: JsonWebKey,
  aad?: Uint8Array
): Promise<DecryptionResult> {
  // Decrypt using recipient's portion
  return eciesDecrypt(encrypted, recipientPrivateKey, aad);
}

/**
 * Decrypt hybrid encrypted data (as sender)
 *
 * @param encrypted - Hybrid encrypted payload
 * @param senderPrivateKey - Sender's private key
 * @param aad - Additional authenticated data
 * @returns Decryption result
 */
export async function eciesHybridDecryptAsSender(
  encrypted: HybridEncryptedPayload,
  senderPrivateKey: JsonWebKey,
  aad?: Uint8Array
): Promise<DecryptionResult> {
  // Build sender-specific payload
  const senderPayload: EncryptedPayload = {
    alg: encrypted.alg,
    epk: encrypted.senderEpk,
    ct: encrypted.senderCt,
    iv: encrypted.senderIv,
    tag: encrypted.senderTag,
    category: encrypted.category
      ? `${encrypted.category}-sender`
      : 'default-sender',
    nonce: encrypted.nonce,
    encryptedAt: encrypted.encryptedAt,
  };

  return eciesDecrypt(senderPayload, senderPrivateKey, aad);
}

/**
 * Verify encrypted payload structure
 *
 * @param data - Data to verify
 * @returns True if valid ECIES encrypted payload
 */
export function isValidECIESPayload(data: unknown): data is EncryptedPayload {
  if (!data || typeof data !== 'object') return false;
  const d = data as unknown as Record<string, unknown>;

  if (d.alg !== 'ECIES-P256') return false;
  if (!d.epk || typeof d.epk !== 'object') return false;
  if (typeof d.ct !== 'string' || d.ct.length === 0) return false;
  if (typeof d.iv !== 'string' || d.iv.length === 0) return false;
  if (typeof d.tag !== 'string' || d.tag.length === 0) return false;
  if (typeof d.encryptedAt !== 'number') return false;

  return true;
}

/**
 * Check if payload is hybrid encrypted
 *
 * @param data - Encrypted payload
 * @returns True if hybrid encrypted
 */
export function isHybridEncrypted(
  data: EncryptedPayload
): data is HybridEncryptedPayload {
  const d = data as unknown as Record<string, unknown>;
  return !!(d.senderEpk && d.senderCt && d.senderIv && d.senderTag);
}

/**
 * Generate a random nonce string
 */
function generateNonceString(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}
