export type MeshDimension = 8 | 16 | 32 | 55;

export interface RevSignals {
  uncertainty: number;
  complexity: number;
  novelty: number;
  budgetSlack?: number;
}

export interface MeshBranchOutput {
  value: number[];
  confidence?: number;
}

export interface MeshBranchContext {
  rev: number;
  input: number[];
}

export interface MeshBranch {
  readonly dim: MeshDimension;
  readonly estimatedCost: number;
  run(context: MeshBranchContext): MeshBranchOutput;
}

export interface ProgressiveMeshConfig {
  add32At: number;
  add55At: number;
  computePenalty: number;
  signalWeights: {
    uncertainty: number;
    complexity: number;
    novelty: number;
    budgetSlack: number;
  };
}

export interface ProgressiveMeshResult {
  value: number[];
  rev: number;
  activeDimensions: MeshDimension[];
  weights: Record<MeshDimension, number>;
  branchConfidence: Record<MeshDimension, number>;
}

/** Default thresholds and weights (mirrors `DEFAULT_CONFIG` in this module). */
export const DEFAULT_PROGRESSIVE_MESH_CONFIG: ProgressiveMeshConfig = {
  add32At: 0.45,
  add55At: 0.72,
  computePenalty: 0.15,
  signalWeights: {
    uncertainty: 0.4,
    complexity: 0.3,
    novelty: 0.2,
    budgetSlack: 0.1,
  },
};

const DEFAULT_CONFIG = DEFAULT_PROGRESSIVE_MESH_CONFIG;

/**
 * Unit clamp for finite reals; non-finite inputs map to `0` (JS runtime guard).
 * Named for alignment with `ForkRaceFoldTheorems.meshClamp01` (finite branch).
 */
export function meshClamp01(value: number): number {
  if (!Number.isFinite(value)) {
    return 0;
  }
  return Math.max(0, Math.min(1, value));
}

/**
 * Convex combination of clamped scalar signals — matches Lean `meshComputeRev`
 * when weights are nonnegative and sum to 1.
 */
export function computeMeshRev(signals: RevSignals, weights: ProgressiveMeshConfig['signalWeights']): number {
  const rev =
    weights.uncertainty * meshClamp01(signals.uncertainty) +
    weights.complexity * meshClamp01(signals.complexity) +
    weights.novelty * meshClamp01(signals.novelty) +
    weights.budgetSlack * meshClamp01(signals.budgetSlack ?? 0.5);
  return meshClamp01(rev);
}

/**
 * Threshold-gated activation list — matches Lean `meshChooseActiveDimensions`
 * given optional branches `32` / `55` present in `availableDims`.
 */
export function chooseActiveMeshDimensions(
  rev: number,
  config: ProgressiveMeshConfig,
  availableDims: ReadonlySet<MeshDimension>
): MeshDimension[] {
  const active: MeshDimension[] = [8, 16];

  if (rev >= config.add32At && availableDims.has(32)) {
    active.push(32);
  }

  if (rev >= config.add55At && availableDims.has(55)) {
    active.push(55);
  }

  return active;
}

/**
 * Rev-dependent capacity prior per branch — factor in `infer` logits before softmax.
 */
export function meshCapacityPrior(dim: MeshDimension, rev: number): number {
  const r = meshClamp01(rev);
  if (dim === 8) {
    return (1 - r) * 1;
  }
  if (dim === 16) {
    return (1 - r) * 0.8 + r * 0.2;
  }
  if (dim === 32) {
    return r * 0.7;
  }
  return r;
}

/**
 * Scalar logit fragment aligned with Lean `meshOrchestratorBranchLogit`:
 * `prior + confidence - penalty * normalizedCost`.
 */
export function meshOrchestratorBranchLogit(
  prior: number,
  confidence: number,
  computePenalty: number,
  normalizedCost: number
): number {
  return prior + confidence - computePenalty * normalizedCost;
}

/** Numerically stabilized softmax; empty in ⇒ empty out. */
export function meshSoftmax(logits: number[]): number[] {
  if (logits.length === 0) {
    return [];
  }

  const maxLogit = Math.max(...logits);
  const exps = logits.map((logit) => Math.exp(logit - maxLogit));
  const total = exps.reduce((sum, value) => sum + value, 0);

  if (total <= 0) {
    return logits.map(() => 1 / logits.length);
  }

  return exps.map((value) => value / total);
}

/** Convex combination of same-length vectors. */
export function meshWeightedBlend(vectors: number[][], weights: number[]): number[] {
  if (vectors.length === 0) {
    return [];
  }

  const out = new Array<number>(vectors[0]!.length).fill(0);

  for (let i = 0; i < vectors.length; i += 1) {
    const vector = vectors[i]!;
    const weight = weights[i] ?? 0;
    for (let j = 0; j < out.length; j += 1) {
      out[j] += (vector[j] ?? 0) * weight;
    }
  }

  return out;
}

/**
 * Progressive multi-octave mesh orchestrator.
 *
 * Lower dimensions are always active. Higher dimensions spin up as rev rises,
 * where rev is derived from uncertainty/complexity/novelty/budget signals.
 */
export class ProgressiveMeshOrchestrator {
  private readonly config: ProgressiveMeshConfig;
  private readonly branches: Map<MeshDimension, MeshBranch>;

  constructor(branches: MeshBranch[], config?: Partial<ProgressiveMeshConfig>) {
    this.config = {
      ...DEFAULT_CONFIG,
      ...config,
      signalWeights: {
        ...DEFAULT_CONFIG.signalWeights,
        ...(config?.signalWeights ?? {}),
      },
    };

    this.branches = new Map(branches.map((branch) => [branch.dim, branch]));

    for (const dim of [8, 16] as const) {
      if (!this.branches.has(dim)) {
        throw new Error(`Missing required base branch ${dim}D`);
      }
    }
  }

  computeRev(signals: RevSignals): number {
    return computeMeshRev(signals, this.config.signalWeights);
  }

  chooseActiveDimensions(rev: number): MeshDimension[] {
    return chooseActiveMeshDimensions(rev, this.config, new Set(this.branches.keys()));
  }

  infer(input: number[], signals: RevSignals): ProgressiveMeshResult {
    const rev = this.computeRev(signals);
    const activeDimensions = this.chooseActiveDimensions(rev);

    const outputs: MeshBranchOutput[] = [];
    const confidences = {} as Record<MeshDimension, number>;
    const costs = {} as Record<MeshDimension, number>;

    for (const dim of activeDimensions) {
      const branch = this.branches.get(dim);
      if (!branch) {
        continue;
      }
      const output = branch.run({ rev, input });
      outputs.push(output);
      confidences[dim] = meshClamp01(output.confidence ?? 0.5);
      costs[dim] = Math.max(0, branch.estimatedCost);
    }

    const logits = activeDimensions.map((dim) => {
      const confidence = confidences[dim] ?? 0.5;
      const normalizedCost = meshClamp01((costs[dim] ?? 0) / 100);
      const capacityPrior = meshCapacityPrior(dim, rev);

      return meshOrchestratorBranchLogit(
        capacityPrior,
        confidence,
        this.config.computePenalty,
        normalizedCost
      );
    });

    const softmaxWeights = meshSoftmax(logits);
    const weights = {} as Record<MeshDimension, number>;

    for (let i = 0; i < activeDimensions.length; i += 1) {
      const dim = activeDimensions[i]!;
      weights[dim] = softmaxWeights[i] ?? 0;
    }

    const value = meshWeightedBlend(
      outputs.map((output) => output.value),
      softmaxWeights
    );

    return {
      value,
      rev,
      activeDimensions,
      weights,
      branchConfidence: confidences,
    };
  }
}
