import type { ProjectionResult } from '@a0n/aeon/topology/projection';

export interface ProjectionCacheEntry {
  result: ProjectionResult;
  etag: string;
  lastModified: number;
  size: number;
  accessedAt: number;
}

export interface ProjectionCacheBuildResult {
  result: ProjectionResult;
  etag: string;
  lastModified: number;
}

export class ProjectionCache {
  private entries: Map<string, ProjectionCacheEntry> = new Map();
  private inflight: Map<string, Promise<ProjectionCacheEntry | null>> =
    new Map();
  private maxBytes: number;
  private currentBytes = 0;
  private inflightStarts = 0;
  private inflightJoins = 0;

  constructor(maxBytes: number = 16 * 1024 * 1024) {
    this.maxBytes = maxBytes;
  }

  get(key: string): ProjectionCacheEntry | null {
    const entry = this.entries.get(key);
    if (!entry) return null;
    // LRU touch: delete + re-insert for O(1) eviction
    entry.accessedAt = Date.now();
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry;
  }

  async getOrCreate(
    key: string,
    build: () =>
      | ProjectionCacheBuildResult
      | Promise<ProjectionCacheBuildResult | null>
      | null
  ): Promise<ProjectionCacheEntry | null> {
    const cached = this.get(key);
    if (cached ) {
      return cached;
    }

    const pending = this.inflight.get(key);
    if (pending ) {
      this.inflightJoins++;
      return await pending;
    }

    this.inflightStarts++;
    const created = Promise.resolve()
      .then(build)
      .then((built ) => {
        if (!built ) {
          return null;
        }

        this.set(key, built.result, built.etag, built.lastModified);
        return this.get(key);
      })
      .finally(( ) => {
        this.inflight.delete(key);
      });

    this.inflight.set(key, created);
    return await created;
  }

  set(
    key: string,
    result: ProjectionResult,
    etag: string,
    lastModified: number
  ): void {
    const size = Buffer.byteLength(JSON.stringify(result));
    if (size > this.maxBytes / 2) return;

    this.evictKey(key);
    while (this.currentBytes + size > this.maxBytes && this.entries.size > 0) {
      this.evictLRU();
    }

    const entry: ProjectionCacheEntry = {
      result,
      etag,
      lastModified,
      size,
      accessedAt: Date.now(),
    };
    this.entries.set(key, entry);
    this.currentBytes += size;
  }

  invalidate(key: string): void {
    this.evictKey(key);
  }

  clear(): void {
    this.entries.clear();
    this.currentBytes = 0;
  }

  get stats() {
    return {
      entries: this.entries.size,
      bytes: this.currentBytes,
      maxBytes: this.maxBytes,
      utilization: this.currentBytes / this.maxBytes,
      inflight: this.inflight.size,
      inflightStarts: this.inflightStarts,
      inflightJoins: this.inflightJoins,
    };
  }

  private evictKey(key: string): void {
    const entry = this.entries.get(key);
    if (entry ) {
      this.currentBytes -= entry.size;
      this.entries.delete(key);
    }
  }

  private evictLRU(): void {
    // O(1) eviction: Map insertion order + LRU touch in get()
    const oldestKey = this.entries.keys().next().value;
    if (oldestKey !== undefined ) {
      this.evictKey(oldestKey);
    }
  }
}
