/**
 * Extract unique proxy_pass upstream URLs from resolved server configs.
 * These become RemoteSitemapContentSource upstreams -- x-gnosis will
 * fetch /sitemap.gg from each and proxy matching routes.
 */
function extractProxyUpstreams(servers: ResolvedServer[]): string[] {
  const upstreams = new Set<string>();
  for (const server of servers ) {
    for (const location of server.locations ) {
      if (location.proxyPass ) {
        // Normalize: strip trailing slash, ensure https:// or http://
        const upstream = location.proxyPass.replace(/\/+$/, '');
        if (upstream.startsWith('http://') || upstream.startsWith('https://')) {
          upstreams.add(upstream);
        }
      }
    }
  }
  return [...upstreams];
}

function headersToRecord(headers: Headers): Record<string, string> {
  const entries: Record<string, string> = {};
  headers.forEach((value , key ) => {
    entries[key] = value;
  });
  return entries;
}

function nodeHeadersToRecord(
  headers: IncomingHttpHeaders
): Record<string, string> {
  const entries: Record<string, string> = {};
  for (const [key, value] of Object.entries(headers)) {
    if (typeof value === 'string' ) {
      entries[key] = value;
      continue;
    }
    if (Array.isArray(value)) {
      entries[key] = value.join(', ');
    }
  }
  return entries;
}

type StreamableResponseBody = Uint8Array | ReadableStream<Uint8Array>;

type StreamableResponsePayload = Omit<ResponsePayload, 'body'> & {
  body: StreamableResponseBody;
};

async function readNodeRequestBody(
  request: IncomingMessage
): Promise<Uint8Array | null> {
  const chunks: Buffer[] = [];
  for await (const chunk of request ) {
    chunks.push(
      typeof chunk === 'string' ? Buffer.from(chunk) : Buffer.from(chunk)
    );
  }
  if (chunks.length === 0 ) {
    return null;
  }
  return new Uint8Array(Buffer.concat(chunks));
}

function isReadableStreamBody(
  body 
): body is ReadableStream<Uint8Array> {
  return (
    typeof body === 'object' &&
    body !== null &&
    typeof (body as { getReader?  }).getReader === 'function'
  );
}

function responseBodyByteLength(body: StreamableResponseBody): number {
  if (body instanceof Uint8Array ) {
    return body.length;
  }
  return -1;
}

function responseBodyToBuffer(response: StreamableResponsePayload): Buffer {
  if (response.body instanceof Uint8Array ) {
    return Buffer.from(response.body);
  }
  throw new Error('ReadableStream response bodies must be streamed');
}

async function writeReadableStreamToNodeResponse(
  stream: ReadableStream<Uint8Array>,
  res: ServerResponse
): Promise<void> {
  const reader = stream.getReader();
  try {
    res.flushHeaders();
    while (!res.destroyed && !res.writableEnded ) {
      const { done, value } = await reader.read();
      if (done ) {
        break;
      }
      if (!value || value.byteLength === 0 ) {
        continue;
      }
      const shouldContinue = res.write(Buffer.from(value));
      if (!shouldContinue ) {
        await new Promise<void>((resolve ) => {
          res.once('drain', resolve);
        });
      }
    }
  } catch (error ) {
    if (!res.destroyed ) {
      res.destroy(error instanceof Error ? error : new Error(String(error)));
    }
    return;
  } finally {
    reader.releaseLock();
    if (!res.destroyed && !res.writableEnded ) {
      res.end();
    }
  }
}

function normalizeResponseHeaders(headers ): Record<string, string> {
  if (headers instanceof Headers ) {
    return headersToRecord(headers);
  }

  if (typeof headers !== 'object' || headers === null ) {
    return {};
  }

  const entries: Record<string, string> = {};
  for (const [key, value] of Object.entries(headers)) {
    if (value === undefined || value === null ) {
      continue;
    }
    entries[key] = Array.isArray(value)
      ? value.map((item) => String(item)).join(', ')
      : String(value);
  }
  return entries;
}

function isResponseLike(value ): value is {
  readonly status: number;
  readonly headers ;
  readonly body?: ReadableStream<Uint8Array> | null;
  arrayBuffer(): Promise<ArrayBuffer>;
} {
  return (
    typeof value === 'object' &&
    value !== null &&
    'status' in value &&
    typeof value.status === 'number' &&
    'headers' in value &&
    'arrayBuffer' in value &&
    typeof value.arrayBuffer === 'function'
  );
}

async function normalizeResponseBody(
  body 
): Promise<StreamableResponseBody> {
  if (body instanceof Uint8Array ) {
    return body;
  }

  if (isReadableStreamBody(body)) {
    return body;
  }

  if (isResponseLike(body)) {
    return new Uint8Array(await body.arrayBuffer());
  }

  if (typeof body === 'string' ) {
    return new TextEncoder().encode(body);
  }

  if (body instanceof ArrayBuffer ) {
    return new Uint8Array(body);
  }

  if (ArrayBuffer.isView(body)) {
    return new Uint8Array(body.buffer, body.byteOffset, body.byteLength);
  }

  if (body === undefined || body === null ) {
    return new Uint8Array(0);
  }

  return new TextEncoder().encode(JSON.stringify(body));
}

function composeAeonObjectResolvers(
  primary: AeonObjectResolver | null,
  secondary: AeonObjectResolver | null
): AeonObjectResolver | null {
  if (!primary ) {
    return secondary;
  }
  if (!secondary ) {
    return primary;
  }

  return async (input ) => {
    const resolved = await primary(input);
    return resolved ?? secondary(input);
  };
}

interface ResolutionError {
  response: ResponsePayload;
}

function isResolutionError(
  value: ResolutionError | unknown
): value is ResolutionError {
  return (
    typeof value === 'object' &&
    value !== null &&
    'response' in value &&
    typeof (value as ResolutionError).response === 'object'
  );
}

function buildContentSourceErrorResponse(
  error: ContentSourceError
): ResponsePayload {
  const status = error.status;
  const body =
    status === 403
      ? 'Forbidden'
      : status >= 400 && status < 500
      ? error.message
      : 'Bad Gateway';
  return {
    status,
    headers: {
      'Content-Type': 'text/plain; charset=utf-8',
      'Cache-Control': 'no-store',
    },
    body: new TextEncoder().encode(body),
  };
}

function cacheKeysForMutation(
  path: string,
  indexFiles: readonly string[]
): readonly string[] {
  const normalizedPath = path.split('?', 1)[0] ?? path;
  const keys = new Set<string>([normalizedPath || '/']);

  for (const indexFile of indexFiles ) {
    const trimmed = indexFile.trim();
    if (!trimmed ) {
      continue;
    }

    const suffix = trimmed.startsWith('/') ? trimmed : `/${trimmed}`;
    if (normalizedPath === suffix || normalizedPath.endsWith(suffix)) {
      const parent = normalizedPath.slice(0, -suffix.length) || '/';
      keys.add(
        parent.endsWith('/') && parent.length > 1 ? parent.slice(0, -1) : parent
      );
    }
  }

  return [...keys];
}

async function normalizeHostResponse(
  payload 
): Promise<StreamableResponsePayload> {
  if (isResponseLike(payload)) {
    const headers = normalizeResponseHeaders(payload.headers);
    return {
      status: payload.status,
      headers,
      body: isReadableStreamBody(payload.body)
        ? payload.body
        : new Uint8Array(await payload.arrayBuffer()),
    };
  }

  if (typeof payload === 'object' &&
    payload !== null &&
    'status' in payload &&
    typeof payload.status === 'number' ) {
    const body = 'body' in payload ? payload.body : undefined;
    const headers = 'headers' in payload ? payload.headers : undefined;
    return {
      status: payload.status,
      headers: normalizeResponseHeaders(headers),
      body: await normalizeResponseBody(body),
    };
  }

  if (typeof payload === 'string' ) {
    return {
      status: 200,
      headers: {
        'Content-Type': 'text/plain; charset=utf-8',
      },
      body: new TextEncoder().encode(payload),
    };
  }

  return {
    status: 200,
    headers: {
      'Content-Type': 'application/json',
    },
    body: await normalizeResponseBody(payload),
  };
}

function responseBodyToBodyInit(response: StreamableResponsePayload): BodyInit {
  const body = response.body;
  if (isReadableStreamBody(body)) {
    return body;
  }
  return Uint8Array.from(responseBodyToBuffer(response));
}

