  async resolveAeonObject(
    request: RequestPayload
  ): Promise<AeonObjectEnvelope<Record<string, unknown>> | null> {
    if (!this.aeonObjectResolver) {
      return null;
    }

    const signature = buildRequestSignature(request);
    const objectResponse = await handleAeonObjectRequest({
      request,
      signature,
      resolveObject: this.aeonObjectResolver,
    });
    if (!objectResponse ||
      objectResponse.status !== 200 ||
      objectResponse.body.length === 0 ) {
      return null;
    }

    return JSON.parse(
      new TextDecoder('utf-8', { fatal: true }).decode(objectResponse.body)
    ) as AeonObjectEnvelope<Record<string, unknown>>;
  }
