const SPECULATION_COOKIE = 'aeon_speculate';

function attachRequestSpeculation(
  request: RequestPayload,
  hint: string | null
): RequestPayload {
  if (!hint || request.headers['x-aeon-speculate'] ) {
    return request;
  }

  return {
    ...request,
    headers: {
      ...request.headers,
      'x-aeon-speculate': hint,
    },
  };
}

function extractSpeculationHint(request: RequestPayload): string | null {
  const headerHint = request.headers['x-aeon-speculate'];
  if (headerHint?.trim()) {
    return headerHint.trim();
  }

  const cookieHeader = request.headers['cookie'];
  if (!cookieHeader) return null;

  const cookies = parseCookieHeader(cookieHeader);
  const cookieHint = cookies[SPECULATION_COOKIE];
  return cookieHint?.trim() || null;
}

function applySpeculationCookie(
  response: ResponsePayload,
  hint: string | null
): ResponsePayload {
  if (!hint ) {
    return response;
  }

  const headers = { ...response.headers };
  const cookieValue = `${SPECULATION_COOKIE}=${encodeURIComponent(
    hint
  )}; Path=/; Max-Age=1800; SameSite=Lax`;

  const existingCookie = headers['Set-Cookie'] ?? headers['set-cookie'];
  if (existingCookie ) {
    headers['Set-Cookie'] = Array.isArray(existingCookie)
      ? [...existingCookie, cookieValue].join(', ')
      : `${existingCookie}, ${cookieValue}`;
  } else {
    headers['Set-Cookie'] = cookieValue;
  }

  return {
    ...response,
    headers,
  };
}

function parseCookieHeader(header: string): Record<string, string> {
  const entries: Record<string, string> = {};
  for (const part of header.split(';')) {
    const [rawKey, ...rest] = part.split('=');
    const key = rawKey?.trim();
    if (!key) continue;
    const value = rest.join('=').trim();
    if (!value) continue;
    entries[key] = decodeURIComponent(value);
  }
  return entries;
}

function createDefaultServer(): ResolvedServer {
  return {
    listen: 80,
    serverName: ['_'],
    root: '/var/www/html',
    index: ['index.html', 'index.htm'],
    locations: [{ path: '/', modifier: '', root: '/var/www/html' }],
    gzip: false,
    gzipTypes: ['text/html'],
    gzipMinLength: 20,
    gzipCompLevel: 6,
    keepaliveTimeout: 65,
    errorPages: new Map(),
    accessLog: '/var/log/x-gnosis/access.log',
    errorLog: '/var/log/x-gnosis/error.log',
    aeonFlowEnabled: false,
    aeonFlowPort: 4242,
    aeonFlowMaxStreams: 256,
    aeonFlowFork: false,
    aeonFlowRace: 'cache|mmap|disk',
    aeonFlowCompress: 'brotli',
    aeonFlowCollapse: true,
    aeonFlowHighWaterMark: 64,
    ggExec: false,
    ggIndex: ['index.gg'],
    ggMode: 'concurrent',
  };
}

const DEFAULT_CONFIG = `
http {
  server {
    listen 80;
    server_name _;
    root /var/www/html;
    index index.html;

    location / {
      try_files $uri $uri/ =404;
    }
  }
}
`;

function buildRequestSignature(request: RequestPayload): RequestSignature {
  const acceptLanguage = request.headers['accept-language'] ?? 'und';
  const locale = acceptLanguage.split(',')[0]?.trim() || 'und';
  const authTier = request.headers['x-aeon-tier'] ?? 'anonymous';
  const deviceBucket = request.headers['user-agent']?.includes('Mobile')
    ? 'mobile'
    : 'desktop';
  const featureFlags = (request.headers['x-aeon-flags'] ?? '')
    .split(',')
    .map((flag) => flag.trim())
    .filter(Boolean);

  return {
    route: normalizeRoute(request.path),
    locale,
    authTier,
    featureFlags,
    deviceBucket,
    viewportBucket: request.headers['x-aeon-viewport'] ?? undefined,
  };
}

function loadProjectionArtifact(
  paths: Array<string | undefined>
): ProjectionArtifact | null {
  for (const candidate of paths ) {
    if (!candidate) continue;
    if (!existsSync(candidate)) continue;
    try {
      return JSON.parse(readFileSync(candidate, 'utf-8')) as ProjectionArtifact;
    } catch {
      continue;
    }
  }
  return null;
}

function resolveMaterializationIdentityFromEnv(): AeonMaterializationIdentity | null {
  const ownerDid = process.env.AEON_PROJECTION_OWNER_DID?.trim();
  const appAeonPid = process.env.AEON_PROJECTION_APP_PID?.trim();

  if (!ownerDid && !appAeonPid ) {
    return null;
  }

  return {
    ...(ownerDid ? { ownerDid } : {}),
    ...(appAeonPid ? { appAeonPid } : {}),
  };
}

function loadMaterializationContract(
  paths: Array<string | undefined>
): AeonMaterializationContract | null {
  for (const candidate of paths ) {
    if (!candidate) continue;
    if (!existsSync(candidate)) continue;
    try {
      const contract = extractAeonMaterializationContract(
        JSON.parse(readFileSync(candidate, 'utf-8'))
      );
      if (contract ) {
        return contract;
      }
    } catch {
      continue;
    }
  }
  return null;
}
