/**
 * Buleyean Neural Types
 *
 * Neural graphs where training is rejection-first.
 * Every neuron carries a void boundary. Every synapse
 * carries rejection counts. The God Formula derives
 * weight updates from what failed -- no reward model.
 *
 * Mechanized foundations:
 *   buleyean_positivity (Law 1) -- P(i) > 0 for all i
 *   buleyean_monotone_nonrejected (Law 2) -- less rejected = more weight
 *   void_boundary_sufficient_statistic -- rejection counts are all you need
 *   failure_strictly_more_informative -- N-1 bits vs 1 bit
 */

/**
 * A neuron with a void boundary.
 * The boundary accumulates rejection counts per activation level.
 */
export interface BuleyeanNeuron {
  id: string;
  type: 'input' | 'hidden' | 'output';
  bias: number;
  activation: 'tanh' | 'relu' | 'sigmoid' | 'identity';
  /** Void boundary: rejection counts per discretized activation level */
  voidBoundary: number[];
  /** Total rejections absorbed */
  totalRejections: number;
  /** Current complement distribution (derived from void boundary) */
  complementWeights: number[];
}

/**
 * A synapse whose weight is derived from the God Formula.
 * w = R - min(v, R) + 1
 */
export interface BuleyeanSynapse {
  id: string;
  fromId: string;
  toId: string;
  /** Current weight (derived from complement distribution) */
  weight: number;
  /** Rejection count for this connection */
  rejections: number;
  /** Total rejection rounds seen */
  totalRounds: number;
}

/**
 * A rejection signal flowing backward through the graph.
 * Instead of gradient backpropagation, we propagate rejection counts.
 */
export interface RejectionSignal {
  /** Which output neuron triggered the rejection */
  sourceNeuronId: string;
  /** The activation that was rejected */
  rejectedActivation: number;
  /** Strength of rejection (1.0 = full rejection) */
  strength: number;
  /** Round number */
  round: number;
}

/**
 * Training configuration for buleyean neural training.
 */
export interface BuleyeanNeuralConfig {
  /** Number of discretized activation levels per neuron (default: 20) */
  activationLevels: number;
  /** Temperature for complement distribution (default: 1.0) */
  temperature: number;
  /** Learning rate -- scales how much complement distribution shifts weights */
  learningRate: number;
  /** Minimum rejection count to include in complement (default: 1) */
  minRejectionCount: number;
  /** Decay rate for old rejections (default: 0.0 = no decay) */
  decayRate: number;
}

export const DEFAULT_NEURAL_CONFIG: BuleyeanNeuralConfig = {
  activationLevels: 20,
  temperature: 1.0,
  learningRate: 0.01,
  minRejectionCount: 1,
  decayRate: 0.0,
};

/**
 * Metrics for a buleyean neural graph.
 */
export interface BuleyeanNeuralMetrics {
  /** Total neurons */
  neuronCount: number;
  /** Total synapses */
  synapseCount: number;
  /** Total rejections across all neurons */
  totalRejections: number;
  /** Mean Bule deficit across neurons */
  meanDeficit: number;
  /** Whether the graph has converged (all deficits = 0) */
  converged: boolean;
  /** Per-neuron entropy of complement distributions */
  neuronEntropies: Map<string, number>;
}

/**
 * Serializable state for persistence.
 */
export interface BuleyeanGraphState {
  neurons: Array<{
    id: string;
    type: BuleyeanNeuron['type'];
    bias: number;
    activation: BuleyeanNeuron['activation'];
    voidBoundary: number[];
    totalRejections: number;
  }>;
  synapses: Array<{
    id: string;
    fromId: string;
    toId: string;
    weight: number;
    rejections: number;
    totalRounds: number;
  }>;
  config: BuleyeanNeuralConfig;
  round: number;
}
