/**
 * Cloud Run Authentication Helper (shared)
 *
 * Provides OIDC token generation for Cloudflare Workers to authenticate
 * to Cloud Run services. Used by edge-workers and edge-web-app.
 *
 * Security Architecture:
 * 1. Cloud Run services require IAM authentication (no public access)
 * 2. Gateway service account has roles/run.invoker on coordinator
 * 3. Cloudflare Workers use this helper to generate OIDC tokens
 * 4. Tokens are cached and refreshed before expiry
 */

interface ServiceAccountKey {
  type: string;
  project_id: string;
  private_key_id: string;
  private_key: string;
  client_email: string;
  client_id: string;
  auth_uri: string;
  token_uri: string;
  auth_provider_x509_cert_url: string;
  client_x509_cert_url: string;
}

interface TokenCache {
  token: string;
  expiry: number;
  audience: string;
}

export const CLOUD_RUN_SERVICE_ACCOUNT_ENV_KEYS = [
  'CLOUDRUN_SA_KEY',
  'GOOGLE_SERVICE_ACCOUNT_JSON',
  'FIREBASE_SERVICE_ACCOUNT',
] as const;

export type CloudRunServiceAccountEnvKey =
  (typeof CLOUD_RUN_SERVICE_ACCOUNT_ENV_KEYS)[number];

export interface CloudRunServiceAccountResolution {
  key: string | undefined;
  source: CloudRunServiceAccountEnvKey | null;
}

// Token cache (in-memory, per worker instance)
const tokenCache = new Map<string, TokenCache>();

// Token refresh buffer (5 minutes before expiry)
const TOKEN_REFRESH_BUFFER_MS = 5 * 60 * 1000;

/**
 * Base64URL encode a string
 */
function base64UrlEncode(str: string): string {
  const base64 = btoa(str);
  return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}

/**
 * Import RSA private key from PEM format
 */
async function importPrivateKey(pem: string): Promise<CryptoKey> {
  const pemContents = pem
    .replace(/-----BEGIN PRIVATE KEY-----/g, '')
    .replace(/-----END PRIVATE KEY-----/g, '')
    .replace(/\s/g, '');

  const binaryDer = Uint8Array.from(atob(pemContents), (c) => c.charCodeAt(0));

  return crypto.subtle.importKey(
    'pkcs8',
    binaryDer,
    {
      name: 'RSASSA-PKCS1-v1_5',
      hash: 'SHA-256',
    },
    false,
    ['sign']
  );
}

/**
 * Sign the JWT using RSA-SHA256
 */
async function signJWT(privateKey: CryptoKey, data: string): Promise<string> {
  const encoder = new TextEncoder();
  const signature = await crypto.subtle.sign(
    'RSASSA-PKCS1-v1_5',
    privateKey,
    encoder.encode(data)
  );

  const signatureArray = new Uint8Array(signature);
  let signatureStr = '';
  for (let i = 0; i < signatureArray.length; i++) {
    signatureStr += String.fromCharCode(signatureArray[i]!);
  }

  return base64UrlEncode(signatureStr);
}

/**
 * Create a JWT for Google OAuth2 token exchange
 */
async function createJWT(
  serviceAccountKey: ServiceAccountKey,
  audience: string
): Promise<string> {
  const now = Math.floor(Date.now() / 1000);
  const expiry = now + 3600; // 1 hour

  const header = {
    alg: 'RS256',
    typ: 'JWT',
    kid: serviceAccountKey.private_key_id,
  };

  const payload = {
    iss: serviceAccountKey.client_email,
    sub: serviceAccountKey.client_email,
    aud: 'https://oauth2.googleapis.com/token',
    iat: now,
    exp: expiry,
    target_audience: audience,
  };

  const encodedHeader = base64UrlEncode(JSON.stringify(header));
  const encodedPayload = base64UrlEncode(JSON.stringify(payload));
  const signatureInput = `${encodedHeader}.${encodedPayload}`;

  const privateKey = await importPrivateKey(serviceAccountKey.private_key);
  const signature = await signJWT(privateKey, signatureInput);

  return `${signatureInput}.${signature}`;
}

/**
 * Exchange JWT for OIDC identity token
 */
async function exchangeJWTForToken(jwt: string): Promise<{
  token: string;
  expiresIn: number;
}> {
  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({
      grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
      assertion: jwt,
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Token exchange failed: ${error}`);
  }

  const data = (await response.json()) as {
    id_token: string;
    expires_in: number;
  };

  return {
    token: data.id_token,
    expiresIn: data.expires_in,
  };
}

/**
 * Get an OIDC identity token for authenticating to Cloud Run
 */
export async function getCloudRunToken(
  serviceAccountKeyJson: string,
  cloudRunUrl: string
): Promise<string> {
  const audience = new URL(cloudRunUrl).origin;

  const cached = tokenCache.get(audience);
  if (cached && cached.expiry > Date.now() + TOKEN_REFRESH_BUFFER_MS) {
    return cached.token;
  }

  let serviceAccountKey: ServiceAccountKey;

  // Extract strictly from the first '{' to the last '}' to ignore any bash-injected quotes or escape characters
  const startIdx = serviceAccountKeyJson.indexOf('{');
  const endIdx = serviceAccountKeyJson.lastIndexOf('}');
  const sanitizedJson =
    startIdx >= 0 && endIdx >= startIdx
      ? serviceAccountKeyJson.slice(startIdx, endIdx + 1)
      : serviceAccountKeyJson;

  try {
    const decoded = atob(sanitizedJson);
    serviceAccountKey = JSON.parse(decoded);
  } catch {
    serviceAccountKey = JSON.parse(sanitizedJson);
  }

  const jwt = await createJWT(serviceAccountKey, audience);
  const { token, expiresIn } = await exchangeJWTForToken(jwt);

  tokenCache.set(audience, {
    token,
    expiry: Date.now() + expiresIn * 1000,
    audience,
  });

  return token;
}

/**
 * Create authenticated fetch headers for Cloud Run
 */
export async function getCloudRunHeaders(
  serviceAccountKeyJson: string,
  cloudRunUrl: string
): Promise<Record<string, string>> {
  const token = await getCloudRunToken(serviceAccountKeyJson, cloudRunUrl);
  return {
    Authorization: `Bearer ${token}`,
  };
}

/**
 * Fetch from Cloud Run with automatic authentication
 */
export async function fetchCloudRunAuthenticated(
  serviceAccountKeyJson: string,
  url: string,
  init?: RequestInit,
  timeoutMs?: number
): Promise<Response> {
  const authHeaders = await getCloudRunHeaders(serviceAccountKeyJson, url);

  const headers = new Headers(init?.headers);
  headers.set('Authorization', authHeaders['Authorization'] ?? '');

  if (!timeoutMs || timeoutMs <= 0) {
    return fetch(url, {
      ...init,
      headers,
    });
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, {
      ...init,
      headers,
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * Resolve Cloud Run service account key from environment with alias support.
 *
 * Precedence:
 * 1. CLOUDRUN_SA_KEY (canonical worker secret)
 * 2. GOOGLE_SERVICE_ACCOUNT_JSON (legacy/local alias)
 * 3. FIREBASE_SERVICE_ACCOUNT (legacy/local alias)
 */
export function resolveCloudRunServiceAccountKey(
  env: Record<string, unknown>
): CloudRunServiceAccountResolution {
  for (const keyName of CLOUD_RUN_SERVICE_ACCOUNT_ENV_KEYS) {
    const raw = env[keyName];
    if (typeof raw !== 'string') {
      continue;
    }
    const trimmed = raw.trim();
    if (!trimmed) {
      continue;
    }
    return {
      key: trimmed,
      source: keyName,
    };
  }

  return {
    key: undefined,
    source: null,
  };
}

/**
 * Check if a Cloud Run URL is configured for authentication
 */
export function isCloudRunAuthConfigured(
  env: Record<string, unknown>
): boolean {
  return !!resolveCloudRunServiceAccountKey(env).key;
}

/**
 * Clear the token cache (useful for testing or key rotation)
 */
export function clearTokenCache(): void {
  tokenCache.clear();
}
