import {
  FEDERATION_SUPERNODE_INDEX,
  SnapshotBackedN1Lookup,
  buildSignedSnapshot,
  createIntentReceipt,
  verifyFederationRecord,
  verifyRouteEnvelope,
  type FederationChainId,
  type FederationIssuerPublicKeyMap,
  type KnotFederationRecord,
  type MutationIntent,
  type N1LookupResult,
  type RevocationDelta,
  type RouteEnvelope,
  type SignedFederationSnapshot,
} from '@a0n/knot-federation-core';
import type { ResolvedServer } from './config/ast.ts';
import type { RequestPayload, ResponsePayload } from './handlers/registry.ts';
import type { XGnosisControlSurface } from './server.ts';

interface FederationSigner {
  readonly issuer: string;
  readonly keyId: string;
  readonly privateKeyPem: string;
}

export interface XGnosisFederationSupernodeOptions {
  readonly supernodeRecord: KnotFederationRecord;
  readonly records?: readonly KnotFederationRecord[];
  readonly mirrors?: readonly string[];
  readonly revocations?: readonly RevocationDelta[];
  readonly epoch?: number;
  readonly signer: FederationSigner;
  readonly issuerPublicKeys: FederationIssuerPublicKeyMap;
}

interface JsonRpcRequest {
  readonly jsonrpc: '2.0';
  readonly id?: string | number | null;
  readonly method: string;
  readonly params?: Record<string, unknown>;
}

function jsonResponse(payload , status = 200): ResponsePayload {
  return {
    status,
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'no-store',
    },
    body: new TextEncoder().encode(JSON.stringify(payload)),
  };
}

function parsePath(request: RequestPayload): URL {
  return new URL(request.path, 'http://x-gnosis.local');
}

function decodeJsonRequestBody(request: RequestPayload)  {
  if (!request.body || request.body.byteLength === 0 ) {
    return null;
  }

  const decoded = new TextDecoder().decode(request.body);
  return JSON.parse(decoded) as unknown;
}

function toPositiveInteger(value: string | null): number | null {
  if (!value ) {
    return null;
  }
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed < 0) {
    return null;
  }
  return parsed;
}

function decodeChainParam(value: string | null): FederationChainId | null {
  const normalized = value?.trim();
  const decoded = (( ) => {
    if (!normalized ) {
      return null;
    }
    try {
      return decodeURIComponent(normalized);
    } catch {
      return normalized;
    }
  })();
  return decoded && decoded.length > 0
    ? (decoded as FederationChainId)
    : null;
}

function endpointFromRequest(request: RequestPayload): string {
  const host = request.headers.host ?? '127.0.0.1';
  const proto = request.headers['x-forwarded-proto'] ?? 'http';
  return `${proto}://${host}`;
}

function sortRecords(records: readonly KnotFederationRecord[]): KnotFederationRecord[] {
  return [...records].sort((left, right) =>
    left.chainId.localeCompare(right.chainId)
  );
}

export class XGnosisFederationControlSurface implements XGnosisControlSurface {
  private readonly signer: FederationSigner;
  private readonly issuerPublicKeys: FederationIssuerPublicKeyMap;
  private readonly mirrors: readonly string[];
  private readonly revocations: readonly RevocationDelta[];
  private readonly acceptedIntents: MutationIntent[] = [];

  private recordsByChain = new Map<FederationChainId, KnotFederationRecord>();
  private epoch: number;

  constructor(options: XGnosisFederationSupernodeOptions) {
    if (options.supernodeRecord.index !== FEDERATION_SUPERNODE_INDEX ) {
      throw new Error('federation supernode record must use index=0');
    }

    this.signer = options.signer;
    this.issuerPublicKeys = options.issuerPublicKeys;
    this.mirrors = options.mirrors ?? [];
    this.revocations = options.revocations ?? [];
    this.epoch = options.epoch ?? options.supernodeRecord.witnessHead.epoch;

    const allRecords = [
      options.supernodeRecord,
      ...(options.records ?? []),
    ];

    for (const record of allRecords ) {
      const check = verifyFederationRecord(record, {
        issuerPublicKeys: this.issuerPublicKeys,
      });
      if (!check.ok ) {
        throw new Error(
          `invalid federation record for ${record.chainId}: ${check.reason}`
        );
      }

      this.recordsByChain.set(record.chainId, record);
    }
  }

  async handleRequest(
    request: RequestPayload,
    _server: ResolvedServer
  ): Promise<ResponsePayload | null> {
    const url = parsePath(request);
    if (!url.pathname.startsWith('/.aeon/federation')) {
      return null;
    }

    try {
      if (request.method === 'GET' && url.pathname === '/.aeon/federation/snapshot' ) {
        return this.handleSnapshotRequest(url);
      }

      if (request.method === 'GET' && url.pathname === '/.aeon/federation/revocations' ) {
        return this.handleRevocationsRequest(url);
      }

      if (request.method === 'GET' && url.pathname === '/.aeon/federation/n1' ) {
        return await this.handleN1LookupRequest(url, request);
      }

      if (
        request.method === 'GET' &&
        url.pathname.startsWith('/.aeon/federation/resolve/')
      ) {
        return await this.handleResolveRequest(url, request);
      }

      if (request.method === 'GET' && url.pathname === '/.aeon/federation/witness' ) {
        return this.handleWitnessStatusRequest(url);
      }

      if (request.method === 'POST' && url.pathname === '/.aeon/federation/intents' ) {
        return this.handleSubmitIntentRequest(request);
      }

      if (request.method === 'POST' && url.pathname === '/.aeon/federation/mcp' ) {
        return await this.handleMcpJsonRpcRequest(request);
      }
    } catch (error ) {
      const message = error instanceof Error ? error.message : String(error);
      return jsonResponse(
        {
          ok: false,
          error: message,
        },
        500
      );
    }

    return null;
  }

  private handleSnapshotRequest(url: URL): ResponsePayload {
    const requestedEpoch = toPositiveInteger(url.searchParams.get('epoch'));
    if (requestedEpoch !== null && requestedEpoch !== this.epoch) {
      return jsonResponse(
        {
          ok: false,
          error: `snapshot epoch ${requestedEpoch} is unavailable`,
          availableEpoch: this.epoch,
        },
        404
      );
    }

    return jsonResponse({
      ok: true,
      snapshot: this.buildSnapshot(),
      proof: this.buildProofEnvelope(),
    });
  }

  private handleRevocationsRequest(url: URL): ResponsePayload {
    const sinceEpoch = toPositiveInteger(url.searchParams.get('sinceEpoch'));
    const deltas =
      sinceEpoch === null
        ? this.revocations
        : this.revocations.filter((delta) => delta.epoch >= sinceEpoch);

    return jsonResponse({
      ok: true,
      epoch: this.epoch,
      revocations: deltas,
      proof: this.buildProofEnvelope(),
    });
  }

  private async handleN1LookupRequest(
    url: URL,
    request: RequestPayload
  ): Promise<ResponsePayload> {
    const fromChainId = decodeChainParam(url.searchParams.get('from'));
    const toChainId = decodeChainParam(url.searchParams.get('to'));

    if (!fromChainId || !toChainId ) {
      return jsonResponse(
        {
          ok: false,
          error: 'n1 lookup requires query params: from, to',
        },
        400
      );
    }

    const lookup = await this.computeN1Lookup(fromChainId, toChainId, request);

    return jsonResponse({
      ok: true,
      lookup,
      proof: this.buildProofEnvelope({
        routeDigest: lookup.route.digest,
        witnessDigest: lookup.witness.digest,
      }),
    });
  }

  private async handleResolveRequest(
    url: URL,
    request: RequestPayload
  ): Promise<ResponsePayload> {
    const chainId = decodeChainParam(
      url.pathname.slice('/.aeon/federation/resolve/'.length)
    );
    if (!chainId ) {
      return jsonResponse({ ok: false, error: 'missing destination chain id' }, 400);
    }

    const fromChainId =
      decodeChainParam(url.searchParams.get('from')) ?? this.supernodeChainId();

    const lookup = await this.computeN1Lookup(fromChainId, chainId, request);
    return jsonResponse({
      ok: true,
      envelope: lookup.route,
      proof: this.buildProofEnvelope({
        routeDigest: lookup.route.digest,
        witnessDigest: lookup.witness.digest,
      }),
    });
  }

  private handleWitnessStatusRequest(url: URL): ResponsePayload {
    const chainId = decodeChainParam(url.searchParams.get('chainId'));

    if (!chainId ) {
      return jsonResponse({
        ok: true,
        epoch: this.epoch,
        witnesses: [...this.recordsByChain.values()].map((record) => ({
          chainId: record.chainId,
          witness: record.witnessHead,
          revoked: this.revocations.some((delta) =>
            delta.revokedChainIds.includes(record.chainId)
          ),
        })),
        proof: this.buildProofEnvelope(),
      });
    }

    const record = this.recordsByChain.get(chainId);
    if (!record ) {
      return jsonResponse({ ok: false, error: `unknown chain: ${chainId}` }, 404);
    }

    return jsonResponse({
      ok: true,
      chainId,
      witness: record.witnessHead,
      revoked: this.revocations.some((delta) =>
        delta.revokedChainIds.includes(chainId)
      ),
      proof: this.buildProofEnvelope({
        witnessDigest: record.witnessHead.digest,
      }),
    });
  }

  private handleSubmitIntentRequest(request: RequestPayload): ResponsePayload {
    const payload = decodeJsonRequestBody(request) as
      | { intent?: MutationIntent }
      | null;
    const intent = payload?.intent;
    if (!intent ) {
      return jsonResponse(
        {
          ok: false,
          error: 'submitIntent requires body: { intent }',
        },
        400
      );
    }

    this.acceptedIntents.push(intent);
    const receipt = createIntentReceipt(
      intent,
      'accepted',
      FEDERATION_SUPERNODE_INDEX,
      undefined,
      this.signer
    );

    return jsonResponse({
      ok: true,
      receipt,
      acceptedIntents: this.acceptedIntents.length,
      proof: this.buildProofEnvelope({
        intentId: intent.intentId,
      }),
    });
  }

  private async handleMcpJsonRpcRequest(
    request: RequestPayload
  ): Promise<ResponsePayload> {
    const payload = decodeJsonRequestBody(request) as JsonRpcRequest | null;
    if (!payload || payload.jsonrpc !== '2.0' || !payload.method ) {
      return jsonResponse(
        {
          jsonrpc: '2.0',
          id: payload?.id ?? null,
          error: {
            code: -32600,
            message: 'Invalid Request',
          },
        },
        400
      );
    }

    try {
      const result = await this.handleJsonRpcMethod(payload, request);
      return jsonResponse({
        jsonrpc: '2.0',
        id: payload.id ?? null,
        result,
      });
    } catch (error ) {
      const message = error instanceof Error ? error.message : String(error);
      return jsonResponse(
        {
          jsonrpc: '2.0',
          id: payload.id ?? null,
          error: {
            code: -32000,
            message,
          },
        },
        500
      );
    }
  }

  private async handleJsonRpcMethod(
    payload: JsonRpcRequest,
    request: RequestPayload
  ): Promise<unknown> {
    switch (payload.method ) {
      case 'federation.resolveChain': {
        const chainId = decodeChainParam(String(payload.params?.chainId ?? ''));
        if (!chainId ) {
          throw new Error('federation.resolveChain requires params.chainId');
        }
        const fromChainId =
          decodeChainParam(String(payload.params?.fromChainId ?? '')) ??
          this.supernodeChainId();
        const lookup = await this.computeN1Lookup(fromChainId, chainId, request);
        return {
          envelope: lookup.route,
          proof: this.buildProofEnvelope({ routeDigest: lookup.route.digest }),
        };
      }

      case 'federation.n1Lookup': {
        const fromChainId = decodeChainParam(
          String(payload.params?.fromChainId ?? '')
        );
        const toChainId = decodeChainParam(
          String(payload.params?.toChainId ?? '')
        );
        if (!fromChainId || !toChainId ) {
          throw new Error(
            'federation.n1Lookup requires params.fromChainId and params.toChainId'
          );
        }
        const lookup = await this.computeN1Lookup(fromChainId, toChainId, request);
        return {
          lookup,
          proof: this.buildProofEnvelope({ routeDigest: lookup.route.digest }),
        };
      }

      case 'federation.pullSnapshot': {
        const epoch = toPositiveInteger(
          payload.params?.epoch ? String(payload.params.epoch) : null
        );
        if (epoch !== null && epoch !== this.epoch) {
          throw new Error(`snapshot epoch ${epoch} is unavailable`);
        }
        return {
          snapshot: this.buildSnapshot(),
          proof: this.buildProofEnvelope(),
        };
      }

      case 'federation.submitIntent': {
        const intent = payload.params?.intent as MutationIntent | undefined;
        if (!intent ) {
          throw new Error('federation.submitIntent requires params.intent');
        }

        this.acceptedIntents.push(intent);
        return {
          receipt: createIntentReceipt(
            intent,
            'accepted',
            FEDERATION_SUPERNODE_INDEX,
            undefined,
            this.signer
          ),
          proof: this.buildProofEnvelope({ intentId: intent.intentId }),
        };
      }

      case 'federation.witnessStatus': {
        const chainId = decodeChainParam(
          payload.params?.chainId ? String(payload.params.chainId) : null
        );

        if (!chainId ) {
          return {
            witnesses: [...this.recordsByChain.values()].map((record) => ({
              chainId: record.chainId,
              witness: record.witnessHead,
            })),
            proof: this.buildProofEnvelope(),
          };
        }

        const record = this.recordsByChain.get(chainId);
        if (!record ) {
          throw new Error(`unknown chain: ${chainId}`);
        }

        return {
          chainId,
          witness: record.witnessHead,
          proof: this.buildProofEnvelope({ witnessDigest: record.witnessHead.digest }),
        };
      }

      case 'federation.revocations': {
        return {
          epoch: this.epoch,
          revocations: this.revocations,
          proof: this.buildProofEnvelope(),
        };
      }

      default:
        throw new Error(`unknown federation JSON-RPC method: ${payload.method}`);
    }
  }

  private buildSnapshot(): SignedFederationSnapshot {
    return buildSignedSnapshot({
      epoch: this.epoch,
      index: FEDERATION_SUPERNODE_INDEX,
      records: sortRecords([...this.recordsByChain.values()]),
      revocations: this.revocations,
      mirrors: this.mirrors,
      signer: this.signer,
    });
  }

  private supernodeChainId(): FederationChainId {
    const supernode = [...this.recordsByChain.values()].find(
      (record) => record.index === FEDERATION_SUPERNODE_INDEX
    );
    if (!supernode ) {
      throw new Error('supernode index=0 record not configured');
    }
    return supernode.chainId;
  }

  private async computeN1Lookup(
    fromChainId: FederationChainId,
    toChainId: FederationChainId,
    request: RequestPayload
  ): Promise<N1LookupResult> {
    const snapshot = this.buildSnapshot();

    const n1 = new SnapshotBackedN1Lookup({
      snapshot,
      resolver: endpointFromRequest(request),
      mode: 'index-0',
      routeSigner: this.signer,
      validation: {
        issuerPublicKeys: this.issuerPublicKeys,
      },
    });

    const lookup = await n1.n1Lookup(fromChainId, toChainId);
    const routeCheck = verifyRouteEnvelope(lookup.route, {
      issuerPublicKeys: this.issuerPublicKeys,
      revocations: this.revocations,
    });
    if (!routeCheck.ok ) {
      throw new Error(`federation route verification failed: ${routeCheck.reason}`);
    }

    return lookup;
  }

  private buildProofEnvelope(input?: {
    readonly routeDigest?: string;
    readonly witnessDigest?: string;
    readonly intentId?: string;
  }): Record<string, unknown> {
    return {
      kind: 'aeon-federation-proof-envelope',
      rhizomeObject: '/.aeon/object/rhizome/federation-index',
      snapshotEpoch: this.epoch,
      snapshotDigest: this.buildSnapshot().snapshot.digest,
      routeDigest: input?.routeDigest ?? null,
      witnessDigest: input?.witnessDigest ?? null,
      intentId: input?.intentId ?? null,
    };
  }
}

export function createXGnosisFederationControlSurface(
  options: XGnosisFederationSupernodeOptions
): XGnosisFederationControlSurface {
  return new XGnosisFederationControlSurface(options);
}
