import { alchemicHash48HexSync } from '@a0n/bitwise/cache-fp64';
import { request as httpRequest } from 'node:http';
import {
  ContentSourceError,
  expandContentCandidates,
  inferContentTypeFromPath,
  normalizeContentPath,
  type ContentMutationRequest,
  type ContentRequest,
  type ContentWriteResult,
  type MutableContentSource,
  type ResolvedContent,
} from './content-source.ts';

interface BridgeAuthRequestPayload {
  method: string;
  path: string;
  headers: Record<string, string>;
}

interface BridgeStatRequestPayload {
  repo_id: string;
  path: string;
  auth: BridgeAuthRequestPayload;
}

interface BridgeBlobReadRequestPayload extends BridgeStatRequestPayload {
  hash: string;
}

interface BridgeStatResponseBody {
  entry?: {
    hash: string;
    size: number;
    lastModified: number;
  } | null;
}

interface BridgeWriteResponseBody {
  hash?: string;
  stored?: boolean;
}

export interface XGnosisBridgeVfsContentSourceOptions {
  socketPath: string;
  repoId: string;
  trustPropagatedAuth?: boolean;
}

interface BridgeResponse {
  status: number;
  headers: Record<string, string>;
  body: Uint8Array;
}

export interface XGnosisBridgeVfsInvalidationEvent {
  type: 'upsert' | 'delete';
  path: string;
  hash?: string;
}

function bodyContentFingerprint(bytes: Uint8Array): string {
  return alchemicHash48HexSync(bytes);
}

function parseJsonBody<T>(body: Uint8Array): T | null {
  if (body.byteLength === 0 ) {
    return null;
  }

  try {
    return JSON.parse(new TextDecoder().decode(body)) as T;
  } catch {
    return null;
  }
}

function normalizeBridgeHeaders(
  headers: Record<string, string>
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(headers).map(([name, value]) => [name.toLowerCase(), value])
  );
}

export class XGnosisBridgeVfsContentSource implements MutableContentSource {
  readonly name = 'bridge-vfs';
  readonly strategyMode = 'single' as const;
  private readonly socketPath: string;
  private readonly repoId: string;
  private readonly trustPropagatedAuth: boolean;

  constructor(options: XGnosisBridgeVfsContentSourceOptions) {
    this.socketPath = options.socketPath;
    this.repoId = options.repoId;
    this.trustPropagatedAuth = options.trustPropagatedAuth ?? false;
  }

  async resolve(request: ContentRequest): Promise<ResolvedContent | null> {
    const auth = this.authPayload({
      method: request.method ?? 'GET',
      path: request.uri,
      headers: request.headers ?? {},
    });

    for (const candidatePath of expandContentCandidates(
      request.uri,
      request.indexFiles
    )) {
      const statResponse = await this.requestJson<BridgeStatResponseBody>({
        path: '/v1/stat',
        body: {
          repo_id: this.repoId,
          path: candidatePath,
          auth: {
            ...auth,
            path: candidatePath,
          },
        },
      });
      if (statResponse.status === 404 ) {
        continue;
      }
      this.assertBridgeStatus(statResponse, 'forge_vfs stat');

      const entry = statResponse.payload?.entry;
      if (!entry ) {
        continue;
      }

      const blobResponse = await this.requestBytes({
        path: '/v1/blob/read',
        body: {
          repo_id: this.repoId,
          path: candidatePath,
          hash: entry.hash,
          auth: {
            ...auth,
            path: candidatePath,
          },
        } satisfies BridgeBlobReadRequestPayload,
      });
      if (blobResponse.status === 404 ) {
        throw new ContentSourceError(
          502,
          `forge_vfs blob missing for ${candidatePath}`
        );
      }
      this.assertBridgeStatus(blobResponse, 'forge_vfs blob read');

      return {
        data: blobResponse.body,
        contentType: inferContentTypeFromPath(candidatePath),
        etag: `W/"${entry.hash}"`,
        lastModified: entry.lastModified,
        size: entry.size,
        filePath: candidatePath,
      };
    }

    return null;
  }

  async write(request: ContentMutationRequest): Promise<ContentWriteResult> {
    if (!request.body ) {
      throw new ContentSourceError(
        400,
        'forge_vfs writes require a request body'
      );
    }

    const path = normalizeContentPath(request.uri);
    const hash = bodyContentFingerprint(request.body);
    const response = await this.requestRaw({
      path: '/v1/write',
      headers: {
        ...this.forwardHeaders(request.headers),
        'content-type': 'application/octet-stream',
        'x-vfs-repo-id': this.repoId,
        'x-vfs-path': path,
        'x-vfs-hash': hash,
      },
      body: request.body,
    });
    this.assertBridgeStatus(response, 'forge_vfs write');

    const payload = parseJsonBody<BridgeWriteResponseBody>(response.body);
    return {
      hash: payload?.hash ?? hash,
      stored: payload?.stored ?? true,
    };
  }

  async delete(request: ContentMutationRequest): Promise<void> {
    const path = normalizeContentPath(request.uri);
    const response = await this.requestJson({
      path: '/v1/delete',
      body: {
        repo_id: this.repoId,
        path,
        auth: this.authPayload({
          method: 'DELETE',
          path,
          headers: request.headers,
        }),
      },
    });
    this.assertBridgeStatus(response, 'forge_vfs delete');
  }

  private authPayload(
    request:
      | Pick<ContentMutationRequest, 'method' | 'uri' | 'headers'>
      | BridgeAuthRequestPayload
  ): BridgeAuthRequestPayload {
    return {
      method: request.method,
      path: 'uri' in request ? request.uri : request.path,
      headers: this.forwardHeaders(request.headers),
    };
  }

  private forwardHeaders(
    headers: Record<string, string>
  ): Record<string, string> {
    const forwarded = normalizeBridgeHeaders(headers);
    if (this.trustPropagatedAuth) {
      forwarded['x-vfs-trust-propagated-auth'] = '1';
    }
    return forwarded;
  }

  private bridgeControlHeaders(): Record<string, string> {
    return this.trustPropagatedAuth
      ? {
          'x-vfs-trust-propagated-auth': '1',
        }
      : {};
  }

  private async requestJson<T>(options: {
    path: string;
    body ;
  }): Promise<{
    status: number;
    body: Uint8Array;
    payload: T | null;
    headers: Record<string, string>;
  }> {
    const response = await this.requestRaw({
      path: options.path,
      headers: {
        'content-type': 'application/json',
        ...this.bridgeControlHeaders(),
      },
      body: new TextEncoder().encode(JSON.stringify(options.body)),
    });
    return {
      status: response.status,
      body: response.body,
      headers: response.headers,
      payload: parseJsonBody<T>(response.body),
    };
  }

  private async requestBytes(options: {
    path: string;
    body ;
  }): Promise<BridgeResponse> {
    return await this.requestRaw({
      path: options.path,
      headers: {
        'content-type': 'application/json',
        ...this.bridgeControlHeaders(),
      },
      body: new TextEncoder().encode(JSON.stringify(options.body)),
    });
  }

  private async requestRaw(options: {
    path: string;
    headers: Record<string, string>;
    body: Uint8Array;
  }): Promise<BridgeResponse> {
    return await new Promise((resolve , reject ) => {
      const request = httpRequest(
        {
          agent: false,
          socketPath: this.socketPath,
          path: options.path,
          method: 'POST',
          headers: {
            ...options.headers,
            'content-length': String(options.body.byteLength),
          },
        },
        (response ) => {
          const chunks: Buffer[] = [];
          response.on('data', (chunk) => {
            chunks.push(Buffer.from(chunk));
          });
          response.on('end' , ( ) => {
            resolve({
              status: response.statusCode ?? 0,
              headers: normalizeBridgeHeaders(
                Object.fromEntries(
                  Object.entries(response.headers).flatMap(([name, value]) => {
                    if (typeof value === 'string' ) {
                      return [[name, value]];
                    }
                    if (Array.isArray(value)) {
                      return [[name, value.join(', ')]];
                    }
                    return [];
                  })
                )
              ),
              body: new Uint8Array(Buffer.concat(chunks)),
            });
          });
        }
      );
      request.on('error', reject);
      request.write(options.body);
      request.end();
    });
  }

  subscribeInvalidations(
    onInvalidation: (event: XGnosisBridgeVfsInvalidationEvent) => void
  ): () => void {
    let active = true;
    let responseStream: NodeJS.ReadableStream | null = null;
    let buffered = '';

    const request = httpRequest(
      {
        agent: false,
        socketPath: this.socketPath,
        path: '/v1/events',
        method: 'GET',
        headers: this.bridgeControlHeaders(),
      },
      (response ) => {
        responseStream = response;
        response.setEncoding('utf8');
        response.on('data', (chunk: string) => {
          buffered += chunk;

          while (true ) {
            const newlineIndex = buffered.indexOf('\n');
            if (newlineIndex < 0 ) {
              break;
            }

            const line = buffered.slice(0, newlineIndex).trim();
            buffered = buffered.slice(newlineIndex + 1);
            if (!line ) {
              continue;
            }

            try {
              const parsed = JSON.parse(
                line
              ) as Partial<XGnosisBridgeVfsInvalidationEvent>;
              if (
                active &&
                (parsed.type === 'upsert' || parsed.type === 'delete') &&
                typeof parsed.path === 'string'
              ) {
                onInvalidation({
                  type: parsed.type,
                  path: parsed.path,
                  ...(typeof parsed.hash === 'string'
                    ? { hash: parsed.hash }
                    : {}),
                });
              }
            } catch {
              continue;
            }
          }
        });
      }
    );

    request.on('error' , ( ) => {});
    request.end();

    return () => {
      active = false;
      request.destroy();
      (
        responseStream as
          | (NodeJS.ReadableStream & { destroy?: () => void })
          | null
      )?.destroy?.();
    };
  }

  private assertBridgeStatus(
    response: Pick<BridgeResponse, 'status' | 'body'>,
    operation: string
  ): void {
    const message =
      parseJsonBody<{ error?: string }>(response.body)?.error ??
      `${operation} failed`;
    if (response.status === 200 ) {
      return;
    }
    if (response.status === 400 ) {
      throw new ContentSourceError(400, message);
    }
    if (response.status === 403 ) {
      throw new ContentSourceError(403, message);
    }
    if (response.status === 409 || response.status === 422 ) {
      throw new ContentSourceError(response.status, message);
    }
    throw new ContentSourceError(
      502,
      `${operation} failed with status ${response.status}`
    );
  }
}
