/**
 * Semiotic Router (Self-Describing Topology)
 *
 * Implements the theoretical structure from:
 * `open-source/gnosis/lean/Lean/ForkRaceFoldTheorems/SemioticStructure.lean`
 *
 * The router eliminates the need for explicit `type` enumerations or OpCodes
 * in distributed payloads by classifying the execution or parsing strategy
 * purely through the topological ordering of the elements.
 */

export enum SemioticAxis {
  /** 
   * Origin / Triage: Ordered heaviest-first or longest-first. 
   * Drops unimportant details quickly to process massive constraints. 
   */
  Origin = 'origin',
  
  /** 
   * Process / Thematic: Ordered by conceptual grouping or hierarchy.
   * Clusters related structures.
   */
  Process = 'process',
  
  /** 
   * Resolution / Chronological: Ordered strictly ascending by time or index. 
   * Complete, exhaustive, sequential verification.
   */
  Resolution = 'resolution',

  /**
   * Unknown or entangled ordering.
   */
  Unordered = 'unordered'
}

export interface SemioticElement {
  /** Chronological/Sequence identifier (e.g., timestamp, index) */
  time?: number;
  /** Heavy/Constraint identifier (e.g., intrinsicBeta1 deficit, payload size) */
  weight?: number;
  /** Conceptual/Hierarchical group identifier (e.g., layer number, tag hash) */
  themeId?: number;
}

/**
 * Derives the Semiotic Axis projection by analyzing the sequence ordering
 * of an un-tagged array of elements. 
 *
 * If the array is perfectly ordered by decreasing weight, it is Triage/Origin.
 * If perfectly ordered by increasing time, it is Chronological/Resolution.
 * If grouped perfectly by theme, it is Thematic/Process.
 * 
 * Note: Tie-breaking biases toward Origin if heavily overlapping, as
 * triage environments are the most structurally demanding.
 */
export function routeTopologyBySemioticOrdering<T extends SemioticElement>(
  elements: T[]
): SemioticAxis {
  try {
    if (elements.length <= 1) return SemioticAxis.Unordered;

    let isHeaviestFirst = true;
    let isChronological = true;
    let isThematicGrouped = true;

    // Track thematic transitions to check for contiguous grouping
    const seenThemes = new Set<number>();
    let currentTheme = elements[0].themeId;
    if (currentTheme !== undefined) seenThemes.add(currentTheme);

    for (let i = 1; i < elements.length; i++) {
      const prev = elements[i - 1];
      const curr = elements[i];

      // Check Origin ordering (Decreasing Weight)
      if (prev.weight !== undefined && curr.weight !== undefined) {
        if (curr.weight > prev.weight) isHeaviestFirst = false;
      } else {
        isHeaviestFirst = false;
      }

      // Check Resolution ordering (Increasing Time)
      if (prev.time !== undefined && curr.time !== undefined) {
        if (curr.time < prev.time) isChronological = false;
      } else {
        isChronological = false;
      }

      // Check Process ordering (Contiguous Themes)
      if (curr.themeId !== undefined) {
        if (curr.themeId !== currentTheme) {
          if (seenThemes.has(curr.themeId)) {
            // A theme we already saw, left, and returned to - not contiguous!
            isThematicGrouped = false;
          } else {
            seenThemes.add(curr.themeId);
            currentTheme = curr.themeId;
          }
        }
      } else {
        isThematicGrouped = false;
      }
    }

    // Precedence checks based on Gnosis theoretical strength
    if (isHeaviestFirst && !isChronological) return SemioticAxis.Origin;
    if (isChronological && !isHeaviestFirst) return SemioticAxis.Resolution;
    if (isThematicGrouped && !isHeaviestFirst && !isChronological) return SemioticAxis.Process;

    // Fallback to strict unordered
    // (If it happens to satisfy multiple perfectly, we treat it as unresolved/unordered
    // unless we add strong heuristic disambiguation.)
    return SemioticAxis.Unordered;

  } catch (error) {
    throw new Error(`[routeTopologyBySemioticOrdering] ${error instanceof Error ? error.message : String(error)}`);
  }
}
