import { createHash } from 'node:crypto';
import type { DistributedTopology } from '@a0n/cognitive-bridge';

export interface TopologyProofToken {
  readonly topologyHash: string;
  readonly signature: string;
  readonly signerDid: string;
  readonly timestamp: number;
}

/**
 * Generates a cryptographic proof of topological soundness.
 *
 * Hashes the distributed topology and signs it using the operator's
 * local identity (DID). This proof is required by aeon-forge for deployment.
 */
export async function generateTopologyProof(
  topology: DistributedTopology,
  signerDid: string,
  privateKey: CryptoKey
): Promise<TopologyProofToken> {
  const timestamp = Date.now();
  const canonicalString = JSON.stringify(
    topology,
    Object.keys(topology).sort()
  );
  const hash = createHash('sha256').update(canonicalString).digest('hex');

  const encoder = new TextEncoder();
  const data = encoder.encode(hash + timestamp);
  const signatureBuffer = await crypto.subtle.sign(
    { name: 'ECDSA', hash: { name: 'SHA-256' } },
    privateKey,
    data
  );

  const signature = Buffer.from(signatureBuffer).toString('base64');

  return {
    topologyHash: hash,
    signature,
    signerDid,
    timestamp,
  };
}

/**
 * Verifies a topological soundness proof.
 */
export async function verifyTopologyProof(
  topology: DistributedTopology,
  token: TopologyProofToken,
  publicKey: CryptoKey
): Promise<boolean> {
  const canonicalString = JSON.stringify(
    topology,
    Object.keys(topology).sort()
  );
  const hash = createHash('sha256').update(canonicalString).digest('hex');

  if (hash !== token.topologyHash) return false;

  const encoder = new TextEncoder();
  const data = encoder.encode(hash + token.timestamp);
  const signature = Buffer.from(token.signature, 'base64');

  return await crypto.subtle.verify(
    { name: 'ECDSA', hash: { name: 'SHA-256' } },
    publicKey,
    signature,
    data
  );
}
