/**
 * @a0n/auth - Access Control Layer
 *
 * Fine-grained access control combining UCAN capabilities with XPath node selection.
 * Grant, revoke, and check access per user, per node, per operation.
 *
 * @example
 * ```typescript
 * import { AccessControl, DID } from '@a0n/auth';
 *
 * const ac = new AccessControl();
 *
 * // Grant Alice full access to her subtree
 * ac.grant('did:key:alice', '//users/alice/**', ['read', 'write', 'delete']);
 *
 * // Open a shared workspace for collaboration
 * ac.grantPublic('//workspace/shared/**', ['read', 'write']);
 *
 * // Lock down admin area
 * ac.deny('*', '//admin/**');
 * ac.grant('did:key:admin', '//admin/**', ['read', 'write', 'admin']);
 *
 * // Check access
 * const canRead = ac.check('did:key:alice', '/users/alice/profile', 'read', data);
 * // => { allowed: true, reason: 'Granted by rule: //users/alice/**' }
 *
 * // Get all nodes a user can access
 * const accessible = ac.getAccessibleNodes('did:key:alice', 'read', data);
 * ```
 */

import type { DID } from './ucanTypes.js';
import {
  compile,
  getGrantedNodes,
  type SelectedNode,
  type CompiledSelector,
} from './xpath.js';

// =============================================================================
// TYPES
// =============================================================================

/**
 * Access operations
 */
export type AccessOperation = 'read' | 'write' | 'delete' | 'admin' | '*';

/**
 * Access rule
 */
export interface AccessRule {
  /** Rule ID */
  id: string;
  /** Subject (DID or '*' for all) */
  subject: string;
  /** XPath selector for target nodes */
  selector: string;
  /** Compiled selector */
  compiled: CompiledSelector;
  /** Allowed operations */
  operations: AccessOperation[];
  /** Grant or deny */
  effect: 'grant' | 'deny';
  /** Priority (higher = checked first) */
  priority: number;
  /** Expiration timestamp */
  expiresAt?: number;
  /** Additional constraints */
  constraints?: Record<string, unknown>;
  /** Human-readable description */
  description?: string;
}

/**
 * Access check result
 */
export interface AccessCheckResult {
  /** Whether access is allowed */
  allowed: boolean;
  /** The rule that determined access */
  matchedRule?: AccessRule;
  /** Reason for the decision */
  reason: string;
  /** The nodes that were checked */
  checkedNodes?: SelectedNode[];
}

/**
 * Access grant options
 */
export interface GrantOptions {
  /** Priority (default: 0) */
  priority?: number;
  /** Expiration (ms from now) */
  expiresIn?: number;
  /** Absolute expiration timestamp */
  expiresAt?: number;
  /** Additional constraints */
  constraints?: Record<string, unknown>;
  /** Human-readable description */
  description?: string;
}

// =============================================================================
// ACCESS CONTROL
// =============================================================================

/**
 * Access Control Manager
 *
 * Manages fine-grained access control with XPath selectors.
 */
export class AccessControl {
  private rules: Map<string, AccessRule> = new Map();
  private ruleCounter = 0;

  /**
   * Grant access to nodes matching a selector
   */
  grant(
    subject: DID | '*',
    selector: string,
    operations: AccessOperation | AccessOperation[],
    options?: GrantOptions
  ): string {
    const ops = Array.isArray(operations) ? operations : [operations];
    return this.addRule(subject, selector, ops, 'grant', options);
  }

  /**
   * Grant public access (all users)
   */
  grantPublic(
    selector: string,
    operations: AccessOperation | AccessOperation[],
    options?: GrantOptions
  ): string {
    return this.grant('*', selector, operations, options);
  }

  /**
   * Deny access to nodes matching a selector
   */
  deny(
    subject: DID | '*',
    selector: string,
    operations: AccessOperation | AccessOperation[] = '*',
    options?: GrantOptions
  ): string {
    const ops = Array.isArray(operations) ? operations : [operations];
    // Deny rules have higher default priority
    const priority = options?.priority ?? 100;
    return this.addRule(subject, selector, ops, 'deny', {
      ...options,
      priority,
    });
  }

  /**
   * Deny public access (block all users)
   */
  denyPublic(
    selector: string,
    operations: AccessOperation | AccessOperation[] = '*',
    options?: GrantOptions
  ): string {
    return this.deny('*', selector, operations, options);
  }

  /**
   * Revoke a rule
   */
  revoke(ruleId: string): boolean {
    return this.rules.delete(ruleId);
  }

  /**
   * Revoke all rules for a subject
   */
  revokeAll(subject: DID | '*'): number {
    let count = 0;
    for (const [id, rule] of this.rules) {
      if (rule.subject === subject) {
        this.rules.delete(id);
        count++;
      }
    }
    return count;
  }

  /**
   * Check if access is allowed
   */
  check(
    subject: DID,
    path: string,
    operation: AccessOperation,
    data?: unknown
  ): AccessCheckResult {
    // Clean up expired rules
    this.cleanupExpired();

    // Get sorted rules (highest priority first)
    const sortedRules = this.getSortedRules();

    // Check each rule
    for (const rule of sortedRules) {
      // Skip if subject doesn't match
      if (rule.subject !== '*' && rule.subject !== subject) {
        continue;
      }

      // Skip if operation doesn't match
      if (
        !rule.operations.includes('*') &&
        !rule.operations.includes(operation)
      ) {
        continue;
      }

      // Check if selector matches the path
      let matches = false;
      let checkedNodes: SelectedNode[] = [];

      if (data !== undefined) {
        // With data, we can do full XPath selection
        const selected = rule.compiled.select(data);
        checkedNodes = selected;

        for (const node of selected) {
          if (node.path === path || path.startsWith(node.path + '/')) {
            matches = true;
            break;
          }
        }
      } else {
        // Without data, do simple path matching
        matches = this.pathMatchesSelector(path, rule.selector);
      }

      if (matches) {
        if (rule.effect === 'deny') {
          return {
            allowed: false,
            matchedRule: rule,
            reason: `Denied by rule: ${rule.selector}${
              rule.description ? ` (${rule.description})` : ''
            }`,
            checkedNodes,
          };
        } else {
          return {
            allowed: true,
            matchedRule: rule,
            reason: `Granted by rule: ${rule.selector}${
              rule.description ? ` (${rule.description})` : ''
            }`,
            checkedNodes,
          };
        }
      }
    }

    // Default deny
    return {
      allowed: false,
      reason: 'No matching rule found',
    };
  }

  /**
   * Check multiple operations at once
   */
  checkMultiple(
    subject: DID,
    path: string,
    operations: AccessOperation[],
    data?: unknown
  ): Map<AccessOperation, AccessCheckResult> {
    const results = new Map<AccessOperation, AccessCheckResult>();
    for (const op of operations) {
      results.set(op, this.check(subject, path, op, data));
    }
    return results;
  }

  /**
   * Get all nodes a subject can access
   */
  getAccessibleNodes(
    subject: DID,
    operation: AccessOperation,
    data: unknown
  ): SelectedNode[] {
    this.cleanupExpired();

    const accessible = new Set<string>();
    const denied = new Set<string>();
    const nodeMap = new Map<string, SelectedNode>();

    // Get sorted rules (highest priority first)
    const sortedRules = this.getSortedRules();

    for (const rule of sortedRules) {
      // Skip if subject doesn't match
      if (rule.subject !== '*' && rule.subject !== subject) {
        continue;
      }

      // Skip if operation doesn't match
      if (
        !rule.operations.includes('*') &&
        !rule.operations.includes(operation)
      ) {
        continue;
      }

      // Get all nodes matching this rule
      const nodes = getGrantedNodes(rule.selector, data);

      for (const node of nodes) {
        nodeMap.set(node.path, node);

        if (rule.effect === 'deny') {
          denied.add(node.path);
          accessible.delete(node.path);
        } else if (!denied.has(node.path)) {
          accessible.add(node.path);
        }
      }
    }

    return Array.from(accessible).map((path) => nodeMap.get(path)!);
  }

  /**
   * Get all rules for a subject
   */
  getRulesForSubject(subject: DID | '*'): AccessRule[] {
    return Array.from(this.rules.values()).filter(
      (r) => r.subject === subject || r.subject === '*'
    );
  }

  /**
   * Get all rules
   */
  getAllRules(): AccessRule[] {
    return Array.from(this.rules.values());
  }

  /**
   * Create a sandbox (public read/write area)
   */
  createSandbox(selector: string, options?: GrantOptions): string[] {
    const readId = this.grantPublic(selector, ['read', 'write'], {
      ...options,
      description: options?.description || `Sandbox: ${selector}`,
    });
    return [readId];
  }

  /**
   * Create a read-only public area
   */
  createPublicReadOnly(selector: string, options?: GrantOptions): string[] {
    const readId = this.grantPublic(selector, 'read', {
      ...options,
      description: options?.description || `Public read-only: ${selector}`,
    });
    const denyId = this.denyPublic(selector, ['write', 'delete'], {
      ...options,
      priority: (options?.priority ?? 0) + 1,
      description: `Block writes to read-only: ${selector}`,
    });
    return [readId, denyId];
  }

  /**
   * Create a user-owned area (user has full control)
   */
  createUserOwned(
    subject: DID,
    selector: string,
    options?: GrantOptions
  ): string[] {
    const grantId = this.grant(
      subject,
      selector,
      ['read', 'write', 'delete', 'admin'],
      {
        ...options,
        description: options?.description || `User-owned: ${selector}`,
      }
    );
    return [grantId];
  }

  /**
   * Export rules as JSON
   */
  exportRules(): object {
    return {
      version: '1.0',
      rules: Array.from(this.rules.values()).map((rule) => ({
        id: rule.id,
        subject: rule.subject,
        selector: rule.selector,
        operations: rule.operations,
        effect: rule.effect,
        priority: rule.priority,
        expiresAt: rule.expiresAt,
        constraints: rule.constraints,
        description: rule.description,
      })),
    };
  }

  /**
   * Import rules from JSON
   */
  importRules(data: { rules: Array<Omit<AccessRule, 'compiled'>> }): void {
    for (const rule of data.rules) {
      this.rules.set(rule.id, {
        ...rule,
        compiled: compile(rule.selector),
      });
    }
  }

  /**
   * Clear all rules
   */
  clear(): void {
    this.rules.clear();
    this.ruleCounter = 0;
  }

  // ==========================================================================
  // PRIVATE METHODS
  // ==========================================================================

  private addRule(
    subject: DID | '*',
    selector: string,
    operations: AccessOperation[],
    effect: 'grant' | 'deny',
    options?: GrantOptions
  ): string {
    const id = `rule-${++this.ruleCounter}`;

    let expiresAt: number | undefined;
    if (options?.expiresAt) {
      expiresAt = options.expiresAt;
    } else if (options?.expiresIn) {
      expiresAt = Date.now() + options.expiresIn;
    }

    const rule: AccessRule = {
      id,
      subject,
      selector,
      compiled: compile(selector),
      operations,
      effect,
      priority: options?.priority ?? 0,
      expiresAt,
      constraints: options?.constraints,
      description: options?.description,
    };

    this.rules.set(id, rule);
    return id;
  }

  private getSortedRules(): AccessRule[] {
    return Array.from(this.rules.values()).sort(
      (a, b) => b.priority - a.priority
    );
  }

  private cleanupExpired(): void {
    const now = Date.now();
    for (const [id, rule] of this.rules) {
      if (rule.expiresAt && rule.expiresAt < now) {
        this.rules.delete(id);
      }
    }
  }

  private pathMatchesSelector(path: string, selector: string): boolean {
    // Simple path matching without data
    // Normalize both paths
    const normalizedPath = path.startsWith('/') ? path : '/' + path;
    let pattern = selector;

    // Handle descendant axis //
    if (pattern.startsWith('//')) {
      const remainder = pattern.slice(2);
      // Match anywhere in the path
      const segments = normalizedPath.split('/').filter((s) => s);
      const patternSegments = remainder.split('/').filter((s) => s);

      for (let i = 0; i <= segments.length - patternSegments.length; i++) {
        if (this.segmentsMatch(segments.slice(i), patternSegments)) {
          return true;
        }
      }
      return false;
    }

    // Handle child axis /
    if (!pattern.startsWith('/')) {
      pattern = '/' + pattern;
    }

    const pathSegments = normalizedPath.split('/').filter((s) => s);
    const patternSegments = pattern.split('/').filter((s) => s);

    return this.segmentsMatch(pathSegments, patternSegments);
  }

  private segmentsMatch(path: string[], pattern: string[]): boolean {
    let pathIdx = 0;
    let patternIdx = 0;

    while (patternIdx < pattern.length) {
      const p = pattern[patternIdx];

      // Double wildcard matches zero or more
      if (p === '**' || p === 'node()') {
        // If last pattern, matches everything
        if (patternIdx === pattern.length - 1) {
          return true;
        }

        // Try matching remaining pattern at each position
        for (let i = pathIdx; i <= path.length; i++) {
          if (
            this.segmentsMatch(path.slice(i), pattern.slice(patternIdx + 1))
          ) {
            return true;
          }
        }
        return false;
      }

      // No more path segments
      if (pathIdx >= path.length) {
        return false;
      }

      // Single wildcard matches one
      if (p === '*') {
        pathIdx++;
        patternIdx++;
        continue;
      }

      // Exact match
      if (p !== path[pathIdx]) {
        return false;
      }

      pathIdx++;
      patternIdx++;
    }

    // Pattern exhausted, path should be too
    return pathIdx === path.length;
  }
}

// =============================================================================
// FACTORY FUNCTIONS
// =============================================================================

/**
 * Create a new AccessControl instance
 */
export function createAccessControl(): AccessControl {
  return new AccessControl();
}

/**
 * Create an AccessControl with common patterns pre-configured
 */
export function createStandardAccessControl(options?: {
  /** Enable public sandbox at /sandbox/** */
  sandbox?: boolean;
  /** Enable user-owned areas at /users/$userId/** */
  userOwned?: boolean;
  /** Paths that should be read-only for everyone */
  publicReadOnly?: string[];
  /** Paths that should be admin-only */
  adminOnly?: string[];
}): AccessControl {
  const ac = new AccessControl();

  if (options?.sandbox !== false) {
    ac.createSandbox('//sandbox/**', { description: 'Public sandbox' });
  }

  if (options?.publicReadOnly) {
    for (const path of options.publicReadOnly) {
      ac.createPublicReadOnly(path);
    }
  }

  if (options?.adminOnly) {
    for (const path of options.adminOnly) {
      ac.denyPublic(path, '*', { description: `Admin-only: ${path}` });
    }
  }

  return ac;
}
