import {
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { join, resolve } from 'node:path';
import type { XRangerSessionRecord } from './types.ts';

function recordPath(registryDir: string, sessionId: string): string {
  return join(registryDir, `${sessionId}.json`);
}

export function ensureXRangerRegistryDir(registryDir: string): string {
  const normalized = resolve(registryDir);
  mkdirSync(normalized, { recursive: true });
  return normalized;
}

export function writeXRangerSessionRecord(
  registryDir: string,
  record: XRangerSessionRecord
): void {
  const dir = ensureXRangerRegistryDir(registryDir);
  writeFileSync(
    recordPath(dir, record.sessionId),
    `${JSON.stringify(record, null, 2)}\n`,
    'utf8'
  );
}

export function removeXRangerSessionRecord(
  registryDir: string,
  sessionId: string
): void {
  rmSync(recordPath(ensureXRangerRegistryDir(registryDir), sessionId), {
    force: true,
  });
}

export function readXRangerSessionRecords(
  registryDir: string
): XRangerSessionRecord[] {
  const dir = ensureXRangerRegistryDir(registryDir);
  return readdirSync(dir)
    .filter((entry) => entry.endsWith('.json'))
    .map((entry) =>
      JSON.parse(readFileSync(join(dir, entry), 'utf8'))
    ) as XRangerSessionRecord[];
}

export function findXRangerSessionByWorkerName(
  registryDir: string,
  workerName: string
): XRangerSessionRecord | null {
  const matches = readXRangerSessionRecords(registryDir)
    .filter((record) => record.workerName === workerName)
    .sort((left, right) => right.startedAt.localeCompare(left.startedAt));
  return matches[0] ?? null;
}
