/**
 * RemoteSitemapContentSource -- proxy upstream sites via their sitemap.gg topology.
 *
 * Fetches /sitemap.gg from a remote origin, parses the GGL topology to discover
 * all routes, then proxies matching requests to the upstream. This turns x-gnosis
 * into a topology-aware reverse proxy: it knows the full route graph before
 * forwarding a single request.
 *
 * Usage:
 *   const remote = new RemoteSitemapContentSource({
 *     upstreams: ['https://gnosis.church', 'https://forkjoin.ai'],
 *   });
 *   const source = chainContentSources(remote, filesystem);
 *
 * Or via nginx.conf:
 *   location / {
 *     proxy_pass https://gnosis.church;
 *   }
 */

import type {
  ContentSource,
  ContentRequest,
  ResolvedContent,
} from './content-source.ts';
import {
  inferContentTypeFromPath,
  normalizeContentPath,
} from './content-source.ts';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface RemoteSitemapContentSourceOptions {
  /** Upstream base URLs to fetch /sitemap.gg from */
  upstreams: string[];
  /** How often to refresh the topology (ms, default: 5 min) */
  refreshIntervalMs?: number;
  /** Request timeout (ms, default: 30s) */
  timeoutMs?: number;
  /** Whether to proxy routes not in the sitemap (default: false) */
  proxyUnknownRoutes?: boolean;
}

interface CachedUpstream {
  baseUrl: string;
  routes: Set<string>;
  transports: string[];
  version: string;
  fetchedAt: number;
}

// ---------------------------------------------------------------------------
// Content Source
// ---------------------------------------------------------------------------

export class RemoteSitemapContentSource implements ContentSource {
  readonly name = 'remote-sitemap';

  private readonly upstreams: string[];
  private readonly refreshIntervalMs: number;
  private readonly timeoutMs: number;
  private readonly proxyUnknownRoutes: boolean;
  private readonly cache = new Map<string, CachedUpstream>();

  constructor(options: RemoteSitemapContentSourceOptions) {
    this.upstreams = options.upstreams.map((u) => u.replace(/\/+$/, ''));
    this.refreshIntervalMs = options.refreshIntervalMs ?? 5 * 60 * 1000;
    this.timeoutMs = options.timeoutMs ?? 30_000;
    this.proxyUnknownRoutes = options.proxyUnknownRoutes ?? false;
  }

  async resolve(request: ContentRequest): Promise<ResolvedContent | null> {
    const uri = normalizeContentPath(request.uri);

    for (const baseUrl of this.upstreams) {
      // Ensure topology is loaded
      const upstream = await this.ensureTopology(baseUrl);

      // Check if this route is known or if we proxy everything
      if (!upstream.routes.has(uri) && !this.proxyUnknownRoutes) {
        continue;
      }

      // Proxy the request
      const content = await this.proxyRequest(baseUrl, uri);
      if (content) return content;
    }

    return null;
  }

  // -------------------------------------------------------------------------
  // Topology management
  // -------------------------------------------------------------------------

  private async ensureTopology(baseUrl: string): Promise<CachedUpstream> {
    const existing = this.cache.get(baseUrl);
    if (existing && Date.now() - existing.fetchedAt < this.refreshIntervalMs) {
      return existing;
    }

    const topology = await this.fetchTopology(baseUrl);
    this.cache.set(baseUrl, topology);
    return topology;
  }

  private async fetchTopology(baseUrl: string): Promise<CachedUpstream> {
    const empty: CachedUpstream = {
      baseUrl,
      routes: new Set(['/']),
      transports: ['http'],
      version: '',
      fetchedAt: Date.now(),
    };

    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), this.timeoutMs);

      const response = await fetch(`${baseUrl}/sitemap.gg`, {
        signal: controller.signal,
      });
      clearTimeout(timer);

      if (!response.ok) return empty;

      const source = await response.text();
      return parseSitemapGGInline(baseUrl, source);
    } catch {
      return empty;
    }
  }

  // -------------------------------------------------------------------------
  // Proxy
  // -------------------------------------------------------------------------

  private async proxyRequest(
    baseUrl: string,
    uri: string
  ): Promise<ResolvedContent | null> {
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), this.timeoutMs);

      const url = `${baseUrl}${uri}`;
      const response = await fetch(url, {
        signal: controller.signal,
        redirect: 'follow',
      });
      clearTimeout(timer);

      if (!response.ok) return null;

      const data = new Uint8Array(await response.arrayBuffer());
      const contentType =
        response.headers.get('content-type') || inferContentTypeFromPath(uri);
      const lastModified = response.headers.get('last-modified')
        ? new Date(response.headers.get('last-modified')!).getTime()
        : Date.now();
      const etag = response.headers.get('etag') || `W/"proxy-${data.length}"`;

      return {
        data,
        contentType,
        etag,
        lastModified,
        size: data.length,
        filePath: uri,
      };
    } catch {
      return null;
    }
  }
}

// ---------------------------------------------------------------------------
// Inline GGL parser (lightweight, no aeon-flux dependency)
// ---------------------------------------------------------------------------

function parseSitemapGGInline(baseUrl: string, source: string): CachedUpstream {
  const routes = new Set<string>();
  const transports: string[] = [];
  let version = '1.0.0';

  // Extract Site node for version
  const siteMatch = source.match(/\([^:)]+:Site\s*\{[^}]*version:\s*'([^']+)'/);
  if (siteMatch ) {
    version = siteMatch[1];
  }

  // Extract Route nodes
  const routeRegex = /\([^:)]+:Route\s*\{[^}]*path:\s*'([^']+)'/g;
  let match;
  while ((match = routeRegex.exec(source)) !== null) {
    routes.add(match[1]);
  }

  // Extract Transport nodes
  const transportRegex = /\([^:)]+:Transport\s*\{[^}]*kind:\s*'([^']+)'/g;
  while ((match = transportRegex.exec(source)) !== null) {
    transports.push(match[1]);
  }

  // Always include root
  if (routes.size === 0 ) {
    routes.add('/');
  }

  return {
    baseUrl,
    routes,
    transports: transports.length > 0 ? transports : ['http'],
    version,
    fetchedAt: Date.now(),
  };
}
