/**
 * Config Compiler
 *
 * Translates resolved nginx config into a .gg topology string.
 * The generated topology is then parsed by BettyCompiler and
 * executed by GnosisEngine with registered x-gnosis handlers.
 */

import type { ResolvedServer, ResolvedLocation } from './ast.ts';

/**
 * Compile a resolved server config into a .gg topology source string.
 */
export function compileServerTopology(server: ResolvedServer): string {
  const locationList = server.locations
    .map((l) => `${l.modifier}${l.path}`)
    .join(',');

  // Level 8: LAMINAR replaces fixed-codec CompressBody.
  // Per-chunk codec racing (identity, gzip, brotli, deflate) picks
  // the smallest result for each chunk. Strictly dominates sendfile()
  // for compressible content (THM-TOPO-RACE-SUBSUMPTION).
  const chunkSize = '65536';
  const codecs = 'identity,gzip,brotli,deflate';

  const lines: string[] = [
    `// Generated x-gnosis topology for ${server.serverName.join(', ')}:${
      server.listen
    }`,
    `// Level 8: Hella-Whipped Laminar Pipeline (per-chunk codec racing)`,
    '',
    `(listener: TCPListener { port: '${server.listen}', backlog: '511' })`,
    `(conn: AcceptConnection)`,
    `(raw: ReadBytes)`,
    `(parsed: AssembledRequest)`,
    `(route: LocationRouter { locations: '${locationList}' })`,
    `(cache: CacheLookup)`,
    `(mmap: MmapRead { root: '${server.root}' })`,
    `(disk: DiskRead { root: '${server.root}' })`,
    `(file: FileData)`,
    `(headers: BuildHeaders { status: '200' })`,
    `(body: LaminarCompress { chunk: '${chunkSize}', codecs: '${codecs}' })`,
    `(response: AssembleResponse)`,
    `(send: SendResponse)`,
    `(keepalive: CheckKeepAlive { timeout: '${server.keepaliveTimeout}' })`,
    '',
    `(listener)-[:FORK]->(conn)`,
    `(conn)-[:PROCESS]->(raw)`,
    `(raw)-[:PROCESS]->(parsed)`,
    `(parsed)-[:PROCESS]->(route)`,
    `(route)-[:FORK]->(cache | mmap | disk)`,
    `(cache | mmap | disk)-[:RACE { failure: 'vent' }]->(file)`,
    `(file)-[:FORK]->(headers | body)`,
    `(headers)-[:PROCESS]->(response)`,
    `(body)-[:LAMINAR { chunk: '${chunkSize}', codecs: '${codecs}' }]->(response)`,
    `(headers | body)-[:FOLD { strategy: 'assemble_response' }]->(response)`,
    `(response)-[:PROCESS]->(send)`,
    `(send)-[:PROCESS]->(keepalive)`,
  ];

  return lines.join('\n');
}

/**
 * Compile a resolved location into a sub-topology fragment.
 */
export function compileLocationTopology(
  location: ResolvedLocation,
  serverRoot: string
): string {
  const root = location.root ?? location.alias ?? serverRoot;

  if (location.returnCode ) {
    return [
      `(loc_${sanitizeId(location.path)}: ReturnResponse { code: '${
        location.returnCode
      }', body: '${location.returnBody ?? ''}' })`,
    ].join('\n');
  }

  return [
    `(loc_${sanitizeId(
      location.path
    )}: StaticLocation { root: '${root}', path: '${location.path}' })`,
  ].join('\n');
}

function sanitizeId(path: string): string {
  return path.replace(/[^a-zA-Z0-9]/g, '_').replace(/^_+|_+$/g, '') || 'root';
}
