/**
 * @a0n/zk-encryption - AES-256-GCM Utilities
 *
 * Symmetric encryption using AES-256-GCM
 */

import type {
  EncryptedPayload,
  EncryptionOptions,
  DecryptionResult,
} from './zkTypes.js';
import { generateNonce } from './keys.js';
import { base64UrlEncode, base64UrlDecode } from './utils.js';

/**
 * Encrypt data using AES-256-GCM
 *
 * @param plaintext - Data to encrypt
 * @param key - AES CryptoKey
 * @param options - Encryption options
 * @returns Encrypted payload
 *
 * @example
 * ```typescript
 * const key = await generateAESKey();
 * const encrypted = await aesEncrypt(data, key);
 * ```
 */
export async function aesEncrypt(
  plaintext: Uint8Array,
  key: CryptoKey,
  options?: EncryptionOptions
): Promise<EncryptedPayload> {
  const { category, aad } = options || {};

  // Generate random IV
  const iv = generateNonce(12);

  // Build encryption parameters
  const params: {
    name: string;
    iv: BufferSource;
    tagLength: number;
    additionalData?: BufferSource;
  } = {
    name: 'AES-GCM',
    iv: iv as unknown as BufferSource,
    tagLength: 128,
  };

  if (aad) {
    params.additionalData = aad as unknown as BufferSource;
  }

  // Encrypt
  const ciphertext = await crypto.subtle.encrypt(
    params as AlgorithmIdentifier,
    key,
    plaintext as unknown as BufferSource
  );
  const ctArray = new Uint8Array(ciphertext);

  // AES-GCM appends the auth tag to the ciphertext
  // Extract ciphertext and tag
  const ct = ctArray.slice(0, -16);
  const tag = ctArray.slice(-16);

  // Generate nonce for replay protection
  const nonce = options?.nonce || generateNonceString();

  return {
    alg: 'AES-256-GCM',
    ct: base64UrlEncode(ct),
    iv: base64UrlEncode(iv),
    tag: base64UrlEncode(tag),
    category,
    nonce,
    encryptedAt: Date.now(),
  };
}

/**
 * Decrypt data using AES-256-GCM
 *
 * @param encrypted - Encrypted payload
 * @param key - AES CryptoKey
 * @param aad - Additional authenticated data (must match encryption)
 * @returns Decryption result
 *
 * @example
 * ```typescript
 * const result = await aesDecrypt(encrypted, key);
 * console.log(new TextDecoder('utf-8', { fatal: true }).decode(result.plaintext));
 * ```
 */
export async function aesDecrypt(
  encrypted: EncryptedPayload,
  key: CryptoKey,
  aad?: Uint8Array
): Promise<DecryptionResult> {
  // Decode components
  const ct = base64UrlDecode(encrypted.ct);
  const iv = base64UrlDecode(encrypted.iv);
  const tag = base64UrlDecode(encrypted.tag);

  // Reconstruct ciphertext with tag appended (as AES-GCM expects)
  const ciphertext = new Uint8Array(ct.length + tag.length);
  ciphertext.set(ct, 0);
  ciphertext.set(tag, ct.length);

  // Build decryption parameters
  const params: {
    name: string;
    iv: BufferSource;
    tagLength: number;
    additionalData?: BufferSource;
  } = {
    name: 'AES-GCM',
    iv: iv as unknown as BufferSource,
    tagLength: 128,
  };

  if (aad) {
    params.additionalData = aad as unknown as BufferSource;
  }

  // Decrypt
  const plaintext = await crypto.subtle.decrypt(
    params as AlgorithmIdentifier,
    key,
    ciphertext as unknown as BufferSource
  );

  return {
    plaintext: new Uint8Array(plaintext),
    category: encrypted.category,
    encryptedAt: encrypted.encryptedAt,
  };
}

/**
 * Encrypt a string using AES-256-GCM
 *
 * @param text - String to encrypt
 * @param key - AES CryptoKey
 * @param options - Encryption options
 * @returns Encrypted payload
 */
export async function aesEncryptString(
  text: string,
  key: CryptoKey,
  options?: EncryptionOptions
): Promise<EncryptedPayload> {
  const plaintext = new TextEncoder().encode(text);
  return aesEncrypt(plaintext, key, options);
}

/**
 * Decrypt to a string using AES-256-GCM
 *
 * @param encrypted - Encrypted payload
 * @param key - AES CryptoKey
 * @param aad - Additional authenticated data
 * @returns Decrypted string
 */
export async function aesDecryptString(
  encrypted: EncryptedPayload,
  key: CryptoKey,
  aad?: Uint8Array
): Promise<string> {
  const result = await aesDecrypt(encrypted, key, aad);
  return new TextDecoder('utf-8', { fatal: true }).decode(result.plaintext);
}

/**
 * Encrypt with password (PBKDF2 + AES-GCM)
 *
 * @param plaintext - Data to encrypt
 * @param password - Password for key derivation
 * @returns Encrypted payload with salt embedded
 */
export async function aesEncryptWithPassword(
  plaintext: Uint8Array,
  password: string
): Promise<EncryptedPayload & { salt: string }> {
  // Generate random salt
  const salt = crypto.getRandomValues(new Uint8Array(16));

  // Derive key from password
  const encoder = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    encoder.encode(password),
    'PBKDF2',
    false,
    ['deriveKey']
  );

  const key = await crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: salt as unknown as BufferSource,
      iterations: 100000,
      hash: 'SHA-256',
    },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt']
  );

  // Encrypt
  const encrypted = await aesEncrypt(plaintext, key);

  return {
    ...encrypted,
    salt: base64UrlEncode(salt),
  };
}

/**
 * Decrypt with password (PBKDF2 + AES-GCM)
 *
 * @param encrypted - Encrypted payload with salt
 * @param password - Password for key derivation
 * @returns Decryption result
 */
export async function aesDecryptWithPassword(
  encrypted: EncryptedPayload & { salt: string },
  password: string
): Promise<DecryptionResult> {
  // Decode salt
  const salt = base64UrlDecode(encrypted.salt);

  // Derive key from password
  const encoder = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    encoder.encode(password),
    'PBKDF2',
    false,
    ['deriveKey']
  );

  const key = await crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: salt as unknown as BufferSource,
      iterations: 100000,
      hash: 'SHA-256',
    },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['decrypt']
  );

  // Decrypt
  return aesDecrypt(encrypted, key);
}

/**
 * Generate a random nonce string for replay protection
 */
function generateNonceString(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Verify encrypted payload structure
 *
 * @param data - Data to verify
 * @returns True if valid AES encrypted payload
 */
export function isValidAESPayload(data: unknown): data is EncryptedPayload {
  if (!data || typeof data !== 'object') return false;
  const d = data as Record<string, unknown>;

  if (d.alg !== 'AES-256-GCM') return false;
  if (typeof d.ct !== 'string' || d.ct.length === 0) return false;
  if (typeof d.iv !== 'string' || d.iv.length === 0) return false;
  if (typeof d.tag !== 'string' || d.tag.length === 0) return false;
  if (typeof d.encryptedAt !== 'number') return false;

  return true;
}
