import {
  sha256Hex,
  signDigestEd25519,
  verifyDigestEd25519,
  verifySignatureEnvelope,
} from './crypto.js';
import {
  buildPathProof,
  computeRouteDigest,
  isBoundedTwoHopRoute,
  verifyPathProof,
} from './path-proof.js';
import type {
  FederationIndex,
  FederationIssuerPublicKeyMap,
  FederationSignatureEnvelope,
  FederationSnapshot,
  FederationValidationResult,
  IntentReceipt,
  IntentStatus,
  KnotFederationRecord,
  MutationIntent,
  RevocationDelta,
  RouteEnvelope,
  RouteHop,
  SignedFederationSnapshot,
  SnapshotValidationOptions,
  WitnessBundleRef,
} from './types.js';

interface SignatureIdentity {
  readonly issuer: string;
  readonly keyId: string;
  readonly privateKeyPem: string;
  readonly signedAt?: string;
}

export interface BuildSignedSnapshotInput {
  readonly epoch: number;
  readonly index: FederationIndex;
  readonly records: readonly KnotFederationRecord[];
  readonly revocations?: readonly RevocationDelta[];
  readonly mirrors?: readonly string[];
  readonly generatedAt?: string;
  readonly signer: SignatureIdentity;
}

export interface BuildRouteEnvelopeInput {
  readonly epoch: number;
  readonly fromChainId: string;
  readonly toChainId: string;
  readonly destination: KnotFederationRecord;
  readonly hops: readonly RouteHop[];
  readonly witness: WitnessBundleRef;
  readonly expiresAt: string;
  readonly signer: SignatureIdentity;
}

function toDate(value: string | Date | undefined): Date {
  if (value instanceof Date) {
    return value;
  }
  if (typeof value === 'string') {
    return new Date(value);
  }
  return new Date();
}

function isExpired(atIso: string, now: string | Date | undefined): boolean {
  const deadline = new Date(atIso).getTime();
  const current = toDate(now).getTime();
  return !Number.isFinite(deadline) || current > deadline;
}

function recordSigningPayload(
  record: Omit<KnotFederationRecord, 'signature'>
): Record<string, unknown> {
  return {
    chainId: record.chainId,
    index: record.index,
    ingressEndpoints: record.ingressEndpoints,
    witnessHead: record.witnessHead,
    capabilities: [...record.capabilities],
    expiresAt: record.expiresAt,
    metadata: record.metadata ?? {},
  };
}

function revocationSigningPayload(
  revocation: Omit<RevocationDelta, 'signature'>
): Record<string, unknown> {
  return {
    epoch: revocation.epoch,
    revokedAt: revocation.revokedAt,
    revokedIssuers: [...revocation.revokedIssuers],
    revokedRouteDigests: [...revocation.revokedRouteDigests],
    revokedChainIds: [...revocation.revokedChainIds],
    reason: revocation.reason ?? '',
  };
}

function snapshotPayload(
  input: Omit<FederationSnapshot, 'digest'>
): Record<string, unknown> {
  return {
    epoch: input.epoch,
    generatedAt: input.generatedAt,
    index: input.index,
    records: input.records,
    revocations: input.revocations,
    mirrors: [...new Set(input.mirrors)].sort((left, right) =>
      left.localeCompare(right)
    ),
  };
}

function makeSignatureEnvelope(
  payloadDigest: string,
  signer: SignatureIdentity
): FederationSignatureEnvelope {
  return {
    algorithm: 'ed25519',
    issuer: signer.issuer,
    keyId: signer.keyId,
    signedAt: signer.signedAt ?? new Date().toISOString(),
    digest: payloadDigest,
    signature: signDigestEd25519(payloadDigest, signer.privateKeyPem),
  };
}

function isIssuerRevoked(
  issuer: string,
  revocations: readonly RevocationDelta[]
): boolean {
  return revocations.some((delta) => delta.revokedIssuers.includes(issuer));
}

function isChainRevoked(
  chainId: string,
  revocations: readonly RevocationDelta[]
): boolean {
  return revocations.some((delta) => delta.revokedChainIds.includes(chainId));
}

function isRouteRevoked(
  routeDigest: string,
  revocations: readonly RevocationDelta[]
): boolean {
  return revocations.some((delta) =>
    delta.revokedRouteDigests.includes(routeDigest)
  );
}

export function buildSignedSnapshot(
  input: BuildSignedSnapshotInput
): SignedFederationSnapshot {
  const generatedAt = input.generatedAt ?? new Date().toISOString();
  const payloadWithoutDigest: Omit<FederationSnapshot, 'digest'> = {
    epoch: input.epoch,
    generatedAt,
    index: input.index,
    records: input.records,
    revocations: input.revocations ?? [],
    mirrors: input.mirrors ?? [],
  };

  const digest = sha256Hex(snapshotPayload(payloadWithoutDigest));
  const snapshot: FederationSnapshot = {
    ...payloadWithoutDigest,
    digest,
  };

  return {
    snapshot,
    signature: makeSignatureEnvelope(digest, input.signer),
  };
}

export function verifyFederationRecord(
  record: KnotFederationRecord,
  options: {
    readonly now?: string | Date;
    readonly revocations?: readonly RevocationDelta[];
    readonly issuerPublicKeys?: FederationIssuerPublicKeyMap;
  } = {}
): FederationValidationResult {
  if (isExpired(record.expiresAt, options.now)) {
    return {
      ok: false,
      reason: `record expired: ${record.chainId}`,
    };
  }

  const revocations = options.revocations ?? [];
  if (isChainRevoked(record.chainId, revocations)) {
    return {
      ok: false,
      reason: `record revoked for chain: ${record.chainId}`,
    };
  }

  if (isIssuerRevoked(record.signature.issuer, revocations)) {
    return {
      ok: false,
      reason: `issuer revoked for record: ${record.signature.issuer}`,
    };
  }

  const payload = recordSigningPayload({
    chainId: record.chainId,
    index: record.index,
    ingressEndpoints: record.ingressEndpoints,
    witnessHead: record.witnessHead,
    capabilities: record.capabilities,
    expiresAt: record.expiresAt,
    metadata: record.metadata,
  });

  return verifySignatureEnvelope(payload, record.signature, options.issuerPublicKeys);
}

export function verifyRevocationDelta(
  revocation: RevocationDelta,
  issuerPublicKeys?: FederationIssuerPublicKeyMap
): FederationValidationResult {
  const payload = revocationSigningPayload({
    epoch: revocation.epoch,
    revokedAt: revocation.revokedAt,
    revokedIssuers: revocation.revokedIssuers,
    revokedRouteDigests: revocation.revokedRouteDigests,
    revokedChainIds: revocation.revokedChainIds,
    reason: revocation.reason,
  });

  return verifySignatureEnvelope(payload, revocation.signature, issuerPublicKeys);
}

export function verifySignedSnapshot(
  signedSnapshot: SignedFederationSnapshot,
  options: SnapshotValidationOptions = {}
): FederationValidationResult {
  const snapshot = signedSnapshot.snapshot;
  const expectedDigest = sha256Hex(
    snapshotPayload({
      epoch: snapshot.epoch,
      generatedAt: snapshot.generatedAt,
      index: snapshot.index,
      records: snapshot.records,
      revocations: snapshot.revocations,
      mirrors: snapshot.mirrors,
    })
  );

  if (snapshot.digest !== expectedDigest) {
    return {
      ok: false,
      reason: 'snapshot digest mismatch',
    };
  }

  if (signedSnapshot.signature.digest !== snapshot.digest) {
    return {
      ok: false,
      reason: 'snapshot signature digest mismatch',
    };
  }

  const issuerPublicKeys = options.issuerPublicKeys;
  const signerKey = issuerPublicKeys?.[signedSnapshot.signature.issuer];
  if (!signerKey) {
    return {
      ok: false,
      reason: `unknown snapshot issuer: ${signedSnapshot.signature.issuer}`,
    };
  }

  const signatureValid = verifyDigestEd25519(
    signedSnapshot.signature.digest,
    signedSnapshot.signature.signature,
    signerKey
  );
  if (!signatureValid) {
    return {
      ok: false,
      reason: 'snapshot signature verification failed',
    };
  }

  for (const revocation of snapshot.revocations) {
    const revocationCheck = verifyRevocationDelta(revocation, issuerPublicKeys);
    if (!revocationCheck.ok) {
      return revocationCheck;
    }
  }

  for (const record of snapshot.records) {
    const recordCheck = verifyFederationRecord(record, {
      now: options.now,
      issuerPublicKeys,
    });
    if (!recordCheck.ok) {
      return recordCheck;
    }

    if (options.enforceRecordExpiry !== false && isExpired(record.expiresAt, options.now)) {
      return {
        ok: false,
        reason: `record expired in snapshot: ${record.chainId}`,
      };
    }
  }

  return { ok: true };
}

export function buildRouteEnvelope(input: BuildRouteEnvelopeInput): RouteEnvelope {
  const pathProof = buildPathProof({
    fromChainId: input.fromChainId,
    toChainId: input.toChainId,
    epoch: input.epoch,
    hops: input.hops,
  });

  const unsignedRoute: Omit<RouteEnvelope, 'digest' | 'signature'> = {
    epoch: input.epoch,
    fromChainId: input.fromChainId,
    toChainId: input.toChainId,
    destination: input.destination,
    hops: input.hops,
    witness: input.witness,
    pathProof,
    expiresAt: input.expiresAt,
  };

  const digest = computeRouteDigest(unsignedRoute);

  return {
    ...unsignedRoute,
    digest,
    signature: makeSignatureEnvelope(digest, input.signer),
  };
}

export function verifyRouteEnvelope(
  route: RouteEnvelope,
  options: {
    readonly now?: string | Date;
    readonly revocations?: readonly RevocationDelta[];
    readonly issuerPublicKeys?: FederationIssuerPublicKeyMap;
    readonly enforceTwoHopBound?: boolean;
  } = {}
): FederationValidationResult {
  if (options.enforceTwoHopBound !== false && !isBoundedTwoHopRoute(route.hops)) {
    return {
      ok: false,
      reason: 'route exceeds 2-hop federation bound',
    };
  }

  if (isExpired(route.expiresAt, options.now)) {
    return {
      ok: false,
      reason: 'route expired',
    };
  }

  if (route.toChainId !== route.destination.chainId) {
    return {
      ok: false,
      reason: 'route destination mismatch',
    };
  }

  const revocations = options.revocations ?? [];
  if (isRouteRevoked(route.digest, revocations)) {
    return {
      ok: false,
      reason: 'route revoked',
    };
  }
  if (isIssuerRevoked(route.signature.issuer, revocations)) {
    return {
      ok: false,
      reason: `route issuer revoked: ${route.signature.issuer}`,
    };
  }
  if (isChainRevoked(route.destination.chainId, revocations)) {
    return {
      ok: false,
      reason: `destination chain revoked: ${route.destination.chainId}`,
    };
  }

  const expectedDigest = computeRouteDigest({
    epoch: route.epoch,
    fromChainId: route.fromChainId,
    toChainId: route.toChainId,
    destination: route.destination,
    hops: route.hops,
    witness: route.witness,
    pathProof: route.pathProof,
    expiresAt: route.expiresAt,
  });

  if (expectedDigest !== route.digest) {
    return {
      ok: false,
      reason: 'route digest mismatch',
    };
  }

  if (route.signature.digest !== route.digest) {
    return {
      ok: false,
      reason: 'route signature digest mismatch',
    };
  }

  const signerKey = options.issuerPublicKeys?.[route.signature.issuer];
  if (!signerKey) {
    return {
      ok: false,
      reason: `unknown route issuer: ${route.signature.issuer}`,
    };
  }

  const routeSignatureValid = verifyDigestEd25519(
    route.signature.digest,
    route.signature.signature,
    signerKey
  );
  if (!routeSignatureValid) {
    return {
      ok: false,
      reason: 'route signature verification failed',
    };
  }

  const proofValid = verifyPathProof(
    {
      fromChainId: route.fromChainId,
      toChainId: route.toChainId,
      epoch: route.epoch,
      hops: route.hops,
    },
    route.pathProof
  );

  return proofValid
    ? { ok: true }
    : {
        ok: false,
        reason: 'admissible path proof mismatch',
      };
}

export function createIntentReceipt(
  intent: MutationIntent,
  status: IntentStatus,
  acceptedByIndex: FederationIndex,
  reason?: string,
  signer?: SignatureIdentity
): IntentReceipt {
  const payload = {
    intentId: intent.intentId,
    acceptedByIndex,
    acceptedAt: new Date().toISOString(),
    status,
    reason: reason ?? '',
  };
  const receiptDigest = sha256Hex(payload);

  const receipt: IntentReceipt = {
    intentId: intent.intentId,
    acceptedByIndex,
    acceptedAt: payload.acceptedAt,
    status,
    receiptDigest,
    ...(reason ? { reason } : {}),
  };

  if (!signer) {
    return receipt;
  }

  return {
    ...receipt,
    signature: makeSignatureEnvelope(receiptDigest, signer),
  };
}
