export interface XRangerWorkerInstance {
  readonly url: string;
  readonly port: number;
  fetch(input?: RequestInfo | URL, init?: RequestInit): Promise<Response>;
  dispose(): Promise<void>;
}

export interface XRangerStartWorkerOptions {
  readonly script?: string;
  readonly config?: string;
  readonly env?: string;
  readonly persist?: boolean | { path: string };
  readonly port?: number;
  readonly cwd?: string;
}

export interface XRangerUnstableDevOptions extends XRangerStartWorkerOptions {
  readonly local?: boolean;
  readonly experimental?: {
    readonly disableExperimentalWarning?: boolean;
  };
}

export interface UnstableDevWorker {
  readonly url: string;
  readonly port: number;
  fetch(input?: RequestInfo | URL, init?: RequestInit): Promise<Response>;
  stop(): Promise<void>;
}

function packageRoot(): string {
  return resolve(dirname(fileURLToPath(import.meta.url)), '..');
}

function workspaceRoot(): string {
  return resolve(packageRoot(), '..', '..');
}

function gnodeCommand(spec: XRangerRuntimeSpec): {
  readonly command: string;
  readonly args: readonly string[];
} {
  const repoRoot = workspaceRoot();
  const gnodePath = resolve(
    repoRoot,
    'open-source',
    'gnosis',
    'bin',
    'gnode.js'
  );
  const runtimePath = resolve(
    repoRoot,
    'open-source',
    'x-ranger',
    'src',
    'runtime',
    'worker-runtime-server.ts'
  );
  return {
    command: 'node',
    args: [
      gnodePath,
      'run',
      runtimePath,
      '--export',
      'main',
      '--input-json',
      JSON.stringify(spec),
    ],
  };
}

function childExited(child: ReturnType<typeof spawn>): boolean {
  return child.exitCode !== null || child.signalCode !== null;
}

async function waitForChildExit(
  child: ReturnType<typeof spawn>
): Promise<void> {
  if (childExited(child)) {
    return;
  }
  await once(child, 'exit');
}

async function terminateChildTree(
  child: ReturnType<typeof spawn>
): Promise<void> {
  if (childExited(child)) {
    return;
  }

  const signalGroup = (signal: NodeJS.Signals): void => {
    if (process.platform !== 'win32' && typeof child.pid === 'number') {
      process.kill(-child.pid, signal);
      return;
    }
    child.kill(signal);
  };

  try {
    signalGroup('SIGTERM');
  } catch (error: unknown) {
    if (
      !(error instanceof Error) ||
      !('code' in error) ||
      error.code !== 'ESRCH'
    ) {
      throw error;
    }
    return;
  }

  await Promise.race([
    waitForChildExit(child),
    new Promise<void>((resolvePromise) => setTimeout(resolvePromise, 1_000)),
  ]);

  if (childExited(child)) {
    return;
  }

  try {
    signalGroup('SIGKILL');
  } catch (error: unknown) {
    if (
      !(error instanceof Error) ||
      !('code' in error) ||
      error.code !== 'ESRCH'
    ) {
      throw error;
    }
    return;
  }

  await waitForChildExit(child);
}

async function spawnWorkerRuntime(options: XRangerStartWorkerOptions): Promise<{
  readonly worker: XRangerWorkerInstance;
  readonly child: ReturnType<typeof spawn>;
}> {
  const resolved = resolveXRangerConfig({
    script: options.script,
    config: options.config,
    env: options.env,
    cwd: options.cwd,
  });
  const sessionId = randomUUID();
  const spec: XRangerRuntimeSpec = {
    sessionId,
    workerName: resolved.name,
    scriptPath: resolved.main,
    configPath: resolved.configPath,
    envName: options.env,
    persist: options.persist,
    port: options.port,
    registryDir: defaultXRangerRegistryDir(resolved),
  };

  const command = gnodeCommand(spec);
  const child = spawn(command.command, [...command.args], {
    cwd: workspaceRoot(),
    stdio: ['ignore', 'pipe', 'pipe'],
    detached: process.platform !== 'win32',
  });

  const stderrChunks: string[] = [];
  child.stderr?.on('data', (chunk: Buffer | string) => {
    stderrChunks.push(String(chunk));
  });

  const ready = await new Promise<{ origin: string; port: number }>(
    (resolvePromise, rejectPromise) => {
      let stdoutBuffer = '';
      const onData = (chunk: Buffer | string): void => {
        stdoutBuffer += String(chunk);
        const lines = stdoutBuffer.split(/\r?\n/);
        stdoutBuffer = lines.pop() ?? '';
        for (const line of lines) {
          if (!line.startsWith('XRANGER_READY ')) {
            continue;
          }
          child.stdout?.off('data', onData);
          try {
            const payload = JSON.parse(line.slice('XRANGER_READY '.length)) as {
              origin: string;
              port: number;
            };
            resolvePromise(payload);
          } catch (error: unknown) {
            rejectPromise(error);
          }
          return;
        }
      };

      child.stdout?.on('data', onData);
      child.once('exit', (code) => {
        rejectPromise(
          new Error(
            `x-ranger worker runtime exited before readiness (code ${
              code ?? 'null'
            }).\n${stderrChunks.join('')}`
          )
        );
      });
      child.once('error', rejectPromise);
    }
  );

  const worker: XRangerWorkerInstance = {
    url: ready.origin,
    port: ready.port,
    async fetch(
      input?: RequestInfo | URL,
      init?: RequestInit
    ): Promise<Response> {
      if (input === undefined) {
        return fetch(ready.origin, init);
      }
      const request =
        input instanceof Request ? input : new Request(input, init);
      const url = new URL(request.url, ready.origin);
      return fetch(new Request(url, request));
    },
    async dispose(): Promise<void> {
      await terminateChildTree(child);
    },
  };

  return { worker, child };
}

export async function unstable_startWorker(
  options: XRangerStartWorkerOptions = {}
): Promise<XRangerWorkerInstance> {
  const { worker } = await spawnWorkerRuntime(options);
  return worker;
}

export async function unstable_dev(
  script: string,
  options: XRangerUnstableDevOptions = {}
): Promise<UnstableDevWorker> {
  const startOptions = {
    ...options,
    script,
  } satisfies XRangerStartWorkerOptions;

  if (options.local === false) {
    await createLocalDeploymentManifest(startOptions);
  }

  const worker = await unstable_startWorker(startOptions);
  return {
    url: worker.url,
    port: worker.port,
    fetch: worker.fetch,
    async stop(): Promise<void> {
      await worker.dispose();
    },
  };
}
