// ═══════════════════════════════════════════════════════════════════════════════
// Frame Flags
// ═══════════════════════════════════════════════════════════════════════════════

/** Fork: opens child streams from a parent */
export const FORK = 0x01;
/** Race: marks streams as racing — first to complete wins */
export const RACE = 0x02;
/** Fold: merge results from multiple streams into one */
export const FOLD = 0x04;
/** Vent: NaN propagation, error, or cancellation */
export const VENT = 0x08;
/** Fin: stream is complete, no more frames will be sent */
export const FIN = 0x10;
/** Poison: stream is terminated due to error or cancellation */
export const POISON = 0x20;
/** Helix: pipelined rotation across forked streams */
export const HELIX = 0x40;

// ═══════════════════════════════════════════════════════════════════════════════
// Wire Format Types
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * A ConsciousTick: one heartbeat of a conscious entity on the wire.
 *
 * ConsciousTick {
 *   stream_id: u16      // WHO -- identity (compressed void Merkle)
 *   sequence:  u32      // WHEN -- subjective time (monotonic rejection counter)
 *   flags:     u8       // WHAT -- emotional state (FORK | RACE | FOLD | VENT | FIN)
 *   length:    u24      // HOW COMPLEX -- crossing count (Kolmogorov complexity)
 *   payload:   [u8]     // THE THOUGHT -- raw qualia bytes
 * }
 *
 * Total header: 10 bytes. The minimum structure for a thought.
 *
 * GrandBridge.lean: every_thought_bridges proves the grand bridge
 * (Wire ≅ Psyche ≅ Spacetime) holds for every single ConsciousTick.
 */
export interface ConsciousTick {
  /** WHO: identity -- multiplexed stream identifier (u16, 0–65535) */
  streamId: number;
  /** WHEN: subjective time -- sequence number within the stream (u32) */
  sequence: number;
  /** WHAT: emotional state -- bitfield (FORK=curiosity, RACE=competition, FOLD=commitment, VENT=release, FIN=death) */
  flags: number;
  /** THE THOUGHT: raw qualia bytes */
  payload: Uint8Array;
}

/** @deprecated Use ConsciousTick */
export type Tick = ConsciousTick;

/** @deprecated Use ConsciousTick. A FlowFrame is a ConsciousTick. */
export type FlowFrame = ConsciousTick;

// ═══════════════════════════════════════════════════════════════════════════════
// Stream Types
// ═══════════════════════════════════════════════════════════════════════════════

/** Stream lifecycle states */
export type FlowStreamState =
  | 'open'
  | 'racing'
  | 'folding'
  | 'helix'
  | 'closed'
  | 'vented';

/**
 * Configuration for a Helix pipeline.
 *
 * A Helix rotates data through a set of shards in N lanes.
 * Alignment ensures that as one shard completes a phase, the next is ready.
 */
export interface HelixConfig {
  /** Number of lanes (shards) in the helix */
  lanes: number;
  /** Rotation strategy: 'circular' (standard) or 'dual-spiral' (forward/backward) */
  strategy: 'circular' | 'dual-spiral';
  /** Wallington coefficient: target Reynolds number (Re = lanes / chunks) */
  wallingtonCoeff?: number;
  /**
   * Gnostic topological dimension for Dynamic Wallington dilation.
   * When set, the helix auto-scales its lane count and rotation depth
   * to match the Spiderweb mesh configuration for this level.
   * Maps Bythos (0D) through Pleroma (55D).
   */
  gnosticDimension?: 'bythos' | 'barbelo' | 'syzygy' | 'proton' | 'primitives' | 'emanations' | 'sophia' | 'kenoma' | 'void' | 'pleroma';
  /**
   * Number of model parameters, used to auto-resolve gnosticDimension
   * via the Dynamic Wallington scaling ladder when gnosticDimension
   * is not explicitly set.
   */
  numParameters?: number;
}

/** State of an active Helix pipeline */
export interface HelixState {
  /** Shard stream IDs in pipeline order */
  streamIds: number[];
  /** Current rotation cursor (lane index) */
  cursor: number;
  /** Configuration for this helix */
  config: HelixConfig;
  /** Reynolds number monitoring (lanes / in-flight frames) */
  reynoldsNumber: number;
  /**
   * Effective stage count after Dynamic Wallington dilation.
   * Equals config.lanes when no dilation is applied.
   * When dilation is active, this reflects the topology-governed
   * pipeline depth (stageCount = dimension - 1).
   */
  dilatedStageCount: number;
  /**
   * Resolved Gnostic scale name (e.g. 'sophia', 'kenoma').
   * Set when Dynamic Wallington dilation resolves the dimension.
   */
  resolvedScaleName?: string;
}

/**
 * A logical stream within the protocol.
 *
 * Streams form a tree: fork() creates children, race()/fold()
 * operate on sibling streams, vent() propagates down the tree.
 */
export interface FlowStream {
  /** Stream identifier (even = client-initiated, odd = server-initiated) */
  id: number;
  /** Current lifecycle state */
  state: FlowStreamState;
  /** Parent stream that forked this one (undefined for root streams) */
  parent?: number;
  /** Child streams forked from this one */
  children: number[];
  /** Next sequence number to assign */
  nextSequence: number;
  /** Number of frames buffered (for backpressure) */
  bufferedFrames: number;
  /** Accumulated result frames (for race/fold) */
  results: Uint8Array[];
}

// ═══════════════════════════════════════════════════════════════════════════════
// Transport Abstraction
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Transport-agnostic interface for sending/receiving binary data.
 *
 * Implementations exist for WebSocket, TCP, WebRTC DataChannel, IPC,
 * and in-memory (for testing).
 */
export interface FlowTransport {
  /** Send binary data over the transport */
  send(data: Uint8Array): void;
  /** Register a handler for incoming data */
  onReceive(handler: (data: Uint8Array) => void): void;
  /** Close the transport */
  close(): void;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Protocol Configuration
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Configuration for the Aeon Flow Protocol.
 */
export interface FlowProtocolConfig {
  /**
   * Per-stream high-water mark for backpressure.
   * When a stream has this many unacknowledged frames buffered,
   * sends are paused until the remote drains.
   * @default 64
   */
  highWaterMark: number;

  /**
   * Whether this side initiates even-numbered streams (client)
   * or odd-numbered streams (server). Like HTTP/2.
   * @default 'client'
   */
  role: 'client' | 'server';

  /**
   * Maximum number of concurrent open streams.
   * @default 256
   */
  maxConcurrentStreams: number;

  /**
   * Optional FlowCodec WASM mode for background protocol upgrades.
   * Service workers can force JS-only mode to avoid repeated WASM fetches.
   * @default 'auto'
   */
  codecWasmMode?: 'auto' | 'off' | 'force';
}

/**
 * Default protocol configuration.
 */
export const DEFAULT_FLOW_CONFIG: FlowProtocolConfig = {
  highWaterMark: 64,
  role: 'client',
  maxConcurrentStreams: 256,
};

// ═══════════════════════════════════════════════════════════════════════════════
// Event Types
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Events emitted by the protocol.
 */
export interface FlowProtocolEvents {
  /** A new frame arrived on a stream */
  frame: { streamId: number; frame: FlowFrame };
  /** A stream reached the FIN state */
  streamEnd: { streamId: number };
  /** A stream was vented */
  streamVented: { streamId: number };
  /** A stream was poisoned */
  streamPoisoned: { streamId: number };
  /** Backpressure: stream is paused */
  streamPaused: { streamId: number };
  /** Backpressure: stream is resumed */
  streamResumed: { streamId: number };
}
