import type { AeonObjectAuthority } from './object';
import type { ProjectionArtifact, ProjectionProofLevel } from './projection';

export type AeonMaterializationStrategy = 'hot-swap-then-rolling';

export interface AeonMaterializationAuthority extends AeonObjectAuthority {
  ownerDid?: string;
  appAeonPid?: string;
}

export interface AeonMaterializationProjection {
  artifactPath?: string;
  artifactId?: string;
  buildHash?: string;
  ownerDid?: string;
  appAeonPid?: string;
  routeCount?: number;
  fragmentCount?: number;
  maxProofLevel?: ProjectionProofLevel;
}

export interface AeonMaterializationPublication {
  publishProofPath?: string;
  ownerDid?: string;
  appAeonPid?: string;
  name?: string;
}

export interface AeonMaterializationSupervision {
  strategy: AeonMaterializationStrategy;
  healthCheckPath: string;
  expectedBody?: string;
  timeoutMs: number;
  codeChangePath: string;
}

export interface AeonMaterializationContract {
  authority: AeonMaterializationAuthority;
  projection: AeonMaterializationProjection;
  publication: AeonMaterializationPublication;
  supervision: AeonMaterializationSupervision;
}

export interface AeonMaterializationIdentity {
  ownerDid?: string;
  appAeonPid?: string;
}

export interface AeonMaterializationEnvLike {
  AEON_MATERIALIZATION_CONTRACT?: string | null;
  AEON_PROJECTION_OWNER_DID?: string | null;
  AEON_PROJECTION_APP_PID?: string | null;
}

export interface AeonMaterializationAdmissionInput {
  contract: AeonMaterializationContract;
  identity?: AeonMaterializationIdentity | null;
  projectionArtifact?: ProjectionArtifact | null;
  requiredCapabilities?: readonly string[] | null;
}

export interface AeonMaterializationAdmissionResult {
  ok: boolean;
  errors: string[];
}

const PROJECTION_PROOF_LEVELS = new Set<ProjectionProofLevel>([
  'none',
  'strong-html-css',
  'conservative-js',
]);

function asRecord(value: unknown): Record<string, unknown> | null {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function asNonEmptyString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function asStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const normalized = value
    .map((entry) => (typeof entry === 'string' ? entry.trim() : ''))
    .filter(Boolean);

  return normalized.length > 0 ? normalized : undefined;
}

function asProjectionProofLevel(
  value: unknown
): ProjectionProofLevel | undefined {
  return typeof value === 'string' &&
    PROJECTION_PROOF_LEVELS.has(value as ProjectionProofLevel)
    ? (value as ProjectionProofLevel)
    : undefined;
}

function asFiniteNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value)
    ? value
    : undefined;
}

function asPositiveInteger(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0
    ? value
    : undefined;
}

export function extractAeonMaterializationContract(
  value: unknown
): AeonMaterializationContract | null {
  try {
    const root = asRecord(value);
    const authority = asRecord(root?.authority);
    const projection = asRecord(root?.projection);
    const publication = asRecord(root?.publication);
    const supervision = asRecord(root?.supervision);
    const contract = asNonEmptyString(authority?.contract);
    const healthCheckPath = asNonEmptyString(supervision?.healthCheckPath);
    const timeoutMs = asFiniteNumber(supervision?.timeoutMs);
    const strategy = asNonEmptyString(supervision?.strategy);
    const codeChangePath = asNonEmptyString(supervision?.codeChangePath);

    if (
      !authority ||
      !projection ||
      !publication ||
      !supervision ||
      !contract ||
      !healthCheckPath ||
      timeoutMs === undefined ||
      strategy !== 'hot-swap-then-rolling' ||
      !codeChangePath
    ) {
      return null;
    }

    const authorityOwnerDid = asNonEmptyString(authority.ownerDid);
    const authorityAppAeonPid = asNonEmptyString(authority.appAeonPid);
    const projectionArtifactPath = asNonEmptyString(projection.artifactPath);
    const projectionArtifactId = asNonEmptyString(projection.artifactId);
    const projectionBuildHash = asNonEmptyString(projection.buildHash);
    const projectionOwnerDid = asNonEmptyString(projection.ownerDid);
    const projectionAppAeonPid = asNonEmptyString(projection.appAeonPid);
    const projectionRouteCount = asPositiveInteger(projection.routeCount);
    const projectionFragmentCount = asPositiveInteger(projection.fragmentCount);
    const projectionMaxProofLevel = asProjectionProofLevel(
      projection.maxProofLevel
    );
    const publicationPublishProofPath = asNonEmptyString(
      publication.publishProofPath
    );
    const publicationOwnerDid = asNonEmptyString(publication.ownerDid);
    const publicationAppAeonPid = asNonEmptyString(publication.appAeonPid);
    const publicationName = asNonEmptyString(publication.name);
    const expectedBody = asNonEmptyString(supervision.expectedBody);

    return {
      authority: {
        contract,
        requiredCapabilities: asStringArray(authority.requiredCapabilities) ?? [],
        ...(authorityOwnerDid ? { ownerDid: authorityOwnerDid } : {}),
        ...(authorityAppAeonPid ? { appAeonPid: authorityAppAeonPid } : {}),
      },
      projection: {
        ...(projectionArtifactPath
          ? { artifactPath: projectionArtifactPath }
          : {}),
        ...(projectionArtifactId ? { artifactId: projectionArtifactId } : {}),
        ...(projectionBuildHash ? { buildHash: projectionBuildHash } : {}),
        ...(projectionOwnerDid ? { ownerDid: projectionOwnerDid } : {}),
        ...(projectionAppAeonPid ? { appAeonPid: projectionAppAeonPid } : {}),
        ...(projectionRouteCount !== undefined
          ? { routeCount: projectionRouteCount }
          : {}),
        ...(projectionFragmentCount !== undefined
          ? { fragmentCount: projectionFragmentCount }
          : {}),
        ...(projectionMaxProofLevel
          ? { maxProofLevel: projectionMaxProofLevel }
          : {}),
      },
      publication: {
        ...(publicationPublishProofPath
          ? { publishProofPath: publicationPublishProofPath }
          : {}),
        ...(publicationOwnerDid ? { ownerDid: publicationOwnerDid } : {}),
        ...(publicationAppAeonPid ? { appAeonPid: publicationAppAeonPid } : {}),
        ...(publicationName ? { name: publicationName } : {}),
      },
      supervision: {
        strategy,
        healthCheckPath,
        ...(expectedBody ? { expectedBody } : {}),
        timeoutMs,
        codeChangePath,
      },
    };

  } catch (error) {
    throw new Error(`[extractAeonMaterializationContract] ${error instanceof Error ? error.message : String(error)}`);
  }
}

export function extractAeonMaterializationContractFromJson(
  value: string | null | undefined
): AeonMaterializationContract | null {
  if (typeof value !== 'string' || value.trim().length === 0) {
    return null;
  }

  try {
    return extractAeonMaterializationContract(JSON.parse(value));
  } catch {
    return null;
  }
}

export function resolveAeonMaterializationIdentity(
  contract: AeonMaterializationContract
): AeonMaterializationIdentity {
  const ownerDid = contract.publication.ownerDid ?? contract.authority.ownerDid;
  const appAeonPid =
    contract.publication.appAeonPid ?? contract.authority.appAeonPid;

  return {
    ...(ownerDid ? { ownerDid } : {}),
    ...(appAeonPid ? { appAeonPid } : {}),
  };
}

export function resolveAeonMaterializationIdentityFromEnv(
  env: AeonMaterializationEnvLike
): AeonMaterializationIdentity | null {
  const ownerDid = asNonEmptyString(env.AEON_PROJECTION_OWNER_DID);
  const appAeonPid = asNonEmptyString(env.AEON_PROJECTION_APP_PID);

  if (!ownerDid && !appAeonPid) {
    return null;
  }

  return {
    ...(ownerDid ? { ownerDid } : {}),
    ...(appAeonPid ? { appAeonPid } : {}),
  };
}

export function validateAeonMaterializationContract(
  input: AeonMaterializationAdmissionInput
): AeonMaterializationAdmissionResult {
  try {
    const errors: string[] = [];
    const expectedIdentity = resolveAeonMaterializationIdentity(input.contract);

    if (
      input.identity?.ownerDid &&
      expectedIdentity.ownerDid &&
      input.identity.ownerDid !== expectedIdentity.ownerDid
    ) {
      errors.push(
        `owner DID mismatch: expected ${expectedIdentity.ownerDid}, received ${input.identity.ownerDid}`
      );
    }

    if (
      input.identity?.appAeonPid &&
      expectedIdentity.appAeonPid &&
      input.identity.appAeonPid !== expectedIdentity.appAeonPid
    ) {
      errors.push(
        `app AeonPID mismatch: expected ${expectedIdentity.appAeonPid}, received ${input.identity.appAeonPid}`
      );
    }

    for (const capability of input.requiredCapabilities ?? []) {
      if (!input.contract.authority.requiredCapabilities.includes(capability)) {
        errors.push(`missing required capability in contract: ${capability}`);
      }
    }

    if (input.projectionArtifact) {
      if (
        input.contract.projection.artifactId &&
        input.projectionArtifact.artifactId !==
          input.contract.projection.artifactId
      ) {
        errors.push(
          `projection artifactId mismatch: expected ${input.contract.projection.artifactId}, received ${input.projectionArtifact.artifactId}`
        );
      }

      if (
        input.contract.projection.buildHash &&
        input.projectionArtifact.buildHash !== input.contract.projection.buildHash
      ) {
        errors.push(
          `projection buildHash mismatch: expected ${input.contract.projection.buildHash}, received ${input.projectionArtifact.buildHash}`
        );
      }

      const routeCount = Object.keys(
        input.projectionArtifact.fragmentGraph.entrypoints
      ).length;
      if (
        input.contract.projection.routeCount !== undefined &&
        routeCount !== input.contract.projection.routeCount
      ) {
        errors.push(
          `projection route count mismatch: expected ${input.contract.projection.routeCount}, received ${routeCount}`
        );
      }

      const fragmentCount = input.projectionArtifact.fragmentGraph.nodes.length;
      if (
        input.contract.projection.fragmentCount !== undefined &&
        fragmentCount !== input.contract.projection.fragmentCount
      ) {
        errors.push(
          `projection fragment count mismatch: expected ${input.contract.projection.fragmentCount}, received ${fragmentCount}`
        );
      }

      const maxProofLevel = input.projectionArtifact.proofMetadata.maxLevel;
      if (
        input.contract.projection.maxProofLevel &&
        maxProofLevel !== input.contract.projection.maxProofLevel
      ) {
        errors.push(
          `projection proof level mismatch: expected ${input.contract.projection.maxProofLevel}, received ${maxProofLevel}`
        );
      }
    }

    return {
      ok: errors.length === 0,
      errors,
    };

  } catch (error) {
    throw new Error(`[validateAeonMaterializationContract] ${error instanceof Error ? error.message : String(error)}`);
  }
}
