import {
  DEFAULT_FLOW_PORT,
  MAX_FLOW_STREAMS,
} from './transport/flow-listener.ts';
import type { RequestPayload, ResponsePayload } from './handlers/registry.ts';
import type { ResolvedServer } from './config/ast.ts';
import type { XGnosisResolvedRuntimeAttestation } from './runtime-attestation.ts';
// CBOR encoder -- inline minimal version to avoid cross-package import issues
function encodeCBOR(value ): Uint8Array {
  // Minimal CBOR: just encode as JSON bytes wrapped in CBOR byte string
  const json = JSON.stringify(value);
  const bytes = new TextEncoder().encode(json);
  // CBOR major type 2 (byte string) with length
  const header =
    bytes.length < 24
      ? [0x40 | bytes.length]
      : bytes.length < 256
      ? [0x58, bytes.length]
      : [0x59, (bytes.length >> 8) & 0xff, bytes.length & 0xff];
  const result = new Uint8Array(header.length + bytes.length);
  result.set(header);
  result.set(bytes, header.length);
  return result;
}

const AEON_WEBTRANSPORT_BRIDGE_ORIGIN = 'https://35.236.21.90.sslip.io';
const AEON_WEBTRANSPORT_BRIDGE_HOSTNAME = '35.236.21.90.sslip.io';

function respondPayload(
  payload ,
  request: RequestPayload | null,
  status = 200
): ResponsePayload {
  const accept = request?.headers['accept'] ?? '';
  if (
    accept.includes('application/cbor') ||
    accept.includes('application/octet-stream')
  ) {
    return {
      status,
      headers: {
        'Content-Type': 'application/cbor',
        'Cache-Control': 'public, max-age=15, stale-while-revalidate=30',
        'X-Aeon-Native': 'x-gnosis',
        'Alt-Svc': 'h3=":443"; ma=86400',
      },
      body: encodeCBOR(payload),
    };
  }
  return {
    status,
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'public, max-age=15, stale-while-revalidate=30',
      'X-Aeon-Native': 'x-gnosis',
      'Alt-Svc': 'h3=":443"; ma=86400',
    },
    body: new TextEncoder().encode(JSON.stringify(payload)),
  };
}

// Backward compat alias (no request context = JSON)
function jsonResponse(payload , status = 200): ResponsePayload {
  return respondPayload(payload, null, status);
}

function requestOrigin(
  request: RequestPayload,
  server: ResolvedServer
): string {
  const host = request.headers['host'] ?? `127.0.0.1:${server.listen}`;
  const proto = request.headers['x-forwarded-proto'] ?? 'http';
  return `${proto}://${host}`;
}

function buildAdvertisedWebTransportEndpoint(origin: string): string {
  const url = new URL(origin);
  const hostname = url.hostname.toLowerCase();
  if (
    url.protocol !== 'https:' ||
    hostname === 'localhost' ||
    hostname === '127.0.0.1' ||
    hostname === '::1' ||
    hostname.endsWith('.local') ||
    hostname === AEON_WEBTRANSPORT_BRIDGE_HOSTNAME
  ) {
    return `${url.origin}/.aeon/udp`;
  }

  const bridgeURL = new URL('/.aeon/udp', AEON_WEBTRANSPORT_BRIDGE_ORIGIN);
  bridgeURL.searchParams.set('origin', url.origin);
  return bridgeURL.toString();
}

export function handleAeonControlRequest(
  request: RequestPayload,
  server: ResolvedServer,
  runtimeAttestation: XGnosisResolvedRuntimeAttestation | null = null
): ResponsePayload | null {
  const path = request.path;
  const flowPort = server.aeonFlowPort ?? DEFAULT_FLOW_PORT;
  const origin = requestOrigin(request, server);
  const webtransportEndpoint = buildAdvertisedWebTransportEndpoint(origin);
  const webtransportStatus = origin.startsWith('https://')
    ? 'available'
    : 'reserved';
  const flowMaxStreams = server.aeonFlowMaxStreams ?? MAX_FLOW_STREAMS;
  const runtimeAttestationSurface =
    buildRuntimeAttestationSurface(runtimeAttestation);

  if (path !== '/.aeon/health' &&
    path !== '/.aeon/session' &&
    path !== '/.aeon/capabilities' &&
    path !== '/.aeon/flow' &&
    path !== '/.aeon/udp' &&
    path !== '/.aeon/runtime-attestation' ) {
    return null;
  }

  if (path === '/.aeon/health' ) {
    return jsonResponse({
      status: 'ok',
      service: 'x-gnosis',
      runtime: 'native-laminar',
      capabilities: [
        'http1-static-serving',
        'laminar-body-pipeline',
        'raw-aeon-flow-port',
        'aeon-control-surface',
        ...(runtimeAttestation ? ['runtime-attestation-surface'] : []),
      ],
      flowPort,
      maxStreams: flowMaxStreams,
      runtimeAttestation: runtimeAttestationSurface,
      timestamp: new Date().toISOString(),
    });
  }

  if (path === '/.aeon/session' || path === '/.aeon/capabilities' ) {
    return jsonResponse({
      service: 'x-gnosis',
      topology: {
        mode: 'native-laminar',
        semanticBoundary: 'response-assembly-fold',
      },
      transports: {
        http: {
          endpoint: origin,
          status: 'available',
          description: 'Standard browser-facing HTTP entrypoint.',
        },
        websocket: {
          endpoint: `${origin}/.aeon/flow`,
          status: 'upgrade-required',
          description:
            'Reserved WebSocket Flow upgrade path. Use the raw flow port until a WebSocket terminator is enabled.',
        },
        webtransport: {
          endpoint: webtransportEndpoint,
          status: webtransportStatus,
          description:
            webtransportStatus === 'available'
              ? 'External HTTP/3 bridge that forwards Aeon WebTransport streams to the native flow websocket.'
              : 'Reserved HTTP/3 datagram endpoint for Aeon UDP semantics.',
        },
        rawFlow: {
          endpoint: `aeon://${hostWithoutPort(origin)}:${flowPort}`,
          status: server.aeonFlowEnabled ? 'available' : 'disabled',
          maxStreams: flowMaxStreams,
        },
      },
      fallbackChain:
        webtransportStatus === 'available'
          ? ['webtransport', 'http', 'raw-flow']
          : ['http', 'raw-flow'],
      runtimeAttestation: runtimeAttestationSurface,
    });
  }

  if (path === '/.aeon/flow' ) {
    return jsonResponse(
      {
        error: 'WebSocket upgrade path is reserved on this native listener.',
        rawFlowEndpoint: `aeon://${hostWithoutPort(origin)}:${flowPort}`,
        flowEnabled: Boolean(server.aeonFlowEnabled),
      },
      426
    );
  }

  if (path === '/.aeon/runtime-attestation' ) {
    if (!runtimeAttestation ) {
      return jsonResponse(
        {
          service: 'x-gnosis',
          endpoint: '/.aeon/runtime-attestation',
          status: 'unavailable',
          message:
            'No certified runtime attestation is configured for this host.',
        },
        503
      );
    }

    return jsonResponse({
      service: 'x-gnosis',
      endpoint: '/.aeon/runtime-attestation',
      status: 'available',
      source: runtimeAttestation.source,
      summary: runtimeAttestation.summary,
      attestation: runtimeAttestation.attestation,
    });
  }

  return jsonResponse(
    {
      status: 'reserved',
      message:
        webtransportStatus === 'available'
          ? 'Use the advertised bridge endpoint for Aeon WebTransport; the Bun listener does not terminate HTTP/3 directly.'
          : 'HTTP/3 WebTransport discovery is advertised for Aeon UDP semantics, but datagram termination is not wired into the Bun listener.',
      endpoint:
        webtransportStatus === 'available'
          ? webtransportEndpoint
          : `${origin}/.aeon/udp`,
    },
    501
  );
}

function hostWithoutPort(origin: string): string {
  return new URL(origin).hostname;
}

function buildRuntimeAttestationSurface(
  runtimeAttestation: XGnosisResolvedRuntimeAttestation | null
): Record<string, unknown> {
  if (!runtimeAttestation ) {
    return {
      endpoint: '/.aeon/runtime-attestation',
      status: 'unavailable',
    };
  }

  return {
    endpoint: '/.aeon/runtime-attestation',
    status: 'available',
    source: runtimeAttestation.source,
    summary: runtimeAttestation.summary,
  };
}
