export interface InferencePayloadPrefix {
  startPos: number;
  seqLen: number;
  body: Uint8Array;
}
/** Stub: passthrough inference-payload encoder (real impl on protocol branch). */
export function encodeInferencePayload(payload: Uint8Array): Uint8Array {
  return payload;
}
export function encodeInferencePrefix(
  startPos: number,
  seqLen: number,
  body: Uint8Array,
): Uint8Array {
  const out = new Uint8Array(8 + body.byteLength);
  const view = new DataView(out.buffer, out.byteOffset, out.byteLength);
  view.setUint32(0, startPos, true);
  view.setUint32(4, seqLen, true);
  out.set(body, 8);
  return out;
}
export function decodeInferencePrefix(payload: Uint8Array): InferencePayloadPrefix {
  if (payload.byteLength < 8) {
    throw new RangeError(`inference payload prefix requires 8 bytes, got ${payload.byteLength}`);
  }
  const view = new DataView(payload.buffer, payload.byteOffset, payload.byteLength);
  return {
    startPos: view.getUint32(0, true),
    seqLen: view.getUint32(4, true),
    body: payload.subarray(8),
  };
}

