import { alchemicHash48HexSync } from '@a0n/bitwise/cache-fp64';

export type CommunityCacheSource =
  | 'cache'
  | 'mmap'
  | 'disk'
  | 'manual'
  | 'community';

export type CommunityCacheFailureKind =
  | 'origin_miss'
  | 'not_found'
  | 'revalidate_failed';

export interface CommunityCacheHead {
  key: string;
  recordId: string;
  etag: string;
  lastModified: number;
  cacheControl: string;
  varyKey: string;
  contentType: string;
  bodyDigest: string;
  size: number;
  observedAt: number;
  source: CommunityCacheSource;
}

interface CommunityCacheRecordBase {
  recordId: string;
  sequence: number;
  key: string;
  observedAt: number;
  source: CommunityCacheSource;
}

export interface CommunityCacheValueRecord extends CommunityCacheRecordBase {
  kind: 'value';
  head: CommunityCacheHead;
}

export interface CommunityCacheFailureRecord extends CommunityCacheRecordBase {
  kind: 'failure';
  failure: CommunityCacheFailureKind;
  detail?: string;
}

export interface CommunityCacheInvalidateRecord
  extends CommunityCacheRecordBase {
  kind: 'invalidate';
  reason: string;
}

export type CommunityCacheRecord =
  | CommunityCacheValueRecord
  | CommunityCacheFailureRecord
  | CommunityCacheInvalidateRecord;

export interface AppendCommunityValueInput {
  key: string;
  etag: string;
  lastModified: number;
  cacheControl: string;
  varyKey?: string;
  contentType: string;
  body: Uint8Array;
  observedAt?: number;
  source?: CommunityCacheSource;
}

export interface AppendCommunityFailureInput {
  key: string;
  failure: CommunityCacheFailureKind;
  detail?: string;
  observedAt?: number;
  source?: CommunityCacheSource;
}

export interface AppendCommunityInvalidateInput {
  key: string;
  reason: string;
  observedAt?: number;
  source?: CommunityCacheSource;
}

export class CommunityCacheJournal {
  private readonly records = new Map<string, CommunityCacheRecord[]>();
  private readonly heads = new Map<string, CommunityCacheHead>();
  private nextSequence = 1;
  private valueRecords = 0;
  private failureRecords = 0;
  private invalidateRecords = 0;

  appendValue(input: AppendCommunityValueInput): CommunityCacheValueRecord {
    const observedAt = input.observedAt ?? Date.now();
    const recordId = this.nextRecordId();
    const head: CommunityCacheHead = {
      key: input.key,
      recordId,
      etag: input.etag,
      lastModified: input.lastModified,
      cacheControl: input.cacheControl,
      varyKey: input.varyKey ?? '',
      contentType: input.contentType,
      bodyDigest: stableBodyDigest(input.body),
      size: input.body.length,
      observedAt,
      source: input.source ?? 'manual',
    };
    const record: CommunityCacheValueRecord = {
      kind: 'value',
      recordId,
      sequence: this.nextSequence - 1,
      key: input.key,
      observedAt,
      source: input.source ?? 'manual',
      head,
    };

    this.appendRecord(record);
    this.heads.set(input.key, head);
    this.valueRecords++;
    return record;
  }

  appendFailure(
    input: AppendCommunityFailureInput
  ): CommunityCacheFailureRecord {
    const record: CommunityCacheFailureRecord = {
      kind: 'failure',
      recordId: this.nextRecordId(),
      sequence: this.nextSequence - 1,
      key: input.key,
      observedAt: input.observedAt ?? Date.now(),
      source: input.source ?? 'manual',
      failure: input.failure,
      ...(input.detail !== undefined ? { detail: input.detail } : {}),
    };

    this.appendRecord(record);
    this.failureRecords++;
    return record;
  }

  appendInvalidate(
    input: AppendCommunityInvalidateInput
  ): CommunityCacheInvalidateRecord {
    const record: CommunityCacheInvalidateRecord = {
      kind: 'invalidate',
      recordId: this.nextRecordId(),
      sequence: this.nextSequence - 1,
      key: input.key,
      observedAt: input.observedAt ?? Date.now(),
      source: input.source ?? 'manual',
      reason: input.reason,
    };

    this.appendRecord(record);
    this.heads.delete(input.key);
    this.invalidateRecords++;
    return record;
  }

  getHead(key: string): CommunityCacheHead | null {
    return this.heads.get(key) ?? null;
  }

  history(key: string): readonly CommunityCacheRecord[] {
    return [...(this.records.get(key) ?? [])];
  }

  clear(): void {
    this.records.clear();
    this.heads.clear();
    this.nextSequence = 1;
    this.valueRecords = 0;
    this.failureRecords = 0;
    this.invalidateRecords = 0;
  }

  get stats() {
    return {
      keys: this.records.size,
      heads: this.heads.size,
      records: this.valueRecords + this.failureRecords + this.invalidateRecords,
      valueRecords: this.valueRecords,
      failureRecords: this.failureRecords,
      invalidateRecords: this.invalidateRecords,
      nextSequence: this.nextSequence,
    };
  }

  private nextRecordId(): string {
    const sequence = this.nextSequence++;
    return `qcache:${sequence}`;
  }

  private appendRecord(record: CommunityCacheRecord): void {
    const existing = this.records.get(record.key);
    if (existing ) {
      existing.push(record);
      return;
    }
    this.records.set(record.key, [record]);
  }
}

function stableBodyDigest(body: Uint8Array): string {
  return alchemicHash48HexSync(body);
}
