/**
 * ForgoCD Structured Logger
 *
 * Provides leveled, structured logging with module context.
 */

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export interface LogEntry {
  level: LogLevel;
  module: string;
  message: string;
  timestamp: number;
  context?: Record<string, unknown>;
}

export type LogHandler = (entry: LogEntry) => void;

const LOG_LEVELS: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

let currentLogLevel: LogLevel = 'info';
let customHandler: LogHandler | null = null;

export function setLogLevel(level: LogLevel): void {
  currentLogLevel = level;
}

export function setLogHandler(handler: LogHandler | null): void {
  customHandler = handler;
}

function defaultHandler(entry: LogEntry): void {
  const prefix = `[${entry.module}]`;
  const message = entry.context
    ? `${prefix} ${entry.message} ${JSON.stringify(entry.context)}`
    : `${prefix} ${entry.message}`;

  switch (entry.level) {
    case 'debug':
      console.debug(message);
      break;
    case 'info':
      console.log(message);
      break;
    case 'warn':
      console.warn(message);
      break;
    case 'error':
      console.error(message);
      break;
  }
}

function emit(entry: LogEntry): void {
  if (LOG_LEVELS[entry.level] < LOG_LEVELS[currentLogLevel]) {
    return;
  }
  (customHandler ?? defaultHandler)(entry);
}

export interface Logger {
  debug(message: string, context?: Record<string, unknown>): void;
  info(message: string, context?: Record<string, unknown>): void;
  warn(message: string, context?: Record<string, unknown>): void;
  error(message: string, context?: Record<string, unknown>): void;
}

export function createLogger(module: string): Logger {
  function log(
    level: LogLevel,
    message: string,
    context?: Record<string, unknown>
  ): void {
    emit({ level, module, message, timestamp: Date.now(), context });
  }

  return {
    debug: (message, context) => log('debug', message, context),
    info: (message, context) => log('info', message, context),
    warn: (message, context) => log('warn', message, context),
    error: (message, context) => log('error', message, context),
  };
}
