/**
 * SQLite compatibility layer for x-ranger.
 *
 * Provides a unified DatabaseSync interface across Node.js (node:sqlite)
 * and Bun (bun:sqlite shim).
 */

import { createRequire } from 'node:module';

export type SQLInputValue = string | number | bigint | Uint8Array | null;

export interface SqliteStatement {
  run(...values: SQLInputValue[]): {
    lastInsertRowid: number | bigint;
    changes: number | bigint;
  };
  all(...values: SQLInputValue[]): unknown[];
  get(...values: SQLInputValue[]): unknown;
  columns(): {
    name: string;
    column: string | null;
    table: string | null;
    database: string | null;
    type: string | null;
  }[];
}

export interface SqliteDatabase {
  exec(sql: string): void;
  prepare(sql: string): SqliteStatement;
  close(): void;
}

let DatabaseSyncExport: new (path: string) => SqliteDatabase;

let initialized = false;

function getDatabaseSyncCtor(): new (path: string) => SqliteDatabase {
  if (initialized) return DatabaseSyncExport;

  let ctor: any = null;

  // 1. Try native node:sqlite
  try {
    const require = createRequire(import.meta.url);
    const nodeSqlite = require('node:sqlite');
    if (nodeSqlite && nodeSqlite.DatabaseSync) {
      ctor = nodeSqlite.DatabaseSync;
    }
  } catch {
    // node:sqlite unavailable
  }

  // 2. Fallback to Bun.sqlite if available
  if (!ctor && (globalThis as any).Bun) {
    const { Database } = (globalThis as any).Bun.sqlite;

    class BunDatabaseSync implements SqliteDatabase {
      private readonly db: any;
      constructor(path: string) {
        this.db = new Database(path);
      }
      exec(sql: string): void {
        this.db.run(sql);
      }
      prepare(sql: string): SqliteStatement {
        const stmt = this.db.prepare(sql);
        return {
          run: (...values: SQLInputValue[]) => {
            const result = stmt.run(...values);
            return {
              lastInsertRowid: result.lastInsertRowid,
              changes: result.changes,
            };
          },
          all: (...values: SQLInputValue[]) => stmt.all(...values),
          get: (...values: SQLInputValue[]) => stmt.get(...values),
          columns: () => {
            return stmt.columnNames.map((name: string) => ({
              name,
              column: name,
              table: null,
              database: null,
              type: null,
            }));
          },
        };
      }
      close(): void {
        this.db.close();
      }
    }

    ctor = BunDatabaseSync;
  }

  if (!ctor) {
    ctor = class {
      constructor() {
        throw new Error(
          'SQLite support is unavailable in this runtime. ' +
            'x-ranger requires Node.js 22.5+ or Bun.'
        );
      }
    };
  }

  DatabaseSyncExport = ctor;
  initialized = true;
  return DatabaseSyncExport;
}

// Proxy class to maintain 'new DatabaseSync()' syntax while allowing lazy init
export const DatabaseSync = function (this: SqliteDatabase, path: string) {
  const Ctor = getDatabaseSyncCtor();
  return new Ctor(path);
} as unknown as { new (path: string): SqliteDatabase };
