/**
 * @a0n/zk-encryption - Key Storage
 *
 * Persistent key storage implementations
 */

import type { ECKeyPair, KeyStorage } from './zkTypes.js';
import { generateKeyPair } from './keys.js';

/**
 * In-memory key storage (volatile - for testing/development)
 */
export class MemoryKeyStorage implements KeyStorage {
  private keys = new Map<string, ECKeyPair>();
  private primaryKeyId: string | null = null;

  async store(keyPair: ECKeyPair): Promise<void> {
    this.keys.set(keyPair.keyId, keyPair);
  }

  async retrieve(keyId: string): Promise<ECKeyPair | null> {
    return this.keys.get(keyId) || null;
  }

  async remove(keyId: string): Promise<void> {
    this.keys.delete(keyId);
    if (this.primaryKeyId === keyId) {
      this.primaryKeyId = null;
    }
  }

  async list(): Promise<string[]> {
    return Array.from(this.keys.keys());
  }

  async getPrimary(): Promise<ECKeyPair | null> {
    if (!this.primaryKeyId) return null;
    return this.keys.get(this.primaryKeyId) || null;
  }

  async setPrimary(keyId: string): Promise<void> {
    if (!this.keys.has(keyId)) {
      throw new Error(`Key ${keyId} not found`);
    }
    this.primaryKeyId = keyId;
  }

  /**
   * Clear all stored keys (for testing)
   */
  clear(): void {
    this.keys.clear();
    this.primaryKeyId = null;
  }
}

/**
 * IndexedDB key storage (persistent - for browser environments)
 */
export class IndexedDBKeyStorage implements KeyStorage {
  private dbName: string;
  private storeName: string;
  private dbVersion: number;
  private primaryKeyName: string;

  constructor(
    dbName = 'zk-encryption-keys',
    storeName = 'keys',
    dbVersion = 1
  ) {
    this.dbName = dbName;
    this.storeName = storeName;
    this.dbVersion = dbVersion;
    this.primaryKeyName = '__primary__';
  }

  private async openDB(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, this.dbVersion);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(this.storeName)) {
          db.createObjectStore(this.storeName, { keyPath: 'keyId' });
        }
      };
    });
  }

  async store(keyPair: ECKeyPair): Promise<void> {
    const db = await this.openDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readwrite');
      const store = tx.objectStore(this.storeName);
      const request = store.put(keyPair);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve();
      tx.oncomplete = () => db.close();
    });
  }

  async retrieve(keyId: string): Promise<ECKeyPair | null> {
    const db = await this.openDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readonly');
      const store = tx.objectStore(this.storeName);
      const request = store.get(keyId);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result || null);
      tx.oncomplete = () => db.close();
    });
  }

  async remove(keyId: string): Promise<void> {
    const db = await this.openDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readwrite');
      const store = tx.objectStore(this.storeName);
      const request = store.delete(keyId);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve();
      tx.oncomplete = () => db.close();
    });
  }

  async list(): Promise<string[]> {
    const db = await this.openDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readonly');
      const store = tx.objectStore(this.storeName);
      const request = store.getAllKeys();

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        const keys = (request.result as string[]).filter(
          (k) => k !== this.primaryKeyName
        );
        resolve(keys);
      };
      tx.oncomplete = () => db.close();
    });
  }

  async getPrimary(): Promise<ECKeyPair | null> {
    const db = await this.openDB();

    // Get primary key ID
    const primaryId = await new Promise<string | null>((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readonly');
      const store = tx.objectStore(this.storeName);
      const request = store.get(this.primaryKeyName);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        const result = request.result as
          | { keyId: string; primaryId: string }
          | undefined;
        resolve(result?.primaryId || null);
      };
    });

    if (!primaryId) {
      db.close();
      return null;
    }

    // Get the primary key pair
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readonly');
      const store = tx.objectStore(this.storeName);
      const request = store.get(primaryId);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result || null);
      tx.oncomplete = () => db.close();
    });
  }

  async setPrimary(keyId: string): Promise<void> {
    const db = await this.openDB();

    // Verify key exists
    const keyExists = await new Promise<boolean>((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readonly');
      const store = tx.objectStore(this.storeName);
      const request = store.get(keyId);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(!!request.result);
    });

    if (!keyExists) {
      db.close();
      throw new Error(`Key ${keyId} not found`);
    }

    // Set primary
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readwrite');
      const store = tx.objectStore(this.storeName);
      const request = store.put({
        keyId: this.primaryKeyName,
        primaryId: keyId,
      });

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve();
      tx.oncomplete = () => db.close();
    });
  }

  /**
   * Clear all stored keys
   */
  async clear(): Promise<void> {
    const db = await this.openDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readwrite');
      const store = tx.objectStore(this.storeName);
      const request = store.clear();

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve();
      tx.oncomplete = () => db.close();
    });
  }
}

/**
 * Create storage instance based on environment
 */
export function createKeyStorage(): KeyStorage {
  // Check if IndexedDB is available
  const hasIndexedDB = typeof indexedDB !== 'undefined' && indexedDB !== null;

  if (hasIndexedDB) {
    return new IndexedDBKeyStorage();
  }

  // Fall back to memory storage
  return new MemoryKeyStorage();
}

/**
 * Get or create primary key pair
 *
 * Convenience function that gets the primary key pair from storage,
 * or generates a new one if none exists.
 *
 * @param storage - Key storage instance
 * @returns Primary key pair
 */
export async function getOrCreatePrimaryKey(
  storage: KeyStorage
): Promise<ECKeyPair> {
  let primary = await storage.getPrimary();

  if (!primary) {
    // Generate new key pair
    primary = await generateKeyPair();
    await storage.store(primary);
    await storage.setPrimary(primary.keyId);
  }

  return primary;
}

/**
 * Rotate primary key
 *
 * Generates a new key pair and sets it as primary.
 * Old key is kept for decrypting historical data.
 *
 * @param storage - Key storage instance
 * @returns New primary key pair
 */
export async function rotatePrimaryKey(
  storage: KeyStorage
): Promise<ECKeyPair> {
  const newKey = await generateKeyPair();
  await storage.store(newKey);
  await storage.setPrimary(newKey.keyId);
  return newKey;
}
