import { existsSync, readdirSync, statSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export type GnosisNativeRuntimeBackend = 'uring' | 'foil';

export interface GnosisUringCommandOptions {
  readonly backend?: GnosisNativeRuntimeBackend;
  readonly port: number;
  readonly root: string;
  readonly threads?: number;
  readonly flowPort?: number;
  readonly flowWorkers?: number;
  readonly useUring?: boolean;
  readonly proxyAll?: boolean;
  readonly proxyUpstreamHost?: string;
  readonly proxyUpstreamPort?: number;
  readonly fsBackend?: 'local' | 'forge_vfs';
  readonly vfsBridgeSocket?: string;
  readonly vfsRepoId?: string;
  readonly vfsSpoolDir?: string;
  readonly trustPropagatedAuth?: boolean;
  readonly rawCaptureJsonl?: string;
  readonly rawDeviceInput?: string;
  readonly rawEngine?: string;
  readonly rawBlockSize?: number;
  readonly rawSampleRateHz?: number;
  readonly rawCenterFrequencyHz?: number;
  readonly rawSampleFormat?: string;
  readonly activationThreshold?: number;
  readonly witnessSignal?: number;
  readonly smartSkipRetentionFloor?: number;
  readonly rtlsdrLibrary?: string;
  readonly rtlsdrIndex?: number;
  readonly libusbLibrary?: string;
  readonly libusbTimeoutMs?: number;
  readonly libusbColdProbe?: boolean;
  readonly libusbAsyncRingDepth?: number;
  readonly noFlow?: boolean;
  readonly gnode?: boolean;
  readonly wasm?: boolean;
}

export interface GnosisUringCommand {
  readonly backend: GnosisNativeRuntimeBackend;
  readonly command: string;
  readonly args: readonly string[];
  readonly display: string;
}

export interface GnosisFoilFlowClientEnvOptions {
  readonly host?: string;
  readonly flowPort?: number;
  readonly timeoutMs?: number;
  readonly backendEnabled?: boolean;
  readonly ambientStartOffset?: number;
  readonly ambientStride?: number;
  readonly ambientParallelism?: number;
  readonly monsterResidentWindow?: number;
}

export interface GnosisFoilFlowClientEnv {
  readonly GNEXEC_FOIL_BACKEND: string;
  readonly GNEXEC_FOIL_FLOW_ADDR: string;
  readonly GNEXEC_FOIL_FLOW_TIMEOUT_MS: string;
  readonly GNOSIS_AMBIENT_START_OFFSET?: string;
  readonly GNOSIS_AMBIENT_STRIDE?: string;
  readonly GNOSIS_AMBIENT_PARALLELISM?: string;
  readonly GNOSIS_MONSTER_RESIDENT_WINDOW?: string;
}

function gnosisUringPackageRoot(): string {
  return resolve(dirname(fileURLToPath(import.meta.url)), '..');
}

function gnosisUringSourceRoot(): string {
  return resolve(gnosisUringPackageRoot(), 'gnosis-uring');
}

function gnosisFoilPackageRoot(): string {
  return resolve(gnosisUringPackageRoot(), '..', 'gnosis', 'distributed-inference');
}

function resolveUringBinaryCandidates(): readonly string[] {
  const packageRoot = gnosisUringPackageRoot();
  const override = process.env.GNOSIS_URING_BIN;
  return [
    ...(override ? [override] : []),
    resolve(packageRoot, 'gnosis-uring', 'target', 'release', 'gnosis-uring'),
    resolve(packageRoot, 'gnosis-uring', 'target', 'debug', 'gnosis-uring'),
  ];
}

function resolveFoilBinaryCandidates(): readonly string[] {
  const packageRoot = gnosisFoilPackageRoot();
  const override = process.env.GNOSIS_FOIL_BIN;
  return [
    ...(override ? [override] : []),
    resolve(packageRoot, 'target', 'release', 'gnosis-foil-control'),
    resolve(packageRoot, 'target', 'debug', 'gnosis-foil-control'),
  ];
}

function treeModifiedAfter(path: string, cutoffMs: number): boolean {
  const stats = statSync(path);
  if (stats.mtimeMs > cutoffMs ) {
    return true;
  }

  if (!stats.isDirectory()) {
    return false;
  }

  return readdirSync(path).some((entry) =>
    treeModifiedAfter(resolve(path, entry), cutoffMs)
  );
}

function isUsableUringBinary(binaryPath: string): boolean {
  if (!existsSync(binaryPath)) {
    return false;
  }

  const binaryMtimeMs = statSync(binaryPath).mtimeMs;
  const sourceRoot = gnosisUringSourceRoot();
  return (
    !treeModifiedAfter(resolve(sourceRoot, 'src'), binaryMtimeMs) &&
    !treeModifiedAfter(resolve(sourceRoot, 'Cargo.toml'), binaryMtimeMs)
  );
}

function isUsableFoilBinary(binaryPath: string): boolean {
  if (!existsSync(binaryPath)) {
    return false;
  }

  const binaryMtimeMs = statSync(binaryPath).mtimeMs;
  const sourceRoot = resolve(gnosisFoilPackageRoot(), 'src');
  return (
    !treeModifiedAfter(sourceRoot, binaryMtimeMs) &&
    !treeModifiedAfter(resolve(gnosisFoilPackageRoot(), 'Cargo.toml'), binaryMtimeMs)
  );
}

export function buildGnosisUringArgs(
  options: GnosisUringCommandOptions
): readonly string[] {
  const args = [
    '--port',
    String(options.port),
    '--root',
    options.root,
    '--threads',
    String(options.threads ?? 1),
    '--flow-port',
    String(options.flowPort ?? 9082),
  ];

  if (options.useUring ) {
    args.push('--uring');
  }

  if (options.proxyAll ) {
    args.push('--proxy-all');
    args.push(
      '--proxy-upstream-host',
      options.proxyUpstreamHost ?? '127.0.0.1'
    );
    if (options.proxyUpstreamPort !== undefined ) {
      args.push('--proxy-upstream-port', String(options.proxyUpstreamPort));
    }
  }

  if (options.fsBackend ) {
    args.push('--fs-backend', options.fsBackend);
  }

  if (options.vfsBridgeSocket ) {
    args.push('--vfs-bridge-socket', options.vfsBridgeSocket);
  }

  if (options.vfsRepoId ) {
    args.push('--vfs-repo-id', options.vfsRepoId);
  }

  if (options.vfsSpoolDir ) {
    args.push('--vfs-spool-dir', options.vfsSpoolDir);
  }

  if (options.trustPropagatedAuth ) {
    args.push('--trust-propagated-auth');
  }

  return args;
}

export function buildGnosisFoilArgs(
  options: GnosisUringCommandOptions
): readonly string[] {
  const args = [
    '--port',
    String(options.port),
    '--flow-port',
    String(options.flowPort ?? 9082),
  ];

  if (options.flowWorkers !== undefined ) {
    args.push('--flow-workers', String(options.flowWorkers));
  }

  if (options.noFlow ) {
    args.push('--no-flow');
  }

  if (options.gnode ) {
    args.push('--gnode');
  }

  if (options.wasm ) {
    args.push('--wasm');
  }

  if (options.proxyAll ) {
    args.push('--proxy-all');
    args.push(
      '--proxy-upstream-host',
      options.proxyUpstreamHost ?? '127.0.0.1'
    );
    if (options.proxyUpstreamPort !== undefined ) {
      args.push('--proxy-upstream-port', String(options.proxyUpstreamPort));
    }
  }

  if (options.rawCaptureJsonl ) {
    args.push('--raw-capture-jsonl', options.rawCaptureJsonl);
  }

  if (options.rawDeviceInput ) {
    args.push('--raw-device-input', options.rawDeviceInput);
  }

  if (options.rawEngine ) {
    args.push('--raw-engine', options.rawEngine);
  }

  if (options.rawBlockSize !== undefined ) {
    args.push('--raw-block-size', String(options.rawBlockSize));
  }

  if (options.rawSampleRateHz !== undefined ) {
    args.push('--raw-sample-rate', String(options.rawSampleRateHz));
  }

  if (options.rawCenterFrequencyHz !== undefined ) {
    args.push('--raw-center-hz', String(options.rawCenterFrequencyHz));
  }

  if (options.rawSampleFormat ) {
    args.push('--raw-sample-format', options.rawSampleFormat);
  }

  if (options.activationThreshold !== undefined ) {
    args.push('--activation-threshold', String(options.activationThreshold));
  }

  if (options.witnessSignal !== undefined ) {
    args.push('--witness-signal', String(options.witnessSignal));
  }

  if (options.smartSkipRetentionFloor !== undefined ) {
    args.push(
      '--smart-skip-retention-floor',
      String(options.smartSkipRetentionFloor)
    );
  }

  if (options.rtlsdrLibrary ) {
    args.push('--rtlsdr-library', options.rtlsdrLibrary);
  }

  if (options.rtlsdrIndex !== undefined ) {
    args.push('--rtlsdr-index', String(options.rtlsdrIndex));
  }

  if (options.libusbLibrary ) {
    args.push('--libusb-library', options.libusbLibrary);
  }

  if (options.libusbTimeoutMs !== undefined ) {
    args.push('--libusb-timeout-ms', String(options.libusbTimeoutMs));
  }

  if (options.libusbColdProbe ) {
    args.push('--libusb-cold-probe');
  }

  if (options.libusbAsyncRingDepth !== undefined ) {
    args.push('--libusb-async-ring-depth', String(options.libusbAsyncRingDepth));
  }

  return args;
}

export function buildGnosisFoilFlowClientEnv(
  options: GnosisFoilFlowClientEnvOptions = {}
): GnosisFoilFlowClientEnv {
  return {
    GNEXEC_FOIL_BACKEND: options.backendEnabled === false ? '0' : '1',
    GNEXEC_FOIL_FLOW_ADDR: `${options.host ?? '127.0.0.1'}:${
      options.flowPort ?? 9082
    }`,
    GNEXEC_FOIL_FLOW_TIMEOUT_MS: String(options.timeoutMs ?? 25),
    ...(options.ambientStartOffset !== undefined
      ? { GNOSIS_AMBIENT_START_OFFSET: String(options.ambientStartOffset) }
      : {}),
    ...(options.ambientStride !== undefined
      ? { GNOSIS_AMBIENT_STRIDE: String(options.ambientStride) }
      : {}),
    ...(options.ambientParallelism !== undefined
      ? { GNOSIS_AMBIENT_PARALLELISM: String(options.ambientParallelism) }
      : {}),
    ...(options.monsterResidentWindow !== undefined
      ? { GNOSIS_MONSTER_RESIDENT_WINDOW: String(options.monsterResidentWindow) }
      : {}),
  };
}

export function resolveGnosisUringCommand(
  options: GnosisUringCommandOptions
): GnosisUringCommand {
  const backend = options.backend ?? 'uring';
  if (backend === 'foil' ) {
    const args = buildGnosisFoilArgs(options);
    const binaryPath = resolveFoilBinaryCandidates().find((candidate) =>
      isUsableFoilBinary(candidate)
    );

    if (binaryPath ) {
      return {
        backend,
        command: binaryPath,
        args,
        display: `${binaryPath} ${args.join(' ')}`,
      };
    }

    const manifestPath = resolve(gnosisFoilPackageRoot(), 'Cargo.toml');
    const cargoArgs = [
      'run',
      '--manifest-path',
      manifestPath,
      '--bin',
      'gnosis-foil-control',
      '--release',
      '--',
      ...args,
    ];

    return {
      backend,
      command: 'cargo',
      args: cargoArgs,
      display: `cargo ${cargoArgs.join(' ')}`,
    };
  }

  const args = buildGnosisUringArgs(options);
  const binaryPath = resolveUringBinaryCandidates().find((candidate) =>
    isUsableUringBinary(candidate)
  );

  if (binaryPath ) {
    return {
      backend,
      command: binaryPath,
      args,
      display: `${binaryPath} ${args.join(' ')}`,
    };
  }

  const manifestPath = resolve(gnosisUringSourceRoot(), 'Cargo.toml');
  const cargoArgs = [
    'run',
    '--manifest-path',
    manifestPath,
    '--bin',
    'gnosis-uring',
    '--release',
    '--',
    ...args,
  ];

  return {
    backend,
    command: 'cargo',
    args: cargoArgs,
    display: `cargo ${cargoArgs.join(' ')}`,
  };
}
