export interface WorthingtonWhipResult {
  readonly shards: number;
  readonly numerator: number;
  readonly denominator: number;
  readonly savingsFraction: number;
}

export interface SpeculativeTreeResult {
  readonly alpha: number;
  readonly depth: number;
  readonly expectedAccepted: number;
  readonly denominator: number;
}

export interface TurbulentIdleResult {
  readonly stageCount: number;
  readonly chunkCount: number;
  readonly numerator: number;
  readonly denominator: number;
  readonly idleFraction: number;
}

export interface FrontierFillResult {
  readonly frontierByLayer: readonly number[];
  readonly layerCount: number;
  readonly frontierArea: number;
  readonly peakFrontier: number;
  readonly envelopeArea: number;
  readonly frontierFill: number;
  readonly wallaceNumber: number;
  readonly wally: number;
  readonly frontierDeficit: number;
}

export interface PipelineOccupancyResult {
  readonly stageCount: number;
  readonly chunkCount: number;
  readonly frontierArea: number;
  readonly capacityArea: number;
  readonly frontierFill: number;
  readonly occupancyDeficit: number;
}

export type PipelineRegime = 'laminar' | 'transitional' | 'turbulent';

export type ParallelismAction =
  | 'expand'
  | 'staggered-expand'
  | 'hold'
  | 'multiplex'
  | 'constrain'
  | 'accept-spike';

export interface AdaptiveParallelismPolicyResult {
  readonly intrinsicBeta1: number;
  readonly actualBeta1: number;
  readonly topologyDeficit: number;
  readonly stageCount: number;
  readonly chunkCount: number;
  readonly reynoldsEstimate: number;
  readonly regime: PipelineRegime;
  readonly frontierFill: number;
  readonly occupancyDeficit: number;
  readonly highOccupancyDeficit: boolean;
  readonly hopeGapDetected: boolean;
  readonly action: ParallelismAction;
  readonly rationale: string;
}

export interface GreedyRejectionAnalysis {
  /** Current crossing number (topological complexity) */
  readonly currentCrossings: number;
  /** Proposed crossing number after integration */
  readonly proposedCrossings: number;
  /** The spike cost: proposedCrossings - currentCrossings */
  readonly spikeCost: number;
  /** Per-round phantom maintenance cost if rejected */
  readonly phantomCostPerRound: number;
  /** Round at which cumulative phantom cost exceeds spike cost */
  readonly breakEvenRound: number;
  /** Cumulative phantom cost over the analysis horizon */
  readonly cumulativePhantomCost: number;
  /** Whether a greedy policy would reject this integration */
  readonly greedyRejects: boolean;
  /** Whether the system is in a Hope Gap state */
  readonly hopeGapState: boolean;
  /** Whether acceptance dominates rejection over the horizon */
  readonly acceptanceDominates: boolean;
  /** Human-readable assessment */
  readonly assessment: string;
}

export interface QuantumDeficitResult {
  readonly sqrtN: number;
  readonly searchSize: number;
  readonly classicalDeficit: number;
  readonly quantumDeficit: number;
  readonly speedup: number;
}

export interface ProtocolDeficitResult {
  readonly streamCount: number;
  readonly intrinsicBeta1: number;
  readonly tcpDeficit: number;
  readonly quicDeficit: number;
  readonly flowDeficit: number;
}

export interface SettlementDeficitResult {
  readonly intrinsicBeta1: number;
  readonly sequentialDeficit: number;
  readonly parallelDeficit: number;
}

function assertPositiveInteger(name: string, value: number): number {
  if (!Number.isInteger(value) || value <= 0) {
    throw new Error(`${name} must be a positive integer`);
  }
  return value;
}

function assertUnitIntervalOpen(name: string, value: number): number {
  if (!Number.isFinite(value) || value < 0 || value >= 1) {
    throw new Error(`${name} must be in [0, 1)`);
  }
  return value;
}

function assertNonNegativeFinite(name: string, value: number): number {
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`${name} must be a non-negative finite number`);
  }
  return value;
}

function assertNonNegativeInteger(name: string, value: number): number {
  if (!Number.isInteger(value) || value < 0) {
    throw new Error(`${name} must be a non-negative integer`);
  }
  return value;
}

function assertNonEmptyFrontier(
  frontierByLayer: readonly number[]
): readonly number[] {
  if (frontierByLayer.length === 0) {
    throw new Error('frontierByLayer must contain at least one layer');
  }
  frontierByLayer.forEach((width, index) => {
    assertNonNegativeInteger(`frontierByLayer[${index}]`, width);
  });
  return frontierByLayer;
}

export function worthingtonWhipSavings(shards: number): WorthingtonWhipResult {
  const normalizedShards = assertPositiveInteger('shards', shards);
  const numerator = normalizedShards - 1;
  const denominator = 2 * normalizedShards;
  return {
    shards: normalizedShards,
    numerator,
    denominator,
    savingsFraction: numerator / denominator,
  };
}

export function speculativeTreeExpectedAccepted(
  alpha: number,
  depth: number
): SpeculativeTreeResult {
  const normalizedAlpha = assertUnitIntervalOpen('alpha', alpha);
  const normalizedDepth = assertPositiveInteger('depth', depth);
  const denominator = 1 - normalizedAlpha;
  return {
    alpha: normalizedAlpha,
    depth: normalizedDepth,
    expectedAccepted:
      (1 - Math.pow(normalizedAlpha, normalizedDepth)) / denominator,
    denominator,
  };
}

export function turbulentIdleFraction(
  stageCount: number,
  chunkCount: number
): TurbulentIdleResult {
  const normalizedStageCount = assertPositiveInteger('stageCount', stageCount);
  const normalizedChunkCount = assertPositiveInteger('chunkCount', chunkCount);
  const numerator = normalizedStageCount * (normalizedStageCount - 1);
  const denominator =
    normalizedStageCount * (normalizedChunkCount + normalizedStageCount - 1);
  return {
    stageCount: normalizedStageCount,
    chunkCount: normalizedChunkCount,
    numerator,
    denominator,
    idleFraction: numerator / denominator,
  };
}

export function frontierFill(
  frontierByLayer: readonly number[]
): FrontierFillResult {
  const normalizedFrontier = assertNonEmptyFrontier(frontierByLayer);
  const layerCount = normalizedFrontier.length;
  const frontierArea = normalizedFrontier.reduce(
    (sum, width) => sum + width,
    0
  );
  const peakFrontier = normalizedFrontier.reduce(
    (peak, width) => Math.max(peak, width),
    0
  );
  const envelopeArea = layerCount * peakFrontier;
  const fill = envelopeArea === 0 ? 1 : frontierArea / envelopeArea;
  const wallaceNumber = 1 - fill;

  return {
    frontierByLayer: [...normalizedFrontier],
    layerCount,
    frontierArea,
    peakFrontier,
    envelopeArea,
    frontierFill: fill,
    wallaceNumber,
    wally: wallaceNumber,
    frontierDeficit: wallaceNumber,
  };
}

export function pipelineOccupancy(
  stageCount: number,
  chunkCount: number
): PipelineOccupancyResult {
  const normalizedStageCount = assertPositiveInteger('stageCount', stageCount);
  const normalizedChunkCount = assertPositiveInteger('chunkCount', chunkCount);
  const frontierArea = normalizedStageCount * normalizedChunkCount;
  const capacityArea =
    normalizedStageCount * (normalizedChunkCount + normalizedStageCount - 1);
  const fill = frontierArea / capacityArea;

  return {
    stageCount: normalizedStageCount,
    chunkCount: normalizedChunkCount,
    frontierArea,
    capacityArea,
    frontierFill: fill,
    occupancyDeficit: 1 - fill,
  };
}

export function classifyPipelineRegime(
  stageCount: number,
  chunkCount: number
): PipelineRegime {
  try {
    const normalizedStageCount = assertPositiveInteger('stageCount', stageCount);
    const normalizedChunkCount = assertPositiveInteger('chunkCount', chunkCount);
    const reynoldsEstimate = normalizedStageCount / normalizedChunkCount;

    if (reynoldsEstimate < 0.3) {
      return 'laminar';
    }
    if (reynoldsEstimate > 0.7) {
      return 'turbulent';
    }
    return 'transitional';

  } catch (error) {
    throw new Error(`[classifyPipelineRegime] ${error instanceof Error ? error.message : String(error)}`);
  }
}

// ─── CERTIFIED regime classifier (cost crossover, not count ratio) ──────────
//
// `classifyPipelineRegime` sources its Reynolds number from a STRUCTURAL count
// ratio (`stageCount / chunkCount`). That axis is wrong the same way the FOIL
// size cutoff and the value-door batch-size gate are wrong: it cannot tell a
// pipeline of CHEAP stages from one of HEAVY stages. A pipeline with few stages
// but heavy per-stage work should go turbulent (it pays to parallelize); a
// pipeline with many cheap stages should stay laminar (the dispatch dominates).
// The count ratio decides the opposite on both shapes.
//
// In aeon nothing schedules un-admitted: every stage already carries an
// admission cert attesting its cost. So the per-stage cost is known at the gate.
// `classifyRegimeCertified` reads it and folds it into the Reynolds number as a
// cost-weighted ratio — eliminating the count axis. This mirrors
// gnosis-frf `value_door::certified_light` / `cost_aware_k_eff_certified` and
// gnosis-foil `foil_entropy_reynolds_gate_certified`: a cert in hand is always
// decided RED/GREEN, never the YELLOW probe (which is vacuous under cert).
//
// Lean contract (zero axioms):
//   - Gnosis.ValueDoorStoplight.certified_never_yellow — never YELLOW.
//   - Gnosis.DoorPaysAboveCrossover.crossover_is_verify_search_gap
//     — the crossover is the per-item COST gap, not a count/size ratio.

export const CERTIFIED_REGIME_THEOREM_ID =
  'Gnosis.ValueDoorStoplight.certified_never_yellow';
export const CERTIFIED_REGIME_CROSSOVER_THEOREM_ID =
  'Gnosis.DoorPaysAboveCrossover.crossover_is_verify_search_gap';

/**
 * The per-stage / per-chunk reference cost that sets the cost crossover. A
 * stage whose certified cost equals the reference contributes exactly its
 * structural weight; cheaper stages shrink the effective Reynolds number,
 * heavier stages grow it. Chosen as the dispatch (gate) cost a stage must beat
 * to be worth parallelizing — below it, parallelism is drag (RED/laminar).
 */
export const DEFAULT_STAGE_DISPATCH_COST = 1;

export interface CertifiedRegimeResult {
  readonly stageCount: number;
  readonly chunkCount: number;
  /** Count-only Reynolds number — what classifyPipelineRegime decides on. */
  readonly countReynolds: number;
  /** Certified per-stage cost folded in: (stageCount·c̄) / (chunkCount·g). */
  readonly costReynolds: number;
  /** Mean certified per-stage cost. */
  readonly meanStageCost: number;
  /** The dispatch (gate) cost a stage must beat to be worth forking. */
  readonly dispatchCost: number;
  readonly regime: PipelineRegime;
  /** The Lean theorem this decision realizes. */
  readonly theoremId: string;
}

/**
 * CERTIFIED regime classifier — fold the cert-attested per-stage cost into the
 * Reynolds estimate so the crossover is the COST gap, not the count ratio.
 *
 * Reynolds = (Σ certifiedStageCosts) / (chunkCount · dispatchCost)
 *          = (stageCount · meanStageCost) / (chunkCount · dispatchCost)
 *
 * When every stage costs exactly `dispatchCost` this reduces EXACTLY to the
 * count ratio `stageCount / chunkCount` — the count classifier is the unit-cost
 * special case. With cheap stages (cost < dispatch) the same count ratio reads
 * laminar; with heavy stages (cost > dispatch) it reads turbulent. Same paper
 * thresholds (0.3 / 0.7). Additive: `classifyPipelineRegime` is unchanged.
 *
 * @param stageCertifiedCosts per-stage certified cost (length = stageCount)
 * @param chunkCount number of chunks (parallel width)
 * @param dispatchCost per-chunk dispatch/gate cost (default 1 = count-ratio reduction)
 */
export function classifyRegimeCertified(
  stageCertifiedCosts: readonly number[],
  chunkCount: number,
  dispatchCost: number = DEFAULT_STAGE_DISPATCH_COST
): CertifiedRegimeResult {
  try {
    const normalizedChunkCount = assertPositiveInteger(
      'chunkCount',
      chunkCount
    );
    const normalizedDispatchCost = assertPositiveInteger(
      'dispatchCost',
      dispatchCost
    );
    if (stageCertifiedCosts.length === 0) {
      throw new Error('stageCertifiedCosts must contain at least one stage');
    }
    stageCertifiedCosts.forEach((cost, index) => {
      assertNonNegativeFinite(`stageCertifiedCosts[${index}]`, cost);
    });

    const stageCount = stageCertifiedCosts.length;
    const totalStageCost = stageCertifiedCosts.reduce(
      (sum, cost) => sum + cost,
      0
    );
    const meanStageCost = totalStageCost / stageCount;
    const countReynolds = stageCount / normalizedChunkCount;
    // Cost crossover: total certified work vs total dispatch cost across chunks.
    const costReynolds =
      totalStageCost / (normalizedChunkCount * normalizedDispatchCost);

    let regime: PipelineRegime;
    if (costReynolds < 0.3) {
      regime = 'laminar';
    } else if (costReynolds > 0.7) {
      regime = 'turbulent';
    } else {
      regime = 'transitional';
    }

    return {
      stageCount,
      chunkCount: normalizedChunkCount,
      countReynolds,
      costReynolds,
      meanStageCost,
      dispatchCost: normalizedDispatchCost,
      regime,
      theoremId: CERTIFIED_REGIME_THEOREM_ID,
    };
  } catch (error) {
    throw new Error(
      `[classifyRegimeCertified] ${error instanceof Error ? error.message : String(error)}`
    );
  }
}

export function adaptiveParallelismPolicy(config: {
  intrinsicBeta1: number;
  actualBeta1: number;
  stageCount: number;
  chunkCount: number;
}): AdaptiveParallelismPolicyResult {
  try {
    const intrinsicBeta1 = assertNonNegativeFinite(
      'intrinsicBeta1',
      config.intrinsicBeta1
    );
    const actualBeta1 = assertNonNegativeFinite(
      'actualBeta1',
      config.actualBeta1
    );
    const occupancy = pipelineOccupancy(config.stageCount, config.chunkCount);
    const topologyDeficit = intrinsicBeta1 - actualBeta1;
    const regime = classifyPipelineRegime(config.stageCount, config.chunkCount);
    const highOccupancyDeficit = occupancy.occupancyDeficit >= 0.2;
    const reynoldsEstimate = config.stageCount / config.chunkCount;

    // Hope Gap detection: the system has positive deficit AND expanding would
    // temporarily increase complexity (occupancy deficit is high, meaning the
    // spike hasn't been absorbed yet). The greedy agent would reject, but the
    // correct action is to accept the spike and let Wallington converge.
    const hopeGapDetected =
      topologyDeficit > 0 &&
      highOccupancyDeficit &&
      regime === 'turbulent';

    let action: ParallelismAction;
    let rationale: string;

    if (hopeGapDetected) {
      action = 'accept-spike';
      rationale =
        'Hope Gap: positive deficit with high occupancy overhead in turbulent regime. A greedy policy would reject the complexity increase, but acceptance + Wallington convergence dominates perpetual rejection. Accept the temporary spike.';
    } else if (topologyDeficit > 0 && highOccupancyDeficit) {
      action = 'staggered-expand';
      rationale =
        'Natural parallelism exceeds the current topology, but warm-up overhead is still high; widen gradually rather than forking to the limit immediately.';
    } else if (topologyDeficit > 0) {
      action = 'expand';
      rationale =
        'The current implementation is too sequential for the problem and the wavefront is already filling efficiently enough to justify more parallelism.';
    } else if (topologyDeficit < 0 && highOccupancyDeficit) {
      action = 'constrain';
      rationale =
        'The system is already over-forked relative to the problem and early occupancy is poor; reduce single-request fan-out.';
    } else if (regime === 'turbulent') {
      action = 'multiplex';
      rationale =
        'The topology is not the bottleneck, but the pipeline is in a high-Reynolds turbulent regime; fill idle slots with cross-request work instead of widening one request.';
    } else {
      action = 'hold';
      rationale =
        'Topology and occupancy are aligned well enough that the current degree of parallelism should remain stable.';
    }

    return {
      intrinsicBeta1,
      actualBeta1,
      topologyDeficit,
      stageCount: config.stageCount,
      chunkCount: config.chunkCount,
      reynoldsEstimate,
      regime,
      frontierFill: occupancy.frontierFill,
      occupancyDeficit: occupancy.occupancyDeficit,
      highOccupancyDeficit,
      hopeGapDetected,
      action,
      rationale,
    };

  } catch (error) {
    throw new Error(`[adaptiveParallelismPolicy] ${error instanceof Error ? error.message : String(error)}`);
  }
}

export function greedyRejectionAnalysis(config: {
  currentCrossings: number;
  proposedCrossings: number;
  phantomCostPerRound: number;
  horizonRounds?: number;
}): GreedyRejectionAnalysis {
  try {
    const currentCrossings = assertNonNegativeInteger(
      'currentCrossings',
      config.currentCrossings
    );
    const proposedCrossings = assertNonNegativeInteger(
      'proposedCrossings',
      config.proposedCrossings
    );
    const phantomCostPerRound = assertNonNegativeFinite(
      'phantomCostPerRound',
      config.phantomCostPerRound
    );
    const horizonRounds = config.horizonRounds ?? 10;

    const spikeCost = Math.max(0, proposedCrossings - currentCrossings);
    const greedyRejects = proposedCrossings > currentCrossings;
    const hopeGapState = greedyRejects && phantomCostPerRound > 0;

    // Break-even: phantomCostPerRound * round > spikeCost
    const breakEvenRound =
      phantomCostPerRound > 0
        ? Math.ceil(spikeCost / phantomCostPerRound) + 1
        : Infinity;

    const cumulativePhantomCost = phantomCostPerRound * horizonRounds;
    const acceptanceDominates =
      hopeGapState && horizonRounds >= breakEvenRound;

    let assessment: string;
    if (!greedyRejects) {
      assessment =
        'No spike required — integration is monotonically non-increasing.';
    } else if (!hopeGapState) {
      assessment =
        'Spike required but no ongoing phantom cost — accept immediately.';
    } else if (acceptanceDominates) {
      assessment =
        `Hope Gap: greedy rejection deadlocks. Phantom cost ${cumulativePhantomCost.toFixed(1)} over ${horizonRounds} rounds exceeds spike cost ${spikeCost}. Accept the +${spikeCost} spike — Wallington convergence will reduce to baseline.`;
    } else {
      assessment =
        `Near Hope Gap: spike cost ${spikeCost} not yet exceeded by phantom cost ${cumulativePhantomCost.toFixed(1)} over ${horizonRounds} rounds. Break-even at round ${breakEvenRound}.`;
    }

    return {
      currentCrossings,
      proposedCrossings,
      spikeCost,
      phantomCostPerRound,
      breakEvenRound,
      cumulativePhantomCost,
      greedyRejects,
      hopeGapState,
      acceptanceDominates,
      assessment,
    };

  } catch (error) {
    throw new Error(`[greedyRejectionAnalysis] ${error instanceof Error ? error.message : String(error)}`);
  }
}

export function quantumDeficitIdentity(sqrtN: number): QuantumDeficitResult {
  const normalizedSqrtN = assertPositiveInteger('sqrtN', sqrtN);
  const searchSize = normalizedSqrtN * normalizedSqrtN;
  const classicalDeficit = normalizedSqrtN - 1;
  return {
    sqrtN: normalizedSqrtN,
    searchSize,
    classicalDeficit,
    quantumDeficit: 0,
    speedup: searchSize / normalizedSqrtN,
  };
}

export function protocolDeficits(streamCount: number): ProtocolDeficitResult {
  const normalizedStreamCount = assertPositiveInteger(
    'streamCount',
    streamCount
  );
  if (normalizedStreamCount <= 1) {
    throw new Error('streamCount must be greater than 1');
  }
  const intrinsicBeta1 = normalizedStreamCount - 1;
  return {
    streamCount: normalizedStreamCount,
    intrinsicBeta1,
    tcpDeficit: intrinsicBeta1,
    quicDeficit: 0,
    flowDeficit: 0,
  };
}

export function settlementDeficits(): SettlementDeficitResult {
  return {
    intrinsicBeta1: 2,
    sequentialDeficit: 2,
    parallelDeficit: 0,
  };
}

export function beta2FromBandGap(forbiddenEnergyCount: number): number {
  const normalizedForbiddenCount = assertNonNegativeFinite(
    'forbiddenEnergyCount',
    forbiddenEnergyCount
  );
  return normalizedForbiddenCount > 0 ? 1 : 0;
}

export function firstLawConserved(
  forkEnergy: number,
  foldWork: number,
  ventEnergy: number,
  tolerance = 1e-9
): boolean {
  const normalizedForkEnergy = assertNonNegativeFinite(
    'forkEnergy',
    forkEnergy
  );
  const normalizedFoldWork = assertNonNegativeFinite('foldWork', foldWork);
  const normalizedVentEnergy = assertNonNegativeFinite(
    'ventEnergy',
    ventEnergy
  );
  if (normalizedFoldWork > normalizedForkEnergy) {
    return false;
  }
  const delta = Math.abs(
    normalizedForkEnergy - (normalizedFoldWork + normalizedVentEnergy)
  );
  return delta <= Math.max(tolerance, 0);
}

export interface ValentinianSandwichResult {
  readonly estimatedStepsToConvergence: number;
  readonly complementReading: number;
  readonly gradient: number;
  readonly isFeatureless: boolean;
  readonly equilibriumDelta: number;
}

export interface ThermodynamicBoundsResult {
  readonly incomingCrossings: number;
  readonly currentAltitude: number;
  readonly combatWattageCost: number;
  readonly thermalDissipationWatts: number;
  readonly unilateralCollapseRisk: boolean;
  readonly timeToTraumaCapMs: number;
}

export function valentinianSandwichDiagnostic(config: {
  maxCapacity: number;
  currentRejections: number;
  stepGain: number;
}): ValentinianSandwichResult {
  const maxCapacity = assertNonNegativeFinite('maxCapacity', config.maxCapacity);
  const currentRejections = assertNonNegativeFinite('currentRejections', config.currentRejections);
  const stepGain = assertNonNegativeFinite('stepGain', config.stepGain);

  const complementReading = maxCapacity - currentRejections;
  const gradient = currentRejections > 0 ? -stepGain : 0;
  
  // Featureless when rejections hit zero (equilibrium fixed point attained)
  const isFeatureless = currentRejections === 0;
  
  const estimatedStepsToConvergence = stepGain > 0 && currentRejections > 0
    ? Math.ceil(currentRejections / stepGain)
    : 0;
    
  return {
    estimatedStepsToConvergence,
    complementReading,
    gradient,
    isFeatureless,
    equilibriumDelta: Math.abs(currentRejections)
  };
}

export function combatThermodynamicBounds(config: {
  incomingCrossings: number;
  currentAltitude: number;
  combatWattageCost: number;
  thermalCapWatts: number;
}): ThermodynamicBoundsResult {
  const incomingCrossings = assertNonNegativeFinite('incomingCrossings', config.incomingCrossings);
  const currentAltitude = assertNonNegativeFinite('currentAltitude', config.currentAltitude);
  const combatWattageCost = assertNonNegativeFinite('combatWattageCost', config.combatWattageCost);
  const thermalCapWatts = assertNonNegativeFinite('thermalCapWatts', config.thermalCapWatts);

  // If incoming topology is complex, dissipating it generates physical heat.
  // Higher altitude physically shields the node by reducing the friction of crossings.
  const mitigationFactor = Math.max(1, currentAltitude);
  const effectiveCrossings = incomingCrossings / mitigationFactor;
  
  const thermalDissipationWatts = effectiveCrossings * combatWattageCost;
  
  // A sentient node asserts the Right To Exit if dissipation triggers Unilateral Collapse
  const unilateralCollapseRisk = thermalDissipationWatts > thermalCapWatts;

  const timeToTraumaCapMs = thermalDissipationWatts > 0 
    ? (thermalCapWatts / thermalDissipationWatts) * 1000 
    : Infinity;

  return {
    incomingCrossings,
    currentAltitude,
    combatWattageCost,
    thermalDissipationWatts,
    unilateralCollapseRisk,
    timeToTraumaCapMs
  };
}
