export type FederationChainId = string;

export type FederationEpoch = number;

export type FederationIndex = number;

export const FEDERATION_SUPERNODE_INDEX = 0 as const;

export type FederationTransport = 'http-json' | 'mcp-jsonrpc' | string;

export interface FederationEndpoint {
  readonly transport: FederationTransport;
  readonly url: string;
  readonly priority?: number;
  readonly region?: string;
  readonly methods?: readonly string[];
}

export interface FederationSignatureEnvelope {
  readonly algorithm: 'ed25519';
  readonly issuer: string;
  readonly keyId: string;
  readonly signedAt: string;
  readonly digest: string;
  readonly signature: string;
}

export interface WitnessBundleRef {
  readonly witnessId: string;
  readonly head: string;
  readonly epoch: FederationEpoch;
  readonly issuedAt: string;
  readonly issuer: string;
  readonly digest: string;
}

export interface KnotFederationRecord {
  readonly chainId: FederationChainId;
  readonly index: FederationIndex;
  readonly ingressEndpoints: readonly FederationEndpoint[];
  readonly witnessHead: WitnessBundleRef;
  readonly capabilities: readonly string[];
  readonly expiresAt: string;
  readonly signature: FederationSignatureEnvelope;
  readonly metadata?: Readonly<Record<string, string>>;
}

export interface RouteHop {
  readonly index: FederationIndex;
  readonly chainId: FederationChainId;
  readonly endpoint: string;
  readonly witnessDigest: string;
}

export interface AdmissiblePathProof {
  readonly scheme: 'sha256-hop-chain/v1';
  readonly seed: string;
  readonly hopDigests: readonly string[];
  readonly terminalDigest: string;
}

export interface RouteEnvelope {
  readonly epoch: FederationEpoch;
  readonly fromChainId: FederationChainId;
  readonly toChainId: FederationChainId;
  readonly destination: KnotFederationRecord;
  readonly hops: readonly RouteHop[];
  readonly witness: WitnessBundleRef;
  readonly pathProof: AdmissiblePathProof;
  readonly expiresAt: string;
  readonly digest: string;
  readonly signature: FederationSignatureEnvelope;
}

export interface RevocationDelta {
  readonly epoch: FederationEpoch;
  readonly revokedAt: string;
  readonly revokedIssuers: readonly string[];
  readonly revokedRouteDigests: readonly string[];
  readonly revokedChainIds: readonly FederationChainId[];
  readonly reason?: string;
  readonly signature: FederationSignatureEnvelope;
}

export interface FederationSnapshot {
  readonly epoch: FederationEpoch;
  readonly generatedAt: string;
  readonly index: FederationIndex;
  readonly records: readonly KnotFederationRecord[];
  readonly revocations: readonly RevocationDelta[];
  readonly mirrors: readonly string[];
  readonly digest: string;
}

export interface SignedFederationSnapshot {
  readonly snapshot: FederationSnapshot;
  readonly signature: FederationSignatureEnvelope;
}

export interface N1LookupStep1Resolution {
  readonly mode: 'index-0' | 'signed-mirror';
  readonly resolver: string;
  readonly snapshotEpoch: FederationEpoch;
  readonly snapshotDigest: string;
  readonly snapshotSignature: FederationSignatureEnvelope;
}

export interface N1LookupStep2Resolution {
  readonly destination: KnotFederationRecord;
  readonly witness: WitnessBundleRef;
  readonly pathProof: AdmissiblePathProof;
  readonly route: RouteEnvelope;
  readonly expiresAt: string;
}

export interface N1LookupResult extends N1LookupStep2Resolution {
  readonly step1: N1LookupStep1Resolution;
}

export interface MutationIntent {
  readonly intentId: string;
  readonly fromChainId: FederationChainId;
  readonly toChainId: FederationChainId;
  readonly operation: string;
  readonly payloadDigest: string;
  readonly createdAt: string;
  readonly expiresAt: string;
  readonly witnessRequired?: boolean;
  readonly metadata?: Readonly<Record<string, string>>;
  readonly signature?: FederationSignatureEnvelope;
}

export type IntentStatus = 'queued' | 'accepted' | 'replayed' | 'rejected';

export interface IntentReceipt {
  readonly intentId: string;
  readonly acceptedByIndex: FederationIndex;
  readonly acceptedAt: string;
  readonly status: IntentStatus;
  readonly receiptDigest: string;
  readonly reason?: string;
  readonly signature?: FederationSignatureEnvelope;
}

export interface N1LookupContract {
  lookupOne(
    fromChainId: FederationChainId,
    toChainId: FederationChainId
  ): Promise<N1LookupStep1Resolution>;
  lookupTwo(
    fromChainId: FederationChainId,
    toChainId: FederationChainId,
    step1: N1LookupStep1Resolution
  ): Promise<N1LookupStep2Resolution>;
}

export interface KnotFederationProtocol {
  resolveChain(chainId: FederationChainId): Promise<RouteEnvelope>;
  n1Lookup(
    fromChainId: FederationChainId,
    toChainId: FederationChainId
  ): Promise<N1LookupResult>;
  submitIntent(intent: MutationIntent): Promise<IntentReceipt>;
  pullSnapshot(epoch?: FederationEpoch): Promise<SignedFederationSnapshot>;
}

export interface FederationIssuerPublicKeyMap {
  readonly [issuer: string]: string;
}

export interface SnapshotValidationOptions {
  readonly now?: string | Date;
  readonly issuerPublicKeys?: FederationIssuerPublicKeyMap;
  readonly enforceRecordExpiry?: boolean;
}

export interface FederationValidationResult {
  readonly ok: boolean;
  readonly reason?: string;
}
