import {
  buildRouteEnvelope,
  verifySignedSnapshot,
} from './snapshot.js';
import type {
  FederationChainId,
  KnotFederationRecord,
  N1LookupContract,
  N1LookupResult,
  N1LookupStep1Resolution,
  N1LookupStep2Resolution,
  RouteHop,
  SignedFederationSnapshot,
  SnapshotValidationOptions,
} from './types.js';

function resolveDestinationRecord(
  snapshot: SignedFederationSnapshot,
  chainId: FederationChainId
): KnotFederationRecord {
  const record = snapshot.snapshot.records.find((entry) => entry.chainId === chainId);
  if (!record) {
    throw new Error(`federation chain not found: ${chainId}`);
  }
  return record;
}

function selectEndpoint(record: KnotFederationRecord): string {
  const sorted = [...record.ingressEndpoints].sort(
    (left, right) => (left.priority ?? Number.MAX_SAFE_INTEGER) - (right.priority ?? Number.MAX_SAFE_INTEGER)
  );
  const endpoint = sorted[0]?.url ?? record.ingressEndpoints[0]?.url;
  if (!endpoint) {
    throw new Error(`federation record has no ingress endpoint: ${record.chainId}`);
  }
  return endpoint;
}

interface RouteSignerIdentity {
  readonly issuer: string;
  readonly keyId: string;
  readonly privateKeyPem: string;
  readonly signedAt?: string;
}

export interface SnapshotBackedN1LookupOptions {
  readonly snapshot: SignedFederationSnapshot;
  readonly resolver: string;
  readonly mode: 'index-0' | 'signed-mirror';
  readonly routeSigner: RouteSignerIdentity;
  readonly validation?: SnapshotValidationOptions;
}

export class SnapshotBackedN1Lookup implements N1LookupContract {
  private readonly snapshot: SignedFederationSnapshot;
  private readonly resolver: string;
  private readonly mode: 'index-0' | 'signed-mirror';
  private readonly routeSigner: RouteSignerIdentity;

  constructor(options: SnapshotBackedN1LookupOptions) {
    const snapshotCheck = verifySignedSnapshot(
      options.snapshot,
      options.validation ?? {}
    );
    if (!snapshotCheck.ok) {
      throw new Error(`invalid federation snapshot: ${snapshotCheck.reason}`);
    }

    this.snapshot = options.snapshot;
    this.resolver = options.resolver;
    this.mode = options.mode;
    this.routeSigner = options.routeSigner;
  }

  async lookupOne(
    _fromChainId: FederationChainId,
    _toChainId: FederationChainId
  ): Promise<N1LookupStep1Resolution> {
    return {
      mode: this.mode,
      resolver: this.resolver,
      snapshotEpoch: this.snapshot.snapshot.epoch,
      snapshotDigest: this.snapshot.snapshot.digest,
      snapshotSignature: this.snapshot.signature,
    };
  }

  async lookupTwo(
    fromChainId: FederationChainId,
    toChainId: FederationChainId,
    step1: N1LookupStep1Resolution
  ): Promise<N1LookupStep2Resolution> {
    if (step1.snapshotDigest !== this.snapshot.snapshot.digest) {
      throw new Error('stale or tampered n1 lookup step1 digest');
    }

    const destination = resolveDestinationRecord(this.snapshot, toChainId);
    const sourceRecord = this.snapshot.snapshot.records.find(
      (entry) => entry.chainId === fromChainId
    );
    const supernodeRecord = this.snapshot.snapshot.records.find(
      (entry) => entry.index === 0
    );

    const destinationEndpoint = selectEndpoint(destination);
    const hops: RouteHop[] = [];

    if (sourceRecord && sourceRecord.index === destination.index) {
      hops.push({
        index: destination.index,
        chainId: destination.chainId,
        endpoint: destinationEndpoint,
        witnessDigest: destination.witnessHead.digest,
      });
    } else {
      if (
        supernodeRecord &&
        sourceRecord?.index !== 0 &&
        destination.index !== 0
      ) {
        hops.push({
          index: 0,
          chainId: supernodeRecord.chainId,
          endpoint: selectEndpoint(supernodeRecord),
          witnessDigest: supernodeRecord.witnessHead.digest,
        });
      }

      hops.push({
        index: destination.index,
        chainId: destination.chainId,
        endpoint: destinationEndpoint,
        witnessDigest: destination.witnessHead.digest,
      });
    }

    const route = buildRouteEnvelope({
      epoch: this.snapshot.snapshot.epoch,
      fromChainId,
      toChainId,
      destination,
      hops,
      witness: destination.witnessHead,
      expiresAt: destination.expiresAt,
      signer: this.routeSigner,
    });

    return {
      destination,
      witness: destination.witnessHead,
      pathProof: route.pathProof,
      route,
      expiresAt: destination.expiresAt,
    };
  }

  async n1Lookup(
    fromChainId: FederationChainId,
    toChainId: FederationChainId
  ): Promise<N1LookupResult> {
    const step1 = await this.lookupOne(fromChainId, toChainId);
    const step2 = await this.lookupTwo(fromChainId, toChainId, step1);
    return {
      step1,
      ...step2,
    };
  }
}

export function resolveRecordFromSnapshot(
  snapshot: SignedFederationSnapshot,
  chainId: FederationChainId
): KnotFederationRecord {
  return resolveDestinationRecord(snapshot, chainId);
}
