/**
 * Aeon Flow Protocol — Stream Multiplexing with Fork/Race/Fold
 *
 * The Flow Layer sits between the Frame Layer (FlowCodec) and the
 * Application Layer (inference, ESI, sync, shell, speculate). It manages
 * multiplexed streams with three protocol-level primitives:
 *
 * - **Fork**: Create N child streams from a parent stream. Each child
 *   runs independently. Used for parallel pipelines, fragment fetching,
 *   reality branching.
 *
 * - **Race**: Mark streams as racing. The first to send a FIN frame wins.
 *   Losers are automatically vented. Used for speculative decoding,
 *   cache races, A/B testing.
 *
 * - **Fold**: Wait for all streams to complete (or vent), then
 *   merge their results via a caller-provided function. Used for shard
 *   assembly, fragment stitching, branch reconciliation.
 *
 * Stream IDs: even = client-initiated, odd = server-initiated (like HTTP/2).
 * Backpressure via per-stream high-water mark (configurable, default 64).
 * Vent propagates from parent to all descendants.
 *
 * @see docs/ebooks/145-log-rolling-pipelined-prefill/ch14-aeon-flow-protocol.md
 */

import { FlowCodec } from './FlowCodec';
import {
  FORK,
  RACE,
  FOLD,
  VENT,
  FIN,
  POISON,
  HELIX,
  DEFAULT_FLOW_CONFIG,
} from './types';
import type {
  FlowFrame,
  FlowStream,
  FlowStreamState,
  FlowTransport,
  FlowProtocolConfig,
  HelixConfig,
  HelixState,
} from './types';

// ═══════════════════════════════════════════════════════════════════════════════
// Internal helpers
// ═══════════════════════════════════════════════════════════════════════════════

type FrameHandler = (frame: FlowFrame) => void;
type VoidHandler = () => void;

/**
 * AeonFlowProtocol
 *
 * Manages multiplexed binary streams over a transport with
 * fork/race/fold semantics.
 */
export class AeonFlowProtocol {
  private streams: Map<number, FlowStream> = new Map();
  private nextEvenId = 0;
  private nextOddId = 1;
  private codec: FlowCodec;
  private transport: FlowTransport;
  private config: FlowProtocolConfig;

  // Event handlers
  private frameHandlers: Map<number, Set<FrameHandler>> = new Map();
  private endHandlers: Map<number, Set<VoidHandler>> = new Map();
  private ventHandlers: Map<number, Set<VoidHandler>> = new Map();
  private poisonHandlers: Map<number, Set<VoidHandler>> = new Map();

  // Race tracking
  private raceGroups: Map<
    string,
    {
      streamIds: number[];
      resolve: (result: { winner: number; result: Uint8Array }) => void;
      settled: boolean;
    }
  > = new Map();

  // Fold tracking
  private foldGroups: Map<
    string,
    {
      streamIds: number[];
      merger: (results: Map<number, Uint8Array>) => Uint8Array;
      resolve: (result: Uint8Array) => void;
      results: Map<number, Uint8Array>;
      completed: Set<number>;
      settled: boolean;
    }
  > = new Map();
  // Helix state tracking
  private helixGroups: Map<string, HelixState> = new Map();

  constructor(transport: FlowTransport, config?: Partial<FlowProtocolConfig>) {
    this.transport = transport;
    this.config = { ...DEFAULT_FLOW_CONFIG, ...config };
    this.codec = FlowCodec.createSync();
    this.upgradeCodecInBackground();

    // Wire up incoming data
    this.transport.onReceive((data: Uint8Array) => {
      this.handleIncoming(data);
    });
  }

  // ═══════════════════════════════════════════════════════════════════════
  // Stream management
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * Open a new root stream (no parent).
   *
   * Client-initiated streams get even IDs; server-initiated get odd IDs.
   */
  openStream(): number {
    const id = this.allocateStreamId();
    this.createStream(id);
    return id;
  }

  /**
   * Get the current state of a stream.
   */
  getStream(streamId: number): FlowStream | undefined {
    return this.streams.get(streamId);
  }

  /**
   * Get all active streams.
   */
  getActiveStreams(): FlowStream[] {
    return Array.from(this.streams.values()).filter(
      (s) => s.state !== 'closed' && s.state !== 'vented'
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  // Fork: create N child streams from a parent
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * Fork a parent stream into N child streams.
   *
   * Each child stream is independent and can send/receive frames.
   * The parent tracks all children. Venting the parent vents all children.
   *
   * @param parentStreamId The stream to fork from
   * @param count Number of child streams to create
   * @returns Array of child stream IDs
   */
  fork(parentStreamId: number, count: number): number[] {
    try {
      const parent = this.requireStream(parentStreamId, 'open');
      if (count < 1) {
        throw new RangeError('Fork count must be at least 1');
      }

      if (this.streams.size + count > this.config.maxConcurrentStreams) {
        throw new Error(
          `Cannot fork ${count} streams: would exceed maxConcurrentStreams (${this.config.maxConcurrentStreams})`
        );
      }

      const childIds: number[] = [];
      for (let i = 0; i < count; i++) {
        const childId = this.allocateStreamId();
        this.createStream(childId, parentStreamId);
        parent.children.push(childId);
        childIds.push(childId);
      }

      // Send FORK frame on parent to notify remote
      this.sendFrame(
        parentStreamId,
        FORK,
        new Uint8Array(childIds.flatMap((id) => [(id >>> 8) & 0xff, id & 0xff]))
      );

      return childIds;
  
    } catch (error) {
      throw new Error(`[fork] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  // ═══════════════════════════════════════════════════════════════════════
  // Race: first stream to FIN wins, losers are vented
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * Race multiple streams. The first to send a FIN frame wins.
   * All other streams in the race are automatically vented.
   *
   * @param streamIds Streams to race (must all be open)
   * @returns Promise resolving with the winner's stream ID and final payload
   */
  race(streamIds: number[]): Promise<{ winner: number; result: Uint8Array }> {
    try {
      if (streamIds.length < 2) {
        throw new RangeError('Race requires at least 2 streams');
      }

      // Mark all streams as racing
      for (const id of streamIds) {
        const stream = this.requireStream(id);
        stream.state = 'racing';
      }

      // Send RACE frame on each stream
      for (const id of streamIds) {
        const peerIds = streamIds.filter((sid) => sid !== id);
        this.sendFrame(
          id,
          RACE,
          new Uint8Array(
            peerIds.flatMap((pid) => [(pid >>> 8) & 0xff, pid & 0xff])
          )
        );
      }

      const groupId = `race-${streamIds.join('-')}-${Date.now()}`;

      return new Promise((resolve) => {
        this.raceGroups.set(groupId, {
          streamIds,
          resolve,
          settled: false,
        });

        // Listen for FIN on each stream
        for (const id of streamIds) {
          this.onStreamEnd(id, () => {
            this.settleRace(groupId, id);
          });
        }
      });
  
    } catch (error) {
      throw new Error(`[race] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  // ═══════════════════════════════════════════════════════════════════════
  // Fold: wait for all streams, merge results
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * Fold multiple streams: wait for all to complete (or vent),
   * then merge their results.
   *
   * @param streamIds Streams to fold
   * @param merger Function that merges results from all streams
   * @returns Promise resolving with the merged result
   */
  fold(
    streamIds: number[],
    merger: (results: Map<number, Uint8Array>) => Uint8Array
  ): Promise<Uint8Array> {
    try {
      if (streamIds.length < 1) {
        throw new RangeError('Fold requires at least 1 stream');
      }

      // Mark all streams as folding
      for (const id of streamIds) {
        const stream = this.requireStream(id);
        stream.state = 'folding';
      }

      // Send FOLD frame on each stream
      for (const id of streamIds) {
        this.sendFrame(id, FOLD, new Uint8Array(0));
      }

      const groupId = `fold-${streamIds.join('-')}-${Date.now()}`;

      return new Promise((resolve) => {
        const group = {
          streamIds,
          merger,
          resolve,
          results: new Map<number, Uint8Array>(),
          completed: new Set<number>(),
          settled: false,
        };

        this.foldGroups.set(groupId, group);

        // Listen for FIN or VENT on each stream
        for (const id of streamIds) {
          this.onStreamEnd(id, () => {
            this.settleFold(groupId, id, false);
          });
          this.onStreamVented(id, () => {
            this.settleFold(groupId, id, true);
          });
        }
      });
  
    } catch (error) {
      throw new Error(`[fold] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  // ═══════════════════════════════════════════════════════════════════════
  // Helix: pipelined rotation across forked streams
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * Create a Helix pipeline from a parent stream.
   *
   * A Helix is a specialized fork that enables rotating pipelined
   * data distribution. One half the helix rotates on either side
   * (Feed spiral and Reap spiral).
   *
   * When `config.numParameters` or `config.gnosticDimension` is provided,
   * the helix auto-dilates via the Dynamic Wallington scaling ladder:
   * the shard count is clamped to the topology-governed stage count
   * and the Wallington coefficient adjusts to the mesh regime.
   *
   * @param parentStreamId The stream to fork from
   * @param shardCount Number of shards (lanes) in the helix
   * @param config Helix configuration options
   * @returns The Helix state object
   */
  helix(
    parentStreamId: number,
    shardCount: number,
    config: Partial<HelixConfig> = {}
  ): HelixState {
    try {
      // ── Dynamic Wallington dilation ──────────────────────────────
      let effectiveShardCount = shardCount;
      let resolvedScaleName: string | undefined;
      let dilatedStageCount = shardCount;

      if (config.numParameters != null || config.gnosticDimension != null) {
        // Resolve dimension: explicit gnosticDimension takes precedence
        // over numParameters auto-resolution.
        const dimension = config.gnosticDimension;
        const numParams = config.numParameters;

        // Dimensional scaling ladder (mirrors buildDynamicWallingtonProfile)
        let scaledStageCount = 1;
        let scaleName = dimension ?? 'bythos';

        if (dimension) {
          // Explicit dimension: use the mesh-level stage mapping
          const DIMENSION_STAGE_MAP: Record<string, number> = {
            bythos: 1, barbelo: 1, syzygy: 1, proton: 1,
            primitives: 1, emanations: 2, sophia: 3,
            kenoma: 2, void: 3, pleroma: 5,
          };
          scaledStageCount = DIMENSION_STAGE_MAP[dimension] ?? 1;
          scaleName = dimension;
        } else if (numParams != null) {
          // Auto-resolve from parameter count
          if (numParams >= 50_000_000_000) { scaleName = 'pleroma'; scaledStageCount = 5; }
          else if (numParams >= 10_000_000_000) { scaleName = 'void'; scaledStageCount = 3; }
          else if (numParams >= 3_000_000_000) { scaleName = 'kenoma'; scaledStageCount = 2; }
          else if (numParams >= 1_000_000_000) { scaleName = 'sophia'; scaledStageCount = 3; }
          else if (numParams >= 500_000_000) { scaleName = 'emanations'; scaledStageCount = 2; }
          else if (numParams >= 100_000_000) { scaleName = 'primitives'; scaledStageCount = 1; }
          else if (numParams >= 10_000_000) { scaleName = 'proton'; scaledStageCount = 1; }
          else if (numParams >= 1_000_000) { scaleName = 'syzygy'; scaledStageCount = 1; }
          else if (numParams >= 100_000) { scaleName = 'barbelo'; scaledStageCount = 1; }
        }

        // Dilation: the helix shard count is clamped to the topology-governed
        // stage count. If the caller requested more shards than the topology
        // can sustain, we reduce; if fewer, we keep the caller's count.
        effectiveShardCount = Math.max(1, Math.min(shardCount, scaledStageCount + 1));
        dilatedStageCount = scaledStageCount;
        resolvedScaleName = scaleName;
      }

      const streamIds = this.fork(parentStreamId, effectiveShardCount);
      const helixConfig: HelixConfig = {
        lanes: effectiveShardCount,
        strategy: config.strategy ?? 'dual-spiral',
        wallingtonCoeff: config.wallingtonCoeff ?? 0.7,
        gnosticDimension: config.gnosticDimension,
        numParameters: config.numParameters,
      };

      const state: HelixState = {
        streamIds,
        cursor: 0,
        config: helixConfig,
        reynoldsNumber: 0,
        dilatedStageCount,
        resolvedScaleName,
      };

      const groupId = `helix-${streamIds.join('-')}-${Date.now()}`;
      this.helixGroups.set(groupId, state);

      for (const id of streamIds) {
        const stream = this.requireStream(id);
        stream.state = 'helix';
        this.sendFrame(id, HELIX, new Uint8Array([effectiveShardCount]));
      }

      return state;
  
    } catch (error) {
      throw new Error(`[helix] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  /**
   * Send a payload through the helix pipeline using rotating rotation.
   */
  rotate(helixGroupId: string, payload: Uint8Array): void {
    const state = this.helixGroups.get(helixGroupId);
    if (!state) throw new Error(`Helix group ${helixGroupId} not found`);

    const streamId = state.streamIds[state.cursor];
    this.send(streamId, payload, HELIX);

    state.cursor = (state.cursor + 1) % state.config.lanes;
  }

  // ═══════════════════════════════════════════════════════════════════════
  // Send / Vent / Close
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * Send a payload on a stream.
   */
  send(streamId: number, payload: Uint8Array, flags = 0): void {
    try {
      const stream = this.requireStream(streamId);

      // Backpressure check
      if (stream.bufferedFrames >= this.config.highWaterMark) {
        throw new Error(
          `Stream ${streamId} backpressure: ${stream.bufferedFrames} frames buffered (high-water mark: ${this.config.highWaterMark})`
        );
      }

      // Accumulate locally so race/fold can read results
      if (payload.length > 0) {
        stream.results.push(payload);
      }
      stream.bufferedFrames++;

      this.sendFrame(streamId, flags, payload);
  
    } catch (error) {
      throw new Error(`[send] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  /**
   * Finish a stream. Sends a FIN frame and transitions to 'closed'.
   *
   * @param streamId Stream to finish
   * @param finalPayload Optional final payload to include with the FIN
   */
  finish(streamId: number, finalPayload?: Uint8Array): void {
    try {
      const stream = this.requireStream(streamId);

      // Accumulate final payload locally
      if (finalPayload && finalPayload.length > 0) {
        stream.results.push(finalPayload);
      }

      this.sendFrame(streamId, FIN, finalPayload ?? new Uint8Array(0));
      stream.state = 'closed';

      // Notify end handlers
      const handlers = this.endHandlers.get(streamId);
      if (handlers) {
        for (const handler of handlers) {
          handler();
        }
      }
  
    } catch (error) {
      throw new Error(`[finish] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  /**
   * Poison a stream. Sends a POISON frame and marks the stream as vented.
   *
   * This is used when a branch of work fails definitively and should lose a
   * race without masquerading as a normal vent/cancel path.
   */
  poison(streamId: number): void {
    try {
      const stream = this.streams.get(streamId);
      if (!stream || stream.state === 'vented' || stream.state === 'closed') {
        return;
      }

      stream.state = 'vented';
      this.sendFrame(streamId, POISON, new Uint8Array(0));

      const poisonHandlers = this.poisonHandlers.get(streamId);
      if (poisonHandlers) {
        for (const handler of poisonHandlers) {
          handler();
        }
      }

      const ventHandlers = this.ventHandlers.get(streamId);
      if (ventHandlers) {
        for (const handler of ventHandlers) {
          handler();
        }
      }
  
    } catch (error) {
      throw new Error(`[poison] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  /**
   * Vent a stream. Sends a VENT frame and propagates to all descendants.
   *
   * Venting is the protocol-level equivalent of NaN propagation,
   * AbortSignal cancellation, or error cascading.
   */
  vent(streamId: number): void {
    try {
      const stream = this.streams.get(streamId);
      if (!stream || stream.state === 'vented' || stream.state === 'closed') {
        return; // Already dead
      }

      stream.state = 'vented';
      this.sendFrame(streamId, VENT, new Uint8Array(0));

      // Notify vent handlers
      const handlers = this.ventHandlers.get(streamId);
      if (handlers) {
        for (const handler of handlers) {
          handler();
        }
      }

      // Propagate vent to all children (recursively)
      for (const childId of stream.children) {
        this.vent(childId);
      }
  
    } catch (error) {
      throw new Error(`[vent] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  // ═══════════════════════════════════════════════════════════════════════
  // Event handlers
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * Register a handler for frames arriving on a specific stream.
   */
  onFrame(streamId: number, handler: FrameHandler): () => void {
    let handlers = this.frameHandlers.get(streamId);
    if (!handlers) {
      handlers = new Set();
      this.frameHandlers.set(streamId, handlers);
    }
    handlers.add(handler);
    return () => {
      handlers!.delete(handler);
    };
  }

  /**
   * Register a handler for when a stream ends (FIN received).
   */
  onStreamEnd(streamId: number, handler: VoidHandler): () => void {
    let handlers = this.endHandlers.get(streamId);
    if (!handlers) {
      handlers = new Set();
      this.endHandlers.set(streamId, handlers);
    }
    handlers.add(handler);
    return () => {
      handlers!.delete(handler);
    };
  }

  /**
   * Register a handler for when a stream is vented.
   */
  onStreamVented(streamId: number, handler: VoidHandler): () => void {
    let handlers = this.ventHandlers.get(streamId);
    if (!handlers) {
      handlers = new Set();
      this.ventHandlers.set(streamId, handlers);
    }
    handlers.add(handler);
    return () => {
      handlers!.delete(handler);
    };
  }

  /**
   * Register a handler for when a stream is poisoned.
   */
  onStreamPoisoned(streamId: number, handler: VoidHandler): () => void {
    let handlers = this.poisonHandlers.get(streamId);
    if (!handlers) {
      handlers = new Set();
      this.poisonHandlers.set(streamId, handlers);
    }
    handlers.add(handler);
    return () => {
      handlers!.delete(handler);
    };
  }

  // ═══════════════════════════════════════════════════════════════════════
  // Destroy
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * Close the protocol and underlying transport.
   * Vents all open streams first.
   */
  destroy(): void {
    try {
      for (const [id, stream] of this.streams) {
        if (stream.state !== 'closed' && stream.state !== 'vented') {
          stream.state = 'closed';
        }
      }
      this.streams.clear();
      this.frameHandlers.clear();
      this.endHandlers.clear();
      this.ventHandlers.clear();
      this.poisonHandlers.clear();
      this.raceGroups.clear();
      this.foldGroups.clear();
      this.transport.close();
  
    } catch (error) {
      throw new Error(`[destroy] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  // ═══════════════════════════════════════════════════════════════════════
  // Private: incoming frame handling
  // ═══════════════════════════════════════════════════════════════════════

  private handleIncoming(data: Uint8Array): void {
    // Decode all frames from the received buffer
    let frames: FlowFrame[];
    try {
      frames = this.codec.decodeBatch(data);
    } catch {
      // Malformed data — nothing to do
      return;
    }

    for (const frame of frames) {
      this.handleFrame(frame);
    }
  }

  private handleFrame(frame: FlowFrame): void {
    try {
      const { streamId, flags } = frame;

      // Auto-create stream if we receive a frame on an unknown stream
      // (the remote opened it)
      if (!this.streams.has(streamId)) {
        this.createStream(streamId);
      }

      const stream = this.streams.get(streamId)!;

      // Handle control flags
      if (flags & POISON) {
        stream.state = 'vented';

        const poisonHandlers = this.poisonHandlers.get(streamId);
        if (poisonHandlers) {
          for (const handler of poisonHandlers) {
            handler();
          }
        }

        const ventHandlers = this.ventHandlers.get(streamId);
        if (ventHandlers) {
          for (const handler of ventHandlers) {
            handler();
          }
        }
        return;
      }

      if (flags & VENT) {
        this.vent(streamId);
        return;
      }

      if (flags & FIN) {
        // Accumulate final payload if present
        if (frame.payload.length > 0) {
          stream.results.push(frame.payload);
        }
        stream.state = 'closed';

        // Notify end handlers
        const endHandlers = this.endHandlers.get(streamId);
        if (endHandlers) {
          for (const handler of endHandlers) {
            handler();
          }
        }
        return;
      }

      if (flags & FORK) {
        // Remote is notifying us about forked child streams
        // Parse child IDs from payload (u16 pairs)
        for (let i = 0; i + 1 < frame.payload.length; i += 2) {
          const childId = (frame.payload[i] << 8) | frame.payload[i + 1];
          if (!this.streams.has(childId)) {
            this.createStream(childId, streamId);
          }
          if (!stream.children.includes(childId)) {
            stream.children.push(childId);
          }
        }
        return;
      }

      if (flags & HELIX) {
        // Helix frames represent sharded rotation. Log and continue.
        // (Full syzygy-cannon layer assembly happens in the application).
        stream.state = 'helix';
      }

      // Data frame — accumulate result and notify handlers
      if (frame.payload.length > 0) {
        stream.results.push(frame.payload);
      }
      stream.bufferedFrames++;

      const handlers = this.frameHandlers.get(streamId);
      if (handlers) {
        for (const handler of handlers) {
          handler(frame);
        }
      }
  
    } catch (error) {
      throw new Error(`[handleFrame] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  // ═══════════════════════════════════════════════════════════════════════
  // Private: race/fold settlement
  // ═══════════════════════════════════════════════════════════════════════

  private settleRace(groupId: string, winnerId: number): void {
    try {
      const group = this.raceGroups.get(groupId);
      if (!group || group.settled) return;
      group.settled = true;

      const winnerStream = this.streams.get(winnerId);
      const result = winnerStream
        ? this.concatenateResults(winnerStream.results)
        : new Uint8Array(0);

      // Vent all losers
      for (const id of group.streamIds) {
        if (id !== winnerId) {
          this.vent(id);
        }
      }

      group.resolve({ winner: winnerId, result });
      this.raceGroups.delete(groupId);
  
    } catch (error) {
      throw new Error(`[settleRace] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  private settleFold(
    groupId: string,
    streamId: number,
    wasVented: boolean
  ): void {
    try {
      const group = this.foldGroups.get(groupId);
      if (!group || group.settled) return;

      group.completed.add(streamId);

      if (!wasVented) {
        const stream = this.streams.get(streamId);
        if (stream) {
          group.results.set(streamId, this.concatenateResults(stream.results));
        }
      }
      // Vented streams contribute nothing to the merge

      // Check if all streams have completed or been vented
      if (group.completed.size >= group.streamIds.length) {
        group.settled = true;
        const merged = group.merger(group.results);
        group.resolve(merged);
        this.foldGroups.delete(groupId);
      }
  
    } catch (error) {
      throw new Error(`[settleFold] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  // ═══════════════════════════════════════════════════════════════════════
  // Private: stream helpers
  // ═══════════════════════════════════════════════════════════════════════

  private allocateStreamId(): number {
    if (this.config.role === 'client') {
      const id = this.nextEvenId;
      this.nextEvenId += 2;
      return id;
    } else {
      const id = this.nextOddId;
      this.nextOddId += 2;
      return id;
    }
  }

  private createStream(id: number, parent?: number): FlowStream {
    const stream: FlowStream = {
      id,
      state: 'open',
      parent,
      children: [],
      nextSequence: 0,
      bufferedFrames: 0,
      results: [],
    };
    this.streams.set(id, stream);
    return stream;
  }

  private requireStream(
    streamId: number,
    ...allowedStates: FlowStreamState[]
  ): FlowStream {
    const stream = this.streams.get(streamId);
    if (!stream) {
      throw new Error(`Stream ${streamId} does not exist`);
    }
    if (allowedStates.length > 0 && !allowedStates.includes(stream.state)) {
      throw new Error(
        `Stream ${streamId} is in state '${
          stream.state
        }', expected one of: ${allowedStates.join(', ')}`
      );
    }
    return stream;
  }

  private sendFrame(
    streamId: number,
    flags: number,
    payload: Uint8Array
  ): void {
    const stream = this.streams.get(streamId);
    if (!stream) return;

    const frame: FlowFrame = {
      streamId,
      sequence: stream.nextSequence++,
      flags,
      payload,
    };

    const encoded = this.codec.encode(frame);
    this.transport.send(encoded);
  }

  private concatenateResults(chunks: Uint8Array[]): Uint8Array {
    try {
      if (chunks.length === 0) return new Uint8Array(0);
      if (chunks.length === 1) return chunks[0];

      let totalLen = 0;
      for (const chunk of chunks) totalLen += chunk.length;

      const result = new Uint8Array(totalLen);
      let offset = 0;
      for (const chunk of chunks) {
        result.set(chunk, offset);
        offset += chunk.length;
      }
      return result;
  
    } catch (error) {
      throw new Error(`[concatenateResults] ${error instanceof Error ? error.message : String(error)}`);
    }
}

  /**
   * Attempt to upgrade to WASM codec without delaying protocol startup.
   * JS codec remains the correctness path if WASM is unavailable.
   */
  private upgradeCodecInBackground(): void {
    const wasmMode = this.config.codecWasmMode ?? 'auto';
    if (wasmMode === 'off') {
      return;
    }

    FlowCodec.create({ wasmMode })
      .then((codec) => {
        if (codec.isWasmAccelerated) {
          this.codec = codec;
        }
      })
      .catch(() => {
        // Graceful fallback: keep JS codec
      });
  }
}
