/**
 * Wrangler TOML → ForgoProjectConfig translator
 *
 * Parses aeon.toml or wrangler.toml files and translates them into ForgoProjectConfig
 * for the ForgoCD deployment engine. Handles [[array.of.tables]] syntax
 * for d1_databases, kv_namespaces, r2_buckets, services, and durable_objects.
 */

import type {
  ForgoProjectConfig,
  ForgoBinding,
  ForgoRuntime,
  ForgoProcessKind,
} from './types.ts';

// ---------------------------------------------------------------------------
// TOML parser — extends the aeon-config pattern to handle [[array.of.tables]]
// ---------------------------------------------------------------------------

function stripTomlComment(line: string): string {
  let inSingle = false;
  let inDouble = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    // Skip escaped characters inside double-quoted strings
    if (ch === '\\' && inDouble && i + 1 < line.length) {
      i++; // skip the escaped char
      continue;
    }
    if (ch === "'" && !inDouble) {
      inSingle = !inSingle;
      continue;
    }
    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
      continue;
    }
    if (ch === '#' && !inSingle && !inDouble) return line.slice(0, i);
  }
  return line;
}

function splitArrayValues(raw: string): string[] {
  const values: string[] = [];
  let current = '';
  let inSingle = false;
  let inDouble = false;
  let braceDepth = 0;
  let bracketDepth = 0;

  for (let i = 0; i < raw.length; i++) {
    const ch = raw[i];
    // Skip escaped characters inside double-quoted strings
    if (ch === '\\' && inDouble && i + 1 < raw.length) {
      current += ch + raw[i + 1];
      i++;
      continue;
    }
    if (ch === "'" && !inDouble) {
      inSingle = !inSingle;
      current += ch;
      continue;
    }
    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
      current += ch;
      continue;
    }
    if (!inSingle && !inDouble) {
      if (ch === '{') braceDepth++;
      else if (ch === '}') braceDepth--;
      else if (ch === '[') bracketDepth++;
      else if (ch === ']') bracketDepth--;
    }
    if (
      ch === ',' &&
      !inSingle &&
      !inDouble &&
      braceDepth === 0 &&
      bracketDepth === 0
    ) {
      values.push(current.trim());
      current = '';
      continue;
    }
    current += ch;
  }
  if (current.trim()) values.push(current.trim());
  return values;
}

/**
 * Unescape TOML double-quoted string escape sequences.
 * Single-quoted strings are literal per TOML spec (no escapes).
 */
function unescapeTomlString(s: string): string {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\' && i + 1 < s.length) {
      const next = s[i + 1];
      switch (next) {
        case '"':
          result += '"';
          i++;
          break;
        case '\\':
          result += '\\';
          i++;
          break;
        case 'n':
          result += '\n';
          i++;
          break;
        case 't':
          result += '\t';
          i++;
          break;
        case 'r':
          result += '\r';
          i++;
          break;
        default:
          result += '\\' + next;
          i++;
          break;
      }
    } else {
      result += s[i];
    }
  }
  return result;
}

function parseTomlScalar(raw: string): unknown {
  const value = raw.trim();
  if (!value) return '';

  // Double-quoted strings: apply escape processing
  if (value.startsWith('"') && value.endsWith('"')) {
    return unescapeTomlString(value.slice(1, -1));
  }
  // Single-quoted strings: literal (no escapes per TOML spec)
  if (value.startsWith("'") && value.endsWith("'")) {
    return value.slice(1, -1);
  }

  if (value === 'true' || value === 'false') return value === 'true';
  if (/^-?\d+(\.\d+)?$/.test(value)) return Number(value);

  if (value.startsWith('[') && value.endsWith(']')) {
    const inner = value.slice(1, -1).trim();
    if (!inner) return [];
    return splitArrayValues(inner).map((item) => parseTomlScalar(item));
  }

  // Inline table: { key = val, key2 = val2 }
  if (value.startsWith('{') && value.endsWith('}')) {
    return parseInlineTable(value.slice(1, -1));
  }

  return value;
}

function parseInlineTable(raw: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  const pairs = splitArrayValues(raw);
  for (const pair of pairs) {
    const eqIdx = pair.indexOf('=');
    if (eqIdx < 0) continue;
    const key = pair.slice(0, eqIdx).trim();
    const val = pair.slice(eqIdx + 1).trim();
    result[key] = parseTomlScalar(val);
  }
  return result;
}

interface WranglerDoc {
  /** Top-level scalar keys */
  root: Record<string, unknown>;
  /** [table] sections */
  tables: Record<string, Record<string, unknown>>;
  /** [[array.of.tables]] sections */
  arrayTables: Record<string, Array<Record<string, unknown>>>;
}

/**
 * Parse a TOML document with support for [[array.of.tables]] syntax.
 */
export function parseWranglerToml(text: string): WranglerDoc {
  const doc: WranglerDoc = { root: {}, tables: {}, arrayTables: {} };
  let currentSection: string | null = null;
  let isArrayTable = false;
  let currentArrayEntry: Record<string, unknown> | null = null;

  for (const lineRaw of text.split(/\r?\n/)) {
    const line = stripTomlComment(lineRaw).trim();
    if (!line) continue;

    // [[array.of.tables]]
    if (line.startsWith('[[') && line.endsWith(']]')) {
      const tableName = line.slice(2, -2).trim();
      currentSection = tableName;
      isArrayTable = true;
      currentArrayEntry = {};
      if (!doc.arrayTables[tableName]) doc.arrayTables[tableName] = [];
      doc.arrayTables[tableName].push(currentArrayEntry);
      continue;
    }

    // [table]
    if (line.startsWith('[') && line.endsWith(']')) {
      currentSection = line.slice(1, -1).trim();
      isArrayTable = false;
      currentArrayEntry = null;
      if (!doc.tables[currentSection]) doc.tables[currentSection] = {};
      continue;
    }

    // key = value
    const eqIdx = line.indexOf('=');
    if (eqIdx < 0) continue;

    const key = line.slice(0, eqIdx).trim();
    const rawValue = line.slice(eqIdx + 1).trim();
    const value = parseTomlScalar(rawValue);

    if (isArrayTable && currentArrayEntry) {
      currentArrayEntry[key] = value;
    } else if (currentSection) {
      doc.tables[currentSection]![key] = value;
    } else {
      doc.root[key] = value;
    }
  }

  return doc;
}

// ---------------------------------------------------------------------------
// wrangler.toml → ForgoProjectConfig
// ---------------------------------------------------------------------------

function inferKind(doc: WranglerDoc): ForgoProcessKind {
  const name = String(doc.root.name || '');
  const main = String(doc.root.main || '');

  if (name.includes('mcp') || main.includes('mcp')) return 'mcp';
  if (name.includes('api') || name.includes('gateway')) return 'api';

  // If it has [assets] or [site], it's a static site
  if (doc.tables.assets || doc.tables.site) return 'site';

  return 'worker';
}

function inferRuntime(_doc: WranglerDoc): ForgoRuntime {
  // All CF workers translate to bun runtime in Forgo
  return 'bun';
}

function extractBindings(doc: WranglerDoc): ForgoBinding[] {
  const bindings: ForgoBinding[] = [];

  // [[kv_namespaces]]
  for (const entry of doc.arrayTables.kv_namespaces || []) {
    bindings.push({
      type: 'kv',
      binding: String(entry.binding || ''),
      id: entry.id ? String(entry.id) : undefined,
    });
  }

  // [[d1_databases]]
  for (const entry of doc.arrayTables.d1_databases || []) {
    bindings.push({
      type: 'd1',
      binding: String(entry.binding || ''),
      id: entry.database_id ? String(entry.database_id) : undefined,
    });
  }

  // [[r2_buckets]]
  for (const entry of doc.arrayTables.r2_buckets || []) {
    bindings.push({
      type: 'r2',
      binding: String(entry.binding || ''),
      id: entry.bucket_name ? String(entry.bucket_name) : undefined,
    });
  }

  // [[services]]
  for (const entry of doc.arrayTables.services || []) {
    bindings.push({
      type: 'service',
      binding: String(entry.binding || ''),
      service: entry.service ? String(entry.service) : undefined,
    });
  }

  // [[durable_objects.bindings]]
  for (const entry of doc.arrayTables['durable_objects.bindings'] || []) {
    bindings.push({
      type: 'durable-object',
      binding: String(entry.name || ''),
      id: entry.class_name ? String(entry.class_name) : undefined,
    });
  }

  return bindings;
}

function extractServiceDeps(doc: WranglerDoc): string[] {
  const deps: string[] = [];
  for (const entry of doc.arrayTables.services || []) {
    if (entry.service) deps.push(String(entry.service));
  }
  return deps;
}

function extractEnv(doc: WranglerDoc): Record<string, string> {
  const env: Record<string, string> = {};
  const vars = doc.tables.vars;
  if (vars) {
    for (const [key, value] of Object.entries(vars)) {
      env[key] = String(value);
    }
  }
  return env;
}

/**
 * Parse a wrangler.toml string and return a ForgoProjectConfig.
 */
export function parseWranglerConfig(tomlText: string): {
  config: ForgoProjectConfig;
  serviceDeps: string[];
} {
  const doc = parseWranglerToml(tomlText);

  const name = String(doc.root.name || 'unknown');
  const main = String(doc.root.main || 'src/index.ts');
  const runtime = inferRuntime(doc);
  const kind = inferKind(doc);
  const bindings = extractBindings(doc);
  const serviceDeps = extractServiceDeps(doc);
  const env = extractEnv(doc);
  const assets = doc.tables.assets
    ? { directory: String(doc.tables.assets.directory || 'public') }
    : undefined;

  const buildCommand = doc.tables.build
    ? String(doc.tables.build.command || '')
    : undefined;

  return {
    config: {
      name,
      runtime,
      kind,
      entryPoint: main,
      env,
      assets,
      bindings,
      buildCommand: buildCommand || undefined,
    },
    serviceDeps,
  };
}

// ---------------------------------------------------------------------------
// ForgoProjectConfig → aeon.toml
// ---------------------------------------------------------------------------

/**
 * Escape a string value for safe embedding in a TOML double-quoted string.
 * Handles backslashes, double quotes, newlines, tabs, and carriage returns.
 */
function escapeTomlValue(value: string): string {
  return value
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
}

/**
 * Serialize a ForgoProjectConfig to aeon.toml format.
 * Used by the `forge translate` command.
 */
export function forgoConfigToAeonToml(config: ForgoProjectConfig): string {
  const lines: string[] = [
    '# aeon.toml',
    '# Translated from wrangler.toml by ForgoCD',
    '',
    '[project]',
    `name = "${escapeTomlValue(config.name)}"`,
    `runtime = "${escapeTomlValue(config.runtime)}"`,
    `kind = "${escapeTomlValue(config.kind)}"`,
    `entryPoint = "${escapeTomlValue(config.entryPoint)}"`,
  ];

  if (config.port !== undefined) {
    lines.push(`port = ${config.port}`);
  }

  if (config.buildCommand) {
    lines.push(`buildCommand = "${escapeTomlValue(config.buildCommand)}"`);
  }

  if (config.assets) {
    lines.push(
      '',
      '[assets]',
      `directory = "${escapeTomlValue(config.assets.directory)}"`
    );
  }

  if (Object.keys(config.env).length > 0) {
    lines.push('', '[vars]');
    for (const [key, value] of Object.entries(config.env)) {
      lines.push(`${key} = "${escapeTomlValue(value)}"`);
    }
  }

  for (const binding of config.bindings) {
    lines.push('');
    switch (binding.type) {
      case 'kv':
        lines.push('[[kv_namespaces]]');
        lines.push(`binding = "${escapeTomlValue(binding.binding)}"`);
        if (binding.id) lines.push(`id = "${escapeTomlValue(binding.id)}"`);
        break;
      case 'd1':
        lines.push('[[d1_databases]]');
        lines.push(`binding = "${escapeTomlValue(binding.binding)}"`);
        if (binding.id)
          lines.push(`database_id = "${escapeTomlValue(binding.id)}"`);
        break;
      case 'r2':
        lines.push('[[r2_buckets]]');
        lines.push(`binding = "${escapeTomlValue(binding.binding)}"`);
        if (binding.id)
          lines.push(`bucket_name = "${escapeTomlValue(binding.id)}"`);
        break;
      case 'service':
        lines.push('[[services]]');
        lines.push(`binding = "${escapeTomlValue(binding.binding)}"`);
        if (binding.service)
          lines.push(`service = "${escapeTomlValue(binding.service)}"`);
        break;
      case 'durable-object':
        lines.push('[[durable_objects.bindings]]');
        lines.push(`name = "${escapeTomlValue(binding.binding)}"`);
        if (binding.id)
          lines.push(`class_name = "${escapeTomlValue(binding.id)}"`);
        break;
    }
  }

  if (config.gnosis) {
    lines.push('', '[gnosis]');
    if (config.gnosis.host) {
      lines.push(`host = "${escapeTomlValue(config.gnosis.host)}"`);
    }
    if (config.gnosis.runtimeTarget) {
      lines.push(
        `runtimeTarget = "${escapeTomlValue(config.gnosis.runtimeTarget)}"`
      );
    }
    if (config.gnosis.surfaces && config.gnosis.surfaces.length > 0) {
      lines.push(
        `surfaces = [${config.gnosis.surfaces
          .map((surface) => `"${escapeTomlValue(surface)}"`)
          .join(', ')}]`
      );
    }
  }

  lines.push('');
  return lines.join('\n');
}
