/**
 * @a0n/auth - Capability Delegation
 *
 * UCAN capability delegation and proof chain verification
 */

import type {
  DID,
  Identity,
  Capability,
  UCANToken,
  DelegationOptions,
  DelegationChainResult,
} from './ucanTypes.js';
import { createUCAN, parseUCAN, verifyUCAN, checkCapability } from './token.js';

/**
 * Delegate capabilities from a parent UCAN to a new audience
 *
 * Creates a child UCAN that derives its authority from the parent.
 * The child's capabilities cannot exceed the parent's capabilities.
 *
 * @param parentToken - Parent UCAN token providing the authority
 * @param issuer - Identity of the delegator (must match parent's audience)
 * @param audience - DID receiving the delegated capabilities
 * @param capabilities - Capabilities to delegate (must be subset of parent)
 * @param options - Delegation options
 * @returns New UCAN token
 *
 * @example
 * ```typescript
 * // Alice has a token granting file/* access
 * // Alice delegates file/read to Bob
 * const bobToken = await delegateCapabilities(
 *   aliceToken,
 *   aliceIdentity,
 *   bobDID,
 *   [{ can: 'file/read', with: 'storage://bucket/*' }],
 * );
 * ```
 */
export async function delegateCapabilities(
  parentToken: string,
  issuer: Identity,
  audience: DID,
  capabilities: Capability[],
  options?: DelegationOptions
): Promise<string> {
  const parent = parseUCAN(parentToken);

  // Verify issuer matches parent's audience
  if (parent.payload.aud !== issuer.did) {
    throw new Error(
      `Issuer DID ${issuer.did} does not match parent audience ${parent.payload.aud}`
    );
  }

  // Check that requested capabilities are within parent's capabilities
  const { attenuate = true } = options || {};

  if (attenuate) {
    for (const cap of capabilities) {
      if (!checkCapability(parent.payload.att, cap)) {
        throw new Error(
          `Cannot delegate capability "${cap.can}" on "${cap.with}" - not granted by parent`
        );
      }
    }
  }

  // Build proof chain
  const existingProofs = parent.payload.prf || [];
  const proofs = [...existingProofs, parentToken];

  // Create child UCAN with parent's expiration as max
  const parentExp = parent.payload.exp;
  const now = Math.floor(Date.now() / 1000);
  const requestedExp = options?.expirationSeconds
    ? now + options.expirationSeconds
    : parentExp;

  // Child cannot expire after parent
  const expirationSeconds = Math.min(requestedExp, parentExp) - now;

  return createUCAN(issuer, audience, capabilities, {
    ...options,
    expirationSeconds,
    proofs,
  });
}

/**
 * Verify a delegation chain
 *
 * Follows the proof chain from a UCAN back to a root issuer,
 * verifying signatures and capability attenuation at each step.
 *
 * @param token - Leaf UCAN token to verify
 * @param resolvePublicKey - Function to resolve public key from DID
 * @returns Delegation chain result
 *
 * @example
 * ```typescript
 * const result = await verifyDelegationChain(token, async (did) => {
 *   // Look up public key for this DID
 *   return await keyStore.getPublicKey(did);
 * });
 *
 * if (result.valid) {
 *   console.log('Chain is valid, root issuer:', result.rootIssuer);
 * }
 * ```
 */
export async function verifyDelegationChain(
  token: string,
  resolvePublicKey: (did: DID) => Promise<JsonWebKey | null>
): Promise<DelegationChainResult> {
  const chain: UCANToken[] = [];
  let currentToken = token;

  // Build chain by following proofs
  while (true) {
    let parsed: UCANToken;

    try {
      parsed = parseUCAN(currentToken);
    } catch (error) {
      return {
        valid: false,
        chain,
        error: `Failed to parse token: ${
          error instanceof Error ? error.message : 'Unknown'
        }`,
      };
    }

    // Resolve issuer's public key
    const issuerPublicKey = await resolvePublicKey(parsed.payload.iss);
    if (!issuerPublicKey) {
      return {
        valid: false,
        chain,
        error: `Could not resolve public key for issuer: ${parsed.payload.iss}`,
      };
    }

    // Verify signature
    const verification = await verifyUCAN(currentToken, issuerPublicKey);
    if (!verification.valid) {
      return {
        valid: false,
        chain,
        error: verification.error,
      };
    }

    chain.unshift(parsed); // Add to beginning (we're walking backwards)

    // Check if there are more proofs
    const proofs = parsed.payload.prf;
    if (!proofs || proofs.length === 0) {
      // This is the root
      break;
    }

    // Verify all proofs in the chain, following the most recent parent
    // for the main chain walk, but validating all proof signatures
    for (let i = 0; i < proofs.length - 1; i++) {
      const proofToken = proofs[i];
      if (proofToken.includes('.')) {
        // Embedded token - verify its signature
        const proofParsed = parseUCAN(proofToken);
        const proofKey = await resolvePublicKey(proofParsed.payload.iss);
        if (proofKey) {
          const proofVerification = await verifyUCAN(proofToken, proofKey);
          if (!proofVerification.valid) {
            return {
              valid: false,
              chain,
              error: `Proof at index ${i} failed verification: ${proofVerification.error}`,
            };
          }
        }
      }
    }
    currentToken = proofs[proofs.length - 1]; // Follow the most recent parent
  }

  // Verify capability attenuation through the chain
  for (let i = 1; i < chain.length; i++) {
    const parent = chain[i - 1];
    const child = chain[i];

    // Child's audience must match child's issuer
    if (parent.payload.aud !== child.payload.iss) {
      return {
        valid: false,
        chain,
        error: `Chain broken: parent audience ${parent.payload.aud} !== child issuer ${child.payload.iss}`,
      };
    }

    // Child's capabilities must be subset of parent's
    for (const childCap of child.payload.att) {
      if (!checkCapability(parent.payload.att, childCap)) {
        return {
          valid: false,
          chain,
          error: `Capability escalation detected: "${childCap.can}" on "${childCap.with}" not in parent`,
        };
      }
    }

    // Child cannot expire after parent
    if (child.payload.exp > parent.payload.exp) {
      return {
        valid: false,
        chain,
        error: `Child expiration ${child.payload.exp} exceeds parent ${parent.payload.exp}`,
      };
    }
  }

  return {
    valid: true,
    chain,
    rootIssuer: chain[0].payload.iss,
  };
}

/**
 * Attenuate capabilities (reduce scope)
 *
 * Creates a new capability array that is a strict subset of the original.
 *
 * @param original - Original capabilities
 * @param restrictions - How to restrict each capability
 * @returns Attenuated capabilities
 */
export function attenuateCapabilities(
  original: Capability[],
  restrictions: Array<{
    original: Capability;
    restricted: Capability;
  }>
): Capability[] {
  return restrictions.map(({ original: orig, restricted }) => {
    // Verify the original capability exists in the provided set
    if (!checkCapability(original, orig)) {
      throw new Error(
        `Original capability "${orig.can}" on "${orig.with}" not found in provided capabilities`
      );
    }
    // Verify the restriction is valid (restricted is subset of original)
    if (!checkCapability([orig], restricted)) {
      throw new Error(
        `Invalid attenuation: "${restricted.can}" on "${restricted.with}" is not subset of "${orig.can}" on "${orig.with}"`
      );
    }
    return restricted;
  });
}

/**
 * Get the root issuer from a delegation chain
 *
 * @param token - UCAN token
 * @param resolveToken - Function to resolve parent tokens
 * @returns Root issuer DID
 */
export async function getRootIssuer(
  token: string,
  resolveToken?: (proof: string) => Promise<string | null>
): Promise<DID> {
  let currentToken = token;

  while (true) {
    const parsed = parseUCAN(currentToken);
    const proofs = parsed.payload.prf;

    if (!proofs || proofs.length === 0) {
      return parsed.payload.iss;
    }

    // Try to get parent token
    const parentProof = proofs[proofs.length - 1];

    // If it looks like a full token, use it directly
    if (parentProof.includes('.')) {
      currentToken = parentProof;
    } else if (resolveToken) {
      // Otherwise try to resolve it
      const resolved = await resolveToken(parentProof);
      if (!resolved) {
        // Can't resolve further, return current issuer
        return parsed.payload.iss;
      }
      currentToken = resolved;
    } else {
      // Can't resolve, return current issuer
      return parsed.payload.iss;
    }
  }
}

/**
 * Calculate the depth of a delegation chain
 *
 * @param token - UCAN token
 * @returns Depth (0 for root token, 1 for first delegation, etc.)
 */
export function getDelegationDepth(token: string): number {
  const parsed = parseUCAN(token);
  const proofs = parsed.payload.prf;

  if (!proofs || proofs.length === 0) {
    return 0;
  }

  // Count embedded tokens in proof chain
  let depth = 0;
  for (const proof of proofs) {
    if (proof.includes('.')) {
      // This is an embedded token
      depth = Math.max(depth, getDelegationDepth(proof) + 1);
    } else {
      // This is a reference, count as 1 level
      depth = Math.max(depth, 1);
    }
  }

  return depth;
}

/**
 * Check if capabilities can be delegated
 *
 * @param parentCapabilities - Capabilities from parent token
 * @param childCapabilities - Capabilities to delegate
 * @returns True if all child capabilities are subset of parent
 */
export function canDelegate(
  parentCapabilities: Capability[],
  childCapabilities: Capability[]
): boolean {
  for (const child of childCapabilities) {
    if (!checkCapability(parentCapabilities, child)) {
      return false;
    }
  }
  return true;
}
