export interface XRangerPlatformProxyOptions
  extends Omit<XRangerConfigResolveOptions, 'script'> {
  readonly environment?: string;
  readonly configPath?: string;
  readonly persist?: boolean | { path: string };
  readonly remoteBindings?: boolean;
}

export interface XRangerPlatformProxy<Env = Record<string, unknown>> {
  readonly env: Env;
  readonly cf: Readonly<Record<string, unknown>>;
  readonly ctx: XRangerExecutionContext;
  readonly caches: {
    readonly default: XRangerNoopCache;
    open(name: string): Promise<XRangerNoopCache>;
  };
  dispose(): Promise<void>;
}

export class XRangerExecutionContext {
  private readonly tasks: Promise<unknown>[] = [];

  waitUntil(promise: Promise<unknown>): void {
    this.tasks.push(promise);
  }

  passThroughOnException(): void {
    // local emulation: intentionally a no-op
  }

  async drain(): Promise<void> {
    await Promise.allSettled(this.tasks);
  }
}

export class XRangerNoopCache {
  async match(): Promise<undefined> {
    return undefined;
  }

  async put(): Promise<void> {
    // no-op by design
  }

  async delete(): Promise<boolean> {
    return false;
  }
}

interface PersistLocation {
  readonly enabled: boolean;
  readonly root?: string;
}

interface KvEntryRecord {
  readonly kind: 'text' | 'bytes';
  readonly value: string;
  readonly metadata?: unknown;
  readonly expiration?: number;
}

/** Async backing store for KV bodies/index. */
export interface XRangerKvBackingStore {
  get(key: string): Promise<KvEntryRecord | null>;
  put(key: string, record: KvEntryRecord): Promise<void>;
  delete(key: string): Promise<void>;
  list(
    prefix?: string
  ): Promise<Array<{ name: string; metadata?: unknown; expiration?: number }>>;
}

export class JSONBackingStore implements XRangerKvBackingStore {
  private readonly store = new Map<string, KvEntryRecord>();

  constructor(private readonly filePath?: string) {
    if (filePath) {
      const data = loadJsonFile<Record<string, KvEntryRecord>>(filePath, {});
      for (const [key, value] of Object.entries(data)) {
        this.store.set(key, value);
      }
    }
  }

  private persist(): void {
    if (!this.filePath) {
      return;
    }
    writeJsonFile(this.filePath, Object.fromEntries(this.store.entries()));
  }

  async get(key: string): Promise<KvEntryRecord | null> {
    const entry = this.store.get(key);
    if (!entry) return null;
    if (entry.expiration && entry.expiration < Date.now() / 1000) {
      this.store.delete(key);
      this.persist();
      return null;
    }
    return entry;
  }

  async put(key: string, record: KvEntryRecord): Promise<void> {
    this.store.set(key, record);
    this.persist();
  }

  async delete(key: string): Promise<void> {
    this.store.delete(key);
    this.persist();
  }

  async list(
    prefix?: string
  ): Promise<Array<{ name: string; metadata?: unknown; expiration?: number }>> {
    const now = Date.now() / 1000;
    const results: Array<{
      name: string;
      metadata?: unknown;
      expiration?: number;
    }> = [];
    for (const [key, entry] of this.store.entries()) {
      if (entry.expiration && entry.expiration < now) {
        continue;
      }
      if (!prefix || key.startsWith(prefix)) {
        results.push({
          name: key,
          metadata: entry.metadata,
          expiration: entry.expiration,
        });
      }
    }
    return results.sort((a, b) => a.name.localeCompare(b.name));
  }
}

export class VaultBackingStore implements XRangerKvBackingStore {
  private readonly index = new Map<
    string,
    Omit<KvEntryRecord, 'value'> & { bodyHash: string }
  >();
  private readonly indexPath: string;
  private readonly bodiesDir: string;

  constructor(root: string) {
    this.indexPath = resolve(root, 'index.json');
    this.bodiesDir = ensureDirectory(resolve(root, 'bodies'));

    const data = loadJsonFile<
      Record<string, Omit<KvEntryRecord, 'value'> & { bodyHash: string }>
    >(this.indexPath, {});
    for (const [key, value] of Object.entries(data)) {
      this.index.set(key, value);
    }
  }

  private persist(): void {
    writeJsonFile(this.indexPath, Object.fromEntries(this.index.entries()));
  }

  async get(key: string): Promise<KvEntryRecord | null> {
    const meta = this.index.get(key);
    if (!meta) return null;

    if (meta.expiration && meta.expiration < Date.now() / 1000) {
      await this.delete(key);
      return null;
    }

    try {
      const bodyPath = resolve(this.bodiesDir, meta.bodyHash);
      const value = readFileSync(bodyPath, 'utf8');
      return { ...meta, value };
    } catch {
      return null;
    }
  }

  async put(key: string, record: KvEntryRecord): Promise<void> {
    const bodyHash = cacheFingerprint48HexSync(record.value);
    const bodyPath = resolve(this.bodiesDir, bodyHash);

    if (!existsSync(bodyPath)) {
      writeFileSync(bodyPath, record.value);
    }

    const { value, ...meta } = record;
    this.index.set(key, { ...meta, bodyHash });
    this.persist();
  }

  async delete(key: string): Promise<void> {
    this.index.delete(key);
    this.persist();
  }

  async list(
    prefix?: string
  ): Promise<Array<{ name: string; metadata?: unknown; expiration?: number }>> {
    const now = Date.now() / 1000;
    const results: Array<{
      name: string;
      metadata?: unknown;
      expiration?: number;
    }> = [];
    for (const [key, meta] of this.index.entries()) {
      if (meta.expiration && meta.expiration < now) {
        continue;
      }
      if (!prefix || key.startsWith(prefix)) {
        results.push({
          name: key,
          metadata: meta.metadata,
          expiration: meta.expiration,
        });
      }
    }
    return results.sort((a, b) => a.name.localeCompare(b.name));
  }
}

class KnotgraphBackingStore implements XRangerKvBackingStore {
  constructor(
    private readonly r2: XRangerR2Bucket,
    private readonly d1: XRangerD1Database
  ) {
    // Ensure index table exists
    this.d1
      .prepare(
        `
      CREATE TABLE IF NOT EXISTS knotgraph_kv_index (
        key TEXT PRIMARY KEY,
        kind TEXT,
        body_hash TEXT,
        metadata TEXT,
        expiration INTEGER
      )
    `
      )
      .run();
  }

  async get(key: string): Promise<KvEntryRecord | null> {
    const row = (await this.d1
      .prepare(
        `
      SELECT kind, body_hash, metadata, expiration FROM knotgraph_kv_index WHERE key = ?
    `
      )
      .bind(key)
      .first()) as {
      kind: 'text' | 'bytes';
      body_hash: string;
      metadata: string | null;
      expiration: number | null;
    } | null;

    if (!row) return null;

    if (row.expiration && row.expiration < Date.now() / 1000) {
      await this.delete(key);
      return null;
    }

    const obj = await this.r2.get(row.body_hash);
    if (!obj) return null;

    return {
      kind: row.kind,
      value: await obj.text(),
      metadata: row.metadata ? JSON.parse(row.metadata) : undefined,
      expiration: row.expiration ?? undefined,
    };
  }

  async put(key: string, record: KvEntryRecord): Promise<void> {
    const bodyHash = cacheFingerprint48HexSync(record.value);
    await this.r2.put(bodyHash, record.value);

    await this.d1
      .prepare(
        `
      INSERT OR REPLACE INTO knotgraph_kv_index (key, kind, body_hash, metadata, expiration)
      VALUES (?, ?, ?, ?, ?)
    `
      )
      .bind(
        key,
        record.kind,
        bodyHash,
        record.metadata ? JSON.stringify(record.metadata) : null,
        record.expiration ?? null
      )
      .run();
  }

  async delete(key: string): Promise<void> {
    await this.d1
      .prepare('DELETE FROM knotgraph_kv_index WHERE key = ?')
      .bind(key)
      .run();
  }

  async list(
    prefix?: string
  ): Promise<Array<{ name: string; metadata?: unknown; expiration?: number }>> {
    const query = prefix
      ? this.d1
          .prepare(
            'SELECT key as name, metadata, expiration FROM knotgraph_kv_index WHERE key LIKE ? ORDER BY key ASC'
          )
          .bind(`${prefix}%`)
      : this.d1.prepare(
          'SELECT key as name, metadata, expiration FROM knotgraph_kv_index ORDER BY key ASC'
        );

    const { results } = (await query.all()) as {
      results: Array<{
        name: string;
        metadata: string | null;
        expiration: number | null;
      }>;
    };
    const now = Date.now() / 1000;

    return results
      .filter((r) => !r.expiration || r.expiration >= now)
      .map((r) => ({
        name: r.name,
        metadata: r.metadata ? JSON.parse(r.metadata) : undefined,
        expiration: r.expiration ?? undefined,
      }));
  }
}

interface R2EntryRecord {
  readonly body: string;
}

function ensureDirectory(path: string): string {
  mkdirSync(path, { recursive: true });
  return path;
}

function resolvePersistLocation(
  config: XRangerResolvedConfig,
  persist: boolean | { path: string } | undefined
): PersistLocation {
  if (persist === false) {
    return { enabled: false };
  }
  if (
    persist &&
    typeof persist === 'object' &&
    typeof persist.path === 'string'
  ) {
    return {
      enabled: true,
      root: ensureDirectory(resolve(config.projectRoot, persist.path)),
    };
  }
  return {
    enabled: true,
    root: ensureDirectory(
      resolve(config.projectRoot, '.wrangler', 'state', 'v3')
    ),
  };
}

function loadJsonFile<T>(path: string, fallback: T): T {
  if (!existsSync(path)) {
    return fallback;
  }
  return JSON.parse(readFileSync(path, 'utf8')) as T;
}

function writeJsonFile(path: string, value: unknown): void {
  ensureDirectory(resolve(path, '..'));
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
}

function encodeBytes(data: Uint8Array): string {
  return Buffer.from(data).toString('base64');
}

function decodeBytes(value: string): Uint8Array {
  return new Uint8Array(Buffer.from(value, 'base64'));
}

function bodyToBytes(
  value: string | ArrayBuffer | ArrayBufferView
): Uint8Array {
  if (typeof value === 'string') {
    return new TextEncoder().encode(value);
  }
  if (value instanceof ArrayBuffer) {
    return new Uint8Array(value.slice(0));
  }
  const source = new Uint8Array(
    value.buffer,
    value.byteOffset,
    value.byteLength
  );
  const cloned = new Uint8Array(source.byteLength);
  cloned.set(source);
  return cloned;
}

function cloneArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  const cloned = bytes.slice(0);
  return cloned.buffer.slice(
    cloned.byteOffset,
    cloned.byteOffset + cloned.byteLength
  ) as ArrayBuffer;
}

function toSqlInputValue(value: unknown): SQLInputValue {
  if (
    value === null ||
    typeof value === 'number' ||
    typeof value === 'bigint' ||
    typeof value === 'string'
  ) {
    return value as SQLInputValue;
  }

  if (ArrayBuffer.isView(value)) {
    return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  }

  if (value instanceof ArrayBuffer) {
    return new Uint8Array(value);
  }

  throw new TypeError(
    `x-ranger D1 bindings only support null, number, bigint, string, ArrayBuffer, and ArrayBufferView values. Received ${typeof value}.`
  );
}

function toSqlInputValues(values: readonly unknown[]): SQLInputValue[] {
  return values.map((value) => toSqlInputValue(value));
}

function normalizeSqlRow<T>(row: T): T {
  if (typeof row !== 'object' || row === null || Array.isArray(row)) {
    return row;
  }
  return { ...(row as Record<string, unknown>) } as T;
}

class XRangerKvNamespace {
  constructor(private readonly bodies: XRangerKvBackingStore) {}

  async put(
    key: string,
    value: string | ArrayBuffer | ArrayBufferView,
    options?: {
      metadata?: unknown;
      expiration?: number;
      expirationTtl?: number;
    }
  ): Promise<void> {
    const bytes = bodyToBytes(value);
    let expiration = options?.expiration;
    if (options?.expirationTtl) {
      expiration = Math.floor(Date.now() / 1000) + options.expirationTtl;
    }

    const entry: KvEntryRecord =
      typeof value === 'string'
        ? { kind: 'text', value, metadata: options?.metadata, expiration }
        : {
            kind: 'bytes',
            value: encodeBytes(bytes),
            metadata: options?.metadata,
            expiration,
          };
    await this.bodies.put(key, entry);
  }

  async get<T = unknown>(
    key: string,
    type: 'text' | 'json' | 'arrayBuffer' = 'text'
  ): Promise<T | string | ArrayBuffer | null> {
    const entry = await this.bodies.get(key);
    if (!entry) {
      return null;
    }
    const text =
      entry.kind === 'text'
        ? entry.value
        : new TextDecoder().decode(decodeBytes(entry.value));
    if (type === 'json') {
      return JSON.parse(text) as T;
    }
    if (type === 'arrayBuffer') {
      const bytes =
        entry.kind === 'text'
          ? new TextEncoder().encode(entry.value)
          : decodeBytes(entry.value);
      return cloneArrayBuffer(bytes);
    }
    return text;
  }

  async getWithMetadata<T = unknown, M = unknown>(
    key: string,
    type: 'text' | 'json' | 'arrayBuffer' = 'text'
  ): Promise<{ value: T | string | ArrayBuffer | null; metadata: M | null }> {
    const entry = await this.bodies.get(key);
    if (!entry) {
      return { value: null, metadata: null };
    }
    const val = await this.get<T>(key, type);
    return { value: val, metadata: (entry.metadata as M) ?? null };
  }

  async delete(key: string): Promise<void> {
    await this.bodies.delete(key);
  }

  async list(options?: {
    prefix?: string;
    limit?: number;
    cursor?: string;
  }): Promise<{
    keys: Array<{ name: string; metadata?: unknown; expiration?: number }>;
    list_complete: boolean;
    cursor: string;
  }> {
    const all = await this.bodies.list(options?.prefix);
    const limit = options?.limit ?? 1000;
    const offset = options?.cursor ? parseInt(options.cursor, 10) : 0;
    const page = all.slice(offset, offset + limit);
    const nextOffset = offset + limit;
    const done = nextOffset >= all.length;

    return {
      keys: page,
      list_complete: done,
      cursor: done ? '' : String(nextOffset),
    };
  }
}

class XRangerR2ObjectBody {
  constructor(private readonly bytes: Uint8Array) {}

  async text(): Promise<string> {
    return new TextDecoder().decode(this.bytes);
  }

  async json<T = unknown>(): Promise<T> {
    return JSON.parse(await this.text()) as T;
  }

  async arrayBuffer(): Promise<ArrayBuffer> {
    const cloned = this.bytes.slice(0);
    return cloned.buffer.slice(
      cloned.byteOffset,
      cloned.byteOffset + cloned.byteLength
    ) as ArrayBuffer;
  }
}

class XRangerR2Bucket {
  private readonly objects = new Map<string, R2EntryRecord>();
  private readonly filePath?: string;

  constructor(filePath: string | undefined) {
    this.filePath = filePath;
    if (filePath) {
      const data = loadJsonFile<Record<string, R2EntryRecord>>(filePath, {});
      for (const [key, value] of Object.entries(data)) {
        this.objects.set(key, value);
      }
    }
  }

  private persist(): void {
    if (!this.filePath) {
      return;
    }
    writeJsonFile(this.filePath, Object.fromEntries(this.objects.entries()));
  }

  async put(
    key: string,
    value: string | ArrayBuffer | ArrayBufferView
  ): Promise<void> {
    this.objects.set(key, {
      body: encodeBytes(bodyToBytes(value)),
    });
    this.persist();
  }

  async get(key: string): Promise<XRangerR2ObjectBody | null> {
    const record = this.objects.get(key);
    return record ? new XRangerR2ObjectBody(decodeBytes(record.body)) : null;
  }

  async head(key: string): Promise<{ key: string; size: number } | null> {
    const record = this.objects.get(key);
    if (!record) {
      return null;
    }
    return {
      key,
      size: decodeBytes(record.body).byteLength,
    };
  }

  async delete(key: string): Promise<void> {
    this.objects.delete(key);
    this.persist();
  }
}

class XRangerD1PreparedStatement {
  constructor(
    private readonly database: SqliteDatabase,
    private readonly sql: string,
    private readonly values: readonly unknown[] = []
  ) {}

  bind(...values: unknown[]): XRangerD1PreparedStatement {
    return new XRangerD1PreparedStatement(this.database, this.sql, values);
  }

  async first<T = Record<string, unknown>>(): Promise<T | null> {
    const statement = this.database.prepare(this.sql);
    const row = statement.get(...toSqlInputValues(this.values)) as
      | T
      | undefined;
    return row === undefined ? null : normalizeSqlRow(row);
  }

  async all<T = Record<string, unknown>>(): Promise<{ results: T[] }> {
    const statement = this.database.prepare(this.sql);
    return {
      results: (statement.all(...toSqlInputValues(this.values)) as T[]).map(
        (row) => normalizeSqlRow(row)
      ),
    };
  }

  async run(): Promise<{
    success: true;
    meta: { changes: number; last_row_id: number };
  }> {
    const statement = this.database.prepare(this.sql);
    const result = statement.run(...toSqlInputValues(this.values));
    return {
      success: true,
      meta: {
        changes: Number(result.changes),
        last_row_id: Number(result.lastInsertRowid),
      },
    };
  }
}

class XRangerD1Database {
  constructor(private readonly database: SqliteDatabase) {}

  prepare(sql: string): XRangerD1PreparedStatement {
    return new XRangerD1PreparedStatement(this.database, sql);
  }

  async batch(
    statements: XRangerD1PreparedStatement[]
  ): Promise<
    Array<{ success: true; meta: { changes: number; last_row_id: number } }>
  > {
    const results = [];
    for (const statement of statements) {
      results.push(await statement.run());
    }
    return results;
  }

  close(): void {
    this.database.close();
  }
}

class XRangerMtlsCertificateBinding {
  readonly certificateId?: string;

  constructor(
    private readonly bindingName: string,
    certificateId: string | undefined
  ) {
    this.certificateId = certificateId;
  }

  async fetch(
    _input: RequestInfo | URL,
    _init?: RequestInit
  ): Promise<Response> {
    throw new Error(
      `x-ranger does not emulate Cloudflare mTLS certificate bindings locally for '${this.bindingName}'. Use upstream Wrangler remote binding connections or deploy to Cloudflare for environment.${this.bindingName}.fetch(...).`
    );
  }
}

class XRangerServiceBinding {
  constructor(
    private readonly serviceName: string,
    private readonly registryDir: string
  ) {}

  async fetch(
    input?: RequestInfo | URL,
    init?: RequestInit
  ): Promise<Response> {
    const target = findXRangerSessionByWorkerName(
      this.registryDir,
      this.serviceName
    );
    if (!target) {
      throw new Error(
        `x-ranger could not resolve service binding '${this.serviceName}'. Start that worker first.`
      );
    }

    if (input === undefined) {
      return fetch(target.origin, init);
    }

    const request = input instanceof Request ? input : new Request(input, init);
    const sourceUrl = new URL(request.url, target.origin);
    const targetUrl = new URL(
      `${sourceUrl.pathname}${sourceUrl.search}${sourceUrl.hash}`,
      target.origin
    );
    return fetch(new Request(targetUrl, request));
  }
}

class XRangerDurableObjectStorage {
  private readonly store = new Map<string, unknown>();
  private readonly filePath?: string;

  constructor(filePath: string | undefined) {
    this.filePath = filePath;
    if (filePath) {
      const data = loadJsonFile<Record<string, unknown>>(filePath, {});
      for (const [key, value] of Object.entries(data)) {
        this.store.set(key, value);
      }
    }
  }

  private persist(): void {
    if (!this.filePath) {
      return;
    }
    writeJsonFile(this.filePath, Object.fromEntries(this.store.entries()));
  }

  async get<T = unknown>(key: string): Promise<T | undefined> {
    return this.store.get(key) as T | undefined;
  }

  async put(key: string, value: unknown): Promise<void> {
    this.store.set(key, value);
    this.persist();
  }

  async delete(key: string): Promise<boolean> {
    const existed = this.store.delete(key);
    this.persist();
    return existed;
  }

  async list<T = unknown>(): Promise<Map<string, T>> {
    return new Map(this.store.entries()) as Map<string, T>;
  }
}

class XRangerDurableObjectState {
  readonly storage: XRangerDurableObjectStorage;
  private readonly tasks: Promise<unknown>[] = [];
  private alarm: number | null = null;

  constructor(storagePath: string | undefined) {
    this.storage = new XRangerDurableObjectStorage(storagePath);
  }

  waitUntil(promise: Promise<unknown>): void {
    this.tasks.push(promise);
  }

  async drain(): Promise<void> {
    await Promise.allSettled(this.tasks);
  }

  async setAlarm(epochMs: number): Promise<void> {
    this.alarm = epochMs;
  }

  async getAlarm(): Promise<number | null> {
    return this.alarm;
  }
}

class XRangerDurableObjectId {
  constructor(private readonly value: string) {}

  toString(): string {
    return this.value;
  }
}

class XRangerDurableObjectNamespace {
  private readonly instances = new Map<string, unknown>();

  constructor(
    private readonly binding: XRangerBindingRecord,
    private readonly objectClass: new (
      state: XRangerDurableObjectState,
      env: Record<string, unknown>
    ) => unknown,
    private readonly env: Record<string, unknown>,
    private readonly persistRoot: string | undefined
  ) {}

  idFromName(name: string): XRangerDurableObjectId {
    const hash = createHash('sha1').update(name).digest('hex');
    return new XRangerDurableObjectId(hash);
  }

  get(id: XRangerDurableObjectId): {
    fetch(request: Request): Promise<Response>;
  } {
    const idString = id.toString();
    return {
      fetch: async (request: Request) => {
        const instance = await this.getOrCreateInstance(idString);
        const candidate = instance as {
          fetch?: (request: Request) => Response | Promise<Response>;
        };
        if (typeof candidate.fetch !== 'function') {
          throw new Error(
            `Durable Object '${
              this.binding.className ?? this.binding.binding
            }' does not expose fetch().`
          );
        }
        const response = await candidate.fetch(request);
        return response instanceof Response
          ? response
          : new Response(String(response));
      },
    };
  }

  private async getOrCreateInstance(id: string): Promise<unknown> {
    const existing = this.instances.get(id);
    if (existing) {
      return existing;
    }

    const storagePath = this.persistRoot
      ? resolve(
          this.persistRoot,
          'durable-objects',
          this.binding.binding,
          `${id}.json`
        )
      : undefined;
    const state = new XRangerDurableObjectState(storagePath);
    const instance = new this.objectClass(state, this.env);
    this.instances.set(id, instance);
    return instance;
  }
}

type PlatformBindingsResult<Env> = XRangerPlatformProxy<Env> & {
  readonly bindingMap: Map<string, XRangerBindingRecord>;
};

function installDurableObjectBase(): void {
  const runtime = globalThis as Record<string, unknown>;
  if (typeof runtime.DurableObject === 'function') {
    return;
  }
  runtime.DurableObject = class DurableObject {
    readonly ctx: unknown;
    readonly env: unknown;

    constructor(state: unknown, env: unknown) {
      this.ctx = state;
      this.env = env;
    }
  };
}

function localCfStub(): Readonly<Record<string, unknown>> {
  return {
    colo: 'LOCAL',
    country: 'US',
    city: 'San Francisco',
    region: 'California',
    timezone: 'America/Los_Angeles',
    asOrganization: 'x-ranger local development',
    httpProtocol: 'HTTP/1.1',
  };
}

async function applyBinding(
  env: Record<string, unknown>,
  binding: XRangerBindingRecord,
  config: XRangerResolvedConfig,
  persistLocation: PersistLocation,
  registryDir: string,
  remoteBindingsEnabled: boolean,
  currentWorkerExports?: Record<string, unknown>
): Promise<(() => void) | undefined> {
  if (binding.type === 'kv') {
    if (persistLocation.enabled && persistLocation.root) {
      const lowerId = (binding.id ?? '').toLowerCase();
      const lowerBinding = binding.binding.toLowerCase();

      const isKnotgraph =
        lowerId.includes('knotgraph') || lowerBinding.includes('knotgraph');
      const isVault =
        lowerId.includes('vault') || lowerBinding.includes('vault');

      if (isKnotgraph) {
        const base = ensureDirectory(
          resolve(persistLocation.root, 'kv', binding.binding)
        );
        const r2 = new XRangerR2Bucket(resolve(base, 'bodies.json'));
        const d1 = new XRangerD1Database(
          new DatabaseSync(resolve(base, 'index.sqlite'))
        );
        env[binding.binding] = new XRangerKvNamespace(
          new KnotgraphBackingStore(r2, d1)
        );
      } else if (isVault) {
        const kvRoot = resolve(persistLocation.root, 'kv', binding.binding);
        env[binding.binding] = new XRangerKvNamespace(
          new VaultBackingStore(kvRoot)
        );
      } else {
        const filePath = resolve(
          persistLocation.root,
          'kv',
          `${binding.binding}.json`
        );
        env[binding.binding] = new XRangerKvNamespace(
          new JSONBackingStore(filePath)
        );
      }
    } else {
      env[binding.binding] = new XRangerKvNamespace(new JSONBackingStore());
    }
    return undefined;
  }

  if (binding.type === 'r2') {
    const filePath =
      persistLocation.enabled && persistLocation.root
        ? resolve(persistLocation.root, 'r2', `${binding.binding}.json`)
        : undefined;
    env[binding.binding] = new XRangerR2Bucket(filePath);
    return undefined;
  }

  if (binding.type === 'd1') {
    const filePath =
      persistLocation.enabled && persistLocation.root
        ? resolve(persistLocation.root, 'd1', `${binding.binding}.sqlite`)
        : ':memory:';
    const database = new XRangerD1Database(new DatabaseSync(filePath));
    env[binding.binding] = database;
    return () => database.close();
  }

  if (binding.type === 'mtls-certificate') {
    env[binding.binding] = new XRangerMtlsCertificateBinding(
      binding.binding,
      binding.certificateId
    );
    return undefined;
  }

  if (binding.type === 'service') {
    env[binding.binding] = remoteBindingsEnabled
      ? new XRangerServiceBinding(
          binding.service ?? binding.binding,
          registryDir
        )
      : {
          async fetch(): Promise<Response> {
            throw new Error(
              `Remote bindings are disabled for service binding '${binding.binding}'.`
            );
          },
        };
    return undefined;
  }

  installDurableObjectBase();
  const className = binding.className;
  const objectClass =
    className && currentWorkerExports
      ? (currentWorkerExports[className] as
          | (new (
              state: XRangerDurableObjectState,
              env: Record<string, unknown>
            ) => unknown)
          | undefined)
      : undefined;

  if (!objectClass) {
    env[binding.binding] = {
      idFromName(name: string) {
        return new XRangerDurableObjectId(
          createHash('sha1').update(name).digest('hex')
        );
      },
      get() {
        return {
          async fetch(): Promise<Response> {
            throw new Error(
              `x-ranger could not materialize Durable Object binding '${binding.binding}'. Start the worker through x-ranger so the exported class is available locally.`
            );
          },
        };
      },
    };
    return undefined;
  }

  env[binding.binding] = new XRangerDurableObjectNamespace(
    binding,
    objectClass,
    env,
    persistLocation.root
  );
  return undefined;
}

export async function createXRangerPlatformProxy<Env = Record<string, unknown>>(
  options: XRangerPlatformProxyOptions & {
    readonly currentWorkerExports?: Record<string, unknown>;
  } = {}
): Promise<PlatformBindingsResult<Env>> {
  const config = resolveXRangerConfig({
    config: options.configPath ?? options.config,
    env: options.environment ?? options.env,
    cwd: options.cwd,
  });
  const env = {
    ...config.vars,
    ...(await readProjectSecrets(
      config.projectRoot,
      config.name,
      options.environment ?? options.env
    )),
  } as Record<string, unknown>;
  const persistLocation = resolvePersistLocation(config, options.persist);
  const registryDir = defaultXRangerRegistryDir(config);
  const cleaners: Array<() => void> = [];

  for (const binding of config.bindings) {
    const cleaner = await applyBinding(
      env,
      binding,
      config,
      persistLocation,
      registryDir,
      options.remoteBindings !== false,
      options.currentWorkerExports
    );
    if (cleaner) {
      cleaners.push(cleaner);
    }
  }

  const ctx = new XRangerExecutionContext();
  const cache = new XRangerNoopCache();
  return {
    env: env as Env,
    cf: localCfStub(),
    ctx,
    caches: {
      default: cache,
      async open(): Promise<XRangerNoopCache> {
        return cache;
      },
    },
    bindingMap: new Map(
      config.bindings.map((binding: XRangerBindingRecord) => [binding.binding, binding])
    ),
    async dispose(): Promise<void> {
      await ctx.drain();
      for (const cleaner of cleaners) {
        cleaner();
      }
    },
  };
}

export async function getPlatformProxy<Env = Record<string, unknown>>(
  options: XRangerPlatformProxyOptions = {}
): Promise<XRangerPlatformProxy<Env>> {
  return createXRangerPlatformProxy<Env>(options);
}

export { installDurableObjectBase };
