import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { createRequire } from 'node:module';
import {
  type ExportFormat,
  type HistoryEntry,
  type HistorySearchRequest,
} from './types.js';

const DEFAULT_HISTORY_PATH = join(homedir(), '.gnot-repl', 'history.sqlite3');

interface SqliteStatement {
  run(...values: unknown[]): unknown;
  all(...values: unknown[]): unknown[];
}

interface SqliteDatabase {
  exec(sql: string): void;
  prepare(sql: string): SqliteStatement;
  close(): void;
}

type DatabaseSyncCtor = new (path: string) => SqliteDatabase;

function resolveDatabaseSync(): DatabaseSyncCtor {
  const require = createRequire(import.meta.url);
  const moduleShape = require('node:sqlite') as {
    DatabaseSync?: DatabaseSyncCtor;
  };
  if (!moduleShape.DatabaseSync) {
    throw new Error('node:sqlite DatabaseSync is unavailable');
  }
  return moduleShape.DatabaseSync;
}

export interface HistoryStore {
  append(
    sessionId: string,
    direction: 'input' | 'output' | 'error',
    text: string,
    at: number
  ): void;
  recent(sessionId: string, limit: number): HistoryEntry[];
  search(request: HistorySearchRequest): HistoryEntry[];
  export(sessionId: string, format: ExportFormat, limit: number): string;
  close(): void;
}

function csvEscape(value: string): string {
  if (value.includes(',') || value.includes('"') || value.includes('\n')) {
    return `"${value.replaceAll('"', '""')}"`;
  }
  return value;
}

export class SqliteHistoryStore implements HistoryStore {
  private readonly db: SqliteDatabase;

  constructor(path: string = DEFAULT_HISTORY_PATH) {
    const DatabaseSync = resolveDatabaseSync();
    mkdirSync(dirname(path), { recursive: true });
    this.db = new DatabaseSync(path);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id TEXT NOT NULL,
        at INTEGER NOT NULL,
        direction TEXT NOT NULL,
        text TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_history_session_at ON history (session_id, at DESC);
    `);
  }

  append(
    sessionId: string,
    direction: 'input' | 'output' | 'error',
    text: string,
    at: number
  ): void {
    const statement = this.db.prepare(
      'INSERT INTO history (session_id, at, direction, text) VALUES (?, ?, ?, ?)'
    );
    statement.run(sessionId, at, direction, text);
  }

  recent(sessionId: string, limit: number): HistoryEntry[] {
    const statement = this.db.prepare(
      'SELECT id, session_id, at, direction, text FROM history WHERE session_id = ? ORDER BY at DESC LIMIT ?'
    );
    const rows = statement.all(sessionId, limit) as {
      id: number;
      session_id: string;
      at: number;
      direction: 'input' | 'output' | 'error';
      text: string;
    }[];
    return rows.map((row) => ({
      id: row.id,
      sessionId: row.session_id,
      at: row.at,
      direction: row.direction,
      text: row.text,
    }));
  }

  search(request: HistorySearchRequest): HistoryEntry[] {
    const safeLimit = request.limit && request.limit > 0 ? request.limit : 50;
    const query = `%${request.query}%`;

    let rows: {
      id: number;
      session_id: string;
      at: number;
      direction: 'input' | 'output' | 'error';
      text: string;
    }[] = [];

    if (request.sessionId) {
      const statement = this.db.prepare(
        `SELECT id, session_id, at, direction, text
         FROM history
         WHERE session_id = ? AND text LIKE ?
         ORDER BY at DESC
         LIMIT ?`
      );
      rows = statement.all(request.sessionId, query, safeLimit) as typeof rows;
    } else {
      const statement = this.db.prepare(
        `SELECT id, session_id, at, direction, text
         FROM history
         WHERE text LIKE ?
         ORDER BY at DESC
         LIMIT ?`
      );
      rows = statement.all(query, safeLimit) as typeof rows;
    }

    return rows.map((row) => ({
      id: row.id,
      sessionId: row.session_id,
      at: row.at,
      direction: row.direction,
      text: row.text,
    }));
  }

  export(sessionId: string, format: ExportFormat, limit: number): string {
    const rows = this.recent(sessionId, limit).reverse();
    if (format === 'json') {
      return JSON.stringify(rows, null, 2);
    }
    if (format === 'csv') {
      const header = 'id,sessionId,at,direction,text';
      const body = rows
        .map((row) =>
          [
            String(row.id),
            csvEscape(row.sessionId),
            String(row.at),
            row.direction,
            csvEscape(row.text),
          ].join(',')
        )
        .join('\n');
      return `${header}\n${body}`;
    }
    if (format === 'tsv') {
      const header = 'id\tsessionId\tat\tdirection\ttext';
      const body = rows
        .map((row) =>
          [
            String(row.id),
            row.sessionId,
            String(row.at),
            row.direction,
            row.text.replaceAll('\t', '    '),
          ].join('\t')
        )
        .join('\n');
      return `${header}\n${body}`;
    }

    const lines: string[] = [
      '| id | session | at | direction | text |',
      '| --- | --- | --- | --- | --- |',
    ];
    for (const row of rows) {
      lines.push(
        `| ${row.id} | ${row.sessionId} | ${row.at} | ${
          row.direction
        } | ${row.text.replaceAll('|', '\\|')} |`
      );
    }
    return lines.join('\n');
  }

  close(): void {
    this.db.close();
  }
}

export class InMemoryHistoryStore implements HistoryStore {
  private readonly rows: HistoryEntry[] = [];
  private nextId = 1;

  append(
    sessionId: string,
    direction: 'input' | 'output' | 'error',
    text: string,
    at: number
  ): void {
    this.rows.push({
      id: this.nextId++,
      sessionId,
      at,
      direction,
      text,
    });
  }

  recent(sessionId: string, limit: number): HistoryEntry[] {
    return this.rows.filter((row) => row.sessionId === sessionId).slice(-limit);
  }

  search(request: HistorySearchRequest): HistoryEntry[] {
    const limit = request.limit && request.limit > 0 ? request.limit : 50;
    const query = request.query.toLowerCase();
    return this.rows
      .filter((row) => {
        if (request.sessionId && row.sessionId !== request.sessionId) {
          return false;
        }
        return row.text.toLowerCase().includes(query);
      })
      .slice(-limit);
  }

  export(sessionId: string, format: ExportFormat, limit: number): string {
    const rows = this.recent(sessionId, limit);
    if (format === 'json') {
      return JSON.stringify(rows, null, 2);
    }
    if (format === 'csv') {
      return rows
        .map((row) =>
          [
            row.id,
            row.sessionId,
            row.at,
            row.direction,
            csvEscape(row.text),
          ].join(',')
        )
        .join('\n');
    }
    if (format === 'tsv') {
      return rows
        .map((row) =>
          [row.id, row.sessionId, row.at, row.direction, row.text].join('\t')
        )
        .join('\n');
    }
    return rows
      .map(
        (row) =>
          `- [${row.id}] ${row.sessionId} ${row.direction} ${row.at}: ${row.text}`
      )
      .join('\n');
  }

  close(): void {}
}
