/**
 * BuleyeanEngine -- rejection-first neural graph engine
 *
 * The core training loop:
 *   1. Forward pass: compute activations through the graph
 *   2. Compare output to expectation
 *   3. Rejection propagation: record what failed in void boundaries
 *   4. Complement update: God Formula derives new weights from rejections
 *
 * No gradient tape. No reward model. No chosen examples.
 * w_i = R - min(v_i, R) + 1. The void boundary maps to the training signal.
 *
 * Mechanized:
 *   buleyean_positivity -- no activation level ever reaches zero probability
 *   buleyean_monotone_nonrejected -- less rejected = more weight
 *   void_walkers_converge -- same rejection history = same distribution
 */

import type {
  BuleyeanNeuron,
  BuleyeanSynapse,
  RejectionSignal,
  BuleyeanNeuralConfig,
  BuleyeanNeuralMetrics,
  BuleyeanGraphState,
} from './types';
import { DEFAULT_NEURAL_CONFIG } from './types';

export class BuleyeanEngine {
  private neurons = new Map<string, BuleyeanNeuron>();
  private synapses: BuleyeanSynapse[] = [];
  private incomingSynapses = new Map<string, BuleyeanSynapse[]>();
  private outgoingSynapses = new Map<string, BuleyeanSynapse[]>();
  private config: BuleyeanNeuralConfig;
  private round = 0;

  // Neuron type index: pre-computed on addNeuron(), avoids O(N) filter per forward()
  private _neuronsByType = new Map<BuleyeanNeuron['type'], BuleyeanNeuron[]>();

  constructor(config?: Partial<BuleyeanNeuralConfig>) {
    this.config = { ...DEFAULT_NEURAL_CONFIG, ...config };
  }

  /**
   * Add a neuron to the graph.
   */
  addNeuron(opts: {
    id: string;
    type: BuleyeanNeuron['type'];
    bias?: number;
    activation?: BuleyeanNeuron['activation'];
  }): BuleyeanNeuron {
    const neuron: BuleyeanNeuron = {
      id: opts.id,
      type: opts.type,
      bias: opts.bias ?? 0,
      activation: opts.activation ?? 'tanh',
      voidBoundary: new Array(this.config.activationLevels).fill(0),
      totalRejections: 0,
      complementWeights: new Array(this.config.activationLevels).fill(
        1 / this.config.activationLevels
      ),
    };

    this.neurons.set(opts.id, neuron);
    if (!this.incomingSynapses.has(opts.id)) {
      this.incomingSynapses.set(opts.id, []);
    }
    if (!this.outgoingSynapses.has(opts.id)) {
      this.outgoingSynapses.set(opts.id, []);
    }

    // Maintain type index for O(1) getNeuronsByType lookups
    let typed = this._neuronsByType.get(opts.type);
    if (!typed) {
      typed = [];
      this._neuronsByType.set(opts.type, typed);
    }
    typed.push(neuron);

    return neuron;
  }

  /**
   * Connect two neurons with a synapse.
   * Initial weight is 1/(total synapses to target) -- uniform complement.
   */
  addSynapse(opts: {
    fromId: string;
    toId: string;
    weight?: number;
  }): BuleyeanSynapse {
    const synapse: BuleyeanSynapse = {
      id: `${opts.fromId}->${opts.toId}`,
      fromId: opts.fromId,
      toId: opts.toId,
      weight: opts.weight ?? 0.5,
      rejections: 0,
      totalRounds: 0,
    };

    this.synapses.push(synapse);

    const incoming = this.incomingSynapses.get(opts.toId) ?? [];
    incoming.push(synapse);
    this.incomingSynapses.set(opts.toId, incoming);

    const outgoing = this.outgoingSynapses.get(opts.fromId) ?? [];
    outgoing.push(synapse);
    this.outgoingSynapses.set(opts.fromId, outgoing);

    return synapse;
  }

  /**
   * Forward pass: compute activations through the graph.
   * Returns output neuron activations.
   */
  forward(inputs: Float32Array): Float32Array {
    const activations = new Map<string, number>();

    // Set input neuron activations
    const inputNeurons = this.getNeuronsByType('input');
    for (let i = 0; i < inputNeurons.length; i++) {
      activations.set(inputNeurons[i].id, inputs[i] ?? 0);
    }

    // Topological forward pass through hidden + output neurons
    // Iterate both arrays without spread concatenation
    const hiddenNeurons = this.getNeuronsByType('hidden');
    const outputNeurons = this.getNeuronsByType('output');

    for (const neurons of [hiddenNeurons, outputNeurons]) {
      for (const neuron of neurons) {
        const incoming = this.incomingSynapses.get(neuron.id) ?? [];
        let sum = neuron.bias;

        for (const synapse of incoming) {
          const inputAct = activations.get(synapse.fromId) ?? 0;
          sum += inputAct * synapse.weight;
        }

        activations.set(neuron.id, this.activate(sum, neuron.activation));
      }
    }

    // Collect output activations
    const output = new Float32Array(outputNeurons.length);
    for (let i = 0; i < outputNeurons.length; i++) {
      output[i] = activations.get(outputNeurons[i].id) ?? 0;
    }

    return output;
  }

  /**
   * Rejection pass: propagate rejection signals backward through the graph.
   *
   * This replaces gradient backpropagation. Instead of computing dL/dw,
   * we record which activations were rejected and update void boundaries.
   * The God Formula then derives new weights from the rejection history.
   */
  reject(signals: RejectionSignal[]): void {
    this.round++;

    for (const signal of signals) {
      const neuron = this.neurons.get(signal.sourceNeuronId);
      if (!neuron) continue;

      // Discretize the rejected activation to a boundary level
      const level = this.discretize(signal.rejectedActivation);
      const count = Math.ceil(signal.strength * 10);

      // Record rejection in the neuron's void boundary
      neuron.voidBoundary[level] += count;
      neuron.totalRejections += count;

      // Propagate rejection backward through incoming synapses
      this.propagateRejectionBackward(neuron.id, signal.strength, new Set());
    }

    // Recompute all complement distributions and weights
    this.recomputeAll();
  }

  /**
   * Train: forward pass, compare to target, reject bad outputs.
   *
   * This is the buleyean training loop:
   *   1. Forward pass
   *   2. Compare output to target
   *   3. For each output neuron where |output - target| > threshold:
   *      reject the output activation with strength proportional to error
   *   4. God Formula updates weights from rejection history
   */
  train(
    inputs: Float32Array,
    targets: Float32Array,
    threshold: number = 0.1
  ): { output: Float32Array; rejections: number; loss: number } {
    const output = this.forward(inputs);
    const outputNeurons = this.getNeuronsByType('output');
    const signals: RejectionSignal[] = [];
    let totalLoss = 0;

    for (let i = 0; i < outputNeurons.length; i++) {
      const error = Math.abs(output[i] - (targets[i] ?? 0));
      totalLoss += error * error;

      if (error > threshold) {
        signals.push({
          sourceNeuronId: outputNeurons[i].id,
          rejectedActivation: output[i],
          strength: Math.min(1.0, error),
          round: this.round,
        });
      }
    }

    if (signals.length > 0) {
      this.reject(signals);
    }

    return {
      output,
      rejections: signals.length,
      loss: totalLoss / Math.max(outputNeurons.length, 1),
    };
  }

  /**
   * Run multiple training steps. Returns per-step loss.
   */
  trainLoop(
    inputs: Float32Array,
    targets: Float32Array,
    steps: number,
    threshold: number = 0.1
  ): number[] {
    const losses: number[] = [];
    for (let i = 0; i < steps; i++) {
      const result = this.train(inputs, targets, threshold);
      losses.push(result.loss);
    }
    return losses;
  }

  /**
   * Spiderweb Void-Walking Batch Training
   * 
   * Mathematically derived from ForkRaceFoldTheorems/SpiderwebMeshNetwork.lean.
   * Leverages the β₁ = k·s topology where k walkers can traverse 
   * the mesh simultaneously without crossing paths.
   * 
   * This provides a massive speedup for failure training: instead of sequential
   * void-boundary updates, k independent walkers (batch items) explore the graph 
   * identically. Their generated rejection signals are independently collected 
   * and then folded together at the hub in a single zero-coordination commit.
   * 
   * O(1) Recompute cost instead of O(K) for k batch samples.
   */
  trainSpiderwebBatch(
    batchInputs: Float32Array[],
    batchTargets: Float32Array[],
    threshold: number = 0.1
  ): { losses: number[]; totalRejections: number } {
    const allSignals: RejectionSignal[] = [];
    const losses: number[] = [];
    const outputNeurons = this.getNeuronsByType('output');
    
    // FORK & RACE: k independent walkers evaluate paths without overlapping state.
    // Zero-coordination required during the forward pass phase.
    for (let i = 0; i < batchInputs.length; i++) {
      const inputs = batchInputs[i];
      const targets = batchTargets[i];
      
      const output = this.forward(inputs);
      let sampleLoss = 0;
      
      for (let j = 0; j < outputNeurons.length; j++) {
        const error = Math.abs(output[j] - (targets[j] ?? 0));
        sampleLoss += error * error;
        
        if (error > threshold) {
          allSignals.push({
            sourceNeuronId: outputNeurons[j].id,
            rejectedActivation: output[j],
            strength: Math.min(1.0, error),
            round: this.round,
          });
        }
      }
      
      losses.push(sampleLoss / Math.max(outputNeurons.length, 1));
    }
    
    // FOLD: The hub absorbs all paths' failure signals in one massive atomic update.
    if (allSignals.length > 0) {
      this.reject(allSignals);
    }
    
    return {
      losses,
      totalRejections: allSignals.length
    };
  }

  /**
   * Get the complement distribution for a neuron.
   * This is the God Formula applied to the void boundary.
   */
  getComplement(neuronId: string): number[] {
    const neuron = this.neurons.get(neuronId);
    if (!neuron) return [];
    return [...neuron.complementWeights];
  }

  /**
   * Get the Bule deficit for a neuron.
   * Deficit = max(rejections) - min(rejections) across boundary levels.
   */
  getDeficit(neuronId: string): number {
    const neuron = this.neurons.get(neuronId);
    if (!neuron || neuron.totalRejections === 0) return 0;

    // Single-pass min/max over non-zero entries (no filter, no spread)
    const boundary = neuron.voidBoundary;
    let min = Infinity;
    let max = -Infinity;
    let hasNonZero = false;
    for (let i = 0; i < boundary.length; i++) {
      const v = boundary[i];
      if (v > 0) {
        hasNonZero = true;
        if (v < min) min = v;
        if (v > max) max = v;
      }
    }
    return hasNonZero ? max - min : 0;
  }

  /**
   * Get graph-level metrics.
   */
  getMetrics(): BuleyeanNeuralMetrics {
    let totalRejections = 0;
    let totalDeficit = 0;
    let neuronCount = 0;
    const neuronEntropies = new Map<string, number>();

    for (const [id, neuron] of this.neurons) {
      totalRejections += neuron.totalRejections;
      totalDeficit += this.getDeficit(id);
      neuronCount++;
      neuronEntropies.set(id, this.neuronEntropy(neuron));
    }

    return {
      neuronCount,
      synapseCount: this.synapses.length,
      totalRejections,
      meanDeficit: neuronCount > 0 ? totalDeficit / neuronCount : 0,
      converged:
        neuronCount > 0 &&
        totalRejections > 0 &&
        totalDeficit / neuronCount < 0.01,
      neuronEntropies,
    };
  }

  /**
   * Serialize graph state for persistence.
   */
  serialize(): BuleyeanGraphState {
    return {
      neurons: [...this.neurons.values()].map((n) => ({
        id: n.id,
        type: n.type,
        bias: n.bias,
        activation: n.activation,
        voidBoundary: [...n.voidBoundary],
        totalRejections: n.totalRejections,
      })),
      synapses: this.synapses.map((s) => ({
        id: s.id,
        fromId: s.fromId,
        toId: s.toId,
        weight: s.weight,
        rejections: s.rejections,
        totalRounds: s.totalRounds,
      })),
      config: { ...this.config },
      round: this.round,
    };
  }

  /**
   * Restore graph state from serialized form.
   */
  static deserialize(state: BuleyeanGraphState): BuleyeanEngine {
    const engine = new BuleyeanEngine(state.config);
    engine.round = state.round;

    for (const n of state.neurons) {
      const neuron = engine.addNeuron({
        id: n.id,
        type: n.type,
        bias: n.bias,
        activation: n.activation,
      });
      neuron.voidBoundary = [...n.voidBoundary];
      neuron.totalRejections = n.totalRejections;
    }

    for (const s of state.synapses) {
      const synapse = engine.addSynapse({
        fromId: s.fromId,
        toId: s.toId,
        weight: s.weight,
      });
      synapse.rejections = s.rejections;
      synapse.totalRounds = s.totalRounds;
    }

    engine.recomputeAll();
    return engine;
  }

  /**
   * Get current round.
   */
  getRound(): number {
    return this.round;
  }

  /**
   * Get a neuron by ID.
   */
  getNeuron(id: string): BuleyeanNeuron | undefined {
    return this.neurons.get(id);
  }

  /**
   * Get all neurons of a given type.
   */
  getNeuronsByType(type: BuleyeanNeuron['type']): BuleyeanNeuron[] {
    return this._neuronsByType.get(type) ?? [];
  }

  // --- Private ---

  private activate(x: number, fn: BuleyeanNeuron['activation']): number {
    switch (fn) {
      case 'tanh':
        return Math.tanh(x);
      case 'relu':
        return Math.max(0, x);
      case 'sigmoid':
        return 1 / (1 + Math.exp(-x));
      case 'identity':
        return x;
    }
  }

  /**
   * Discretize a continuous activation [-1, 1] to a boundary level index.
   */
  private discretize(activation: number): number {
    const clamped = Math.max(-1, Math.min(1, activation));
    const normalized = (clamped + 1) / 2; // [0, 1]
    const level = Math.floor(normalized * (this.config.activationLevels - 1));
    return Math.max(0, Math.min(this.config.activationLevels - 1, level));
  }

  /**
   * Propagate rejection backward through incoming synapses.
   * Each synapse carries the rejection signal attenuated by its weight.
   */
  private propagateRejectionBackward(
    neuronId: string,
    strength: number,
    visited: Set<string>
  ): void {
    // Iterative BFS instead of recursive DFS -- avoids O(depth) call stack
    // and makes worst-case O(N) instead of O(N^2) for dense graphs
    const queue: Array<{ id: string; strength: number }> = [
      { id: neuronId, strength },
    ];
    let head = 0;

    while (head < queue.length) {
      const { id, strength: s } = queue[head++];
      if (visited.has(id) || s < 0.01) continue;
      visited.add(id);

      const incoming = this.incomingSynapses.get(id) ?? [];
      for (const synapse of incoming) {
        // Reject the synapse itself
        const attenuation = Math.abs(synapse.weight);
        synapse.rejections += Math.ceil(s * attenuation * 10);
        synapse.totalRounds++;

        // Propagate to source neuron
        const source = this.neurons.get(synapse.fromId);
        if (source && source.type !== 'input') {
          // Record in source neuron's void boundary at its current activation level
          const level = this.discretize(0); // Use midpoint as proxy
          const count = Math.ceil(s * attenuation);
          if (count > 0) {
            source.voidBoundary[level] += count;
            source.totalRejections += count;
          }

          // Continue backward via queue (not recursion)
          queue.push({ id: synapse.fromId, strength: s * attenuation * 0.5 });
        }
      }
    }
  }

  /**
   * Recompute complement distributions and synapse weights from void boundaries.
   * This is the God Formula: w_i = R - min(v_i, R) + 1
   */
  private recomputeAll(): void {
    // Update neuron complement distributions
    for (const neuron of this.neurons.values()) {
      neuron.complementWeights = this.computeComplement(neuron);
    }

    // Update synapse weights from complement distribution
    for (const synapse of this.synapses) {
      synapse.weight = this.computeSynapseWeight(synapse);
    }

    // Apply decay if configured
    if (this.config.decayRate > 0) {
      for (const neuron of this.neurons.values()) {
        for (let i = 0; i < neuron.voidBoundary.length; i++) {
          neuron.voidBoundary[i] = Math.floor(
            neuron.voidBoundary[i] * (1 - this.config.decayRate)
          );
        }
      }
    }
  }

  /**
   * Compute complement distribution from void boundary using the God Formula.
   * w_i = R - min(v_i, R) + 1
   */
  private computeComplement(neuron: BuleyeanNeuron): number[] {
    const R = neuron.totalRejections;
    if (R === 0) {
      // Uniform -- no rejections yet
      return new Array(this.config.activationLevels).fill(
        1 / this.config.activationLevels
      );
    }

    const levels = this.config.activationLevels;
    const weights = new Array(levels);
    let totalWeight = 0;

    for (let i = 0; i < levels; i++) {
      const v = neuron.voidBoundary[i];
      // God Formula: w_i = R - min(v_i, R) + 1
      const w = R - Math.min(v, R) + 1;
      weights[i] = w;
      totalWeight += w;
    }

    // Normalize with temperature
    if (totalWeight === 0) {
      return new Array(levels).fill(1 / levels);
    }

    const temp = this.config.temperature;
    const invTotalWeight = 1 / totalWeight;
    const complement = new Array(levels);
    let normSum = 0;

    if (temp === 1.0) {
      // Fast path: no power operation needed
      for (let i = 0; i < levels; i++) {
        const v = weights[i] * invTotalWeight;
        complement[i] = v;
        normSum += v;
      }
    } else {
      // Pre-compute reciprocal temperature to avoid division in loop
      const invTemp = 1 / temp;
      for (let i = 0; i < levels; i++) {
        const v = Math.pow(weights[i] * invTotalWeight, invTemp);
        complement[i] = v;
        normSum += v;
      }
    }

    // Final normalization with reciprocal multiply
    const invNormSum = 1 / normSum;
    for (let i = 0; i < levels; i++) {
      complement[i] *= invNormSum;
    }

    return complement;
  }

  /**
   * Compute synapse weight from its rejection history.
   * Same God Formula applied to synapse-level rejections.
   */
  private computeSynapseWeight(synapse: BuleyeanSynapse): number {
    if (synapse.totalRounds === 0) return synapse.weight;

    const R = synapse.totalRounds;
    const v = synapse.rejections;

    // God Formula: w = R - min(v, R) + 1, normalized to [0, 1]
    const w = R - Math.min(v, R) + 1;
    const maxW = R + 1; // Maximum possible weight (zero rejections)

    // Scale to [-1, 1] centered at 0
    const normalized = (w / maxW) * 2 - 1;

    // Blend with current weight using learning rate
    return (
      synapse.weight * (1 - this.config.learningRate) +
      normalized * this.config.learningRate
    );
  }

  /**
   * Shannon entropy of a neuron's complement distribution.
   */
  private neuronEntropy(neuron: BuleyeanNeuron): number {
    let h = 0;
    for (const p of neuron.complementWeights) {
      if (p > 0) h -= p * Math.log(p);
    }
    return h;
  }
}
