/**
 * @a0n/zk-encryption - Key Management
 *
 * ECDH key generation, HKDF key derivation, and key utilities
 */

import type {
  ECKeyPair,
  KeyDerivationOptions,
  DomainCategory,
} from './zkTypes.js';

/**
 * Generate a random key ID
 */
export function generateKeyId(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Generate a new P-256 ECDH key pair
 *
 * @returns Key pair with public and private keys
 *
 * @example
 * ```typescript
 * const keyPair = await generateKeyPair();
 * console.log(keyPair.keyId);
 * ```
 */
export async function generateKeyPair(): Promise<ECKeyPair> {
  const keyPair = (await crypto.subtle.generateKey(
    { name: 'ECDH', namedCurve: 'P-256' },
    true,
    ['deriveBits']
  )) as CryptoKeyPair;

  const publicKey = (await crypto.subtle.exportKey(
    'jwk',
    keyPair.publicKey
  )) as JsonWebKey;
  const privateKey = (await crypto.subtle.exportKey(
    'jwk',
    keyPair.privateKey
  )) as JsonWebKey;

  return {
    publicKey,
    privateKey,
    keyId: generateKeyId(),
    createdAt: new Date().toISOString(),
  };
}

/**
 * Import a public key from JWK format
 *
 * @param publicKey - JWK public key
 * @returns CryptoKey for ECDH operations
 */
export async function importPublicKey(
  publicKey: JsonWebKey
): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'jwk',
    publicKey,
    { name: 'ECDH', namedCurve: 'P-256' },
    false,
    []
  );
}

/**
 * Import a private key from JWK format
 *
 * @param privateKey - JWK private key
 * @returns CryptoKey for ECDH operations
 */
export async function importPrivateKey(
  privateKey: JsonWebKey
): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'jwk',
    privateKey,
    { name: 'ECDH', namedCurve: 'P-256' },
    false,
    ['deriveBits']
  );
}

/**
 * Derive shared secret using ECDH
 *
 * @param privateKey - Local private key
 * @param publicKey - Remote public key
 * @returns Shared secret bytes (256 bits)
 */
export async function deriveSharedSecret(
  privateKey: CryptoKey,
  publicKey: CryptoKey
): Promise<Uint8Array> {
  const sharedBits = await crypto.subtle.deriveBits(
    { name: 'ECDH', public: publicKey } as AlgorithmIdentifier,
    privateKey,
    256
  );

  return new Uint8Array(sharedBits);
}

/**
 * Derive an AES key from shared secret using HKDF
 *
 * @param sharedSecret - ECDH shared secret
 * @param category - Domain category for key separation
 * @param options - Key derivation options
 * @returns AES-GCM CryptoKey
 */
export async function deriveAESKey(
  sharedSecret: Uint8Array,
  category: DomainCategory = 'default',
  options?: KeyDerivationOptions
): Promise<CryptoKey> {
  const { salt = new Uint8Array(0), keyLength = 256 } = options || {};

  // Import shared secret as HKDF key material
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    sharedSecret as unknown as BufferSource,
    'HKDF',
    false,
    ['deriveKey']
  );

  // Build info string with domain separation
  const info = options?.info || `zk-${category}-v1`;
  const infoBytes = new TextEncoder().encode(info);

  // Derive AES key
  return crypto.subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt: salt as unknown as BufferSource,
      info: infoBytes as unknown as BufferSource,
    },
    keyMaterial,
    { name: 'AES-GCM', length: keyLength },
    false,
    ['encrypt', 'decrypt']
  );
}

/**
 * Derive AES key directly from two JWK key pairs
 *
 * Convenience function that handles import and ECDH in one call.
 *
 * @param localPrivateKey - Local private key (JWK)
 * @param remotePublicKey - Remote public key (JWK)
 * @param category - Domain category
 * @param options - Key derivation options
 * @returns AES-GCM CryptoKey
 */
export async function deriveAESKeyFromJWK(
  localPrivateKey: JsonWebKey,
  remotePublicKey: JsonWebKey,
  category: DomainCategory = 'default',
  options?: KeyDerivationOptions
): Promise<CryptoKey> {
  const privateKey = await importPrivateKey(localPrivateKey);
  const publicKey = await importPublicKey(remotePublicKey);
  const sharedSecret = await deriveSharedSecret(privateKey, publicKey);
  return deriveAESKey(sharedSecret, category, options);
}

/**
 * Generate a random AES-256 key
 *
 * For symmetric encryption without ECDH.
 *
 * @returns AES-GCM CryptoKey
 */
export async function generateAESKey(): Promise<CryptoKey> {
  return crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, true, [
    'encrypt',
    'decrypt',
  ]);
}

/**
 * Export an AES key to raw bytes
 *
 * @param key - AES CryptoKey
 * @returns Key bytes
 */
export async function exportAESKey(key: CryptoKey): Promise<Uint8Array> {
  const raw = await crypto.subtle.exportKey('raw', key);
  return new Uint8Array(raw);
}

/**
 * Import AES key from raw bytes
 *
 * @param keyBytes - Key bytes (32 bytes for AES-256)
 * @returns AES-GCM CryptoKey
 */
export async function importAESKey(keyBytes: Uint8Array): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'raw',
    keyBytes as unknown as BufferSource,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

/**
 * Generate a random nonce/IV
 *
 * @param length - Nonce length in bytes (default: 12 for AES-GCM)
 * @returns Random bytes
 */
export function generateNonce(length = 12): Uint8Array {
  return crypto.getRandomValues(new Uint8Array(length));
}

/**
 * Compute key fingerprint
 *
 * @param publicKey - JWK public key
 * @returns Fingerprint string
 */
export async function computeKeyFingerprint(
  publicKey: JsonWebKey
): Promise<string> {
  const canonical = JSON.stringify(publicKey, Object.keys(publicKey).sort());
  const bytes = new TextEncoder().encode(canonical);
  const hash = await crypto.subtle.digest('SHA-256', bytes);
  const hashBytes = new Uint8Array(hash);

  // Return first 16 bytes as hex
  return Array.from(hashBytes.slice(0, 16))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Derive a password-based key using PBKDF2
 *
 * @param password - Password string
 * @param salt - Salt bytes (should be random, at least 16 bytes)
 * @param iterations - PBKDF2 iterations (default: 100000)
 * @returns AES-GCM CryptoKey
 */
export async function deriveKeyFromPassword(
  password: string,
  salt: Uint8Array,
  iterations = 100000
): Promise<CryptoKey> {
  const encoder = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    encoder.encode(password),
    'PBKDF2',
    false,
    ['deriveKey']
  );

  return crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: salt as unknown as BufferSource,
      iterations,
      hash: 'SHA-256',
    },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}
