import { FlowFrame, FIN, FOLD, FORK, VENT } from './types';

export const SKYMESH_FRAME_SCHEMA = 'gnosis.skymesh.v1';
export const SKYMESH_FLOW_STREAM_ID = 0x5353;

export interface SkymeshAirGap {
  readonly linkBetweenStations?: boolean;
  readonly [key: string]: unknown;
}

export interface SkymeshFlowFrame {
  readonly schemaVersion: string;
  readonly stations: readonly unknown[];
  readonly airGap: SkymeshAirGap;
  readonly [key: string]: unknown;
}

export interface SkymeshFlowFrameOptions {
  readonly streamId?: number;
  readonly sequence?: number;
  readonly flags?: number;
  readonly terminalBatch?: boolean;
}

const encoder = new TextEncoder();
const decoder = new TextDecoder();

function stableSequence(input: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function firstStationToken(frame: SkymeshFlowFrame): string {
  const station = frame.stations[0];
  if (station && typeof station === 'object') {
    const token = (station as { token?: unknown }).token;
    if (typeof token === 'string') {
      return token;
    }
  }
  return '';
}

function sequenceKey(frame: SkymeshFlowFrame): string {
  return `${firstStationToken(frame)}:${frame.airGap.linkBetweenStations === true ? 'linked' : 'gapped'}`;
}

function isMalformed(frame: SkymeshFlowFrame): boolean {
  return (
    !frame ||
    typeof frame !== 'object' ||
    frame.schemaVersion !== SKYMESH_FRAME_SCHEMA ||
    !Array.isArray(frame.stations) ||
    !frame.airGap ||
    typeof frame.airGap !== 'object'
  );
}

function defaultFlags(frame: SkymeshFlowFrame, terminalBatch: boolean): number {
  const breached = isMalformed(frame) || frame.airGap.linkBetweenStations === true;
  const base = breached ? VENT : FORK | FOLD;
  return terminalBatch ? base | FIN : base;
}

export function encodeSkymeshFlowFrame(
  frame: SkymeshFlowFrame,
  options: SkymeshFlowFrameOptions = {}
): FlowFrame {
  const payload = encoder.encode(JSON.stringify(frame));
  return {
    streamId: options.streamId ?? SKYMESH_FLOW_STREAM_ID,
    sequence: options.sequence ?? stableSequence(sequenceKey(frame)),
    flags: options.flags ?? defaultFlags(frame, options.terminalBatch === true),
    payload,
  };
}

function assertSkymeshFrame(value: unknown): asserts value is SkymeshFlowFrame {
  if (!value || typeof value !== 'object') {
    throw new Error('Skymesh FlowFrame payload must be a JSON object.');
  }
  const frame = value as Partial<SkymeshFlowFrame>;
  if (frame.schemaVersion !== SKYMESH_FRAME_SCHEMA) {
    throw new Error('Skymesh FlowFrame payload has an unsupported schemaVersion.');
  }
  if (!Array.isArray(frame.stations)) {
    throw new Error('Skymesh FlowFrame payload must include a stations array.');
  }
  if (!frame.airGap || typeof frame.airGap !== 'object') {
    throw new Error('Skymesh FlowFrame payload must include an airGap object.');
  }
}

export function decodeSkymeshFlowFrame(flowFrame: FlowFrame): SkymeshFlowFrame {
  const parsed = JSON.parse(decoder.decode(flowFrame.payload)) as unknown;
  assertSkymeshFrame(parsed);
  return parsed;
}
