/**
 * x-gnosis CERA Feedback Collector
 *
 * Collects runtime metrics from the inbound stream and periodically
 * flushes them to the forge event bus as `inbound-entropy-report`.
 *
 * Metrics collected:
 * - Request entropy: Shannon entropy over status codes and latencies
 * - Codec efficiency: from laminar PipelineResult codecDistribution
 * - Handler health: per-route error rates
 * - Void walker state: current void boundary from laminar codec selection
 */

import type { VoidWalkerState, PipelineResult } from './pipeline/laminar.ts';

// ── Types ────────────────────────────────────────────────────

export interface RequestMetric {
  route: string;
  statusCode: number;
  latencyMs: number;
  codec: string;
  timestamp: number;
}

export interface EntropyReport {
  type: 'inbound-entropy-report';
  timestamp: number;
  requestEntropy: number;
  statusDistribution: Record<number, number>;
  codecEfficiency: number;
  codecDistribution: Record<string, number>;
  routeHealth: Record<string, RouteHealth>;
  voidWalkerRounds: number;
  totalRequests: number;
  windowMs: number;
}

export interface RouteHealth {
  requests: number;
  errors: number;
  errorRate: number;
  avgLatencyMs: number;
  p99LatencyMs: number;
}

export interface FeedbackCollectorConfig {
  /** Flush interval in milliseconds (default: 30000) */
  flushIntervalMs: number;
  /** Forge event bus URL for HTTP POST (default: localhost:3334) */
  forgeEventBusUrl: string;
  /** Maximum metrics to buffer before forced flush */
  maxBufferSize: number;
}

const DEFAULT_CONFIG: FeedbackCollectorConfig = {
  flushIntervalMs: 30_000,
  forgeEventBusUrl: 'http://localhost:3334',
  maxBufferSize: 10_000,
};

// ── Feedback Collector ───────────────────────────────────────

export class CeraFeedbackCollector {
  private config: FeedbackCollectorConfig;
  private metrics: RequestMetric[] = [];
  private flushTimer: ReturnType<typeof setInterval> | null = null;
  private lastFlush = Date.now();
  private voidWalkerRef: VoidWalkerState | null = null;
  private codecStats: Record<string, number> = {};
  private onFlush: ((report: EntropyReport) => void) | null = null;
  private onIdle: (() => void) | null = null;

  constructor(config: Partial<FeedbackCollectorConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Set a callback for idle windows.
   * Called after flush when the buffer is empty -- signals that the
   * pipeline has no pending work and daydreaming can begin.
   */
  setIdleHandler(handler: () => void): void {
    this.onIdle = handler;
  }

  /**
   * Start periodic flush timer.
   */
  start(): void {
    if (this.flushTimer) return;
    this.flushTimer = setInterval(( ) => {
      this.flush();
    }, this.config.flushIntervalMs);
  }

  /**
   * Stop the collector and flush remaining metrics.
   */
  stop(): void {
    if (this.flushTimer) {
      clearInterval(this.flushTimer);
      this.flushTimer = null;
    }
    this.flush();
  }

  /**
   * Record a request metric after response.
   */
  record(metric: RequestMetric): void {
    this.metrics.push(metric);

    // Track codec distribution
    this.codecStats[metric.codec] = (this.codecStats[metric.codec] ?? 0) + 1;

    // Force flush if buffer is full
    if (this.metrics.length >= this.config.maxBufferSize) {
      this.flush();
    }
  }

  /**
   * Record codec distribution from a laminar pipeline result.
   */
  recordPipelineResult(result: PipelineResult): void {
    for (const [codec, count] of Object.entries(result.codecDistribution)) {
      this.codecStats[codec] = (this.codecStats[codec] ?? 0) + count;
    }
  }

  /**
   * Set the shared void walker reference for state reporting.
   */
  setVoidWalker(walker: VoidWalkerState): void {
    this.voidWalkerRef = walker;
  }

  /**
   * Set a callback for flush events (alternative to HTTP POST).
   */
  setFlushHandler(handler: (report: EntropyReport) => void): void {
    this.onFlush = handler;
  }

  /**
   * Flush buffered metrics and send entropy report.
   */
  flush(): EntropyReport | null {
    if (this.metrics.length === 0) return null;

    const now = Date.now();
    const windowMs = now - this.lastFlush;

    // Compute status code distribution
    const statusCounts: Record<number, number> = {};
    for (const m of this.metrics) {
      statusCounts[m.statusCode] = (statusCounts[m.statusCode] ?? 0) + 1;
    }

    // Compute per-route health
    const routeMap = new Map<string, RequestMetric[]>();
    for (const m of this.metrics) {
      const arr = routeMap.get(m.route) ?? [];
      arr.push(m);
      routeMap.set(m.route, arr);
    }

    const routeHealth: Record<string, RouteHealth> = {};
    for (const [route , metrics] of routeMap ) {
      const errors = metrics.filter((m) => m.statusCode >= 500).length;
      const latencies = metrics.map((m) => m.latencyMs).sort((a, b) => a - b);
      const p99Idx = Math.min(
        Math.ceil(latencies.length * 0.99) - 1,
        latencies.length - 1
      );

      routeHealth[route] = {
        requests: metrics.length,
        errors,
        errorRate: metrics.length > 0 ? errors / metrics.length : 0,
        avgLatencyMs: latencies.reduce((a, b) => a + b, 0) / latencies.length,
        p99LatencyMs: latencies[p99Idx] ?? 0,
      };
    }

    // Shannon entropy over status code distribution
    const totalReqs = this.metrics.length;
    const statusProbs = Object.values(statusCounts).map((c) => c / totalReqs);
    const requestEntropy = shannonEntropy(statusProbs);

    // Codec efficiency: ratio of non-identity to total
    const totalCodecUses = Object.values(this.codecStats).reduce(
      (a, b) => a + b,
      0
    );
    const identityUses = this.codecStats['identity'] ?? 0;
    const codecEfficiency =
      totalCodecUses > 0 ? 1 - identityUses / totalCodecUses : 0;

    const report: EntropyReport = {
      type: 'inbound-entropy-report',
      timestamp: now,
      requestEntropy,
      statusDistribution: statusCounts,
      codecEfficiency,
      codecDistribution: { ...this.codecStats },
      routeHealth,
      voidWalkerRounds: this.voidWalkerRef?.rounds ?? 0,
      totalRequests: totalReqs,
      windowMs,
    };

    // Send to forge event bus
    if (this.onFlush) {
      this.onFlush(report);
    } else {
      this.sendToForge(report);
    }

    // Reset state
    this.metrics = [];
    this.codecStats = {};
    this.lastFlush = now;

    // Signal idle window -- buffer is empty, daydreaming can begin
    if (this.onIdle && this.metrics.length === 0) {
      try {
        this.onIdle();
      } catch {
        // Idle handler errors should not break the collector
      }
    }

    return report;
  }

  /**
   * Current buffer size.
   */
  get bufferedCount(): number {
    return this.metrics.length;
  }

  private async sendToForge(report: EntropyReport): Promise<void> {
    try {
      await fetch(`${this.config.forgeEventBusUrl}/events`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'inbound-entropy-report',
          projectName: 'x-gnosis',
          timestamp: report.timestamp,
          details: report,
        }),
      });
    } catch {
      // Best-effort delivery -- metrics will be re-collected next window
    }
  }
}

// ── Shannon Entropy (inline for zero-dep feedback collector) ─

function shannonEntropy(probs: number[]): number {
  let h = 0;
  for (const p of probs ) {
    if (p > 0) h -= p * Math.log(p);
  }
  return h;
}
