function normalizeOptionalString(
  value: string | null | undefined
): string | undefined {
  const trimmed = value?.trim();
  return trimmed && trimmed.length > 0 ? trimmed : undefined;
}

function concatUint8Arrays(chunks: readonly Uint8Array[]): Uint8Array {
  const total = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks ) {
    bytes.set(chunk, offset);
    offset += chunk.length;
  }
  return bytes;
}

function uniqueFamilies(
  manifest: TauriEdgeArtifactManifest,
  families: readonly TauriEdgeFragmentFamily[] | undefined
): TauriEdgeFragmentFamily[] {
  const requested =
    families && families.length > 0
      ? families
      : manifest.fragments.map((fragment) => fragment.family);
  return [...new Set(requested)].sort();
}

function isExactManifest(value ): value is TauriEdgeArtifactManifest {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { runtimeTarget?  }).runtimeTarget === 'tauri-edge' &&
    typeof (value as { artifactId?  }).artifactId === 'string' &&
    typeof (value as { manifestDigest?  }).manifestDigest === 'string'
  );
}

function requiredCapability(can: string, artifactId: string): GnosisCapability {
  return {
    can,
    with: `aeon://artifact/${artifactId}`,
  };
}

function enforceCapability(
  executionAuth: GnosisExecutionAuthContext | null | undefined,
  required: GnosisCapability,
  reason: string
): void {
  if (!executionAuth || executionAuth.enforce !== true ) {
    return;
  }

  if (!checkGrantedCapability(executionAuth.capabilities ?? [], required)) {
    throw new Error(
      `Missing capability ${required.can} on ${required.with} for ${reason}.`
    );
  }
}

function capabilitiesToHeaderValues(
  executionAuth: GnosisExecutionAuthContext | null | undefined
): string[] {
  const capabilities = executionAuth?.capabilities ?? [];
  return capabilities
    .map((capability ) => {
      const can = capability.can?.trim();
      if (!can ) {
        return null;
      }
      const withValue = capability.with?.trim();
      return withValue ? `${can} ${withValue}` : can;
    })
    .filter((entry): entry is string => Boolean(entry));
}

function normalizeRuntimeBinding(
  manifest: TauriEdgeArtifactManifest,
  runtimeBindingHash: string | null | undefined
): string | undefined {
  const expected = normalizeOptionalString(manifest.runtimeBindingHash);
  const actual = normalizeOptionalString(runtimeBindingHash ?? undefined);
  if (expected && actual && expected !== actual ) {
    throw new Error(
      `Tauri-edge runtime binding mismatch: manifest expects ${expected}, received ${actual}.`
    );
  }
  return actual ?? expected;
}

function pathRequiresZk(
  manifest: TauriEdgeArtifactManifest,
  scopePath: string | undefined
): string | null {
  if (!manifest.zkPolicy || !scopePath ) {
    return null;
  }

  return (manifest.zkPolicy.protectedPaths.find((candidate ) => {
      const normalized = normalizeOptionalString(candidate);
      return normalized ? scopePath.startsWith(normalized) : false;
    }) ?? null
  );
}

function enforceZkPolicy(input: {
  readonly manifest: TauriEdgeArtifactManifest;
  readonly scopePath?: string;
  readonly zkProof?: TauriEdgeZkProofEnvelope | null;
}): void {
  const protectedPath = pathRequiresZk(input.manifest, input.scopePath);
  if (!protectedPath || !input.manifest.zkPolicy ) {
    return;
  }

  if (input.manifest.zkPolicy.mode === 'off' ) {
    return;
  }

  const proof = input.zkProof;
  const coversPath =
    !!proof?.proof &&
    (proof.paths?.some((candidate) => candidate === protectedPath) ?? false);

  if (input.manifest.zkPolicy.mode === 'required' && !coversPath ) {
    throw new Error(
      `Tauri-edge path ${protectedPath} requires a ZK proof under ${
        input.manifest.zkPolicy.proofSystem ?? 'the configured proof system'
      }.`
    );
  }
}

function requireRuntimePosition(
  position: XGnosisResolvedRuntimePosition | null,
  reason: string
): XGnosisResolvedRuntimePosition {
  if (!position ) {
    throw new Error(
      `Unable to resolve tauri-edge runtime position for ${reason}.`
    );
  }

  return position;
}

export class XGnosisTauriEdgeRuntime {
  private readonly enabled: boolean;
  private readonly db: TauriEdgeD1Database | null;
  private readonly tables: TauriEdgeD1TableNames;
  private readonly payloadRoot?: string;
  private readonly spoolDir: string;
  private readonly worldAlias: string;
  private readonly nodeIdOverride?: string;
  private readonly runtimeIdOverride?: string;
  private readonly runtimeBindingHash?: string;
  private readonly executionSurface: GnosisTauriEdgeExecutionSurface;
  private readonly runtimeContinuationClient: XGnosisRuntimeContinuationClient | null;
  private readonly runtimeContinuationStrict: boolean;
  private readonly hydratedArtifacts = new Map<
    string,
    HydratedTauriEdgeArtifact
  >();
  private readonly sessionCache = new Map<string, StoredTauriEdgeSession>();
  private readonly runtimeToArtifact = new Map<string, string>();
  private coldHydrations = 0;
  private warmHydrations = 0;
  private d1ArtifactReads = 0;
  private d1FragmentReads = 0;

  constructor(options: XGnosisTauriEdgeRuntimeOptions) {
    this.enabled = options.enabled ?? true;
    this.db = options.db ?? null;
    this.tables =
      options.d1Tables ??
      resolveTauriEdgeD1TableNames(options.d1TablePrefix ?? 'tauri_edge');
    this.payloadRoot = normalizeOptionalString(options.payloadRoot);
    this.spoolDir = options.spoolDir;
    this.worldAlias = options.worldAlias ?? 'default';
    this.nodeIdOverride = normalizeOptionalString(options.nodeId);
    this.runtimeIdOverride = normalizeOptionalString(options.runtimeId);
    this.runtimeBindingHash = normalizeOptionalString(
      options.runtimeBindingHash ?? undefined
    );
    mkdirSync(this.spoolDir, { recursive: true });
    this.executionSurface = new GnosisTauriEdgeExecutionSurface({
      wasmSurface:
        (options.wasmExecutionSurface as unknown as GnosisTauriEdgeExecutionSurfaceOptions['wasmSurface']) ??
        undefined,
      runtimeName: 'tauri-edge',
    });
    this.runtimeContinuationClient = options.runtimeContinuation
      ? new XGnosisRuntimeContinuationClient(options.runtimeContinuation)
      : null;
    this.runtimeContinuationStrict = options.runtimeContinuationStrict ?? false;
  }

  getStatus(): XGnosisTauriEdgeRuntimeStatus {
    return {
      enabled: this.enabled,
      hydratedArtifacts: this.hydratedArtifacts.size,
      activeSessions: this.sessionCache.size,
      coldHydrations: this.coldHydrations,
      warmHydrations: this.warmHydrations,
      d1ArtifactReads: this.d1ArtifactReads,
      d1FragmentReads: this.d1FragmentReads,
    };
  }

  async hydrateArtifact(
    request: XGnosisTauriEdgeHydrateRequest
  ): Promise<XGnosisTauriEdgeHydrateResult> {
    const hydrated = await this.ensureHydrated(
      request.artifactId,
      request.families,
      request.executionAuth
    );
    return {
      artifactId: hydrated.manifest.artifactId,
      manifestDigest: hydrated.manifest.manifestDigest,
      warm: hydrated.warm,
      hydratedFamilies: [...hydrated.familyPaths.keys()].sort(),
      fragmentCount: hydrated.manifest.fragments.length,
      ...(hydrated.guestWasmPath
        ? { guestWasmPath: hydrated.guestWasmPath }
        : {}),
      ...(hydrated.commandSurfacePath
        ? { commandSurfacePath: hydrated.commandSurfacePath }
        : {}),
    };
  }

  async invoke(
    request: XGnosisTauriEdgeInvokeRequest
  ): Promise<XGnosisTauriEdgeInvokeResult> {
    const hydrated = await this.ensureHydrated(
      request.artifactId,
      ['guest-wasm', 'command-surface', 'capability'],
      request.executionAuth
    );
    const commandSurface = hydrated.commandSurfacePath
      ? JSON.parse(readFileSync(hydrated.commandSurfacePath, 'utf8'))
      : undefined;
    const execution = await this.executionSurface.invoke({
      manifest: hydrated.manifest,
      guestWasmPath: hydrated.guestWasmPath,
      command: request.command,
      input: request.input,
      commandSurface,
      executionAuth: request.executionAuth,
      scopePath: request.scopePath,
      zkProof: request.zkProof,
      runtimeBindingHash:
        request.runtimeBindingHash ??
        this.runtimeBindingHash ??
        hydrated.manifest.runtimeBindingHash,
    });

    const sessionId = request.sessionId ?? randomUUID();
    const ordinal =
      (this.sessionCache.get(sessionId)?.position.ordinal ?? -1) + 1;
    const positionRoot = sha256Hex(
      JSON.stringify({
        artifactId: hydrated.manifest.artifactId,
        sessionId,
        command: request.command,
        ordinal,
        payload: execution.payload ?? null,
      })
    );
    const snapshotRoot = sha256Hex(
      JSON.stringify({
        artifactId: hydrated.manifest.artifactId,
        sessionId,
        command: request.command,
        ordinal,
        positionRoot,
      })
    );
    const updatedAt = Date.now();
    const guestFragment = hydrated.manifest.fragments.find(
      (fragment) => fragment.family === 'guest-wasm'
    );
    const runtimePosition = requireRuntimePosition(
      resolveXGnosisRuntimePosition({
        worldAlias: this.worldAlias,
        nodeId: this.resolveNodeId(hydrated.manifest),
        runtime: 'tauri-edge',
        runtimeId: this.resolveRuntimeId(hydrated.manifest),
        sessionId,
        snapshotRoot,
        positionId: `cursor-${ordinal}`,
        positionRoot,
        ...(guestFragment ? { streamId: String(guestFragment.streamId) } : {}),
        ordinal,
        reconstructable: true,
      }),
      `artifact ${hydrated.manifest.artifactId} session ${sessionId}`
    );
    this.runtimeToArtifact.set(
      runtimePosition.runtimeId,
      hydrated.manifest.artifactId
    );
    this.sessionCache.set(sessionId, {
      artifactId: hydrated.manifest.artifactId,
      runtimeId: runtimePosition.runtimeId,
      position: runtimePosition,
      updatedAt,
    });
    await this.persistSession({
      session_id: sessionId,
      artifact_id: hydrated.manifest.artifactId,
      snapshot_root: snapshotRoot,
      position_root: positionRoot,
      ...(guestFragment ? { stream_id: guestFragment.streamId } : {}),
      ordinal,
      ...(request.zkProof?.proof ? { zk_proof: request.zkProof.proof } : {}),
      updated_at: updatedAt,
    });

    await this.pauseRuntimeContinuationRemote({
      artifactId: hydrated.manifest.artifactId,
      runtimeTarget: 'tauri-edge',
      sessionId,
      positionRoot,
      snapshotRoot,
      ordinal,
      projectName:
        normalizeOptionalString(hydrated.manifest.application.name) ??
        hydrated.manifest.artifactId,
      ownerDid: request.executionAuth?.principal,
      executionAuth: request.executionAuth,
    });

    return {
      hydration: {
        artifactId: hydrated.manifest.artifactId,
        manifestDigest: hydrated.manifest.manifestDigest,
        warm: hydrated.warm,
        hydratedFamilies: [...hydrated.familyPaths.keys()].sort(),
        fragmentCount: hydrated.manifest.fragments.length,
        ...(hydrated.guestWasmPath
          ? { guestWasmPath: hydrated.guestWasmPath }
          : {}),
        ...(hydrated.commandSurfacePath
          ? { commandSurfacePath: hydrated.commandSurfacePath }
          : {}),
      },
      execution,
      sessionId,
      runtimePosition,
    };
  }

  async resumeSession(
    request: XGnosisTauriEdgeResumeRequest
  ): Promise<XGnosisTauriEdgeResumeResult> {
    const remote = await this.resumeRuntimeContinuationRemote(request);
    if (remote ) {
      return remote;
    }

    const cached = this.sessionCache.get(request.sessionId);
    if (cached ) {
      const manifest = await this.loadManifest(cached.artifactId);
      this.enforceSessionResume({
        executionAuth: request.executionAuth,
        manifest,
        scopePath: request.scopePath,
        zkProof: request.zkProof,
      });
      return {
        sessionId: request.sessionId,
        artifactId: cached.artifactId,
        runtimePosition: cached.position,
      };
    }

    const row = await this.loadSessionRow(request.sessionId);
    if (!row ) {
      throw new Error(`Unknown tauri-edge session '${request.sessionId}'.`);
    }

    const manifest = await this.loadManifest(row.artifact_id);
    this.enforceSessionResume({
      executionAuth: request.executionAuth,
      manifest,
      scopePath: request.scopePath,
      zkProof: request.zkProof,
    });
    const runtimePosition = requireRuntimePosition(
      resolveXGnosisRuntimePosition({
        worldAlias: this.worldAlias,
        nodeId: this.resolveNodeId(manifest),
        runtime: 'tauri-edge',
        runtimeId: this.resolveRuntimeId(manifest),
        sessionId: row.session_id,
        snapshotRoot: normalizeOptionalString(row.snapshot_root),
        positionId:
          row.ordinal !== undefined ? `cursor-${row.ordinal}` : undefined,
        positionRoot: normalizeOptionalString(row.position_root),
        ...(row.stream_id !== undefined
          ? { streamId: String(row.stream_id) }
          : {}),
        ordinal: row.ordinal,
        reconstructable: true,
      }),
      `artifact ${manifest.artifactId} session ${row.session_id}`
    );
    this.runtimeToArtifact.set(runtimePosition.runtimeId, manifest.artifactId);
    this.sessionCache.set(request.sessionId, {
      artifactId: manifest.artifactId,
      runtimeId: runtimePosition.runtimeId,
      position: runtimePosition,
      updatedAt: row.updated_at,
    });
    return {
      sessionId: request.sessionId,
      artifactId: manifest.artifactId,
      runtimePosition,
    };
  }

  async issueSessionHandoff(
    request: XGnosisTauriEdgeHandoffRequest
  ): Promise<XGnosisTauriEdgeHandoffResult> {
    if (!this.runtimeContinuationClient) {
      throw new Error('tauri-edge runtime continuation remote is not enabled.');
    }
    const principal = normalizeOptionalString(request.executionAuth?.principal);
    if (!principal ) {
      throw new Error(
        'tauri-edge runtime handoff requires executionAuth.principal.'
      );
    }

    return this.runtimeContinuationClient.handoff(
      {
        sessionId: request.sessionId,
        fromDid: principal,
        ...(request.toDid ? { toDid: request.toDid } : {}),
        ...(request.capabilities ? { capabilities: request.capabilities } : {}),
        bindingScheme: request.bindingScheme,
        bindingEpoch: request.bindingEpoch,
        ...(request.bindingNonce
          ? { bindingNonce: request.bindingNonce }
          : {}),
        ...(request.classicalBinding
          ? { classicalBinding: request.classicalBinding }
          : {}),
        ...(request.pqBinding ? { pqBinding: request.pqBinding } : {}),
        ...(request.expiresAt ? { expiresAt: request.expiresAt } : {}),
      },
      {
        authToken: request.executionAuth?.token,
        capabilities: capabilitiesToHeaderValues(request.executionAuth),
      }
    );
  }

  async resolveSession(
    request: XGnosisTauriEdgeResolveRequest
  ): Promise<XGnosisTauriEdgeResolveResult> {
    if (!this.runtimeContinuationClient) {
      throw new Error('tauri-edge runtime continuation remote is not enabled.');
    }
    if (!request.sessionId && !request.bookmark ) {
      throw new Error(
        'tauri-edge runtime resolve requires sessionId or bookmark.'
      );
    }
    return this.runtimeContinuationClient.resolve(
      {
        ...(request.sessionId ? { sessionId: request.sessionId } : {}),
        ...(request.bookmark ? { bookmark: request.bookmark } : {}),
      },
      {
        authToken: request.executionAuth?.token,
        capabilities: capabilitiesToHeaderValues(request.executionAuth),
      }
    );
  }

  createObjectResolver(): AeonObjectResolver {
    return async ({ route, request } ) => {
      if (route.kind !== 'rhizome' ) {
        return null;
      }

      const runtimeBookmark = route.runtimeBookmark;
      const runtimeTarget =
        runtimeBookmark?.runtimeTarget ?? runtimeBookmark?.runtime;
      if (runtimeTarget && runtimeTarget !== 'tauri-edge' ) {
        return null;
      }

      const subjectKind = route.subjectKind ?? 'runtime-position';
      if (subjectKind !== 'runtime' &&
        subjectKind !== 'runtime-session' &&
        subjectKind !== 'runtime-position' ) {
        return null;
      }

      const sessionId = normalizeOptionalString(runtimeBookmark?.sessionId);
      if (sessionId ) {
        const executionAuth = await deriveExecutionAuthFromHeaders(
          request.headers
        );
        const resumed = await this.resumeSession({
          sessionId,
          ...(executionAuth ? { executionAuth } : {}),
        });
        return createRuntimePositionEnvelope({
          request,
          runtimePosition: resumed.runtimePosition,
          subjectKind,
        });
      }

      const runtimeId = normalizeOptionalString(
        runtimeBookmark?.runtimeId ?? route.nodeId ?? undefined
      );
      if (!runtimeId ) {
        return null;
      }

      const artifactId = this.runtimeToArtifact.get(runtimeId) ?? runtimeId;
      const manifest = await this.tryLoadManifest(artifactId);
      if (!manifest ) {
        return null;
      }

      const runtimePosition = requireRuntimePosition(
        resolveXGnosisRuntimePosition({
          worldAlias: this.worldAlias,
          nodeId: this.resolveNodeId(manifest),
          runtime: 'tauri-edge',
          runtimeId: this.resolveRuntimeId(manifest),
          sessionId: `${manifest.artifactId}-root`,
          snapshotRoot: manifest.manifestDigest,
          reconstructable: true,
        }),
        `artifact ${manifest.artifactId} root session`
      );
      this.runtimeToArtifact.set(
        runtimePosition.runtimeId,
        manifest.artifactId
      );
      return createRuntimePositionEnvelope({
        request,
        runtimePosition,
        subjectKind,
      });
    };
  }

  private async pauseRuntimeContinuationRemote(input: {
    readonly artifactId: string;
    readonly runtimeTarget: string;
    readonly sessionId: string;
    readonly snapshotRoot: string;
    readonly positionRoot: string;
    readonly ordinal: number;
    readonly projectName: string;
    readonly ownerDid?: string;
    readonly executionAuth?: GnosisExecutionAuthContext | null;
  }): Promise<void> {
    if (!this.runtimeContinuationClient) {
      return;
    }

    try {
      await this.runtimeContinuationClient.pause(
        {
          sessionId: input.sessionId,
          projectName: input.projectName,
          runtimeTarget: input.runtimeTarget,
          artifactId: input.artifactId,
          snapshotRoot: input.snapshotRoot,
          positionRoot: input.positionRoot,
          ordinal: input.ordinal,
          ...(input.ownerDid ? { ownerDid: input.ownerDid } : {}),
        },
        {
          authToken: input.executionAuth?.token,
        }
      );
    } catch (error ) {
      if (this.runtimeContinuationStrict) {
        throw error;
      }
    }
  }

  private async resumeRuntimeContinuationRemote(
    request: XGnosisTauriEdgeResumeRequest
  ): Promise<XGnosisTauriEdgeResumeResult | null> {
    if (!this.runtimeContinuationClient) {
      return null;
    }

    const callerCapabilities = capabilitiesToHeaderValues(
      request.executionAuth
    );
    let resumed;
    try {
      resumed = await this.runtimeContinuationClient.resume(
        {
          sessionId: request.sessionId,
          ...(request.executionAuth?.principal
            ? { requesterDid: request.executionAuth.principal }
            : {}),
          ...(request.handoffId ? { handoffId: request.handoffId } : {}),
          ...(request.executionAuth?.enforce !== undefined
            ? { enforceAuth: request.executionAuth.enforce }
            : {}),
          ...(request.expectedRuntimeTarget
            ? { expectedRuntimeTarget: request.expectedRuntimeTarget }
            : {}),
          ...(request.expectedArtifactId
            ? { expectedArtifactId: request.expectedArtifactId }
            : {}),
          ...(request.expectedSnapshotRoot
            ? { expectedSnapshotRoot: request.expectedSnapshotRoot }
            : {}),
          ...(request.expectedPositionRoot
            ? { expectedPositionRoot: request.expectedPositionRoot }
            : {}),
          ...(request.expectedOrdinal !== undefined
            ? { expectedOrdinal: request.expectedOrdinal }
            : {}),
        },
        {
          authToken: request.executionAuth?.token,
          capabilities: callerCapabilities,
        }
      );
    } catch (error ) {
      if (this.runtimeContinuationStrict) {
        throw error;
      }
      return null;
    }

    if (resumed.result !== 'ok' || !resumed.run || !resumed.session ) {
      if (this.runtimeContinuationStrict) {
        throw new Error(
          `tauri-edge runtime continuation resume failed for session ${request.sessionId}: ${resumed.reason ?? resumed.result}`
        );
      }
      return null;
    }

    const manifest = await this.tryLoadManifest(resumed.run.artifactId);
    if (!manifest ) {
      if (this.runtimeContinuationStrict) {
        throw new Error(
          `tauri-edge runtime continuation returned artifact '${resumed.run.artifactId}' which is unavailable locally.`
        );
      }
      return null;
    }

    this.enforceSessionResume({
      executionAuth: request.executionAuth,
      manifest,
      scopePath: request.scopePath,
      zkProof: request.zkProof,
    });

    const remotePosition = resumed.runtimePosition;
    const snapshotRoot =
      normalizeOptionalString(remotePosition?.snapshotRoot) ??
      normalizeOptionalString(resumed.run.snapshotRoot);
    const positionRoot = normalizeOptionalString(remotePosition?.positionRoot);
    const ordinal =
      remotePosition?.ordinal ??
      (typeof resumed.session.ordinal === 'number'
        ? resumed.session.ordinal
        : undefined);

    const runtimePosition = requireRuntimePosition(
      resolveXGnosisRuntimePosition({
        worldAlias: this.worldAlias,
        nodeId: this.resolveNodeId(manifest),
        runtime: 'tauri-edge',
        runtimeId: this.resolveRuntimeId(manifest),
        sessionId: remotePosition?.sessionId ?? resumed.session.sessionId,
        ...(snapshotRoot ? { snapshotRoot } : {}),
        ...(ordinal !== undefined ? { positionId: `cursor-${ordinal}` } : {}),
        ...(positionRoot ? { positionRoot } : {}),
        ...(ordinal !== undefined ? { ordinal } : {}),
        reconstructable: true,
      }),
      `remote continuation session ${request.sessionId}`
    );

    const updatedAt = resumed.session.updatedAt ?? Date.now();
    this.runtimeToArtifact.set(runtimePosition.runtimeId, manifest.artifactId);
    this.sessionCache.set(runtimePosition.sessionId, {
      artifactId: manifest.artifactId,
      runtimeId: runtimePosition.runtimeId,
      position: runtimePosition,
      updatedAt,
    });
    await this.persistSession({
      session_id: runtimePosition.sessionId,
      artifact_id: manifest.artifactId,
      ...(snapshotRoot ? { snapshot_root: snapshotRoot } : {}),
      ...(positionRoot ? { position_root: positionRoot } : {}),
      ...(ordinal !== undefined ? { ordinal } : {}),
      updated_at: updatedAt,
    });

    return {
      sessionId: runtimePosition.sessionId,
      artifactId: manifest.artifactId,
      runtimePosition,
    };
  }

  private enforceSessionResume(input: {
    readonly executionAuth: GnosisExecutionAuthContext | null | undefined;
    readonly manifest: TauriEdgeArtifactManifest;
    readonly scopePath?: string;
    readonly zkProof?: TauriEdgeZkProofEnvelope | null;
  }): void {
    normalizeRuntimeBinding(input.manifest, this.runtimeBindingHash);
    enforceZkPolicy(input);
    enforceCapability(
      input.executionAuth,
      requiredCapability(
        'tauri-edge/session.resume',
        input.manifest.artifactId
      ),
      'session resume'
    );
  }

  private async ensureHydrated(
    artifactId: string,
    requestedFamilies: readonly TauriEdgeFragmentFamily[] | undefined,
    executionAuth: GnosisExecutionAuthContext | null | undefined
  ): Promise<HydratedTauriEdgeArtifact> {
    const cached = this.hydratedArtifacts.get(artifactId);
    if (cached ) {
      const families = uniqueFamilies(cached.manifest, requestedFamilies);
      const warm = families.every((family) =>
        (cached.familyPaths.get(family) ?? []).every((filePath) =>
          existsSync(filePath)
        )
      );
      if (warm ) {
        this.warmHydrations += 1;
        return {
          ...cached,
          warm: true,
        };
      }
    }

    this.enforceArtifactHydrate(executionAuth, artifactId);
    const manifest = cached?.manifest ?? (await this.loadManifest(artifactId));
    const families = uniqueFamilies(manifest, requestedFamilies);
    const spoolManifestPath = this.spoolManifestPath(artifactId);
    if (existsSync(spoolManifestPath) && !cached) {
      const spooledManifest = this.loadManifestFromSpool(artifactId);
      if (spooledManifest ) {
        const spooledFamilyPaths =
          this.buildFamilyPathsFromManifest(spooledManifest);
        const warm = families.every((family) =>
          (spooledFamilyPaths.get(family) ?? []).every((filePath) =>
            existsSync(filePath)
          )
        );
        if (warm ) {
          const hydrated = this.finishHydratedArtifact(
            spooledManifest,
            spooledFamilyPaths,
            true
          );
          this.hydratedArtifacts.set(artifactId, hydrated);
          this.warmHydrations += 1;
          return hydrated;
        }
      }
    }

    const fragments = await this.loadFragmentRows(artifactId, families);
    const familyRows = new Map<
      TauriEdgeFragmentFamily,
      TauriEdgeFragmentRow[]
    >();
    for (const fragment of fragments ) {
      const existing = familyRows.get(fragment.family) ?? [];
      existing.push(fragment);
      familyRows.set(fragment.family, existing);
    }

    const familyPaths = new Map<TauriEdgeFragmentFamily, readonly string[]>();
    for (const family of families ) {
      const rows = (familyRows.get(family) ?? []).sort((left , right ) => {
        if (left.stream_id !== right.stream_id ) {
          return left.stream_id - right.stream_id;
        }
        return left.ordinal - right.ordinal;
      });
      const grouped = new Map<string, TauriEdgeFragmentRow[]>();
      for (const row of rows ) {
        const key = `${row.family}:${row.stream_id}:${row.source_path ?? ''}`;
        const existing = grouped.get(key) ?? [];
        existing.push(row);
        grouped.set(key, existing);
      }
      const materialized: string[] = [];
      for (const groupedRows of grouped.values()) {
        const bytes = concatUint8Arrays(
          groupedRows.map((row) => this.readFragmentPayload(row))
        );
        const outputPath = this.materializedPathForRow(
          artifactId,
          groupedRows[0]!
        );
        mkdirSync(dirname(outputPath), { recursive: true });
        writeFileSync(outputPath, bytes);
        materialized.push(outputPath);
      }
      familyPaths.set(family, materialized);
    }

    mkdirSync(dirname(spoolManifestPath), { recursive: true });
    writeFileSync(
      spoolManifestPath,
      `${JSON.stringify(manifest, null, 2)}\n`,
      'utf8'
    );
    const hydrated = this.finishHydratedArtifact(manifest, familyPaths, false);
    this.hydratedArtifacts.set(artifactId, hydrated);
    this.runtimeToArtifact.set(
      this.resolveRuntimeId(manifest),
      manifest.artifactId
    );
    this.coldHydrations += 1;
    return hydrated;
  }

  private finishHydratedArtifact(
    manifest: TauriEdgeArtifactManifest,
    familyPaths: ReadonlyMap<TauriEdgeFragmentFamily, readonly string[]>,
    warm: boolean
  ): HydratedTauriEdgeArtifact {
    return {
      manifest,
      familyPaths,
      guestWasmPath: familyPaths.get('guest-wasm')?.[0],
      commandSurfacePath: familyPaths.get('command-surface')?.[0],
      capabilityManifestPath: familyPaths.get('capability')?.[0],
      attestationPath: familyPaths.get('attestation')?.[0],
      warm,
    };
  }

  private enforceArtifactHydrate(
    executionAuth: GnosisExecutionAuthContext | null | undefined,
    artifactId: string
  ): void {
    enforceCapability(
      executionAuth,
      requiredCapability('tauri-edge/artifact.hydrate', artifactId),
      'artifact hydration'
    );
    enforceCapability(
      executionAuth,
      requiredCapability('tauri-edge/fragment.read', artifactId),
      'fragment read'
    );
  }

  private readFragmentPayload(row: TauriEdgeFragmentRow): Uint8Array {
    const payloadPath = this.resolvePayloadPath(row.payload_ref);
    const bytes = new Uint8Array(readFileSync(payloadPath));
    if (sha256Hex(bytes) !== row.hash) {
      throw new Error(
        `Tauri-edge fragment hash mismatch for ${row.payload_ref}.`
      );
    }
    const frame = decodeTauriEdgeFlowFrame(bytes);
    if (frame.streamId !== row.stream_id || frame.sequence !== row.ordinal ) {
      throw new Error(
        `Tauri-edge fragment sequence mismatch for ${row.payload_ref}.`
      );
    }
    return frame.payload;
  }

  private resolvePayloadPath(payloadRef: string): string {
    if (isAbsolute(payloadRef)) {
      return payloadRef;
    }
    if (!this.payloadRoot) {
      return resolve(payloadRef);
    }
    return join(this.payloadRoot, payloadRef);
  }

  private materializedPathForRow(
    artifactId: string,
    row: Pick<TauriEdgeFragmentRow, 'family' | 'stream_id' | 'source_path'>
  ): string {
    const relativePath =
      normalizeOptionalString(row.source_path ?? undefined) ??
      join('generated', row.family, `${row.stream_id}.bin`);
    return join(this.spoolDir, artifactId, 'materialized', relativePath);
  }

  private spoolManifestPath(artifactId: string): string {
    return join(this.spoolDir, artifactId, 'manifest.json');
  }

  private buildFamilyPathsFromManifest(
    manifest: TauriEdgeArtifactManifest
  ): ReadonlyMap<TauriEdgeFragmentFamily, readonly string[]> {
    const grouped = new Map<TauriEdgeFragmentFamily, string[]>();
    const seen = new Set<string>();
    for (const fragment of manifest.fragments ) {
      const path = this.materializedPathForFragment(
        manifest.artifactId,
        fragment
      );
      if (seen.has(path)) {
        continue;
      }
      seen.add(path);
      const existing = grouped.get(fragment.family) ?? [];
      existing.push(path);
      grouped.set(fragment.family, existing);
    }
    return grouped;
  }

  private materializedPathForFragment(
    artifactId: string,
    fragment: TauriEdgeFragmentDescriptor
  ): string {
    const relativePath =
      normalizeOptionalString(fragment.sourcePath ?? undefined) ??
      join('generated', fragment.family, `${fragment.streamId}.bin`);
    return join(this.spoolDir, artifactId, 'materialized', relativePath);
  }

  private loadManifestFromSpool(
    artifactId: string
  ): TauriEdgeArtifactManifest | null {
    const manifestPath = this.spoolManifestPath(artifactId);
    if (!existsSync(manifestPath)) {
      return null;
    }
    const parsed = JSON.parse(readFileSync(manifestPath, 'utf8')) as unknown;
    return isExactManifest(parsed) ? parsed : null;
  }

  private async loadManifest(
    artifactId: string
  ): Promise<TauriEdgeArtifactManifest> {
    const cached = this.hydratedArtifacts.get(artifactId)?.manifest;
    if (cached ) {
      return cached;
    }
    const spooled = this.loadManifestFromSpool(artifactId);
    if (spooled ) {
      return spooled;
    }
    if (!this.db) {
      throw new Error(
        `Tauri-edge D1 index is not configured, so artifact ${artifactId} cannot be reconstructed.`
      );
    }

    const row = await this.db
      .prepare(
        `SELECT artifact_id, manifest_json, manifest_digest FROM ${this.tables.artifacts} WHERE artifact_id = ? LIMIT 1`
      )
      .bind(artifactId)
      .first<TauriEdgeArtifactRow>();
    this.d1ArtifactReads += 1;
    if (!row ) {
      throw new Error(`Unknown tauri-edge artifact '${artifactId}'.`);
    }

    const parsed = JSON.parse(row.manifest_json) as unknown;
    if (!isExactManifest(parsed)) {
      throw new Error(`Tauri-edge manifest row for ${artifactId} is invalid.`);
    }

    const { manifestDigest: _digest, ...withoutDigest } = parsed;
    const computed = computeTauriEdgeManifestDigest(withoutDigest);
    if (computed !== parsed.manifestDigest ||
      computed !== row.manifest_digest ) {
      throw new Error(`Tauri-edge manifest digest mismatch for ${artifactId}.`);
    }

    return parsed;
  }

  private async tryLoadManifest(
    artifactId: string
  ): Promise<TauriEdgeArtifactManifest | null> {
    try {
      return await this.loadManifest(artifactId);
    } catch {
      return null;
    }
  }

  private async loadFragmentRows(
    artifactId: string,
    families: readonly TauriEdgeFragmentFamily[]
  ): Promise<TauriEdgeFragmentRow[]> {
    if (!this.db) {
      throw new Error(
        `Tauri-edge D1 index is not configured, so fragments for ${artifactId} cannot be reconstructed.`
      );
    }

    const rows = await this.db
      .prepare(
        `SELECT artifact_id, stream_id, ordinal, family, encoding, byte_length, payload_byte_length, hash, payload_ref, source_path, content_type FROM ${this.tables.fragments} WHERE artifact_id = ? ORDER BY stream_id ASC, ordinal ASC`
      )
      .bind(artifactId)
      .all<TauriEdgeFragmentRow>();
    this.d1FragmentReads += 1;
    return (rows.results ?? []).filter((row) => families.includes(row.family));
  }

  private async loadSessionRow(
    sessionId: string
  ): Promise<TauriEdgeSessionRow | null> {
    if (!this.db) {
      return null;
    }

    return this.db
      .prepare(
        `SELECT session_id, artifact_id, snapshot_root, position_root, stream_id, ordinal, zk_proof, updated_at FROM ${this.tables.sessions} WHERE session_id = ? LIMIT 1`
      )
      .bind(sessionId)
      .first<TauriEdgeSessionRow>();
  }

  private async persistSession(row: TauriEdgeSessionRow): Promise<void> {
    if (!this.db) {
      return;
    }

    await this.db
      .prepare(
        `INSERT OR REPLACE INTO ${this.tables.sessions} (session_id, artifact_id, snapshot_root, position_root, stream_id, ordinal, zk_proof, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      )
      .bind(
        row.session_id,
        row.artifact_id,
        row.snapshot_root ?? null,
        row.position_root ?? null,
        row.stream_id ?? null,
        row.ordinal ?? null,
        row.zk_proof ?? null,
        row.updated_at
      )
      .run();
  }

  private resolveNodeId(manifest: TauriEdgeArtifactManifest): string {
    return this.nodeIdOverride ?? manifest.artifactId;
  }

  private resolveRuntimeId(manifest: TauriEdgeArtifactManifest): string {
    return this.runtimeIdOverride ?? manifest.artifactId;
  }
}
