/**
 * @a0n/auth - Resource Path Module
 *
 * Provides path-based resource matching for fine-grained access control.
 * Supports wildcards, sandboxing, and path hierarchy validation.
 *
 * @example
 * ```typescript
 * import { ResourcePath, matchResource, isSandbox } from '@a0n/auth';
 *
 * // Check if a capability grants access to a resource
 * const granted = matchResource('aeon:state:/users/*\/public', 'aeon:state:/users/123/public');
 * // => true
 *
 * // Check if a path is in a sandbox
 * const sandboxed = isSandbox('aeon:state:/sandbox/experiments/**');
 * // => true
 * ```
 */

/**
 * Resource URI pattern
 * Format: scheme:namespace:/path/to/resource
 */
export interface ResourceURI {
  /** URI scheme (e.g., 'aeon', 'file', 'storage') */
  scheme: string;
  /** Namespace within the scheme (e.g., 'state', 'sync', 'config') */
  namespace: string;
  /** Path segments (without leading slash) */
  path: string[];
  /** Original full URI */
  raw: string;
}

/**
 * Result of a resource match operation
 */
export interface ResourceMatchResult {
  /** Whether the pattern matches the resource */
  matches: boolean;
  /** Captured values from wildcards (in order) */
  captures: string[];
  /** The matched path segments */
  matchedPath: string[];
  /** Remaining path after match (for ** patterns) */
  remainder?: string[];
}

/**
 * Resource path configuration
 */
export interface ResourcePathConfig {
  /** Paths that are designated as sandboxes (unrestricted areas) */
  sandboxPaths?: string[];
  /** Paths that are read-only */
  readOnlyPaths?: string[];
  /** Paths that are completely restricted */
  restrictedPaths?: string[];
}

// =============================================================================
// PARSING
// =============================================================================

/**
 * Parse a resource URI into its components
 *
 * @example
 * parseResourceURI('aeon:state:/users/123/profile')
 * // => { scheme: 'aeon', namespace: 'state', path: ['users', '123', 'profile'], raw: '...' }
 */
export function parseResourceURI(uri: string): ResourceURI | null {
  // Handle wildcard '*' as a special case
  if (uri === '*') {
    return {
      scheme: '*',
      namespace: '*',
      path: ['**'],
      raw: uri,
    };
  }

  // Format: scheme:namespace:/path/segments
  const match = uri.match(/^([a-z0-9-]+):([a-z0-9-]+):\/(.*)$/i);
  if (!match) {
    return null;
  }

  const [, scheme, namespace, pathStr] = match;
  const path = pathStr.split('/').filter((segment) => segment.length > 0);

  return {
    scheme,
    namespace,
    path,
    raw: uri,
  };
}

/**
 * Construct a resource URI from components
 */
export function buildResourceURI(
  scheme: string,
  namespace: string,
  path: string[]
): string {
  return `${scheme}:${namespace}:/${path.join('/')}`;
}

// =============================================================================
// MATCHING
// =============================================================================

/**
 * Check if a pattern matches a resource path
 *
 * Supports:
 * - Exact match: `/users/123` matches `/users/123`
 * - Single wildcard: `/users/*` matches `/users/123`
 * - Recursive wildcard: `/sandbox/**` matches `/sandbox/any/path/here`
 * - Mixed: `/users/*\/settings/**` matches `/users/123/settings/notifications/email`
 *
 * @param pattern - The pattern to match against (can contain * and **)
 * @param resource - The resource path to check
 * @returns Match result with captures
 */
export function matchResource(
  pattern: string,
  resource: string
): ResourceMatchResult {
  const patternURI = parseResourceURI(pattern);
  const resourceURI = parseResourceURI(resource);

  // Invalid URIs don't match
  if (!patternURI || !resourceURI) {
    return { matches: false, captures: [], matchedPath: [] };
  }

  // Universal wildcard
  if (pattern === '*' || patternURI.scheme === '*') {
    return {
      matches: true,
      captures: [resource],
      matchedPath: resourceURI.path,
    };
  }

  // Scheme must match (unless pattern scheme is wildcard)
  if (patternURI.scheme !== '*' && patternURI.scheme !== resourceURI.scheme) {
    return { matches: false, captures: [], matchedPath: [] };
  }

  // Namespace must match (unless pattern namespace is wildcard)
  if (
    patternURI.namespace !== '*' &&
    patternURI.namespace !== resourceURI.namespace
  ) {
    return { matches: false, captures: [], matchedPath: [] };
  }

  // Match path segments
  return matchPathSegments(patternURI.path, resourceURI.path);
}

/**
 * Match path segments with wildcard support
 */
function matchPathSegments(
  pattern: string[],
  path: string[]
): ResourceMatchResult {
  const captures: string[] = [];
  const matchedPath: string[] = [];
  let patternIdx = 0;
  let pathIdx = 0;

  while (patternIdx < pattern.length) {
    const patternSegment = pattern[patternIdx];

    // Recursive wildcard - matches zero or more segments
    if (patternSegment === '**') {
      // If ** is the last pattern segment, it matches everything remaining
      if (patternIdx === pattern.length - 1) {
        const remainder = path.slice(pathIdx);
        captures.push(remainder.join('/'));
        matchedPath.push(...remainder);
        return { matches: true, captures, matchedPath, remainder };
      }

      // Find where the next pattern segment matches
      let foundMatch = false;

      for (let i = pathIdx; i <= path.length; i++) {
        const subPath = path.slice(i);
        const subResult = matchPathSegments(
          pattern.slice(patternIdx + 1),
          subPath
        );

        if (subResult.matches) {
          const captured = path.slice(pathIdx, i);
          captures.push(captured.join('/'));
          matchedPath.push(...captured, ...subResult.matchedPath);
          captures.push(...subResult.captures);
          foundMatch = true;
          break;
        }
      }

      return {
        matches: foundMatch,
        captures,
        matchedPath,
      };
    }

    // No more path segments to match
    if (pathIdx >= path.length) {
      return { matches: false, captures, matchedPath };
    }

    const pathSegment = path[pathIdx];

    // Single wildcard - matches exactly one segment
    if (patternSegment === '*') {
      captures.push(pathSegment);
      matchedPath.push(pathSegment);
      patternIdx++;
      pathIdx++;
      continue;
    }

    // Exact match required
    if (patternSegment !== pathSegment) {
      return { matches: false, captures, matchedPath };
    }

    matchedPath.push(pathSegment);
    patternIdx++;
    pathIdx++;
  }

  // Pattern exhausted - path should also be exhausted for exact match
  const matches = pathIdx === path.length;
  return { matches, captures, matchedPath };
}

/**
 * Check if a pattern grants access to a resource
 * Alias for matchResource(...).matches
 */
export function grantsAccess(pattern: string, resource: string): boolean {
  return matchResource(pattern, resource).matches;
}

// =============================================================================
// HIERARCHY
// =============================================================================

/**
 * Check if a path is a parent of another path
 *
 * @example
 * isParentPath('/users', '/users/123/profile') // => true
 * isParentPath('/users/123', '/users/456') // => false
 */
export function isParentPath(parent: string, child: string): boolean {
  const parentURI = parseResourceURI(parent);
  const childURI = parseResourceURI(child);

  if (!parentURI || !childURI) {
    return false;
  }

  if (
    parentURI.scheme !== childURI.scheme ||
    parentURI.namespace !== childURI.namespace
  ) {
    return false;
  }

  if (parentURI.path.length >= childURI.path.length) {
    return false;
  }

  for (let i = 0; i < parentURI.path.length; i++) {
    if (parentURI.path[i] !== childURI.path[i]) {
      return false;
    }
  }

  return true;
}

/**
 * Check if a path is a child of another path
 */
export function isChildPath(child: string, parent: string): boolean {
  return isParentPath(parent, child);
}

/**
 * Get all ancestor paths for a resource
 *
 * @example
 * getAncestorPaths('aeon:state:/users/123/profile/settings')
 * // => ['aeon:state:/', 'aeon:state:/users', 'aeon:state:/users/123', 'aeon:state:/users/123/profile']
 */
export function getAncestorPaths(resource: string): string[] {
  const uri = parseResourceURI(resource);
  if (!uri) {
    return [];
  }

  const ancestors: string[] = [];
  for (let i = 0; i < uri.path.length; i++) {
    ancestors.push(
      buildResourceURI(uri.scheme, uri.namespace, uri.path.slice(0, i))
    );
  }

  return ancestors;
}

// =============================================================================
// SANDBOXING
// =============================================================================

const DEFAULT_SANDBOX_PATTERNS = [
  '*:*:/sandbox/**',
  '*:*:/tmp/**',
  '*:*:/dev/**',
  '*:*:/test/**',
];

/**
 * Check if a resource path is within a sandbox
 *
 * Sandboxes are designated areas where operations are unrestricted.
 * Default sandboxes: /sandbox/**, /tmp/**, /dev/**, /test/**
 */
export function isSandbox(
  resource: string,
  customSandboxPatterns?: string[]
): boolean {
  const patterns = customSandboxPatterns || DEFAULT_SANDBOX_PATTERNS;

  for (const pattern of patterns) {
    if (matchResource(pattern, resource).matches) {
      return true;
    }
  }

  return false;
}

/**
 * Check if a resource operation should be allowed based on sandbox rules
 */
export function checkSandboxAccess(
  resource: string,
  operation: 'read' | 'write' | 'delete' | 'admin',
  config?: ResourcePathConfig
): { allowed: boolean; reason?: string } {
  // Check if in sandbox - always allowed
  if (isSandbox(resource, config?.sandboxPaths)) {
    return { allowed: true };
  }

  // Check if restricted
  if (config?.restrictedPaths) {
    for (const pattern of config.restrictedPaths) {
      if (matchResource(pattern, resource).matches) {
        return { allowed: false, reason: 'Resource is in restricted area' };
      }
    }
  }

  // Check if read-only
  if (config?.readOnlyPaths && operation !== 'read') {
    for (const pattern of config.readOnlyPaths) {
      if (matchResource(pattern, resource).matches) {
        return { allowed: false, reason: 'Resource is read-only' };
      }
    }
  }

  return { allowed: true };
}

// =============================================================================
// ATTENUATION
// =============================================================================

/**
 * Attenuate a resource pattern to a more specific sub-path
 *
 * Used when delegating capabilities to restrict scope.
 *
 * @example
 * attenuateResource('aeon:state:/users/**', '/users/123/**')
 * // => 'aeon:state:/users/123/**'
 *
 * @param parentPattern - The pattern being attenuated
 * @param subPath - The sub-path to restrict to
 * @returns The attenuated pattern, or null if invalid
 */
export function attenuateResource(
  parentPattern: string,
  subPath: string
): string | null {
  const parentURI = parseResourceURI(parentPattern);

  if (!parentURI) {
    return null;
  }

  // Universal wildcard can be attenuated to anything
  if (parentPattern === '*') {
    return subPath;
  }

  // Parse the sub-path
  const subPathSegments = subPath.split('/').filter((s) => s.length > 0);

  // Build the attenuated path
  const attenuatedPath: string[] = [];
  let parentIdx = 0;

  for (const segment of subPathSegments) {
    // If we've exhausted parent path segments
    if (parentIdx >= parentURI.path.length) {
      // If parent ends with **, we can add more segments
      if (parentURI.path[parentURI.path.length - 1] === '**') {
        attenuatedPath.push(segment);
        continue;
      }
      // Otherwise, can't attenuate further
      return null;
    }

    const parentSegment = parentURI.path[parentIdx];

    if (parentSegment === '**') {
      // ** matches anything, so accept this segment
      attenuatedPath.push(segment);
      // Don't advance parentIdx - ** is greedy
    } else if (parentSegment === '*') {
      // * matches single segment
      attenuatedPath.push(segment);
      parentIdx++;
    } else if (parentSegment === segment) {
      // Exact match
      attenuatedPath.push(segment);
      parentIdx++;
    } else {
      // Mismatch
      return null;
    }
  }

  return buildResourceURI(
    parentURI.scheme,
    parentURI.namespace,
    attenuatedPath
  );
}

/**
 * Check if one capability can be attenuated to another
 *
 * @example
 * canAttenuate(
 *   { can: 'state/write', with: 'aeon:state:/users/**' },
 *   { can: 'state/read', with: 'aeon:state:/users/123/**' }
 * )
 * // => true (more specific path, less privileged action)
 */
export function canAttenuate(
  parent: { can: string; with: string },
  child: { can: string; with: string }
): boolean {
  // Check action attenuation
  if (!canAttenuateAction(parent.can, child.can)) {
    return false;
  }

  // Check resource attenuation
  return (
    matchResource(parent.with, child.with).matches ||
    attenuateResource(parent.with, child.with) !== null
  );
}

/**
 * Check if an action can be attenuated to another action
 *
 * Action hierarchy (most to least privileged):
 * - admin > write > read
 * - *\/write includes *\/read
 */
function canAttenuateAction(parent: string, child: string): boolean {
  // Same action is always valid
  if (parent === child) {
    return true;
  }

  // Wildcard parent grants everything
  if (parent === '*' || parent.endsWith('/*')) {
    return true;
  }

  // Check common patterns
  const [parentNamespace, parentAction] = parent.split('/');
  const [childNamespace, childAction] = child.split('/');

  // Namespace must match
  if (parentNamespace !== childNamespace && parentNamespace !== '*') {
    return false;
  }

  // Admin can attenuate to anything
  if (parentAction === 'admin') {
    return true;
  }

  // Write can attenuate to read
  if (parentAction === 'write' && childAction === 'read') {
    return true;
  }

  return false;
}

// =============================================================================
// UTILITY
// =============================================================================

/**
 * Normalize a resource path (remove empty segments, normalize slashes)
 */
export function normalizePath(path: string): string {
  const uri = parseResourceURI(path);
  if (!uri) {
    return path;
  }

  return buildResourceURI(uri.scheme, uri.namespace, uri.path);
}

/**
 * Extract the base path (without wildcards)
 */
export function getBasePath(pattern: string): string {
  const uri = parseResourceURI(pattern);
  if (!uri) {
    return pattern;
  }

  const basePath = uri.path.filter(
    (segment) => segment !== '*' && segment !== '**'
  );

  return buildResourceURI(uri.scheme, uri.namespace, basePath);
}

/**
 * Check if a pattern contains wildcards
 */
export function hasWildcards(pattern: string): boolean {
  return pattern.includes('*');
}

/**
 * Get the depth of a resource path
 */
export function getPathDepth(resource: string): number {
  const uri = parseResourceURI(resource);
  return uri ? uri.path.length : 0;
}
