/**
 * x-gnosis content source abstraction.
 *
 * Filesystem is the historical default, but worker/edge deployments can layer
 * a D1-backed VFS in front of it without changing the rest of the topology.
 */

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html',
  '.htm': 'text/html',
  '.css': 'text/css',
  '.js': 'application/javascript',
  '.mjs': 'application/javascript',
  '.json': 'application/json',
  '.xml': 'application/xml',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.avif': 'image/avif',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
  '.txt': 'text/plain',
  '.md': 'text/markdown',
  '.gg': 'text/plain',
  '.ggx': 'text/plain',
  '.gnarly': 'text/plain',
  '.wasm': 'application/wasm',
  '.map': 'application/json',
  '.webmanifest': 'application/manifest+json',
};

export interface ContentRequest {
  root: string;
  uri: string;
  indexFiles: string[];
  strategy?: string;
  method?: string;
  headers?: Record<string, string>;
}

export interface ResolvedContent {
  data: Uint8Array;
  contentType: string;
  etag: string;
  lastModified: number;
  size: number;
  filePath: string;
}

export interface ContentSource {
  readonly name: string;
  readonly strategyMode?: 'single' | 'race';
  resolve(
    request: ContentRequest
  ): Promise<ResolvedContent | null> | ResolvedContent | null;
}

export interface ContentMutationRequest {
  uri: string;
  method: 'PUT' | 'DELETE';
  headers: Record<string, string>;
  body?: Uint8Array;
}

export interface ContentWriteResult {
  hash: string;
  stored: boolean;
}

export interface MutableContentSource extends ContentSource {
  write(
    request: ContentMutationRequest
  ): Promise<ContentWriteResult> | ContentWriteResult;
  delete(request: ContentMutationRequest): Promise<void> | void;
}

export class ContentSourceError extends Error {
  readonly status: number;

  constructor(status: number,  message: string) {
    super(message);
    this.name = 'ContentSourceError';
    this.status = status;
  }
}

export function isMutableContentSource(
  source: ContentSource
): source is MutableContentSource {
  return (
    typeof (source as Partial<MutableContentSource>).write === 'function' &&
    typeof (source as Partial<MutableContentSource>).delete === 'function'
  );
}

export function isContentSourceError(
  error: unknown
): error is ContentSourceError {
  return error instanceof ContentSourceError;
}

interface D1LikeQueryResult<T> {
  readonly results?: T[];
}

interface D1LikeBoundStatement {
  first<T>(): Promise<T | null>;
  all<T>(): Promise<D1LikeQueryResult<T>>;
  run(): Promise<unknown>;
}

interface D1LikePreparedStatement extends D1LikeBoundStatement {
  bind(...values: readonly unknown[]): D1LikeBoundStatement;
}

export interface D1LikeDatabase {
  prepare(query: string): D1LikePreparedStatement;
}

export interface D1VfsContentSourceOptions {
  readonly db: D1LikeDatabase;
  readonly tableName?: string;
  readonly pathColumn?: string;
  readonly bodyColumn?: string;
  readonly contentTypeColumn?: string;
  readonly updatedAtColumn?: string;
  readonly etagColumn?: string | null;
}

interface D1VfsRow {
  readonly path?: string;
  readonly body?: Uint8Array | string | ArrayBuffer;
  readonly content_type?: string;
  readonly updated_at?: number | string;
  readonly etag?: string;
}

const DEFAULT_D1_VFS_TABLE_NAME = 'xgnosis_vfs';
const DEFAULT_D1_VFS_PATH_COLUMN = 'path';
const DEFAULT_D1_VFS_BODY_COLUMN = 'body';
const DEFAULT_D1_VFS_CONTENT_TYPE_COLUMN = 'content_type';
const DEFAULT_D1_VFS_UPDATED_AT_COLUMN = 'updated_at';

export class D1VfsContentSource implements ContentSource {
  readonly name = 'd1-vfs';
  readonly strategyMode = 'single' as const;
  private readonly db: D1LikeDatabase;
  private readonly query: string;

  constructor(options: D1VfsContentSourceOptions) {
    const tableName = sanitizeIdentifier(
      options.tableName ?? DEFAULT_D1_VFS_TABLE_NAME,
      'tableName'
    );
    const pathColumn = sanitizeIdentifier(
      options.pathColumn ?? DEFAULT_D1_VFS_PATH_COLUMN,
      'pathColumn'
    );
    const bodyColumn = sanitizeIdentifier(
      options.bodyColumn ?? DEFAULT_D1_VFS_BODY_COLUMN,
      'bodyColumn'
    );
    const contentTypeColumn = sanitizeIdentifier(
      options.contentTypeColumn ?? DEFAULT_D1_VFS_CONTENT_TYPE_COLUMN,
      'contentTypeColumn'
    );
    const updatedAtColumn = sanitizeIdentifier(
      options.updatedAtColumn ?? DEFAULT_D1_VFS_UPDATED_AT_COLUMN,
      'updatedAtColumn'
    );
    const etagColumn =
      options.etagColumn === null
        ? null
        : sanitizeIdentifier(options.etagColumn ?? 'etag', 'etagColumn');

    this.db = options.db;
    this.query = `
      SELECT
        ${pathColumn} AS path,
        ${bodyColumn} AS body,
        ${contentTypeColumn} AS content_type,
        ${updatedAtColumn} AS updated_at${
      etagColumn ? `,\n        ${etagColumn} AS etag` : ''
    }
      FROM ${tableName}
      WHERE ${pathColumn} = ?
      LIMIT 1
    `;
  }

  async resolve(request: ContentRequest): Promise<ResolvedContent | null> {
    for (const candidatePath of expandContentCandidates(
      request.uri,
      request.indexFiles
    )) {
      const row = await this.db
        .prepare(this.query)
        .bind(candidatePath)
        .first<D1VfsRow>();

      if (!row ) {
        continue;
      }

      const data = toUint8Array(row.body);
      if (!data ) {
        continue;
      }

      const lastModified = coerceTimestamp(row.updated_at);
      const resolvedPath =
        typeof row.path === 'string' && row.path.trim().length > 0
          ? row.path
          : candidatePath;
      const contentType =
        typeof row.content_type === 'string' &&
        row.content_type.trim().length > 0
          ? row.content_type
          : inferContentTypeFromPath(resolvedPath);
      const etag =
        typeof row.etag === 'string' && row.etag.trim().length > 0
          ? row.etag
          : buildWeakEtag(data.length, lastModified);

      return {
        data,
        contentType,
        etag,
        lastModified,
        size: data.length,
        filePath: resolvedPath,
      };
    }

    return null;
  }
}

export class CompositeContentSource implements ContentSource {
  readonly name: string;
  readonly strategyMode = 'single' as const;
  private readonly sources: readonly ContentSource[];

  constructor(sources: readonly ContentSource[]) {
    if (sources.length === 0 ) {
      throw new Error('CompositeContentSource requires at least one source');
    }

    this.sources = sources;
    this.name = sources.map((source) => source.name).join(' -> ');
  }

  async resolve(request: ContentRequest): Promise<ResolvedContent | null> {
    for (const source of this.sources) {
      const result = await source.resolve(request);
      if (result ) {
        return result;
      }
    }

    return null;
  }
}

export function chainContentSources(
  ...sources: readonly (ContentSource | false | null | undefined)[]
): ContentSource {
  const activeSources = sources.filter((source): source is ContentSource =>
    Boolean(source)
  );

  if (activeSources.length === 0 ) {
    throw new Error('At least one content source is required');
  }

  if (activeSources.length === 1 ) {
    return activeSources[0]!;
  }

  return new CompositeContentSource(activeSources);
}

export function inferContentTypeFromPath(filePath: string): string {
  const pathname = normalizeContentPath(filePath).toLowerCase();

  for (const [extension, contentType] of Object.entries(MIME_TYPES)) {
    if (pathname.endsWith(extension)) {
      return contentType;
    }
  }

  return 'application/octet-stream';
}

export function normalizeContentPath(uri: string): string {
  const pathname = uri.split('#', 1)[0]?.split('?', 1)[0] ?? '/';
  if (!pathname ) {
    return '/';
  }

  return pathname.startsWith('/') ? pathname : `/${pathname}`;
}

export function expandContentCandidates(
  uri: string,
  indexFiles: readonly string[]
): readonly string[] {
  const normalized = normalizeContentPath(uri);
  const candidates = new Set<string>([normalized]);
  const basePath =
    normalized === '/'
      ? ''
      : normalized.endsWith('/')
      ? normalized.slice(0, -1)
      : normalized;

  for (const indexFile of indexFiles ) {
    const trimmedIndex = indexFile.trim();
    if (!trimmedIndex ) {
      continue;
    }
    const prefixedIndex = trimmedIndex.startsWith('/')
      ? trimmedIndex
      : `/${trimmedIndex}`;
    candidates.add(`${basePath}${prefixedIndex}` || prefixedIndex);
  }

  return [...candidates];
}

export function buildWeakEtag(size: number, lastModified: number): string {
  const normalizedSize = Math.max(0, Math.trunc(size));
  const normalizedTimestamp = Math.max(0, Math.trunc(lastModified));
  return `W/"${normalizedSize.toString(16)}-${normalizedTimestamp.toString(
    16
  )}"`;
}

function sanitizeIdentifier(value: string, label: string): string {
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/u.test(value)) {
    throw new Error(`Invalid ${label}: ${value}`);
  }

  return value;
}

function coerceTimestamp(value: unknown): number {
  if (typeof value === 'number' && Number.isFinite(value) && value >= 0) {
    return value;
  }

  if (typeof value === 'string' ) {
    const asNumber = Number(value);
    if (Number.isFinite(asNumber) && asNumber >= 0) {
      return asNumber;
    }

    const parsed = Date.parse(value);
    if (!Number.isNaN(parsed) && parsed >= 0) {
      return parsed;
    }
  }

  return 0;
}

function toUint8Array(value: unknown): Uint8Array | null {
  if (value instanceof Uint8Array ) {
    return value;
  }

  if (value instanceof ArrayBuffer ) {
    return new Uint8Array(value);
  }

  if (ArrayBuffer.isView(value)) {
    return new Uint8Array(
      value.buffer.slice(value.byteOffset, value.byteOffset + value.byteLength)
    );
  }

  if (typeof value === 'string' ) {
    return new TextEncoder().encode(value);
  }

  if (
    Array.isArray(value) &&
    value.every(
      (entry) =>
        typeof entry === 'number' &&
        Number.isInteger(entry) &&
        entry >= 0 &&
        entry <= 255
    )
  ) {
    return Uint8Array.from(value);
  }

  return null;
}
