import { randomUUID } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { cacheFingerprint48HexSync } from '@a0n/bitwise/cache-fp48';
import { resolveXRangerConfig } from './config.js';
import type { XRangerConfigResolveOptions } from './config.js';
import type {
  XRangerDeploymentBindingSummary,
  XRangerDeploymentManifest,
} from './types.js';

export interface XRangerDeploymentOptions extends XRangerConfigResolveOptions {}

function fp48Hex(value: string): string {
  return cacheFingerprint48HexSync(value);
}

function bindingSummary(
  type: XRangerDeploymentBindingSummary['type'],
  binding: string,
  target: string | undefined
): XRangerDeploymentBindingSummary {
  return target ? { type, binding, target } : { type, binding };
}

export async function createLocalDeploymentManifest(
  options: XRangerDeploymentOptions = {}
): Promise<{
  readonly manifestPath: string;
  readonly manifest: XRangerDeploymentManifest;
}> {
  const config = resolveXRangerConfig(options);
  const scriptContent = readFileSync(config.main, 'utf8');
  const configContent = readFileSync(config.configPath, 'utf8');
  const deploymentId = randomUUID();
  const manifest: XRangerDeploymentManifest = {
    version: 1,
    deploymentId,
    createdAt: new Date().toISOString(),
    workerName: config.name,
    environment: options.env,
    scriptPath: config.main,
    configPath: config.configPath,
    compatibilityDate: config.compatibilityDate,
    entryDigest: fp48Hex(scriptContent),
    configDigest: fp48Hex(configContent),
    bindings: config.bindings.map((binding) =>
      bindingSummary(
        binding.type,
        binding.binding,
        binding.service ??
          binding.bucketName ??
          binding.databaseName ??
          binding.className ??
          binding.certificateId
      )
    ),
    runtime: {
      host: 'gnosis-uring',
      compatibility: 'wrangler-compatible-local',
      runtimeTarget: 'workers',
      backupTargets: ['fastly-compute@wasi'],
    },
    forge: {
      workloadKind: 'lambda',
      engine: 'aeon-forge',
      transport: 'x-ranger',
    },
  };

  const manifestDir = resolve(
    config.projectRoot,
    '.x-ranger',
    'deployments',
    config.name
  );
  mkdirSync(manifestDir, { recursive: true });
  const manifestPath = resolve(manifestDir, `${deploymentId}.json`);
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`, 'utf8');

  return { manifestPath, manifest };
}

export function deploymentDirectoryForConfig(configPath: string): string {
  return resolve(dirname(configPath), '.x-ranger', 'deployments');
}
